/* ============ ICONS (multi-color, flat, theme-independent) ============ */
function icon(name, cls){
  cls = cls || 'icon';
  const M = {
    dashboard:'<rect x="3" y="3" width="7" height="9" rx="1.5" fill="#3b82f6"/><rect x="14" y="3" width="7" height="5" rx="1.5" fill="#f59e0b"/><rect x="14" y="12" width="7" height="9" rx="1.5" fill="#10b981"/><rect x="3" y="16" width="7" height="5" rx="1.5" fill="#a855f7"/>',
    quiz:'<circle cx="12" cy="12" r="9.5" fill="#8b5cf6"/><path d="M9.3 9.2a2.8 2.8 0 0 1 5.4.4c0 1.9-2.7 2.1-2.7 3.9" stroke="#fff" stroke-width="1.8" fill="none" stroke-linecap="round"/><circle cx="12" cy="17.2" r="1.1" fill="#fbbf24"/>',
    cards:'<path d="M7.5 6.2l10.2-2.8 3.8 11.3-4 1.1z" fill="#fb923c"/><rect x="3" y="7" width="14" height="10" rx="2" fill="#0ea5e9"/><rect x="6" y="10" width="8" height="1.6" rx="0.8" fill="#fff" opacity="0.85"/>',
    wrench:'<path d="M3 20h18" stroke="#94a3b8" stroke-width="2" stroke-linecap="round"/><path d="M14.7 3.3a4.3 4.3 0 0 0-5.7 5l-6.3 6.3 2.7 2.7 6.3-6.3a4.3 4.3 0 0 0 5-5.7l-2.6 2.6-2.1-2.1z" fill="#ef4444"/>',
    pbq:'<path d="M3 20h18" stroke="#94a3b8" stroke-width="2" stroke-linecap="round"/><rect x="5.5" y="12" width="3.4" height="7" rx="0.8" fill="#ef4444"/><rect x="10.3" y="7" width="3.4" height="12" rx="0.8" fill="#f59e0b"/><rect x="15.1" y="10" width="3.4" height="9" rx="0.8" fill="#10b981"/>',
    acronym:'<rect x="3" y="4.5" width="18" height="4" rx="1.5" fill="#3b82f6"/><rect x="3" y="10" width="12" height="4" rx="1.5" fill="#f59e0b"/><rect x="3" y="15.5" width="15" height="4" rx="1.5" fill="#10b981"/>',
    tips:'<path d="M12 2.5a6.2 6.2 0 0 0-3.8 11.1c.6.5.9 1.1.9 1.8v0.4h5.8v-.4c0-.7.3-1.3.9-1.8A6.2 6.2 0 0 0 12 2.5z" fill="#fbbf24"/><rect x="9" y="17.5" width="6" height="1.8" rx="0.6" fill="#94a3b8"/><rect x="9.6" y="20" width="4.8" height="1.6" rx="0.6" fill="#64748b"/>',
    settings:'<circle cx="12" cy="12" r="9.4" fill="#64748b"/><circle cx="12" cy="12" r="3.6" fill="#fff"/><circle cx="12" cy="12" r="2.1" fill="#3b82f6"/>',
    server:'<rect x="4" y="3.5" width="16" height="7" rx="1.6" fill="#334155"/><rect x="4" y="13.5" width="16" height="7" rx="1.6" fill="#475569"/><circle cx="7.2" cy="7" r="1" fill="#22c55e"/><circle cx="7.2" cy="17" r="1" fill="#22c55e"/><rect x="10.5" y="6.3" width="6" height="1.4" rx="0.6" fill="#94a3b8"/><rect x="10.5" y="16.3" width="6" height="1.4" rx="0.6" fill="#94a3b8"/>',
    admin:'<rect x="3" y="4" width="18" height="17" rx="2.2" fill="#7c3aed"/><rect x="8" y="2" width="8" height="4" rx="1.4" fill="#fbbf24"/><rect x="6" y="10" width="12" height="1.8" rx="0.9" fill="#fff"/><rect x="6" y="14" width="9" height="1.8" rx="0.9" fill="#fff" opacity="0.75"/>',
    lock:'<rect x="4.5" y="10.5" width="15" height="10" rx="2.2" fill="#dc2626"/><path d="M7.5 10.5V7.8a4.5 4.5 0 0 1 9 0v2.7" stroke="#3b82f6" stroke-width="2.2" fill="none" stroke-linecap="round"/><circle cx="12" cy="15.3" r="1.6" fill="#fbbf24"/>',
    ops:'<rect x="1.5" y="15" width="21" height="6" rx="2" fill="#e2e8f0"/><path d="M2 12h4l2-7 4 14 2-7h7" stroke="#ef4444" stroke-width="2.1" fill="none" stroke-linecap="round" stroke-linejoin="round"/>',
    check:'<circle cx="12" cy="12" r="9.5" fill="#16a34a"/><path d="M7 12.3l3.4 3.4 6.6-6.9" stroke="#fff" stroke-width="2.2" fill="none" stroke-linecap="round" stroke-linejoin="round"/>',
    x:'<circle cx="12" cy="12" r="9.5" fill="#dc2626"/><path d="M8.2 8.2l7.6 7.6M15.8 8.2l-7.6 7.6" stroke="#fff" stroke-width="2.2" stroke-linecap="round"/>',
    flag:'<rect x="5" y="2.5" width="2" height="19" rx="1" fill="#64748b"/><path d="M7 4h11l-2.6 3.6L18 11.2H7z" fill="#ef4444"/>',
    book:'<path d="M4 5a2 2 0 0 1 2-2h6v18H6a2 2 0 0 0-2 2z" fill="#3b82f6"/><path d="M20 5a2 2 0 0 0-2-2h-6v18h6a2 2 0 0 1 2 2z" fill="#f59e0b"/>',
    external:'<rect x="4" y="4" width="13" height="16" rx="2" fill="#e2e8f0"/><path d="M12 4h8v8" stroke="#3b82f6" stroke-width="2.1" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d="M20 4L10.5 13.5" stroke="#f59e0b" stroke-width="2.1" stroke-linecap="round"/>',
    refresh:'<path d="M20 11A8 8 0 0 0 6 6.3L3 9" stroke="#3b82f6" stroke-width="2.2" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d="M4 13a8 8 0 0 0 14 4.7L21 15" stroke="#10b981" stroke-width="2.2" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d="M3 4v5h5M21 20v-5h-5" stroke="#64748b" stroke-width="2.2" fill="none" stroke-linecap="round" stroke-linejoin="round"/>',
    disk:'<circle cx="12" cy="12" r="9.5" fill="#0ea5e9"/><circle cx="12" cy="12" r="3.2" fill="#e0f2fe"/><circle cx="12" cy="12" r="1.2" fill="#0ea5e9"/>',
    shield:'<path d="M12 2.5l7.5 3v6c0 5-3.2 8.6-7.5 9.5-4.3-.9-7.5-4.5-7.5-9.5v-6z" fill="#2563eb"/><path d="M8.4 12.2l2.4 2.4 4.8-4.9" stroke="#fff" stroke-width="1.9" fill="none" stroke-linecap="round" stroke-linejoin="round"/>'
  };
  return '<svg class="'+cls+'" viewBox="0 0 24 24">'+(M[name]||M.server)+'</svg>';
}
const NAV_LABELS = {dashboard:['dashboard','Dashboard'],quiz:['quiz','Practice Quiz'],flashcards:['cards','Flashcards'],pbq:['pbq','Performance-Based Qs'],troubleshooting:['wrench','Troubleshooting'],acronyms:['acronym','Acronyms'],studytips:['tips','Study Tips'],settings:['settings','Settings']};
document.querySelectorAll('.nav-link[data-route]').forEach(a=>{
  const r=a.getAttribute('data-route'), pair=NAV_LABELS[r], ic=pair[0], label=pair[1];
  a.innerHTML = icon(ic)+'<span>'+label+'</span>';
});

/* ============ DOMAIN / OBJECTIVE DATA (CV0-004, Exam Objectives 2.0) ============ */
/* ============ DOMAIN / OBJECTIVE DATA (CV0-004, Exam Objectives 2.0) ============ */
const DOMAINS = [{"id": "1.0", "title": "Cloud Architecture", "weight": 23, "icon": "server", "objectives": [{"id": "1.1", "title": "Given a scenario, use the appropriate cloud service model"}, {"id": "1.2", "title": "Explain concepts related to service availability"}, {"id": "1.3", "title": "Explain cloud networking concepts"}, {"id": "1.4", "title": "Compare and contrast storage resources and technologies"}, {"id": "1.5", "title": "Explain the purpose of cloud-native design concepts"}, {"id": "1.6", "title": "Compare and contrast containerization concepts"}, {"id": "1.7", "title": "Compare and contrast virtualization concepts"}, {"id": "1.8", "title": "Summarize cost considerations related to cloud usage"}, {"id": "1.9", "title": "Explain the importance of database concepts"}, {"id": "1.10", "title": "Compare and contrast methods for optimizing workloads using cloud resources"}, {"id": "1.11", "title": "Identify evolving technologies in the cloud"}]}, {"id": "2.0", "title": "Deployment", "weight": 19, "icon": "admin", "objectives": [{"id": "2.1", "title": "Compare and contrast cloud deployment models"}, {"id": "2.2", "title": "Given a scenario, implement appropriate deployment strategies"}, {"id": "2.3", "title": "Summarize aspects of cloud migration"}, {"id": "2.4", "title": "Given a scenario, use code to deploy and configure cloud resources"}, {"id": "2.5", "title": "Given a set of requirements, provision the appropriate cloud resources"}]}, {"id": "3.0", "title": "Operations", "weight": 17, "icon": "ops", "objectives": [{"id": "3.1", "title": "Given a scenario, configure appropriate resources to achieve observability"}, {"id": "3.2", "title": "Given a scenario, configure appropriate scaling approaches"}, {"id": "3.3", "title": "Given a scenario, use appropriate backup and recovery methods"}, {"id": "3.4", "title": "Given a scenario, manage the life cycle of cloud resources"}]}, {"id": "4.0", "title": "Security", "weight": 19, "icon": "lock", "objectives": [{"id": "4.1", "title": "Explain vulnerability management concepts"}, {"id": "4.2", "title": "Compare and contrast aspects of compliance and regulation"}, {"id": "4.3", "title": "Given a scenario, implement identity and access management"}, {"id": "4.4", "title": "Given a scenario, apply security best practices"}, {"id": "4.5", "title": "Given a scenario, apply security controls in the cloud"}, {"id": "4.6", "title": "Given a scenario, monitor suspicious activities to identify common attacks"}]}, {"id": "5.0", "title": "DevOps Fundamentals", "weight": 10, "icon": "wrench", "objectives": [{"id": "5.1", "title": "Explain source control concepts"}, {"id": "5.2", "title": "Explain concepts related to continuous integration/continuous deployment (CI/CD) pipelines"}, {"id": "5.3", "title": "Explain concepts related to integration of systems"}, {"id": "5.4", "title": "Explain the importance of tools used in DevOps environments"}]}, {"id": "6.0", "title": "Troubleshooting", "weight": 12, "icon": "flag", "objectives": [{"id": "6.1", "title": "Given a scenario, troubleshoot deployment issues"}, {"id": "6.2", "title": "Given a scenario, troubleshoot network issues"}, {"id": "6.3", "title": "Given a scenario, troubleshoot security issues"}]}];
const OBJ_INDEX = {}; DOMAINS.forEach(d=>d.objectives.forEach(o=>{o.domain=d.id; OBJ_INDEX[o.id]=o;}));

/* ============ QUESTION BANK (2,196 questions covering every CV0-004 objective) ============ */
const QBANK = [{"obj": "6.2", "q": "Which of the following best describes \"DHCP (Troubleshooting)\"?", "c": ["An incorrect entry in a route table sending traffic to the wrong destination.", "Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500).", "Dynamic Host Configuration Protocol — automatically assigns IP addressing information to hosts.", "The distinction between a switch port carrying a single VLAN (access) versus multiple VLANs (trunk)."], "a": 2, "e": "Dynamic Host Configuration Protocol — automatically assigns IP addressing information to hosts. A failed DHCP service can leave hosts without any usable network configuration."}, {"obj": "3.3", "q": "A description reads: \"Restoring data directly onto the original system/location.\" Which term does this describe?", "c": ["In-Place Recovery", "Differential Backup", "Backup Schedule", "Backup Replication"], "a": 0, "e": "\"Restoring data directly onto the original system/location.\" describes In-Place Recovery. The simplest recovery approach when the original infrastructure is still available and intact."}, {"obj": "4.4", "q": "Which term best matches this description: \"Controls governing which files and directories a container process can read or write.\"?", "c": ["Patching (Security)", "Container File Access Permissions", "Privileged Container", "Unprivileged Container"], "a": 1, "e": "\"Controls governing which files and directories a container process can read or write.\" describes Container File Access Permissions. Misconfigured permissions inside a container can let an attacker access or modify data they shouldn't."}, {"obj": "4.1", "q": "Why does this matter on the exam and in practice? \"The step that actually reduces risk — identification without remediation provides no real protection.\" — which term does this explain?", "c": ["Scanning Scope", "Remediation", "Vulnerability Assessment", "Vulnerability Identification"], "a": 1, "e": "The step that actually reduces risk — identification without remediation provides no real protection. This describes Remediation (\"Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability.\")."}, {"obj": "2.3", "q": "How would you most accurately define \"Replatform\"?", "c": ["A migration strategy that moves an application to the cloud with minimal changes, also called lift and shift.", "A migration strategy that decommissions an application no longer needed.", "A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture.", "A migration strategy that rewrites portions of an application to better fit cloud-native patterns."], "a": 2, "e": "A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture. A middle ground between a straight lift-and-shift and a full application redesign."}, {"obj": "4.5", "q": "Which of the following best describes the difference between a network ACL and a network security group in most cloud platforms?", "c": ["They are identical with no functional difference", "Network ACLs typically operate at the subnet level and are often stateless, while security groups operate at the instance level and are often stateful", "Security groups only apply to on-premises networks", "Network ACLs can only allow traffic, never deny it"], "a": 1, "e": "Network ACLs commonly apply at the subnet level and may be stateless (requiring explicit rules for return traffic), while security groups apply per-instance and are typically stateful."}, {"obj": "4.4", "q": "Which of the following best describes \"Privileged Container\"?", "c": ["A container granted elevated access to the host system's resources.", "A container running with restricted access, isolated from the host's sensitive resources.", "Hardening guidance published by a specific cloud provider or software vendor for their own product.", "Access controls and encryption settings applied to object storage buckets/containers."], "a": 0, "e": "A container granted elevated access to the host system's resources. Significantly increases risk since a compromised privileged container can affect the underlying host."}, {"obj": "1.5", "q": "A colleague says: \"Essential in dynamic cloud-native environments where service instances and IP addresses change constantly.\" Which concept are they describing?", "c": ["Cloud-Provided Managed Service", "Loosely Coupled Architecture", "Service Discovery", "Fan-Out"], "a": 2, "e": "Essential in dynamic cloud-native environments where service instances and IP addresses change constantly. This describes Service Discovery (\"A mechanism that lets services dynamically find the network location of other services.\")."}, {"obj": "1.3", "q": "In Cloud+ terminology, \"LAN\" is an abbreviation for which of the following?", "c": ["Customer Relationship Management", "Cloud Security Alliance", "Recovery Point Objective", "Local Area Network"], "a": 3, "e": "LAN stands for Local Area Network. A network confined to a relatively small physical area."}, {"obj": "1.11", "q": "A factory has hundreds of IoT sensors that would each individually need a cloud connection, which would be inefficient and costly. What component aggregates their data before sending it to the cloud?", "c": ["An IoT sensor", "An IoT gateway", "A CDN", "A hypervisor"], "a": 1, "e": "An IoT gateway aggregates and relays data from multiple sensors, reducing the number of direct cloud connections needed and enabling local pre-processing."}, {"obj": "6.1", "q": "A company's application becomes completely unreachable for all users following a botched deployment. What severity level does this represent?", "c": ["A partial outage", "A full outage", "API throttling", "A sizing issue"], "a": 1, "e": "A full outage represents a complete loss of service availability, the most severe availability impact, prioritized above a partial outage."}, {"obj": "3.4", "q": "In cloud computing terminology, \"Decommissioning — End of Life\" refers to which of the following?", "c": ["Temporary data that does not need to persist beyond a session or process.", "A significant version update that may include new features and breaking changes.", "A software update addressing a specific bug or vulnerability.", "Retiring a resource because it has reached the end of its useful life or support."], "a": 3, "e": "Retiring a resource because it has reached the end of its useful life or support. Requires planning for data migration/retention before the resource is removed."}, {"obj": "4.1", "q": "Why does this matter on the exam and in practice? \"Helps prioritize which vulnerabilities to remediate first based on actual risk.\" — which term does this explain?", "c": ["Remediation", "Scanning Scope", "CVE", "Vulnerability Assessment"], "a": 3, "e": "Helps prioritize which vulnerabilities to remediate first based on actual risk. This describes Vulnerability Assessment (\"Evaluating identified vulnerabilities for severity, exploitability, and business impact.\")."}, {"obj": "1.11", "q": "How would you most accurately define \"Generative AI\"?", "c": ["AI models that create new content (text, images, code) based on learned patterns.", "A device that collects data from the physical environment (temperature, motion, etc.).", "The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data.", "AI technology that automatically converts text from one language to another."], "a": 0, "e": "AI models that create new content (text, images, code) based on learned patterns. A rapidly growing category of cloud AI services used for content creation and code assistance."}, {"obj": "5.4", "q": "A team wants to automatically deploy, scale, and self-heal dozens of containerized microservices across a cluster of nodes. Which tool is purpose-built for this orchestration?", "c": ["Docker alone", "Kubernetes", "Git", "Grafana"], "a": 1, "e": "Kubernetes is the de facto standard for container orchestration, automating deployment, scaling, and self-healing of containerized applications across a cluster."}, {"obj": "1.2", "q": "Why does this matter on the exam and in practice? \"Provides the data needed to detect outages and calculate real-world uptime against SLA targets.\" — which term does this explain?", "c": ["Warm Site", "Availability Monitoring", "Availability Zone", "RPO"], "a": 1, "e": "Provides the data needed to detect outages and calculate real-world uptime against SLA targets. This describes Availability Monitoring (\"Continuously checking that a resource or service is up and responding as expected.\")."}, {"obj": "1.5", "q": "An administrator explains the importance of a concept: \"Allows teams to develop, scale, and deploy components independently rather than as one large monolith.\" What concept is this?", "c": ["Loosely Coupled Architecture", "Cloud-Provided Managed Service", "Microservices", "Service Discovery"], "a": 2, "e": "Allows teams to develop, scale, and deploy components independently rather than as one large monolith. This describes Microservices (\"An architecture where an application is broken into small, independently deployable services.\")."}, {"obj": "4.4", "q": "An administrator explains the importance of a concept: \"Limits the potential damage if an account or service is compromised.\" What concept is this?", "c": ["API Security", "Principle of Least Privilege", "Unprivileged Container", "Object Storage Security"], "a": 1, "e": "Limits the potential damage if an account or service is compromised. This describes Principle of Least Privilege (\"Granting only the minimum access rights needed to perform a function.\")."}, {"obj": "2.3", "q": "Which migration strategy provides the fastest initial migration timeline but the least long-term benefit from cloud-native features?", "c": ["Re-architect", "Refactor", "Rehost", "Replatform"], "a": 2, "e": "Rehost (lift and shift) is the fastest approach since it requires minimal changes, but it also captures the least benefit from cloud-native capabilities."}, {"obj": "4.3", "q": "In cloud computing terminology, \"CLI\" refers to which of the following?", "c": ["A hardened server that provides a single, monitored entry point for administrative access into a private network.", "Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources.", "Allowing users to authenticate using credentials from a separate, trusted identity provider.", "Secure Shell — an encrypted protocol for remote command-line access to cloud resources."], "a": 1, "e": "Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources. Popular for scripting and automation tasks that would be tedious through a web portal."}, {"obj": "1.5", "q": "Select the most accurate description of \"Service Discovery\":", "c": ["A mechanism that lets services dynamically find the network location of other services.", "A design where components interact through well-defined interfaces with minimal direct dependencies.", "A messaging pattern where one event is distributed to multiple downstream consumers/services.", "An architecture where an application is broken into small, independently deployable services."], "a": 0, "e": "A mechanism that lets services dynamically find the network location of other services. Essential in dynamic cloud-native environments where service instances and IP addresses change constantly."}, {"obj": "5.3", "q": "Which term is most closely associated with this real-world importance: \"Underpins many internal microservice-to-microservice communication patterns (e.g., gRPC).\"?", "c": ["GraphQL", "SOAP", "RPC", "Event-Driven Architecture"], "a": 2, "e": "Underpins many internal microservice-to-microservice communication patterns (e.g., gRPC). This describes RPC (\"Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local.\")."}, {"obj": "1.6", "q": "In cloud computing terminology, \"Workload Orchestration\" refers to which of the following?", "c": ["Temporary storage tied to a container's lifecycle that is lost when the container stops.", "Storage that survives beyond the lifecycle of an individual container.", "Automated management of container deployment, scaling, and healing (e.g., Kubernetes).", "A repository for storing and distributing container images (e.g., Docker Hub, a private registry)."], "a": 2, "e": "Automated management of container deployment, scaling, and healing (e.g., Kubernetes). Essential for running containerized applications reliably at scale in production."}, {"obj": "1.4", "q": "Which of the following best describes \"HDD\"?", "c": ["Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk.", "A storage tier for data accessed less frequently than hot data, balancing cost and access speed.", "A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost.", "Hard Disk Drive — traditional magnetic spinning-platter storage."], "a": 3, "e": "Hard Disk Drive — traditional magnetic spinning-platter storage. Offers lower cost per GB than SSD, suited to large, less performance-sensitive datasets."}, {"obj": "2.5", "q": "Which of the following terms fits this definition: \"The uptime and resiliency expectations for a workload.\"?", "c": ["Compute Requirements", "Storage Requirements", "Compliance Requirements", "Availability Requirements"], "a": 3, "e": "\"The uptime and resiliency expectations for a workload.\" describes Availability Requirements. Drives decisions like multi-AZ deployment, clustering, and failover design."}, {"obj": "3.1", "q": "An engineer troubleshooting a slow checkout process needs to see exactly which of five backend calls (inventory, payment, shipping, tax, and confirmation) is adding the most latency to the overall request. What tool is best suited?", "c": ["A basic CPU utilization dashboard", "Distributed tracing showing the timing of each call in the request path", "A simple log retention policy", "An alert triage spreadsheet"], "a": 1, "e": "Distributed tracing specifically shows the timing breakdown of each hop in a multi-service request, directly revealing which call contributes the most latency."}, {"obj": "4.6", "q": "Why does this matter on the exam and in practice? \"A cloud-specific attack vector, since metadata services often provide temporary credentials to the instance.\" — which term does this explain?", "c": ["Cryptojacking", "Metadata Attack", "Event Monitoring (Security)", "Zombie Instance"], "a": 1, "e": "A cloud-specific attack vector, since metadata services often provide temporary credentials to the instance. This describes Metadata Attack (\"An attack that abuses a cloud instance's metadata service to steal credentials or configuration data.\")."}, {"obj": "1.10", "q": "Which of the following is the correct expansion of \"IOPS\"?", "c": ["Input/Output Operations Per Second", "Intrusion Prevention System", "Real-time Messaging Protocol", "Database as a Service"], "a": 0, "e": "IOPS stands for Input/Output Operations Per Second. A measure of storage system performance."}, {"obj": "1.6", "q": "A description reads: \"A single container running in isolation without orchestration.\" Which term does this describe?", "c": ["Port Mapping", "Ephemeral Storage", "Stand-Alone Container", "Workload Orchestration"], "a": 2, "e": "\"A single container running in isolation without orchestration.\" describes Stand-Alone Container. Simple to run for development/testing but lacks automated scaling, healing, or scheduling."}, {"obj": "2.5", "q": "Why does this matter on the exam and in practice? \"Can restrict which regions, providers, or configurations are acceptable for a given workload.\" — which term does this explain?", "c": ["Availability Requirements", "Compute Requirements", "Network Requirements", "Compliance Requirements"], "a": 3, "e": "Can restrict which regions, providers, or configurations are acceptable for a given workload. This describes Compliance Requirements (\"Legal or regulatory obligations a workload's data and processing must meet.\")."}, {"obj": "3.3", "q": "Why does this matter on the exam and in practice? \"Balances storage cost against the need to recover from an issue discovered after some delay.\" — which term does this explain?", "c": ["Backup Schedule", "Backup Retention (Ops)", "Parallel Recovery", "In-Place Recovery"], "a": 1, "e": "Balances storage cost against the need to recover from an issue discovered after some delay. This describes Backup Retention (Ops) (\"How long backup copies are kept before being deleted or overwritten.\")."}, {"obj": "5.1", "q": "Which concept is described by the phrase: \"Organizing and maintaining separate lines of development (branches) within a repository.\"?", "c": ["Pull Request", "Code Merge", "Version Management", "Branch Management"], "a": 3, "e": "\"Organizing and maintaining separate lines of development (branches) within a repository.\" describes Branch Management. Allows parallel work on features/fixes without disrupting the main codebase."}, {"obj": "3.2", "q": "Which statement accurately describes \"Horizontal Scaling\"?", "c": ["Scaling in response to a specific event (like a message queue depth increasing).", "Scaling resources up or down at predefined times based on known usage patterns.", "Adding more instances of a resource to handle increased load (scale out).", "Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%)."], "a": 2, "e": "Adding more instances of a resource to handle increased load (scale out). Improves both capacity and redundancy, and is the standard scaling approach in cloud-native design."}, {"obj": "5.2", "q": "Which term is most closely associated with this real-world importance: \"The \"CI\" in CI/CD — frequent integration catches conflicts and bugs early.\"?", "c": ["Code Integration", "Public Repository", "Build (CI/CD)", "CI/CD Security"], "a": 0, "e": "The \"CI\" in CI/CD — frequent integration catches conflicts and bugs early. This describes Code Integration (\"Merging code changes from multiple contributors into a shared, continuously tested codebase.\")."}, {"obj": "3.1", "q": "Which of the following best describes \"Monitoring Metrics\"?", "c": ["The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.", "Numeric measurements of system behavior (CPU, memory, request rate) collected over time.", "Defining how long log data is kept before being archived or deleted.", "Combining logs from many sources into a unified, searchable view."], "a": 1, "e": "Numeric measurements of system behavior (CPU, memory, request rate) collected over time. The foundation of dashboards and alerting used to understand system health."}, {"obj": "1.11", "q": "How would you most accurately define \"IoT Sensor\"?", "c": ["AI technology that identifies objects, scenes, or features within images or video.", "A device that collects data from the physical environment (temperature, motion, etc.).", "AI technology that converts written text into spoken audio (speech synthesis).", "A device that aggregates and relays data from multiple IoT sensors to the cloud."], "a": 1, "e": "A device that collects data from the physical environment (temperature, motion, etc.). The data-collection endpoint in most IoT architectures, feeding data upstream for processing."}, {"obj": "6.2", "q": "A network engineer discovers that a route table entry sends traffic destined for a specific subnet to the wrong gateway, causing it to be dropped. What is this called?", "c": ["A missing route", "A misconfigured route", "IP scope exhaustion", "Protocol deprecation"], "a": 1, "e": "A misconfigured route is an incorrect entry in a route table sending traffic to the wrong destination, distinct from a missing route where no entry exists at all."}, {"obj": "3.3", "q": "Which statement accurately describes \"Incremental Backup\"?", "c": ["Restoring individual files or specific data items rather than an entire dataset.", "Backs up only data changed since the last backup of any type.", "Copying backup data to another location (often off-site or another region).", "Verifying that backed-up data has not been corrupted."], "a": 1, "e": "Backs up only data changed since the last backup of any type. Fastest to perform, but restoring requires the full chain of backups applied in order."}, {"obj": "1.9", "q": "Given the description \"A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS).\", which term is being defined?", "c": ["Provider-Managed Database", "Relational Database", "Self-Managed Database", "Non-Relational Database"], "a": 0, "e": "\"A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS).\" describes Provider-Managed Database. Reduces administrative burden significantly, letting teams focus on the data and application instead of the database engine."}, {"obj": "4.6", "q": "An attacker exploits a cloud instance's metadata service to retrieve temporary credentials automatically assigned to that instance, then uses them to access other cloud resources. What is this called?", "c": ["A metadata attack", "A DDoS attack", "Phishing", "Cryptojacking"], "a": 0, "e": "A metadata attack abuses a cloud instance's metadata service (which often provides temporary credentials) to steal access, a cloud-specific attack vector."}, {"obj": "1.1", "q": "Under the shared responsibility model for an IaaS deployment, who is typically responsible for patching the guest operating system?", "c": ["The cloud provider only", "The customer", "Neither party", "A third-party auditor"], "a": 1, "e": "In IaaS, the provider secures the physical infrastructure and hypervisor, while the customer remains responsible for OS-level patching and configuration."}, {"obj": "3.1", "q": "A company's on-call rotation is overwhelmed because every minor warning generates an urgent page, causing engineers to eventually ignore alerts altogether. What practice would most directly address this?", "c": ["Better alert triage and tuning to distinguish true emergencies from minor warnings", "Deleting all logs immediately", "Removing all monitoring metrics", "Increasing the number of alerts sent"], "a": 0, "e": "Properly triaging and tuning alerts to distinguish real emergencies from minor warnings prevents alert fatigue, which otherwise causes engineers to start ignoring important alerts."}, {"obj": "1.10", "q": "Users in a distant region report noticeably slow application response times despite healthy server-side CPU and memory metrics. What metric should be investigated first?", "c": ["Network latency between the user and the application region", "Storage IOPS", "CPU utilization", "Compute optimization type"], "a": 0, "e": "Slow response times with healthy server-side metrics point toward network latency, especially for users geographically distant from the hosting region."}, {"obj": "1.4", "q": "In Cloud+ terminology, \"RAID\" is an abbreviation for which of the following?", "c": ["Software-defined Network", "Redundant Array of Independent Disks", "Virtual Machine", "Virtual Private Network"], "a": 1, "e": "RAID stands for Redundant Array of Independent Disks. A technology combining multiple physical disks for redundancy, performance, or both."}, {"obj": "4.3", "q": "Which statement accurately describes \"MFA\"?", "c": ["Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.", "Multifactor Authentication — requiring two or more independent verification factors to log in.", "A hardened server that provides a single, monitored entry point for administrative access into a private network.", "Application Programming Interface — used here for programmatic management/access to cloud resources."], "a": 1, "e": "Multifactor Authentication — requiring two or more independent verification factors to log in. Makes stolen credentials alone insufficient for an attacker to gain access."}, {"obj": "3.2", "q": "An application automatically adds new instances whenever average CPU utilization crosses 75% for five consecutive minutes. What scaling approach is this?", "c": ["Scheduled scaling", "Triggered scaling — load-based", "Manual scaling", "Vertical scaling only"], "a": 1, "e": "Load-triggered scaling reacts to a real-time metric threshold being crossed, the most common autoscaling mechanism."}, {"obj": "2.5", "q": "In cloud computing terminology, \"Compute Requirements\" refers to which of the following?", "c": ["The capacity, performance, and durability needs a workload has for its data.", "The bandwidth, latency, and connectivity needs of a workload.", "Legal or regulatory obligations a workload's data and processing must meet.", "The processing power (CPU, RAM) needed to run a workload effectively."], "a": 3, "e": "The processing power (CPU, RAM) needed to run a workload effectively. Determines the instance size and type selected during provisioning."}, {"obj": "5.2", "q": "How would you most accurately define \"Private Repository\"?", "c": ["A code or artifact repository restricted to authorized users/systems.", "Automatically running tests against code as part of the pipeline.", "Merging code changes from multiple contributors into a shared, continuously tested codebase.", "A code or artifact repository accessible to anyone."], "a": 0, "e": "A code or artifact repository restricted to authorized users/systems. The standard choice for proprietary source code and internal build artifacts."}, {"obj": "2.5", "q": "Which term is most closely associated with this real-world importance: \"Shapes decisions about region placement, dedicated connections, and load balancer configuration.\"?", "c": ["Network Requirements", "Storage Requirements", "Compute Requirements", "Compliance Requirements"], "a": 0, "e": "Shapes decisions about region placement, dedicated connections, and load balancer configuration. This describes Network Requirements (\"The bandwidth, latency, and connectivity needs of a workload.\")."}, {"obj": "1.5", "q": "Which of the following terms fits this definition: \"An architecture where an application is broken into small, independently deployable services.\"?", "c": ["Microservices", "Loosely Coupled Architecture", "Cloud-Provided Managed Service", "Fan-Out"], "a": 0, "e": "\"An architecture where an application is broken into small, independently deployable services.\" describes Microservices. Allows teams to develop, scale, and deploy components independently rather than as one large monolith."}, {"obj": "3.4", "q": "A temporary cache used only during a single processing job does not need to be backed up or retained afterward. What type of data is this?", "c": ["Persistent data", "Ephemeral data", "Archived data", "Compliance data"], "a": 1, "e": "Ephemeral data is temporary and does not need to persist beyond a session or process, unlike persistent data."}, {"obj": "2.1", "q": "Which concept is described by the phrase: \"A deployment model combining private/on-premises infrastructure with public cloud resources.\"?", "c": ["Public Cloud", "Private Cloud", "Hybrid Cloud", "Community Cloud"], "a": 2, "e": "\"A deployment model combining private/on-premises infrastructure with public cloud resources.\" describes Hybrid Cloud. Common for gradual migration, burst capacity, or workloads with data residency constraints."}, {"obj": "1.5", "q": "Which term best matches this description: \"A messaging pattern where one event is distributed to multiple downstream consumers/services.\"?", "c": ["Service Discovery", "Loosely Coupled Architecture", "Microservices", "Fan-Out"], "a": 3, "e": "\"A messaging pattern where one event is distributed to multiple downstream consumers/services.\" describes Fan-Out. Common in event-driven microservices to notify several services of the same event simultaneously."}, {"obj": "1.9", "q": "A company chooses a self-managed database over a provider-managed service specifically because they need to install a custom, unsupported extension not offered by any managed service. What are they trading away by making this choice?", "c": ["Nothing; there is no trade-off", "The convenience of provider-managed patching, backups, and maintenance in exchange for full customization control", "Data durability guarantees", "The ability to use SQL at all"], "a": 1, "e": "Choosing a self-managed database for custom control means giving up the operational convenience (automated patching, backups, maintenance) that a managed service provides."}, {"obj": "1.8", "q": "A company has a steady-state workload running 24/7 for the next three years and wants to minimize cost. Which billing model is most appropriate?", "c": ["Pay-as-you-go", "Spot instances", "Reserved resources", "On-demand dedicated host"], "a": 2, "e": "Reserved resources offer a discount in exchange for a committed term, ideal for predictable, long-running workloads."}, {"obj": "5.4", "q": "A team wants an agentless automation tool that uses simple, human-readable YAML playbooks to configure hundreds of servers consistently. Which tool fits best?", "c": ["Terraform", "Ansible", "Kubernetes", "Jenkins"], "a": 1, "e": "Ansible is an agentless automation tool that uses YAML playbooks to automate configuration management tasks across many systems without requiring installed agents."}, {"obj": "1.6", "q": "\"Ephemeral Storage\" is best defined as which of the following?", "c": ["Storage that survives beyond the lifecycle of an individual container.", "Automated management of container deployment, scaling, and healing (e.g., Kubernetes).", "A repository for storing and distributing container images (e.g., Docker Hub, a private registry).", "Temporary storage tied to a container's lifecycle that is lost when the container stops."], "a": 3, "e": "Temporary storage tied to a container's lifecycle that is lost when the container stops. Suitable only for temporary/scratch data since it disappears when the container is removed."}, {"obj": "5.1", "q": "Which statement accurately describes \"Code Push\"?", "c": ["Uploading local code changes to a remote/shared repository.", "A formal request to merge a proposed code change into a shared branch, typically triggering review.", "Tracking and organizing different versions of code or configuration over time.", "Combining changes from different branches into one."], "a": 0, "e": "Uploading local code changes to a remote/shared repository. The action that shares a developer's committed changes with the rest of the team."}, {"obj": "2.2", "q": "A team wants to expose a risky new feature to just 5% of production traffic before a full rollout. Which strategy is this?", "c": ["Canary deployment", "Blue-green deployment", "In-place deployment", "Rolling deployment"], "a": 0, "e": "Canary deployment gradually exposes a change to a small subset of traffic first, limiting the impact of any issues."}, {"obj": "4.3", "q": "Given the description \"An access model where the resource owner decides who else can access it.\", which term is being defined?", "c": ["OAuth 2.0", "Bastion Host", "SSH", "Discretionary Access Control"], "a": 3, "e": "\"An access model where the resource owner decides who else can access it.\" describes Discretionary Access Control. Flexible, but relies on individual owners consistently applying good judgment about access grants."}, {"obj": "1.4", "q": "Which of the following best describes \"Object Storage\"?", "c": ["Storage that manages data as discrete objects with metadata, accessed via an API (e.g., S3).", "A storage tier for data accessed less frequently than hot data, balancing cost and access speed.", "Hard Disk Drive — traditional magnetic spinning-platter storage.", "Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O."], "a": 0, "e": "Storage that manages data as discrete objects with metadata, accessed via an API (e.g., S3). Highly scalable and durable, ideal for unstructured data like backups, media, and static web content."}, {"obj": "1.11", "q": "A colleague says: \"Powers use cases like content moderation, quality inspection, and security monitoring.\" Which concept are they describing?", "c": ["Sentiment Analysis", "Visual Recognition", "Text Recognition", "IoT Gateway"], "a": 1, "e": "Powers use cases like content moderation, quality inspection, and security monitoring. This describes Visual Recognition (\"AI technology that identifies objects, scenes, or features within images or video.\")."}, {"obj": "5.2", "q": "Which statement accurately describes \"CI/CD Automation\"?", "c": ["A simple, unstructured file (like a config or script) produced or consumed by a pipeline.", "Automatically building, testing, and deploying code changes with minimal manual intervention.", "A package format (.deb) used for installing software on Debian-based Linux distributions.", "A code or artifact repository accessible to anyone."], "a": 1, "e": "Automatically building, testing, and deploying code changes with minimal manual intervention. Reduces human error and speeds up the delivery of software changes."}, {"obj": "1.8", "q": "A company evaluates switching a predictable, long-running workload from pay-as-you-go to a 1-year reserved commitment. What is the primary trade-off they are considering?", "c": ["Higher flexibility in exchange for a higher price", "Lower cost in exchange for reduced flexibility due to the committed term", "No difference in cost or flexibility", "Reserved pricing eliminates the need for monitoring"], "a": 1, "e": "Reserved pricing lowers cost through a committed term, at the cost of the flexibility that pay-as-you-go pricing offers."}, {"obj": "4.1", "q": "Which statement accurately describes \"Vulnerability Identification\"?", "c": ["Evaluating identified vulnerabilities for severity, exploitability, and business impact.", "The step of detecting known weaknesses in systems, typically via automated scanning.", "Defining which systems, networks, or applications a vulnerability scan will cover.", "Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities."], "a": 1, "e": "The step of detecting known weaknesses in systems, typically via automated scanning. The first concrete step in the vulnerability management lifecycle, feeding into assessment and remediation."}, {"obj": "4.2", "q": "In cloud computing terminology, \"Data Sovereignty\" refers to which of the following?", "c": ["A data retention requirement specified in a contract with a customer or partner.", "Payment Card Industry Data Security Standard — security requirements for handling payment card data.", "An organization that publishes best practices and frameworks specifically for cloud security.", "The principle that data is subject to the laws of the country in which it is physically located."], "a": 3, "e": "The principle that data is subject to the laws of the country in which it is physically located. Determines which region a workload must be deployed in to satisfy legal requirements."}, {"obj": "5.4", "q": "A description reads: \"A distributed version control system used to track changes in source code.\" Which term does this describe?", "c": ["GitHub Actions", "Jenkins", "Git", "Grafana"], "a": 2, "e": "\"A distributed version control system used to track changes in source code.\" describes Git. The de facto standard version control system underlying most modern DevOps workflows."}, {"obj": "4.3", "q": "Given the description \"Authentication using a temporary token issued after initial login, rather than resending credentials each time.\", which term is being defined?", "c": ["Token-Based Authentication", "Bastion Host", "CLI", "Group-Based Access Control"], "a": 0, "e": "\"Authentication using a temporary token issued after initial login, rather than resending credentials each time.\" describes Token-Based Authentication. Reduces the exposure of long-term credentials and supports short-lived, revocable sessions."}, {"obj": "6.2", "q": "A newly created subnet has no path defined to reach a peered VPC, so traffic destined there is silently dropped. What is the cause?", "c": ["A missing route", "IP scope exhaustion", "Cipher suite deprecation", "HTTP status code mismatch"], "a": 0, "e": "A missing route means no path has been defined for that destination in the route table, so traffic is dropped."}, {"obj": "4.3", "q": "A description reads: \"Authentication using a temporary token issued after initial login, rather than resending credentials each time.\" Which term does this describe?", "c": ["Web Portal", "API (IAM Context)", "Token-Based Authentication", "Directory-Based Authentication"], "a": 2, "e": "\"Authentication using a temporary token issued after initial login, rather than resending credentials each time.\" describes Token-Based Authentication. Reduces the exposure of long-term credentials and supports short-lived, revocable sessions."}, {"obj": "3.4", "q": "\"Persistent Data\" is best defined as which of the following?", "c": ["Validating changes (patches, updates, configuration) before applying them broadly.", "Data that must be retained beyond the life of the process or instance that created it.", "Temporary data that does not need to persist beyond a session or process.", "A smaller update, typically with bug fixes and small improvements."], "a": 1, "e": "Data that must be retained beyond the life of the process or instance that created it. Requires durable storage and appropriate backup strategy since it represents lasting business value."}, {"obj": "6.2", "q": "Which statement accurately describes \"NAT (Troubleshooting)\"?", "c": ["Network Address Translation — translates private addresses to a public address for routing.", "Two networks using conflicting/duplicate IP address ranges.", "A connectivity failure caused by a system relying on a protocol version the other side no longer supports.", "Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500)."], "a": 0, "e": "Network Address Translation — translates private addresses to a public address for routing. Misconfigured NAT/port forwarding is a common cause of unreachable services behind a private network."}, {"obj": "1.8", "q": "Which of the following best describes \"Pay-As-You-Go\"?", "c": ["Attaching key-value metadata labels to cloud resources.", "A billing model where a customer pays for an entire physical host, regardless of utilization.", "Tracking actual consumption of cloud resources for billing and capacity planning purposes.", "A billing model charging only for actual resource consumption, with no upfront commitment."], "a": 3, "e": "A billing model charging only for actual resource consumption, with no upfront commitment. Maximizes flexibility for unpredictable or short-term workloads, at a higher per-unit cost than reserved pricing."}, {"obj": "1.6", "q": "Which term is most closely associated with this real-world importance: \"Essential for running containerized applications reliably at scale in production.\"?", "c": ["Image Registry", "Port Mapping", "Persistent Volume", "Workload Orchestration"], "a": 3, "e": "Essential for running containerized applications reliably at scale in production. This describes Workload Orchestration (\"Automated management of container deployment, scaling, and healing (e.g., Kubernetes).\")."}, {"obj": "5.2", "q": "A colleague says: \"Sometimes all that's needed for simple deployment tasks, without a full package format.\" Which concept are they describing?", "c": ["Flat File Artifact", "CI/CD Security", "Public Repository", "Code Deployment"], "a": 0, "e": "Sometimes all that's needed for simple deployment tasks, without a full package format. This describes Flat File Artifact (\"A simple, unstructured file (like a config or script) produced or consumed by a pipeline.\")."}, {"obj": "2.1", "q": "Which term best matches this description: \"Infrastructure physically located and managed within the organization's own facilities.\"?", "c": ["Community Cloud", "Public Cloud", "Hybrid Cloud", "On Premises"], "a": 3, "e": "\"Infrastructure physically located and managed within the organization's own facilities.\" describes On Premises. Gives maximum control over hardware and data location, at the cost of full operational responsibility."}, {"obj": "4.1", "q": "Which of the following is the correct expansion of \"CVSS\"?", "c": ["Lightweight Directory Access Protocol", "Common Vulnerability Scoring System", "Data Loss Prevention", "Virtual Desktop Infrastructure"], "a": 1, "e": "CVSS stands for Common Vulnerability Scoring System. A framework for rating the severity of security vulnerabilities."}, {"obj": "1.8", "q": "Given the description \"Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice.\", which term is being defined?", "c": ["Tagging", "Spot Instance", "Resource Metering", "Reserved Resources"], "a": 1, "e": "\"Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice.\" describes Spot Instance. Ideal for fault-tolerant, interruptible workloads like batch processing, but not suitable for critical always-on services."}, {"obj": "4.2", "q": "A company must ensure customer data physically stored in the EU remains subject to EU law, even though the company is US-based. What concept governs this?", "c": ["Data ownership", "Data sovereignty", "Data classification", "Litigation hold"], "a": 1, "e": "Data sovereignty means data is subject to the laws of the country where it is physically located."}, {"obj": "4.3", "q": "A colleague says: \"The standard way to securely administer Linux-based cloud instances remotely.\" Which concept are they describing?", "c": ["Bastion Host", "MFA", "SSH", "Web Portal"], "a": 2, "e": "The standard way to securely administer Linux-based cloud instances remotely. This describes SSH (\"Secure Shell — an encrypted protocol for remote command-line access to cloud resources.\")."}, {"obj": "5.3", "q": "The acronym \"RPC\" stands for:", "c": ["Disaster Recovery", "Remote Procedure Call", "Advanced Encryption Standard", "Availability Zone"], "a": 1, "e": "RPC stands for Remote Procedure Call. Lets a program execute a procedure on a remote system as if it were local."}, {"obj": "5.3", "q": "A frontend team wants to request only the exact fields they need from a backend API, rather than receiving a fixed, over-fetched response. Which API technology fits?", "c": ["SOAP", "GraphQL", "RPC", "Web sockets"], "a": 1, "e": "GraphQL lets clients specify exactly which fields they need, reducing over-fetching common with traditional REST endpoints."}, {"obj": "4.6", "q": "\"Vulnerability Exploitation — Human Error\" is best defined as which of the following?", "c": ["Malicious software designed to damage, disrupt, or gain unauthorized access to a system.", "A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email.", "A departure from a system's established normal behavior pattern.", "An attack that succeeds due to a mistake made by an authorized user (misconfiguration, mishandling credentials, etc.)."], "a": 3, "e": "An attack that succeeds due to a mistake made by an authorized user (misconfiguration, mishandling credentials, etc.). Highlights that technical controls alone can't fully prevent security incidents caused by human mistakes."}, {"obj": "5.2", "q": "In cloud computing terminology, \"RPM Package\" refers to which of the following?", "c": ["Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions.", "Releasing built and tested code to a target environment (e.g., production).", "A code or artifact repository accessible to anyone.", "Compiling/packaging source code into a deployable artifact."], "a": 0, "e": "Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions. One of several standard package formats a CI/CD pipeline might produce or deploy."}, {"obj": "2.4", "q": "A colleague says: \"One of the two dominant data formats used to define cloud resources declaratively.\" Which concept are they describing?", "c": ["JSON", "Drift Detection", "YAML", "IaC Versioning"], "a": 0, "e": "One of the two dominant data formats used to define cloud resources declaratively. This describes JSON (\"JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates.\")."}, {"obj": "1.1", "q": "Which of the following is the correct expansion of \"CSP\"?", "c": ["Customer Relationship Management", "Infrastructure as Code", "Cloud Service Provider", "System and Organization Controls 2"], "a": 2, "e": "CSP stands for Cloud Service Provider. A company offering cloud computing services (IaaS, PaaS, SaaS)."}, {"obj": "5.3", "q": "Which of the following best describes \"SOAP\"?", "c": ["Simple Object Access Protocol — an XML-based messaging protocol for web services.", "A query language for APIs that lets clients request exactly the data they need.", "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local.", "A design where components communicate by producing and reacting to events rather than direct calls."], "a": 0, "e": "Simple Object Access Protocol — an XML-based messaging protocol for web services. Older and more rigid than REST, but still used in some enterprise and legacy integrations."}, {"obj": "5.3", "q": "A chat application needs a persistent, full-duplex connection so messages can be pushed to users instantly without repeated polling. What technology should be used?", "c": ["REST with polling", "Web sockets", "SOAP", "A one-way RPC call"], "a": 1, "e": "Web sockets provide a persistent, full-duplex connection over a single TCP connection, ideal for real-time bidirectional communication like chat, unlike typical request/response HTTP."}, {"obj": "5.2", "q": "Multiple developers frequently merge their changes into a shared branch, with automated builds and tests running on every merge to catch conflicts and bugs early. What CI/CD principle is this?", "c": ["Code deployment", "Continuous integration (frequent code integration with automated verification)", "Artifact versioning only", "CI/CD security"], "a": 1, "e": "Continuous integration merges code frequently with automated builds/tests, catching integration conflicts and bugs early rather than late in the release cycle."}, {"obj": "6.1", "q": "A team allocates far more virtual CPUs to VMs on a host than the physical hardware can truly support, and performance degrades sharply under load. What is this called?", "c": ["Regional service availability", "Oversubscription", "API throttling", "Deprecation of functionality"], "a": 1, "e": "Oversubscription allocates more virtual resources than the underlying physical capacity can truly support, which can cause performance degradation when too many workloads compete for resources."}, {"obj": "1.4", "q": "A company needs a shared file system that many application servers can simultaneously mount and read/write, similar to a traditional network file share. What storage type fits?", "c": ["Object storage", "Block storage", "File storage", "Ephemeral disk"], "a": 2, "e": "File storage provides a shared, hierarchical file system accessible by multiple clients simultaneously, unlike block storage attached to a single VM."}, {"obj": "4.4", "q": "\"Hardening\" is best defined as which of the following?", "c": ["Securely storing and controlling access to credentials, API keys, and other sensitive configuration values.", "Controls governing which files and directories a container process can read or write.", "Reducing a system's attack surface by disabling unnecessary services, closing unused ports, and applying secure configurations.", "Applying vendor-released updates that fix known vulnerabilities."], "a": 2, "e": "Reducing a system's attack surface by disabling unnecessary services, closing unused ports, and applying secure configurations. One of the most fundamental and heavily tested security practices across all IT domains."}, {"obj": "4.6", "q": "Which concept is described by the phrase: \"Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources.\"?", "c": ["Vulnerability Exploitation — Outdated Software", "Malware", "Event Monitoring (Security)", "DDoS"], "a": 3, "e": "\"Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources.\" describes DDoS. Aims to exhaust resources or bandwidth so legitimate users cannot access the service."}, {"obj": "4.6", "q": "An investigation into a data breach reveals the root cause was an employee who accidentally misconfigured a storage bucket's permissions, exposing data publicly. What category of cause does this represent?", "c": ["Vulnerability exploitation via outdated software", "Vulnerability exploitation via human error", "A network-layer DDoS attack", "A hardware failure"], "a": 1, "e": "This scenario is caused by a human mistake (misconfiguration) rather than exploiting outdated software, categorizing it as human error rather than a software vulnerability exploit."}, {"obj": "6.3", "q": "Why does this matter on the exam and in practice? \"The core security incident type that access controls, logging, and monitoring are designed to catch.\" — which term does this explain?", "c": ["Unauthorized Software", "Privilege Escalation (Troubleshooting)", "Cipher Suite Deprecation", "Unauthorized Access"], "a": 3, "e": "The core security incident type that access controls, logging, and monitoring are designed to catch. This describes Unauthorized Access (\"Access to a system or data by someone without proper permission.\")."}, {"obj": "4.5", "q": "Why does this matter on the exam and in practice? \"Operates at the subnet/network level, distinct from security group/instance-level rules.\" — which term does this explain?", "c": ["Endpoint Protection", "WAF", "IAM Policies", "Network ACL"], "a": 3, "e": "Operates at the subnet/network level, distinct from security group/instance-level rules. This describes Network ACL (\"Access Control List — a set of rules controlling traffic in and out of a subnet at the network level.\")."}, {"obj": "4.3", "q": "Which term is most closely associated with this real-world importance: \"Enables automation but requires careful credential management since keys can be leaked or misused.\"?", "c": ["Federation", "Programmatic Access", "RDP", "Bastion Host"], "a": 1, "e": "Enables automation but requires careful credential management since keys can be leaked or misused. This describes Programmatic Access (\"Accessing cloud resources via code rather than a human using a GUI (API/SDK).\")."}, {"obj": "1.3", "q": "Which of the following best describes \"Firewall\"?", "c": ["A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features.", "Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains.", "A device or service that filters network traffic based on defined rules.", "A logical subdivision of a network's IP address range."], "a": 2, "e": "A device or service that filters network traffic based on defined rules. The primary control for restricting which traffic is allowed in/out of a cloud network segment."}, {"obj": "1.3", "q": "A company needs to connect its on-premises datacenter to its cloud VPC with consistent, predictable bandwidth and lower latency than a typical internet-based VPN. What should they provision?", "c": ["A site-to-site VPN over the public internet", "A dedicated connection (e.g., Direct Connect or ExpressRoute)", "A CDN endpoint", "A public-facing load balancer"], "a": 1, "e": "A dedicated connection provides a private physical link with more consistent performance than routing over the public internet via VPN."}, {"obj": "1.9", "q": "In cloud computing terminology, \"Non-Relational Database\" refers to which of the following?", "c": ["A database that organizes data into structured tables with defined relationships (SQL).", "A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs.", "A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure.", "A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS)."], "a": 1, "e": "A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs. Better suited for unstructured/semi-structured data and workloads needing horizontal scalability."}, {"obj": "3.4", "q": "A colleague says: \"Requires durable storage and appropriate backup strategy since it represents lasting business value.\" Which concept are they describing?", "c": ["Minor Update", "Patch", "Persistent Data", "Ephemeral Data"], "a": 2, "e": "Requires durable storage and appropriate backup strategy since it represents lasting business value. This describes Persistent Data (\"Data that must be retained beyond the life of the process or instance that created it.\")."}, {"obj": "1.11", "q": "Which term best matches this description: \"AI models that create new content (text, images, code) based on learned patterns.\"?", "c": ["IoT Sensor", "Generative AI", "Visual Recognition", "IoT Transmission Protocol"], "a": 1, "e": "\"AI models that create new content (text, images, code) based on learned patterns.\" describes Generative AI. A rapidly growing category of cloud AI services used for content creation and code assistance."}, {"obj": "1.2", "q": "A manufacturing company deploys sensors on a factory floor that pass data to a small local server for real-time processing before summarized results are sent to the cloud. What architecture is this?", "c": ["Cloud bursting", "Edge computing", "A community cloud", "A hot site"], "a": 1, "e": "Edge computing processes data physically close to where it's generated, reducing latency for time-sensitive factory-floor operations."}, {"obj": "1.10", "q": "Which of the following best describes \"Compute Optimization (VM)\"?", "c": ["Input/Output Operations Per Second — a measure of storage performance.", "Using virtual machines as the compute resource type for a workload.", "Using Function as a Service as the compute resource type for a workload.", "The time delay for data to travel between two points on a network."], "a": 1, "e": "Using virtual machines as the compute resource type for a workload. Appropriate for workloads needing full OS control and long-running processes."}, {"obj": "1.2", "q": "In Cloud+ terminology, \"RTO\" is an abbreviation for which of the following?", "c": ["Hypertext Transfer Protocol", "Operating System", "Recovery Time Objective", "Cloud Service Provider"], "a": 2, "e": "RTO stands for Recovery Time Objective. The maximum acceptable downtime for a system after a disruption."}, {"obj": "5.3", "q": "Which statement accurately describes \"RPC\"?", "c": ["Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local.", "A design where components communicate by producing and reacting to events rather than direct calls.", "A query language for APIs that lets clients request exactly the data they need.", "Simple Object Access Protocol — an XML-based messaging protocol for web services."], "a": 0, "e": "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local. Underpins many internal microservice-to-microservice communication patterns (e.g., gRPC)."}, {"obj": "1.3", "q": "A colleague says: \"Used for advanced routing scenarios like connecting on-premises networks to the cloud via dedicated connections.\" Which concept are they describing?", "c": ["Route Table", "BGP", "SDN", "Transit Gateway"], "a": 1, "e": "Used for advanced routing scenarios like connecting on-premises networks to the cloud via dedicated connections. This describes BGP (\"Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.\")."}, {"obj": "6.2", "q": "A server behind a NAT gateway cannot be reached directly from the internet on a specific port, even though internal-to-internal connectivity works fine. What is likely missing?", "c": ["A DNS A record only", "A port forwarding (destination NAT) rule directing that external port to the internal server", "A default gateway configuration", "A subnet mask correction"], "a": 1, "e": "Reaching an internally NATed server from the internet on a specific port typically requires an explicit port forwarding/destination NAT rule on the gateway."}, {"obj": "1.3", "q": "Which of the following best describes \"Static Route\"?", "c": ["A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features.", "A manually configured network route that does not change dynamically.", "Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network.", "Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains."], "a": 1, "e": "A manually configured network route that does not change dynamically. Simple and predictable, but requires manual updates if the network topology changes."}, {"obj": "1.11", "q": "A global retailer wants its website content automatically converted into multiple languages for international customers. Which AI capability is needed?", "c": ["Text translation", "Visual recognition", "Sentiment analysis", "IoT transmission protocol"], "a": 0, "e": "Text translation automatically converts text from one language to another, directly serving the retailer's international localization need."}, {"obj": "1.3", "q": "Which concept is described by the phrase: \"Virtual Private Cloud — an isolated, logically defined network within a public cloud provider's infrastructure.\"?", "c": ["Application Gateway", "VPN", "Dedicated Connection", "VPC"], "a": 3, "e": "\"Virtual Private Cloud — an isolated, logically defined network within a public cloud provider's infrastructure.\" describes VPC. Forms the fundamental network boundary for cloud resources, similar to a private on-premises network."}, {"obj": "1.5", "q": "Which scenario best illustrates a loosely coupled architecture?", "c": ["Service A calls a well-defined API on Service B and does not depend on B's internal implementation details", "Service A directly accesses Service B's internal database tables", "Service A and Service B share the same compiled binary", "Service A must be restarted whenever Service B is updated"], "a": 0, "e": "Interacting only through a well-defined API interface, without depending on internal implementation details, is the hallmark of loose coupling."}, {"obj": "4.2", "q": "Which concept is described by the phrase: \"The principle that data is subject to the laws of the country in which it is physically located.\"?", "c": ["Data Ownership", "Data Sovereignty", "Regulatory Retention", "Data Classification"], "a": 1, "e": "\"The principle that data is subject to the laws of the country in which it is physically located.\" describes Data Sovereignty. Determines which region a workload must be deployed in to satisfy legal requirements."}, {"obj": "1.6", "q": "A container needs data to survive even after the container is destroyed and replaced. What should be used?", "c": ["Ephemeral storage", "A persistent volume", "Local container filesystem", "Port mapping"], "a": 1, "e": "A persistent volume exists independently of any single container's lifecycle, preserving data across container restarts and replacements."}, {"obj": "1.2", "q": "A company needs the fastest possible recovery time after a regional outage and is willing to pay for a fully staffed, continuously synced standby environment. Which DR site type fits?", "c": ["Cold site", "Warm site", "Hot site", "Reciprocal site"], "a": 2, "e": "A hot site is kept fully equipped and synchronized, enabling the fastest possible failover at the highest ongoing cost."}, {"obj": "4.4", "q": "Which concept is described by the phrase: \"A container granted elevated access to the host system's resources.\"?", "c": ["Data in Transit Encryption", "Secrets Management", "Privileged Container", "Patching (Security)"], "a": 2, "e": "\"A container granted elevated access to the host system's resources.\" describes Privileged Container. Significantly increases risk since a compromised privileged container can affect the underlying host."}, {"obj": "4.4", "q": "A colleague says: \"APIs are a primary attack surface in cloud-native applications and require dedicated protective controls.\" Which concept are they describing?", "c": ["Object Storage Security", "Hardening", "Vendor-Specific Benchmark", "API Security"], "a": 3, "e": "APIs are a primary attack surface in cloud-native applications and require dedicated protective controls. This describes API Security (\"Practices and controls that protect APIs from abuse, unauthorized access, and attack.\")."}, {"obj": "4.2", "q": "A cloud customer wants third-party assurance that a SaaS provider's security and availability controls meet an independent audit standard. Which report should they request?", "c": ["A CVE report", "A SOC 2 report", "A CVSS score", "An RTO worksheet"], "a": 1, "e": "A SOC 2 report is an independent audit evaluating a service provider's controls around security, availability, and confidentiality."}, {"obj": "2.3", "q": "\"Retain\" is best defined as which of the following?", "c": ["A migration strategy that decommissions an application no longer needed.", "Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.", "A migration strategy that keeps a workload where it currently is, deferring migration.", "A migration strategy that moves an application to the cloud with minimal changes, also called lift and shift."], "a": 2, "e": "A migration strategy that keeps a workload where it currently is, deferring migration. Appropriate for applications not yet ready or not worth migrating due to cost or complexity."}, {"obj": "1.10", "q": "A description reads: \"Input/Output Operations Per Second — a measure of storage performance.\" Which term does this describe?", "c": ["Network Throughput", "IOPS (Optimization)", "Compute Optimization (VM)", "Workflow (Optimization)"], "a": 1, "e": "\"Input/Output Operations Per Second — a measure of storage performance.\" describes IOPS (Optimization). A key metric for sizing storage for database or transaction-heavy workloads."}, {"obj": "4.4", "q": "A company encrypts all data stored in its cloud object storage buckets so that even if the underlying storage is somehow improperly accessed, the data remains unreadable without the correct key. What practice is this?", "c": ["Data in transit encryption", "Data at rest encryption", "API security", "Least privilege"], "a": 1, "e": "Data at rest encryption protects stored data so it remains unreadable without the correct key, even if the media or storage itself is improperly accessed."}, {"obj": "1.6", "q": "Which of the following terms fits this definition: \"Automated management of container deployment, scaling, and healing (e.g., Kubernetes).\"?", "c": ["Port Mapping", "Image Registry", "Workload Orchestration", "Stand-Alone Container"], "a": 2, "e": "\"Automated management of container deployment, scaling, and healing (e.g., Kubernetes).\" describes Workload Orchestration. Essential for running containerized applications reliably at scale in production."}, {"obj": "6.2", "q": "Select the most accurate description of \"NTP (Troubleshooting)\":", "c": ["Two networks using conflicting/duplicate IP address ranges.", "Network Time Protocol — synchronizes system clocks across a network.", "A connectivity failure caused by a system relying on a protocol version the other side no longer supports.", "Domain Name System — resolves hostnames to IP addresses."], "a": 1, "e": "Network Time Protocol — synchronizes system clocks across a network. Clock drift can break authentication (like Kerberos) and certificate validation in subtle, confusing ways."}, {"obj": "4.1", "q": "Why does this matter on the exam and in practice? \"Ensures the scan actually covers all in-scope assets rather than leaving blind spots.\" — which term does this explain?", "c": ["Remediation", "Vulnerability Assessment", "Scanning Scope", "Vulnerability Identification"], "a": 2, "e": "Ensures the scan actually covers all in-scope assets rather than leaving blind spots. This describes Scanning Scope (\"Defining which systems, networks, or applications a vulnerability scan will cover.\")."}, {"obj": "4.6", "q": "Which of the following best describes \"Cryptojacking\"?", "c": ["A cloud instance that is running but forgotten, unmonitored, or unmanaged.", "Continuously observing system and security events for signs of malicious activity.", "Unauthorized use of a system's computing resources to mine cryptocurrency.", "Network ports left open on a system that are not required for its function."], "a": 2, "e": "Unauthorized use of a system's computing resources to mine cryptocurrency. Often detected through unexplained high CPU usage and increased cloud compute costs."}, {"obj": "5.2", "q": "How would you most accurately define \"Debian Package\"?", "c": ["A package format (.deb) used for installing software on Debian-based Linux distributions.", "A packaged container image produced and stored as a build output.", "Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions.", "Incorporating security scanning and checks into the automated pipeline."], "a": 0, "e": "A package format (.deb) used for installing software on Debian-based Linux distributions. The counterpart to RPM packages on Debian/Ubuntu-based systems."}, {"obj": "1.3", "q": "Which term best matches this description: \"A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers).\"?", "c": ["VPC", "VLAN", "CDN", "Application Load Balancer"], "a": 3, "e": "\"A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers).\" describes Application Load Balancer. Enables advanced routing such as sending /api traffic to one backend and /images to another."}, {"obj": "1.11", "q": "Which statement accurately describes \"IoT Transmission Protocol\"?", "c": ["AI technology that converts written text into spoken audio (speech synthesis).", "Lightweight protocols (like MQTT or CoAP) designed for constrained IoT devices and networks.", "AI technology that converts spoken audio into written text (speech recognition).", "AI technology that determines the emotional tone (positive/negative/neutral) of text."], "a": 1, "e": "Lightweight protocols (like MQTT or CoAP) designed for constrained IoT devices and networks. Optimized for low bandwidth and power use, unlike heavier traditional web protocols."}, {"obj": "4.2", "q": "\"PCI DSS\" is best defined as which of the following?", "c": ["Systems and Organization Controls 2 — an audit framework evaluating a service provider's controls around security, availability, and confidentiality.", "The principle that data is subject to the laws of the country in which it is physically located.", "Payment Card Industry Data Security Standard — security requirements for handling payment card data.", "Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted)."], "a": 2, "e": "Payment Card Industry Data Security Standard — security requirements for handling payment card data. Any cloud workload that stores, processes, or transmits card data must meet these requirements."}, {"obj": "2.1", "q": "A company is migrating gradually from on-premises to the cloud and needs both environments to operate together during the multi-year transition. Which deployment model supports this transitional approach?", "c": ["Public cloud only", "Hybrid cloud", "Community cloud", "On premises only"], "a": 1, "e": "Hybrid cloud is commonly used to support gradual migrations, letting on-premises and public cloud infrastructure operate together during the transition."}, {"obj": "4.3", "q": "A colleague says: \"Simplifies administration and enforces consistent access across users with the same job function.\" Which concept are they describing?", "c": ["OpenID Connect", "Federation", "Directory-Based Authentication", "Role-Based Access Control"], "a": 3, "e": "Simplifies administration and enforces consistent access across users with the same job function. This describes Role-Based Access Control (\"Granting permissions based on a user's assigned role rather than to each individual directly.\")."}, {"obj": "1.8", "q": "A company wants to avoid overpaying for reserved capacity it no longer fully needs after downsizing a project. What practice should they perform regularly?", "c": ["Ignore utilization trends entirely", "Periodically review and rightsize reserved commitments against actual usage", "Switch permanently to dedicated host billing", "Disable all resource metering"], "a": 1, "e": "Regularly reviewing utilization against reserved commitments allows a company to rightsize and avoid continuing to pay for capacity it no longer needs."}, {"obj": "1.7", "q": "A hypervisor environment uses a virtual network built on top of the physical network infrastructure, allowing flexible virtual topologies independent of the physical layout. What is this called?", "c": ["A VLAN only", "An overlay network", "Hardware pass-through", "Host affinity"], "a": 1, "e": "An overlay network is built on top of physical infrastructure, allowing flexible virtual network topologies independent of physical layout, common in virtualization and containers."}, {"obj": "2.2", "q": "A team wants to test a risky new feature on just 5% of production traffic before committing to a full rollout, minimizing the blast radius of any issue. Which strategy is this?", "c": ["Blue-green deployment", "Canary deployment", "In-place deployment", "A cold-standby deployment"], "a": 1, "e": "Canary deployment gradually exposes a change to a small subset of traffic first, limiting exposure if something goes wrong."}, {"obj": "6.2", "q": "An organization's cloud subnet has run out of available IP addresses, blocking new instances from being provisioned. What is this called?", "c": ["IP scope exhaustion", "Network overlap", "Protocol incompatibility", "A missing route"], "a": 0, "e": "IP scope exhaustion means the available address range has been fully consumed, blocking new provisioning until it is expanded or addresses are reclaimed."}, {"obj": "2.3", "q": "In cloud computing terminology, \"Retire\" refers to which of the following?", "c": ["A migration strategy that moves an application to the cloud with minimal changes, also called lift and shift.", "A migration strategy that rewrites portions of an application to better fit cloud-native patterns.", "Moving workloads out of the cloud back to local infrastructure.", "A migration strategy that decommissions an application no longer needed."], "a": 3, "e": "A migration strategy that decommissions an application no longer needed. Reduces the overall migration scope and ongoing costs by eliminating unnecessary systems."}, {"obj": "4.5", "q": "Which of the following terms fits this definition: \"Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications.\"?", "c": ["IPS/IDS", "Endpoint Protection", "WAF", "Network Security Group"], "a": 2, "e": "\"Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications.\" describes WAF. Protects against application-layer attacks like SQL injection and cross-site scripting that a normal firewall wouldn't catch."}, {"obj": "1.6", "q": "Select the most accurate description of \"Image Registry\":", "c": ["Binding a container's internal port to a port on the host or load balancer.", "A repository for storing and distributing container images (e.g., Docker Hub, a private registry).", "Storage that survives beyond the lifecycle of an individual container.", "A single container running in isolation without orchestration."], "a": 1, "e": "A repository for storing and distributing container images (e.g., Docker Hub, a private registry). Provides a central, versioned source for pulling container images during deployment."}, {"obj": "2.1", "q": "\"Private Cloud\" is best defined as which of the following?", "c": ["A deployment model combining private/on-premises infrastructure with public cloud resources.", "Infrastructure dedicated to a single organization, hosted on- or off-premises.", "Infrastructure physically located and managed within the organization's own facilities.", "Infrastructure owned by a third-party provider and shared across many customers (multi-tenant)."], "a": 1, "e": "Infrastructure dedicated to a single organization, hosted on- or off-premises. Offers greater control and customization at higher cost than public cloud."}, {"obj": "4.1", "q": "Given the description \"The step of detecting known weaknesses in systems, typically via automated scanning.\", which term is being defined?", "c": ["Vulnerability Identification", "Vulnerability Assessment", "Scanning Scope", "CVE"], "a": 0, "e": "\"The step of detecting known weaknesses in systems, typically via automated scanning.\" describes Vulnerability Identification. The first concrete step in the vulnerability management lifecycle, feeding into assessment and remediation."}, {"obj": "3.3", "q": "Why does this matter on the exam and in practice? \"Especially important since backups often contain complete copies of sensitive production data.\" — which term does this explain?", "c": ["Backup Encryption", "Bulk Recovery", "Granular Recovery", "In-Place Recovery"], "a": 0, "e": "Especially important since backups often contain complete copies of sensitive production data. This describes Backup Encryption (\"Encrypting backup data so it remains protected even if the storage media or files are exposed.\")."}, {"obj": "5.4", "q": "Which concept is described by the phrase: \"An open-source tool for visualizing metrics and creating monitoring dashboards.\"?", "c": ["Docker", "Grafana", "Ansible", "Git"], "a": 1, "e": "\"An open-source tool for visualizing metrics and creating monitoring dashboards.\" describes Grafana. Commonly paired with time-series databases to build real-time operational dashboards."}, {"obj": "6.2", "q": "Select the most accurate description of \"DNS (Troubleshooting)\":", "c": ["Dynamic Host Configuration Protocol — automatically assigns IP addressing information to hosts.", "Domain Name System — resolves hostnames to IP addresses.", "Two networks using conflicting/duplicate IP address ranges.", "A connectivity failure caused by a system relying on a protocol version the other side no longer supports."], "a": 1, "e": "Domain Name System — resolves hostnames to IP addresses. DNS failures cause connectivity issues that look like the destination is down, even when it's reachable by IP."}, {"obj": "2.4", "q": "An administrator explains the importance of a concept: \"Makes infrastructure changes repeatable, version-controlled, and auditable.\" What concept is this?", "c": ["YAML", "Configuration as Code", "Infrastructure as Code", "Drift Detection"], "a": 2, "e": "Makes infrastructure changes repeatable, version-controlled, and auditable. This describes Infrastructure as Code (\"Managing and provisioning infrastructure through machine-readable definition files rather than manual processes.\")."}, {"obj": "6.1", "q": "Which concept is described by the phrase: \"A previously available feature or API being retired by the provider.\"?", "c": ["Deprecation of Functionality", "API Throttling", "Outdated Component Definitions", "Partial Outage"], "a": 0, "e": "\"A previously available feature or API being retired by the provider.\" describes Deprecation of Functionality. Deployments relying on deprecated functionality will eventually fail and must be updated proactively."}, {"obj": "4.2", "q": "Which term best matches this description: \"Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted).\"?", "c": ["SOC2", "Data Classification", "Regulatory Retention", "Cloud Security Alliance"], "a": 1, "e": "\"Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted).\" describes Data Classification. Drives how strictly a given piece of data must be protected and handled."}, {"obj": "6.2", "q": "Given the description \"A connectivity failure caused by two systems using different or mismatched protocol versions.\", which term is being defined?", "c": ["HTTP Status Codes", "Protocol Incompatibility", "DHCP (Troubleshooting)", "Protocol Deprecation"], "a": 1, "e": "\"A connectivity failure caused by two systems using different or mismatched protocol versions.\" describes Protocol Incompatibility. Common after upgrading one side of a connection without updating the other."}, {"obj": "4.4", "q": "Why does this matter on the exam and in practice? \"Ensures only authorized users/systems can read or modify shared file data.\" — which term does this explain?", "c": ["Unprivileged Container", "File Storage Security", "Secrets Management", "Patching (Security)"], "a": 1, "e": "Ensures only authorized users/systems can read or modify shared file data. This describes File Storage Security (\"Access controls and encryption applied to shared file storage systems.\")."}, {"obj": "1.10", "q": "A team needs a workload that runs unpredictably in short bursts, wants zero server management, and only wants to pay for actual execution time. Which compute optimization approach fits best?", "c": ["Virtual machines with reserved capacity", "Containers on a self-managed cluster", "Serverless functions (FaaS)", "Dedicated physical hosts"], "a": 2, "e": "Serverless compute eliminates server management entirely and bills only for actual execution time, ideal for unpredictable, bursty workloads."}, {"obj": "1.10", "q": "An administrator explains the importance of a concept: \"Appropriate for workloads needing full OS control and long-running processes.\" What concept is this?", "c": ["Network Throughput", "Orchestration (Workload)", "Workflow (Optimization)", "Compute Optimization (VM)"], "a": 3, "e": "Appropriate for workloads needing full OS control and long-running processes. This describes Compute Optimization (VM) (\"Using virtual machines as the compute resource type for a workload.\")."}, {"obj": "1.3", "q": "A cloud network engineer needs to advertise routes dynamically between the company's on-premises network and its cloud VPC over a dedicated connection, adjusting automatically if a path becomes unavailable. What protocol is typically used?", "c": ["Static routing only", "BGP", "VLAN tagging", "CDN routing"], "a": 1, "e": "BGP is the routing protocol commonly used to dynamically exchange and adjust routing information over dedicated connections between large networks."}, {"obj": "5.2", "q": "Which term is most closely associated with this real-world importance: \"Catches regressions before code reaches production, a core benefit of CI/CD.\"?", "c": ["Code Integration", "CI/CD Workflow", "Public Repository", "CI/CD Testing"], "a": 3, "e": "Catches regressions before code reaches production, a core benefit of CI/CD. This describes CI/CD Testing (\"Automatically running tests against code as part of the pipeline.\")."}, {"obj": "5.1", "q": "A developer submits a pull request, but a reviewer identifies a security issue and requests changes before approval. What is the purpose of this review step?", "c": ["To slow down development with no real benefit", "To catch bugs, security issues, and design problems before the change reaches the shared codebase", "To automatically deploy the code to production", "To delete the developer's branch"], "a": 1, "e": "Code review specifically exists to catch bugs, security issues, and design problems before a change is merged and potentially reaches production."}, {"obj": "4.4", "q": "A company stores API keys and database passwords in a dedicated vault service instead of hardcoding them into application source code. What practice is this?", "c": ["Secrets management", "Data at rest encryption", "Least privilege", "API security"], "a": 0, "e": "Secrets management securely stores and controls access to credentials and API keys, avoiding exposure in source code."}, {"obj": "4.5", "q": "Select the most accurate description of \"IAM Policies\":", "c": ["Access Control List — a set of rules controlling traffic in and out of a subnet at the network level.", "A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs.", "Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic.", "Rules that define what actions a given identity is allowed or denied to perform on cloud resources."], "a": 3, "e": "Rules that define what actions a given identity is allowed or denied to perform on cloud resources. The core mechanism for enforcing least privilege and access control in cloud environments."}, {"obj": "6.1", "q": "A deployment fails only when targeting one specific region while succeeding in all others, and the target region simply doesn't offer the required managed database service. What is the cause?", "c": ["Regional service availability", "API throttling", "Sizing issues", "Resource allocation misconfiguration"], "a": 0, "e": "Not all cloud services are available in every region; a deployment can fail simply because a required service isn't offered in the chosen region."}, {"obj": "6.1", "q": "A previously working deployment pipeline suddenly fails because a cloud provider retired an API endpoint the automation relied on, with no replacement configured. What is the cause?", "c": ["A sizing issue", "Deprecation of functionality", "Oversubscription", "A partial outage"], "a": 1, "e": "Deprecation of functionality occurs when a previously available feature or API is retired by the provider, breaking any automation still relying on it."}, {"obj": "1.1", "q": "What does the abbreviation \"OS\" stand for?", "c": ["Hard Disk Drive", "Operating System", "System and Organization Controls 2", "Internet Service Provider"], "a": 1, "e": "OS stands for Operating System. The base software managing hardware resources and running applications."}, {"obj": "1.2", "q": "An administrator explains the importance of a concept: \"Offers the shortest RTO but is the most expensive DR option to maintain.\" What concept is this?", "c": ["Availability Zone", "Hot Site", "Edge Computing", "Cloud Bursting"], "a": 1, "e": "Offers the shortest RTO but is the most expensive DR option to maintain. This describes Hot Site (\"A fully equipped, continuously running DR site that can take over almost immediately.\")."}, {"obj": "4.4", "q": "Which term best matches this description: \"A set of vendor-neutral, consensus-based configuration hardening guidelines.\"?", "c": ["CIS Benchmark", "Zero Trust", "Object Storage Security", "Principle of Least Privilege"], "a": 0, "e": "\"A set of vendor-neutral, consensus-based configuration hardening guidelines.\" describes CIS Benchmark. Provides a well-known, widely adopted baseline for hardening systems and cloud services."}, {"obj": "1.6", "q": "Which term best matches this description: \"Temporary storage tied to a container's lifecycle that is lost when the container stops.\"?", "c": ["Stand-Alone Container", "Persistent Volume", "Image Registry", "Ephemeral Storage"], "a": 3, "e": "\"Temporary storage tied to a container's lifecycle that is lost when the container stops.\" describes Ephemeral Storage. Suitable only for temporary/scratch data since it disappears when the container is removed."}, {"obj": "1.3", "q": "Given the description \"Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.\", which term is being defined?", "c": ["BGP", "Subnet", "VLAN", "VPN"], "a": 0, "e": "\"Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.\" describes BGP. Used for advanced routing scenarios like connecting on-premises networks to the cloud via dedicated connections."}, {"obj": "6.3", "q": "A security review discovers an employee accessed a customer database they had no legitimate business reason to view, despite having valid credentials. What is this called?", "c": ["A software vulnerability issue", "Unauthorized access", "Cipher suite deprecation", "IP scope exhaustion"], "a": 1, "e": "Unauthorized access describes access to a system or data by someone without proper permission or legitimate business justification, even if their credentials are technically valid."}, {"obj": "4.5", "q": "Select the most accurate description of \"Endpoint Protection\":", "c": ["Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity.", "Security software (antivirus, EDR) installed directly on servers, VMs, or devices.", "Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications.", "A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs."], "a": 1, "e": "Security software (antivirus, EDR) installed directly on servers, VMs, or devices. Detects and blocks malicious activity at the individual system level."}, {"obj": "4.1", "q": "A company's vulnerability scan only covers half of its cloud instances because several newly provisioned VMs were never added to the scan's target list. What step of vulnerability management was inadequately performed?", "c": ["Remediation", "Scanning scope definition", "CVE tracking", "Vulnerability assessment"], "a": 1, "e": "An incomplete scanning scope leaves parts of the environment unscanned, creating blind spots that should have been addressed by properly defining scope to include all assets."}, {"obj": "3.3", "q": "Select the most accurate description of \"Backup Schedule\":", "c": ["Verifying that backed-up data has not been corrupted.", "Restoring data directly onto the original system/location.", "The defined frequency and timing of backup jobs.", "Restoring a large set of data all at once."], "a": 2, "e": "The defined frequency and timing of backup jobs. Directly determines the achievable RPO for a given system."}, {"obj": "1.10", "q": "A storage volume backing a transaction-heavy database is consistently maxing out its available read/write operations per second, even though free capacity (GB) remains. What metric is the bottleneck?", "c": ["Network latency", "IOPS", "Storage capacity in GB", "CPU core count"], "a": 1, "e": "IOPS measures how many read/write operations a storage system can handle per second; exhausting it creates a bottleneck independent of remaining free capacity."}, {"obj": "1.8", "q": "Which of the following would be the most appropriate use case for dedicated host billing rather than standard multi-tenant instance billing?", "c": ["A short-lived, interruptible batch job", "A workload with per-physical-host licensing or strict compliance isolation requirements", "A workload needing maximum cost flexibility with no commitment", "A workload that can tolerate being reclaimed at any time"], "a": 1, "e": "Dedicated host billing is specifically useful when licensing terms or compliance requirements mandate physical isolation from other tenants."}, {"obj": "1.6", "q": "A containerized database needs its data to survive container restarts and replacements, since the container's own filesystem is normally wiped on restart. What should be used?", "c": ["Ephemeral storage", "A persistent volume", "No storage configuration is needed", "Port mapping"], "a": 1, "e": "Persistent volumes exist independently of any single container's lifecycle, which is required for stateful workloads like databases."}, {"obj": "4.3", "q": "A description reads: \"Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.\" Which term does this describe?", "c": ["SAML", "Role-Based Access Control", "API (IAM Context)", "SDK"], "a": 0, "e": "\"Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.\" describes SAML. Commonly used to implement federated single sign-on into cloud platforms."}, {"obj": "1.1", "q": "An administrator explains the importance of a concept: \"Billing is based on execution time/invocations rather than reserved capacity, ideal for event-driven workloads.\" What concept is this?", "c": ["SaaS", "FaaS", "Shared Responsibility Model", "IaaS"], "a": 1, "e": "Billing is based on execution time/invocations rather than reserved capacity, ideal for event-driven workloads. This describes FaaS (\"Function as a Service — lets code run in response to events without provisioning or managing any server (serverless).\")."}, {"obj": "3.1", "q": "A colleague says: \"Balances storage cost against the need to investigate older incidents or meet compliance requirements.\" Which concept are they describing?", "c": ["Log Aggregation", "Monitoring Metrics", "Tracing", "Log Retention"], "a": 3, "e": "Balances storage cost against the need to investigate older incidents or meet compliance requirements. This describes Log Retention (\"Defining how long log data is kept before being archived or deleted.\")."}, {"obj": "3.1", "q": "An engineer wants to follow a single customer request as it passes through five different microservices to find where latency is introduced. What observability technique is needed?", "c": ["Log rotation", "Tracing", "Alert triage", "Resource metering"], "a": 1, "e": "Tracing follows a single request across multiple services, which is essential for pinpointing latency in distributed systems."}, {"obj": "1.10", "q": "Which of the following best describes the goal of workload optimization in a cloud environment?", "c": ["Always choosing the cheapest possible compute type regardless of performance needs", "Matching compute, storage, and network resources to the specific needs of each workload for the best balance of performance and cost", "Using only virtual machines for every workload type", "Avoiding all monitoring and metrics collection"], "a": 1, "e": "Workload optimization is about matching resource types and configurations to actual workload needs, balancing performance and cost rather than defaulting to one option."}, {"obj": "5.2", "q": "In cloud computing terminology, \"Debian Package\" refers to which of the following?", "c": ["A code or artifact repository restricted to authorized users/systems.", "A package format (.deb) used for installing software on Debian-based Linux distributions.", "Releasing built and tested code to a target environment (e.g., production).", "A packaged virtual machine image produced and stored as a build output."], "a": 1, "e": "A package format (.deb) used for installing software on Debian-based Linux distributions. The counterpart to RPM packages on Debian/Ubuntu-based systems."}, {"obj": "4.2", "q": "Which term is most closely associated with this real-world importance: \"Closely related to, but distinct from, data sovereignty — it may be a business rather than legal requirement.\"?", "c": ["Data Classification", "Data Ownership", "SOC2", "Data Locality"], "a": 3, "e": "Closely related to, but distinct from, data sovereignty — it may be a business rather than legal requirement. This describes Data Locality (\"Requirements or preferences about the physical location where data is stored or processed.\")."}, {"obj": "3.3", "q": "A company performs a full backup every Sunday and differential backups every other day. If a restore is needed on Thursday, which backups are needed?", "c": ["Sunday's full backup plus only Wednesday's differential", "Sunday's full backup plus every differential from Monday through Wednesday", "Only Wednesday's differential backup", "Only Sunday's full backup"], "a": 0, "e": "A differential backup captures all changes since the last full backup, so only the most recent differential (Wednesday's) plus the full backup are needed to restore."}, {"obj": "5.2", "q": "Select the most accurate description of \"Debian Package\":", "c": ["A package format (.deb) used for installing software on Debian-based Linux distributions.", "A packaged virtual machine image produced and stored as a build output.", "Releasing built and tested code to a target environment (e.g., production).", "Incorporating security scanning and checks into the automated pipeline."], "a": 0, "e": "A package format (.deb) used for installing software on Debian-based Linux distributions. The counterpart to RPM packages on Debian/Ubuntu-based systems."}, {"obj": "1.1", "q": "Why does this matter on the exam and in practice? \"The customer patches and secures the OS/apps; the provider is responsible only for the underlying physical infrastructure.\" — which term does this explain?", "c": ["IaaS", "Shared Responsibility Model", "FaaS", "PaaS"], "a": 0, "e": "The customer patches and secures the OS/apps; the provider is responsible only for the underlying physical infrastructure. This describes IaaS (\"Infrastructure as a Service — provides virtualized compute, storage, and networking, leaving the OS and above to the customer.\")."}, {"obj": "6.1", "q": "Which statement accurately describes \"Regional Service Availability\"?", "c": ["A provider intentionally limiting the rate of API calls a customer can make.", "Allocating more virtual resources than the underlying physical capacity can truly support.", "The fact that not all cloud services are available in every region.", "A degradation where some, but not all, functionality or users are affected."], "a": 2, "e": "The fact that not all cloud services are available in every region. A deployment can fail simply because a required service isn't offered in the chosen region."}, {"obj": "1.5", "q": "A cloud-native application needs each service instance to dynamically find the network location of other services as they scale up and down. What capability is required?", "c": ["Service discovery", "Fan-out", "Loosely coupled architecture", "Cloud-provided managed service"], "a": 0, "e": "Service discovery lets services dynamically locate one another in an environment where instances and IPs change constantly."}, {"obj": "4.3", "q": "Which concept is described by the phrase: \"Authenticating with credentials stored directly on the system rather than a central directory.\"?", "c": ["Local User Authentication", "Directory-Based Authentication", "Group-Based Access Control", "MFA"], "a": 0, "e": "\"Authenticating with credentials stored directly on the system rather than a central directory.\" describes Local User Authentication. Simple but doesn't scale well and complicates centralized policy enforcement across many systems."}, {"obj": "1.7", "q": "Which term best matches this description: \"A single hypervisor host running VMs with no clustering.\"?", "c": ["Stand-Alone Virtualization", "Cloning", "NAS (Virtualization Context)", "VM Network"], "a": 0, "e": "\"A single hypervisor host running VMs with no clustering.\" describes Stand-Alone Virtualization. Simple but offers no failover if the host fails."}, {"obj": "4.3", "q": "Select the most accurate description of \"Directory-Based Authentication\":", "c": ["Authenticating against a centralized directory service (like LDAP or Active Directory).", "Multifactor Authentication — requiring two or more independent verification factors to log in.", "An authorization framework that lets an application access resources on a user's behalf without sharing their password.", "An access model where the resource owner decides who else can access it."], "a": 0, "e": "Authenticating against a centralized directory service (like LDAP or Active Directory). Centralizes identity management across many systems rather than maintaining separate local accounts."}, {"obj": "3.1", "q": "A company gathers logs from dozens of application instances scattered across multiple regions into a single centralized system for searching and analysis. What practice is this?", "c": ["Log retention", "Log aggregation", "Alert response", "Tracing"], "a": 1, "e": "Log aggregation combines logs from many sources into a unified, searchable view, enabling cross-service correlation."}, {"obj": "6.3", "q": "Which of the following best describes \"Leaked Credentials\"?", "c": ["Software installed or running without proper approval, increasing risk and potentially breaching policy.", "An identity gaining higher access than originally granted, often through a flaw or misconfiguration.", "Authentication credentials that have been exposed, such as in code repositories or logs.", "Problems arising from unpatched or improperly configured software containing known weaknesses."], "a": 2, "e": "Authentication credentials that have been exposed, such as in code repositories or logs. A very common real-world cause of cloud breaches, often via credentials accidentally committed to source control."}, {"obj": "4.6", "q": "A company notices that several of its cloud instances have open network ports that were never intentionally configured and serve no known business purpose. What should be investigated?", "c": ["Whether the unnecessary open ports were introduced by misconfiguration or compromise", "Whether the instances are running a scheduled backup", "Whether the DNS configuration is correct", "Whether the billing statement is accurate"], "a": 0, "e": "Unnecessary open ports are a common finding indicating either misconfiguration or compromise, and should be investigated and closed if not required."}, {"obj": "5.2", "q": "Given the description \"Incorporating security scanning and checks into the automated pipeline.\", which term is being defined?", "c": ["Flat File Artifact", "CI/CD Security", "Code Integration", "CI/CD Workflow"], "a": 1, "e": "\"Incorporating security scanning and checks into the automated pipeline.\" describes CI/CD Security. Shifts security left, catching vulnerabilities earlier and cheaper than after deployment."}, {"obj": "1.8", "q": "A company's workload is abruptly terminated mid-job because the underlying capacity was reclaimed by the provider with only a few minutes' notice. What pricing model was most likely in use?", "c": ["Reserved resources", "Dedicated host billing", "Spot instances", "Pay-as-you-go on-demand"], "a": 2, "e": "Spot instances can be reclaimed by the provider with little notice, which is the defining trade-off in exchange for their steep discount."}, {"obj": "5.4", "q": "An administrator explains the importance of a concept: \"The most widely used container runtime and image format in modern DevOps workflows.\" What concept is this?", "c": ["Docker", "Jenkins", "ELK Stack", "GitHub Actions"], "a": 0, "e": "The most widely used container runtime and image format in modern DevOps workflows. This describes Docker (\"A platform for building, running, and managing containers.\")."}, {"obj": "6.1", "q": "An IaC template references a VM size that the provider has since retired. What is the most likely cause of the deployment failure?", "c": ["Outdated component definitions", "Oversubscription", "Permission issues", "Partial outage"], "a": 0, "e": "Outdated component definitions reference resource types/sizes no longer valid, causing deployment failures until updated."}, {"obj": "4.2", "q": "A colleague says: \"Clarifies responsibility and rights when data is stored or processed by a third-party cloud provider.\" Which concept are they describing?", "c": ["Data Locality", "Cloud Security Alliance", "Data Ownership", "Data Sovereignty"], "a": 2, "e": "Clarifies responsibility and rights when data is stored or processed by a third-party cloud provider. This describes Data Ownership (\"Defining who legally owns and controls a given set of data.\")."}, {"obj": "3.1", "q": "Why does this matter on the exam and in practice? \"The first step in observability — without collection, logs remain scattered and hard to analyze.\" — which term does this explain?", "c": ["Alert Triage", "Log Retention", "Log Collection", "Alert Response"], "a": 2, "e": "The first step in observability — without collection, logs remain scattered and hard to analyze. This describes Log Collection (\"Gathering log data from applications, systems, and services into a central location.\")."}, {"obj": "4.3", "q": "Select the most accurate description of \"Web Portal\":", "c": ["Authentication using a temporary token issued after initial login, rather than resending credentials each time.", "An access model where the resource owner decides who else can access it.", "Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources.", "A graphical, browser-based interface for managing cloud resources."], "a": 3, "e": "A graphical, browser-based interface for managing cloud resources. The most accessible management interface for humans, though less suited to automation."}, {"obj": "4.6", "q": "Which of the following terms fits this definition: \"A cloud instance that is running but forgotten, unmonitored, or unmanaged.\"?", "c": ["Zombie Instance", "DDoS", "Unnecessary Open Ports", "Deviation from Baseline"], "a": 0, "e": "\"A cloud instance that is running but forgotten, unmonitored, or unmanaged.\" describes Zombie Instance. Represents both wasted cost and an unpatched, unmonitored attack surface."}, {"obj": "5.4", "q": "Which term is most closely associated with this real-world importance: \"The de facto standard for container orchestration in modern cloud-native environments.\"?", "c": ["Jenkins", "Grafana", "Kubernetes", "Terraform"], "a": 2, "e": "The de facto standard for container orchestration in modern cloud-native environments. This describes Kubernetes (\"An open-source platform for automating deployment, scaling, and management of containerized applications.\")."}, {"obj": "2.3", "q": "Which of the following best illustrates the risk of vendor lock-in during a cloud migration?", "c": ["Choosing a migration strategy that uses only open, portable standards", "Building extensively on one provider's proprietary serverless and database services, making a future move to another provider very costly", "Retaining a workload on-premises indefinitely", "Retiring an unused application"], "a": 1, "e": "Deep reliance on one provider's proprietary services increases switching costs and complexity, which is the core risk of vendor lock-in."}, {"obj": "1.8", "q": "An administrator explains the importance of a concept: \"Prevents overspending on oversized resources while avoiding performance issues from undersized ones.\" What concept is this?", "c": ["Pay-As-You-Go", "Dedicated Host Billing", "Rightsizing", "Resource Metering"], "a": 2, "e": "Prevents overspending on oversized resources while avoiding performance issues from undersized ones. This describes Rightsizing (\"Adjusting the size/type of provisioned resources to match actual workload demand.\")."}, {"obj": "1.9", "q": "Which statement accurately describes \"Self-Managed Database\"?", "c": ["A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure.", "A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs.", "A database that organizes data into structured tables with defined relationships (SQL).", "A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS)."], "a": 0, "e": "A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure. Offers maximum control but requires the customer to handle all operational overhead."}, {"obj": "1.7", "q": "A description reads: \"A rule keeping specific VMs running on the same (or different) physical host.\" Which term does this describe?", "c": ["Host Affinity", "Local Storage (Virtualization)", "SAN (Virtualization Context)", "Hardware Pass-Through"], "a": 0, "e": "\"A rule keeping specific VMs running on the same (or different) physical host.\" describes Host Affinity. Used to keep related VMs together for performance, or apart for redundancy (anti-affinity)."}, {"obj": "4.6", "q": "In Cloud+ terminology, \"DDoS\" is an abbreviation for which of the following?", "c": ["Multifactor Authentication", "Cloud Security Alliance", "Distributed Denial of Service", "Redundant Array of Independent Disks"], "a": 2, "e": "DDoS stands for Distributed Denial of Service. An attack overwhelming a target with traffic from many distributed sources."}, {"obj": "6.3", "q": "Which term is most closely associated with this real-world importance: \"Common after a platform disables old, insecure ciphers for security reasons, breaking legacy clients.\"?", "c": ["Cipher Suite Deprecation", "Privilege Escalation (Troubleshooting)", "Software Vulnerability Issues", "Unauthorized Access"], "a": 0, "e": "Common after a platform disables old, insecure ciphers for security reasons, breaking legacy clients. This describes Cipher Suite Deprecation (\"A connectivity/security failure caused by relying on an outdated, no-longer-supported encryption cipher suite.\")."}, {"obj": "1.5", "q": "An e-commerce platform is broken into independently deployable services for catalog, cart, checkout, and shipping, each owned by a different team. What architecture pattern is this?", "c": ["A monolithic architecture", "Microservices", "A single virtual machine deployment", "A mainframe architecture"], "a": 1, "e": "Microservices architecture breaks an application into small, independently deployable services, matching this description exactly."}, {"obj": "5.4", "q": "Why does this matter on the exam and in practice? \"The de facto standard for container orchestration in modern cloud-native environments.\" — which term does this explain?", "c": ["Docker", "Ansible", "Kubernetes", "Jenkins"], "a": 2, "e": "The de facto standard for container orchestration in modern cloud-native environments. This describes Kubernetes (\"An open-source platform for automating deployment, scaling, and management of containerized applications.\")."}, {"obj": "4.6", "q": "Which term is most closely associated with this real-world importance: \"A key signal used to detect anomalies that might indicate compromise or misuse.\"?", "c": ["Phishing", "DDoS", "Deviation from Baseline", "Vulnerability Exploitation — Human Error"], "a": 2, "e": "A key signal used to detect anomalies that might indicate compromise or misuse. This describes Deviation from Baseline (\"A departure from a system's established normal behavior pattern.\")."}, {"obj": "4.3", "q": "Which concept is described by the phrase: \"Software Development Kit — a set of libraries/tools that let developers programmatically interact with a cloud platform.\"?", "c": ["API (IAM Context)", "Bastion Host", "Local User Authentication", "SDK"], "a": 3, "e": "\"Software Development Kit — a set of libraries/tools that let developers programmatically interact with a cloud platform.\" describes SDK. Simplifies calling cloud provider APIs from within application code."}, {"obj": "3.2", "q": "Given the description \"Scaling in response to a specific event (like a message queue depth increasing).\", which term is being defined?", "c": ["Triggered Scaling — Load", "Triggered Scaling — Event", "Horizontal Scaling", "Triggered Scaling — Trending"], "a": 1, "e": "\"Scaling in response to a specific event (like a message queue depth increasing).\" describes Triggered Scaling — Event. Useful for event-driven architectures where load isn't purely CPU/memory based."}, {"obj": "1.6", "q": "A developer runs a single container on their laptop for local testing with no orchestration platform involved. What is this best described as?", "c": ["Workload orchestration", "A stand-alone container", "A persistent volume deployment", "An image registry deployment"], "a": 1, "e": "A single container running in isolation without orchestration is a stand-alone container, common for development and testing but lacking production-grade automation."}, {"obj": "2.3", "q": "\"Re-Architect\" is best defined as which of the following?", "c": ["Moving workloads from local infrastructure into a cloud environment.", "A migration strategy that decommissions an application no longer needed.", "A migration strategy that substantially redesigns an application to be cloud-native.", "Moving workloads out of the cloud back to local infrastructure."], "a": 2, "e": "A migration strategy that substantially redesigns an application to be cloud-native. Takes the most effort but unlocks the greatest long-term benefits like scalability and cost efficiency."}, {"obj": "1.4", "q": "A description reads: \"A storage tier for infrequently accessed data, offering lower cost with slower retrieval.\" Which term does this describe?", "c": ["Warm Storage Tier", "Cold Storage Tier", "Object Storage", "Block Storage"], "a": 1, "e": "\"A storage tier for infrequently accessed data, offering lower cost with slower retrieval.\" describes Cold Storage Tier. Suitable for older backups or compliance data that is rarely, but occasionally, needed."}, {"obj": "4.3", "q": "A colleague says: \"Makes stolen credentials alone insufficient for an attacker to gain access.\" Which concept are they describing?", "c": ["Token-Based Authentication", "Directory-Based Authentication", "SAML", "MFA"], "a": 3, "e": "Makes stolen credentials alone insufficient for an attacker to gain access. This describes MFA (\"Multifactor Authentication — requiring two or more independent verification factors to log in.\")."}, {"obj": "1.3", "q": "Which of the following best describes \"SDN\"?", "c": ["A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features.", "Virtual Private Cloud — an isolated, logically defined network within a public cloud provider's infrastructure.", "A set of rules that determines where network traffic is directed.", "Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management."], "a": 3, "e": "Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management. Underpins most cloud networking, allowing networks to be defined and changed through code/APIs rather than physical rewiring."}, {"obj": "1.4", "q": "Which term is most closely associated with this real-world importance: \"Used for OS disks and databases that need low-latency, structured access to storage.\"?", "c": ["Cold Storage Tier", "SSD", "Warm Storage Tier", "Block Storage"], "a": 3, "e": "Used for OS disks and databases that need low-latency, structured access to storage. This describes Block Storage (\"Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk.\")."}, {"obj": "3.3", "q": "A colleague says: \"Restores are simpler than incremental (just the full plus the latest differential), but each differential grows larger over time.\" Which concept are they describing?", "c": ["Granular Recovery", "Full Backup", "Backup Recoverability Testing", "Differential Backup"], "a": 3, "e": "Restores are simpler than incremental (just the full plus the latest differential), but each differential grows larger over time. This describes Differential Backup (\"Backs up all data changed since the last full backup.\")."}, {"obj": "4.3", "q": "Administrators need a single, hardened, monitored entry point to reach private cloud instances via SSH rather than exposing every instance directly. What should be deployed?", "c": ["A bastion host", "A CDN", "A web portal", "An application gateway"], "a": 0, "e": "A bastion host provides one hardened, monitored entry point for administrative access, reducing the exposed attack surface."}, {"obj": "5.1", "q": "A developer saves a snapshot of their local changes to their version control history before sharing them with anyone else. What action is this?", "c": ["A code push", "A code commit", "A pull request", "A code merge"], "a": 1, "e": "A commit saves a snapshot of changes to the local version control history, distinct from pushing those changes to a shared remote repository."}, {"obj": "2.4", "q": "Select the most accurate description of \"Infrastructure as Code\":", "c": ["Yet Another Markup Language — a human-readable data format widely used for IaC and configuration files.", "Tracking changes to infrastructure code over time using version control.", "JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates.", "Managing and provisioning infrastructure through machine-readable definition files rather than manual processes."], "a": 3, "e": "Managing and provisioning infrastructure through machine-readable definition files rather than manual processes. Makes infrastructure changes repeatable, version-controlled, and auditable."}, {"obj": "4.4", "q": "A company implements rate limiting, authentication, and input validation specifically for its public-facing REST APIs to prevent abuse. What practice is this?", "c": ["Hardening of the OS only", "API security", "Data at rest encryption", "Secrets management"], "a": 1, "e": "API security encompasses practices like rate limiting, authentication, and input validation that specifically protect APIs, a primary attack surface in cloud-native applications."}, {"obj": "1.4", "q": "A company must retain financial records for 10 years for compliance but expects to access them perhaps once or twice during that entire period. Which storage tier minimizes cost?", "c": ["Hot tier", "Warm tier", "Archive tier", "Local SSD"], "a": 2, "e": "Archive tier storage offers the lowest cost for data that is very rarely accessed, in exchange for the slowest retrieval times."}, {"obj": "4.3", "q": "The acronym \"SSH\" stands for:", "c": ["Secure Shell", "Disaster Recovery", "Virtual CPU", "Transport Layer Security"], "a": 0, "e": "SSH stands for Secure Shell. An encrypted protocol for secure remote command-line access and file transfer."}, {"obj": "3.3", "q": "A backup administrator actually restores a sample dataset to confirm it can be used, rather than trusting a \"success\" status alone. What practice is this?", "c": ["Backup integrity testing only", "Backup recoverability testing", "Backup replication", "Granular recovery"], "a": 1, "e": "Backup recoverability testing involves actually restoring data to confirm it is truly usable, since a reported success doesn't guarantee restorability."}, {"obj": "5.1", "q": "Why does this matter on the exam and in practice? \"Integrates parallel work from multiple developers or feature branches.\" — which term does this explain?", "c": ["Code Commit", "Code Merge", "Pull Request", "Version Management"], "a": 1, "e": "Integrates parallel work from multiple developers or feature branches. This describes Code Merge (\"Combining changes from different branches into one.\")."}, {"obj": "1.11", "q": "Which statement accurately describes \"IoT Gateway\"?", "c": ["AI technology that determines the emotional tone (positive/negative/neutral) of text.", "AI technology that converts written text into spoken audio (speech synthesis).", "A device that aggregates and relays data from multiple IoT sensors to the cloud.", "A device that collects data from the physical environment (temperature, motion, etc.)."], "a": 2, "e": "A device that aggregates and relays data from multiple IoT sensors to the cloud. Reduces the number of direct cloud connections needed and can perform local pre-processing."}, {"obj": "1.2", "q": "Which statement accurately describes \"Edge Computing\"?", "c": ["Processing data physically close to where it is generated rather than in a centralized datacenter.", "A basic facility with power and space but no pre-installed equipment.", "Using services from more than one public cloud provider simultaneously.", "Temporarily extending an on-premises workload into the public cloud to handle demand spikes."], "a": 0, "e": "Processing data physically close to where it is generated rather than in a centralized datacenter. Reduces latency for time-sensitive applications like IoT and content delivery."}, {"obj": "5.2", "q": "\"CI/CD Testing\" is best defined as which of the following?", "c": ["A packaged container image produced and stored as a build output.", "A packaged virtual machine image produced and stored as a build output.", "Automatically running tests against code as part of the pipeline.", "A package format (.deb) used for installing software on Debian-based Linux distributions."], "a": 2, "e": "Automatically running tests against code as part of the pipeline. Catches regressions before code reaches production, a core benefit of CI/CD."}, {"obj": "4.1", "q": "The acronym \"CVE\" stands for:", "c": ["Real-time Messaging Protocol", "Common Vulnerabilities and Exposures", "Logical Unit Number", "Dynamic Host Configuration Protocol"], "a": 1, "e": "CVE stands for Common Vulnerabilities and Exposures. A standardized identifier for publicly known security vulnerabilities."}, {"obj": "4.1", "q": "Which of the following is the most appropriate reason to periodically re-scan an environment even after a round of remediation is complete?", "c": ["Re-scanning is purely a formality with no value once remediation is done", "New vulnerabilities are continuously discovered and disclosed, and previous fixes should be verified as still effective", "Vulnerability management only needs to happen once per organization's lifetime", "Re-scanning replaces the need for an initial scanning scope definition"], "a": 1, "e": "Vulnerability management is an ongoing cycle since new vulnerabilities are constantly discovered, and periodic re-scanning both catches new issues and verifies prior fixes remain effective."}, {"obj": "1.4", "q": "A colleague says: \"Ideal for shared application data and home directories accessed by multiple servers simultaneously.\" Which concept are they describing?", "c": ["HDD", "File Storage", "Block Storage", "Archive Storage Tier"], "a": 1, "e": "Ideal for shared application data and home directories accessed by multiple servers simultaneously. This describes File Storage (\"Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB).\")."}, {"obj": "1.11", "q": "A fleet of remote temperature sensors needs to aggregate readings locally before sending data to the cloud, minimizing the number of direct cloud connections. What component is needed?", "c": ["An IoT gateway", "A CDN", "A transit gateway", "A load balancer"], "a": 0, "e": "An IoT gateway aggregates and relays data from multiple sensors, reducing the number of direct cloud connections and enabling local pre-processing."}, {"obj": "1.3", "q": "Why does this matter on the exam and in practice? \"Enables private communication between separate VPCs without routing traffic over the public internet.\" — which term does this explain?", "c": ["VPC Peering", "Application Gateway", "VPN", "Firewall"], "a": 0, "e": "Enables private communication between separate VPCs without routing traffic over the public internet. This describes VPC Peering (\"A direct network connection between two VPCs that allows them to communicate as if on the same network.\")."}, {"obj": "4.5", "q": "A colleague says: \"Essential for internet-facing cloud services that could otherwise be overwhelmed by attack traffic.\" Which concept are they describing?", "c": ["DDoS Protection", "Network ACL", "Network Security Group", "DLP"], "a": 0, "e": "Essential for internet-facing cloud services that could otherwise be overwhelmed by attack traffic. This describes DDoS Protection (\"Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic.\")."}, {"obj": "3.4", "q": "A company applies a major version update directly to production without first testing it in a staging environment, and the update breaks a critical integration. What lifecycle management step was skipped?", "c": ["End of life planning", "Lifecycle testing before production rollout", "Data classification", "Ephemeral storage configuration"], "a": 1, "e": "Skipping lifecycle testing (validating a major update in staging before production rollout) is exactly what allowed the breaking change to reach production untested."}, {"obj": "2.4", "q": "Which concept is described by the phrase: \"Tracking changes to infrastructure code over time using version control.\"?", "c": ["IaC Testing", "Drift Detection", "JSON", "IaC Versioning"], "a": 3, "e": "\"Tracking changes to infrastructure code over time using version control.\" describes IaC Versioning. Enables rollback to a known-good configuration and provides an audit trail of infrastructure changes."}, {"obj": "3.4", "q": "How would you most accurately define \"Decommissioning — End of Support\"?", "c": ["Retiring or upgrading a resource because the vendor no longer provides support/patches for it.", "A smaller update, typically with bug fixes and small improvements.", "Temporary data that does not need to persist beyond a session or process.", "Retiring a resource because it has reached the end of its useful life or support."], "a": 0, "e": "Retiring or upgrading a resource because the vendor no longer provides support/patches for it. Running unsupported resources leaves known vulnerabilities permanently unpatched."}, {"obj": "2.5", "q": "An administrator explains the importance of a concept: \"Shapes decisions about region placement, dedicated connections, and load balancer configuration.\" What concept is this?", "c": ["Compute Requirements", "Storage Requirements", "Availability Requirements", "Network Requirements"], "a": 3, "e": "Shapes decisions about region placement, dedicated connections, and load balancer configuration. This describes Network Requirements (\"The bandwidth, latency, and connectivity needs of a workload.\")."}, {"obj": "5.3", "q": "Which term is most closely associated with this real-world importance: \"Reduces over-fetching/under-fetching of data compared to traditional REST endpoints.\"?", "c": ["Event-Driven Architecture", "Web Sockets", "SOAP", "GraphQL"], "a": 3, "e": "Reduces over-fetching/under-fetching of data compared to traditional REST endpoints. This describes GraphQL (\"A query language for APIs that lets clients request exactly the data they need.\")."}, {"obj": "2.3", "q": "In cloud computing terminology, \"Retain\" refers to which of the following?", "c": ["Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.", "Moving workloads from one cloud provider or region to another.", "A migration strategy that keeps a workload where it currently is, deferring migration.", "A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture."], "a": 2, "e": "A migration strategy that keeps a workload where it currently is, deferring migration. Appropriate for applications not yet ready or not worth migrating due to cost or complexity."}, {"obj": "6.2", "q": "Which of the following best describes \"Missing Route\"?", "c": ["An incorrect entry in a route table sending traffic to the wrong destination.", "A connectivity failure caused by a system relying on a protocol version the other side no longer supports.", "Domain Name System — resolves hostnames to IP addresses.", "A required network path that has not been defined in a route table."], "a": 3, "e": "A required network path that has not been defined in a route table. Traffic destined for that path is silently dropped, a common and often overlooked cloud networking issue."}, {"obj": "4.6", "q": "A server's outbound traffic suddenly spikes to an unfamiliar external IP address at 3 AM with no scheduled process running. What should be suspected?", "c": ["A routine software update", "Potential malware or a compromised account communicating externally", "Normal DNS caching behavior", "A scheduled backup job"], "a": 1, "e": "Unexplained outbound traffic to an unfamiliar destination during off-hours is a classic indicator of malware or account compromise communicating with an external party."}, {"obj": "1.7", "q": "Which concept is described by the phrase: \"The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network.\"?", "c": ["SAN (Virtualization Context)", "Hardware Pass-Through", "VM Network", "NAS (Virtualization Context)"], "a": 2, "e": "\"The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network.\" describes VM Network. Determines how a VM communicates with other VMs, the host, and external networks."}, {"obj": "1.10", "q": "Why does this matter on the exam and in practice? \"More lightweight and portable than VMs, ideal for microservices and rapid scaling.\" — which term does this explain?", "c": ["Orchestration (Workload)", "Compute Optimization (Container)", "Network Throughput", "Compute Optimization (Serverless)"], "a": 1, "e": "More lightweight and portable than VMs, ideal for microservices and rapid scaling. This describes Compute Optimization (Container) (\"Using containers as the compute resource type for a workload.\")."}, {"obj": "4.5", "q": "A company's e-commerce site experiences a sudden flood of traffic clearly designed to exhaust its server capacity and deny service to legitimate customers. Which control was most likely insufficient or missing?", "c": ["IAM policies", "DDoS protection", "Network ACLs", "Data at rest encryption"], "a": 1, "e": "A flood of traffic designed to exhaust capacity and deny service describes a DDoS attack, which DDoS protection services are specifically designed to mitigate."}, {"obj": "1.1", "q": "Which of the following best explains why the shared responsibility model shifts more security duties to the provider as you move from IaaS toward SaaS?", "c": ["Providers become less trustworthy at higher service levels", "The provider manages progressively more of the technology stack (OS, middleware, application) at each higher level", "Customers always pay less as responsibility shifts", "SaaS providers are legally exempt from security requirements"], "a": 1, "e": "As the service model moves up the stack, the provider takes over management of more layers, correspondingly assuming more of the associated security responsibility."}, {"obj": "3.3", "q": "A description reads: \"The defined frequency and timing of backup jobs.\" Which term does this describe?", "c": ["Bulk Recovery", "Backup Schedule", "Granular Recovery", "Backup Integrity Testing"], "a": 1, "e": "\"The defined frequency and timing of backup jobs.\" describes Backup Schedule. Directly determines the achievable RPO for a given system."}, {"obj": "6.1", "q": "A description reads: \"IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated.\" Which term does this describe?", "c": ["Outdated Component Definitions", "Partial Outage", "Service Quota", "Sizing Issues"], "a": 0, "e": "\"IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated.\" describes Outdated Component Definitions. Leads to deployment failures when the referenced component is no longer valid on the platform."}, {"obj": "3.1", "q": "A company wants to keep 90 days of application logs for troubleshooting, then automatically archive or delete older entries. What is being configured?", "c": ["Log retention", "Tracing", "Alert response", "Monitoring metrics"], "a": 0, "e": "Log retention defines how long log data is kept before being archived or deleted, balancing cost against investigative needs."}, {"obj": "4.3", "q": "Which of the following terms fits this definition: \"Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.\"?", "c": ["OpenID Connect", "Programmatic Access", "SAML", "Directory-Based Authentication"], "a": 2, "e": "\"Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.\" describes SAML. Commonly used to implement federated single sign-on into cloud platforms."}, {"obj": "5.2", "q": "Which of the following best describes the benefit of automating the deployment stage of a CI/CD pipeline?", "c": ["It eliminates the need for testing entirely", "It reduces the risk and manual effort involved in releasing changes to an environment", "It guarantees the code has no bugs", "It removes the need for version control"], "a": 1, "e": "Automating deployment reduces the manual effort and risk of human error involved in releasing changes, though it doesn't replace the need for testing or version control."}, {"obj": "4.4", "q": "Which statement accurately describes \"Principle of Least Privilege\"?", "c": ["A security model that assumes no user or device should be trusted by default, even inside the network perimeter.", "Access controls and encryption applied to shared file storage systems.", "Granting only the minimum access rights needed to perform a function.", "Controls governing which files and directories a container process can read or write."], "a": 2, "e": "Granting only the minimum access rights needed to perform a function. Limits the potential damage if an account or service is compromised."}, {"obj": "1.2", "q": "Given the description \"An isolated location within a region with independent power, cooling, and networking.\", which term is being defined?", "c": ["Availability Zone", "Availability Monitoring", "RPO", "Multicloud Tenancy"], "a": 0, "e": "\"An isolated location within a region with independent power, cooling, and networking.\" describes Availability Zone. Spreading resources across AZs protects against a single datacenter failure without the latency of a different region."}, {"obj": "5.2", "q": "Which concept is described by the phrase: \"A packaged virtual machine image produced and stored as a build output.\"?", "c": ["RPM Package", "Code Integration", "VM Image Artifact", "Build (CI/CD)"], "a": 2, "e": "\"A packaged virtual machine image produced and stored as a build output.\" describes VM Image Artifact. Provides a versioned, reusable deployment unit for VM-based workloads."}, {"obj": "6.1", "q": "Which statement accurately describes \"Service Quota\"?", "c": ["A provider-imposed limit on how many of a given resource type can be provisioned.", "IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated.", "A failure caused by mismatched software, hardware, or configuration versions.", "A deployment failure or performance problem caused by choosing an inappropriately sized resource."], "a": 0, "e": "A provider-imposed limit on how many of a given resource type can be provisioned. Deployments can fail silently if a quota is reached without prior awareness."}, {"obj": "1.4", "q": "Why does this matter on the exam and in practice? \"The default choice for performance-sensitive workloads like databases.\" — which term does this explain?", "c": ["Object Storage", "SSD", "HDD", "Archive Storage Tier"], "a": 1, "e": "The default choice for performance-sensitive workloads like databases. This describes SSD (\"Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.\")."}, {"obj": "6.2", "q": "In cloud computing terminology, \"DHCP (Troubleshooting)\" refers to which of the following?", "c": ["Network Time Protocol — synchronizes system clocks across a network.", "Dynamic Host Configuration Protocol — automatically assigns IP addressing information to hosts.", "Two networks using conflicting/duplicate IP address ranges.", "A required network path that has not been defined in a route table."], "a": 1, "e": "Dynamic Host Configuration Protocol — automatically assigns IP addressing information to hosts. A failed DHCP service can leave hosts without any usable network configuration."}, {"obj": "1.4", "q": "An administrator explains the importance of a concept: \"Highly scalable and durable, ideal for unstructured data like backups, media, and static web content.\" What concept is this?", "c": ["Object Storage", "File Storage", "SSD", "HDD"], "a": 0, "e": "Highly scalable and durable, ideal for unstructured data like backups, media, and static web content. This describes Object Storage (\"Storage that manages data as discrete objects with metadata, accessed via an API (e.g., S3).\")."}, {"obj": "2.3", "q": "In cloud computing terminology, \"Cloud-to-On-Premises Migration\" refers to which of the following?", "c": ["A migration strategy that moves an application to the cloud with minimal changes, also called lift and shift.", "Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.", "Moving workloads from local infrastructure into a cloud environment.", "Moving workloads out of the cloud back to local infrastructure."], "a": 3, "e": "Moving workloads out of the cloud back to local infrastructure. Sometimes chosen for cost, compliance, or performance reasons after initial cloud adoption."}, {"obj": "3.3", "q": "A company encrypts its backup files so that even if the backup storage is somehow accessed by an unauthorized party, the data remains unreadable. What practice is this?", "c": ["Backup replication", "Backup encryption", "Backup recoverability testing", "Bulk recovery"], "a": 1, "e": "Backup encryption protects backup data even if the underlying storage or files are exposed, since backups often contain complete copies of sensitive production data."}, {"obj": "3.4", "q": "A company plans to decommission an old application, but a customer contract requires specific data from it to be retained for three more years. What is the appropriate lifecycle management action?", "c": ["Immediately destroy all data and applications regardless of contractual obligations", "Archive the required data or extend limited retention for the specific data before fully decommissioning the resource", "Ignore the contractual requirement since the application is being retired", "Indefinitely delay decommissioning the entire application forever"], "a": 1, "e": "Contractual retention requirements must be satisfied for the specific data in question, even as the broader application is retired, typically through targeted archiving."}, {"obj": "1.4", "q": "Given the description \"A storage tier for data accessed less frequently than hot data, balancing cost and access speed.\", which term is being defined?", "c": ["File Storage", "SSD", "Warm Storage Tier", "Block Storage"], "a": 2, "e": "\"A storage tier for data accessed less frequently than hot data, balancing cost and access speed.\" describes Warm Storage Tier. A middle ground for data that's not actively hot but still needed with reasonable speed."}, {"obj": "1.10", "q": "A company observes that increasing the number of application server instances does not improve response times, and investigation reveals the shared database's IOPS are maxed out. What should be optimized?", "c": ["Add more application servers regardless of the database bottleneck", "Improve the database's storage performance (e.g., faster storage tier, more IOPS capacity)", "Reduce the number of application servers", "Ignore the finding since IOPS rarely matter"], "a": 1, "e": "Since the bottleneck is the database's storage IOPS, adding more application servers won't help; the storage performance itself needs to be addressed."}, {"obj": "1.4", "q": "A company needs to attach a virtual disk to a single VM to serve as its operating system boot volume. Which storage type is appropriate?", "c": ["Object storage", "Block storage", "File storage (NFS)", "Archive tier storage"], "a": 1, "e": "Block storage is the standard choice for OS boot volumes, since it presents a raw, addressable virtual disk to a single VM."}, {"obj": "2.2", "q": "Which of the following best describes \"Canary Deployment\"?", "c": ["Updating an existing server or instance directly rather than deploying an entirely new one.", "A strategy running two identical environments (blue and green), switching traffic to the new version once verified.", "Updating instances incrementally, a few at a time, rather than all at once.", "Gradually rolling out a change to a small subset of users or servers before a full rollout."], "a": 3, "e": "Gradually rolling out a change to a small subset of users or servers before a full rollout. Limits the blast radius of a bad deployment by exposing it to only a fraction of traffic first."}, {"obj": "5.2", "q": "A CI/CD pipeline fails a deployment because a required configuration file was accidentally left out of the build. What stage of the pipeline should be improved to catch this earlier?", "c": ["Code review only", "CI/CD testing, to validate the build artifact's completeness before deployment", "Branch management", "Version control history"], "a": 1, "e": "Improving automated testing to validate build artifact completeness would have caught the missing configuration file before it reached the deployment stage."}, {"obj": "1.2", "q": "Select the most accurate description of \"RTO\":", "c": ["A fully equipped, continuously running DR site that can take over almost immediately.", "Using services from more than one public cloud provider simultaneously.", "Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption.", "A basic facility with power and space but no pre-installed equipment."], "a": 2, "e": "Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption. Drives the choice of DR site type and how much automation/investment is needed to meet the target."}, {"obj": "1.1", "q": "A description reads: \"Infrastructure as a Service — provides virtualized compute, storage, and networking, leaving the OS and above to the customer.\" Which term does this describe?", "c": ["Shared Responsibility Model", "IaaS", "FaaS", "SaaS"], "a": 1, "e": "\"Infrastructure as a Service — provides virtualized compute, storage, and networking, leaving the OS and above to the customer.\" describes IaaS. The customer patches and secures the OS/apps; the provider is responsible only for the underlying physical infrastructure."}, {"obj": "2.4", "q": "A DevOps engineer writes a Kubernetes manifest to define a deployment's replicas, image, and resource limits. Which data format is this most likely written in?", "c": ["A proprietary binary format", "YAML", "A spreadsheet", "Plain unstructured text with no structure"], "a": 1, "e": "YAML is the standard, human-readable format used for Kubernetes manifests and many other IaC/configuration tools."}, {"obj": "2.4", "q": "The acronym \"IaC\" stands for:", "c": ["Infrastructure as Code", "Continuous Integration/Continuous Deployment", "Data Loss Prevention", "Logical Unit Number"], "a": 0, "e": "IaC stands for Infrastructure as Code. Managing and provisioning infrastructure through machine-readable definition files."}, {"obj": "1.9", "q": "The acronym \"IPS\" stands for:", "c": ["Bring Your Own Device", "Graphics Processing Unit", "Common Weakness Enumeration", "Intrusion Prevention System"], "a": 3, "e": "IPS stands for Intrusion Prevention System. Detects and actively blocks malicious network activity."}, {"obj": "3.3", "q": "Which statement accurately describes \"Backup Schedule\"?", "c": ["Backs up all data changed since the last full backup.", "How long backup copies are kept before being deleted or overwritten.", "Restoring data directly onto the original system/location.", "The defined frequency and timing of backup jobs."], "a": 3, "e": "The defined frequency and timing of backup jobs. Directly determines the achievable RPO for a given system."}, {"obj": "3.2", "q": "Which of the following best describes \"Manual Scaling\"?", "c": ["Scaling in response to a specific event (like a message queue depth increasing).", "Increasing the resources (CPU/RAM) of an existing instance (scale up).", "An administrator explicitly changing resource capacity rather than relying on automation.", "Scaling resources up or down at predefined times based on known usage patterns."], "a": 2, "e": "An administrator explicitly changing resource capacity rather than relying on automation. Useful for planned events or when automated triggers aren't yet configured."}, {"obj": "1.8", "q": "A company needs to track exactly how many hours each type of cloud resource was consumed during the month to validate their bill. What capability supports this?", "c": ["Tagging alone", "Resource metering", "Dedicated host billing", "Reserved instance discounts"], "a": 1, "e": "Resource metering tracks actual consumption of cloud resources, providing the raw usage data needed to validate billing and plan capacity."}, {"obj": "1.7", "q": "In cloud computing terminology, \"Cloning\" refers to which of the following?", "c": ["Creating an exact copy of an existing VM.", "Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction.", "A rule keeping specific VMs running on the same (or different) physical host.", "Network Attached Storage — shared file-level storage accessible by multiple hosts."], "a": 0, "e": "Creating an exact copy of an existing VM. Speeds up deployment of identical VMs without building each one from scratch."}, {"obj": "2.1", "q": "Given the description \"Infrastructure physically located and managed within the organization's own facilities.\", which term is being defined?", "c": ["On Premises", "Public Cloud", "Private Cloud", "Hybrid Cloud"], "a": 0, "e": "\"Infrastructure physically located and managed within the organization's own facilities.\" describes On Premises. Gives maximum control over hardware and data location, at the cost of full operational responsibility."}, {"obj": "5.2", "q": "Select the most accurate description of \"Code Integration\":", "c": ["A package format (.deb) used for installing software on Debian-based Linux distributions.", "Incorporating security scanning and checks into the automated pipeline.", "Merging code changes from multiple contributors into a shared, continuously tested codebase.", "Releasing built and tested code to a target environment (e.g., production)."], "a": 2, "e": "Merging code changes from multiple contributors into a shared, continuously tested codebase. The \"CI\" in CI/CD — frequent integration catches conflicts and bugs early."}, {"obj": "1.8", "q": "An engineer discovers several unattached storage volumes and idle load balancers still incurring charges from a decommissioned project. What practice would have caught this earlier?", "c": ["Regular cost/resource metering review and cleanup of orphaned resources", "Switching everything to spot pricing", "Avoiding all tagging", "Increasing reserved commitments"], "a": 0, "e": "Regularly reviewing resource metering and utilization data helps identify orphaned, unused resources that continue to incur unnecessary cost."}, {"obj": "1.4", "q": "A company is designing storage for a new application and must decide between block, file, and object storage. Which factor is most directly relevant to this decision?", "c": ["The color scheme of the storage vendor's dashboard", "How the application needs to access the data (raw block device, shared file system, or API-based objects)", "The number of employees at the company", "The physical location of the company's headquarters"], "a": 1, "e": "The application's access pattern (block-level, shared file-level, or object/API-level) is the primary driver in choosing the appropriate storage type."}, {"obj": "4.1", "q": "A team applies a vendor patch to close a known vulnerability identified during a scan. What step of the vulnerability management lifecycle is this?", "c": ["Identification", "Assessment", "Remediation", "Scanning scope"], "a": 2, "e": "Remediation is the step that actually applies a fix to resolve the vulnerability, reducing real risk."}, {"obj": "3.4", "q": "A cloud resource has reached the point where the vendor no longer issues security patches for it. What lifecycle stage is this?", "c": ["End of life", "End of support", "Minor update", "Ephemeral data"], "a": 1, "e": "End of support means the vendor no longer provides updates/patches, leaving known vulnerabilities permanently unaddressed if not replaced."}, {"obj": "4.5", "q": "A company wants to prevent sensitive customer data from being uploaded to an unauthorized personal cloud storage account by an employee. Which control is designed for this?", "c": ["DDoS protection", "DLP", "A WAF", "An IDS"], "a": 1, "e": "DLP is specifically designed to detect and block unauthorized transmission of sensitive data, including uploads to unauthorized external destinations."}, {"obj": "1.8", "q": "An engineer notices a production VM has been running at 5% CPU utilization for months while costing the same as a much larger instance actually needed. What should be done?", "c": ["Leave it as-is since resizing risks downtime", "Rightsize the instance to a smaller, cheaper type matching actual utilization", "Convert it to a spot instance immediately with no further analysis", "Increase its size to use more of the reserved capacity"], "a": 1, "e": "Rightsizing adjusts the resource to match actual observed demand, eliminating wasted spend on oversized, underutilized capacity."}, {"obj": "4.5", "q": "Which term is most closely associated with this real-world importance: \"Operates at the subnet/network level, distinct from security group/instance-level rules.\"?", "c": ["Network ACL", "IAM Policies", "Endpoint Protection", "DLP"], "a": 0, "e": "Operates at the subnet/network level, distinct from security group/instance-level rules. This describes Network ACL (\"Access Control List — a set of rules controlling traffic in and out of a subnet at the network level.\")."}, {"obj": "1.3", "q": "What does the abbreviation \"CDN\" stand for?", "c": ["Content Delivery Network", "Infrastructure as a Service", "Access Control List", "Network Interface Card"], "a": 0, "e": "CDN stands for Content Delivery Network. A geographically distributed set of servers that cache content closer to end users."}, {"obj": "5.1", "q": "\"Branch Management\" is best defined as which of the following?", "c": ["Combining changes from different branches into one.", "Saving a snapshot of changes to the local version control history.", "Having other team members examine proposed code changes before they are merged.", "Organizing and maintaining separate lines of development (branches) within a repository."], "a": 3, "e": "Organizing and maintaining separate lines of development (branches) within a repository. Allows parallel work on features/fixes without disrupting the main codebase."}, {"obj": "4.4", "q": "Which concept is described by the phrase: \"Encrypting data as it moves across a network (e.g., via TLS).\"?", "c": ["Vendor-Specific Benchmark", "Secrets Management", "Data in Transit Encryption", "Patching (Security)"], "a": 2, "e": "\"Encrypting data as it moves across a network (e.g., via TLS).\" describes Data in Transit Encryption. Protects data from eavesdropping while crossing untrusted networks like the internet."}, {"obj": "1.4", "q": "Which concept is described by the phrase: \"Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk.\"?", "c": ["Block Storage", "Hot Storage Tier", "Archive Storage Tier", "File Storage"], "a": 0, "e": "\"Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk.\" describes Block Storage. Used for OS disks and databases that need low-latency, structured access to storage."}, {"obj": "6.2", "q": "Which of the following is the correct expansion of \"DHCP\"?", "c": ["Dynamic Host Configuration Protocol", "Network Time Protocol", "Transmission Control Protocol", "Remote Desktop Protocol"], "a": 0, "e": "DHCP stands for Dynamic Host Configuration Protocol. Automatically assigns IP addressing information to hosts on a network."}, {"obj": "2.5", "q": "\"Compliance Requirements\" is best defined as which of the following?", "c": ["The bandwidth, latency, and connectivity needs of a workload.", "Legal or regulatory obligations a workload's data and processing must meet.", "The capacity, performance, and durability needs a workload has for its data.", "The processing power (CPU, RAM) needed to run a workload effectively."], "a": 1, "e": "Legal or regulatory obligations a workload's data and processing must meet. Can restrict which regions, providers, or configurations are acceptable for a given workload."}, {"obj": "4.4", "q": "Select the most accurate description of \"Container File Access Permissions\":", "c": ["Controls governing which files and directories a container process can read or write.", "Hardening guidance published by a specific cloud provider or software vendor for their own product.", "A set of vendor-neutral, consensus-based configuration hardening guidelines.", "A container granted elevated access to the host system's resources."], "a": 0, "e": "Controls governing which files and directories a container process can read or write. Misconfigured permissions inside a container can let an attacker access or modify data they shouldn't."}, {"obj": "3.1", "q": "An engineer wants to follow one specific customer request as it passes through six different microservices to pinpoint where a 3-second delay is introduced. What observability technique is needed?", "c": ["Log retention configuration", "Distributed tracing", "Alert triage", "Monitoring metrics dashboards alone"], "a": 1, "e": "Tracing follows a single request across multiple services, which is essential for pinpointing exactly where latency is introduced in a distributed system."}, {"obj": "1.3", "q": "\"Transit Gateway\" is best defined as which of the following?", "c": ["Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management.", "A hub service that connects many VPCs and on-premises networks through a single point.", "A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute).", "Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network."], "a": 1, "e": "A hub service that connects many VPCs and on-premises networks through a single point. Simplifies large-scale network architectures compared to a full mesh of individual peering connections."}, {"obj": "6.2", "q": "A colleague says: \"Traffic destined for that path is silently dropped, a common and often overlooked cloud networking issue.\" Which concept are they describing?", "c": ["Network Overlap", "Missing Route", "Access vs. Trunk Ports", "DNS (Troubleshooting)"], "a": 1, "e": "Traffic destined for that path is silently dropped, a common and often overlooked cloud networking issue. This describes Missing Route (\"A required network path that has not been defined in a route table.\")."}, {"obj": "3.3", "q": "Which statement accurately describes \"Full Backup\"?", "c": ["A complete copy of all selected data.", "Restoring a large set of data all at once.", "Restoring individual files or specific data items rather than an entire dataset.", "The defined frequency and timing of backup jobs."], "a": 0, "e": "A complete copy of all selected data. Forms the baseline that incremental and differential backups build on."}, {"obj": "4.6", "q": "Why does this matter on the exam and in practice? \"Represents both wasted cost and an unpatched, unmonitored attack surface.\" — which term does this explain?", "c": ["Zombie Instance", "Cryptojacking", "Phishing", "Vulnerability Exploitation — Outdated Software"], "a": 0, "e": "Represents both wasted cost and an unpatched, unmonitored attack surface. This describes Zombie Instance (\"A cloud instance that is running but forgotten, unmonitored, or unmanaged.\")."}, {"obj": "6.1", "q": "An administrator explains the importance of a concept: \"Both undersizing (poor performance) and oversizing (wasted cost) are common sizing mistakes.\" What concept is this?", "c": ["Sizing Issues", "Service Quota", "API Throttling", "Regional Service Availability"], "a": 0, "e": "Both undersizing (poor performance) and oversizing (wasted cost) are common sizing mistakes. This describes Sizing Issues (\"A deployment failure or performance problem caused by choosing an inappropriately sized resource.\")."}, {"obj": "4.4", "q": "Why does this matter on the exam and in practice? \"Misconfigured object storage permissions are a very common real-world cause of public data exposure.\" — which term does this explain?", "c": ["Privileged Container", "Vendor-Specific Benchmark", "Unprivileged Container", "Object Storage Security"], "a": 3, "e": "Misconfigured object storage permissions are a very common real-world cause of public data exposure. This describes Object Storage Security (\"Access controls and encryption settings applied to object storage buckets/containers.\")."}, {"obj": "5.2", "q": "An administrator explains the importance of a concept: \"Documents and enforces a consistent, repeatable delivery process.\" What concept is this?", "c": ["Container Image Artifact", "Code Integration", "Private Repository", "CI/CD Workflow"], "a": 3, "e": "Documents and enforces a consistent, repeatable delivery process. This describes CI/CD Workflow (\"The defined sequence of automated stages a change passes through from commit to deployment.\")."}, {"obj": "6.3", "q": "Which term best matches this description: \"Access to a system or data by someone without proper permission.\"?", "c": ["Leaked Credentials", "Software Vulnerability Issues", "Unauthorized Access", "Cipher Suite Deprecation"], "a": 2, "e": "\"Access to a system or data by someone without proper permission.\" describes Unauthorized Access. The core security incident type that access controls, logging, and monitoring are designed to catch."}, {"obj": "3.2", "q": "How would you most accurately define \"Scheduled Scaling\"?", "c": ["Adding more instances of a resource to handle increased load (scale out).", "Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%).", "Increasing the resources (CPU/RAM) of an existing instance (scale up).", "Scaling resources up or down at predefined times based on known usage patterns."], "a": 3, "e": "Scaling resources up or down at predefined times based on known usage patterns. Ideal for predictable daily/weekly demand cycles, like scaling up before business hours."}, {"obj": "2.3", "q": "Why does this matter on the exam and in practice? \"A middle ground between a straight lift-and-shift and a full application redesign.\" — which term does this explain?", "c": ["Refactor", "Vendor Lock-In", "Replatform", "Cloud-to-On-Premises Migration"], "a": 2, "e": "A middle ground between a straight lift-and-shift and a full application redesign. This describes Replatform (\"A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture.\")."}, {"obj": "4.1", "q": "Which term is most closely associated with this real-world importance: \"The step that actually reduces risk — identification without remediation provides no real protection.\"?", "c": ["Vulnerability Assessment", "CVE", "Vulnerability Identification", "Remediation"], "a": 3, "e": "The step that actually reduces risk — identification without remediation provides no real protection. This describes Remediation (\"Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability.\")."}, {"obj": "2.5", "q": "\"Compute Requirements\" is best defined as which of the following?", "c": ["The bandwidth, latency, and connectivity needs of a workload.", "The processing power (CPU, RAM) needed to run a workload effectively.", "The uptime and resiliency expectations for a workload.", "The capacity, performance, and durability needs a workload has for its data."], "a": 1, "e": "The processing power (CPU, RAM) needed to run a workload effectively. Determines the instance size and type selected during provisioning."}, {"obj": "3.3", "q": "Which of the following terms fits this definition: \"Backs up only data changed since the last backup of any type.\"?", "c": ["Parallel Recovery", "Full Backup", "Granular Recovery", "Incremental Backup"], "a": 3, "e": "\"Backs up only data changed since the last backup of any type.\" describes Incremental Backup. Fastest to perform, but restoring requires the full chain of backups applied in order."}, {"obj": "1.4", "q": "A description reads: \"The lowest-cost storage tier, designed for rarely accessed data with the slowest retrieval times (sometimes hours).\" Which term does this describe?", "c": ["Hot Storage Tier", "Archive Storage Tier", "HDD", "Warm Storage Tier"], "a": 1, "e": "\"The lowest-cost storage tier, designed for rarely accessed data with the slowest retrieval times (sometimes hours).\" describes Archive Storage Tier. Ideal for long-term retention data that must be kept for compliance but is almost never read."}, {"obj": "5.3", "q": "Which of the following terms fits this definition: \"A design where components communicate by producing and reacting to events rather than direct calls.\"?", "c": ["GraphQL", "SOAP", "Event-Driven Architecture", "Web Sockets"], "a": 2, "e": "\"A design where components communicate by producing and reacting to events rather than direct calls.\" describes Event-Driven Architecture. Enables loose coupling and scalability, common in cloud-native and microservices designs."}, {"obj": "6.3", "q": "How would you most accurately define \"Privilege Escalation (Troubleshooting)\"?", "c": ["An identity gaining higher access than originally granted, often through a flaw or misconfiguration.", "Access to a system or data by someone without proper permission.", "Software installed or running without proper approval, increasing risk and potentially breaching policy.", "Problems arising from unpatched or improperly configured software containing known weaknesses."], "a": 0, "e": "An identity gaining higher access than originally granted, often through a flaw or misconfiguration. A critical security troubleshooting concern after any suspected compromise of a low-privilege account."}, {"obj": "2.5", "q": "Which combination of requirements would most directly determine whether a workload should be provisioned with a dedicated connection to an on-premises datacenter?", "c": ["Compute and storage requirements only", "Network requirements (bandwidth/latency) and possibly compliance requirements", "Availability requirements alone", "None of these are relevant to connection type"], "a": 1, "e": "Network requirements (needed bandwidth and latency) combined with any compliance constraints on data transport are the primary drivers for choosing a dedicated connection."}, {"obj": "1.3", "q": "In cloud computing terminology, \"Route Table\" refers to which of the following?", "c": ["A set of rules that determines where network traffic is directed.", "A direct network connection between two VPCs that allows them to communicate as if on the same network.", "A manually configured network route that does not change dynamically.", "Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management."], "a": 0, "e": "A set of rules that determines where network traffic is directed. Every subnet in a VPC is associated with a route table controlling how its traffic flows."}, {"obj": "1.8", "q": "Which of the following best describes \"Resource Metering\"?", "c": ["A billing model where a customer pays for an entire physical host, regardless of utilization.", "Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice.", "Adjusting the size/type of provisioned resources to match actual workload demand.", "Tracking actual consumption of cloud resources for billing and capacity planning purposes."], "a": 3, "e": "Tracking actual consumption of cloud resources for billing and capacity planning purposes. Provides the raw usage data that billing and rightsizing decisions are based on."}, {"obj": "1.11", "q": "\"IoT Gateway\" is best defined as which of the following?", "c": ["Lightweight protocols (like MQTT or CoAP) designed for constrained IoT devices and networks.", "A device that aggregates and relays data from multiple IoT sensors to the cloud.", "Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case.", "AI models that create new content (text, images, code) based on learned patterns."], "a": 1, "e": "A device that aggregates and relays data from multiple IoT sensors to the cloud. Reduces the number of direct cloud connections needed and can perform local pre-processing."}, {"obj": "3.1", "q": "A company configures its logging system to automatically archive logs older than 90 days and delete them after 2 years to balance compliance needs against storage cost. What is being configured?", "c": ["Log aggregation", "Log retention policy", "Alert triage", "Tracing configuration"], "a": 1, "e": "A log retention policy defines how long log data is kept before being archived or deleted, balancing storage cost against compliance and investigative needs."}, {"obj": "4.5", "q": "A company deploys a service specifically designed to filter and monitor HTTP traffic to a public-facing web application, blocking SQL injection attempts. What should be deployed?", "c": ["A network ACL", "A WAF", "An IDS", "A network security group only"], "a": 1, "e": "A WAF is designed specifically to filter application-layer (HTTP) traffic, catching attacks like SQL injection that a standard firewall would miss."}, {"obj": "4.3", "q": "Which term best matches this description: \"An authorization framework that lets an application access resources on a user's behalf without sharing their password.\"?", "c": ["OAuth 2.0", "Group-Based Access Control", "Web Portal", "SDK"], "a": 0, "e": "\"An authorization framework that lets an application access resources on a user's behalf without sharing their password.\" describes OAuth 2.0. The standard mechanism behind \"log in with...\" and delegated API access scenarios."}, {"obj": "1.7", "q": "Select the most accurate description of \"VM Network\":", "c": ["Grouping multiple hypervisor hosts together to share resources and enable failover/migration.", "Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction.", "The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network.", "A virtual network built on top of physical network infrastructure, common in virtualization and containers."], "a": 2, "e": "The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network. Determines how a VM communicates with other VMs, the host, and external networks."}, {"obj": "4.5", "q": "A company deploys a control specifically designed to filter and monitor HTTP traffic to its public-facing web application, blocking SQL injection and cross-site scripting attempts. What should be deployed?", "c": ["A network ACL", "A WAF", "An IPS at the network layer only", "A network security group with basic port rules"], "a": 1, "e": "A WAF is specifically designed to filter application-layer (HTTP) traffic, catching attacks like SQL injection that a standard network-layer firewall would miss."}, {"obj": "1.11", "q": "Why does this matter on the exam and in practice? \"Used to digitize and search paper documents or extract data from images automatically.\" — which term does this explain?", "c": ["IoT Sensor", "Text Recognition", "Voice-to-Text", "Machine Learning"], "a": 1, "e": "Used to digitize and search paper documents or extract data from images automatically. This describes Text Recognition (\"AI technology that extracts text from images or scanned documents (OCR).\")."}, {"obj": "6.2", "q": "A colleague says: \"Misconfiguring one as the other is a common cause of VLAN connectivity problems.\" Which concept are they describing?", "c": ["DNS (Troubleshooting)", "Access vs. Trunk Ports", "HTTP Status Codes", "NAT (Troubleshooting)"], "a": 1, "e": "Misconfiguring one as the other is a common cause of VLAN connectivity problems. This describes Access vs. Trunk Ports (\"The distinction between a switch port carrying a single VLAN (access) versus multiple VLANs (trunk).\")."}, {"obj": "1.10", "q": "An application transferring large video files to storage is limited by how much data can move per second, even though IOPS appear healthy. What metric should be investigated?", "c": ["Storage throughput", "Network latency only", "CPU utilization", "IOPS"], "a": 0, "e": "Storage throughput measures the rate of data transfer (MB/s or GB/s), which is the relevant bottleneck for large sequential transfers like video files, distinct from IOPS."}, {"obj": "4.6", "q": "Why does this matter on the exam and in practice? \"Highlights that technical controls alone can't fully prevent security incidents caused by human mistakes.\" — which term does this explain?", "c": ["Phishing", "Deviation from Baseline", "DDoS", "Vulnerability Exploitation — Human Error"], "a": 3, "e": "Highlights that technical controls alone can't fully prevent security incidents caused by human mistakes. This describes Vulnerability Exploitation — Human Error (\"An attack that succeeds due to a mistake made by an authorized user (misconfiguration, mishandling credentials, etc.).\")."}, {"obj": "1.7", "q": "How would you most accurately define \"NAS (Virtualization Context)\"?", "c": ["Storage physically attached to a single hypervisor host.", "Grouping multiple hypervisor hosts together to share resources and enable failover/migration.", "Storage Area Network — shared block storage accessible by multiple hypervisor hosts.", "Network Attached Storage — shared file-level storage accessible by multiple hosts."], "a": 3, "e": "Network Attached Storage — shared file-level storage accessible by multiple hosts. Commonly used for storing VM templates, ISOs, and shared datastores."}, {"obj": "1.11", "q": "Which concept is described by the phrase: \"AI technology that converts written text into spoken audio (speech synthesis).\"?", "c": ["Text-to-Voice", "Text Recognition", "Machine Learning", "IoT Sensor"], "a": 0, "e": "\"AI technology that converts written text into spoken audio (speech synthesis).\" describes Text-to-Voice. Used for voice assistants, accessibility tools, and automated phone systems."}, {"obj": "5.4", "q": "A team needs to automatically deploy, scale, and heal dozens of containerized microservices across a cluster of nodes. Which tool is purpose-built for this?", "c": ["Docker", "Kubernetes", "Git", "Jenkins"], "a": 1, "e": "Kubernetes is the de facto standard for orchestrating containerized applications at scale, handling deployment, scaling, and self-healing."}, {"obj": "5.1", "q": "Which of the following best describes \"Version Management\"?", "c": ["Having other team members examine proposed code changes before they are merged.", "Organizing and maintaining separate lines of development (branches) within a repository.", "Tracking and organizing different versions of code or configuration over time.", "Uploading local code changes to a remote/shared repository."], "a": 2, "e": "Tracking and organizing different versions of code or configuration over time. Provides the history needed to understand what changed and to roll back if necessary."}, {"obj": "1.6", "q": "Which of the following correctly distinguishes ephemeral storage from a persistent volume in a containerized environment?", "c": ["Ephemeral storage survives container restarts; persistent volumes do not", "Ephemeral storage is lost when the container stops; persistent volumes survive beyond the container's lifecycle", "They are functionally identical", "Persistent volumes can only be used for container images"], "a": 1, "e": "Ephemeral storage is temporary and tied to the container's lifecycle, while persistent volumes are specifically designed to survive beyond an individual container's life."}, {"obj": "2.3", "q": "Which term is most closely associated with this real-world importance: \"The fastest migration approach but does not take advantage of cloud-native features.\"?", "c": ["Rehost", "Retire", "Replatform", "Refactor"], "a": 0, "e": "The fastest migration approach but does not take advantage of cloud-native features. This describes Rehost (\"A migration strategy that moves an application to the cloud with minimal changes, also called lift and shift.\")."}, {"obj": "1.4", "q": "Why does this matter on the exam and in practice? \"Suitable for older backups or compliance data that is rarely, but occasionally, needed.\" — which term does this explain?", "c": ["Cold Storage Tier", "Object Storage", "File Storage", "Hot Storage Tier"], "a": 0, "e": "Suitable for older backups or compliance data that is rarely, but occasionally, needed. This describes Cold Storage Tier (\"A storage tier for infrequently accessed data, offering lower cost with slower retrieval.\")."}, {"obj": "1.5", "q": "A cloud-native application design avoids a single service being a critical dependency for every other service. What principle does this reflect?", "c": ["Tight coupling for reliability", "Loose coupling to reduce cascading failure risk", "Centralizing all logic in one monolith for simplicity", "Avoiding all forms of service communication"], "a": 1, "e": "Loose coupling reduces the risk that a failure in one service cascades and takes down unrelated services that depend on it too tightly."}, {"obj": "6.1", "q": "A colleague says: \"Still requires prompt attention but may allow more measured troubleshooting than a full outage.\" Which concept are they describing?", "c": ["Deprecation of Functionality", "Partial Outage", "Service Quota", "Full Outage"], "a": 1, "e": "Still requires prompt attention but may allow more measured troubleshooting than a full outage. This describes Partial Outage (\"A degradation where some, but not all, functionality or users are affected.\")."}, {"obj": "5.2", "q": "Which of the following best describes \"CI/CD Security\"?", "c": ["Merging code changes from multiple contributors into a shared, continuously tested codebase.", "A simple, unstructured file (like a config or script) produced or consumed by a pipeline.", "A code or artifact repository accessible to anyone.", "Incorporating security scanning and checks into the automated pipeline."], "a": 3, "e": "Incorporating security scanning and checks into the automated pipeline. Shifts security left, catching vulnerabilities earlier and cheaper than after deployment."}, {"obj": "1.8", "q": "Given the description \"Tracking actual consumption of cloud resources for billing and capacity planning purposes.\", which term is being defined?", "c": ["Reserved Resources", "Pay-As-You-Go", "Spot Instance", "Resource Metering"], "a": 3, "e": "\"Tracking actual consumption of cloud resources for billing and capacity planning purposes.\" describes Resource Metering. Provides the raw usage data that billing and rightsizing decisions are based on."}, {"obj": "3.1", "q": "Why does this matter on the exam and in practice? \"Critical for pinpointing where latency or errors occur across microservices.\" — which term does this explain?", "c": ["Log Aggregation", "Log Retention", "Log Collection", "Tracing"], "a": 3, "e": "Critical for pinpointing where latency or errors occur across microservices. This describes Tracing (\"Following a single request as it moves through multiple services in a distributed system.\")."}, {"obj": "1.6", "q": "Given the description \"A single container running in isolation without orchestration.\", which term is being defined?", "c": ["Stand-Alone Container", "Port Mapping", "Workload Orchestration", "Image Registry"], "a": 0, "e": "\"A single container running in isolation without orchestration.\" describes Stand-Alone Container. Simple to run for development/testing but lacks automated scaling, healing, or scheduling."}, {"obj": "5.4", "q": "Which of the following best describes \"Git\"?", "c": ["A distributed version control system used to track changes in source code.", "An open-source platform for automating deployment, scaling, and management of containerized applications.", "A platform for building, running, and managing containers.", "A widely used open-source automation server for building CI/CD pipelines."], "a": 0, "e": "A distributed version control system used to track changes in source code. The de facto standard version control system underlying most modern DevOps workflows."}, {"obj": "3.2", "q": "An administrator explains the importance of a concept: \"Useful for planned events or when automated triggers aren't yet configured.\" What concept is this?", "c": ["Manual Scaling", "Horizontal Scaling", "Scheduled Scaling", "Vertical Scaling"], "a": 0, "e": "Useful for planned events or when automated triggers aren't yet configured. This describes Manual Scaling (\"An administrator explicitly changing resource capacity rather than relying on automation.\")."}, {"obj": "3.3", "q": "Which term is most closely associated with this real-world importance: \"Protects against a disaster affecting the primary backup location.\"?", "c": ["Differential Backup", "Backup Encryption", "Backup Replication", "Backup Integrity Testing"], "a": 2, "e": "Protects against a disaster affecting the primary backup location. This describes Backup Replication (\"Copying backup data to another location (often off-site or another region).\")."}, {"obj": "4.6", "q": "Why does this matter on the exam and in practice? \"Makes immutable, offline backups especially critical, since online backups can also be encrypted.\" — which term does this explain?", "c": ["Cryptojacking", "Vulnerability Exploitation — Human Error", "Unnecessary Open Ports", "Ransomware"], "a": 3, "e": "Makes immutable, offline backups especially critical, since online backups can also be encrypted. This describes Ransomware (\"Malware that encrypts a victim's data and demands payment for the decryption key.\")."}, {"obj": "1.5", "q": "Why does this matter on the exam and in practice? \"Essential in dynamic cloud-native environments where service instances and IP addresses change constantly.\" — which term does this explain?", "c": ["Service Discovery", "Loosely Coupled Architecture", "Microservices", "Fan-Out"], "a": 0, "e": "Essential in dynamic cloud-native environments where service instances and IP addresses change constantly. This describes Service Discovery (\"A mechanism that lets services dynamically find the network location of other services.\")."}, {"obj": "1.8", "q": "Which of the following terms fits this definition: \"Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice.\"?", "c": ["Reserved Resources", "Tagging", "Rightsizing", "Spot Instance"], "a": 3, "e": "\"Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice.\" describes Spot Instance. Ideal for fault-tolerant, interruptible workloads like batch processing, but not suitable for critical always-on services."}, {"obj": "6.3", "q": "Legacy clients suddenly fail to establish a TLS connection to a cloud service after the provider disabled older, insecure cipher suites for security reasons. What is the cause?", "c": ["Cipher suite deprecation", "Leaked credentials", "Privilege escalation", "Unauthorized software"], "a": 0, "e": "When a provider disables outdated cipher suites for security, legacy clients relying on them will fail to connect until they are updated to support current ciphers."}, {"obj": "2.3", "q": "Which of the following best describes \"Cloud-to-Cloud Migration\"?", "c": ["Moving workloads from local infrastructure into a cloud environment.", "Moving workloads from one cloud provider or region to another.", "A migration strategy that rewrites portions of an application to better fit cloud-native patterns.", "Difficulty moving away from a cloud provider due to reliance on proprietary services or formats."], "a": 1, "e": "Moving workloads from one cloud provider or region to another. Often driven by cost optimization, feature needs, or avoiding vendor lock-in."}, {"obj": "2.3", "q": "Which term is most closely associated with this real-world importance: \"Takes the most effort but unlocks the greatest long-term benefits like scalability and cost efficiency.\"?", "c": ["Re-Architect", "Cloud-to-Cloud Migration", "Retire", "Replatform"], "a": 0, "e": "Takes the most effort but unlocks the greatest long-term benefits like scalability and cost efficiency. This describes Re-Architect (\"A migration strategy that substantially redesigns an application to be cloud-native.\")."}, {"obj": "1.9", "q": "An administrator explains the importance of a concept: \"Best suited for structured data requiring strong consistency and complex queries/joins.\" What concept is this?", "c": ["Relational Database", "Non-Relational Database", "Provider-Managed Database", "Self-Managed Database"], "a": 0, "e": "Best suited for structured data requiring strong consistency and complex queries/joins. This describes Relational Database (\"A database that organizes data into structured tables with defined relationships (SQL).\")."}, {"obj": "4.6", "q": "CPU usage across several cloud instances spikes dramatically with no corresponding increase in legitimate workload, and the monthly cloud bill rises unexpectedly. What should be suspected?", "c": ["A DDoS attack", "Cryptojacking", "A DNS misconfiguration", "A licensing renewal"], "a": 1, "e": "Cryptojacking abuses compute resources to mine cryptocurrency, often surfacing as unexplained high CPU usage paired with increased cloud costs."}, {"obj": "4.6", "q": "Select the most accurate description of \"Ransomware\":", "c": ["A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email.", "A cloud instance that is running but forgotten, unmonitored, or unmanaged.", "An attack that succeeds because a system was running software with a known, unpatched vulnerability.", "Malware that encrypts a victim's data and demands payment for the decryption key."], "a": 3, "e": "Malware that encrypts a victim's data and demands payment for the decryption key. Makes immutable, offline backups especially critical, since online backups can also be encrypted."}, {"obj": "4.4", "q": "\"API Security\" is best defined as which of the following?", "c": ["Practices and controls that protect APIs from abuse, unauthorized access, and attack.", "A container granted elevated access to the host system's resources.", "A container running with restricted access, isolated from the host's sensitive resources.", "Access controls and encryption applied to shared file storage systems."], "a": 0, "e": "Practices and controls that protect APIs from abuse, unauthorized access, and attack. APIs are a primary attack surface in cloud-native applications and require dedicated protective controls."}, {"obj": "4.1", "q": "The acronym \"CWE\" stands for:", "c": ["Software-defined Network", "Recovery Time Objective", "Center for Internet Security", "Common Weakness Enumeration"], "a": 3, "e": "CWE stands for Common Weakness Enumeration. A community list of common software and hardware weakness types."}, {"obj": "1.7", "q": "A company clusters three hypervisor hosts and configures automatic VM failover if any single host goes down. What virtualization capability does this rely on?", "c": ["Stand-alone virtualization", "Clustering", "Hardware pass-through only", "Ephemeral storage"], "a": 1, "e": "Clustering enables automatic failover and resource sharing across hosts, which is exactly what allows VMs to recover if a single host fails."}, {"obj": "1.4", "q": "Which of the following terms fits this definition: \"Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk.\"?", "c": ["Block Storage", "File Storage", "Object Storage", "SSD"], "a": 0, "e": "\"Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk.\" describes Block Storage. Used for OS disks and databases that need low-latency, structured access to storage."}, {"obj": "6.3", "q": "A low-privilege service account is found to have performed administrative actions it should never have been authorized to do. What does this indicate?", "c": ["Proper least-privilege enforcement", "Privilege escalation", "Federation working correctly", "Zero Trust enforcement"], "a": 1, "e": "This is a textbook example of privilege escalation, where an entity gains access beyond what was originally granted."}, {"obj": "2.5", "q": "A company provisioning a new analytics workload must decide on instance type, storage tier, network configuration, and region, all before deployment. What is the primary purpose of assessing these requirements upfront?", "c": ["To make the provisioning process take longer for no benefit", "To ensure the provisioned resources actually match the workload's real needs for performance, cost, availability, and compliance", "To guarantee the lowest possible price regardless of performance", "To avoid ever having to change the configuration again"], "a": 1, "e": "Assessing requirements upfront ensures the provisioned resources genuinely match the workload's actual needs across performance, cost, availability, and compliance dimensions."}, {"obj": "6.2", "q": "Which term best matches this description: \"Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500).\"?", "c": ["NTP (Troubleshooting)", "Access vs. Trunk Ports", "HTTP Status Codes", "VLAN Misconfigured Tags"], "a": 2, "e": "\"Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500).\" describes HTTP Status Codes. Provide the first clue about whether a problem is client-side, server-side, or related to routing/access."}, {"obj": "3.3", "q": "A colleague says: \"Fastest to perform, but restoring requires the full chain of backups applied in order.\" Which concept are they describing?", "c": ["Parallel Recovery", "Incremental Backup", "In-Place Recovery", "Granular Recovery"], "a": 1, "e": "Fastest to perform, but restoring requires the full chain of backups applied in order. This describes Incremental Backup (\"Backs up only data changed since the last backup of any type.\")."}, {"obj": "2.4", "q": "Which concept is described by the phrase: \"Yet Another Markup Language — a human-readable data format widely used for IaC and configuration files.\"?", "c": ["Drift Detection", "YAML", "Configuration as Code", "IaC Testing"], "a": 1, "e": "\"Yet Another Markup Language — a human-readable data format widely used for IaC and configuration files.\" describes YAML. The preferred format for tools like Kubernetes manifests and many CI/CD pipeline definitions."}, {"obj": "4.4", "q": "Which term best matches this description: \"A security model that assumes no user or device should be trusted by default, even inside the network perimeter.\"?", "c": ["API Security", "Patching (Security)", "Zero Trust", "Object Storage Security"], "a": 2, "e": "\"A security model that assumes no user or device should be trusted by default, even inside the network perimeter.\" describes Zero Trust. Requires continuous verification of identity and context for every access request, not just at the network edge."}, {"obj": "2.3", "q": "Which term is most closely associated with this real-world importance: \"Similar to re-architecting but often more incremental, improving specific components over time.\"?", "c": ["Replatform", "Refactor", "Retain", "Cloud-to-On-Premises Migration"], "a": 1, "e": "Similar to re-architecting but often more incremental, improving specific components over time. This describes Refactor (\"A migration strategy that rewrites portions of an application to better fit cloud-native patterns.\")."}, {"obj": "5.4", "q": "Given the description \"A platform for building, running, and managing containers.\", which term is being defined?", "c": ["Docker", "Terraform", "Git", "GitHub Actions"], "a": 0, "e": "\"A platform for building, running, and managing containers.\" describes Docker. The most widely used container runtime and image format in modern DevOps workflows."}, {"obj": "6.2", "q": "A newly created subnet has no path defined to reach a peered VPC's address range, and traffic destined there is silently dropped. What is the cause?", "c": ["A missing route", "IP scope exhaustion", "Cipher suite deprecation", "An HTTP status code mismatch"], "a": 0, "e": "A missing route means no path has been defined for that destination in the route table, so traffic is silently dropped."}, {"obj": "4.5", "q": "Which statement accurately describes \"Network ACL\"?", "c": ["Rules that define what actions a given identity is allowed or denied to perform on cloud resources.", "Access Control List — a set of rules controlling traffic in and out of a subnet at the network level.", "Security software (antivirus, EDR) installed directly on servers, VMs, or devices.", "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data."], "a": 1, "e": "Access Control List — a set of rules controlling traffic in and out of a subnet at the network level. Operates at the subnet/network level, distinct from security group/instance-level rules."}, {"obj": "3.2", "q": "A company wants its infrastructure to automatically shrink back down after a traffic spike subsides, to avoid paying for unused capacity. What scaling capability supports both scaling out and back in?", "c": ["A one-way scaling policy that only ever adds instances", "Autoscaling policies that scale both out and in based on demand", "Manual scaling performed only once", "Vertical scaling that cannot be reversed"], "a": 1, "e": "Well-designed autoscaling policies scale capacity both up and down with demand, avoiding the cost of retaining unused capacity after a spike subsides."}, {"obj": "1.9", "q": "A company installs and personally manages patching, backups, and tuning for a database engine running on their own VM. What type of database deployment is this?", "c": ["A provider-managed database service", "A self-managed database", "A serverless database function", "An object storage bucket"], "a": 1, "e": "A self-managed database is one the customer installs, configures, and maintains themselves, taking on full operational responsibility."}, {"obj": "1.9", "q": "Which of the following is the correct expansion of \"CRUD\"?", "c": ["Random Access Memory", "Redundant Array of Independent Disks", "Software as a Service", "Create, Read, Update, Delete"], "a": 3, "e": "CRUD stands for Create, Read, Update, Delete. The four basic operations performed on stored data."}, {"obj": "3.3", "q": "A company restores a failed production server directly back onto the same original infrastructure, since it's still available and intact after the issue was resolved. What recovery approach is this?", "c": ["Parallel recovery", "In-place recovery", "Bulk recovery only", "Granular recovery only"], "a": 1, "e": "In-place recovery restores data directly onto the original system/location, the simplest approach when the original infrastructure remains available and intact."}, {"obj": "6.1", "q": "How would you most accurately define \"Regional Service Availability\"?", "c": ["The fact that not all cloud services are available in every region.", "A deployment failing because the deploying identity lacks sufficient rights.", "Incorrectly assigned CPU, memory, or storage limits for a workload.", "A degradation where some, but not all, functionality or users are affected."], "a": 0, "e": "The fact that not all cloud services are available in every region. A deployment can fail simply because a required service isn't offered in the chosen region."}, {"obj": "2.1", "q": "Which of the following terms fits this definition: \"A deployment model combining private/on-premises infrastructure with public cloud resources.\"?", "c": ["Community Cloud", "Private Cloud", "Public Cloud", "Hybrid Cloud"], "a": 3, "e": "\"A deployment model combining private/on-premises infrastructure with public cloud resources.\" describes Hybrid Cloud. Common for gradual migration, burst capacity, or workloads with data residency constraints."}, {"obj": "1.4", "q": "Which concept is described by the phrase: \"Hard Disk Drive — traditional magnetic spinning-platter storage.\"?", "c": ["Block Storage", "HDD", "Archive Storage Tier", "File Storage"], "a": 1, "e": "\"Hard Disk Drive — traditional magnetic spinning-platter storage.\" describes HDD. Offers lower cost per GB than SSD, suited to large, less performance-sensitive datasets."}, {"obj": "1.3", "q": "Given the description \"A set of rules that determines where network traffic is directed.\", which term is being defined?", "c": ["BGP", "Route Table", "Transit Gateway", "Dedicated Connection"], "a": 1, "e": "\"A set of rules that determines where network traffic is directed.\" describes Route Table. Every subnet in a VPC is associated with a route table controlling how its traffic flows."}, {"obj": "4.4", "q": "Why does this matter on the exam and in practice? \"One of the most fundamental and heavily tested security practices across all IT domains.\" — which term does this explain?", "c": ["Privileged Container", "Zero Trust", "Hardening", "Unprivileged Container"], "a": 2, "e": "One of the most fundamental and heavily tested security practices across all IT domains. This describes Hardening (\"Reducing a system's attack surface by disabling unnecessary services, closing unused ports, and applying secure configurations.\")."}, {"obj": "2.2", "q": "\"In-Place Deployment\" is best defined as which of the following?", "c": ["Gradually rolling out a change to a small subset of users or servers before a full rollout.", "Updating instances incrementally, a few at a time, rather than all at once.", "A strategy running two identical environments (blue and green), switching traffic to the new version once verified.", "Updating an existing server or instance directly rather than deploying an entirely new one."], "a": 3, "e": "Updating an existing server or instance directly rather than deploying an entirely new one. Simpler but riskier than blue-green since there is no separate environment to instantly roll back to."}, {"obj": "1.8", "q": "A colleague says: \"Enables cost allocation, automation, and organization of resources by project, owner, or environment.\" Which concept are they describing?", "c": ["Rightsizing", "Dedicated Host Billing", "Spot Instance", "Tagging"], "a": 3, "e": "Enables cost allocation, automation, and organization of resources by project, owner, or environment. This describes Tagging (\"Attaching key-value metadata labels to cloud resources.\")."}, {"obj": "2.3", "q": "Select the most accurate description of \"Cloud-to-On-Premises Migration\":", "c": ["A migration strategy that substantially redesigns an application to be cloud-native.", "Moving workloads out of the cloud back to local infrastructure.", "A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture.", "A migration strategy that decommissions an application no longer needed."], "a": 1, "e": "Moving workloads out of the cloud back to local infrastructure. Sometimes chosen for cost, compliance, or performance reasons after initial cloud adoption."}, {"obj": "4.2", "q": "In cloud computing terminology, \"PCI DSS\" refers to which of the following?", "c": ["Requirements or preferences about the physical location where data is stored or processed.", "An international standard specifying requirements for an information security management system.", "A data retention requirement specified in a contract with a customer or partner.", "Payment Card Industry Data Security Standard — security requirements for handling payment card data."], "a": 3, "e": "Payment Card Industry Data Security Standard — security requirements for handling payment card data. Any cloud workload that stores, processes, or transmits card data must meet these requirements."}, {"obj": "4.3", "q": "Which concept is described by the phrase: \"An access model where the resource owner decides who else can access it.\"?", "c": ["Directory-Based Authentication", "Discretionary Access Control", "Role-Based Access Control", "Token-Based Authentication"], "a": 1, "e": "\"An access model where the resource owner decides who else can access it.\" describes Discretionary Access Control. Flexible, but relies on individual owners consistently applying good judgment about access grants."}, {"obj": "3.3", "q": "How would you most accurately define \"In-Place Recovery\"?", "c": ["The defined frequency and timing of backup jobs.", "Restoring data directly onto the original system/location.", "Actually restoring backup data to confirm it can be used successfully.", "Restoring a large set of data all at once."], "a": 1, "e": "Restoring data directly onto the original system/location. The simplest recovery approach when the original infrastructure is still available and intact."}, {"obj": "6.2", "q": "Which of the following terms fits this definition: \"The distinction between a switch port carrying a single VLAN (access) versus multiple VLANs (trunk).\"?", "c": ["NTP (Troubleshooting)", "HTTP Status Codes", "Access vs. Trunk Ports", "DNS (Troubleshooting)"], "a": 2, "e": "\"The distinction between a switch port carrying a single VLAN (access) versus multiple VLANs (trunk).\" describes Access vs. Trunk Ports. Misconfiguring one as the other is a common cause of VLAN connectivity problems."}, {"obj": "2.1", "q": "Which statement accurately describes \"Private Cloud\"?", "c": ["Infrastructure shared by several organizations with common concerns such as compliance or security requirements.", "Infrastructure owned by a third-party provider and shared across many customers (multi-tenant).", "Infrastructure physically located and managed within the organization's own facilities.", "Infrastructure dedicated to a single organization, hosted on- or off-premises."], "a": 3, "e": "Infrastructure dedicated to a single organization, hosted on- or off-premises. Offers greater control and customization at higher cost than public cloud."}, {"obj": "1.4", "q": "The acronym \"SSD\" stands for:", "c": ["Advanced Encryption Standard", "Single Sign-On", "Infrastructure as Code", "Solid-state Drive"], "a": 3, "e": "SSD stands for Solid-state Drive. Flash-based storage offering faster performance and no moving parts compared to HDDs."}, {"obj": "6.3", "q": "Which concept is described by the phrase: \"Software installed or running without proper approval, increasing risk and potentially breaching policy.\"?", "c": ["Privilege Escalation (Troubleshooting)", "Software Vulnerability Issues", "Unauthorized Software", "Cipher Suite Deprecation"], "a": 2, "e": "\"Software installed or running without proper approval, increasing risk and potentially breaching policy.\" describes Unauthorized Software. Can introduce vulnerabilities, malware, or licensing violations into an otherwise controlled environment."}, {"obj": "5.1", "q": "Given the description \"Tracking and organizing different versions of code or configuration over time.\", which term is being defined?", "c": ["Code Review", "Branch Management", "Version Management", "Code Commit"], "a": 2, "e": "\"Tracking and organizing different versions of code or configuration over time.\" describes Version Management. Provides the history needed to understand what changed and to roll back if necessary."}, {"obj": "4.5", "q": "A description reads: \"Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data.\" Which term does this describe?", "c": ["DLP", "Network Security Group", "Network ACL", "IAM Policies"], "a": 0, "e": "\"Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data.\" describes DLP. Commonly blocks sensitive data like credit card numbers from leaving the network through channels like email."}, {"obj": "2.5", "q": "Which term is most closely associated with this real-world importance: \"Can restrict which regions, providers, or configurations are acceptable for a given workload.\"?", "c": ["Availability Requirements", "Storage Requirements", "Compliance Requirements", "Compute Requirements"], "a": 2, "e": "Can restrict which regions, providers, or configurations are acceptable for a given workload. This describes Compliance Requirements (\"Legal or regulatory obligations a workload's data and processing must meet.\")."}, {"obj": "1.7", "q": "Which term best matches this description: \"Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction.\"?", "c": ["SAN (Virtualization Context)", "Hardware Pass-Through", "Local Storage (Virtualization)", "Clustering"], "a": 1, "e": "\"Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction.\" describes Hardware Pass-Through. Used when a workload needs near-native performance from a specific device, like a GPU."}, {"obj": "2.2", "q": "An operations team updates ten web servers behind a load balancer two at a time, keeping the application available to users throughout the entire process. Which strategy is this?", "c": ["Blue-green deployment", "Rolling deployment", "Canary deployment", "In-place deployment"], "a": 1, "e": "Rolling deployment updates instances incrementally, a few at a time, keeping the application available throughout — though the full rollout takes longer than an all-at-once approach."}, {"obj": "4.4", "q": "Which of the following terms fits this definition: \"Hardening guidance published by a specific cloud provider or software vendor for their own product.\"?", "c": ["Hardening", "Vendor-Specific Benchmark", "Patching (Security)", "API Security"], "a": 1, "e": "\"Hardening guidance published by a specific cloud provider or software vendor for their own product.\" describes Vendor-Specific Benchmark. Complements general benchmarks with platform-specific configuration recommendations."}, {"obj": "1.9", "q": "A company migrates its self-managed MySQL database on a VM to a fully managed cloud database service. What is the most direct benefit they gain?", "c": ["Full control over the underlying hypervisor", "Reduced operational burden since the provider now handles patching, backups, and maintenance", "Guaranteed zero cost going forward", "Elimination of the need for any database at all"], "a": 1, "e": "Migrating to a managed database service shifts operational tasks like patching and backups to the provider, directly reducing the team's administrative workload."}, {"obj": "3.1", "q": "A team wants to detect a slow memory leak days before it causes an outage by observing a gradual upward trend in memory usage over time. What capability enables this early detection?", "c": ["Alert response documentation", "Monitoring metrics with trend analysis", "Log aggregation without any metrics", "Distributed tracing alone"], "a": 1, "e": "Monitoring metrics collected over time allow trend analysis (like a gradual memory increase) that can reveal developing problems before they cause an outage."}, {"obj": "1.1", "q": "A startup wants to focus entirely on writing application code and never wants to think about servers, operating systems, or scaling infrastructure, even during traffic spikes. Which service model best fits?", "c": ["IaaS", "PaaS", "FaaS", "On-premises"], "a": 2, "e": "FaaS (serverless) removes all server management and automatically scales with event volume, letting developers focus purely on code."}, {"obj": "4.1", "q": "Select the most accurate description of \"Scanning Scope\":", "c": ["The step of detecting known weaknesses in systems, typically via automated scanning.", "Evaluating identified vulnerabilities for severity, exploitability, and business impact.", "Defining which systems, networks, or applications a vulnerability scan will cover.", "Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities."], "a": 2, "e": "Defining which systems, networks, or applications a vulnerability scan will cover. Ensures the scan actually covers all in-scope assets rather than leaving blind spots."}, {"obj": "1.6", "q": "Which of the following terms fits this definition: \"Storage that survives beyond the lifecycle of an individual container.\"?", "c": ["Port Mapping", "Persistent Volume", "Workload Orchestration", "Ephemeral Storage"], "a": 1, "e": "\"Storage that survives beyond the lifecycle of an individual container.\" describes Persistent Volume. Needed for stateful container workloads like databases, since container filesystems are normally ephemeral."}, {"obj": "1.7", "q": "What does the abbreviation \"SAN\" stand for?", "c": ["Continuous Integration/Continuous Deployment", "Representational State Transfer", "Virtual Desktop Infrastructure", "Storage Area Network"], "a": 3, "e": "SAN stands for Storage Area Network. A dedicated network providing block-level storage access to servers."}, {"obj": "1.9", "q": "A colleague says: \"Better suited for unstructured/semi-structured data and workloads needing horizontal scalability.\" Which concept are they describing?", "c": ["Relational Database", "Provider-Managed Database", "Self-Managed Database", "Non-Relational Database"], "a": 3, "e": "Better suited for unstructured/semi-structured data and workloads needing horizontal scalability. This describes Non-Relational Database (\"A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs.\")."}, {"obj": "1.1", "q": "Which term is most closely associated with this real-world importance: \"Billing is based on execution time/invocations rather than reserved capacity, ideal for event-driven workloads.\"?", "c": ["SaaS", "Shared Responsibility Model", "PaaS", "FaaS"], "a": 3, "e": "Billing is based on execution time/invocations rather than reserved capacity, ideal for event-driven workloads. This describes FaaS (\"Function as a Service — lets code run in response to events without provisioning or managing any server (serverless).\")."}, {"obj": "2.3", "q": "During a migration assessment, a company decides an old internal reporting tool is redundant and will be shut down rather than migrated. What migration strategy is this?", "c": ["Retain", "Retire", "Replatform", "Refactor"], "a": 1, "e": "Retire decommissions an application no longer needed, reducing the overall scope and ongoing cost of the migration project."}, {"obj": "1.11", "q": "In cloud computing terminology, \"Machine Learning\" refers to which of the following?", "c": ["AI technology that identifies objects, scenes, or features within images or video.", "Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case.", "AI technology that converts written text into spoken audio (speech synthesis).", "AI technology that extracts text from images or scanned documents (OCR)."], "a": 1, "e": "Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case. Underpins many modern cloud AI services such as recommendation engines and fraud detection."}, {"obj": "2.1", "q": "Which term best matches this description: \"A deployment model combining private/on-premises infrastructure with public cloud resources.\"?", "c": ["Community Cloud", "Hybrid Cloud", "Private Cloud", "Public Cloud"], "a": 1, "e": "\"A deployment model combining private/on-premises infrastructure with public cloud resources.\" describes Hybrid Cloud. Common for gradual migration, burst capacity, or workloads with data residency constraints."}, {"obj": "1.4", "q": "Which of the following best describes \"Block Storage\"?", "c": ["Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk.", "Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB).", "A storage tier for infrequently accessed data, offering lower cost with slower retrieval.", "A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost."], "a": 0, "e": "Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk. Used for OS disks and databases that need low-latency, structured access to storage."}, {"obj": "1.2", "q": "A colleague says: \"A middle-ground between cost and recovery speed compared to hot and cold sites.\" Which concept are they describing?", "c": ["Cold Site", "RTO", "Warm Site", "Edge Computing"], "a": 2, "e": "A middle-ground between cost and recovery speed compared to hot and cold sites. This describes Warm Site (\"A partially equipped DR site that needs recent data restored before it can take over.\")."}, {"obj": "1.5", "q": "A retailer's inventory service publishes an event whenever stock changes, and any interested service can subscribe without the inventory service needing to know who is listening. What design concept does this best illustrate?", "c": ["Tight coupling", "Event-driven fan-out with loose coupling", "A monolithic architecture", "Manual service configuration"], "a": 1, "e": "Publishing events without needing to know the specific subscribers is a hallmark of loosely coupled, event-driven (fan-out) design."}, {"obj": "2.3", "q": "A colleague says: \"The fastest migration approach but does not take advantage of cloud-native features.\" Which concept are they describing?", "c": ["Retire", "Replatform", "On-Premises-to-Cloud Migration", "Rehost"], "a": 3, "e": "The fastest migration approach but does not take advantage of cloud-native features. This describes Rehost (\"A migration strategy that moves an application to the cloud with minimal changes, also called lift and shift.\")."}, {"obj": "1.6", "q": "How would you most accurately define \"Persistent Volume\"?", "c": ["A repository for storing and distributing container images (e.g., Docker Hub, a private registry).", "Automated management of container deployment, scaling, and healing (e.g., Kubernetes).", "A single container running in isolation without orchestration.", "Storage that survives beyond the lifecycle of an individual container."], "a": 3, "e": "Storage that survives beyond the lifecycle of an individual container. Needed for stateful container workloads like databases, since container filesystems are normally ephemeral."}, {"obj": "4.2", "q": "A company wants cloud-specific security best practices and frameworks tailored to cloud environments, beyond general-purpose security standards. Which organization's guidance would be most relevant?", "c": ["The Cloud Security Alliance (CSA)", "A generic local business bureau", "An unrelated national fire safety agency", "A generic customer service standard"], "a": 0, "e": "The Cloud Security Alliance publishes best practices and frameworks specifically for cloud security, complementing general-purpose standards that may not fully address cloud-specific concerns."}, {"obj": "5.3", "q": "Which of the following is a key advantage of GraphQL over a traditional fixed-response REST endpoint for a mobile app with limited bandwidth?", "c": ["GraphQL always requires more bandwidth than REST", "GraphQL lets the client request only the specific fields needed, reducing unnecessary data transfer", "GraphQL cannot be used over HTTP", "GraphQL eliminates the need for any backend server"], "a": 1, "e": "By letting clients specify exactly which fields they need, GraphQL can reduce unnecessary data transfer compared to a fixed REST response, valuable for bandwidth-constrained clients."}, {"obj": "4.2", "q": "The acronym \"SOC2\" stands for:", "c": ["Application Programming Interface", "Configuration as Code", "Network Interface Card", "System and Organization Controls 2"], "a": 3, "e": "SOC2 stands for System and Organization Controls 2. An audit framework evaluating a service provider's security and availability controls."}, {"obj": "2.1", "q": "A hospital must keep all patient records on infrastructure it fully owns due to strict regulatory concerns, with no public cloud involvement at all. Which deployment model fits?", "c": ["Public cloud", "On premises", "Hybrid cloud", "Community cloud"], "a": 1, "e": "On-premises infrastructure is physically located and fully managed within the organization's own facilities, giving maximum control needed for strict regulatory requirements."}, {"obj": "3.2", "q": "Which concept is described by the phrase: \"Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU).\"?", "c": ["Manual Scaling", "Vertical Scaling", "Triggered Scaling — Trending", "Scheduled Scaling"], "a": 2, "e": "\"Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU).\" describes Triggered Scaling — Trending. Reacts to gradual changes in demand rather than short spikes."}, {"obj": "5.2", "q": "A CI/CD pipeline automatically runs a suite of unit and integration tests against every proposed change before it can be merged. What CI/CD stage is this?", "c": ["Build", "CI/CD testing", "Code deployment", "Artifact publishing"], "a": 1, "e": "CI/CD testing automatically runs tests as part of the pipeline, catching regressions before code reaches production."}, {"obj": "1.1", "q": "Which of the following is the correct expansion of \"FaaS\"?", "c": ["Redundant Array of Independent Disks", "Intrusion Detection System", "Graphics Processing Unit", "Function as a Service"], "a": 3, "e": "FaaS stands for Function as a Service. A serverless model where code runs in response to events without managing servers."}, {"obj": "1.3", "q": "Which statement accurately describes \"Network Load Balancer\"?", "c": ["A device or service that filters network traffic based on defined rules.", "A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features.", "A direct network connection between two VPCs that allows them to communicate as if on the same network.", "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port."], "a": 3, "e": "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port. Provides extremely high throughput and low latency for use cases where Layer 7 inspection isn't needed."}, {"obj": "4.1", "q": "Which of the following best describes the relationship between vulnerability identification and vulnerability assessment?", "c": ["They are the same step performed twice", "Identification detects that a weakness exists; assessment evaluates its severity and impact to inform prioritization", "Assessment always happens before identification", "Assessment replaces the need for identification entirely"], "a": 1, "e": "Identification detects a weakness (often via scanning), while assessment then evaluates its severity and impact, and the two are distinct sequential steps."}, {"obj": "5.3", "q": "A colleague says: \"The most common style for modern web APIs due to its simplicity and statelessness.\" Which concept are they describing?", "c": ["RPC", "GraphQL", "REST", "SOAP"], "a": 2, "e": "The most common style for modern web APIs due to its simplicity and statelessness. This describes REST (\"Representational State Transfer — an architectural style for web services using standard HTTP methods.\")."}, {"obj": "4.3", "q": "\"Role-Based Access Control\" is best defined as which of the following?", "c": ["Granting permissions based on a user's assigned role rather than to each individual directly.", "Granting permissions to a group, which members inherit by being added to that group.", "An authorization framework that lets an application access resources on a user's behalf without sharing their password.", "Authentication using a temporary token issued after initial login, rather than resending credentials each time."], "a": 0, "e": "Granting permissions based on a user's assigned role rather than to each individual directly. Simplifies administration and enforces consistent access across users with the same job function."}, {"obj": "5.3", "q": "Which statement accurately describes \"Web Sockets\"?", "c": ["Simple Object Access Protocol — an XML-based messaging protocol for web services.", "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local.", "A protocol providing full-duplex, persistent communication channels over a single TCP connection.", "A query language for APIs that lets clients request exactly the data they need."], "a": 2, "e": "A protocol providing full-duplex, persistent communication channels over a single TCP connection. Enables real-time, bidirectional communication like chat apps or live dashboards, unlike typical request/response HTTP."}, {"obj": "1.3", "q": "A company wants to reduce load on its origin web servers and improve page load times for users located far from its primary region by caching static assets closer to users. What should be deployed?", "c": ["A VPC peering connection", "A CDN", "A transit gateway", "A static route"], "a": 1, "e": "A CDN caches content at edge locations geographically closer to users, reducing origin server load and improving load times for distant users."}, {"obj": "2.5", "q": "\"Availability Requirements\" is best defined as which of the following?", "c": ["The uptime and resiliency expectations for a workload.", "The bandwidth, latency, and connectivity needs of a workload.", "The capacity, performance, and durability needs a workload has for its data.", "The processing power (CPU, RAM) needed to run a workload effectively."], "a": 0, "e": "The uptime and resiliency expectations for a workload. Drives decisions like multi-AZ deployment, clustering, and failover design."}, {"obj": "5.2", "q": "Given the description \"Automatically building, testing, and deploying code changes with minimal manual intervention.\", which term is being defined?", "c": ["VM Image Artifact", "CI/CD Automation", "Public Repository", "Code Deployment"], "a": 1, "e": "\"Automatically building, testing, and deploying code changes with minimal manual intervention.\" describes CI/CD Automation. Reduces human error and speeds up the delivery of software changes."}, {"obj": "1.7", "q": "Which of the following best describes \"Hardware Pass-Through\"?", "c": ["Creating an exact copy of an existing VM.", "Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction.", "Storage physically attached to a single hypervisor host.", "The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network."], "a": 1, "e": "Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction. Used when a workload needs near-native performance from a specific device, like a GPU."}, {"obj": "2.3", "q": "A team incrementally rewrites specific components of an application to use cloud-native patterns over several months, rather than redesigning everything at once. What migration strategy best describes this?", "c": ["Rehost", "Refactor", "Retire", "Retain"], "a": 1, "e": "Refactor rewrites portions of an application to better fit cloud-native patterns, often more incremental than a full re-architecture."}, {"obj": "1.4", "q": "Select the most accurate description of \"HDD\":", "c": ["Storage that manages data as discrete objects with metadata, accessed via an API (e.g., S3).", "Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk.", "Hard Disk Drive — traditional magnetic spinning-platter storage.", "The lowest-cost storage tier, designed for rarely accessed data with the slowest retrieval times (sometimes hours)."], "a": 2, "e": "Hard Disk Drive — traditional magnetic spinning-platter storage. Offers lower cost per GB than SSD, suited to large, less performance-sensitive datasets."}, {"obj": "1.11", "q": "A logistics company wants to digitize paper shipping manifests by extracting printed text from scanned images. Which AI capability is needed?", "c": ["Text recognition (OCR)", "Voice-to-text", "Generative AI", "Sentiment analysis"], "a": 0, "e": "Text recognition (OCR) extracts text from images or scanned documents, exactly matching the need to digitize paper manifests."}, {"obj": "1.11", "q": "Which statement accurately describes \"Generative AI\"?", "c": ["AI technology that converts written text into spoken audio (speech synthesis).", "AI technology that converts spoken audio into written text (speech recognition).", "A device that collects data from the physical environment (temperature, motion, etc.).", "AI models that create new content (text, images, code) based on learned patterns."], "a": 3, "e": "AI models that create new content (text, images, code) based on learned patterns. A rapidly growing category of cloud AI services used for content creation and code assistance."}, {"obj": "1.2", "q": "Select the most accurate description of \"Region\":", "c": ["A distinct geographic location where a cloud provider operates one or more datacenters.", "Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption.", "Processing data physically close to where it is generated rather than in a centralized datacenter.", "Recovery Point Objective — the maximum acceptable amount of data loss, measured in time."], "a": 0, "e": "A distinct geographic location where a cloud provider operates one or more datacenters. Choosing the right region affects latency, data sovereignty, and compliance."}, {"obj": "1.2", "q": "Which of the following best describes \"Edge Computing\"?", "c": ["A distinct geographic location where a cloud provider operates one or more datacenters.", "Processing data physically close to where it is generated rather than in a centralized datacenter.", "Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption.", "Using services from more than one public cloud provider simultaneously."], "a": 1, "e": "Processing data physically close to where it is generated rather than in a centralized datacenter. Reduces latency for time-sensitive applications like IoT and content delivery."}, {"obj": "1.5", "q": "Why does this matter on the exam and in practice? \"Common in event-driven microservices to notify several services of the same event simultaneously.\" — which term does this explain?", "c": ["Fan-Out", "Loosely Coupled Architecture", "Cloud-Provided Managed Service", "Service Discovery"], "a": 0, "e": "Common in event-driven microservices to notify several services of the same event simultaneously. This describes Fan-Out (\"A messaging pattern where one event is distributed to multiple downstream consumers/services.\")."}, {"obj": "2.5", "q": "An administrator explains the importance of a concept: \"Can restrict which regions, providers, or configurations are acceptable for a given workload.\" What concept is this?", "c": ["Compliance Requirements", "Network Requirements", "Compute Requirements", "Availability Requirements"], "a": 0, "e": "Can restrict which regions, providers, or configurations are acceptable for a given workload. This describes Compliance Requirements (\"Legal or regulatory obligations a workload's data and processing must meet.\")."}, {"obj": "3.2", "q": "A database server is running out of headroom, so the team increases its CPU and RAM allocation rather than adding another instance. What scaling approach is this?", "c": ["Horizontal scaling", "Vertical scaling", "Scheduled scaling", "Triggered scaling — event"], "a": 1, "e": "Vertical scaling increases the resources of an existing instance (scale up), as opposed to horizontal scaling which adds more instances."}, {"obj": "1.3", "q": "Why does this matter on the exam and in practice? \"Separates traffic types on shared physical/virtual network infrastructure.\" — which term does this explain?", "c": ["VLAN", "VPC Peering", "Firewall", "Application Gateway"], "a": 0, "e": "Separates traffic types on shared physical/virtual network infrastructure. This describes VLAN (\"Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains.\")."}, {"obj": "3.2", "q": "How would you most accurately define \"Triggered Scaling — Event\"?", "c": ["Scaling resources up or down at predefined times based on known usage patterns.", "Scaling in response to a specific event (like a message queue depth increasing).", "An administrator explicitly changing resource capacity rather than relying on automation.", "Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%)."], "a": 1, "e": "Scaling in response to a specific event (like a message queue depth increasing). Useful for event-driven architectures where load isn't purely CPU/memory based."}, {"obj": "4.2", "q": "A description reads: \"Payment Card Industry Data Security Standard — security requirements for handling payment card data.\" Which term does this describe?", "c": ["SOC2", "Litigation Hold", "PCI DSS", "Regulatory Retention"], "a": 2, "e": "\"Payment Card Industry Data Security Standard — security requirements for handling payment card data.\" describes PCI DSS. Any cloud workload that stores, processes, or transmits card data must meet these requirements."}, {"obj": "1.1", "q": "Which term is most closely associated with this real-world importance: \"The customer patches and secures the OS/apps; the provider is responsible only for the underlying physical infrastructure.\"?", "c": ["SaaS", "PaaS", "Shared Responsibility Model", "IaaS"], "a": 3, "e": "The customer patches and secures the OS/apps; the provider is responsible only for the underlying physical infrastructure. This describes IaaS (\"Infrastructure as a Service — provides virtualized compute, storage, and networking, leaving the OS and above to the customer.\")."}, {"obj": "1.9", "q": "A social media company needs to store rapidly growing, semi-structured user activity data that must scale horizontally across many nodes. Which database type is most appropriate?", "c": ["A traditional relational database", "A non-relational (NoSQL) database", "A single-file flat database", "An archive tier object store"], "a": 1, "e": "Non-relational databases handle flexible, semi-structured data formats and scale horizontally more easily than traditional relational databases."}, {"obj": "4.5", "q": "A company wants to block emails containing what appear to be customer credit card numbers from leaving the corporate network. What control should be deployed?", "c": ["DLP", "A WAF", "An IDS", "A network security group"], "a": 0, "e": "DLP detects and blocks unauthorized transmission of sensitive data such as credit card numbers leaving via channels like email."}, {"obj": "1.2", "q": "Given the description \"Continuously checking that a resource or service is up and responding as expected.\", which term is being defined?", "c": ["Availability Monitoring", "Region", "Cold Site", "RPO"], "a": 0, "e": "\"Continuously checking that a resource or service is up and responding as expected.\" describes Availability Monitoring. Provides the data needed to detect outages and calculate real-world uptime against SLA targets."}, {"obj": "1.11", "q": "Which concept is described by the phrase: \"AI technology that identifies objects, scenes, or features within images or video.\"?", "c": ["IoT Sensor", "Text Translation", "Visual Recognition", "Generative AI"], "a": 2, "e": "\"AI technology that identifies objects, scenes, or features within images or video.\" describes Visual Recognition. Powers use cases like content moderation, quality inspection, and security monitoring."}, {"obj": "2.3", "q": "In cloud computing terminology, \"Refactor\" refers to which of the following?", "c": ["Moving workloads out of the cloud back to local infrastructure.", "A migration strategy that rewrites portions of an application to better fit cloud-native patterns.", "A migration strategy that keeps a workload where it currently is, deferring migration.", "A migration strategy that decommissions an application no longer needed."], "a": 1, "e": "A migration strategy that rewrites portions of an application to better fit cloud-native patterns. Similar to re-architecting but often more incremental, improving specific components over time."}, {"obj": "2.3", "q": "A team migrating a legacy application chooses to replatform rather than rehost specifically because they want to take advantage of a managed load balancer and managed database without redesigning the application's core logic. What best characterizes replatforming compared to rehosting?", "c": ["Replatforming makes no changes at all, identical to rehosting", "Replatforming makes targeted optimizations to leverage cloud capabilities while keeping the core architecture largely intact", "Replatforming always costs more than a full re-architecture", "Replatforming requires retiring the original application first"], "a": 1, "e": "Replatforming sits between rehosting and re-architecting: it makes some cloud-oriented optimizations without a full redesign of the application's core architecture."}, {"obj": "2.2", "q": "A team wants the fastest possible rollback if a new release causes a critical failure, and is willing to pay for double the infrastructure temporarily to achieve this. Which strategy best supports this goal?", "c": ["In-place deployment", "Blue-green deployment", "A slow, single-instance rolling deployment", "Canary deployment with a 1% initial rollout only"], "a": 1, "e": "Blue-green deployment allows near-instant rollback by simply switching traffic back to the still-running previous environment, which requires temporarily running two full environments."}, {"obj": "1.7", "q": "A description reads: \"Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction.\" Which term does this describe?", "c": ["Local Storage (Virtualization)", "Stand-Alone Virtualization", "NAS (Virtualization Context)", "Hardware Pass-Through"], "a": 3, "e": "\"Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction.\" describes Hardware Pass-Through. Used when a workload needs near-native performance from a specific device, like a GPU."}, {"obj": "1.8", "q": "A data science team runs large batch training jobs that can tolerate being interrupted and restarted, and wants to minimize compute costs above all else. Which pricing model offers the deepest discount for this use case?", "c": ["Reserved resources", "Spot instances", "Dedicated host billing", "On-demand pay-as-you-go"], "a": 1, "e": "Spot instances offer steep discounts on interruptible spare capacity, well suited to fault-tolerant batch workloads that can handle being reclaimed."}, {"obj": "3.3", "q": "Which term is most closely associated with this real-world importance: \"Restores are simpler than incremental (just the full plus the latest differential), but each differential grows larger over time.\"?", "c": ["Full Backup", "Differential Backup", "Backup Encryption", "Parallel Recovery"], "a": 1, "e": "Restores are simpler than incremental (just the full plus the latest differential), but each differential grows larger over time. This describes Differential Backup (\"Backs up all data changed since the last full backup.\")."}, {"obj": "5.4", "q": "A team needs to provision identical infrastructure across AWS, Azure, and Google Cloud using one consistent tool and configuration language, avoiding provider-specific scripting for each. Which tool is best suited?", "c": ["Docker", "Terraform", "Grafana", "Jenkins"], "a": 1, "e": "Terraform's multi-cloud support and unified configuration language make it well suited for provisioning consistent infrastructure across multiple cloud providers."}, {"obj": "5.1", "q": "Before a proposed code change can be merged into the main branch, two teammates must review and approve it. What workflow mechanism enforces this?", "c": ["A code commit", "A pull request", "A code push", "Branch management"], "a": 1, "e": "A pull request is the formal mechanism for requesting a merge, typically triggering mandatory review before code is integrated."}, {"obj": "6.2", "q": "An administrator explains the importance of a concept: \"Clock drift can break authentication (like Kerberos) and certificate validation in subtle, confusing ways.\" What concept is this?", "c": ["NTP (Troubleshooting)", "Protocol Deprecation", "Network Overlap", "VLAN Misconfigured Tags"], "a": 0, "e": "Clock drift can break authentication (like Kerberos) and certificate validation in subtle, confusing ways. This describes NTP (Troubleshooting) (\"Network Time Protocol — synchronizes system clocks across a network.\")."}, {"obj": "1.11", "q": "Which statement accurately describes \"Text-to-Voice\"?", "c": ["AI technology that converts written text into spoken audio (speech synthesis).", "AI models that create new content (text, images, code) based on learned patterns.", "The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data.", "AI technology that automatically converts text from one language to another."], "a": 0, "e": "AI technology that converts written text into spoken audio (speech synthesis). Used for voice assistants, accessibility tools, and automated phone systems."}, {"obj": "4.1", "q": "Which of the following best illustrates the remediation step of the vulnerability management lifecycle?", "c": ["Running an automated scan to detect weaknesses", "Ranking vulnerabilities by severity", "Applying a vendor patch or compensating control to fix a confirmed vulnerability", "Defining which systems will be scanned"], "a": 2, "e": "Remediation is specifically the act of applying a fix (patch, configuration change, or compensating control), distinct from identification, assessment, or scope definition."}, {"obj": "1.8", "q": "Which statement accurately describes \"Pay-As-You-Go\"?", "c": ["Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice.", "Adjusting the size/type of provisioned resources to match actual workload demand.", "A billing model where a customer pays for an entire physical host, regardless of utilization.", "A billing model charging only for actual resource consumption, with no upfront commitment."], "a": 3, "e": "A billing model charging only for actual resource consumption, with no upfront commitment. Maximizes flexibility for unpredictable or short-term workloads, at a higher per-unit cost than reserved pricing."}, {"obj": "3.3", "q": "A company's RPO for a critical database is 15 minutes. Which backup/replication approach is most likely needed to meet this?", "c": ["Nightly full backups only", "Weekly differential backups", "Frequent transaction log backups or near-continuous replication", "Monthly full backups with no incrementals"], "a": 2, "e": "A tight 15-minute RPO requires very frequent data protection, such as frequent transaction log backups or continuous/synchronous replication, rather than infrequent full backups."}, {"obj": "4.4", "q": "Which concept is described by the phrase: \"Securely storing and controlling access to credentials, API keys, and other sensitive configuration values.\"?", "c": ["Privileged Container", "Secrets Management", "Unprivileged Container", "Object Storage Security"], "a": 1, "e": "\"Securely storing and controlling access to credentials, API keys, and other sensitive configuration values.\" describes Secrets Management. Prevents secrets from being hardcoded in source code or exposed in plaintext configuration files."}, {"obj": "1.1", "q": "A development team wants to deploy containerized microservices without managing the underlying VM fleet, but still wants control over the container runtime configuration. Which model is the closest fit?", "c": ["SaaS", "PaaS (container-oriented)", "On-premises virtualization", "FaaS only"], "a": 1, "e": "Many PaaS offerings (including container-oriented platforms) let developers control application/container configuration while the provider manages the underlying infrastructure and runtime."}, {"obj": "1.3", "q": "How would you most accurately define \"VPN\"?", "c": ["A device or service that filters network traffic based on defined rules.", "A manually configured network route that does not change dynamically.", "A hub service that connects many VPCs and on-premises networks through a single point.", "Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network."], "a": 3, "e": "Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network. A common way to connect on-premises networks or remote users securely to cloud resources."}, {"obj": "4.3", "q": "An administrator explains the importance of a concept: \"Commonly used to implement federated single sign-on into cloud platforms.\" What concept is this?", "c": ["SAML", "Federation", "Web Portal", "Local User Authentication"], "a": 0, "e": "Commonly used to implement federated single sign-on into cloud platforms. This describes SAML (\"Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.\")."}, {"obj": "3.3", "q": "Which of the following terms fits this definition: \"Backs up all data changed since the last full backup.\"?", "c": ["Backup Replication", "Incremental Backup", "Full Backup", "Differential Backup"], "a": 3, "e": "\"Backs up all data changed since the last full backup.\" describes Differential Backup. Restores are simpler than incremental (just the full plus the latest differential), but each differential grows larger over time."}, {"obj": "1.7", "q": "Why does this matter on the exam and in practice? \"Used to keep related VMs together for performance, or apart for redundancy (anti-affinity).\" — which term does this explain?", "c": ["Host Affinity", "Local Storage (Virtualization)", "SAN (Virtualization Context)", "Clustering"], "a": 0, "e": "Used to keep related VMs together for performance, or apart for redundancy (anti-affinity). This describes Host Affinity (\"A rule keeping specific VMs running on the same (or different) physical host.\")."}, {"obj": "1.8", "q": "Which concept is described by the phrase: \"Attaching key-value metadata labels to cloud resources.\"?", "c": ["Tagging", "Spot Instance", "Dedicated Host Billing", "Resource Metering"], "a": 0, "e": "\"Attaching key-value metadata labels to cloud resources.\" describes Tagging. Enables cost allocation, automation, and organization of resources by project, owner, or environment."}, {"obj": "1.9", "q": "The acronym \"NoSQL\" stands for:", "c": ["Continuous Integration/Continuous Deployment", "Lightweight Directory Access Protocol", "Not Only Structured Query Language", "Configuration as Code"], "a": 2, "e": "NoSQL stands for Not Only Structured Query Language. A category of non-relational databases using flexible data models."}, {"obj": "4.3", "q": "What does the abbreviation \"OAuth\" stand for?", "c": ["Identity and Access Management", "Open Authorization", "Cloud Security Alliance", "Local Area Network"], "a": 1, "e": "OAuth stands for Open Authorization. An authorization framework letting an application access resources on a user's behalf."}, {"obj": "1.6", "q": "Select the most accurate description of \"Port Mapping\":", "c": ["Binding a container's internal port to a port on the host or load balancer.", "Temporary storage tied to a container's lifecycle that is lost when the container stops.", "A single container running in isolation without orchestration.", "Storage that survives beyond the lifecycle of an individual container."], "a": 0, "e": "Binding a container's internal port to a port on the host or load balancer. Allows external traffic to reach a service running inside an otherwise isolated container."}, {"obj": "5.4", "q": "Select the most accurate description of \"Terraform\":", "c": ["Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization.", "An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively.", "A platform for building, running, and managing containers.", "An open-source, agentless automation tool used for configuration management and orchestration."], "a": 1, "e": "An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively. One of the most widely used multi-cloud IaC tools, using its own HCL configuration language."}, {"obj": "2.3", "q": "Which of the following terms fits this definition: \"Moving workloads from local infrastructure into a cloud environment.\"?", "c": ["Retain", "On-Premises-to-Cloud Migration", "Cloud-to-Cloud Migration", "Vendor Lock-In"], "a": 1, "e": "\"Moving workloads from local infrastructure into a cloud environment.\" describes On-Premises-to-Cloud Migration. The most common migration type when organizations first adopt cloud computing."}, {"obj": "2.2", "q": "Which term best matches this description: \"Updating instances incrementally, a few at a time, rather than all at once.\"?", "c": ["In-Place Deployment", "Canary Deployment", "Rolling Deployment", "Blue-Green Deployment"], "a": 2, "e": "\"Updating instances incrementally, a few at a time, rather than all at once.\" describes Rolling Deployment. Keeps the application available throughout the deployment, at the cost of a longer overall rollout window."}, {"obj": "4.3", "q": "In Cloud+ terminology, \"CLI\" is an abbreviation for which of the following?", "c": ["Configuration as Code", "Red Hat Package Manager", "Elasticsearch, Logstash, and Kibana", "Common Language Infrastructure"], "a": 3, "e": "CLI stands for Common Language Infrastructure. A text-based command line tool for managing cloud resources."}, {"obj": "3.2", "q": "A colleague says: \"Ideal for predictable daily/weekly demand cycles, like scaling up before business hours.\" Which concept are they describing?", "c": ["Manual Scaling", "Triggered Scaling — Trending", "Scheduled Scaling", "Horizontal Scaling"], "a": 2, "e": "Ideal for predictable daily/weekly demand cycles, like scaling up before business hours. This describes Scheduled Scaling (\"Scaling resources up or down at predefined times based on known usage patterns.\")."}, {"obj": "5.1", "q": "Which of the following terms fits this definition: \"Combining changes from different branches into one.\"?", "c": ["Branch Management", "Version Management", "Code Merge", "Pull Request"], "a": 2, "e": "\"Combining changes from different branches into one.\" describes Code Merge. Integrates parallel work from multiple developers or feature branches."}, {"obj": "4.2", "q": "Legal counsel instructs IT to preserve a specific set of emails indefinitely because they may be relevant to a lawsuit, overriding the normal 90-day deletion policy. What is this called?", "c": ["Regulatory retention", "Litigation hold", "Data classification", "Contractual retention"], "a": 1, "e": "A litigation hold is a legal requirement to preserve specific data due to pending or anticipated litigation, overriding normal schedules."}, {"obj": "1.6", "q": "An external user needs to reach a web service running inside a container on port 8080, but the container's ports are otherwise isolated from the host network. What must be configured?", "c": ["Persistent volume mounting", "Port mapping", "Image registry access", "Workload orchestration only"], "a": 1, "e": "Port mapping binds a container's internal port to a port on the host or load balancer, allowing external traffic to reach the containerized service."}, {"obj": "6.2", "q": "Given the description \"Running out of available addresses within a defined IP range or subnet.\", which term is being defined?", "c": ["Missing Route", "NAT (Troubleshooting)", "HTTP Status Codes", "IP Scope Exhaustion"], "a": 3, "e": "\"Running out of available addresses within a defined IP range or subnet.\" describes IP Scope Exhaustion. Prevents new resources from being provisioned with an address until the range is expanded or reclaimed."}, {"obj": "4.3", "q": "How would you most accurately define \"API (IAM Context)\"?", "c": ["An identity layer built on top of OAuth 2.0 used for authentication (proving who you are).", "Application Programming Interface — used here for programmatic management/access to cloud resources.", "Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.", "Accessing cloud resources via code rather than a human using a GUI (API/SDK)."], "a": 1, "e": "Application Programming Interface — used here for programmatic management/access to cloud resources. API access typically requires its own credentials (keys/tokens) separate from human user logins."}, {"obj": "6.2", "q": "Which of the following terms fits this definition: \"Incorrect VLAN tagging causing traffic to be dropped or delivered to the wrong segment.\"?", "c": ["Network Overlap", "NAT (Troubleshooting)", "VLAN Misconfigured Tags", "Access vs. Trunk Ports"], "a": 2, "e": "\"Incorrect VLAN tagging causing traffic to be dropped or delivered to the wrong segment.\" describes VLAN Misconfigured Tags. A classic Layer 2 troubleshooting issue, especially after switch or trunk reconfiguration."}, {"obj": "4.2", "q": "Which concept is described by the phrase: \"An international standard specifying requirements for an information security management system.\"?", "c": ["PCI DSS", "SOC2", "Regulatory Retention", "ISO 27001"], "a": 3, "e": "\"An international standard specifying requirements for an information security management system.\" describes ISO 27001. A widely recognized certification demonstrating a structured approach to information security."}, {"obj": "4.3", "q": "An administrator explains the importance of a concept: \"Simple but doesn't scale well and complicates centralized policy enforcement across many systems.\" What concept is this?", "c": ["Local User Authentication", "OpenID Connect", "Directory-Based Authentication", "Federation"], "a": 0, "e": "Simple but doesn't scale well and complicates centralized policy enforcement across many systems. This describes Local User Authentication (\"Authenticating with credentials stored directly on the system rather than a central directory.\")."}, {"obj": "6.2", "q": "Which statement accurately describes \"NTP (Troubleshooting)\"?", "c": ["Domain Name System — resolves hostnames to IP addresses.", "A required network path that has not been defined in a route table.", "Network Time Protocol — synchronizes system clocks across a network.", "The distinction between a switch port carrying a single VLAN (access) versus multiple VLANs (trunk)."], "a": 2, "e": "Network Time Protocol — synchronizes system clocks across a network. Clock drift can break authentication (like Kerberos) and certificate validation in subtle, confusing ways."}, {"obj": "1.9", "q": "A colleague says: \"Best suited for structured data requiring strong consistency and complex queries/joins.\" Which concept are they describing?", "c": ["Provider-Managed Database", "Non-Relational Database", "Relational Database", "Self-Managed Database"], "a": 2, "e": "Best suited for structured data requiring strong consistency and complex queries/joins. This describes Relational Database (\"A database that organizes data into structured tables with defined relationships (SQL).\")."}, {"obj": "3.3", "q": "A colleague says: \"Balances storage cost against the need to recover from an issue discovered after some delay.\" Which concept are they describing?", "c": ["Differential Backup", "Backup Retention (Ops)", "Parallel Recovery", "Granular Recovery"], "a": 1, "e": "Balances storage cost against the need to recover from an issue discovered after some delay. This describes Backup Retention (Ops) (\"How long backup copies are kept before being deleted or overwritten.\")."}, {"obj": "6.1", "q": "A colleague says: \"Deployments can fail silently if a quota is reached without prior awareness.\" Which concept are they describing?", "c": ["Service Quota", "API Throttling", "Full Outage", "Resource Allocation Misconfiguration"], "a": 0, "e": "Deployments can fail silently if a quota is reached without prior awareness. This describes Service Quota (\"A provider-imposed limit on how many of a given resource type can be provisioned.\")."}, {"obj": "5.2", "q": "A pipeline automatically compiles source code into a deployable package every time a change is merged. What CI/CD stage is this?", "c": ["Build", "Testing", "Deployment", "Code review"], "a": 0, "e": "The build stage compiles/packages source code into a deployable artifact, transforming code into something runnable."}, {"obj": "3.3", "q": "An administrator explains the importance of a concept: \"Useful for testing a restore or recovering without disrupting the still-running original system.\" What concept is this?", "c": ["Full Backup", "Backup Replication", "Backup Retention (Ops)", "Parallel Recovery"], "a": 3, "e": "Useful for testing a restore or recovering without disrupting the still-running original system. This describes Parallel Recovery (\"Restoring data to an alternate system running alongside the original.\")."}, {"obj": "1.3", "q": "Which of the following terms fits this definition: \"A direct network connection between two VPCs that allows them to communicate as if on the same network.\"?", "c": ["VPC Peering", "Application Load Balancer", "Subnet", "Route Table"], "a": 0, "e": "\"A direct network connection between two VPCs that allows them to communicate as if on the same network.\" describes VPC Peering. Enables private communication between separate VPCs without routing traffic over the public internet."}, {"obj": "2.3", "q": "During a migration assessment, a company decides an old internal tool is no longer needed and will be shut down instead of migrated. What strategy is this?", "c": ["Retain", "Retire", "Replatform", "Refactor"], "a": 1, "e": "Retire decommissions an application that is no longer needed, reducing the overall migration scope."}, {"obj": "6.1", "q": "A company scales up a fleet of VMs on a shared physical host until performance for all tenants degrades noticeably, even though no single VM is failing outright. What is the most likely cause?", "c": ["Regional service availability", "Oversubscription of the underlying physical host's resources", "API throttling", "A full outage"], "a": 1, "e": "Allocating more virtual resources across VMs than the physical host can truly support (oversubscription) causes shared performance degradation across all tenants, even without any single outright failure."}, {"obj": "2.4", "q": "A team wants to roll back to a known-good infrastructure configuration after a bad change was applied last week. What practice makes this possible?", "c": ["IaC versioning with a tracked history of changes", "Avoiding all documentation", "Manual memory of past configurations", "Disabling all version control"], "a": 0, "e": "IaC versioning tracks changes over time using version control, enabling rollback to a previously known-good configuration."}, {"obj": "1.11", "q": "\"Machine Learning\" is best defined as which of the following?", "c": ["AI technology that converts written text into spoken audio (speech synthesis).", "Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case.", "AI technology that automatically converts text from one language to another.", "AI technology that converts spoken audio into written text (speech recognition)."], "a": 1, "e": "Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case. Underpins many modern cloud AI services such as recommendation engines and fraud detection."}, {"obj": "1.1", "q": "Given the description \"Function as a Service — lets code run in response to events without provisioning or managing any server (serverless).\", which term is being defined?", "c": ["FaaS", "SaaS", "Shared Responsibility Model", "IaaS"], "a": 0, "e": "\"Function as a Service — lets code run in response to events without provisioning or managing any server (serverless).\" describes FaaS. Billing is based on execution time/invocations rather than reserved capacity, ideal for event-driven workloads."}, {"obj": "6.3", "q": "Which term best matches this description: \"Problems arising from unpatched or improperly configured software containing known weaknesses.\"?", "c": ["Leaked Credentials", "Software Vulnerability Issues", "Cipher Suite Deprecation", "Unauthorized Software"], "a": 1, "e": "\"Problems arising from unpatched or improperly configured software containing known weaknesses.\" describes Software Vulnerability Issues. Reinforces the ongoing need for vulnerability management and timely patching."}, {"obj": "1.7", "q": "What does the abbreviation \"vNIC\" stand for?", "c": ["Virtual Private Network", "Hypertext Transfer Protocol", "Virtual NIC", "Domain Name System"], "a": 2, "e": "vNIC stands for Virtual NIC. A virtual network adapter presented to a guest VM by the hypervisor."}, {"obj": "4.5", "q": "\"IAM Policies\" is best defined as which of the following?", "c": ["Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity.", "Security software (antivirus, EDR) installed directly on servers, VMs, or devices.", "Rules that define what actions a given identity is allowed or denied to perform on cloud resources.", "A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs."], "a": 2, "e": "Rules that define what actions a given identity is allowed or denied to perform on cloud resources. The core mechanism for enforcing least privilege and access control in cloud environments."}, {"obj": "3.3", "q": "A company copies its backup data to a second region so that a disaster affecting the primary region does not also destroy the only backup copy. What is this practice called?", "c": ["Backup encryption", "Backup replication", "Granular recovery", "In-place recovery"], "a": 1, "e": "Backup replication copies backup data to another location (often a different region), protecting against a disaster affecting the primary backup location."}, {"obj": "4.3", "q": "Select the most accurate description of \"OAuth 2.0\":", "c": ["Secure Shell — an encrypted protocol for remote command-line access to cloud resources.", "A hardened server that provides a single, monitored entry point for administrative access into a private network.", "An authorization framework that lets an application access resources on a user's behalf without sharing their password.", "Multifactor Authentication — requiring two or more independent verification factors to log in."], "a": 2, "e": "An authorization framework that lets an application access resources on a user's behalf without sharing their password. The standard mechanism behind \"log in with...\" and delegated API access scenarios."}, {"obj": "6.1", "q": "How would you most accurately define \"Service Quota\"?", "c": ["The fact that not all cloud services are available in every region.", "Incorrectly assigned CPU, memory, or storage limits for a workload.", "A provider intentionally limiting the rate of API calls a customer can make.", "A provider-imposed limit on how many of a given resource type can be provisioned."], "a": 3, "e": "A provider-imposed limit on how many of a given resource type can be provisioned. Deployments can fail silently if a quota is reached without prior awareness."}, {"obj": "4.2", "q": "A company receives a legal notice requiring it to preserve specific records related to an ongoing regulatory investigation, even though its normal retention policy would have deleted them by now. What should the company do?", "c": ["Proceed with normal deletion since policy takes precedence", "Honor the litigation hold and preserve the specified records until the hold is lifted", "Ignore the notice since it conflicts with internal policy", "Delete the records immediately to avoid liability"], "a": 1, "e": "A litigation hold legally overrides normal retention/deletion schedules until it is lifted, and must be honored regardless of the company's default policy."}, {"obj": "1.7", "q": "A GPU-intensive machine learning workload running in a VM needs near-native performance from the physical GPU. What virtualization feature should be used?", "c": ["Overlay networking", "Hardware pass-through", "Host affinity", "Cloning"], "a": 1, "e": "Hardware pass-through gives a VM direct access to a physical device, avoiding hypervisor abstraction overhead for near-native performance."}, {"obj": "1.11", "q": "Why does this matter on the exam and in practice? \"Optimized for low bandwidth and power use, unlike heavier traditional web protocols.\" — which term does this explain?", "c": ["Text-to-Voice", "IoT Transmission Protocol", "Text Translation", "Generative AI"], "a": 1, "e": "Optimized for low bandwidth and power use, unlike heavier traditional web protocols. This describes IoT Transmission Protocol (\"Lightweight protocols (like MQTT or CoAP) designed for constrained IoT devices and networks.\")."}, {"obj": "5.3", "q": "In cloud computing terminology, \"Web Sockets\" refers to which of the following?", "c": ["A design where components communicate by producing and reacting to events rather than direct calls.", "Representational State Transfer — an architectural style for web services using standard HTTP methods.", "A protocol providing full-duplex, persistent communication channels over a single TCP connection.", "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local."], "a": 2, "e": "A protocol providing full-duplex, persistent communication channels over a single TCP connection. Enables real-time, bidirectional communication like chat apps or live dashboards, unlike typical request/response HTTP."}, {"obj": "1.2", "q": "A colleague says: \"Spreading resources across AZs protects against a single datacenter failure without the latency of a different region.\" Which concept are they describing?", "c": ["Availability Monitoring", "RPO", "Hot Site", "Availability Zone"], "a": 3, "e": "Spreading resources across AZs protects against a single datacenter failure without the latency of a different region. This describes Availability Zone (\"An isolated location within a region with independent power, cooling, and networking.\")."}, {"obj": "5.3", "q": "In cloud computing terminology, \"Event-Driven Architecture\" refers to which of the following?", "c": ["A protocol providing full-duplex, persistent communication channels over a single TCP connection.", "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local.", "A design where components communicate by producing and reacting to events rather than direct calls.", "Simple Object Access Protocol — an XML-based messaging protocol for web services."], "a": 2, "e": "A design where components communicate by producing and reacting to events rather than direct calls. Enables loose coupling and scalability, common in cloud-native and microservices designs."}, {"obj": "4.3", "q": "Which statement accurately describes \"Discretionary Access Control\"?", "c": ["A hardened server that provides a single, monitored entry point for administrative access into a private network.", "Accessing cloud resources via code rather than a human using a GUI (API/SDK).", "A graphical, browser-based interface for managing cloud resources.", "An access model where the resource owner decides who else can access it."], "a": 3, "e": "An access model where the resource owner decides who else can access it. Flexible, but relies on individual owners consistently applying good judgment about access grants."}, {"obj": "1.1", "q": "During a security audit of an IaaS deployment, the auditor asks who is responsible for patching a security vulnerability in the guest operating system. What is the correct answer per the shared responsibility model?", "c": ["The cloud provider", "The customer", "Neither party is responsible", "The hardware manufacturer"], "a": 1, "e": "In IaaS, the customer owns responsibility for the guest OS, including patching, since the provider is only responsible for the underlying physical infrastructure and hypervisor."}, {"obj": "4.1", "q": "A security team wants to reference a specific vulnerability consistently when communicating with a software vendor, a scanning tool vendor, and their own internal ticketing system. What should they use?", "c": ["A internal-only nickname with no external meaning", "The vulnerability's CVE identifier", "A random ticket number with no cross-reference", "An unofficial description with no standard reference"], "a": 1, "e": "CVE identifiers provide a standardized reference recognized across vendors and tools, ensuring consistent communication about a specific vulnerability."}, {"obj": "5.4", "q": "A team wants to build real-time dashboards visualizing metrics collected from their cloud infrastructure. Which tool is commonly used for this?", "c": ["Grafana", "Jenkins", "Git", "Docker"], "a": 0, "e": "Grafana is widely used to visualize metrics and build monitoring dashboards, often paired with a time-series database."}, {"obj": "1.4", "q": "How would you most accurately define \"HDD\"?", "c": ["Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk.", "Hard Disk Drive — traditional magnetic spinning-platter storage.", "A storage tier for infrequently accessed data, offering lower cost with slower retrieval.", "A storage tier for data accessed less frequently than hot data, balancing cost and access speed."], "a": 1, "e": "Hard Disk Drive — traditional magnetic spinning-platter storage. Offers lower cost per GB than SSD, suited to large, less performance-sensitive datasets."}, {"obj": "4.3", "q": "Which term is most closely associated with this real-world importance: \"Essential for investigating incidents and demonstrating compliance with access policies.\"?", "c": ["Programmatic Access", "Local User Authentication", "Audit Trail", "API (IAM Context)"], "a": 2, "e": "Essential for investigating incidents and demonstrating compliance with access policies. This describes Audit Trail (\"A chronological record of who did what, and when, within a system.\")."}, {"obj": "3.2", "q": "Which concept is described by the phrase: \"An administrator explicitly changing resource capacity rather than relying on automation.\"?", "c": ["Horizontal Scaling", "Vertical Scaling", "Manual Scaling", "Triggered Scaling — Load"], "a": 2, "e": "\"An administrator explicitly changing resource capacity rather than relying on automation.\" describes Manual Scaling. Useful for planned events or when automated triggers aren't yet configured."}, {"obj": "3.3", "q": "Which backup approach generally requires the least backup time per day but the most complex, multi-step restore process?", "c": ["Full backups every day", "Full backup plus daily incremental backups", "Full backup plus daily differential backups", "No backups at all"], "a": 1, "e": "Incremental backups are the fastest to perform daily but require restoring the full chain of incrementals in order, making the restore process more complex than differential backups."}, {"obj": "4.5", "q": "Which of the following is the correct expansion of \"WAF\"?", "c": ["Internet Protocol", "Internet Control Message Protocol", "Artificial Intelligence", "Web Application Firewall"], "a": 3, "e": "WAF stands for Web Application Firewall. A firewall designed to filter and monitor HTTP traffic to web applications."}, {"obj": "4.4", "q": "Why does this matter on the exam and in practice? \"Closes known security gaps that attackers commonly target since patches for them already exist.\" — which term does this explain?", "c": ["Container File Access Permissions", "Patching (Security)", "Vendor-Specific Benchmark", "Secrets Management"], "a": 1, "e": "Closes known security gaps that attackers commonly target since patches for them already exist. This describes Patching (Security) (\"Applying vendor-released updates that fix known vulnerabilities.\")."}, {"obj": "4.3", "q": "Which concept is described by the phrase: \"Authenticating against a centralized directory service (like LDAP or Active Directory).\"?", "c": ["Audit Trail", "Discretionary Access Control", "RDP", "Directory-Based Authentication"], "a": 3, "e": "\"Authenticating against a centralized directory service (like LDAP or Active Directory).\" describes Directory-Based Authentication. Centralizes identity management across many systems rather than maintaining separate local accounts."}, {"obj": "4.6", "q": "Which concept is described by the phrase: \"An attack that succeeds due to a mistake made by an authorized user (misconfiguration, mishandling credentials, etc.).\"?", "c": ["Deviation from Baseline", "DDoS", "Unnecessary Open Ports", "Vulnerability Exploitation — Human Error"], "a": 3, "e": "\"An attack that succeeds due to a mistake made by an authorized user (misconfiguration, mishandling credentials, etc.).\" describes Vulnerability Exploitation — Human Error. Highlights that technical controls alone can't fully prevent security incidents caused by human mistakes."}, {"obj": "2.3", "q": "Which concept is described by the phrase: \"Moving workloads out of the cloud back to local infrastructure.\"?", "c": ["Cloud-to-Cloud Migration", "Cloud-to-On-Premises Migration", "Replatform", "Retire"], "a": 1, "e": "\"Moving workloads out of the cloud back to local infrastructure.\" describes Cloud-to-On-Premises Migration. Sometimes chosen for cost, compliance, or performance reasons after initial cloud adoption."}, {"obj": "2.5", "q": "Select the most accurate description of \"Network Requirements\":", "c": ["The processing power (CPU, RAM) needed to run a workload effectively.", "The bandwidth, latency, and connectivity needs of a workload.", "The uptime and resiliency expectations for a workload.", "The capacity, performance, and durability needs a workload has for its data."], "a": 1, "e": "The bandwidth, latency, and connectivity needs of a workload. Shapes decisions about region placement, dedicated connections, and load balancer configuration."}, {"obj": "1.6", "q": "A container is used to run a short-lived batch job that writes temporary intermediate files which do not need to be kept after the job finishes. What storage type is appropriate?", "c": ["A persistent volume", "Ephemeral storage", "An image registry", "A shared NFS export required for all containers"], "a": 1, "e": "Ephemeral storage is appropriate for temporary data that does not need to survive beyond the container's lifecycle, such as scratch files for a batch job."}, {"obj": "2.4", "q": "How would you most accurately define \"Infrastructure as Code\"?", "c": ["JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates.", "Identifying when a deployed resource's actual state no longer matches its defined IaC configuration.", "Managing and provisioning infrastructure through machine-readable definition files rather than manual processes.", "Validating infrastructure code for syntax, security, and logic before it is applied to real environments."], "a": 2, "e": "Managing and provisioning infrastructure through machine-readable definition files rather than manual processes. Makes infrastructure changes repeatable, version-controlled, and auditable."}, {"obj": "1.2", "q": "Which of the following terms fits this definition: \"Using services from more than one public cloud provider simultaneously.\"?", "c": ["Multicloud Tenancy", "Hot Site", "Availability Monitoring", "Cold Site"], "a": 0, "e": "\"Using services from more than one public cloud provider simultaneously.\" describes Multicloud Tenancy. Reduces vendor lock-in and can improve resilience, but increases operational and integration complexity."}, {"obj": "1.3", "q": "Which statement accurately describes \"Application Gateway\"?", "c": ["A set of rules that determines where network traffic is directed.", "Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network.", "A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features.", "Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks."], "a": 2, "e": "A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features. Provides a single ingress point for web applications with built-in security and traffic-shaping features."}, {"obj": "2.3", "q": "Which concept is described by the phrase: \"A migration strategy that decommissions an application no longer needed.\"?", "c": ["Retire", "Refactor", "On-Premises-to-Cloud Migration", "Rehost"], "a": 0, "e": "\"A migration strategy that decommissions an application no longer needed.\" describes Retire. Reduces the overall migration scope and ongoing costs by eliminating unnecessary systems."}, {"obj": "3.3", "q": "Which of the following best describes why a company might choose to encrypt its backups even though the production data is already encrypted at rest?", "c": ["Backups are never at risk since they are inherently different from production data", "Backup media is often stored separately, transported, or replicated to other locations, creating additional independent exposure that should also be protected", "Encrypting backups is purely a legal formality with no real security value", "Production encryption automatically covers backup files with no separate action needed"], "a": 1, "e": "Backup copies often travel to different storage locations or media, creating independent exposure risk that should be protected with its own encryption rather than assuming production encryption alone suffices."}, {"obj": "3.3", "q": "Which term is most closely associated with this real-world importance: \"Forms the baseline that incremental and differential backups build on.\"?", "c": ["Full Backup", "Incremental Backup", "Granular Recovery", "Backup Integrity Testing"], "a": 0, "e": "Forms the baseline that incremental and differential backups build on. This describes Full Backup (\"A complete copy of all selected data.\")."}, {"obj": "2.1", "q": "Which factor most directly distinguishes a community cloud from a standard private cloud?", "c": ["A community cloud is shared among multiple organizations with common concerns, while a private cloud is dedicated to a single organization", "A community cloud is always free of charge", "A private cloud can never be hosted off-premises", "A community cloud has no security controls"], "a": 0, "e": "The defining difference is tenancy: a community cloud serves multiple organizations sharing common concerns, while a private cloud serves just one organization."}, {"obj": "4.5", "q": "\"DLP\" is best defined as which of the following?", "c": ["Rules that define what actions a given identity is allowed or denied to perform on cloud resources.", "Security software (antivirus, EDR) installed directly on servers, VMs, or devices.", "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data.", "A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs."], "a": 2, "e": "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data. Commonly blocks sensitive data like credit card numbers from leaving the network through channels like email."}, {"obj": "3.1", "q": "A financial company must retain audit logs for 7 years due to regulatory requirements, even though the logs are rarely accessed after the first month. What should be configured?", "c": ["Immediate deletion after 30 days", "A log retention policy that retains logs for 7 years, potentially moving older logs to cheaper storage tiers", "No retention policy at all", "Aggregating logs without any retention plan"], "a": 1, "e": "A properly configured retention policy keeps logs for the required regulatory period, often shifting older, rarely accessed logs to cheaper storage rather than deleting them prematurely."}, {"obj": "2.4", "q": "A description reads: \"Managing system or application configuration through code rather than manual configuration.\" Which term does this describe?", "c": ["YAML", "IaC Versioning", "Configuration as Code", "Infrastructure as Code"], "a": 2, "e": "\"Managing system or application configuration through code rather than manual configuration.\" describes Configuration as Code. Ensures configuration consistency across environments and enables automated drift correction."}, {"obj": "1.9", "q": "A company needs strong transactional consistency (ACID compliance) for financial transactions with complex relationships between accounts and transactions. Which database type is the standard choice?", "c": ["A relational database", "A pure key-value store", "Object storage", "A flat CSV file"], "a": 0, "e": "Relational databases are the standard choice for workloads requiring strong transactional consistency and complex relational integrity, such as financial systems."}, {"obj": "4.4", "q": "Which of the following best describes \"Principle of Least Privilege\"?", "c": ["Applying vendor-released updates that fix known vulnerabilities.", "Granting only the minimum access rights needed to perform a function.", "Reducing a system's attack surface by disabling unnecessary services, closing unused ports, and applying secure configurations.", "Controls governing which files and directories a container process can read or write."], "a": 1, "e": "Granting only the minimum access rights needed to perform a function. Limits the potential damage if an account or service is compromised."}, {"obj": "1.1", "q": "An administrator explains the importance of a concept: \"Developers push code and the provider handles the OS, runtime, and scaling, speeding up application delivery.\" What concept is this?", "c": ["Shared Responsibility Model", "SaaS", "PaaS", "FaaS"], "a": 2, "e": "Developers push code and the provider handles the OS, runtime, and scaling, speeding up application delivery. This describes PaaS (\"Platform as a Service — provides a managed runtime/platform for developing and deploying applications without managing the underlying OS.\")."}, {"obj": "6.1", "q": "A colleague says: \"Represents the most severe availability impact, prioritized above partial outages.\" Which concept are they describing?", "c": ["Outdated Component Definitions", "Regional Service Availability", "Full Outage", "Sizing Issues"], "a": 2, "e": "Represents the most severe availability impact, prioritized above partial outages. This describes Full Outage (\"A complete loss of service availability.\")."}, {"obj": "5.2", "q": "A description reads: \"A packaged virtual machine image produced and stored as a build output.\" Which term does this describe?", "c": ["Code Deployment", "RPM Package", "Flat File Artifact", "VM Image Artifact"], "a": 3, "e": "\"A packaged virtual machine image produced and stored as a build output.\" describes VM Image Artifact. Provides a versioned, reusable deployment unit for VM-based workloads."}, {"obj": "1.3", "q": "Given the description \"A logical subdivision of a network's IP address range.\", which term is being defined?", "c": ["Subnet", "VLAN", "Network Load Balancer", "SDN"], "a": 0, "e": "\"A logical subdivision of a network's IP address range.\" describes Subnet. Used within a VPC to separate resources (e.g., public-facing vs. private-only) for security and routing control."}, {"obj": "3.3", "q": "A description reads: \"Restoring a large set of data all at once.\" Which term does this describe?", "c": ["Bulk Recovery", "Backup Integrity Testing", "Backup Schedule", "Backup Retention (Ops)"], "a": 0, "e": "\"Restoring a large set of data all at once.\" describes Bulk Recovery. Appropriate when an entire system or dataset needs to be recovered together."}, {"obj": "4.6", "q": "Which of the following best describes \"DDoS\"?", "c": ["A cloud instance that is running but forgotten, unmonitored, or unmanaged.", "A departure from a system's established normal behavior pattern.", "Malware that encrypts a victim's data and demands payment for the decryption key.", "Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources."], "a": 3, "e": "Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources. Aims to exhaust resources or bandwidth so legitimate users cannot access the service."}, {"obj": "4.4", "q": "Given the description \"Granting only the minimum access rights needed to perform a function.\", which term is being defined?", "c": ["Data at Rest Encryption", "Principle of Least Privilege", "Data in Transit Encryption", "Patching (Security)"], "a": 1, "e": "\"Granting only the minimum access rights needed to perform a function.\" describes Principle of Least Privilege. Limits the potential damage if an account or service is compromised."}, {"obj": "4.3", "q": "Which term is most closely associated with this real-world importance: \"Widely used for consumer and enterprise single sign-on into cloud applications.\"?", "c": ["Federation", "API (IAM Context)", "Bastion Host", "OpenID Connect"], "a": 3, "e": "Widely used for consumer and enterprise single sign-on into cloud applications. This describes OpenID Connect (\"An identity layer built on top of OAuth 2.0 used for authentication (proving who you are).\")."}, {"obj": "1.6", "q": "A team needs an internal, access-restricted location to store proprietary container images that must not be publicly available. What should be configured?", "c": ["A public image registry with default settings", "A private image registry with access controls", "Ephemeral storage with public read access", "A persistent volume shared publicly"], "a": 1, "e": "A private image registry with proper access controls restricts proprietary images to authorized users, unlike a public registry."}, {"obj": "3.3", "q": "A description reads: \"Restoring individual files or specific data items rather than an entire dataset.\" Which term does this describe?", "c": ["Differential Backup", "Granular Recovery", "Backup Encryption", "Bulk Recovery"], "a": 1, "e": "\"Restoring individual files or specific data items rather than an entire dataset.\" describes Granular Recovery. Saves time when only a small subset of data (like one accidentally deleted file) needs to be restored."}, {"obj": "3.1", "q": "A description reads: \"Gathering log data from applications, systems, and services into a central location.\" Which term does this describe?", "c": ["Tracing", "Alert Triage", "Log Aggregation", "Log Collection"], "a": 3, "e": "\"Gathering log data from applications, systems, and services into a central location.\" describes Log Collection. The first step in observability — without collection, logs remain scattered and hard to analyze."}, {"obj": "1.5", "q": "Which statement accurately describes \"Fan-Out\"?", "c": ["A service the cloud provider fully operates (e.g., a managed database), removing the customer's operational burden.", "A messaging pattern where one event is distributed to multiple downstream consumers/services.", "A mechanism that lets services dynamically find the network location of other services.", "An architecture where an application is broken into small, independently deployable services."], "a": 1, "e": "A messaging pattern where one event is distributed to multiple downstream consumers/services. Common in event-driven microservices to notify several services of the same event simultaneously."}, {"obj": "4.5", "q": "Which term is most closely associated with this real-world importance: \"The primary mechanism for instance-level network access control in most cloud platforms.\"?", "c": ["DLP", "Network ACL", "Network Security Group", "DDoS Protection"], "a": 2, "e": "The primary mechanism for instance-level network access control in most cloud platforms. This describes Network Security Group (\"A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs.\")."}, {"obj": "4.3", "q": "Given the description \"A graphical, browser-based interface for managing cloud resources.\", which term is being defined?", "c": ["Audit Trail", "Token-Based Authentication", "Web Portal", "OAuth 2.0"], "a": 2, "e": "\"A graphical, browser-based interface for managing cloud resources.\" describes Web Portal. The most accessible management interface for humans, though less suited to automation."}, {"obj": "2.4", "q": "An administrator explains the importance of a concept: \"One of the two dominant data formats used to define cloud resources declaratively.\" What concept is this?", "c": ["IaC Versioning", "JSON", "IaC Testing", "Drift Detection"], "a": 1, "e": "One of the two dominant data formats used to define cloud resources declaratively. This describes JSON (\"JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates.\")."}, {"obj": "1.2", "q": "\"RPO\" is best defined as which of the following?", "c": ["Recovery Point Objective — the maximum acceptable amount of data loss, measured in time.", "An isolated location within a region with independent power, cooling, and networking.", "A distinct geographic location where a cloud provider operates one or more datacenters.", "A fully equipped, continuously running DR site that can take over almost immediately."], "a": 0, "e": "Recovery Point Objective — the maximum acceptable amount of data loss, measured in time. A tight RPO requires frequent backups or synchronous replication; a looser RPO allows infrequent backups."}, {"obj": "1.1", "q": "A company's compliance team asks whether they are responsible for patching the hypervisor in their IaaS environment. What is the correct answer?", "c": ["Yes, the customer must patch the hypervisor", "No, the hypervisor and underlying physical infrastructure are the provider's responsibility", "Only if the customer requests hypervisor access", "The hypervisor does not require patching"], "a": 1, "e": "The hypervisor and physical infrastructure remain the cloud provider's responsibility even in IaaS; the customer's responsibility begins at the guest OS."}, {"obj": "1.10", "q": "A company automates the scheduling, scaling, and lifecycle management of its workloads across a cluster rather than manually managing each instance. What concept does this represent?", "c": ["Manual provisioning", "Orchestration", "IOPS optimization", "Network latency reduction"], "a": 1, "e": "Orchestration automates coordination of workload deployment, scaling, and lifecycle management, replacing manual per-instance management."}, {"obj": "2.5", "q": "A provisioning plan for a new database instance considers expected read/write load (compute), required uptime (availability), and where the data must reside (compliance). Which of the following was NOT explicitly assessed in this scenario?", "c": ["Compute requirements", "Availability requirements", "Compliance requirements", "Storage capacity and performance requirements"], "a": 3, "e": "The scenario describes compute, availability, and compliance considerations, but does not mention assessing storage capacity/performance requirements, which should also be part of a complete provisioning plan."}, {"obj": "6.1", "q": "A team's automated deployment script begins failing intermittently with 'rate exceeded' errors from the cloud provider's API during a large bulk resource creation job. What should be implemented to resolve this?", "c": ["Retry logic with backoff to handle API throttling gracefully", "Increasing the instance size of the deploying VM", "Switching to a different region entirely", "Ignoring the errors since they are cosmetic"], "a": 0, "e": "Implementing retry logic with exponential backoff is the standard way to gracefully handle API throttling during bulk operations, rather than overwhelming the API further."}, {"obj": "6.1", "q": "Which of the following terms fits this definition: \"A deployment failure or performance problem caused by choosing an inappropriately sized resource.\"?", "c": ["Resource Allocation Misconfiguration", "Sizing Issues", "Incompatibility (Deployment)", "Regional Service Availability"], "a": 1, "e": "\"A deployment failure or performance problem caused by choosing an inappropriately sized resource.\" describes Sizing Issues. Both undersizing (poor performance) and oversizing (wasted cost) are common sizing mistakes."}, {"obj": "1.2", "q": "Which term is most closely associated with this real-world importance: \"Reduces vendor lock-in and can improve resilience, but increases operational and integration complexity.\"?", "c": ["Region", "RPO", "Cloud Bursting", "Multicloud Tenancy"], "a": 3, "e": "Reduces vendor lock-in and can improve resilience, but increases operational and integration complexity. This describes Multicloud Tenancy (\"Using services from more than one public cloud provider simultaneously.\")."}, {"obj": "3.3", "q": "Which of the following terms fits this definition: \"Actually restoring backup data to confirm it can be used successfully.\"?", "c": ["Differential Backup", "Backup Recoverability Testing", "In-Place Recovery", "Incremental Backup"], "a": 1, "e": "\"Actually restoring backup data to confirm it can be used successfully.\" describes Backup Recoverability Testing. A backup reporting \"success\" does not guarantee the data is truly restorable — testing closes that gap."}, {"obj": "1.10", "q": "Which statement accurately describes \"Compute Optimization (VM)\"?", "c": ["Input/Output Operations Per Second — a measure of storage performance.", "Using provider-operated services instead of self-managed infrastructure to reduce operational overhead.", "The actual amount of data successfully transferred over a network connection in a given time.", "Using virtual machines as the compute resource type for a workload."], "a": 3, "e": "Using virtual machines as the compute resource type for a workload. Appropriate for workloads needing full OS control and long-running processes."}, {"obj": "4.4", "q": "Why does this matter on the exam and in practice? \"Significantly increases risk since a compromised privileged container can affect the underlying host.\" — which term does this explain?", "c": ["Data at Rest Encryption", "Data in Transit Encryption", "Patching (Security)", "Privileged Container"], "a": 3, "e": "Significantly increases risk since a compromised privileged container can affect the underlying host. This describes Privileged Container (\"A container granted elevated access to the host system's resources.\")."}, {"obj": "4.6", "q": "Which concept is described by the phrase: \"Continuously observing system and security events for signs of malicious activity.\"?", "c": ["Vulnerability Exploitation — Outdated Software", "Metadata Attack", "Event Monitoring (Security)", "Unnecessary Open Ports"], "a": 2, "e": "\"Continuously observing system and security events for signs of malicious activity.\" describes Event Monitoring (Security). Provides the raw visibility needed to detect an attack in progress."}, {"obj": "1.2", "q": "A description reads: \"Temporarily extending an on-premises workload into the public cloud to handle demand spikes.\" Which term does this describe?", "c": ["Cold Site", "RTO", "Cloud Bursting", "Warm Site"], "a": 2, "e": "\"Temporarily extending an on-premises workload into the public cloud to handle demand spikes.\" describes Cloud Bursting. Lets an organization keep steady-state workloads on cheaper private infrastructure while still handling peak load."}, {"obj": "2.1", "q": "Several universities in a state want to share cloud infrastructure that meets a common set of research-compliance requirements, without opening it to the general public. Which model fits?", "c": ["Public cloud", "Private cloud", "Community cloud", "Hybrid cloud"], "a": 2, "e": "A community cloud is shared among organizations with common concerns, such as shared compliance or governance needs."}, {"obj": "5.2", "q": "\"Build (CI/CD)\" is best defined as which of the following?", "c": ["A code or artifact repository restricted to authorized users/systems.", "A packaged container image produced and stored as a build output.", "Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions.", "Compiling/packaging source code into a deployable artifact."], "a": 3, "e": "Compiling/packaging source code into a deployable artifact. The step that transforms source code into something that can actually be run or deployed."}, {"obj": "6.2", "q": "\"HTTP Status Codes\" is best defined as which of the following?", "c": ["An incorrect entry in a route table sending traffic to the wrong destination.", "Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500).", "Network Time Protocol — synchronizes system clocks across a network.", "Two networks using conflicting/duplicate IP address ranges."], "a": 1, "e": "Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500). Provide the first clue about whether a problem is client-side, server-side, or related to routing/access."}, {"obj": "4.2", "q": "A healthcare company must retain certain patient records for a legally mandated period under national health data regulations. What type of retention requirement is this?", "c": ["Contractual retention", "Regulatory retention", "Litigation hold", "Data locality preference"], "a": 1, "e": "Regulatory retention is a data retention requirement mandated by law or industry regulation, with legal consequences for non-compliance, distinct from purely contractual or internal preferences."}, {"obj": "1.10", "q": "How would you most accurately define \"Network Latency\"?", "c": ["Using virtual machines as the compute resource type for a workload.", "Automated coordination of workload deployment, scaling, and lifecycle management.", "The time delay for data to travel between two points on a network.", "The rate of data transfer to/from a storage system, usually measured in MB/s or GB/s."], "a": 2, "e": "The time delay for data to travel between two points on a network. A critical factor when placing workloads and choosing regions/AZs for latency-sensitive applications."}, {"obj": "1.4", "q": "Given the description \"A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost.\", which term is being defined?", "c": ["File Storage", "Hot Storage Tier", "Object Storage", "Cold Storage Tier"], "a": 1, "e": "\"A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost.\" describes Hot Storage Tier. Appropriate for active production data that needs to be retrieved quickly and often."}, {"obj": "4.6", "q": "In cloud computing terminology, \"Ransomware\" refers to which of the following?", "c": ["Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources.", "Unauthorized use of a system's computing resources to mine cryptocurrency.", "Malicious software designed to damage, disrupt, or gain unauthorized access to a system.", "Malware that encrypts a victim's data and demands payment for the decryption key."], "a": 3, "e": "Malware that encrypts a victim's data and demands payment for the decryption key. Makes immutable, offline backups especially critical, since online backups can also be encrypted."}, {"obj": "5.3", "q": "An administrator explains the importance of a concept: \"Reduces over-fetching/under-fetching of data compared to traditional REST endpoints.\" What concept is this?", "c": ["SOAP", "RPC", "Web Sockets", "GraphQL"], "a": 3, "e": "Reduces over-fetching/under-fetching of data compared to traditional REST endpoints. This describes GraphQL (\"A query language for APIs that lets clients request exactly the data they need.\")."}, {"obj": "3.1", "q": "Which of the following is the correct expansion of \"RACI\"?", "c": ["Common Vulnerability Scoring System", "Universal Serial Bus", "Responsible, Accountable, Consulted, Informed", "Virtual Machine"], "a": 2, "e": "RACI stands for Responsible, Accountable, Consulted, Informed. A framework for defining roles and responsibilities in a process."}, {"obj": "2.5", "q": "A company provisioning a new workload needs to decide between a region in North America and one in Europe. Which requirement category most directly influences this decision if the customer base is entirely European and data residency laws apply?", "c": ["Compute requirements only", "Compliance and network requirements (data residency and latency)", "Availability requirements only", "None of these matter for region selection"], "a": 1, "e": "Both compliance (data residency laws) and network requirements (latency for European users) directly drive the choice to provision in a European region."}, {"obj": "1.3", "q": "Which of the following terms fits this definition: \"A device or service that filters network traffic based on defined rules.\"?", "c": ["Network Load Balancer", "CDN", "Route Table", "Firewall"], "a": 3, "e": "\"A device or service that filters network traffic based on defined rules.\" describes Firewall. The primary control for restricting which traffic is allowed in/out of a cloud network segment."}, {"obj": "5.4", "q": "Which term is most closely associated with this real-world importance: \"One of the most established tools for orchestrating build, test, and deployment automation.\"?", "c": ["Jenkins", "Terraform", "Kubernetes", "ELK Stack"], "a": 0, "e": "One of the most established tools for orchestrating build, test, and deployment automation. This describes Jenkins (\"A widely used open-source automation server for building CI/CD pipelines.\")."}, {"obj": "4.3", "q": "Which term is most closely associated with this real-world importance: \"Makes stolen credentials alone insufficient for an attacker to gain access.\"?", "c": ["SSH", "RDP", "MFA", "CLI"], "a": 2, "e": "Makes stolen credentials alone insufficient for an attacker to gain access. This describes MFA (\"Multifactor Authentication — requiring two or more independent verification factors to log in.\")."}, {"obj": "4.3", "q": "A colleague says: \"Reduces the attack surface by ensuring administrative access doesn't require directly exposing every resource.\" Which concept are they describing?", "c": ["Role-Based Access Control", "SDK", "RDP", "Bastion Host"], "a": 3, "e": "Reduces the attack surface by ensuring administrative access doesn't require directly exposing every resource. This describes Bastion Host (\"A hardened server that provides a single, monitored entry point for administrative access into a private network.\")."}, {"obj": "5.3", "q": "A team building a real-time multiplayer game needs the server to instantly push game state updates to all connected players without each player repeatedly requesting updates. What integration technology fits best?", "c": ["REST polling every second", "Web sockets", "SOAP", "A batch file transfer job"], "a": 1, "e": "Web sockets support real-time, low-latency, bidirectional pushes of data, which is well suited to instantly broadcasting game state to connected players."}, {"obj": "1.5", "q": "Which of the following best describes \"Cloud-Provided Managed Service\"?", "c": ["A mechanism that lets services dynamically find the network location of other services.", "A messaging pattern where one event is distributed to multiple downstream consumers/services.", "An architecture where an application is broken into small, independently deployable services.", "A service the cloud provider fully operates (e.g., a managed database), removing the customer's operational burden."], "a": 3, "e": "A service the cloud provider fully operates (e.g., a managed database), removing the customer's operational burden. Reduces administrative overhead at the cost of some control and customization."}, {"obj": "6.3", "q": "An organization discovers that credentials for a service account have been exposed in a misconfigured, publicly accessible log file. What immediate action should be taken?", "c": ["Ignore the finding since logs are rarely accessed by attackers", "Rotate/revoke the exposed credentials immediately and secure the log file's access permissions", "Wait until the next scheduled audit to address it", "Delete the service account entirely with no further investigation"], "a": 1, "e": "Exposed credentials should be immediately rotated/revoked to prevent misuse, and the underlying exposure (public log access) should be fixed to prevent recurrence."}, {"obj": "1.10", "q": "A microservices team wants a lightweight, portable compute unit that can be rapidly scaled and moved between environments with minimal overhead. Which compute type fits best?", "c": ["Dedicated physical servers", "Containers", "Bare-metal-only deployment", "Tape-based compute"], "a": 1, "e": "Containers are lightweight and portable compared to full VMs, making them well suited to rapid scaling and movement between environments."}, {"obj": "1.7", "q": "Which statement accurately describes \"NAS (Virtualization Context)\"?", "c": ["A single hypervisor host running VMs with no clustering.", "Network Attached Storage — shared file-level storage accessible by multiple hosts.", "Storage Area Network — shared block storage accessible by multiple hypervisor hosts.", "A rule keeping specific VMs running on the same (or different) physical host."], "a": 1, "e": "Network Attached Storage — shared file-level storage accessible by multiple hosts. Commonly used for storing VM templates, ISOs, and shared datastores."}, {"obj": "4.6", "q": "Which concept is described by the phrase: \"An attack that abuses a cloud instance's metadata service to steal credentials or configuration data.\"?", "c": ["Malware", "Metadata Attack", "Unnecessary Open Ports", "DDoS"], "a": 1, "e": "\"An attack that abuses a cloud instance's metadata service to steal credentials or configuration data.\" describes Metadata Attack. A cloud-specific attack vector, since metadata services often provide temporary credentials to the instance."}, {"obj": "1.3", "q": "\"Static Route\" is best defined as which of the following?", "c": ["A set of rules that determines where network traffic is directed.", "A manually configured network route that does not change dynamically.", "Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains.", "Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks."], "a": 1, "e": "A manually configured network route that does not change dynamically. Simple and predictable, but requires manual updates if the network topology changes."}, {"obj": "1.5", "q": "Which concept is described by the phrase: \"A mechanism that lets services dynamically find the network location of other services.\"?", "c": ["Fan-Out", "Loosely Coupled Architecture", "Cloud-Provided Managed Service", "Service Discovery"], "a": 3, "e": "\"A mechanism that lets services dynamically find the network location of other services.\" describes Service Discovery. Essential in dynamic cloud-native environments where service instances and IP addresses change constantly."}, {"obj": "2.1", "q": "Which of the following best describes \"On Premises\"?", "c": ["Infrastructure owned by a third-party provider and shared across many customers (multi-tenant).", "Infrastructure dedicated to a single organization, hosted on- or off-premises.", "Infrastructure physically located and managed within the organization's own facilities.", "Infrastructure shared by several organizations with common concerns such as compliance or security requirements."], "a": 2, "e": "Infrastructure physically located and managed within the organization's own facilities. Gives maximum control over hardware and data location, at the cost of full operational responsibility."}, {"obj": "1.4", "q": "A company wants multiple application servers across different VMs to share access to the same set of files using a standard network file protocol. Which storage type is appropriate?", "c": ["Block storage attached to one VM", "File storage (e.g., NFS or SMB)", "Local ephemeral storage", "Archive tier object storage"], "a": 1, "e": "File storage using protocols like NFS or SMB allows multiple clients to simultaneously access a shared file system."}, {"obj": "5.4", "q": "Given the description \"An open-source tool for visualizing metrics and creating monitoring dashboards.\", which term is being defined?", "c": ["Docker", "Grafana", "Ansible", "ELK Stack"], "a": 1, "e": "\"An open-source tool for visualizing metrics and creating monitoring dashboards.\" describes Grafana. Commonly paired with time-series databases to build real-time operational dashboards."}, {"obj": "1.3", "q": "Which statement accurately describes \"SDN\"?", "c": ["A device or service that filters network traffic based on defined rules.", "Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.", "A set of rules that determines where network traffic is directed.", "Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management."], "a": 3, "e": "Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management. Underpins most cloud networking, allowing networks to be defined and changed through code/APIs rather than physical rewiring."}, {"obj": "4.6", "q": "In cloud computing terminology, \"Event Monitoring (Security)\" refers to which of the following?", "c": ["Network ports left open on a system that are not required for its function.", "Malicious software designed to damage, disrupt, or gain unauthorized access to a system.", "Continuously observing system and security events for signs of malicious activity.", "A cloud instance that is running but forgotten, unmonitored, or unmanaged."], "a": 2, "e": "Continuously observing system and security events for signs of malicious activity. Provides the raw visibility needed to detect an attack in progress."}, {"obj": "1.9", "q": "A colleague says: \"Offers maximum control but requires the customer to handle all operational overhead.\" Which concept are they describing?", "c": ["Relational Database", "Provider-Managed Database", "Non-Relational Database", "Self-Managed Database"], "a": 3, "e": "Offers maximum control but requires the customer to handle all operational overhead. This describes Self-Managed Database (\"A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure.\")."}, {"obj": "1.11", "q": "Which of the following terms fits this definition: \"A device that collects data from the physical environment (temperature, motion, etc.).\"?", "c": ["Text Translation", "IoT Sensor", "IoT Transmission Protocol", "Generative AI"], "a": 1, "e": "\"A device that collects data from the physical environment (temperature, motion, etc.).\" describes IoT Sensor. The data-collection endpoint in most IoT architectures, feeding data upstream for processing."}, {"obj": "1.9", "q": "An administrator explains the importance of a concept: \"Better suited for unstructured/semi-structured data and workloads needing horizontal scalability.\" What concept is this?", "c": ["Non-Relational Database", "Self-Managed Database", "Provider-Managed Database", "Relational Database"], "a": 0, "e": "Better suited for unstructured/semi-structured data and workloads needing horizontal scalability. This describes Non-Relational Database (\"A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs.\")."}, {"obj": "1.2", "q": "The acronym \"AI\" stands for:", "c": ["Graphics Processing Unit", "Border Gateway Protocol", "Input/Output Operations Per Second", "Artificial Intelligence"], "a": 3, "e": "AI stands for Artificial Intelligence. Computer systems performing tasks that typically require human intelligence."}, {"obj": "1.5", "q": "Which of the following most accurately describes why cloud-native applications favor small, independently deployable services over a single large codebase?", "c": ["It is always cheaper regardless of scale", "It allows independent teams to develop, test, and deploy their piece of the system without coordinating a single massive release", "It eliminates the need for testing entirely", "It requires less network infrastructure"], "a": 1, "e": "Breaking a system into independently deployable services lets teams work and release independently, avoiding the coordination overhead of one large monolithic release."}, {"obj": "1.5", "q": "Given the description \"An architecture where an application is broken into small, independently deployable services.\", which term is being defined?", "c": ["Fan-Out", "Loosely Coupled Architecture", "Microservices", "Service Discovery"], "a": 2, "e": "\"An architecture where an application is broken into small, independently deployable services.\" describes Microservices. Allows teams to develop, scale, and deploy components independently rather than as one large monolith."}, {"obj": "6.2", "q": "A colleague says: \"Commonly causes routing failures when connecting previously separate networks (e.g., via VPN or peering).\" Which concept are they describing?", "c": ["Network Overlap", "Protocol Deprecation", "Access vs. Trunk Ports", "DHCP (Troubleshooting)"], "a": 0, "e": "Commonly causes routing failures when connecting previously separate networks (e.g., via VPN or peering). This describes Network Overlap (\"Two networks using conflicting/duplicate IP address ranges.\")."}, {"obj": "1.2", "q": "\"Region\" is best defined as which of the following?", "c": ["A basic facility with power and space but no pre-installed equipment.", "A distinct geographic location where a cloud provider operates one or more datacenters.", "Recovery Point Objective — the maximum acceptable amount of data loss, measured in time.", "Continuously checking that a resource or service is up and responding as expected."], "a": 1, "e": "A distinct geographic location where a cloud provider operates one or more datacenters. Choosing the right region affects latency, data sovereignty, and compliance."}, {"obj": "1.8", "q": "Which term is most closely associated with this real-world importance: \"Reduces cost for predictable, steady-state workloads compared to pay-as-you-go pricing.\"?", "c": ["Tagging", "Reserved Resources", "Resource Metering", "Dedicated Host Billing"], "a": 1, "e": "Reduces cost for predictable, steady-state workloads compared to pay-as-you-go pricing. This describes Reserved Resources (\"Pre-purchasing capacity for a discounted rate in exchange for a committed term.\")."}, {"obj": "4.3", "q": "An administrator writes a script that uses text-based commands to create, list, and delete cloud resources without opening a browser. What interface are they using?", "c": ["A web portal", "The CLI", "RDP", "SAML"], "a": 1, "e": "The CLI (Command Line Interface) provides text-based commands for managing cloud resources, popular for scripting and automation."}, {"obj": "4.5", "q": "Given the description \"Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity.\", which term is being defined?", "c": ["IPS/IDS", "IAM Policies", "Network ACL", "WAF"], "a": 0, "e": "\"Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity.\" describes IPS/IDS. IDS alerts on suspicious activity; IPS goes further by actively blocking it in real time."}, {"obj": "4.4", "q": "Which of the following terms fits this definition: \"A container running with restricted access, isolated from the host's sensitive resources.\"?", "c": ["Unprivileged Container", "Zero Trust", "Data at Rest Encryption", "Object Storage Security"], "a": 0, "e": "\"A container running with restricted access, isolated from the host's sensitive resources.\" describes Unprivileged Container. The safer default for container security, limiting the impact of a container-level compromise."}, {"obj": "2.2", "q": "A company performing a blue-green deployment discovers a critical bug immediately after switching all traffic to the new (green) environment. What is the fastest recovery action?", "c": ["Roll forward with a hotfix deployed to green", "Switch traffic back to the still-running blue environment", "Take the entire application offline while investigating", "Perform a rolling deployment to fix green"], "a": 1, "e": "Since blue-green keeps the previous environment (blue) running and unchanged, switching traffic back to it is the fastest way to recover from a bad release."}, {"obj": "4.3", "q": "Select the most accurate description of \"Local User Authentication\":", "c": ["Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.", "Authenticating with credentials stored directly on the system rather than a central directory.", "Allowing users to authenticate using credentials from a separate, trusted identity provider.", "Application Programming Interface — used here for programmatic management/access to cloud resources."], "a": 1, "e": "Authenticating with credentials stored directly on the system rather than a central directory. Simple but doesn't scale well and complicates centralized policy enforcement across many systems."}, {"obj": "3.4", "q": "A software vendor releases a new version with significant new features and some breaking API changes that could affect existing integrations. What type of update is this?", "c": ["A patch", "A minor update", "A major update", "A configuration-only change"], "a": 2, "e": "A major update includes significant new features and potentially breaking changes, requiring more careful testing than a routine patch or minor update."}, {"obj": "4.3", "q": "In cloud computing terminology, \"Discretionary Access Control\" refers to which of the following?", "c": ["Application Programming Interface — used here for programmatic management/access to cloud resources.", "Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.", "An identity layer built on top of OAuth 2.0 used for authentication (proving who you are).", "An access model where the resource owner decides who else can access it."], "a": 3, "e": "An access model where the resource owner decides who else can access it. Flexible, but relies on individual owners consistently applying good judgment about access grants."}, {"obj": "3.1", "q": "Select the most accurate description of \"Monitoring Metrics\":", "c": ["Numeric measurements of system behavior (CPU, memory, request rate) collected over time.", "The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.", "Gathering log data from applications, systems, and services into a central location.", "The defined actions taken once an alert is triaged and confirmed to need action."], "a": 0, "e": "Numeric measurements of system behavior (CPU, memory, request rate) collected over time. The foundation of dashboards and alerting used to understand system health."}, {"obj": "3.2", "q": "Which statement accurately describes \"Triggered Scaling — Trending\"?", "c": ["Increasing the resources (CPU/RAM) of an existing instance (scale up).", "An administrator explicitly changing resource capacity rather than relying on automation.", "Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU).", "Scaling in response to a specific event (like a message queue depth increasing)."], "a": 2, "e": "Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU). Reacts to gradual changes in demand rather than short spikes."}, {"obj": "3.3", "q": "Which of the following best describes \"Backup Retention (Ops)\"?", "c": ["Verifying that backed-up data has not been corrupted.", "The defined frequency and timing of backup jobs.", "Restoring individual files or specific data items rather than an entire dataset.", "How long backup copies are kept before being deleted or overwritten."], "a": 3, "e": "How long backup copies are kept before being deleted or overwritten. Balances storage cost against the need to recover from an issue discovered after some delay."}, {"obj": "6.2", "q": "In cloud computing terminology, \"Missing Route\" refers to which of the following?", "c": ["Network Address Translation — translates private addresses to a public address for routing.", "A connectivity failure caused by two systems using different or mismatched protocol versions.", "Running out of available addresses within a defined IP range or subnet.", "A required network path that has not been defined in a route table."], "a": 3, "e": "A required network path that has not been defined in a route table. Traffic destined for that path is silently dropped, a common and often overlooked cloud networking issue."}, {"obj": "4.6", "q": "An employee clicks a link in an email that appears to be from IT support and enters their credentials on a fake login page. What attack type is this?", "c": ["DDoS", "Phishing", "Cryptojacking", "Metadata attack"], "a": 1, "e": "Phishing is a social engineering attack that tricks a user into revealing credentials, one of the most common initial access vectors."}, {"obj": "4.5", "q": "A security team wants visibility into attempted SQL injection attacks specifically targeting their web application's login form. Which control's logs would be most directly relevant?", "c": ["A network ACL's logs", "A WAF's logs", "DLP logs", "DDoS protection logs only"], "a": 1, "e": "A WAF specifically inspects and logs application-layer attacks like SQL injection attempts against a web application, unlike network-layer controls."}, {"obj": "1.8", "q": "An administrator explains the importance of a concept: \"Enables cost allocation, automation, and organization of resources by project, owner, or environment.\" What concept is this?", "c": ["Resource Metering", "Tagging", "Dedicated Host Billing", "Reserved Resources"], "a": 1, "e": "Enables cost allocation, automation, and organization of resources by project, owner, or environment. This describes Tagging (\"Attaching key-value metadata labels to cloud resources.\")."}, {"obj": "2.4", "q": "After deploying infrastructure via IaC, an engineer manually changes a firewall rule directly in the console. What process would catch this discrepancy?", "c": ["Drift detection", "Code review", "Backup validation", "Service discovery"], "a": 0, "e": "Drift detection identifies when a resource's actual state no longer matches its defined IaC configuration, catching manual out-of-band changes."}, {"obj": "3.4", "q": "An administrator explains the importance of a concept: \"Requires more careful testing than minor updates due to a higher risk of compatibility issues.\" What concept is this?", "c": ["Persistent Data", "Lifecycle Testing", "Minor Update", "Major Update"], "a": 3, "e": "Requires more careful testing than minor updates due to a higher risk of compatibility issues. This describes Major Update (\"A significant version update that may include new features and breaking changes.\")."}, {"obj": "1.4", "q": "What does the abbreviation \"NVME\" stand for?", "c": ["Recovery Point Objective", "Internet Small Computer System Interface", "Continuous Integration/Continuous Deployment", "Non-Volatile Memory Express"], "a": 3, "e": "NVME stands for Non-Volatile Memory Express. A high-speed protocol for SSDs connected via the PCIe bus."}, {"obj": "5.1", "q": "Two teammates independently review a proposed code change, leave comments about a potential bug, and request revisions before approving it. What practice is this?", "c": ["Code push", "Code commit", "Code review", "Branch management only"], "a": 2, "e": "Code review is the practice of having other team members examine proposed changes before merging, catching bugs and design issues early."}, {"obj": "1.6", "q": "A company wants to ensure every deployment uses a known-good, versioned container image rather than an arbitrary or untracked build. What practice supports this?", "c": ["Avoiding image registries entirely", "Pulling images from a versioned image registry with tagged releases", "Running containers with no image source tracking", "Disabling persistent volumes"], "a": 1, "e": "Using a versioned image registry with proper tagging ensures deployments consistently use known, traceable image versions."}, {"obj": "3.2", "q": "A company configures autoscaling based on a sustained upward trend in average response time over the past hour, rather than reacting to any single momentary spike. What scaling approach is this?", "c": ["Triggered scaling — trending", "Manual scaling", "Scheduled scaling", "Vertical scaling only"], "a": 0, "e": "Trend-based triggered scaling reacts to a sustained pattern over time rather than an instantaneous threshold crossing, useful for gradual demand changes."}, {"obj": "4.5", "q": "A company configures rules controlling inbound and outbound traffic at the subnet level within its VPC, distinct from instance-level firewall rules. What is being configured?", "c": ["A network security group", "A network ACL", "A WAF", "DLP rules"], "a": 1, "e": "Network ACLs operate at the subnet/network level, controlling traffic in and out of a subnet, distinct from instance-level security groups."}, {"obj": "4.3", "q": "Select the most accurate description of \"SDK\":", "c": ["Software Development Kit — a set of libraries/tools that let developers programmatically interact with a cloud platform.", "Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.", "Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.", "A graphical, browser-based interface for managing cloud resources."], "a": 0, "e": "Software Development Kit — a set of libraries/tools that let developers programmatically interact with a cloud platform. Simplifies calling cloud provider APIs from within application code."}, {"obj": "2.3", "q": "Which migration strategy typically requires the most engineering effort but yields the greatest long-term scalability and cost-efficiency benefits?", "c": ["Rehost", "Retain", "Re-architect", "Retire"], "a": 2, "e": "Re-architecting requires the most effort since it substantially redesigns the application, but it unlocks the greatest long-term benefits from cloud-native scalability and cost efficiency."}, {"obj": "4.5", "q": "A large volume of malicious traffic is aimed at overwhelming a public-facing cloud application's bandwidth. What control specifically mitigates this?", "c": ["DLP", "DDoS protection", "IAM policies", "Network ACL"], "a": 1, "e": "DDoS protection services absorb or filter malicious traffic volumes specifically designed to overwhelm a target."}, {"obj": "3.3", "q": "In cloud computing terminology, \"Backup Replication\" refers to which of the following?", "c": ["Backs up only data changed since the last backup of any type.", "Restoring data directly onto the original system/location.", "Backs up all data changed since the last full backup.", "Copying backup data to another location (often off-site or another region)."], "a": 3, "e": "Copying backup data to another location (often off-site or another region). Protects against a disaster affecting the primary backup location."}, {"obj": "2.3", "q": "How would you most accurately define \"Vendor Lock-In\"?", "c": ["A migration strategy that keeps a workload where it currently is, deferring migration.", "A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture.", "Moving workloads out of the cloud back to local infrastructure.", "Difficulty moving away from a cloud provider due to reliance on proprietary services or formats."], "a": 3, "e": "Difficulty moving away from a cloud provider due to reliance on proprietary services or formats. A key risk consideration when architecting for portability across multiple providers."}, {"obj": "6.1", "q": "Which statement accurately describes \"Oversubscription\"?", "c": ["A deployment failing because the deploying identity lacks sufficient rights.", "Allocating more virtual resources than the underlying physical capacity can truly support.", "A provider intentionally limiting the rate of API calls a customer can make.", "IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated."], "a": 1, "e": "Allocating more virtual resources than the underlying physical capacity can truly support. Can cause performance degradation or failed provisioning if too many workloads compete for the same physical resources."}, {"obj": "4.4", "q": "A cloud provider publishes its own specific hardening recommendations for securing its particular managed database service, supplementing general industry benchmarks. What is this called?", "c": ["A CIS Benchmark", "A vendor-specific benchmark", "A CVE", "A SOC 2 report"], "a": 1, "e": "Vendor-specific benchmarks provide hardening guidance tailored to a particular vendor's specific product, complementing general-purpose benchmarks like CIS."}, {"obj": "1.10", "q": "A cost-conscious team running a well-known, standardized workload (like a message queue) decides to use the provider's managed offering instead of self-hosting it. What optimization principle does this reflect?", "c": ["Avoiding all managed services", "Leveraging managed services to reduce operational overhead for standardized functionality", "Maximizing self-managed infrastructure regardless of standardization", "Ignoring cost considerations entirely"], "a": 1, "e": "Using managed services for standardized, well-understood functionality reduces operational overhead compared to self-managing every component."}, {"obj": "5.1", "q": "Which of the following terms fits this definition: \"A formal request to merge a proposed code change into a shared branch, typically triggering review.\"?", "c": ["Code Review", "Version Management", "Pull Request", "Branch Management"], "a": 2, "e": "\"A formal request to merge a proposed code change into a shared branch, typically triggering review.\" describes Pull Request. The standard workflow mechanism for reviewing and discussing changes before merging."}, {"obj": "1.4", "q": "\"Hot Storage Tier\" is best defined as which of the following?", "c": ["Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.", "Storage that manages data as discrete objects with metadata, accessed via an API (e.g., S3).", "A storage tier for infrequently accessed data, offering lower cost with slower retrieval.", "A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost."], "a": 3, "e": "A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost. Appropriate for active production data that needs to be retrieved quickly and often."}, {"obj": "4.6", "q": "\"Zombie Instance\" is best defined as which of the following?", "c": ["Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources.", "Continuously observing system and security events for signs of malicious activity.", "A cloud instance that is running but forgotten, unmonitored, or unmanaged.", "A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email."], "a": 2, "e": "A cloud instance that is running but forgotten, unmonitored, or unmanaged. Represents both wasted cost and an unpatched, unmonitored attack surface."}, {"obj": "5.4", "q": "A team wants to define their build, test, and deployment pipeline directly alongside their code in their GitHub repository, triggered automatically on every push. Which tool fits best?", "c": ["Terraform", "GitHub Actions", "Grafana", "Ansible"], "a": 1, "e": "GitHub Actions is a CI/CD automation feature built into GitHub, letting teams define pipelines that run in response to repository events like pushes."}, {"obj": "4.3", "q": "After a user logs in successfully, the system issues a short-lived credential for that session rather than requiring the user's password to be resent with every request. What authentication approach is this?", "c": ["Local user authentication", "Token-based authentication", "Directory-based authentication only", "Discretionary access control"], "a": 1, "e": "Token-based authentication issues a temporary token after initial login, reducing exposure of long-term credentials and supporting short-lived, revocable sessions."}, {"obj": "2.3", "q": "A company completely redesigns a legacy monolith into microservices to take full advantage of cloud-native scalability. What strategy is this?", "c": ["Rehost", "Replatform", "Re-architect", "Retain"], "a": 2, "e": "Re-architecting substantially redesigns an application to be cloud-native, requiring the most effort but yielding the greatest long-term benefit."}, {"obj": "1.1", "q": "Which concept is described by the phrase: \"Software as a Service — delivers a fully managed application to end users over the internet.\"?", "c": ["PaaS", "FaaS", "IaaS", "SaaS"], "a": 3, "e": "\"Software as a Service — delivers a fully managed application to end users over the internet.\" describes SaaS. The provider manages everything except the user's own data and configuration within the app."}, {"obj": "6.1", "q": "Why does this matter on the exam and in practice? \"One of the most common causes of failed automated deployments in cloud environments.\" — which term does this explain?", "c": ["Resource Allocation Misconfiguration", "API Throttling", "Permission Issues (Deployment)", "Incompatibility (Deployment)"], "a": 2, "e": "One of the most common causes of failed automated deployments in cloud environments. This describes Permission Issues (Deployment) (\"A deployment failing because the deploying identity lacks sufficient rights.\")."}, {"obj": "4.4", "q": "Select the most accurate description of \"Data at Rest Encryption\":", "c": ["A security model that assumes no user or device should be trusted by default, even inside the network perimeter.", "Encrypting stored data so it remains unreadable without the correct key.", "Encrypting data as it moves across a network (e.g., via TLS).", "A set of vendor-neutral, consensus-based configuration hardening guidelines."], "a": 1, "e": "Encrypting stored data so it remains unreadable without the correct key. Protects data even if the underlying storage media is stolen or improperly accessed."}, {"obj": "6.1", "q": "In cloud computing terminology, \"Partial Outage\" refers to which of the following?", "c": ["A deployment failing because the deploying identity lacks sufficient rights.", "A degradation where some, but not all, functionality or users are affected.", "Incorrectly assigned CPU, memory, or storage limits for a workload.", "A complete loss of service availability."], "a": 1, "e": "A degradation where some, but not all, functionality or users are affected. Still requires prompt attention but may allow more measured troubleshooting than a full outage."}, {"obj": "2.1", "q": "Which of the following best describes \"Private Cloud\"?", "c": ["A deployment model combining private/on-premises infrastructure with public cloud resources.", "Infrastructure owned by a third-party provider and shared across many customers (multi-tenant).", "Infrastructure shared by several organizations with common concerns such as compliance or security requirements.", "Infrastructure dedicated to a single organization, hosted on- or off-premises."], "a": 3, "e": "Infrastructure dedicated to a single organization, hosted on- or off-premises. Offers greater control and customization at higher cost than public cloud."}, {"obj": "4.6", "q": "A company's monitoring detects unusually high outbound data transfer volume from a database server to an external destination overnight. What should be suspected first?", "c": ["A routine scheduled patch install", "Potential data exfiltration by malware or a compromised account", "A normal load balancer health check", "A DNS zone transfer performed automatically"], "a": 1, "e": "Unusually high outbound data transfer to an external destination, especially overnight, is a strong indicator of potential data exfiltration by malware or a compromised account."}, {"obj": "1.8", "q": "A finance team wants to break down cloud spending by department and project across hundreds of resources. What should be applied to every resource to enable this?", "c": ["Reserved pricing", "Tagging with key-value metadata", "Spot instance bidding", "Dedicated hosting"], "a": 1, "e": "Tagging resources with metadata like department or project enables detailed cost allocation and reporting across the environment."}, {"obj": "1.7", "q": "A colleague says: \"Used to keep related VMs together for performance, or apart for redundancy (anti-affinity).\" Which concept are they describing?", "c": ["NAS (Virtualization Context)", "Local Storage (Virtualization)", "Stand-Alone Virtualization", "Host Affinity"], "a": 3, "e": "Used to keep related VMs together for performance, or apart for redundancy (anti-affinity). This describes Host Affinity (\"A rule keeping specific VMs running on the same (or different) physical host.\")."}, {"obj": "3.1", "q": "After an alert is confirmed as a genuine critical issue, the on-call engineer follows a documented runbook to restart the affected service and notify stakeholders. What stage of the observability lifecycle is this?", "c": ["Alert triage", "Alert response", "Log aggregation", "Monitoring metric collection"], "a": 1, "e": "Alert response is the defined action taken once an alert is triaged and confirmed to need action, turning detection into actual resolution."}, {"obj": "5.2", "q": "Which term is most closely associated with this real-world importance: \"Provides a versioned, portable, reusable deployment unit for containerized workloads.\"?", "c": ["CI/CD Automation", "Private Repository", "Container Image Artifact", "CI/CD Testing"], "a": 2, "e": "Provides a versioned, portable, reusable deployment unit for containerized workloads. This describes Container Image Artifact (\"A packaged container image produced and stored as a build output.\")."}, {"obj": "4.6", "q": "CPU usage on several cloud instances has spiked dramatically with no corresponding increase in legitimate workload, and cloud costs have risen unexpectedly. What should be suspected?", "c": ["A DDoS attack", "Cryptojacking", "A DNS misconfiguration", "A licensing issue"], "a": 1, "e": "Cryptojacking abuses compute resources to mine cryptocurrency, often surfacing as unexplained high CPU usage and increased costs."}, {"obj": "4.6", "q": "How would you most accurately define \"Vulnerability Exploitation — Human Error\"?", "c": ["Malware that encrypts a victim's data and demands payment for the decryption key.", "Malicious software designed to damage, disrupt, or gain unauthorized access to a system.", "An attack that succeeds due to a mistake made by an authorized user (misconfiguration, mishandling credentials, etc.).", "A departure from a system's established normal behavior pattern."], "a": 2, "e": "An attack that succeeds due to a mistake made by an authorized user (misconfiguration, mishandling credentials, etc.). Highlights that technical controls alone can't fully prevent security incidents caused by human mistakes."}, {"obj": "1.4", "q": "Which statement accurately describes \"File Storage\"?", "c": ["A storage tier for infrequently accessed data, offering lower cost with slower retrieval.", "Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB).", "A storage tier for data accessed less frequently than hot data, balancing cost and access speed.", "Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O."], "a": 1, "e": "Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB). Ideal for shared application data and home directories accessed by multiple servers simultaneously."}, {"obj": "1.3", "q": "How would you most accurately define \"VLAN\"?", "c": ["A manually configured network route that does not change dynamically.", "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port.", "Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains.", "A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers)."], "a": 2, "e": "Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains. Separates traffic types on shared physical/virtual network infrastructure."}, {"obj": "1.8", "q": "How would you most accurately define \"Dedicated Host Billing\"?", "c": ["Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice.", "Tracking actual consumption of cloud resources for billing and capacity planning purposes.", "Pre-purchasing capacity for a discounted rate in exchange for a committed term.", "A billing model where a customer pays for an entire physical host, regardless of utilization."], "a": 3, "e": "A billing model where a customer pays for an entire physical host, regardless of utilization. Useful for licensing or compliance requirements that need physical isolation from other tenants."}, {"obj": "4.6", "q": "A colleague says: \"Often detected through unexplained high CPU usage and increased cloud compute costs.\" Which concept are they describing?", "c": ["Zombie Instance", "Metadata Attack", "Cryptojacking", "Event Monitoring (Security)"], "a": 2, "e": "Often detected through unexplained high CPU usage and increased cloud compute costs. This describes Cryptojacking (\"Unauthorized use of a system's computing resources to mine cryptocurrency.\")."}, {"obj": "4.3", "q": "Which statement accurately describes \"SDK\"?", "c": ["Software Development Kit — a set of libraries/tools that let developers programmatically interact with a cloud platform.", "Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.", "Granting permissions based on a user's assigned role rather than to each individual directly.", "Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system."], "a": 0, "e": "Software Development Kit — a set of libraries/tools that let developers programmatically interact with a cloud platform. Simplifies calling cloud provider APIs from within application code."}, {"obj": "6.3", "q": "A colleague says: \"A very common real-world cause of cloud breaches, often via credentials accidentally committed to source control.\" Which concept are they describing?", "c": ["Cipher Suite Deprecation", "Leaked Credentials", "Privilege Escalation (Troubleshooting)", "Unauthorized Software"], "a": 1, "e": "A very common real-world cause of cloud breaches, often via credentials accidentally committed to source control. This describes Leaked Credentials (\"Authentication credentials that have been exposed, such as in code repositories or logs.\")."}, {"obj": "6.2", "q": "A colleague says: \"Highlights the need to track and update deprecated protocol usage before it causes an outage.\" Which concept are they describing?", "c": ["DNS (Troubleshooting)", "Protocol Deprecation", "NAT (Troubleshooting)", "Protocol Incompatibility"], "a": 1, "e": "Highlights the need to track and update deprecated protocol usage before it causes an outage. This describes Protocol Deprecation (\"A connectivity failure caused by a system relying on a protocol version the other side no longer supports.\")."}, {"obj": "3.4", "q": "Given the description \"Validating changes (patches, updates, configuration) before applying them broadly.\", which term is being defined?", "c": ["Major Update", "Lifecycle Testing", "Decommissioning — End of Life", "Ephemeral Data"], "a": 1, "e": "\"Validating changes (patches, updates, configuration) before applying them broadly.\" describes Lifecycle Testing. Reduces the risk that a routine update introduces a new production issue."}, {"obj": "1.3", "q": "A company needs a private, dedicated, low-latency connection between its datacenter and its cloud provider, without traversing the public internet. What should it provision?", "c": ["A site-to-site VPN", "A dedicated connection (e.g., Direct Connect/ExpressRoute)", "A CDN", "A public load balancer"], "a": 1, "e": "A dedicated connection provides a private physical link directly to the provider, offering more consistent performance than a VPN over the internet."}, {"obj": "1.6", "q": "Which of the following best describes \"Image Registry\"?", "c": ["Binding a container's internal port to a port on the host or load balancer.", "Automated management of container deployment, scaling, and healing (e.g., Kubernetes).", "A single container running in isolation without orchestration.", "A repository for storing and distributing container images (e.g., Docker Hub, a private registry)."], "a": 3, "e": "A repository for storing and distributing container images (e.g., Docker Hub, a private registry). Provides a central, versioned source for pulling container images during deployment."}, {"obj": "1.2", "q": "Select the most accurate description of \"Hot Site\":", "c": ["Using services from more than one public cloud provider simultaneously.", "An isolated location within a region with independent power, cooling, and networking.", "Recovery Point Objective — the maximum acceptable amount of data loss, measured in time.", "A fully equipped, continuously running DR site that can take over almost immediately."], "a": 3, "e": "A fully equipped, continuously running DR site that can take over almost immediately. Offers the shortest RTO but is the most expensive DR option to maintain."}, {"obj": "1.5", "q": "A team migrates a large, tightly interwoven application where every module directly calls internal functions of every other module. What is this an example of, as opposed to cloud-native design?", "c": ["Loosely coupled architecture", "A tightly coupled monolithic design", "Microservices", "Service discovery"], "a": 1, "e": "Direct internal dependencies between all modules describe a tightly coupled monolith, the opposite of the loosely coupled, independently deployable cloud-native ideal."}, {"obj": "2.3", "q": "Which of the following terms fits this definition: \"Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.\"?", "c": ["On-Premises-to-Cloud Migration", "Retain", "Vendor Lock-In", "Rehost"], "a": 2, "e": "\"Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.\" describes Vendor Lock-In. A key risk consideration when architecting for portability across multiple providers."}, {"obj": "5.2", "q": "In cloud computing terminology, \"CI/CD Workflow\" refers to which of the following?", "c": ["Automatically running tests against code as part of the pipeline.", "Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions.", "Incorporating security scanning and checks into the automated pipeline.", "The defined sequence of automated stages a change passes through from commit to deployment."], "a": 3, "e": "The defined sequence of automated stages a change passes through from commit to deployment. Documents and enforces a consistent, repeatable delivery process."}, {"obj": "5.4", "q": "Select the most accurate description of \"Ansible\":", "c": ["A CI/CD automation feature built into GitHub for running workflows in response to repository events.", "A platform for building, running, and managing containers.", "An open-source platform for automating deployment, scaling, and management of containerized applications.", "An open-source, agentless automation tool used for configuration management and orchestration."], "a": 3, "e": "An open-source, agentless automation tool used for configuration management and orchestration. Uses simple YAML playbooks to automate repetitive configuration tasks across many systems."}, {"obj": "4.4", "q": "Given the description \"Access controls and encryption settings applied to object storage buckets/containers.\", which term is being defined?", "c": ["Object Storage Security", "Zero Trust", "API Security", "Secrets Management"], "a": 0, "e": "\"Access controls and encryption settings applied to object storage buckets/containers.\" describes Object Storage Security. Misconfigured object storage permissions are a very common real-world cause of public data exposure."}, {"obj": "3.1", "q": "Why does this matter on the exam and in practice? \"The foundation of dashboards and alerting used to understand system health.\" — which term does this explain?", "c": ["Monitoring Metrics", "Alert Triage", "Tracing", "Log Retention"], "a": 0, "e": "The foundation of dashboards and alerting used to understand system health. This describes Monitoring Metrics (\"Numeric measurements of system behavior (CPU, memory, request rate) collected over time.\")."}, {"obj": "4.5", "q": "Which of the following is the correct expansion of \"ACL\"?", "c": ["Access Control List", "Virtual LAN", "Infrastructure as Code", "Transport Layer Security"], "a": 0, "e": "ACL stands for Access Control List. A list of rules attached to a resource that allows or denies specific traffic or users."}, {"obj": "3.4", "q": "A company's patch management process requires all major updates to pass through lifecycle testing in a staging environment before production deployment, but allows security patches to bypass this process during active exploitation. What does this policy reflect?", "c": ["A blanket rule with no risk-based exceptions", "A risk-based approach balancing thorough testing against the urgency of an actively exploited vulnerability", "A policy that ignores security entirely", "A requirement that all updates be applied immediately with no testing ever"], "a": 1, "e": "This policy balances the general need for lifecycle testing against the urgency of patching an actively exploited vulnerability, an example of risk-based prioritization."}, {"obj": "3.4", "q": "Which of the following best describes \"Persistent Data\"?", "c": ["Retiring or upgrading a resource because the vendor no longer provides support/patches for it.", "Data that must be retained beyond the life of the process or instance that created it.", "Validating changes (patches, updates, configuration) before applying them broadly.", "A smaller update, typically with bug fixes and small improvements."], "a": 1, "e": "Data that must be retained beyond the life of the process or instance that created it. Requires durable storage and appropriate backup strategy since it represents lasting business value."}, {"obj": "6.3", "q": "An administrator explains the importance of a concept: \"Common after a platform disables old, insecure ciphers for security reasons, breaking legacy clients.\" What concept is this?", "c": ["Leaked Credentials", "Software Vulnerability Issues", "Privilege Escalation (Troubleshooting)", "Cipher Suite Deprecation"], "a": 3, "e": "Common after a platform disables old, insecure ciphers for security reasons, breaking legacy clients. This describes Cipher Suite Deprecation (\"A connectivity/security failure caused by relying on an outdated, no-longer-supported encryption cipher suite.\")."}, {"obj": "5.2", "q": "Which of the following best describes \"CI/CD Automation\"?", "c": ["A packaged virtual machine image produced and stored as a build output.", "Incorporating security scanning and checks into the automated pipeline.", "Releasing built and tested code to a target environment (e.g., production).", "Automatically building, testing, and deploying code changes with minimal manual intervention."], "a": 3, "e": "Automatically building, testing, and deploying code changes with minimal manual intervention. Reduces human error and speeds up the delivery of software changes."}, {"obj": "4.4", "q": "A security team requires every access request, even from devices already inside the corporate network, to be continuously verified rather than automatically trusted. What security model is this?", "c": ["Perimeter-only security", "Zero Trust", "Discretionary access control", "A single-factor VPN model"], "a": 1, "e": "Zero Trust assumes no implicit trust for any user or device, requiring continuous verification of identity and context for every access request, regardless of network location."}, {"obj": "5.4", "q": "The acronym \"ELK\" stands for:", "c": ["Common Weakness Scoring System", "Virtual Desktop Infrastructure", "JavaScript Object Notation", "Elasticsearch, Logstash, and Kibana"], "a": 3, "e": "ELK stands for Elasticsearch, Logstash, and Kibana. A common open-source stack for log aggregation, processing, and visualization."}, {"obj": "1.7", "q": "A small business runs a single hypervisor host with several VMs and has no plan for failover if that host fails. What virtualization approach is this?", "c": ["Clustering", "Stand-alone virtualization", "Host affinity", "Hardware pass-through"], "a": 1, "e": "A single hypervisor host with no clustering for failover is stand-alone virtualization, offering simplicity but no automatic recovery if the host fails."}, {"obj": "3.2", "q": "Which of the following terms fits this definition: \"Adding more instances of a resource to handle increased load (scale out).\"?", "c": ["Triggered Scaling — Event", "Horizontal Scaling", "Triggered Scaling — Load", "Scheduled Scaling"], "a": 1, "e": "\"Adding more instances of a resource to handle increased load (scale out).\" describes Horizontal Scaling. Improves both capacity and redundancy, and is the standard scaling approach in cloud-native design."}, {"obj": "6.2", "q": "Given the description \"Dynamic Host Configuration Protocol — automatically assigns IP addressing information to hosts.\", which term is being defined?", "c": ["NAT (Troubleshooting)", "Network Overlap", "VLAN Misconfigured Tags", "DHCP (Troubleshooting)"], "a": 3, "e": "\"Dynamic Host Configuration Protocol — automatically assigns IP addressing information to hosts.\" describes DHCP (Troubleshooting). A failed DHCP service can leave hosts without any usable network configuration."}, {"obj": "2.1", "q": "Which of the following best describes \"Public Cloud\"?", "c": ["Infrastructure physically located and managed within the organization's own facilities.", "Infrastructure owned by a third-party provider and shared across many customers (multi-tenant).", "Infrastructure dedicated to a single organization, hosted on- or off-premises.", "A deployment model combining private/on-premises infrastructure with public cloud resources."], "a": 1, "e": "Infrastructure owned by a third-party provider and shared across many customers (multi-tenant). Lowest upfront cost and fastest to provision, but less control than private cloud."}, {"obj": "4.3", "q": "How would you most accurately define \"SSH\"?", "c": ["Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources.", "Secure Shell — an encrypted protocol for remote command-line access to cloud resources.", "Authentication using a temporary token issued after initial login, rather than resending credentials each time.", "Authenticating against a centralized directory service (like LDAP or Active Directory)."], "a": 1, "e": "Secure Shell — an encrypted protocol for remote command-line access to cloud resources. The standard way to securely administer Linux-based cloud instances remotely."}, {"obj": "4.3", "q": "Which term is most closely associated with this real-world importance: \"Simplifies calling cloud provider APIs from within application code.\"?", "c": ["Federation", "SDK", "Discretionary Access Control", "Local User Authentication"], "a": 1, "e": "Simplifies calling cloud provider APIs from within application code. This describes SDK (\"Software Development Kit — a set of libraries/tools that let developers programmatically interact with a cloud platform.\")."}, {"obj": "1.10", "q": "\"Network Throughput\" is best defined as which of the following?", "c": ["The time delay for data to travel between two points on a network.", "The actual amount of data successfully transferred over a network connection in a given time.", "A defined sequence of automated steps/tasks that process data or coordinate resources.", "Using Function as a Service as the compute resource type for a workload."], "a": 1, "e": "The actual amount of data successfully transferred over a network connection in a given time. Determines whether a network link can support a workload's data transfer needs."}, {"obj": "1.11", "q": "A smart city deploys traffic sensors that connect to the internet using a low-power wide-area cellular technology suited for remote, battery-powered devices. What IoT concept does this describe?", "c": ["IoT communication (choice of connectivity method)", "Visual recognition", "Text-to-voice", "Generative AI"], "a": 0, "e": "The choice of connectivity method (like low-power cellular) for IoT devices falls under IoT communication, affecting range, power use, and bandwidth."}, {"obj": "1.4", "q": "Which statement accurately describes \"Block Storage\"?", "c": ["Hard Disk Drive — traditional magnetic spinning-platter storage.", "Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.", "Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk.", "Storage that manages data as discrete objects with metadata, accessed via an API (e.g., S3)."], "a": 2, "e": "Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk. Used for OS disks and databases that need low-latency, structured access to storage."}, {"obj": "6.1", "q": "Which of the following would most likely cause a deployment to fail specifically in one particular region while working correctly everywhere else?", "c": ["A global account-wide service quota limit", "That specific region not offering the required managed service (regional service availability)", "A code syntax error in the IaC template", "An expired SSL certificate"], "a": 1, "e": "A region-specific failure while others succeed most likely indicates the target region doesn't offer a required service, a regional service availability issue."}, {"obj": "2.2", "q": "An administrator explains the importance of a concept: \"Keeps the application available throughout the deployment, at the cost of a longer overall rollout window.\" What concept is this?", "c": ["Rolling Deployment", "Blue-Green Deployment", "In-Place Deployment", "Canary Deployment"], "a": 0, "e": "Keeps the application available throughout the deployment, at the cost of a longer overall rollout window. This describes Rolling Deployment (\"Updating instances incrementally, a few at a time, rather than all at once.\")."}, {"obj": "1.10", "q": "\"Managed Services (Optimization)\" is best defined as which of the following?", "c": ["Using provider-operated services instead of self-managed infrastructure to reduce operational overhead.", "The actual amount of data successfully transferred over a network connection in a given time.", "Using Function as a Service as the compute resource type for a workload.", "Using virtual machines as the compute resource type for a workload."], "a": 0, "e": "Using provider-operated services instead of self-managed infrastructure to reduce operational overhead. Frees up staff time from routine maintenance so they can focus on higher-value work."}, {"obj": "1.3", "q": "Why does this matter on the exam and in practice? \"Used for advanced routing scenarios like connecting on-premises networks to the cloud via dedicated connections.\" — which term does this explain?", "c": ["BGP", "Route Table", "Application Gateway", "Subnet"], "a": 0, "e": "Used for advanced routing scenarios like connecting on-premises networks to the cloud via dedicated connections. This describes BGP (\"Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.\")."}, {"obj": "1.5", "q": "Select the most accurate description of \"Loosely Coupled Architecture\":", "c": ["A messaging pattern where one event is distributed to multiple downstream consumers/services.", "A design where components interact through well-defined interfaces with minimal direct dependencies.", "A mechanism that lets services dynamically find the network location of other services.", "An architecture where an application is broken into small, independently deployable services."], "a": 1, "e": "A design where components interact through well-defined interfaces with minimal direct dependencies. Improves resilience and flexibility since one component's changes or failures don't directly break others."}, {"obj": "2.4", "q": "Which statement accurately describes \"IaC Versioning\"?", "c": ["JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates.", "Tracking changes to infrastructure code over time using version control.", "Managing system or application configuration through code rather than manual configuration.", "Validating infrastructure code for syntax, security, and logic before it is applied to real environments."], "a": 1, "e": "Tracking changes to infrastructure code over time using version control. Enables rollback to a known-good configuration and provides an audit trail of infrastructure changes."}, {"obj": "5.3", "q": "A description reads: \"A query language for APIs that lets clients request exactly the data they need.\" Which term does this describe?", "c": ["GraphQL", "RPC", "SOAP", "Web Sockets"], "a": 0, "e": "\"A query language for APIs that lets clients request exactly the data they need.\" describes GraphQL. Reduces over-fetching/under-fetching of data compared to traditional REST endpoints."}, {"obj": "5.3", "q": "\"Event-Driven Architecture\" is best defined as which of the following?", "c": ["A design where components communicate by producing and reacting to events rather than direct calls.", "A protocol providing full-duplex, persistent communication channels over a single TCP connection.", "A query language for APIs that lets clients request exactly the data they need.", "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local."], "a": 0, "e": "A design where components communicate by producing and reacting to events rather than direct calls. Enables loose coupling and scalability, common in cloud-native and microservices designs."}, {"obj": "1.10", "q": "Why does this matter on the exam and in practice? \"Determines whether a network link can support a workload's data transfer needs.\" — which term does this explain?", "c": ["Network Throughput", "IOPS (Optimization)", "Managed Services (Optimization)", "Orchestration (Workload)"], "a": 0, "e": "Determines whether a network link can support a workload's data transfer needs. This describes Network Throughput (\"The actual amount of data successfully transferred over a network connection in a given time.\")."}, {"obj": "4.4", "q": "Which term is most closely associated with this real-world importance: \"Requires continuous verification of identity and context for every access request, not just at the network edge.\"?", "c": ["Unprivileged Container", "Data at Rest Encryption", "File Storage Security", "Zero Trust"], "a": 3, "e": "Requires continuous verification of identity and context for every access request, not just at the network edge. This describes Zero Trust (\"A security model that assumes no user or device should be trusted by default, even inside the network perimeter.\")."}, {"obj": "4.5", "q": "Which concept is described by the phrase: \"Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications.\"?", "c": ["IAM Policies", "IPS/IDS", "WAF", "Endpoint Protection"], "a": 2, "e": "\"Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications.\" describes WAF. Protects against application-layer attacks like SQL injection and cross-site scripting that a normal firewall wouldn't catch."}, {"obj": "3.3", "q": "Why does this matter on the exam and in practice? \"Appropriate when an entire system or dataset needs to be recovered together.\" — which term does this explain?", "c": ["Full Backup", "Bulk Recovery", "Granular Recovery", "Backup Encryption"], "a": 1, "e": "Appropriate when an entire system or dataset needs to be recovered together. This describes Bulk Recovery (\"Restoring a large set of data all at once.\")."}, {"obj": "2.1", "q": "Given the description \"Infrastructure shared by several organizations with common concerns such as compliance or security requirements.\", which term is being defined?", "c": ["On Premises", "Public Cloud", "Community Cloud", "Private Cloud"], "a": 2, "e": "\"Infrastructure shared by several organizations with common concerns such as compliance or security requirements.\" describes Community Cloud. Balances shared cost benefits with more tailored governance than a general public cloud."}, {"obj": "6.2", "q": "Which of the following is the correct expansion of \"ICMP\"?", "c": ["Intrusion Detection System", "Responsible, Accountable, Consulted, Informed", "Internet Control Message Protocol", "Software Development Kit"], "a": 2, "e": "ICMP stands for Internet Control Message Protocol. A protocol used for network diagnostics such as ping and error reporting."}, {"obj": "2.3", "q": "A company assessing its application portfolio for cloud migration determines that one application is critical but not yet ready due to a pending vendor contract renewal. What is the most appropriate strategy for now?", "c": ["Immediately retire the application", "Retain the application until conditions change", "Rehost regardless of readiness", "Refactor immediately without further planning"], "a": 1, "e": "Retain is appropriate when an application isn't yet ready to migrate due to external constraints, deferring the decision until conditions change."}, {"obj": "5.3", "q": "Which term is most closely associated with this real-world importance: \"The most common style for modern web APIs due to its simplicity and statelessness.\"?", "c": ["RPC", "Web Sockets", "REST", "Event-Driven Architecture"], "a": 2, "e": "The most common style for modern web APIs due to its simplicity and statelessness. This describes REST (\"Representational State Transfer — an architectural style for web services using standard HTTP methods.\")."}, {"obj": "5.1", "q": "How would you most accurately define \"Code Push\"?", "c": ["Tracking and organizing different versions of code or configuration over time.", "Saving a snapshot of changes to the local version control history.", "Combining changes from different branches into one.", "Uploading local code changes to a remote/shared repository."], "a": 3, "e": "Uploading local code changes to a remote/shared repository. The action that shares a developer's committed changes with the rest of the team."}, {"obj": "2.5", "q": "Which term best matches this description: \"The processing power (CPU, RAM) needed to run a workload effectively.\"?", "c": ["Compliance Requirements", "Availability Requirements", "Network Requirements", "Compute Requirements"], "a": 3, "e": "\"The processing power (CPU, RAM) needed to run a workload effectively.\" describes Compute Requirements. Determines the instance size and type selected during provisioning."}, {"obj": "1.11", "q": "Which of the following terms fits this definition: \"AI technology that extracts text from images or scanned documents (OCR).\"?", "c": ["Text Recognition", "IoT Gateway", "IoT Transmission Protocol", "Voice-to-Text"], "a": 0, "e": "\"AI technology that extracts text from images or scanned documents (OCR).\" describes Text Recognition. Used to digitize and search paper documents or extract data from images automatically."}, {"obj": "1.7", "q": "Which of the following best describes \"Clustering\"?", "c": ["Creating an exact copy of an existing VM.", "A single hypervisor host running VMs with no clustering.", "Storage Area Network — shared block storage accessible by multiple hypervisor hosts.", "Grouping multiple hypervisor hosts together to share resources and enable failover/migration."], "a": 3, "e": "Grouping multiple hypervisor hosts together to share resources and enable failover/migration. Enables high availability and load balancing of VMs across multiple physical hosts."}, {"obj": "2.2", "q": "Which of the following is a disadvantage of blue-green deployment compared to rolling deployment?", "c": ["Blue-green requires double the infrastructure temporarily, increasing cost during the transition", "Blue-green cannot support instant rollback", "Blue-green always takes longer to complete than rolling deployment", "Blue-green cannot be automated"], "a": 0, "e": "Blue-green requires running two full parallel environments during the transition, temporarily doubling infrastructure cost, unlike rolling deployment's incremental approach."}, {"obj": "3.3", "q": "Which term is most closely associated with this real-world importance: \"Ensures the backup itself is trustworthy before it's ever relied upon during an actual incident.\"?", "c": ["Incremental Backup", "Backup Schedule", "In-Place Recovery", "Backup Integrity Testing"], "a": 3, "e": "Ensures the backup itself is trustworthy before it's ever relied upon during an actual incident. This describes Backup Integrity Testing (\"Verifying that backed-up data has not been corrupted.\")."}, {"obj": "4.6", "q": "Why does this matter on the exam and in practice? \"A common finding during security assessments and an easy target for attackers to exploit.\" — which term does this explain?", "c": ["Unnecessary Open Ports", "Ransomware", "DDoS", "Phishing"], "a": 0, "e": "A common finding during security assessments and an easy target for attackers to exploit. This describes Unnecessary Open Ports (\"Network ports left open on a system that are not required for its function.\")."}, {"obj": "4.4", "q": "How would you most accurately define \"Hardening\"?", "c": ["Granting only the minimum access rights needed to perform a function.", "Encrypting stored data so it remains unreadable without the correct key.", "Reducing a system's attack surface by disabling unnecessary services, closing unused ports, and applying secure configurations.", "A security model that assumes no user or device should be trusted by default, even inside the network perimeter."], "a": 2, "e": "Reducing a system's attack surface by disabling unnecessary services, closing unused ports, and applying secure configurations. One of the most fundamental and heavily tested security practices across all IT domains."}, {"obj": "4.3", "q": "Which concept is described by the phrase: \"An authorization framework that lets an application access resources on a user's behalf without sharing their password.\"?", "c": ["OAuth 2.0", "Discretionary Access Control", "OpenID Connect", "RDP"], "a": 0, "e": "\"An authorization framework that lets an application access resources on a user's behalf without sharing their password.\" describes OAuth 2.0. The standard mechanism behind \"log in with...\" and delegated API access scenarios."}, {"obj": "1.2", "q": "A company runs workloads split across AWS and Azure simultaneously to avoid depending on a single provider. What is this practice called?", "c": ["Cloud bursting", "Multicloud tenancy", "Edge computing", "Community cloud"], "a": 1, "e": "Multicloud tenancy uses services from more than one public cloud provider, reducing vendor lock-in at the cost of added complexity."}, {"obj": "6.2", "q": "\"IP Scope Exhaustion\" is best defined as which of the following?", "c": ["An incorrect entry in a route table sending traffic to the wrong destination.", "A required network path that has not been defined in a route table.", "Two networks using conflicting/duplicate IP address ranges.", "Running out of available addresses within a defined IP range or subnet."], "a": 3, "e": "Running out of available addresses within a defined IP range or subnet. Prevents new resources from being provisioned with an address until the range is expanded or reclaimed."}, {"obj": "1.2", "q": "Given the description \"Temporarily extending an on-premises workload into the public cloud to handle demand spikes.\", which term is being defined?", "c": ["Edge Computing", "Cloud Bursting", "Availability Zone", "Warm Site"], "a": 1, "e": "\"Temporarily extending an on-premises workload into the public cloud to handle demand spikes.\" describes Cloud Bursting. Lets an organization keep steady-state workloads on cheaper private infrastructure while still handling peak load."}, {"obj": "4.4", "q": "Which statement accurately describes \"API Security\"?", "c": ["A security model that assumes no user or device should be trusted by default, even inside the network perimeter.", "Hardening guidance published by a specific cloud provider or software vendor for their own product.", "Granting only the minimum access rights needed to perform a function.", "Practices and controls that protect APIs from abuse, unauthorized access, and attack."], "a": 3, "e": "Practices and controls that protect APIs from abuse, unauthorized access, and attack. APIs are a primary attack surface in cloud-native applications and require dedicated protective controls."}, {"obj": "4.3", "q": "Which concept is described by the phrase: \"Application Programming Interface — used here for programmatic management/access to cloud resources.\"?", "c": ["API (IAM Context)", "SDK", "Bastion Host", "Programmatic Access"], "a": 0, "e": "\"Application Programming Interface — used here for programmatic management/access to cloud resources.\" describes API (IAM Context). API access typically requires its own credentials (keys/tokens) separate from human user logins."}, {"obj": "5.1", "q": "Select the most accurate description of \"Code Push\":", "c": ["Uploading local code changes to a remote/shared repository.", "A formal request to merge a proposed code change into a shared branch, typically triggering review.", "Saving a snapshot of changes to the local version control history.", "Having other team members examine proposed code changes before they are merged."], "a": 0, "e": "Uploading local code changes to a remote/shared repository. The action that shares a developer's committed changes with the rest of the team."}, {"obj": "1.9", "q": "Select the most accurate description of \"Non-Relational Database\":", "c": ["A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS).", "A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure.", "A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs.", "A database that organizes data into structured tables with defined relationships (SQL)."], "a": 2, "e": "A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs. Better suited for unstructured/semi-structured data and workloads needing horizontal scalability."}, {"obj": "3.1", "q": "Which of the following best describes \"Alert Triage\"?", "c": ["Defining how long log data is kept before being archived or deleted.", "The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.", "The defined actions taken once an alert is triaged and confirmed to need action.", "Gathering log data from applications, systems, and services into a central location."], "a": 1, "e": "The process of reviewing and prioritizing incoming alerts to determine urgency and next steps. Prevents alert fatigue and ensures the most critical issues are addressed first."}, {"obj": "1.8", "q": "Which concept is described by the phrase: \"Pre-purchasing capacity for a discounted rate in exchange for a committed term.\"?", "c": ["Reserved Resources", "Rightsizing", "Pay-As-You-Go", "Tagging"], "a": 0, "e": "\"Pre-purchasing capacity for a discounted rate in exchange for a committed term.\" describes Reserved Resources. Reduces cost for predictable, steady-state workloads compared to pay-as-you-go pricing."}, {"obj": "6.3", "q": "An employee shares their cloud console password with a colleague to save time, and that colleague later performs unauthorized actions. What security issue does this best illustrate?", "c": ["Cipher suite deprecation", "Unauthorized access enabled by credential sharing", "Regional service availability", "IP scope exhaustion"], "a": 1, "e": "Sharing credentials enables unauthorized access by someone who wasn't individually granted permission, illustrating why credentials should never be shared."}, {"obj": "5.1", "q": "A colleague says: \"The basic unit of change tracking in most version control systems.\" Which concept are they describing?", "c": ["Code Commit", "Version Management", "Code Merge", "Pull Request"], "a": 0, "e": "The basic unit of change tracking in most version control systems. This describes Code Commit (\"Saving a snapshot of changes to the local version control history.\")."}, {"obj": "4.4", "q": "Which term best matches this description: \"Encrypting data as it moves across a network (e.g., via TLS).\"?", "c": ["Zero Trust", "Object Storage Security", "Data in Transit Encryption", "Privileged Container"], "a": 2, "e": "\"Encrypting data as it moves across a network (e.g., via TLS).\" describes Data in Transit Encryption. Protects data from eavesdropping while crossing untrusted networks like the internet."}, {"obj": "1.7", "q": "Given the description \"A virtual network built on top of physical network infrastructure, common in virtualization and containers.\", which term is being defined?", "c": ["Cloning", "Overlay Network", "Stand-Alone Virtualization", "Local Storage (Virtualization)"], "a": 1, "e": "\"A virtual network built on top of physical network infrastructure, common in virtualization and containers.\" describes Overlay Network. Allows flexible virtual network topologies independent of the underlying physical network layout."}, {"obj": "4.5", "q": "\"DDoS Protection\" is best defined as which of the following?", "c": ["Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic.", "A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs.", "Rules that define what actions a given identity is allowed or denied to perform on cloud resources.", "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data."], "a": 0, "e": "Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic. Essential for internet-facing cloud services that could otherwise be overwhelmed by attack traffic."}, {"obj": "5.1", "q": "A developer saves a local snapshot of their changes to their version control history before pushing it to the shared repository. What action is this?", "c": ["A code push", "A code commit", "A pull request", "A code merge"], "a": 1, "e": "A commit saves a snapshot of changes to local version control history, distinct from pushing it to a remote repository."}, {"obj": "6.2", "q": "Why does this matter on the exam and in practice? \"Highlights the need to track and update deprecated protocol usage before it causes an outage.\" — which term does this explain?", "c": ["IP Scope Exhaustion", "Missing Route", "Protocol Deprecation", "VLAN Misconfigured Tags"], "a": 2, "e": "Highlights the need to track and update deprecated protocol usage before it causes an outage. This describes Protocol Deprecation (\"A connectivity failure caused by a system relying on a protocol version the other side no longer supports.\")."}, {"obj": "1.3", "q": "Select the most accurate description of \"Transit Gateway\":", "c": ["Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.", "Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management.", "Content Delivery Network — a geographically distributed set of servers that cache content closer to end users.", "A hub service that connects many VPCs and on-premises networks through a single point."], "a": 3, "e": "A hub service that connects many VPCs and on-premises networks through a single point. Simplifies large-scale network architectures compared to a full mesh of individual peering connections."}, {"obj": "1.3", "q": "Which of the following is the correct expansion of \"CIS\"?", "c": ["Common Weakness Enumeration", "Redundant Array of Independent Disks", "Center for Internet Security", "Common Language Infrastructure"], "a": 2, "e": "CIS stands for Center for Internet Security. Publishes consensus-based configuration hardening benchmarks."}, {"obj": "2.5", "q": "Which concept is described by the phrase: \"The processing power (CPU, RAM) needed to run a workload effectively.\"?", "c": ["Availability Requirements", "Network Requirements", "Storage Requirements", "Compute Requirements"], "a": 3, "e": "\"The processing power (CPU, RAM) needed to run a workload effectively.\" describes Compute Requirements. Determines the instance size and type selected during provisioning."}, {"obj": "5.2", "q": "\"RPM Package\" is best defined as which of the following?", "c": ["A code or artifact repository accessible to anyone.", "Merging code changes from multiple contributors into a shared, continuously tested codebase.", "A simple, unstructured file (like a config or script) produced or consumed by a pipeline.", "Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions."], "a": 3, "e": "Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions. One of several standard package formats a CI/CD pipeline might produce or deploy."}, {"obj": "5.4", "q": "Why does this matter on the exam and in practice? \"A widely used open-source stack for centralized logging and observability.\" — which term does this explain?", "c": ["Jenkins", "ELK Stack", "Git", "Ansible"], "a": 1, "e": "A widely used open-source stack for centralized logging and observability. This describes ELK Stack (\"Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization.\")."}, {"obj": "4.3", "q": "An administrator explains the importance of a concept: \"The standard way to securely administer Linux-based cloud instances remotely.\" What concept is this?", "c": ["MFA", "OpenID Connect", "SSH", "SDK"], "a": 2, "e": "The standard way to securely administer Linux-based cloud instances remotely. This describes SSH (\"Secure Shell — an encrypted protocol for remote command-line access to cloud resources.\")."}, {"obj": "4.6", "q": "Which term best matches this description: \"A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email.\"?", "c": ["Ransomware", "Unnecessary Open Ports", "DDoS", "Phishing"], "a": 3, "e": "\"A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email.\" describes Phishing. One of the most common initial access vectors used in real-world breaches."}, {"obj": "1.4", "q": "Which of the following is the correct expansion of \"LUN\"?", "c": ["Transmission Control Protocol", "Disaster Recovery", "Logical Unit Number", "Common Language Infrastructure"], "a": 2, "e": "LUN stands for Logical Unit Number. An identifier for a logically addressable storage volume presented from a SAN."}, {"obj": "1.6", "q": "A description reads: \"A repository for storing and distributing container images (e.g., Docker Hub, a private registry).\" Which term does this describe?", "c": ["Port Mapping", "Persistent Volume", "Image Registry", "Workload Orchestration"], "a": 2, "e": "\"A repository for storing and distributing container images (e.g., Docker Hub, a private registry).\" describes Image Registry. Provides a central, versioned source for pulling container images during deployment."}, {"obj": "1.7", "q": "A colleague says: \"Commonly used for storing VM templates, ISOs, and shared datastores.\" Which concept are they describing?", "c": ["Cloning", "NAS (Virtualization Context)", "Local Storage (Virtualization)", "Clustering"], "a": 1, "e": "Commonly used for storing VM templates, ISOs, and shared datastores. This describes NAS (Virtualization Context) (\"Network Attached Storage — shared file-level storage accessible by multiple hosts.\")."}, {"obj": "4.3", "q": "Given the description \"A chronological record of who did what, and when, within a system.\", which term is being defined?", "c": ["Audit Trail", "Local User Authentication", "Discretionary Access Control", "RDP"], "a": 0, "e": "\"A chronological record of who did what, and when, within a system.\" describes Audit Trail. Essential for investigating incidents and demonstrating compliance with access policies."}, {"obj": "1.11", "q": "A description reads: \"The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data.\" Which term does this describe?", "c": ["Sentiment Analysis", "Machine Learning", "IoT Communication", "Text Translation"], "a": 2, "e": "\"The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data.\" describes IoT Communication. Choice of communication method affects range, power consumption, and bandwidth available to the device."}, {"obj": "4.3", "q": "How would you most accurately define \"CLI\"?", "c": ["Authenticating against a centralized directory service (like LDAP or Active Directory).", "Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources.", "Software Development Kit — a set of libraries/tools that let developers programmatically interact with a cloud platform.", "Granting permissions based on a user's assigned role rather than to each individual directly."], "a": 1, "e": "Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources. Popular for scripting and automation tasks that would be tedious through a web portal."}, {"obj": "6.2", "q": "Why does this matter on the exam and in practice? \"Misconfiguring one as the other is a common cause of VLAN connectivity problems.\" — which term does this explain?", "c": ["VLAN Misconfigured Tags", "Access vs. Trunk Ports", "DNS (Troubleshooting)", "Protocol Incompatibility"], "a": 1, "e": "Misconfiguring one as the other is a common cause of VLAN connectivity problems. This describes Access vs. Trunk Ports (\"The distinction between a switch port carrying a single VLAN (access) versus multiple VLANs (trunk).\")."}, {"obj": "1.6", "q": "A company runs a single containerized web app on one host without any orchestration, and when the host fails, the app goes down with no automatic recovery. What is the most likely reason for this lack of resilience?", "c": ["The image registry is misconfigured", "The workload lacks orchestration to automatically reschedule the container elsewhere on failure", "Persistent volumes were used incorrectly", "Port mapping was not configured"], "a": 1, "e": "Without an orchestration platform to detect the failure and reschedule the container onto a healthy host, a stand-alone container deployment has no automatic recovery mechanism."}, {"obj": "4.5", "q": "Which concept is described by the phrase: \"Rules that define what actions a given identity is allowed or denied to perform on cloud resources.\"?", "c": ["IPS/IDS", "Network ACL", "DDoS Protection", "IAM Policies"], "a": 3, "e": "\"Rules that define what actions a given identity is allowed or denied to perform on cloud resources.\" describes IAM Policies. The core mechanism for enforcing least privilege and access control in cloud environments."}, {"obj": "1.3", "q": "Which of the following would most directly cause an application load balancer to be unable to make routing decisions based on the requested URL path?", "c": ["Using a Layer 4 network load balancer instead of a Layer 7 application load balancer", "Using too many availability zones", "Enabling a CDN", "Using VPC peering"], "a": 0, "e": "Layer 4 load balancers only see IP/port information and cannot inspect HTTP-level details like URL paths, unlike Layer 7 application load balancers."}, {"obj": "3.4", "q": "Which term best matches this description: \"Retiring or upgrading a resource because the vendor no longer provides support/patches for it.\"?", "c": ["Major Update", "Decommissioning — End of Support", "Decommissioning — End of Life", "Minor Update"], "a": 1, "e": "\"Retiring or upgrading a resource because the vendor no longer provides support/patches for it.\" describes Decommissioning — End of Support. Running unsupported resources leaves known vulnerabilities permanently unpatched."}, {"obj": "2.4", "q": "A company wants to standardize how both their cloud infrastructure and application configurations are managed, treating both as version-controlled artifacts. What two practices are they combining?", "c": ["Infrastructure as Code and Configuration as Code", "Drift detection and manual provisioning", "IaC testing and ad hoc scripting", "Service discovery and load balancing"], "a": 0, "e": "Combining IaC (for infrastructure) and CaC (for configuration) lets a team manage both categories consistently as version-controlled code."}, {"obj": "2.3", "q": "Given the description \"Moving workloads out of the cloud back to local infrastructure.\", which term is being defined?", "c": ["Cloud-to-On-Premises Migration", "Cloud-to-Cloud Migration", "Replatform", "Re-Architect"], "a": 0, "e": "\"Moving workloads out of the cloud back to local infrastructure.\" describes Cloud-to-On-Premises Migration. Sometimes chosen for cost, compliance, or performance reasons after initial cloud adoption."}, {"obj": "1.8", "q": "Which term best matches this description: \"Attaching key-value metadata labels to cloud resources.\"?", "c": ["Pay-As-You-Go", "Reserved Resources", "Dedicated Host Billing", "Tagging"], "a": 3, "e": "\"Attaching key-value metadata labels to cloud resources.\" describes Tagging. Enables cost allocation, automation, and organization of resources by project, owner, or environment."}, {"obj": "5.2", "q": "Select the most accurate description of \"RPM Package\":", "c": ["A simple, unstructured file (like a config or script) produced or consumed by a pipeline.", "Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions.", "Incorporating security scanning and checks into the automated pipeline.", "Automatically building, testing, and deploying code changes with minimal manual intervention."], "a": 1, "e": "Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions. One of several standard package formats a CI/CD pipeline might produce or deploy."}, {"obj": "1.9", "q": "Which of the following is the correct expansion of \"CRM\"?", "c": ["Customer Relationship Management", "Lightweight Directory Access Protocol", "International Organization for Standardization", "Network Attached Storage"], "a": 0, "e": "CRM stands for Customer Relationship Management. Software used to manage a company's interactions with customers, often delivered as SaaS."}, {"obj": "5.3", "q": "Which integration approach would be most appropriate for a system where Service A needs to synchronously call a specific function on Service B and wait for its direct result?", "c": ["Event-driven fan-out with no direct response", "RPC", "Asynchronous message queuing with no response expected", "Batch file transfer"], "a": 1, "e": "RPC is designed for synchronous, direct function-call-style communication where the caller waits for a specific result, unlike event-driven fan-out."}, {"obj": "4.4", "q": "A colleague says: \"Misconfigured object storage permissions are a very common real-world cause of public data exposure.\" Which concept are they describing?", "c": ["Principle of Least Privilege", "Vendor-Specific Benchmark", "Data in Transit Encryption", "Object Storage Security"], "a": 3, "e": "Misconfigured object storage permissions are a very common real-world cause of public data exposure. This describes Object Storage Security (\"Access controls and encryption settings applied to object storage buckets/containers.\")."}, {"obj": "5.3", "q": "Select the most accurate description of \"SOAP\":", "c": ["Representational State Transfer — an architectural style for web services using standard HTTP methods.", "Simple Object Access Protocol — an XML-based messaging protocol for web services.", "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local.", "A query language for APIs that lets clients request exactly the data they need."], "a": 1, "e": "Simple Object Access Protocol — an XML-based messaging protocol for web services. Older and more rigid than REST, but still used in some enterprise and legacy integrations."}, {"obj": "2.4", "q": "A team wants every infrastructure change to be reviewed, version-controlled, and repeatable rather than made manually through a console. What practice should they adopt?", "c": ["Manual provisioning", "Infrastructure as Code", "Ad hoc scripting only", "Tagging"], "a": 1, "e": "IaC manages infrastructure through machine-readable, version-controlled definition files, making changes repeatable and auditable."}, {"obj": "6.1", "q": "Select the most accurate description of \"Sizing Issues\":", "c": ["A provider-imposed limit on how many of a given resource type can be provisioned.", "IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated.", "A deployment failure or performance problem caused by choosing an inappropriately sized resource.", "Incorrectly assigned CPU, memory, or storage limits for a workload."], "a": 2, "e": "A deployment failure or performance problem caused by choosing an inappropriately sized resource. Both undersizing (poor performance) and oversizing (wasted cost) are common sizing mistakes."}, {"obj": "5.1", "q": "A team combines changes from a completed feature branch into the main branch after review and approval. What action is this?", "c": ["A code commit", "A code push", "A code merge", "Version management only"], "a": 2, "e": "A code merge combines changes from different branches into one, integrating completed work into the shared codebase."}, {"obj": "4.3", "q": "Which of the following terms fits this definition: \"Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.\"?", "c": ["OpenID Connect", "RDP", "Web Portal", "API (IAM Context)"], "a": 1, "e": "\"Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.\" describes RDP. The standard way to remotely access Windows-based cloud instances."}, {"obj": "1.11", "q": "\"IoT Transmission Protocol\" is best defined as which of the following?", "c": ["AI technology that determines the emotional tone (positive/negative/neutral) of text.", "Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case.", "Lightweight protocols (like MQTT or CoAP) designed for constrained IoT devices and networks.", "AI technology that converts written text into spoken audio (speech synthesis)."], "a": 2, "e": "Lightweight protocols (like MQTT or CoAP) designed for constrained IoT devices and networks. Optimized for low bandwidth and power use, unlike heavier traditional web protocols."}, {"obj": "3.3", "q": "Which of the following best describes \"Full Backup\"?", "c": ["A complete copy of all selected data.", "Backs up all data changed since the last full backup.", "Backs up only data changed since the last backup of any type.", "The defined frequency and timing of backup jobs."], "a": 0, "e": "A complete copy of all selected data. Forms the baseline that incremental and differential backups build on."}, {"obj": "3.3", "q": "A company performs a full backup every Sunday and incremental backups on all other days. If a restore is needed on Thursday, which backups must be applied, and in what order?", "c": ["Only Thursday's incremental", "Sunday's full only", "Sunday's full, then Monday, Tuesday, and Wednesday's incrementals in order", "Only the most recent incremental, regardless of earlier ones"], "a": 2, "e": "Restoring from an incremental chain requires the last full backup plus every incremental since, applied in order."}, {"obj": "2.1", "q": "Which term is most closely associated with this real-world importance: \"Balances shared cost benefits with more tailored governance than a general public cloud.\"?", "c": ["On Premises", "Public Cloud", "Community Cloud", "Private Cloud"], "a": 2, "e": "Balances shared cost benefits with more tailored governance than a general public cloud. This describes Community Cloud (\"Infrastructure shared by several organizations with common concerns such as compliance or security requirements.\")."}, {"obj": "3.1", "q": "A colleague says: \"Turns detection into resolution — an alert with no response plan provides little value.\" Which concept are they describing?", "c": ["Alert Triage", "Log Aggregation", "Alert Response", "Log Collection"], "a": 2, "e": "Turns detection into resolution — an alert with no response plan provides little value. This describes Alert Response (\"The defined actions taken once an alert is triaged and confirmed to need action.\")."}, {"obj": "1.10", "q": "Which of the following best describes \"Compute Optimization (Serverless)\"?", "c": ["The rate of data transfer to/from a storage system, usually measured in MB/s or GB/s.", "Using Function as a Service as the compute resource type for a workload.", "The actual amount of data successfully transferred over a network connection in a given time.", "Automated coordination of workload deployment, scaling, and lifecycle management."], "a": 1, "e": "Using Function as a Service as the compute resource type for a workload. Eliminates server management entirely, billing only for actual execution time."}, {"obj": "4.6", "q": "In cloud computing terminology, \"Unnecessary Open Ports\" refers to which of the following?", "c": ["An attack that succeeds due to a mistake made by an authorized user (misconfiguration, mishandling credentials, etc.).", "A departure from a system's established normal behavior pattern.", "Unauthorized use of a system's computing resources to mine cryptocurrency.", "Network ports left open on a system that are not required for its function."], "a": 3, "e": "Network ports left open on a system that are not required for its function. A common finding during security assessments and an easy target for attackers to exploit."}, {"obj": "1.3", "q": "A description reads: \"A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute).\" Which term does this describe?", "c": ["Application Load Balancer", "SDN", "Dedicated Connection", "Static Route"], "a": 2, "e": "\"A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute).\" describes Dedicated Connection. Offers more consistent bandwidth/latency and often lower cost at scale than routing through the public internet."}, {"obj": "3.3", "q": "An administrator explains the importance of a concept: \"A backup reporting \"success\" does not guarantee the data is truly restorable — testing closes that gap.\" What concept is this?", "c": ["Incremental Backup", "Backup Recoverability Testing", "In-Place Recovery", "Backup Replication"], "a": 1, "e": "A backup reporting \"success\" does not guarantee the data is truly restorable — testing closes that gap. This describes Backup Recoverability Testing (\"Actually restoring backup data to confirm it can be used successfully.\")."}, {"obj": "3.4", "q": "An administrator explains the importance of a concept: \"Applying patches promptly closes known security gaps before they can be exploited.\" What concept is this?", "c": ["Patch", "Ephemeral Data", "Decommissioning — End of Support", "Persistent Data"], "a": 0, "e": "Applying patches promptly closes known security gaps before they can be exploited. This describes Patch (\"A software update addressing a specific bug or vulnerability.\")."}, {"obj": "4.1", "q": "A security bulletin references 'CVE-2024-12345' when describing a specific vulnerability affecting a widely used library. What is the purpose of this identifier?", "c": ["It indicates the exact severity score of the vulnerability", "It provides a standardized, publicly referenced identifier so the vulnerability can be tracked consistently across tools and vendors", "It automatically applies a patch", "It replaces the need for any vulnerability assessment"], "a": 1, "e": "CVE provides a standardized identifier for publicly known vulnerabilities, letting different tools, vendors, and teams reference the same issue consistently."}, {"obj": "1.10", "q": "An administrator explains the importance of a concept: \"A key metric for sizing storage for database or transaction-heavy workloads.\" What concept is this?", "c": ["Compute Optimization (Container)", "Compute Optimization (Serverless)", "IOPS (Optimization)", "Network Latency"], "a": 2, "e": "A key metric for sizing storage for database or transaction-heavy workloads. This describes IOPS (Optimization) (\"Input/Output Operations Per Second — a measure of storage performance.\")."}, {"obj": "5.2", "q": "Which term is most closely associated with this real-world importance: \"The counterpart to RPM packages on Debian/Ubuntu-based systems.\"?", "c": ["Build (CI/CD)", "Debian Package", "CI/CD Workflow", "CI/CD Testing"], "a": 1, "e": "The counterpart to RPM packages on Debian/Ubuntu-based systems. This describes Debian Package (\"A package format (.deb) used for installing software on Debian-based Linux distributions.\")."}, {"obj": "2.5", "q": "Which term is most closely associated with this real-world importance: \"Drives decisions like multi-AZ deployment, clustering, and failover design.\"?", "c": ["Storage Requirements", "Availability Requirements", "Compute Requirements", "Compliance Requirements"], "a": 1, "e": "Drives decisions like multi-AZ deployment, clustering, and failover design. This describes Availability Requirements (\"The uptime and resiliency expectations for a workload.\")."}, {"obj": "5.1", "q": "Why does this matter on the exam and in practice? \"The basic unit of change tracking in most version control systems.\" — which term does this explain?", "c": ["Code Review", "Code Commit", "Branch Management", "Code Push"], "a": 1, "e": "The basic unit of change tracking in most version control systems. This describes Code Commit (\"Saving a snapshot of changes to the local version control history.\")."}, {"obj": "1.4", "q": "How would you most accurately define \"Object Storage\"?", "c": ["Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB).", "Storage that manages data as discrete objects with metadata, accessed via an API (e.g., S3).", "The lowest-cost storage tier, designed for rarely accessed data with the slowest retrieval times (sometimes hours).", "Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O."], "a": 1, "e": "Storage that manages data as discrete objects with metadata, accessed via an API (e.g., S3). Highly scalable and durable, ideal for unstructured data like backups, media, and static web content."}, {"obj": "3.1", "q": "Given the description \"Following a single request as it moves through multiple services in a distributed system.\", which term is being defined?", "c": ["Alert Triage", "Log Collection", "Tracing", "Log Aggregation"], "a": 2, "e": "\"Following a single request as it moves through multiple services in a distributed system.\" describes Tracing. Critical for pinpointing where latency or errors occur across microservices."}, {"obj": "1.11", "q": "\"Sentiment Analysis\" is best defined as which of the following?", "c": ["AI technology that determines the emotional tone (positive/negative/neutral) of text.", "Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case.", "Lightweight protocols (like MQTT or CoAP) designed for constrained IoT devices and networks.", "AI technology that converts written text into spoken audio (speech synthesis)."], "a": 0, "e": "AI technology that determines the emotional tone (positive/negative/neutral) of text. Used to analyze customer feedback, reviews, and social media at scale."}, {"obj": "3.4", "q": "A company continues running a database version for two years after its vendor stopped issuing security patches for it. What risk does this create?", "c": ["No risk, since the software still functions normally", "Known vulnerabilities in that version remain permanently unpatched, creating an ongoing security risk", "The vendor is legally required to still provide free patches", "The software will automatically update itself"], "a": 1, "e": "Running unsupported software means any vulnerabilities discovered after end of support will never be patched, leaving a permanent, growing security risk."}, {"obj": "4.2", "q": "A company's legal team instructs IT to preserve all emails related to a specific project indefinitely because the project is now the subject of pending litigation, overriding the normal 90-day deletion policy. What is this called?", "c": ["Regulatory retention", "Litigation hold", "Contractual retention", "Data classification"], "a": 1, "e": "A litigation hold is a legal requirement to preserve specific data due to pending or anticipated litigation, which overrides normal retention schedules."}, {"obj": "3.3", "q": "An administrator explains the importance of a concept: \"Especially important since backups often contain complete copies of sensitive production data.\" What concept is this?", "c": ["Full Backup", "Backup Recoverability Testing", "Parallel Recovery", "Backup Encryption"], "a": 3, "e": "Especially important since backups often contain complete copies of sensitive production data. This describes Backup Encryption (\"Encrypting backup data so it remains protected even if the storage media or files are exposed.\")."}, {"obj": "5.2", "q": "Given the description \"A simple, unstructured file (like a config or script) produced or consumed by a pipeline.\", which term is being defined?", "c": ["Build (CI/CD)", "Private Repository", "Flat File Artifact", "Code Integration"], "a": 2, "e": "\"A simple, unstructured file (like a config or script) produced or consumed by a pipeline.\" describes Flat File Artifact. Sometimes all that's needed for simple deployment tasks, without a full package format."}, {"obj": "4.6", "q": "Select the most accurate description of \"Malware\":", "c": ["An attack that abuses a cloud instance's metadata service to steal credentials or configuration data.", "Network ports left open on a system that are not required for its function.", "An attack that succeeds because a system was running software with a known, unpatched vulnerability.", "Malicious software designed to damage, disrupt, or gain unauthorized access to a system."], "a": 3, "e": "Malicious software designed to damage, disrupt, or gain unauthorized access to a system. A broad category of threats requiring layered defenses like endpoint protection and patching."}, {"obj": "4.1", "q": "A vulnerability scan identifies a weakness and assigns it a standardized public identifier so it can be tracked across tools and vendors. What is this identifier called?", "c": ["A CVSS score", "A CVE ID", "A CWE entry", "An SLA reference"], "a": 1, "e": "CVE provides a standardized, publicly referenced identifier for known vulnerabilities, distinct from a CVSS severity score."}, {"obj": "1.2", "q": "Which of the following terms fits this definition: \"Temporarily extending an on-premises workload into the public cloud to handle demand spikes.\"?", "c": ["RPO", "Cloud Bursting", "Cold Site", "Availability Zone"], "a": 1, "e": "\"Temporarily extending an on-premises workload into the public cloud to handle demand spikes.\" describes Cloud Bursting. Lets an organization keep steady-state workloads on cheaper private infrastructure while still handling peak load."}, {"obj": "1.7", "q": "What does the abbreviation \"USB\" stand for?", "c": ["Software-defined Network", "Virtual Private Network", "Universal Serial Bus", "Center for Internet Security"], "a": 2, "e": "USB stands for Universal Serial Bus. A common interface standard for connecting peripherals and storage."}, {"obj": "5.1", "q": "A team's pull request template requires the author to describe what changed and why, and requires at least one reviewer's approval. What is the overall purpose of this workflow?", "c": ["To make development slower with no benefit", "To ensure changes are documented, reviewed, and vetted before becoming part of the shared codebase", "To eliminate the need for version control", "To bypass code review requirements"], "a": 1, "e": "This structured pull request workflow ensures every change is documented and reviewed before merging, improving code quality and shared understanding."}, {"obj": "3.3", "q": "A company discovers during an actual disaster that its backups, while technically successful, cannot restore a working database because the schema version doesn't match. What practice would have caught this earlier?", "c": ["Backup replication alone", "Regular backup recoverability testing that performs full test restores", "Backup encryption alone", "Increasing backup frequency without testing restores"], "a": 1, "e": "Only actually testing a full restore (recoverability testing) would reveal a schema mismatch or similar issue that a 'successful' backup job status wouldn't catch."}, {"obj": "1.1", "q": "A company wants full control over OS-level security hardening and custom kernel modules for a specialized workload. Which service model gives them this level of control?", "c": ["SaaS", "FaaS", "IaaS", "A fully managed PaaS"], "a": 2, "e": "IaaS gives the customer full control down to and including the guest OS, which is necessary for custom kernel-level configuration."}, {"obj": "1.4", "q": "A company is storing millions of unstructured media files (images, videos) that need to be accessed via HTTP APIs at massive scale. Which storage type is the best fit?", "c": ["Block storage", "Object storage", "File storage (SMB)", "Local disk"], "a": 1, "e": "Object storage is designed for massive scale, unstructured data accessed via API, making it ideal for media and backup files."}, {"obj": "1.4", "q": "Which of the following terms fits this definition: \"The lowest-cost storage tier, designed for rarely accessed data with the slowest retrieval times (sometimes hours).\"?", "c": ["Warm Storage Tier", "Cold Storage Tier", "Hot Storage Tier", "Archive Storage Tier"], "a": 3, "e": "\"The lowest-cost storage tier, designed for rarely accessed data with the slowest retrieval times (sometimes hours).\" describes Archive Storage Tier. Ideal for long-term retention data that must be kept for compliance but is almost never read."}, {"obj": "6.2", "q": "A colleague says: \"Prevents new resources from being provisioned with an address until the range is expanded or reclaimed.\" Which concept are they describing?", "c": ["Protocol Deprecation", "DNS (Troubleshooting)", "NAT (Troubleshooting)", "IP Scope Exhaustion"], "a": 3, "e": "Prevents new resources from being provisioned with an address until the range is expanded or reclaimed. This describes IP Scope Exhaustion (\"Running out of available addresses within a defined IP range or subnet.\")."}, {"obj": "6.3", "q": "Which of the following terms fits this definition: \"An identity gaining higher access than originally granted, often through a flaw or misconfiguration.\"?", "c": ["Leaked Credentials", "Privilege Escalation (Troubleshooting)", "Unauthorized Software", "Software Vulnerability Issues"], "a": 1, "e": "\"An identity gaining higher access than originally granted, often through a flaw or misconfiguration.\" describes Privilege Escalation (Troubleshooting). A critical security troubleshooting concern after any suspected compromise of a low-privilege account."}, {"obj": "5.3", "q": "A colleague says: \"Older and more rigid than REST, but still used in some enterprise and legacy integrations.\" Which concept are they describing?", "c": ["Event-Driven Architecture", "GraphQL", "Web Sockets", "SOAP"], "a": 3, "e": "Older and more rigid than REST, but still used in some enterprise and legacy integrations. This describes SOAP (\"Simple Object Access Protocol — an XML-based messaging protocol for web services.\")."}, {"obj": "4.4", "q": "\"Unprivileged Container\" is best defined as which of the following?", "c": ["Encrypting data as it moves across a network (e.g., via TLS).", "A container running with restricted access, isolated from the host's sensitive resources.", "Access controls and encryption settings applied to object storage buckets/containers.", "A security model that assumes no user or device should be trusted by default, even inside the network perimeter."], "a": 1, "e": "A container running with restricted access, isolated from the host's sensitive resources. The safer default for container security, limiting the impact of a container-level compromise."}, {"obj": "1.1", "q": "The acronym \"IaaS\" stands for:", "c": ["Infrastructure as a Service", "Responsible, Accountable, Consulted, Informed", "Local Area Network", "Cloud Service Provider"], "a": 0, "e": "IaaS stands for Infrastructure as a Service. A cloud model providing virtualized compute, storage, and networking resources."}, {"obj": "5.4", "q": "A team wants to visualize CPU, memory, and request-rate metrics collected by their monitoring system on a shared dashboard accessible to the whole team. Which tool is commonly used to build this dashboard?", "c": ["Ansible", "Grafana", "Jenkins", "Git"], "a": 1, "e": "Grafana is the standard tool for building shared, real-time visualization dashboards from collected monitoring metrics."}, {"obj": "2.2", "q": "Select the most accurate description of \"In-Place Deployment\":", "c": ["Updating an existing server or instance directly rather than deploying an entirely new one.", "A strategy running two identical environments (blue and green), switching traffic to the new version once verified.", "Updating instances incrementally, a few at a time, rather than all at once.", "Gradually rolling out a change to a small subset of users or servers before a full rollout."], "a": 0, "e": "Updating an existing server or instance directly rather than deploying an entirely new one. Simpler but riskier than blue-green since there is no separate environment to instantly roll back to."}, {"obj": "1.7", "q": "Which term is most closely associated with this real-world importance: \"Speeds up deployment of identical VMs without building each one from scratch.\"?", "c": ["Cloning", "VM Network", "Clustering", "Overlay Network"], "a": 0, "e": "Speeds up deployment of identical VMs without building each one from scratch. This describes Cloning (\"Creating an exact copy of an existing VM.\")."}, {"obj": "1.10", "q": "Which of the following best describes \"Workflow (Optimization)\"?", "c": ["A defined sequence of automated steps/tasks that process data or coordinate resources.", "Automated coordination of workload deployment, scaling, and lifecycle management.", "Using Function as a Service as the compute resource type for a workload.", "The time delay for data to travel between two points on a network."], "a": 0, "e": "A defined sequence of automated steps/tasks that process data or coordinate resources. Helps chain together cloud services and automate multi-step business processes."}, {"obj": "4.2", "q": "Select the most accurate description of \"Cloud Security Alliance\":", "c": ["An organization that publishes best practices and frameworks specifically for cloud security.", "Systems and Organization Controls 2 — an audit framework evaluating a service provider's controls around security, availability, and confidentiality.", "A data retention requirement mandated by law or industry regulation.", "Defining who legally owns and controls a given set of data."], "a": 0, "e": "An organization that publishes best practices and frameworks specifically for cloud security. Provides cloud-specific guidance (like the CCM) that general security standards may not fully address."}, {"obj": "1.3", "q": "A company needs to logically segment management traffic from application data traffic on the same physical switch infrastructure. What technology accomplishes this?", "c": ["BGP", "VLANs", "CDN caching", "A transit gateway"], "a": 1, "e": "VLANs logically segment a shared physical switch into isolated broadcast domains, separating different traffic types without extra hardware."}, {"obj": "4.1", "q": "A vulnerability assessment rates a newly discovered flaw as low severity because it requires local physical access to exploit and affects a non-critical internal tool. What does this rating most directly influence?", "c": ["Whether the vulnerability gets a CVE identifier", "The prioritization of remediation effort relative to other higher-severity vulnerabilities", "The scanning scope for future scans", "Nothing; all vulnerabilities are remediated with equal urgency regardless of severity"], "a": 1, "e": "Severity ratings from the assessment step directly inform how vulnerabilities are prioritized for remediation, with lower-severity issues typically addressed after higher-severity ones."}, {"obj": "5.2", "q": "Which term is most closely associated with this real-world importance: \"Reduces human error and speeds up the delivery of software changes.\"?", "c": ["CI/CD Automation", "Flat File Artifact", "Code Deployment", "Public Repository"], "a": 0, "e": "Reduces human error and speeds up the delivery of software changes. This describes CI/CD Automation (\"Automatically building, testing, and deploying code changes with minimal manual intervention.\")."}, {"obj": "2.1", "q": "Which concept is described by the phrase: \"Infrastructure dedicated to a single organization, hosted on- or off-premises.\"?", "c": ["On Premises", "Hybrid Cloud", "Community Cloud", "Private Cloud"], "a": 3, "e": "\"Infrastructure dedicated to a single organization, hosted on- or off-premises.\" describes Private Cloud. Offers greater control and customization at higher cost than public cloud."}, {"obj": "4.2", "q": "Select the most accurate description of \"Litigation Hold\":", "c": ["A legal requirement to preserve specific data because it may be relevant to pending litigation.", "The principle that data is subject to the laws of the country in which it is physically located.", "Requirements or preferences about the physical location where data is stored or processed.", "An international standard specifying requirements for an information security management system."], "a": 0, "e": "A legal requirement to preserve specific data because it may be relevant to pending litigation. Overrides normal retention/deletion schedules until the hold is lifted."}, {"obj": "1.3", "q": "Given the description \"A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute).\", which term is being defined?", "c": ["Transit Gateway", "VPC Peering", "Dedicated Connection", "BGP"], "a": 2, "e": "\"A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute).\" describes Dedicated Connection. Offers more consistent bandwidth/latency and often lower cost at scale than routing through the public internet."}, {"obj": "6.1", "q": "In cloud computing terminology, \"Oversubscription\" refers to which of the following?", "c": ["A provider intentionally limiting the rate of API calls a customer can make.", "A failure caused by mismatched software, hardware, or configuration versions.", "A previously available feature or API being retired by the provider.", "Allocating more virtual resources than the underlying physical capacity can truly support."], "a": 3, "e": "Allocating more virtual resources than the underlying physical capacity can truly support. Can cause performance degradation or failed provisioning if too many workloads compete for the same physical resources."}, {"obj": "4.4", "q": "A description reads: \"Practices and controls that protect APIs from abuse, unauthorized access, and attack.\" Which term does this describe?", "c": ["Data at Rest Encryption", "API Security", "Patching (Security)", "Zero Trust"], "a": 1, "e": "\"Practices and controls that protect APIs from abuse, unauthorized access, and attack.\" describes API Security. APIs are a primary attack surface in cloud-native applications and require dedicated protective controls."}, {"obj": "2.1", "q": "A company keeps its core financial systems on-premises for compliance reasons but bursts analytics workloads to the public cloud during peak reporting periods. Which deployment model describes this combination?", "c": ["Public cloud only", "Private cloud only", "Hybrid cloud", "Community cloud"], "a": 2, "e": "Hybrid cloud combines private/on-premises infrastructure with public cloud resources, exactly matching this burst-capacity scenario."}, {"obj": "1.4", "q": "A company wants to balance cost and retrieval speed for data that is accessed a few times per month but not daily. Which storage tier is the best fit?", "c": ["Hot tier", "Warm tier", "Archive tier", "In-memory cache only"], "a": 1, "e": "The warm tier balances moderate access frequency against cost, sitting between the fastest/most expensive hot tier and the slowest/cheapest archive tier."}, {"obj": "4.2", "q": "A company processing credit card transactions in the cloud must comply with which specific standard?", "c": ["ISO 27001", "PCI DSS", "SOC 2", "GDPR"], "a": 1, "e": "PCI DSS specifically governs organizations that store, process, or transmit payment card data."}, {"obj": "4.6", "q": "A security review discovers several cloud instances that are running and incurring cost but are unmonitored and not tied to any active project or owner. What are these called?", "c": ["Bastion hosts", "Zombie instances", "Reserved instances", "Load-balanced instances"], "a": 1, "e": "Zombie instances are forgotten, unmonitored resources that represent both wasted cost and an unmanaged, unpatched attack surface."}, {"obj": "1.3", "q": "How would you most accurately define \"Application Load Balancer\"?", "c": ["A hub service that connects many VPCs and on-premises networks through a single point.", "A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute).", "A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers).", "A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features."], "a": 2, "e": "A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers). Enables advanced routing such as sending /api traffic to one backend and /images to another."}, {"obj": "5.3", "q": "In cloud computing terminology, \"GraphQL\" refers to which of the following?", "c": ["Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local.", "A query language for APIs that lets clients request exactly the data they need.", "A protocol providing full-duplex, persistent communication channels over a single TCP connection.", "Representational State Transfer — an architectural style for web services using standard HTTP methods."], "a": 1, "e": "A query language for APIs that lets clients request exactly the data they need. Reduces over-fetching/under-fetching of data compared to traditional REST endpoints."}, {"obj": "4.5", "q": "Which concept is described by the phrase: \"Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic.\"?", "c": ["IAM Policies", "Network ACL", "WAF", "DDoS Protection"], "a": 3, "e": "\"Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic.\" describes DDoS Protection. Essential for internet-facing cloud services that could otherwise be overwhelmed by attack traffic."}, {"obj": "1.3", "q": "Select the most accurate description of \"Dedicated Connection\":", "c": ["A device or service that filters network traffic based on defined rules.", "A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute).", "A set of rules that determines where network traffic is directed.", "A hub service that connects many VPCs and on-premises networks through a single point."], "a": 1, "e": "A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute). Offers more consistent bandwidth/latency and often lower cost at scale than routing through the public internet."}, {"obj": "1.2", "q": "The acronym \"ISO\" stands for:", "c": ["OpenID Connect Protocol", "Remote Procedure Call", "International Organization for Standardization", "Common Weakness Enumeration"], "a": 2, "e": "ISO stands for International Organization for Standardization. Publishes international standards; also refers to a disk image (.iso) file format."}, {"obj": "1.6", "q": "A colleague says: \"Needed for stateful container workloads like databases, since container filesystems are normally ephemeral.\" Which concept are they describing?", "c": ["Persistent Volume", "Ephemeral Storage", "Stand-Alone Container", "Port Mapping"], "a": 0, "e": "Needed for stateful container workloads like databases, since container filesystems are normally ephemeral. This describes Persistent Volume (\"Storage that survives beyond the lifecycle of an individual container.\")."}, {"obj": "1.1", "q": "A retailer uses a fully managed email marketing tool accessed entirely through a web browser, with no infrastructure of their own involved. Which model is this?", "c": ["IaaS", "PaaS", "SaaS", "FaaS"], "a": 2, "e": "SaaS delivers a complete, ready-to-use application to end users with the provider managing everything underneath."}, {"obj": "1.10", "q": "Which concept is described by the phrase: \"Using virtual machines as the compute resource type for a workload.\"?", "c": ["Workflow (Optimization)", "Network Latency", "Network Throughput", "Compute Optimization (VM)"], "a": 3, "e": "\"Using virtual machines as the compute resource type for a workload.\" describes Compute Optimization (VM). Appropriate for workloads needing full OS control and long-running processes."}, {"obj": "4.3", "q": "Which of the following terms fits this definition: \"Authentication using a temporary token issued after initial login, rather than resending credentials each time.\"?", "c": ["Token-Based Authentication", "SSH", "Programmatic Access", "Federation"], "a": 0, "e": "\"Authentication using a temporary token issued after initial login, rather than resending credentials each time.\" describes Token-Based Authentication. Reduces the exposure of long-term credentials and supports short-lived, revocable sessions."}, {"obj": "1.11", "q": "Select the most accurate description of \"IoT Gateway\":", "c": ["AI technology that converts spoken audio into written text (speech recognition).", "The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data.", "AI technology that extracts text from images or scanned documents (OCR).", "A device that aggregates and relays data from multiple IoT sensors to the cloud."], "a": 3, "e": "A device that aggregates and relays data from multiple IoT sensors to the cloud. Reduces the number of direct cloud connections needed and can perform local pre-processing."}, {"obj": "1.10", "q": "Why does this matter on the exam and in practice? \"Important for workloads that move large volumes of data, like backups or media processing.\" — which term does this explain?", "c": ["Network Latency", "Managed Services (Optimization)", "Storage Throughput", "Orchestration (Workload)"], "a": 2, "e": "Important for workloads that move large volumes of data, like backups or media processing. This describes Storage Throughput (\"The rate of data transfer to/from a storage system, usually measured in MB/s or GB/s.\")."}, {"obj": "1.9", "q": "Which factor would most strongly justify choosing a self-managed database instead of a provider-managed service?", "c": ["A desire to minimize administrative overhead", "A need for a very specific custom configuration or extension not supported by any managed offering", "A need for automatic provider-managed backups", "A preference for the provider to handle all patching"], "a": 1, "e": "Self-managed databases make sense when a highly specific customization or extension is required that no managed service offers, despite the added operational burden."}, {"obj": "5.2", "q": "A pipeline builds a fully configured virtual machine image as its output artifact, ready to be launched as a new instance. What type of artifact is this?", "c": ["A container image artifact", "A VM image artifact", "An RPM package", "A flat file artifact"], "a": 1, "e": "A VM image artifact is a packaged virtual machine image produced as a build output, providing a versioned, reusable deployment unit for VM-based workloads."}, {"obj": "5.2", "q": "A team defines an explicit sequence of stages — build, test, security scan, and deploy — that every code change automatically passes through. What is this sequence called?", "c": ["A code review checklist", "A CI/CD workflow", "Branch management", "An artifact repository"], "a": 1, "e": "A CI/CD workflow is the defined sequence of automated stages a change passes through from commit to deployment, documenting and enforcing a consistent process."}, {"obj": "1.10", "q": "Which statement accurately describes \"Workflow (Optimization)\"?", "c": ["Using Function as a Service as the compute resource type for a workload.", "Using provider-operated services instead of self-managed infrastructure to reduce operational overhead.", "The rate of data transfer to/from a storage system, usually measured in MB/s or GB/s.", "A defined sequence of automated steps/tasks that process data or coordinate resources."], "a": 3, "e": "A defined sequence of automated steps/tasks that process data or coordinate resources. Helps chain together cloud services and automate multi-step business processes."}, {"obj": "5.2", "q": "Which of the following best describes \"Code Deployment\"?", "c": ["A package format (.deb) used for installing software on Debian-based Linux distributions.", "A simple, unstructured file (like a config or script) produced or consumed by a pipeline.", "A packaged virtual machine image produced and stored as a build output.", "Releasing built and tested code to a target environment (e.g., production)."], "a": 3, "e": "Releasing built and tested code to a target environment (e.g., production). The \"CD\" in CI/CD — automating this step reduces the risk and effort of releasing changes."}, {"obj": "1.8", "q": "A batch analytics job can tolerate being interrupted and restarted, and cost is the top priority. Which pricing option offers the deepest discount?", "c": ["Reserved resources", "Spot instances", "Dedicated host", "Pay-as-you-go"], "a": 1, "e": "Spot instances offer steep discounts on spare capacity but can be reclaimed by the provider, making them suitable only for interruption-tolerant workloads."}, {"obj": "1.9", "q": "A company wants to store a database but avoid handling patching, backups, and maintenance themselves. What should they use?", "c": ["A self-managed database on a VM", "A provider-managed database service", "Local block storage", "An object storage bucket"], "a": 1, "e": "Provider-managed database services (DBaaS) handle patching, backups, and maintenance on behalf of the customer."}, {"obj": "2.3", "q": "Which term is most closely associated with this real-world importance: \"The most common migration type when organizations first adopt cloud computing.\"?", "c": ["On-Premises-to-Cloud Migration", "Rehost", "Cloud-to-Cloud Migration", "Retain"], "a": 0, "e": "The most common migration type when organizations first adopt cloud computing. This describes On-Premises-to-Cloud Migration (\"Moving workloads from local infrastructure into a cloud environment.\")."}, {"obj": "4.3", "q": "Which term best matches this description: \"Accessing cloud resources via code rather than a human using a GUI (API/SDK).\"?", "c": ["Programmatic Access", "Directory-Based Authentication", "MFA", "SAML"], "a": 0, "e": "\"Accessing cloud resources via code rather than a human using a GUI (API/SDK).\" describes Programmatic Access. Enables automation but requires careful credential management since keys can be leaked or misused."}, {"obj": "4.6", "q": "Which of the following best describes \"Event Monitoring (Security)\"?", "c": ["Network ports left open on a system that are not required for its function.", "Malware that encrypts a victim's data and demands payment for the decryption key.", "Continuously observing system and security events for signs of malicious activity.", "A cloud instance that is running but forgotten, unmonitored, or unmanaged."], "a": 2, "e": "Continuously observing system and security events for signs of malicious activity. Provides the raw visibility needed to detect an attack in progress."}, {"obj": "1.10", "q": "A team needs full OS-level control and long-running background processes that must persist indefinitely. Which compute type is most appropriate?", "c": ["Serverless functions", "Virtual machines", "Ephemeral containers only", "A CDN edge function"], "a": 1, "e": "VMs provide full OS control and are well suited to long-running processes that need to persist, unlike serverless functions designed for short-lived executions."}, {"obj": "2.3", "q": "A company migrates its production database from one cloud provider to another to take advantage of better pricing. What type of migration is this?", "c": ["On-premises-to-cloud", "Cloud-to-on-premises", "Cloud-to-cloud", "Retain"], "a": 2, "e": "Cloud-to-cloud migration moves workloads between different cloud providers or regions, often for cost or feature reasons."}, {"obj": "2.1", "q": "How would you most accurately define \"Community Cloud\"?", "c": ["A deployment model combining private/on-premises infrastructure with public cloud resources.", "Infrastructure owned by a third-party provider and shared across many customers (multi-tenant).", "Infrastructure dedicated to a single organization, hosted on- or off-premises.", "Infrastructure shared by several organizations with common concerns such as compliance or security requirements."], "a": 3, "e": "Infrastructure shared by several organizations with common concerns such as compliance or security requirements. Balances shared cost benefits with more tailored governance than a general public cloud."}, {"obj": "2.4", "q": "Given the description \"Identifying when a deployed resource's actual state no longer matches its defined IaC configuration.\", which term is being defined?", "c": ["Infrastructure as Code", "Drift Detection", "JSON", "IaC Testing"], "a": 1, "e": "\"Identifying when a deployed resource's actual state no longer matches its defined IaC configuration.\" describes Drift Detection. Helps catch unauthorized or manual changes that could cause inconsistency or security gaps."}, {"obj": "3.2", "q": "A message-processing service scales out additional worker instances whenever the backlog in its queue exceeds 1,000 pending messages, rather than reacting to CPU usage. What scaling approach is this?", "c": ["Triggered scaling — event-based", "Scheduled scaling", "Manual scaling", "Vertical scaling"], "a": 0, "e": "Event-triggered scaling reacts to a specific event or condition, like queue depth, rather than pure CPU/memory thresholds, useful for event-driven architectures."}, {"obj": "3.2", "q": "A team configures their message queue processing service to add workers automatically whenever queue depth exceeds a threshold, and remove them once the backlog clears. What type of scaling trigger is queue depth?", "c": ["A scheduled trigger", "An event-based trigger", "A vertical scaling trigger", "A manual trigger"], "a": 1, "e": "Queue depth is an event/condition-based trigger, distinct from a fixed schedule or a pure CPU/memory load threshold, fitting the event-triggered scaling category."}, {"obj": "2.2", "q": "Given the description \"Gradually rolling out a change to a small subset of users or servers before a full rollout.\", which term is being defined?", "c": ["Rolling Deployment", "In-Place Deployment", "Canary Deployment", "Blue-Green Deployment"], "a": 2, "e": "\"Gradually rolling out a change to a small subset of users or servers before a full rollout.\" describes Canary Deployment. Limits the blast radius of a bad deployment by exposing it to only a fraction of traffic first."}, {"obj": "2.2", "q": "In cloud computing terminology, \"Rolling Deployment\" refers to which of the following?", "c": ["Gradually rolling out a change to a small subset of users or servers before a full rollout.", "Updating instances incrementally, a few at a time, rather than all at once.", "Updating an existing server or instance directly rather than deploying an entirely new one.", "A strategy running two identical environments (blue and green), switching traffic to the new version once verified."], "a": 1, "e": "Updating instances incrementally, a few at a time, rather than all at once. Keeps the application available throughout the deployment, at the cost of a longer overall rollout window."}, {"obj": "1.3", "q": "In Cloud+ terminology, \"NAT\" is an abbreviation for which of the following?", "c": ["Virtual Private Network", "Security Assertion Markup Language", "Input/Output Operations Per Second", "Network Address Translation"], "a": 3, "e": "NAT stands for Network Address Translation. Translates private IP addresses to a public address (or vice versa) for routing."}, {"obj": "1.6", "q": "Given the description \"Automated management of container deployment, scaling, and healing (e.g., Kubernetes).\", which term is being defined?", "c": ["Image Registry", "Workload Orchestration", "Port Mapping", "Stand-Alone Container"], "a": 1, "e": "\"Automated management of container deployment, scaling, and healing (e.g., Kubernetes).\" describes Workload Orchestration. Essential for running containerized applications reliably at scale in production."}, {"obj": "4.5", "q": "In Cloud+ terminology, \"HTTP\" is an abbreviation for which of the following?", "c": ["Local Area Network", "Solid-state Drive", "Remote Procedure Call", "Hypertext Transfer Protocol"], "a": 3, "e": "HTTP stands for Hypertext Transfer Protocol. The unencrypted protocol used to transfer web content."}, {"obj": "1.7", "q": "A company deploys a cluster of hypervisor hosts and configures VM templates and ISOs to be centrally stored and accessible by all hosts over the network. What storage type is most likely being used for this shared repository?", "c": ["Local storage", "NAS", "Hardware pass-through storage", "Ephemeral storage"], "a": 1, "e": "NAS provides shared file-level storage accessible by multiple hosts, commonly used for storing VM templates and ISO images centrally."}, {"obj": "1.7", "q": "\"Clustering\" is best defined as which of the following?", "c": ["Storage physically attached to a single hypervisor host.", "A single hypervisor host running VMs with no clustering.", "The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network.", "Grouping multiple hypervisor hosts together to share resources and enable failover/migration."], "a": 3, "e": "Grouping multiple hypervisor hosts together to share resources and enable failover/migration. Enables high availability and load balancing of VMs across multiple physical hosts."}, {"obj": "4.2", "q": "An administrator explains the importance of a concept: \"Clarifies responsibility and rights when data is stored or processed by a third-party cloud provider.\" What concept is this?", "c": ["Data Locality", "Data Ownership", "ISO 27001", "Regulatory Retention"], "a": 1, "e": "Clarifies responsibility and rights when data is stored or processed by a third-party cloud provider. This describes Data Ownership (\"Defining who legally owns and controls a given set of data.\")."}, {"obj": "4.2", "q": "Which of the following best describes \"Litigation Hold\"?", "c": ["A legal requirement to preserve specific data because it may be relevant to pending litigation.", "Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted).", "A data retention requirement mandated by law or industry regulation.", "An international standard specifying requirements for an information security management system."], "a": 0, "e": "A legal requirement to preserve specific data because it may be relevant to pending litigation. Overrides normal retention/deletion schedules until the hold is lifted."}, {"obj": "5.2", "q": "How would you most accurately define \"Flat File Artifact\"?", "c": ["A packaged virtual machine image produced and stored as a build output.", "Releasing built and tested code to a target environment (e.g., production).", "Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions.", "A simple, unstructured file (like a config or script) produced or consumed by a pipeline."], "a": 3, "e": "A simple, unstructured file (like a config or script) produced or consumed by a pipeline. Sometimes all that's needed for simple deployment tasks, without a full package format."}, {"obj": "1.10", "q": "A workload experiencing high latency between two dependent microservices deployed in different regions should consider which optimization?", "c": ["Increasing IOPS on an unrelated storage volume", "Relocating the services closer together to reduce network latency", "Switching to archive tier storage", "Disabling monitoring"], "a": 1, "e": "Since the issue is inter-service network latency across regions, relocating the dependent services closer together directly addresses the root cause."}, {"obj": "1.3", "q": "Which concept is described by the phrase: \"A hub service that connects many VPCs and on-premises networks through a single point.\"?", "c": ["BGP", "VPN", "Firewall", "Transit Gateway"], "a": 3, "e": "\"A hub service that connects many VPCs and on-premises networks through a single point.\" describes Transit Gateway. Simplifies large-scale network architectures compared to a full mesh of individual peering connections."}, {"obj": "3.1", "q": "A company experiences a production incident but discovers that the relevant logs were already deleted per an overly aggressive retention policy, hampering the investigation. What should be reconsidered?", "c": ["The tracing configuration only", "The log retention policy's duration for logs relevant to incident investigation", "The monitoring dashboard's color scheme", "The alert triage process only"], "a": 1, "e": "An overly short log retention policy can destroy evidence needed for incident investigation; the retention duration should be reconsidered to balance cost against investigative needs."}, {"obj": "4.5", "q": "In Cloud+ terminology, \"DLP\" is an abbreviation for which of the following?", "c": ["Data Loss Prevention", "Software-defined Network", "Operating System", "Information Technology Infrastructure Library"], "a": 0, "e": "DLP stands for Data Loss Prevention. Controls that detect and prevent unauthorized transmission of sensitive data."}, {"obj": "6.1", "q": "Which concept is described by the phrase: \"A deployment failure or performance problem caused by choosing an inappropriately sized resource.\"?", "c": ["Regional Service Availability", "Permission Issues (Deployment)", "Sizing Issues", "API Throttling"], "a": 2, "e": "\"A deployment failure or performance problem caused by choosing an inappropriately sized resource.\" describes Sizing Issues. Both undersizing (poor performance) and oversizing (wasted cost) are common sizing mistakes."}, {"obj": "1.3", "q": "Which of the following best describes \"Network Load Balancer\"?", "c": ["Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management.", "A set of rules that determines where network traffic is directed.", "A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers).", "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port."], "a": 3, "e": "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port. Provides extremely high throughput and low latency for use cases where Layer 7 inspection isn't needed."}, {"obj": "2.4", "q": "Which of the following terms fits this definition: \"Tracking changes to infrastructure code over time using version control.\"?", "c": ["Infrastructure as Code", "JSON", "IaC Versioning", "IaC Testing"], "a": 2, "e": "\"Tracking changes to infrastructure code over time using version control.\" describes IaC Versioning. Enables rollback to a known-good configuration and provides an audit trail of infrastructure changes."}, {"obj": "1.4", "q": "A description reads: \"Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.\" Which term does this describe?", "c": ["File Storage", "Warm Storage Tier", "HDD", "SSD"], "a": 3, "e": "\"Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.\" describes SSD. The default choice for performance-sensitive workloads like databases."}, {"obj": "1.11", "q": "Which statement accurately describes \"IoT Communication\"?", "c": ["AI technology that extracts text from images or scanned documents (OCR).", "AI technology that identifies objects, scenes, or features within images or video.", "AI technology that converts written text into spoken audio (speech synthesis).", "The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data."], "a": 3, "e": "The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data. Choice of communication method affects range, power consumption, and bandwidth available to the device."}, {"obj": "4.5", "q": "\"Network Security Group\" is best defined as which of the following?", "c": ["A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs.", "Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications.", "Access Control List — a set of rules controlling traffic in and out of a subnet at the network level.", "Security software (antivirus, EDR) installed directly on servers, VMs, or devices."], "a": 0, "e": "A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs. The primary mechanism for instance-level network access control in most cloud platforms."}, {"obj": "1.5", "q": "Given the description \"A service the cloud provider fully operates (e.g., a managed database), removing the customer's operational burden.\", which term is being defined?", "c": ["Fan-Out", "Cloud-Provided Managed Service", "Loosely Coupled Architecture", "Service Discovery"], "a": 1, "e": "\"A service the cloud provider fully operates (e.g., a managed database), removing the customer's operational burden.\" describes Cloud-Provided Managed Service. Reduces administrative overhead at the cost of some control and customization."}, {"obj": "6.1", "q": "Which term best matches this description: \"A failure caused by mismatched software, hardware, or configuration versions.\"?", "c": ["Deprecation of Functionality", "Outdated Component Definitions", "Incompatibility (Deployment)", "Full Outage"], "a": 2, "e": "\"A failure caused by mismatched software, hardware, or configuration versions.\" describes Incompatibility (Deployment). A very common root cause of failed deployments, especially after an update to one dependency."}, {"obj": "1.1", "q": "An administrator explains the importance of a concept: \"Responsibility shifts up the stack as you move from IaaS to PaaS to SaaS — misunderstanding this is a common real-world security gap.\" What concept is this?", "c": ["IaaS", "Shared Responsibility Model", "FaaS", "PaaS"], "a": 1, "e": "Responsibility shifts up the stack as you move from IaaS to PaaS to SaaS — misunderstanding this is a common real-world security gap. This describes Shared Responsibility Model (\"A framework defining which security and operational tasks belong to the cloud provider versus the customer.\")."}, {"obj": "4.6", "q": "Why does this matter on the exam and in practice? \"One of the most common initial access vectors used in real-world breaches.\" — which term does this explain?", "c": ["Cryptojacking", "Phishing", "DDoS", "Malware"], "a": 1, "e": "One of the most common initial access vectors used in real-world breaches. This describes Phishing (\"A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email.\")."}, {"obj": "1.7", "q": "An administrator needs to rapidly deploy 20 identical VMs for a training lab based on one pre-configured VM. What technique should be used?", "c": ["Hardware pass-through", "Cloning", "Host affinity", "An overlay network"], "a": 1, "e": "Cloning creates exact copies of an existing VM, allowing rapid, consistent deployment of many identical VMs."}, {"obj": "1.10", "q": "Which of the following best describes \"Storage Throughput\"?", "c": ["Using provider-operated services instead of self-managed infrastructure to reduce operational overhead.", "Input/Output Operations Per Second — a measure of storage performance.", "The rate of data transfer to/from a storage system, usually measured in MB/s or GB/s.", "Automated coordination of workload deployment, scaling, and lifecycle management."], "a": 2, "e": "The rate of data transfer to/from a storage system, usually measured in MB/s or GB/s. Important for workloads that move large volumes of data, like backups or media processing."}, {"obj": "3.3", "q": "Which of the following terms fits this definition: \"Restoring data to an alternate system running alongside the original.\"?", "c": ["Backup Recoverability Testing", "Backup Retention (Ops)", "In-Place Recovery", "Parallel Recovery"], "a": 3, "e": "\"Restoring data to an alternate system running alongside the original.\" describes Parallel Recovery. Useful for testing a restore or recovering without disrupting the still-running original system."}, {"obj": "3.4", "q": "Which term is most closely associated with this real-world importance: \"Reduces the risk that a routine update introduces a new production issue.\"?", "c": ["Major Update", "Decommissioning — End of Support", "Minor Update", "Lifecycle Testing"], "a": 3, "e": "Reduces the risk that a routine update introduces a new production issue. This describes Lifecycle Testing (\"Validating changes (patches, updates, configuration) before applying them broadly.\")."}, {"obj": "1.10", "q": "An administrator explains the importance of a concept: \"A critical factor when placing workloads and choosing regions/AZs for latency-sensitive applications.\" What concept is this?", "c": ["Managed Services (Optimization)", "Network Latency", "IOPS (Optimization)", "Orchestration (Workload)"], "a": 1, "e": "A critical factor when placing workloads and choosing regions/AZs for latency-sensitive applications. This describes Network Latency (\"The time delay for data to travel between two points on a network.\")."}, {"obj": "4.2", "q": "\"SOC2\" is best defined as which of the following?", "c": ["Payment Card Industry Data Security Standard — security requirements for handling payment card data.", "An international standard specifying requirements for an information security management system.", "Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted).", "Systems and Organization Controls 2 — an audit framework evaluating a service provider's controls around security, availability, and confidentiality."], "a": 3, "e": "Systems and Organization Controls 2 — an audit framework evaluating a service provider's controls around security, availability, and confidentiality. A common compliance report requested by customers evaluating a cloud vendor's security posture."}, {"obj": "5.3", "q": "A web API uses standard HTTP methods like GET, POST, PUT, and DELETE to manage resources, and is stateless between requests. What architectural style is this?", "c": ["SOAP", "REST", "RPC", "GraphQL exclusively"], "a": 1, "e": "REST is an architectural style for web services using standard HTTP methods and stateless request handling, the most common modern API style."}, {"obj": "1.2", "q": "A description reads: \"Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption.\" Which term does this describe?", "c": ["Edge Computing", "RPO", "RTO", "Warm Site"], "a": 2, "e": "\"Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption.\" describes RTO. Drives the choice of DR site type and how much automation/investment is needed to meet the target."}, {"obj": "3.4", "q": "Which concept is described by the phrase: \"Validating changes (patches, updates, configuration) before applying them broadly.\"?", "c": ["Minor Update", "Lifecycle Testing", "Decommissioning — End of Life", "Decommissioning — End of Support"], "a": 1, "e": "\"Validating changes (patches, updates, configuration) before applying them broadly.\" describes Lifecycle Testing. Reduces the risk that a routine update introduces a new production issue."}, {"obj": "1.8", "q": "A company needs a full physical host dedicated to their workload due to a software vendor's per-physical-host licensing terms, even though they don't use all its capacity. What billing model addresses this?", "c": ["Pay-as-you-go", "Spot instance pricing", "Dedicated host billing", "Reserved resource pricing"], "a": 2, "e": "Dedicated host billing charges for an entire physical host regardless of utilization, which is necessary here to satisfy per-host licensing terms requiring physical isolation."}, {"obj": "3.2", "q": "Why does this matter on the exam and in practice? \"Useful for event-driven architectures where load isn't purely CPU/memory based.\" — which term does this explain?", "c": ["Triggered Scaling — Event", "Manual Scaling", "Vertical Scaling", "Triggered Scaling — Trending"], "a": 0, "e": "Useful for event-driven architectures where load isn't purely CPU/memory based. This describes Triggered Scaling — Event (\"Scaling in response to a specific event (like a message queue depth increasing).\")."}, {"obj": "2.4", "q": "Which scenario best illustrates configuration drift that IaC drift detection is designed to catch?", "c": ["A resource is provisioned exactly as defined in the IaC template with no later changes", "An engineer manually adds an extra open port to a security group directly in the console, diverging from the IaC-defined rules", "A team updates the IaC template and redeploys through the normal pipeline", "A team deletes an unused IaC template file"], "a": 1, "e": "A manual, out-of-band change made directly in the console (bypassing the IaC pipeline) is exactly the kind of divergence drift detection is designed to catch."}, {"obj": "1.3", "q": "Given the description \"Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network.\", which term is being defined?", "c": ["VPC Peering", "Subnet", "Dedicated Connection", "VPN"], "a": 3, "e": "\"Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network.\" describes VPN. A common way to connect on-premises networks or remote users securely to cloud resources."}, {"obj": "4.4", "q": "How would you most accurately define \"Patching (Security)\"?", "c": ["Encrypting data as it moves across a network (e.g., via TLS).", "Applying vendor-released updates that fix known vulnerabilities.", "A container granted elevated access to the host system's resources.", "Practices and controls that protect APIs from abuse, unauthorized access, and attack."], "a": 1, "e": "Applying vendor-released updates that fix known vulnerabilities. Closes known security gaps that attackers commonly target since patches for them already exist."}, {"obj": "5.4", "q": "A team needs a distributed version control system to track every change to their source code, enabling branching, merging, and collaboration among developers. Which tool is the de facto standard?", "c": ["Jenkins", "Git", "Grafana", "Kubernetes"], "a": 1, "e": "Git is the de facto standard distributed version control system underlying most modern DevOps and source control workflows."}, {"obj": "1.6", "q": "Why does this matter on the exam and in practice? \"Simple to run for development/testing but lacks automated scaling, healing, or scheduling.\" — which term does this explain?", "c": ["Workload Orchestration", "Persistent Volume", "Ephemeral Storage", "Stand-Alone Container"], "a": 3, "e": "Simple to run for development/testing but lacks automated scaling, healing, or scheduling. This describes Stand-Alone Container (\"A single container running in isolation without orchestration.\")."}, {"obj": "1.8", "q": "\"Dedicated Host Billing\" is best defined as which of the following?", "c": ["Pre-purchasing capacity for a discounted rate in exchange for a committed term.", "A billing model charging only for actual resource consumption, with no upfront commitment.", "A billing model where a customer pays for an entire physical host, regardless of utilization.", "Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice."], "a": 2, "e": "A billing model where a customer pays for an entire physical host, regardless of utilization. Useful for licensing or compliance requirements that need physical isolation from other tenants."}, {"obj": "3.2", "q": "\"Triggered Scaling — Load\" is best defined as which of the following?", "c": ["Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU).", "Increasing the resources (CPU/RAM) of an existing instance (scale up).", "Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%).", "Adding more instances of a resource to handle increased load (scale out)."], "a": 2, "e": "Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%). The most common autoscaling trigger, reacting quickly to current demand."}, {"obj": "1.1", "q": "A description reads: \"Platform as a Service — provides a managed runtime/platform for developing and deploying applications without managing the underlying OS.\" Which term does this describe?", "c": ["Shared Responsibility Model", "FaaS", "PaaS", "SaaS"], "a": 2, "e": "\"Platform as a Service — provides a managed runtime/platform for developing and deploying applications without managing the underlying OS.\" describes PaaS. Developers push code and the provider handles the OS, runtime, and scaling, speeding up application delivery."}, {"obj": "2.5", "q": "A team provisions a new service without assessing availability requirements and later experiences a full outage when a single availability zone fails, since everything was deployed in just one AZ. What was missing from the original provisioning process?", "c": ["Compute requirements assessment", "Availability requirements assessment driving a multi-AZ design", "Compliance requirements assessment", "Network requirements assessment"], "a": 1, "e": "A proper availability requirements assessment would have driven a multi-AZ (or multi-region) design, avoiding a single point of failure at the AZ level."}, {"obj": "5.3", "q": "Which of the following is the correct expansion of \"RTMP\"?", "c": ["Real-time Messaging Protocol", "Local Area Network", "Availability Zone", "Network Address Translation"], "a": 0, "e": "RTMP stands for Real-time Messaging Protocol. A protocol historically used for streaming audio, video, and data over the internet."}, {"obj": "2.1", "q": "\"Public Cloud\" is best defined as which of the following?", "c": ["Infrastructure owned by a third-party provider and shared across many customers (multi-tenant).", "A deployment model combining private/on-premises infrastructure with public cloud resources.", "Infrastructure physically located and managed within the organization's own facilities.", "Infrastructure shared by several organizations with common concerns such as compliance or security requirements."], "a": 0, "e": "Infrastructure owned by a third-party provider and shared across many customers (multi-tenant). Lowest upfront cost and fastest to provision, but less control than private cloud."}, {"obj": "1.3", "q": "Which of the following terms fits this definition: \"A logical subdivision of a network's IP address range.\"?", "c": ["Static Route", "CDN", "Subnet", "Firewall"], "a": 2, "e": "\"A logical subdivision of a network's IP address range.\" describes Subnet. Used within a VPC to separate resources (e.g., public-facing vs. private-only) for security and routing control."}, {"obj": "1.4", "q": "Which of the following is the correct expansion of \"API\"?", "c": ["General Data Protection Regulation", "Multifactor Authentication", "Application Programming Interface", "Red Hat Package Manager"], "a": 2, "e": "API stands for Application Programming Interface. A defined interface letting software components communicate, often used for cloud automation."}, {"obj": "1.8", "q": "Which of the following best describes \"Reserved Resources\"?", "c": ["A billing model where a customer pays for an entire physical host, regardless of utilization.", "A billing model charging only for actual resource consumption, with no upfront commitment.", "Pre-purchasing capacity for a discounted rate in exchange for a committed term.", "Tracking actual consumption of cloud resources for billing and capacity planning purposes."], "a": 2, "e": "Pre-purchasing capacity for a discounted rate in exchange for a committed term. Reduces cost for predictable, steady-state workloads compared to pay-as-you-go pricing."}, {"obj": "5.1", "q": "A colleague says: \"Integrates parallel work from multiple developers or feature branches.\" Which concept are they describing?", "c": ["Code Merge", "Branch Management", "Code Commit", "Version Management"], "a": 0, "e": "Integrates parallel work from multiple developers or feature branches. This describes Code Merge (\"Combining changes from different branches into one.\")."}, {"obj": "5.4", "q": "A team wants an agentless tool that uses simple YAML playbooks to automate configuration across many servers. Which tool fits?", "c": ["Terraform", "Ansible", "Jenkins", "Grafana"], "a": 1, "e": "Ansible is an agentless automation tool that uses YAML playbooks for configuration management across many systems."}, {"obj": "4.3", "q": "An administrator explains the importance of a concept: \"API access typically requires its own credentials (keys/tokens) separate from human user logins.\" What concept is this?", "c": ["SSH", "API (IAM Context)", "OpenID Connect", "MFA"], "a": 1, "e": "API access typically requires its own credentials (keys/tokens) separate from human user logins. This describes API (IAM Context) (\"Application Programming Interface — used here for programmatic management/access to cloud resources.\")."}, {"obj": "2.1", "q": "Which of the following is a key trade-off of choosing public cloud over a private cloud deployment?", "c": ["Public cloud always costs more upfront", "Public cloud offers less control and customization in exchange for lower cost and faster provisioning", "Public cloud cannot be used by any regulated industry", "Private cloud always has faster deployment times"], "a": 1, "e": "Public cloud trades some control and customization for lower upfront cost and faster provisioning, compared to a dedicated private cloud."}, {"obj": "4.4", "q": "How would you most accurately define \"API Security\"?", "c": ["Practices and controls that protect APIs from abuse, unauthorized access, and attack.", "Applying vendor-released updates that fix known vulnerabilities.", "Encrypting data as it moves across a network (e.g., via TLS).", "A security model that assumes no user or device should be trusted by default, even inside the network perimeter."], "a": 0, "e": "Practices and controls that protect APIs from abuse, unauthorized access, and attack. APIs are a primary attack surface in cloud-native applications and require dedicated protective controls."}, {"obj": "1.3", "q": "Which concept is described by the phrase: \"A logical subdivision of a network's IP address range.\"?", "c": ["Network Load Balancer", "Application Load Balancer", "VPC", "Subnet"], "a": 3, "e": "\"A logical subdivision of a network's IP address range.\" describes Subnet. Used within a VPC to separate resources (e.g., public-facing vs. private-only) for security and routing control."}, {"obj": "1.6", "q": "Which term best matches this description: \"Storage that survives beyond the lifecycle of an individual container.\"?", "c": ["Ephemeral Storage", "Stand-Alone Container", "Port Mapping", "Persistent Volume"], "a": 3, "e": "\"Storage that survives beyond the lifecycle of an individual container.\" describes Persistent Volume. Needed for stateful container workloads like databases, since container filesystems are normally ephemeral."}, {"obj": "1.8", "q": "Which term best matches this description: \"A billing model charging only for actual resource consumption, with no upfront commitment.\"?", "c": ["Reserved Resources", "Pay-As-You-Go", "Resource Metering", "Dedicated Host Billing"], "a": 1, "e": "\"A billing model charging only for actual resource consumption, with no upfront commitment.\" describes Pay-As-You-Go. Maximizes flexibility for unpredictable or short-term workloads, at a higher per-unit cost than reserved pricing."}, {"obj": "3.4", "q": "\"Minor Update\" is best defined as which of the following?", "c": ["A significant version update that may include new features and breaking changes.", "Temporary data that does not need to persist beyond a session or process.", "Validating changes (patches, updates, configuration) before applying them broadly.", "A smaller update, typically with bug fixes and small improvements."], "a": 3, "e": "A smaller update, typically with bug fixes and small improvements. Generally lower risk than major updates but should still be tested before production rollout."}, {"obj": "4.4", "q": "How would you most accurately define \"Secrets Management\"?", "c": ["Access controls and encryption applied to shared file storage systems.", "Securely storing and controlling access to credentials, API keys, and other sensitive configuration values.", "Applying vendor-released updates that fix known vulnerabilities.", "Granting only the minimum access rights needed to perform a function."], "a": 1, "e": "Securely storing and controlling access to credentials, API keys, and other sensitive configuration values. Prevents secrets from being hardcoded in source code or exposed in plaintext configuration files."}, {"obj": "6.3", "q": "Which concept is described by the phrase: \"Access to a system or data by someone without proper permission.\"?", "c": ["Unauthorized Access", "Privilege Escalation (Troubleshooting)", "Software Vulnerability Issues", "Cipher Suite Deprecation"], "a": 0, "e": "\"Access to a system or data by someone without proper permission.\" describes Unauthorized Access. The core security incident type that access controls, logging, and monitoring are designed to catch."}, {"obj": "1.6", "q": "An administrator explains the importance of a concept: \"Allows external traffic to reach a service running inside an otherwise isolated container.\" What concept is this?", "c": ["Persistent Volume", "Port Mapping", "Stand-Alone Container", "Workload Orchestration"], "a": 1, "e": "Allows external traffic to reach a service running inside an otherwise isolated container. This describes Port Mapping (\"Binding a container's internal port to a port on the host or load balancer.\")."}, {"obj": "4.4", "q": "A developer hardcodes a database password directly into application source code, which is later exposed in a public repository. What practice, if followed, would have prevented this exposure?", "c": ["API security", "Secrets management using a dedicated vault service", "Zero Trust enforcement only", "Data at rest encryption alone"], "a": 1, "e": "Secrets management stores credentials securely in a dedicated vault rather than hardcoding them in source code, directly preventing this kind of exposure."}, {"obj": "2.2", "q": "Select the most accurate description of \"Blue-Green Deployment\":", "c": ["Updating an existing server or instance directly rather than deploying an entirely new one.", "A strategy running two identical environments (blue and green), switching traffic to the new version once verified.", "Gradually rolling out a change to a small subset of users or servers before a full rollout.", "Updating instances incrementally, a few at a time, rather than all at once."], "a": 1, "e": "A strategy running two identical environments (blue and green), switching traffic to the new version once verified. Allows near-instant rollback by simply switching traffic back to the previous environment."}, {"obj": "1.7", "q": "Which of the following terms fits this definition: \"Grouping multiple hypervisor hosts together to share resources and enable failover/migration.\"?", "c": ["NAS (Virtualization Context)", "Stand-Alone Virtualization", "Cloning", "Clustering"], "a": 3, "e": "\"Grouping multiple hypervisor hosts together to share resources and enable failover/migration.\" describes Clustering. Enables high availability and load balancing of VMs across multiple physical hosts."}, {"obj": "1.7", "q": "Which of the following best explains the purpose of host affinity rules in a virtualization cluster?", "c": ["To keep specified VMs running on the same physical host, often for performance or licensing reasons", "To ensure VMs are always spread across every available host", "To prevent any VM from ever being migrated", "To disable clustering entirely"], "a": 0, "e": "Host affinity rules keep specified VMs together on the same host, which can be useful for performance (low-latency communication) or licensing requirements."}, {"obj": "4.3", "q": "Why does this matter on the exam and in practice? \"Flexible, but relies on individual owners consistently applying good judgment about access grants.\" — which term does this explain?", "c": ["Web Portal", "Discretionary Access Control", "Token-Based Authentication", "Local User Authentication"], "a": 1, "e": "Flexible, but relies on individual owners consistently applying good judgment about access grants. This describes Discretionary Access Control (\"An access model where the resource owner decides who else can access it.\")."}, {"obj": "3.3", "q": "A user accidentally deletes a single important file from a large dataset. What type of recovery is most appropriate?", "c": ["Bulk recovery", "Granular recovery", "In-place recovery of the entire system", "Parallel recovery of everything"], "a": 1, "e": "Granular recovery restores individual files or specific data items rather than an entire dataset, saving time for small-scope restores."}, {"obj": "6.2", "q": "Which statement accurately describes \"DNS (Troubleshooting)\"?", "c": ["Domain Name System — resolves hostnames to IP addresses.", "A connectivity failure caused by a system relying on a protocol version the other side no longer supports.", "Two networks using conflicting/duplicate IP address ranges.", "Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500)."], "a": 0, "e": "Domain Name System — resolves hostnames to IP addresses. DNS failures cause connectivity issues that look like the destination is down, even when it's reachable by IP."}, {"obj": "2.4", "q": "Given the description \"Validating infrastructure code for syntax, security, and logic before it is applied to real environments.\", which term is being defined?", "c": ["Infrastructure as Code", "IaC Testing", "Drift Detection", "YAML"], "a": 1, "e": "\"Validating infrastructure code for syntax, security, and logic before it is applied to real environments.\" describes IaC Testing. Catches errors before they cause an outage or misconfiguration in production."}, {"obj": "5.2", "q": "Why does this matter on the exam and in practice? \"Shifts security left, catching vulnerabilities earlier and cheaper than after deployment.\" — which term does this explain?", "c": ["Public Repository", "CI/CD Automation", "CI/CD Security", "CI/CD Testing"], "a": 2, "e": "Shifts security left, catching vulnerabilities earlier and cheaper than after deployment. This describes CI/CD Security (\"Incorporating security scanning and checks into the automated pipeline.\")."}, {"obj": "1.5", "q": "A company wants new instances of a checkout service to be automatically detected by the API gateway as soon as they start, and removed as soon as they stop. What supports this behavior?", "c": ["Manual gateway reconfiguration for every deployment", "Service discovery integrated with the gateway", "A single static list of IP addresses", "A monolithic deployment model"], "a": 1, "e": "Service discovery integrated with the gateway allows automatic detection of new and removed instances without manual reconfiguration."}, {"obj": "4.3", "q": "Which of the following is the correct expansion of \"IAM\"?", "c": ["Data Security Standard", "Web Application Firewall", "Identity and Access Management", "Availability Zone"], "a": 2, "e": "IAM stands for Identity and Access Management. The framework of policies and tools controlling who can access which cloud resources."}, {"obj": "5.3", "q": "A frontend team wants to request exactly the specific fields they need from a backend API in a single query, rather than receiving a large fixed response structure. Which API technology fits best?", "c": ["SOAP", "GraphQL", "RPC", "A flat REST endpoint returning full objects only"], "a": 1, "e": "GraphQL lets clients specify exactly which fields they need, reducing over-fetching or under-fetching of data compared to a fixed REST response structure."}, {"obj": "2.5", "q": "Which of the following terms fits this definition: \"The bandwidth, latency, and connectivity needs of a workload.\"?", "c": ["Availability Requirements", "Storage Requirements", "Network Requirements", "Compute Requirements"], "a": 2, "e": "\"The bandwidth, latency, and connectivity needs of a workload.\" describes Network Requirements. Shapes decisions about region placement, dedicated connections, and load balancer configuration."}, {"obj": "1.3", "q": "Which term is most closely associated with this real-world importance: \"Simplifies large-scale network architectures compared to a full mesh of individual peering connections.\"?", "c": ["Transit Gateway", "SDN", "Dedicated Connection", "Network Load Balancer"], "a": 0, "e": "Simplifies large-scale network architectures compared to a full mesh of individual peering connections. This describes Transit Gateway (\"A hub service that connects many VPCs and on-premises networks through a single point.\")."}, {"obj": "6.1", "q": "Which of the following best describes \"API Throttling\"?", "c": ["A failure caused by mismatched software, hardware, or configuration versions.", "A provider intentionally limiting the rate of API calls a customer can make.", "Incorrectly assigned CPU, memory, or storage limits for a workload.", "A deployment failing because the deploying identity lacks sufficient rights."], "a": 1, "e": "A provider intentionally limiting the rate of API calls a customer can make. Can cause deployment or application failures if automation exceeds the allowed request rate."}, {"obj": "2.2", "q": "Which of the following terms fits this definition: \"Gradually rolling out a change to a small subset of users or servers before a full rollout.\"?", "c": ["Canary Deployment", "In-Place Deployment", "Rolling Deployment", "Blue-Green Deployment"], "a": 0, "e": "\"Gradually rolling out a change to a small subset of users or servers before a full rollout.\" describes Canary Deployment. Limits the blast radius of a bad deployment by exposing it to only a fraction of traffic first."}, {"obj": "3.1", "q": "An administrator explains the importance of a concept: \"Turns detection into resolution — an alert with no response plan provides little value.\" What concept is this?", "c": ["Log Retention", "Log Collection", "Monitoring Metrics", "Alert Response"], "a": 3, "e": "Turns detection into resolution — an alert with no response plan provides little value. This describes Alert Response (\"The defined actions taken once an alert is triaged and confirmed to need action.\")."}, {"obj": "4.6", "q": "Select the most accurate description of \"DDoS\":", "c": ["Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources.", "A departure from a system's established normal behavior pattern.", "A cloud instance that is running but forgotten, unmonitored, or unmanaged.", "Malware that encrypts a victim's data and demands payment for the decryption key."], "a": 0, "e": "Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources. Aims to exhaust resources or bandwidth so legitimate users cannot access the service."}, {"obj": "6.2", "q": "Which statement accurately describes \"VLAN Misconfigured Tags\"?", "c": ["Network Time Protocol — synchronizes system clocks across a network.", "Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500).", "Two networks using conflicting/duplicate IP address ranges.", "Incorrect VLAN tagging causing traffic to be dropped or delivered to the wrong segment."], "a": 3, "e": "Incorrect VLAN tagging causing traffic to be dropped or delivered to the wrong segment. A classic Layer 2 troubleshooting issue, especially after switch or trunk reconfiguration."}, {"obj": "6.1", "q": "An administrator explains the importance of a concept: \"Leads to deployment failures when the referenced component is no longer valid on the platform.\" What concept is this?", "c": ["API Throttling", "Sizing Issues", "Full Outage", "Outdated Component Definitions"], "a": 3, "e": "Leads to deployment failures when the referenced component is no longer valid on the platform. This describes Outdated Component Definitions (\"IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated.\")."}, {"obj": "4.3", "q": "Which of the following best describes \"Web Portal\"?", "c": ["Multifactor Authentication — requiring two or more independent verification factors to log in.", "Allowing users to authenticate using credentials from a separate, trusted identity provider.", "Secure Shell — an encrypted protocol for remote command-line access to cloud resources.", "A graphical, browser-based interface for managing cloud resources."], "a": 3, "e": "A graphical, browser-based interface for managing cloud resources. The most accessible management interface for humans, though less suited to automation."}, {"obj": "2.4", "q": "A team manages application configuration files (like environment variables and feature flags) through version-controlled code rather than manual edits on each server. What practice is this?", "c": ["Infrastructure as Code", "Configuration as Code", "Drift detection", "IaC testing"], "a": 1, "e": "Configuration as Code manages system/application configuration through code, ensuring consistency across environments, distinct from infrastructure provisioning itself."}, {"obj": "1.8", "q": "A colleague says: \"Provides the raw usage data that billing and rightsizing decisions are based on.\" Which concept are they describing?", "c": ["Spot Instance", "Dedicated Host Billing", "Resource Metering", "Tagging"], "a": 2, "e": "Provides the raw usage data that billing and rightsizing decisions are based on. This describes Resource Metering (\"Tracking actual consumption of cloud resources for billing and capacity planning purposes.\")."}, {"obj": "5.2", "q": "A description reads: \"A packaged container image produced and stored as a build output.\" Which term does this describe?", "c": ["Public Repository", "CI/CD Workflow", "VM Image Artifact", "Container Image Artifact"], "a": 3, "e": "\"A packaged container image produced and stored as a build output.\" describes Container Image Artifact. Provides a versioned, portable, reusable deployment unit for containerized workloads."}, {"obj": "6.2", "q": "Which concept is described by the phrase: \"Network Address Translation — translates private addresses to a public address for routing.\"?", "c": ["DNS (Troubleshooting)", "NAT (Troubleshooting)", "Protocol Deprecation", "Network Overlap"], "a": 1, "e": "\"Network Address Translation — translates private addresses to a public address for routing.\" describes NAT (Troubleshooting). Misconfigured NAT/port forwarding is a common cause of unreachable services behind a private network."}, {"obj": "4.4", "q": "A company promptly applies vendor-released updates that fix known vulnerabilities across its fleet of cloud instances. What practice is this?", "c": ["Hardening only", "Patching", "Secrets management", "API security"], "a": 1, "e": "Patching applies vendor-released updates that fix known vulnerabilities, closing security gaps that attackers commonly target."}, {"obj": "4.4", "q": "Which of the following terms fits this definition: \"A security model that assumes no user or device should be trusted by default, even inside the network perimeter.\"?", "c": ["Data at Rest Encryption", "Principle of Least Privilege", "Secrets Management", "Zero Trust"], "a": 3, "e": "\"A security model that assumes no user or device should be trusted by default, even inside the network perimeter.\" describes Zero Trust. Requires continuous verification of identity and context for every access request, not just at the network edge."}, {"obj": "1.11", "q": "Why does this matter on the exam and in practice? \"Choice of communication method affects range, power consumption, and bandwidth available to the device.\" — which term does this explain?", "c": ["IoT Communication", "Text Translation", "IoT Gateway", "Sentiment Analysis"], "a": 0, "e": "Choice of communication method affects range, power consumption, and bandwidth available to the device. This describes IoT Communication (\"The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data.\")."}, {"obj": "3.2", "q": "A description reads: \"Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%).\" Which term does this describe?", "c": ["Triggered Scaling — Load", "Triggered Scaling — Event", "Manual Scaling", "Horizontal Scaling"], "a": 0, "e": "\"Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%).\" describes Triggered Scaling — Load. The most common autoscaling trigger, reacting quickly to current demand."}, {"obj": "3.3", "q": "A colleague says: \"Especially important since backups often contain complete copies of sensitive production data.\" Which concept are they describing?", "c": ["Backup Retention (Ops)", "Backup Encryption", "Differential Backup", "Backup Integrity Testing"], "a": 1, "e": "Especially important since backups often contain complete copies of sensitive production data. This describes Backup Encryption (\"Encrypting backup data so it remains protected even if the storage media or files are exposed.\")."}, {"obj": "4.4", "q": "A container is configured to run with elevated access to the underlying host's resources, significantly increasing risk if the container is compromised. What is this container called?", "c": ["An unprivileged container", "A privileged container", "An ephemeral container", "A stand-alone container"], "a": 1, "e": "A privileged container has elevated access to host resources, meaning a compromise of the container could affect the underlying host, unlike an unprivileged container."}, {"obj": "6.1", "q": "Which of the following terms fits this definition: \"IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated.\"?", "c": ["Regional Service Availability", "Permission Issues (Deployment)", "Outdated Component Definitions", "Deprecation of Functionality"], "a": 2, "e": "\"IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated.\" describes Outdated Component Definitions. Leads to deployment failures when the referenced component is no longer valid on the platform."}, {"obj": "3.1", "q": "A description reads: \"The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.\" Which term does this describe?", "c": ["Alert Triage", "Monitoring Metrics", "Log Collection", "Log Retention"], "a": 0, "e": "\"The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.\" describes Alert Triage. Prevents alert fatigue and ensures the most critical issues are addressed first."}, {"obj": "6.1", "q": "A deployment fails only in one specific region while succeeding elsewhere, because a required managed service isn't offered there. What is the cause?", "c": ["Regional service availability", "API throttling", "Sizing issues", "Resource allocation misconfiguration"], "a": 0, "e": "Not all cloud services are available in every region; a deployment can fail simply because the target region doesn't offer it."}, {"obj": "6.3", "q": "Legacy clients suddenly fail to establish a TLS connection to a cloud service after the provider disabled older, insecure cipher suites. What is the cause?", "c": ["Cipher suite deprecation", "Leaked credentials", "Privilege escalation", "Unauthorized software"], "a": 0, "e": "When a provider disables outdated cipher suites for security, legacy clients relying on them will fail to connect until updated."}, {"obj": "1.6", "q": "Why does this matter on the exam and in practice? \"Needed for stateful container workloads like databases, since container filesystems are normally ephemeral.\" — which term does this explain?", "c": ["Persistent Volume", "Ephemeral Storage", "Stand-Alone Container", "Image Registry"], "a": 0, "e": "Needed for stateful container workloads like databases, since container filesystems are normally ephemeral. This describes Persistent Volume (\"Storage that survives beyond the lifecycle of an individual container.\")."}, {"obj": "2.4", "q": "Which of the following terms fits this definition: \"Identifying when a deployed resource's actual state no longer matches its defined IaC configuration.\"?", "c": ["JSON", "IaC Versioning", "Configuration as Code", "Drift Detection"], "a": 3, "e": "\"Identifying when a deployed resource's actual state no longer matches its defined IaC configuration.\" describes Drift Detection. Helps catch unauthorized or manual changes that could cause inconsistency or security gaps."}, {"obj": "1.2", "q": "Which statement accurately describes \"Cloud Bursting\"?", "c": ["Recovery Point Objective — the maximum acceptable amount of data loss, measured in time.", "A basic facility with power and space but no pre-installed equipment.", "Temporarily extending an on-premises workload into the public cloud to handle demand spikes.", "Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption."], "a": 2, "e": "Temporarily extending an on-premises workload into the public cloud to handle demand spikes. Lets an organization keep steady-state workloads on cheaper private infrastructure while still handling peak load."}, {"obj": "3.2", "q": "How would you most accurately define \"Vertical Scaling\"?", "c": ["Increasing the resources (CPU/RAM) of an existing instance (scale up).", "Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU).", "Scaling resources up or down at predefined times based on known usage patterns.", "Adding more instances of a resource to handle increased load (scale out)."], "a": 0, "e": "Increasing the resources (CPU/RAM) of an existing instance (scale up). Simpler than horizontal scaling but has an upper limit and usually requires downtime or a reboot."}, {"obj": "1.3", "q": "\"VLAN\" is best defined as which of the following?", "c": ["Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains.", "Content Delivery Network — a geographically distributed set of servers that cache content closer to end users.", "A logical subdivision of a network's IP address range.", "A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute)."], "a": 0, "e": "Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains. Separates traffic types on shared physical/virtual network infrastructure."}, {"obj": "1.4", "q": "Why does this matter on the exam and in practice? \"Ideal for long-term retention data that must be kept for compliance but is almost never read.\" — which term does this explain?", "c": ["Archive Storage Tier", "Block Storage", "Hot Storage Tier", "HDD"], "a": 0, "e": "Ideal for long-term retention data that must be kept for compliance but is almost never read. This describes Archive Storage Tier (\"The lowest-cost storage tier, designed for rarely accessed data with the slowest retrieval times (sometimes hours).\")."}, {"obj": "2.1", "q": "Which deployment model would be least appropriate for a small startup with no existing infrastructure and a need to launch quickly with minimal capital expenditure?", "c": ["Public cloud", "On premises", "A managed public cloud service", "Pay-as-you-go public cloud resources"], "a": 1, "e": "On-premises deployment requires significant capital expenditure and lead time for infrastructure, making it the least appropriate choice for a startup needing to launch quickly and cheaply."}, {"obj": "4.6", "q": "Which concept is described by the phrase: \"Network ports left open on a system that are not required for its function.\"?", "c": ["Unnecessary Open Ports", "Ransomware", "Malware", "Cryptojacking"], "a": 0, "e": "\"Network ports left open on a system that are not required for its function.\" describes Unnecessary Open Ports. A common finding during security assessments and an easy target for attackers to exploit."}, {"obj": "4.4", "q": "An organization wants a vendor-neutral, consensus-based hardening baseline to apply across its cloud instances. What should it reference?", "c": ["A CIS Benchmark", "A CVE database", "An SLA", "A CWE list"], "a": 0, "e": "CIS Benchmarks provide vendor-neutral, consensus-based configuration hardening guidelines widely used across the industry."}, {"obj": "6.1", "q": "A deployment fails because the automated pipeline's service account lacks permission to create a new storage bucket. What category of issue is this?", "c": ["Sizing issues", "Permission issues (deployment)", "Oversubscription", "Deprecation of functionality"], "a": 1, "e": "A deployment failing due to the deploying identity lacking sufficient rights is a permission issue, one of the most common causes of failed automated deployments."}, {"obj": "1.6", "q": "Which of the following terms fits this definition: \"A repository for storing and distributing container images (e.g., Docker Hub, a private registry).\"?", "c": ["Workload Orchestration", "Image Registry", "Persistent Volume", "Ephemeral Storage"], "a": 1, "e": "\"A repository for storing and distributing container images (e.g., Docker Hub, a private registry).\" describes Image Registry. Provides a central, versioned source for pulling container images during deployment."}, {"obj": "3.4", "q": "Which of the following best describes \"Major Update\"?", "c": ["Retiring a resource because it has reached the end of its useful life or support.", "A smaller update, typically with bug fixes and small improvements.", "Validating changes (patches, updates, configuration) before applying them broadly.", "A significant version update that may include new features and breaking changes."], "a": 3, "e": "A significant version update that may include new features and breaking changes. Requires more careful testing than minor updates due to a higher risk of compatibility issues."}, {"obj": "4.3", "q": "Which concept is described by the phrase: \"Allowing users to authenticate using credentials from a separate, trusted identity provider.\"?", "c": ["CLI", "Local User Authentication", "SAML", "Federation"], "a": 3, "e": "\"Allowing users to authenticate using credentials from a separate, trusted identity provider.\" describes Federation. Lets organizations use existing corporate identities to access cloud resources without duplicate accounts."}, {"obj": "5.3", "q": "How would you most accurately define \"Event-Driven Architecture\"?", "c": ["Representational State Transfer — an architectural style for web services using standard HTTP methods.", "A design where components communicate by producing and reacting to events rather than direct calls.", "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local.", "Simple Object Access Protocol — an XML-based messaging protocol for web services."], "a": 1, "e": "A design where components communicate by producing and reacting to events rather than direct calls. Enables loose coupling and scalability, common in cloud-native and microservices designs."}, {"obj": "2.3", "q": "Which of the following best describes \"Refactor\"?", "c": ["Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.", "Moving workloads out of the cloud back to local infrastructure.", "A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture.", "A migration strategy that rewrites portions of an application to better fit cloud-native patterns."], "a": 3, "e": "A migration strategy that rewrites portions of an application to better fit cloud-native patterns. Similar to re-architecting but often more incremental, improving specific components over time."}, {"obj": "1.10", "q": "Which statement accurately describes \"IOPS (Optimization)\"?", "c": ["Input/Output Operations Per Second — a measure of storage performance.", "Automated coordination of workload deployment, scaling, and lifecycle management.", "A defined sequence of automated steps/tasks that process data or coordinate resources.", "Using provider-operated services instead of self-managed infrastructure to reduce operational overhead."], "a": 0, "e": "Input/Output Operations Per Second — a measure of storage performance. A key metric for sizing storage for database or transaction-heavy workloads."}, {"obj": "4.4", "q": "How would you most accurately define \"Vendor-Specific Benchmark\"?", "c": ["A security model that assumes no user or device should be trusted by default, even inside the network perimeter.", "Applying vendor-released updates that fix known vulnerabilities.", "A container granted elevated access to the host system's resources.", "Hardening guidance published by a specific cloud provider or software vendor for their own product."], "a": 3, "e": "Hardening guidance published by a specific cloud provider or software vendor for their own product. Complements general benchmarks with platform-specific configuration recommendations."}, {"obj": "6.2", "q": "Which term is most closely associated with this real-world importance: \"Commonly causes routing failures when connecting previously separate networks (e.g., via VPN or peering).\"?", "c": ["Network Overlap", "Missing Route", "NAT (Troubleshooting)", "HTTP Status Codes"], "a": 0, "e": "Commonly causes routing failures when connecting previously separate networks (e.g., via VPN or peering). This describes Network Overlap (\"Two networks using conflicting/duplicate IP address ranges.\")."}, {"obj": "4.5", "q": "A colleague says: \"The primary mechanism for instance-level network access control in most cloud platforms.\" Which concept are they describing?", "c": ["DLP", "DDoS Protection", "Network Security Group", "Endpoint Protection"], "a": 2, "e": "The primary mechanism for instance-level network access control in most cloud platforms. This describes Network Security Group (\"A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs.\")."}, {"obj": "2.2", "q": "A small internal tool with only one server is updated by directly patching that same running instance rather than provisioning a separate one. Which strategy is being used?", "c": ["Blue-green deployment", "Canary deployment", "In-place deployment", "Rolling deployment"], "a": 2, "e": "In-place deployment updates the existing server directly, which is simpler but riskier than blue-green since there's no separate environment to instantly roll back to."}, {"obj": "5.3", "q": "Which concept is described by the phrase: \"A protocol providing full-duplex, persistent communication channels over a single TCP connection.\"?", "c": ["SOAP", "GraphQL", "Web Sockets", "REST"], "a": 2, "e": "\"A protocol providing full-duplex, persistent communication channels over a single TCP connection.\" describes Web Sockets. Enables real-time, bidirectional communication like chat apps or live dashboards, unlike typical request/response HTTP."}, {"obj": "4.4", "q": "A company requires all traffic between its web application and end users to use HTTPS, ensuring data cannot be eavesdropped on while crossing the internet. What practice is this?", "c": ["Data at rest encryption", "Data in transit encryption", "Secrets management", "Zero Trust enforcement"], "a": 1, "e": "Requiring HTTPS/TLS for all traffic protects data as it moves across the network, which is the definition of data in transit encryption."}, {"obj": "2.3", "q": "Which of the following best describes \"Retire\"?", "c": ["A migration strategy that decommissions an application no longer needed.", "Moving workloads from local infrastructure into a cloud environment.", "A migration strategy that rewrites portions of an application to better fit cloud-native patterns.", "A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture."], "a": 0, "e": "A migration strategy that decommissions an application no longer needed. Reduces the overall migration scope and ongoing costs by eliminating unnecessary systems."}, {"obj": "4.6", "q": "Which of the following terms fits this definition: \"An attack that succeeds because a system was running software with a known, unpatched vulnerability.\"?", "c": ["Metadata Attack", "Vulnerability Exploitation — Outdated Software", "Cryptojacking", "Ransomware"], "a": 1, "e": "\"An attack that succeeds because a system was running software with a known, unpatched vulnerability.\" describes Vulnerability Exploitation — Outdated Software. Reinforces why timely patch management is one of the most effective security controls."}, {"obj": "2.5", "q": "A company provisioning a new customer-facing application decides to deploy it across three availability zones with automated health checks and failover. What set of requirements most directly drove this decision?", "c": ["Compliance requirements only", "Availability requirements", "Compute requirements only", "Storage requirements only"], "a": 1, "e": "Multi-AZ deployment with automated failover is a direct response to availability requirements defining the acceptable uptime and resiliency for the application."}, {"obj": "5.4", "q": "A team stores all their source code in Git and uses GitHub Actions to automatically build and test every pull request before it can be merged. What DevOps principle does this combination support?", "c": ["Manual, ad hoc deployment with no automation", "Continuous integration through automated build/test triggered by source control events", "Avoiding version control entirely", "Disabling all automated testing"], "a": 1, "e": "Combining Git (version control) with GitHub Actions (CI/CD automation) directly supports continuous integration, automatically validating every change before merge."}, {"obj": "1.9", "q": "Which scenario best illustrates a reason to choose a non-relational database over a relational one?", "c": ["The data has a fixed, rarely changing schema with strict relationships", "The application needs to store rapidly evolving, semi-structured data at massive scale with flexible schema", "The application requires complex multi-table SQL joins", "The application needs strict ACID transactional guarantees for banking transfers"], "a": 1, "e": "Non-relational databases are best suited to rapidly evolving, semi-structured data at scale, where schema flexibility matters more than complex relational joins."}, {"obj": "6.2", "q": "What does the abbreviation \"NTP\" stand for?", "c": ["Virtual CPU", "General Data Protection Regulation", "Storage Area Network", "Network Time Protocol"], "a": 3, "e": "NTP stands for Network Time Protocol. Synchronizes system clocks across a network, critical for authentication and logging."}, {"obj": "2.4", "q": "A description reads: \"JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates.\" Which term does this describe?", "c": ["IaC Testing", "JSON", "Infrastructure as Code", "Drift Detection"], "a": 1, "e": "\"JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates.\" describes JSON. One of the two dominant data formats used to define cloud resources declaratively."}, {"obj": "4.4", "q": "A security team assumes no device or user should be automatically trusted, even inside the corporate network, and requires continuous verification for every access request. What model is this?", "c": ["Defense in depth only", "Zero Trust", "Discretionary access control", "Least functionality"], "a": 1, "e": "Zero Trust assumes no implicit trust and requires continuous verification of identity and context for every access request."}, {"obj": "5.4", "q": "An administrator explains the importance of a concept: \"The de facto standard version control system underlying most modern DevOps workflows.\" What concept is this?", "c": ["Jenkins", "Terraform", "GitHub Actions", "Git"], "a": 3, "e": "The de facto standard version control system underlying most modern DevOps workflows. This describes Git (\"A distributed version control system used to track changes in source code.\")."}, {"obj": "6.3", "q": "How would you most accurately define \"Leaked Credentials\"?", "c": ["Authentication credentials that have been exposed, such as in code repositories or logs.", "Software installed or running without proper approval, increasing risk and potentially breaching policy.", "Access to a system or data by someone without proper permission.", "A connectivity/security failure caused by relying on an outdated, no-longer-supported encryption cipher suite."], "a": 0, "e": "Authentication credentials that have been exposed, such as in code repositories or logs. A very common real-world cause of cloud breaches, often via credentials accidentally committed to source control."}, {"obj": "1.2", "q": "A small nonprofit wants basic disaster recovery but has a very limited budget and can tolerate being down for a few days after a disaster while equipment is procured and configured. Which DR site type is most appropriate?", "c": ["Hot site", "Warm site", "Cold site", "Multi-region active-active"], "a": 2, "e": "A cold site offers only basic space and power with no pre-installed equipment, the cheapest option but with the longest time to become operational."}, {"obj": "6.2", "q": "Which term best matches this description: \"Network Time Protocol — synchronizes system clocks across a network.\"?", "c": ["DHCP (Troubleshooting)", "Misconfigured Route", "VLAN Misconfigured Tags", "NTP (Troubleshooting)"], "a": 3, "e": "\"Network Time Protocol — synchronizes system clocks across a network.\" describes NTP (Troubleshooting). Clock drift can break authentication (like Kerberos) and certificate validation in subtle, confusing ways."}, {"obj": "4.6", "q": "An employee clicks a link in an email appearing to be from IT support and enters their credentials on a fake login page. What attack type is this?", "c": ["DDoS", "Phishing", "Cryptojacking", "A metadata attack"], "a": 1, "e": "Phishing is a social engineering attack that tricks a user into revealing credentials, one of the most common initial access vectors in real breaches."}, {"obj": "5.2", "q": "An administrator explains the importance of a concept: \"Provides a versioned, portable, reusable deployment unit for containerized workloads.\" What concept is this?", "c": ["VM Image Artifact", "Container Image Artifact", "Flat File Artifact", "Public Repository"], "a": 1, "e": "Provides a versioned, portable, reusable deployment unit for containerized workloads. This describes Container Image Artifact (\"A packaged container image produced and stored as a build output.\")."}, {"obj": "4.6", "q": "Why does this matter on the exam and in practice? \"A broad category of threats requiring layered defenses like endpoint protection and patching.\" — which term does this explain?", "c": ["Malware", "Vulnerability Exploitation — Human Error", "Vulnerability Exploitation — Outdated Software", "DDoS"], "a": 0, "e": "A broad category of threats requiring layered defenses like endpoint protection and patching. This describes Malware (\"Malicious software designed to damage, disrupt, or gain unauthorized access to a system.\")."}, {"obj": "5.4", "q": "Which term best matches this description: \"Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization.\"?", "c": ["Jenkins", "Ansible", "ELK Stack", "GitHub Actions"], "a": 2, "e": "\"Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization.\" describes ELK Stack. A widely used open-source stack for centralized logging and observability."}, {"obj": "4.4", "q": "Given the description \"Securely storing and controlling access to credentials, API keys, and other sensitive configuration values.\", which term is being defined?", "c": ["File Storage Security", "Vendor-Specific Benchmark", "Secrets Management", "Privileged Container"], "a": 2, "e": "\"Securely storing and controlling access to credentials, API keys, and other sensitive configuration values.\" describes Secrets Management. Prevents secrets from being hardcoded in source code or exposed in plaintext configuration files."}, {"obj": "2.3", "q": "A company determines that a particular legacy application is too costly to migrate right now and decides to leave it running on-premises for the time being. What migration strategy is this?", "c": ["Retire", "Retain", "Rehost", "Re-architect"], "a": 1, "e": "Retain keeps a workload where it currently is, deferring migration when it isn't yet ready or cost-justified."}, {"obj": "5.1", "q": "A team maintains separate lines of development for a new feature, a bug fix, and the stable release, allowing parallel work without disrupting the main codebase. What practice is this?", "c": ["Code review", "Branch management", "Code push", "Pull request approval"], "a": 1, "e": "Branch management organizes and maintains separate lines of development, enabling parallel work on features or fixes without disrupting the main codebase."}, {"obj": "3.3", "q": "A colleague says: \"Appropriate when an entire system or dataset needs to be recovered together.\" Which concept are they describing?", "c": ["Parallel Recovery", "Bulk Recovery", "Backup Replication", "Backup Encryption"], "a": 1, "e": "Appropriate when an entire system or dataset needs to be recovered together. This describes Bulk Recovery (\"Restoring a large set of data all at once.\")."}, {"obj": "4.3", "q": "In Cloud+ terminology, \"OIDC\" is an abbreviation for which of the following?", "c": ["Simple Object Access Protocol", "Artificial Intelligence", "OpenID Connect Protocol", "Responsible, Accountable, Consulted, Informed"], "a": 2, "e": "OIDC stands for OpenID Connect Protocol. An identity layer built on OAuth 2.0 used for authentication."}, {"obj": "5.2", "q": "Which term is most closely associated with this real-world importance: \"Convenient for open-source projects but not suitable for proprietary or sensitive code.\"?", "c": ["Container Image Artifact", "Public Repository", "Private Repository", "CI/CD Security"], "a": 1, "e": "Convenient for open-source projects but not suitable for proprietary or sensitive code. This describes Public Repository (\"A code or artifact repository accessible to anyone.\")."}, {"obj": "1.1", "q": "In Cloud+ terminology, \"RAM\" is an abbreviation for which of the following?", "c": ["Common Weakness Scoring System", "Network Interface Card", "Transport Layer Security", "Random Access Memory"], "a": 3, "e": "RAM stands for Random Access Memory. Volatile memory used to store data actively in use by running processes."}, {"obj": "1.4", "q": "Select the most accurate description of \"Warm Storage Tier\":", "c": ["A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost.", "A storage tier for data accessed less frequently than hot data, balancing cost and access speed.", "Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB).", "The lowest-cost storage tier, designed for rarely accessed data with the slowest retrieval times (sometimes hours)."], "a": 1, "e": "A storage tier for data accessed less frequently than hot data, balancing cost and access speed. A middle ground for data that's not actively hot but still needed with reasonable speed."}, {"obj": "4.1", "q": "An automated scanner detects that several cloud instances are running outdated software with known weaknesses. What step of the vulnerability management lifecycle has just occurred?", "c": ["Remediation", "Vulnerability identification", "Scanning scope definition", "CVE publication"], "a": 1, "e": "Detecting known weaknesses via automated scanning is the vulnerability identification step, which then feeds into assessment and remediation."}, {"obj": "1.5", "q": "Which of the following is a risk specifically introduced by adopting a microservices architecture, compared to a monolith?", "c": ["Inability to scale any component independently", "Increased operational complexity from managing many independently deployed services", "Elimination of the need for networking", "Guaranteed elimination of all downtime"], "a": 1, "e": "While microservices offer independent scaling and deployment, they introduce additional operational complexity from managing many distributed components."}, {"obj": "1.7", "q": "Which of the following terms fits this definition: \"Creating an exact copy of an existing VM.\"?", "c": ["Cloning", "Clustering", "Overlay Network", "Local Storage (Virtualization)"], "a": 0, "e": "\"Creating an exact copy of an existing VM.\" describes Cloning. Speeds up deployment of identical VMs without building each one from scratch."}, {"obj": "4.5", "q": "Which of the following terms fits this definition: \"Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic.\"?", "c": ["DLP", "Network ACL", "IAM Policies", "DDoS Protection"], "a": 3, "e": "\"Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic.\" describes DDoS Protection. Essential for internet-facing cloud services that could otherwise be overwhelmed by attack traffic."}, {"obj": "2.4", "q": "A team wants every infrastructure change to be reviewed, version-controlled, and repeatable rather than made manually through a cloud console. What practice should they adopt?", "c": ["Manual console-based provisioning", "Infrastructure as Code", "Ad hoc scripting with no version control", "Verbal change requests only"], "a": 1, "e": "IaC manages infrastructure through machine-readable, version-controlled definition files, making changes repeatable, reviewable, and auditable."}, {"obj": "3.2", "q": "Given the description \"Increasing the resources (CPU/RAM) of an existing instance (scale up).\", which term is being defined?", "c": ["Triggered Scaling — Load", "Triggered Scaling — Event", "Vertical Scaling", "Scheduled Scaling"], "a": 2, "e": "\"Increasing the resources (CPU/RAM) of an existing instance (scale up).\" describes Vertical Scaling. Simpler than horizontal scaling but has an upper limit and usually requires downtime or a reboot."}, {"obj": "1.10", "q": "Which statement accurately describes \"Compute Optimization (Container)\"?", "c": ["Using virtual machines as the compute resource type for a workload.", "Using containers as the compute resource type for a workload.", "Input/Output Operations Per Second — a measure of storage performance.", "Automated coordination of workload deployment, scaling, and lifecycle management."], "a": 1, "e": "Using containers as the compute resource type for a workload. More lightweight and portable than VMs, ideal for microservices and rapid scaling."}, {"obj": "6.1", "q": "An IaC template references a specific VM instance type that the provider has since retired and no longer offers. What is the most likely cause of the resulting deployment failure?", "c": ["Outdated component definitions in the IaC template", "Oversubscription", "Permission issues", "A full outage"], "a": 0, "e": "Outdated component definitions reference resource types or sizes no longer valid on the platform, causing deployment failures until the template is updated."}, {"obj": "2.4", "q": "Which of the following is a primary benefit of using IaC over manual infrastructure provisioning?", "c": ["It eliminates the need for any testing", "Changes become repeatable, version-controlled, and auditable rather than ad hoc and undocumented", "It guarantees zero cost for cloud resources", "It removes the need for any security review"], "a": 1, "e": "IaC's core benefit is making infrastructure changes repeatable, version-controlled, and auditable, unlike ad hoc manual changes."}, {"obj": "4.2", "q": "Which of the following best distinguishes data sovereignty from data locality?", "c": ["They are identical concepts with no meaningful difference", "Data sovereignty is a legal requirement tied to a country's laws; data locality can be a business preference about physical location that isn't necessarily legally mandated", "Data locality always overrides data sovereignty", "Data sovereignty only applies to financial data"], "a": 1, "e": "Data sovereignty specifically concerns legal jurisdiction based on physical data location, while data locality can reflect a business preference that may or may not be legally required."}, {"obj": "2.4", "q": "Which term best matches this description: \"Managing system or application configuration through code rather than manual configuration.\"?", "c": ["Configuration as Code", "JSON", "Drift Detection", "IaC Testing"], "a": 0, "e": "\"Managing system or application configuration through code rather than manual configuration.\" describes Configuration as Code. Ensures configuration consistency across environments and enables automated drift correction."}, {"obj": "4.4", "q": "An administrator explains the importance of a concept: \"Ensures only authorized users/systems can read or modify shared file data.\" What concept is this?", "c": ["Principle of Least Privilege", "Container File Access Permissions", "File Storage Security", "Unprivileged Container"], "a": 2, "e": "Ensures only authorized users/systems can read or modify shared file data. This describes File Storage Security (\"Access controls and encryption applied to shared file storage systems.\")."}, {"obj": "4.3", "q": "Select the most accurate description of \"Group-Based Access Control\":", "c": ["Application Programming Interface — used here for programmatic management/access to cloud resources.", "Granting permissions to a group, which members inherit by being added to that group.", "An authorization framework that lets an application access resources on a user's behalf without sharing their password.", "Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties."], "a": 1, "e": "Granting permissions to a group, which members inherit by being added to that group. Similar to RBAC but organized around groups rather than formally defined roles."}, {"obj": "4.6", "q": "A description reads: \"Malware that encrypts a victim's data and demands payment for the decryption key.\" Which term does this describe?", "c": ["Deviation from Baseline", "Malware", "Ransomware", "Cryptojacking"], "a": 2, "e": "\"Malware that encrypts a victim's data and demands payment for the decryption key.\" describes Ransomware. Makes immutable, offline backups especially critical, since online backups can also be encrypted."}, {"obj": "2.2", "q": "A team wants to avoid taking the entire application offline during an update but does not want to double their infrastructure cost by running two full parallel environments. Which strategy balances these constraints best?", "c": ["Blue-green deployment", "Rolling deployment", "In-place deployment on all servers simultaneously", "A full outage deployment window"], "a": 1, "e": "Rolling deployment updates instances incrementally without requiring a full duplicate environment, keeping the application available while avoiding blue-green's doubled infrastructure cost."}, {"obj": "4.4", "q": "Why does this matter on the exam and in practice? \"Misconfigured permissions inside a container can let an attacker access or modify data they shouldn't.\" — which term does this explain?", "c": ["Secrets Management", "Object Storage Security", "Vendor-Specific Benchmark", "Container File Access Permissions"], "a": 3, "e": "Misconfigured permissions inside a container can let an attacker access or modify data they shouldn't. This describes Container File Access Permissions (\"Controls governing which files and directories a container process can read or write.\")."}, {"obj": "3.2", "q": "In cloud computing terminology, \"Triggered Scaling — Event\" refers to which of the following?", "c": ["Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%).", "Adding more instances of a resource to handle increased load (scale out).", "Scaling in response to a specific event (like a message queue depth increasing).", "Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU)."], "a": 2, "e": "Scaling in response to a specific event (like a message queue depth increasing). Useful for event-driven architectures where load isn't purely CPU/memory based."}, {"obj": "3.4", "q": "Why does this matter on the exam and in practice? \"Running unsupported resources leaves known vulnerabilities permanently unpatched.\" — which term does this explain?", "c": ["Decommissioning — End of Support", "Minor Update", "Patch", "Lifecycle Testing"], "a": 0, "e": "Running unsupported resources leaves known vulnerabilities permanently unpatched. This describes Decommissioning — End of Support (\"Retiring or upgrading a resource because the vendor no longer provides support/patches for it.\")."}, {"obj": "4.3", "q": "Select the most accurate description of \"CLI\":", "c": ["An identity layer built on top of OAuth 2.0 used for authentication (proving who you are).", "Authenticating against a centralized directory service (like LDAP or Active Directory).", "Software Development Kit — a set of libraries/tools that let developers programmatically interact with a cloud platform.", "Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources."], "a": 3, "e": "Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources. Popular for scripting and automation tasks that would be tedious through a web portal."}, {"obj": "1.10", "q": "An administrator explains the importance of a concept: \"Eliminates server management entirely, billing only for actual execution time.\" What concept is this?", "c": ["Compute Optimization (VM)", "Storage Throughput", "Network Throughput", "Compute Optimization (Serverless)"], "a": 3, "e": "Eliminates server management entirely, billing only for actual execution time. This describes Compute Optimization (Serverless) (\"Using Function as a Service as the compute resource type for a workload.\")."}, {"obj": "4.3", "q": "Which concept is described by the phrase: \"Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.\"?", "c": ["OAuth 2.0", "SAML", "Token-Based Authentication", "Directory-Based Authentication"], "a": 1, "e": "\"Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.\" describes SAML. Commonly used to implement federated single sign-on into cloud platforms."}, {"obj": "3.1", "q": "Which statement accurately describes \"Alert Response\"?", "c": ["Combining logs from many sources into a unified, searchable view.", "Following a single request as it moves through multiple services in a distributed system.", "The defined actions taken once an alert is triaged and confirmed to need action.", "The process of reviewing and prioritizing incoming alerts to determine urgency and next steps."], "a": 2, "e": "The defined actions taken once an alert is triaged and confirmed to need action. Turns detection into resolution — an alert with no response plan provides little value."}, {"obj": "1.3", "q": "The acronym \"VPC\" stands for:", "c": ["Red Hat Package Manager", "Center for Internet Security", "Multifactor Authentication", "Virtual Private Cloud"], "a": 3, "e": "VPC stands for Virtual Private Cloud. An isolated, logically defined network within a public cloud provider's infrastructure."}, {"obj": "6.2", "q": "A description reads: \"Network Address Translation — translates private addresses to a public address for routing.\" Which term does this describe?", "c": ["Protocol Deprecation", "NAT (Troubleshooting)", "Protocol Incompatibility", "Network Overlap"], "a": 1, "e": "\"Network Address Translation — translates private addresses to a public address for routing.\" describes NAT (Troubleshooting). Misconfigured NAT/port forwarding is a common cause of unreachable services behind a private network."}, {"obj": "4.1", "q": "A company patches a critical vulnerability on its internet-facing servers but never re-scans to confirm the fix actually worked. What risk does this create?", "c": ["No risk, since applying a patch always guarantees success", "The vulnerability may still be present due to an incomplete or failed patch application, undetected without a follow-up scan", "Patches never need verification of any kind", "The original scan becomes invalid retroactively"], "a": 1, "e": "Without a follow-up scan to confirm remediation, a failed or incomplete patch application could leave the vulnerability present without anyone knowing."}, {"obj": "1.3", "q": "Which of the following terms fits this definition: \"Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.\"?", "c": ["CDN", "Dedicated Connection", "Transit Gateway", "BGP"], "a": 3, "e": "\"Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.\" describes BGP. Used for advanced routing scenarios like connecting on-premises networks to the cloud via dedicated connections."}, {"obj": "2.5", "q": "An administrator explains the importance of a concept: \"Must be assessed before provisioning to choose the right storage type and tier.\" What concept is this?", "c": ["Network Requirements", "Availability Requirements", "Compliance Requirements", "Storage Requirements"], "a": 3, "e": "Must be assessed before provisioning to choose the right storage type and tier. This describes Storage Requirements (\"The capacity, performance, and durability needs a workload has for its data.\")."}, {"obj": "1.10", "q": "Given the description \"Input/Output Operations Per Second — a measure of storage performance.\", which term is being defined?", "c": ["Compute Optimization (VM)", "IOPS (Optimization)", "Workflow (Optimization)", "Network Latency"], "a": 1, "e": "\"Input/Output Operations Per Second — a measure of storage performance.\" describes IOPS (Optimization). A key metric for sizing storage for database or transaction-heavy workloads."}, {"obj": "2.2", "q": "In cloud computing terminology, \"In-Place Deployment\" refers to which of the following?", "c": ["Gradually rolling out a change to a small subset of users or servers before a full rollout.", "A strategy running two identical environments (blue and green), switching traffic to the new version once verified.", "Updating an existing server or instance directly rather than deploying an entirely new one.", "Updating instances incrementally, a few at a time, rather than all at once."], "a": 2, "e": "Updating an existing server or instance directly rather than deploying an entirely new one. Simpler but riskier than blue-green since there is no separate environment to instantly roll back to."}, {"obj": "4.3", "q": "Which of the following best describes \"API (IAM Context)\"?", "c": ["Granting permissions based on a user's assigned role rather than to each individual directly.", "Secure Shell — an encrypted protocol for remote command-line access to cloud resources.", "Application Programming Interface — used here for programmatic management/access to cloud resources.", "An authorization framework that lets an application access resources on a user's behalf without sharing their password."], "a": 2, "e": "Application Programming Interface — used here for programmatic management/access to cloud resources. API access typically requires its own credentials (keys/tokens) separate from human user logins."}, {"obj": "4.4", "q": "In cloud computing terminology, \"Unprivileged Container\" refers to which of the following?", "c": ["Access controls and encryption settings applied to object storage buckets/containers.", "Encrypting stored data so it remains unreadable without the correct key.", "Reducing a system's attack surface by disabling unnecessary services, closing unused ports, and applying secure configurations.", "A container running with restricted access, isolated from the host's sensitive resources."], "a": 3, "e": "A container running with restricted access, isolated from the host's sensitive resources. The safer default for container security, limiting the impact of a container-level compromise."}, {"obj": "1.3", "q": "A newly created subnet has no entries directing traffic to a peered VPC's address range. What is the most likely outcome?", "c": ["Traffic will automatically find another path", "Traffic destined for that VPC will be dropped since no route exists", "The peering connection will automatically create the missing route", "Nothing; routes are not required for connectivity"], "a": 1, "e": "Without an explicit route table entry for the destination, traffic to that destination will be dropped even if a peering connection physically exists."}, {"obj": "1.11", "q": "In cloud computing terminology, \"Text Translation\" refers to which of the following?", "c": ["The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data.", "AI technology that automatically converts text from one language to another.", "AI technology that identifies objects, scenes, or features within images or video.", "AI technology that determines the emotional tone (positive/negative/neutral) of text."], "a": 1, "e": "AI technology that automatically converts text from one language to another. Enables applications to serve global users without manual translation."}, {"obj": "4.6", "q": "Which term best matches this description: \"A cloud instance that is running but forgotten, unmonitored, or unmanaged.\"?", "c": ["Malware", "Metadata Attack", "Deviation from Baseline", "Zombie Instance"], "a": 3, "e": "\"A cloud instance that is running but forgotten, unmonitored, or unmanaged.\" describes Zombie Instance. Represents both wasted cost and an unpatched, unmonitored attack surface."}, {"obj": "5.2", "q": "A team packages its application as a container image and stores it in a company-controlled repository not accessible to the public. What is this repository called?", "c": ["A public repository", "A private repository", "An RPM package", "A flat file artifact"], "a": 1, "e": "A private repository restricts access to authorized users/systems, the standard choice for proprietary artifacts."}, {"obj": "1.10", "q": "\"Compute Optimization (Container)\" is best defined as which of the following?", "c": ["Using containers as the compute resource type for a workload.", "A defined sequence of automated steps/tasks that process data or coordinate resources.", "Input/Output Operations Per Second — a measure of storage performance.", "The rate of data transfer to/from a storage system, usually measured in MB/s or GB/s."], "a": 0, "e": "Using containers as the compute resource type for a workload. More lightweight and portable than VMs, ideal for microservices and rapid scaling."}, {"obj": "5.2", "q": "An administrator explains the importance of a concept: \"Catches regressions before code reaches production, a core benefit of CI/CD.\" What concept is this?", "c": ["Flat File Artifact", "Public Repository", "RPM Package", "CI/CD Testing"], "a": 3, "e": "Catches regressions before code reaches production, a core benefit of CI/CD. This describes CI/CD Testing (\"Automatically running tests against code as part of the pipeline.\")."}, {"obj": "1.2", "q": "Which statement accurately describes \"RTO\"?", "c": ["Processing data physically close to where it is generated rather than in a centralized datacenter.", "Temporarily extending an on-premises workload into the public cloud to handle demand spikes.", "Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption.", "A fully equipped, continuously running DR site that can take over almost immediately."], "a": 2, "e": "Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption. Drives the choice of DR site type and how much automation/investment is needed to meet the target."}, {"obj": "2.3", "q": "Which of the following best describes \"On-Premises-to-Cloud Migration\"?", "c": ["A migration strategy that substantially redesigns an application to be cloud-native.", "Moving workloads out of the cloud back to local infrastructure.", "Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.", "Moving workloads from local infrastructure into a cloud environment."], "a": 3, "e": "Moving workloads from local infrastructure into a cloud environment. The most common migration type when organizations first adopt cloud computing."}, {"obj": "1.2", "q": "Which of the following is the correct expansion of \"DR\"?", "c": ["JavaScript Object Notation", "Disaster Recovery", "Internet Protocol", "Configuration as Code"], "a": 1, "e": "DR stands for Disaster Recovery. The process and plans for restoring IT operations after a disruptive event."}, {"obj": "1.11", "q": "Which statement accurately describes \"IoT Sensor\"?", "c": ["A device that collects data from the physical environment (temperature, motion, etc.).", "AI technology that automatically converts text from one language to another.", "AI technology that converts written text into spoken audio (speech synthesis).", "AI technology that converts spoken audio into written text (speech recognition)."], "a": 0, "e": "A device that collects data from the physical environment (temperature, motion, etc.). The data-collection endpoint in most IoT architectures, feeding data upstream for processing."}, {"obj": "1.2", "q": "A company wants to validate that its documented RTO of 4 hours is actually achievable in practice. What should it do?", "c": ["Assume the RTO is correct since it was written down", "Conduct a live or simulated failover test measuring actual recovery time", "Only review the RTO during an annual compliance audit with no testing", "Increase the RTO arbitrarily to make it easier to meet"], "a": 1, "e": "Only conducting an actual failover test (live or simulated) can validate that a stated RTO is achievable in real conditions, since assumptions on paper may not hold."}, {"obj": "6.3", "q": "Which of the following best describes \"Unauthorized Software\"?", "c": ["Access to a system or data by someone without proper permission.", "Problems arising from unpatched or improperly configured software containing known weaknesses.", "An identity gaining higher access than originally granted, often through a flaw or misconfiguration.", "Software installed or running without proper approval, increasing risk and potentially breaching policy."], "a": 3, "e": "Software installed or running without proper approval, increasing risk and potentially breaching policy. Can introduce vulnerabilities, malware, or licensing violations into an otherwise controlled environment."}, {"obj": "4.3", "q": "An administrator needs to securely access a Linux-based cloud instance's command line remotely to run diagnostic commands. Which protocol should be used?", "c": ["RDP", "SSH", "SAML", "OAuth 2.0"], "a": 1, "e": "SSH is the standard encrypted protocol for secure remote command-line access to Linux-based systems."}, {"obj": "1.8", "q": "A colleague says: \"Maximizes flexibility for unpredictable or short-term workloads, at a higher per-unit cost than reserved pricing.\" Which concept are they describing?", "c": ["Pay-As-You-Go", "Rightsizing", "Tagging", "Resource Metering"], "a": 0, "e": "Maximizes flexibility for unpredictable or short-term workloads, at a higher per-unit cost than reserved pricing. This describes Pay-As-You-Go (\"A billing model charging only for actual resource consumption, with no upfront commitment.\")."}, {"obj": "6.1", "q": "Which term is most closely associated with this real-world importance: \"Can cause deployment or application failures if automation exceeds the allowed request rate.\"?", "c": ["Permission Issues (Deployment)", "API Throttling", "Service Quota", "Sizing Issues"], "a": 1, "e": "Can cause deployment or application failures if automation exceeds the allowed request rate. This describes API Throttling (\"A provider intentionally limiting the rate of API calls a customer can make.\")."}, {"obj": "3.2", "q": "A web tier adds more identical server instances behind a load balancer to handle growing traffic. What scaling approach is this?", "c": ["Vertical scaling", "Horizontal scaling", "Manual scaling only", "Scheduled scaling only"], "a": 1, "e": "Horizontal scaling (scale out) adds more instances of a resource, improving both capacity and redundancy."}, {"obj": "2.2", "q": "Why does this matter on the exam and in practice? \"Keeps the application available throughout the deployment, at the cost of a longer overall rollout window.\" — which term does this explain?", "c": ["In-Place Deployment", "Rolling Deployment", "Canary Deployment", "Blue-Green Deployment"], "a": 1, "e": "Keeps the application available throughout the deployment, at the cost of a longer overall rollout window. This describes Rolling Deployment (\"Updating instances incrementally, a few at a time, rather than all at once.\")."}, {"obj": "4.6", "q": "Which of the following terms fits this definition: \"Malware that encrypts a victim's data and demands payment for the decryption key.\"?", "c": ["Ransomware", "Vulnerability Exploitation — Human Error", "Metadata Attack", "DDoS"], "a": 0, "e": "\"Malware that encrypts a victim's data and demands payment for the decryption key.\" describes Ransomware. Makes immutable, offline backups especially critical, since online backups can also be encrypted."}, {"obj": "1.9", "q": "A gaming company needs to store player profile data in a flexible, schema-less format that can evolve quickly as new features are added. Which database type best supports this?", "c": ["A strict relational schema with rigid table definitions", "A non-relational document database", "A tape-based archive system", "A block storage volume"], "a": 1, "e": "Non-relational (NoSQL) document databases support flexible, evolving schemas, which is well suited to rapidly changing application data models."}, {"obj": "3.3", "q": "An administrator explains the importance of a concept: \"Saves time when only a small subset of data (like one accidentally deleted file) needs to be restored.\" What concept is this?", "c": ["Backup Schedule", "Granular Recovery", "Backup Replication", "Backup Integrity Testing"], "a": 1, "e": "Saves time when only a small subset of data (like one accidentally deleted file) needs to be restored. This describes Granular Recovery (\"Restoring individual files or specific data items rather than an entire dataset.\")."}, {"obj": "1.3", "q": "A company configures a firewall to allow only necessary inbound ports to its web tier and denies everything else by default. What networking control is being used?", "c": ["A VPC peering rule", "A firewall/security group with least-privilege rules", "BGP route filtering", "CDN caching rules"], "a": 1, "e": "A properly scoped firewall or security group enforces least-privilege network access by only allowing explicitly required traffic."}, {"obj": "4.2", "q": "Which term is most closely associated with this real-world importance: \"Provides cloud-specific guidance (like the CCM) that general security standards may not fully address.\"?", "c": ["Data Sovereignty", "PCI DSS", "SOC2", "Cloud Security Alliance"], "a": 3, "e": "Provides cloud-specific guidance (like the CCM) that general security standards may not fully address. This describes Cloud Security Alliance (\"An organization that publishes best practices and frameworks specifically for cloud security.\")."}, {"obj": "2.3", "q": "An administrator explains the importance of a concept: \"The fastest migration approach but does not take advantage of cloud-native features.\" What concept is this?", "c": ["Rehost", "Retain", "Refactor", "Cloud-to-Cloud Migration"], "a": 0, "e": "The fastest migration approach but does not take advantage of cloud-native features. This describes Rehost (\"A migration strategy that moves an application to the cloud with minimal changes, also called lift and shift.\")."}, {"obj": "1.5", "q": "A company relies on a cloud provider's fully managed database service rather than installing and maintaining a database on their own VMs. What cloud-native concept does this represent?", "c": ["A cloud-provided managed service", "A monolithic architecture", "Tight coupling", "Fan-out messaging"], "a": 0, "e": "Using a provider-operated service instead of self-managed infrastructure is the definition of a cloud-provided managed service, reducing operational burden."}, {"obj": "1.5", "q": "A team designs services to communicate through well-defined APIs with minimal direct dependencies, so that changing one service rarely breaks another. What design principle does this reflect?", "c": ["Tight coupling", "Loosely coupled architecture", "Monolithic design", "Single point of failure design"], "a": 1, "e": "Loosely coupled architecture minimizes direct dependencies between components, improving resilience and flexibility when one component changes or fails."}, {"obj": "2.3", "q": "A colleague says: \"Similar to re-architecting but often more incremental, improving specific components over time.\" Which concept are they describing?", "c": ["Re-Architect", "Vendor Lock-In", "Refactor", "Rehost"], "a": 2, "e": "Similar to re-architecting but often more incremental, improving specific components over time. This describes Refactor (\"A migration strategy that rewrites portions of an application to better fit cloud-native patterns.\")."}, {"obj": "5.2", "q": "A team packages its application as a container image after a successful build and stores it in a company-controlled repository not accessible to the public. What is this repository called?", "c": ["A public repository", "A private repository", "A flat file artifact store with no access control", "An open-source repository"], "a": 1, "e": "A private repository restricts access to authorized users/systems, the standard choice for proprietary build artifacts like container images."}, {"obj": "4.3", "q": "An administrator needs remote graphical desktop access to a Windows-based cloud instance to run a GUI application. Which protocol should be used?", "c": ["SSH", "RDP", "OpenID Connect", "SAML"], "a": 1, "e": "RDP (Remote Desktop Protocol) is Microsoft's standard protocol for remote graphical access to Windows-based systems."}, {"obj": "6.2", "q": "A web application returns an HTTP 502 error to users whenever the backend server is overloaded. What does this status code category generally indicate?", "c": ["A client-side error caused by the browser", "A server-side or gateway error indicating a problem communicating with or receiving a valid response from the upstream server", "A successful request with no data", "A redirect to another URL"], "a": 1, "e": "5xx status codes like 502 generally indicate server-side or gateway errors, pointing to a problem with the upstream server rather than the client's request."}, {"obj": "1.11", "q": "A security company wants to automatically detect when a person enters a restricted area captured on camera. Which AI capability is most relevant?", "c": ["Visual recognition", "Text-to-voice", "Sentiment analysis", "Text translation"], "a": 0, "e": "Visual recognition identifies objects, scenes, or features (like a person) within images or video, matching this security use case."}, {"obj": "4.3", "q": "A new employee logs into the cloud provider's graphical dashboard through their web browser to review billing and configure a few settings manually. What interface are they using?", "c": ["The CLI", "An SDK", "A web portal", "Programmatic API access"], "a": 2, "e": "A web portal is the graphical, browser-based interface for managing cloud resources, most accessible for humans doing manual, occasional tasks."}, {"obj": "5.3", "q": "\"Web Sockets\" is best defined as which of the following?", "c": ["Simple Object Access Protocol — an XML-based messaging protocol for web services.", "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local.", "A query language for APIs that lets clients request exactly the data they need.", "A protocol providing full-duplex, persistent communication channels over a single TCP connection."], "a": 3, "e": "A protocol providing full-duplex, persistent communication channels over a single TCP connection. Enables real-time, bidirectional communication like chat apps or live dashboards, unlike typical request/response HTTP."}, {"obj": "5.3", "q": "A microservice calls a function on another internal service as if it were a local function call, without the caller needing to know the network details. What integration pattern is this?", "c": ["REST", "RPC (Remote Procedure Call)", "Web sockets", "GraphQL"], "a": 1, "e": "RPC lets a program execute a procedure on a remote system as if it were local, commonly used for internal microservice-to-microservice communication."}, {"obj": "1.11", "q": "A description reads: \"A device that collects data from the physical environment (temperature, motion, etc.).\" Which term does this describe?", "c": ["Generative AI", "IoT Transmission Protocol", "Text-to-Voice", "IoT Sensor"], "a": 3, "e": "\"A device that collects data from the physical environment (temperature, motion, etc.).\" describes IoT Sensor. The data-collection endpoint in most IoT architectures, feeding data upstream for processing."}, {"obj": "5.2", "q": "An administrator explains the importance of a concept: \"The step that transforms source code into something that can actually be run or deployed.\" What concept is this?", "c": ["Debian Package", "CI/CD Testing", "Build (CI/CD)", "VM Image Artifact"], "a": 2, "e": "The step that transforms source code into something that can actually be run or deployed. This describes Build (CI/CD) (\"Compiling/packaging source code into a deployable artifact.\")."}, {"obj": "1.8", "q": "Which term is most closely associated with this real-world importance: \"Maximizes flexibility for unpredictable or short-term workloads, at a higher per-unit cost than reserved pricing.\"?", "c": ["Rightsizing", "Spot Instance", "Pay-As-You-Go", "Dedicated Host Billing"], "a": 2, "e": "Maximizes flexibility for unpredictable or short-term workloads, at a higher per-unit cost than reserved pricing. This describes Pay-As-You-Go (\"A billing model charging only for actual resource consumption, with no upfront commitment.\")."}, {"obj": "1.7", "q": "Which term is most closely associated with this real-world importance: \"Simple but offers no failover if the host fails.\"?", "c": ["Overlay Network", "Stand-Alone Virtualization", "Cloning", "NAS (Virtualization Context)"], "a": 1, "e": "Simple but offers no failover if the host fails. This describes Stand-Alone Virtualization (\"A single hypervisor host running VMs with no clustering.\")."}, {"obj": "3.3", "q": "Select the most accurate description of \"Full Backup\":", "c": ["Restoring a large set of data all at once.", "A complete copy of all selected data.", "Restoring individual files or specific data items rather than an entire dataset.", "Restoring data directly onto the original system/location."], "a": 1, "e": "A complete copy of all selected data. Forms the baseline that incremental and differential backups build on."}, {"obj": "1.11", "q": "A description reads: \"Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case.\" Which term does this describe?", "c": ["Machine Learning", "Generative AI", "IoT Gateway", "Visual Recognition"], "a": 0, "e": "\"Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case.\" describes Machine Learning. Underpins many modern cloud AI services such as recommendation engines and fraud detection."}, {"obj": "4.3", "q": "Which term is most closely associated with this real-world importance: \"Similar to RBAC but organized around groups rather than formally defined roles.\"?", "c": ["Web Portal", "Federation", "Group-Based Access Control", "CLI"], "a": 2, "e": "Similar to RBAC but organized around groups rather than formally defined roles. This describes Group-Based Access Control (\"Granting permissions to a group, which members inherit by being added to that group.\")."}, {"obj": "3.4", "q": "\"Decommissioning — End of Support\" is best defined as which of the following?", "c": ["Retiring a resource because it has reached the end of its useful life or support.", "A smaller update, typically with bug fixes and small improvements.", "Data that must be retained beyond the life of the process or instance that created it.", "Retiring or upgrading a resource because the vendor no longer provides support/patches for it."], "a": 3, "e": "Retiring or upgrading a resource because the vendor no longer provides support/patches for it. Running unsupported resources leaves known vulnerabilities permanently unpatched."}, {"obj": "5.3", "q": "An enterprise integration uses an XML-based messaging protocol with a strict, formally defined contract between systems, common in legacy enterprise environments. What protocol is this?", "c": ["REST", "GraphQL", "SOAP", "Web sockets"], "a": 2, "e": "SOAP is an XML-based messaging protocol with a strict formal contract, still used in some enterprise and legacy system integrations, unlike the more flexible REST style."}, {"obj": "1.5", "q": "A description reads: \"A service the cloud provider fully operates (e.g., a managed database), removing the customer's operational burden.\" Which term does this describe?", "c": ["Cloud-Provided Managed Service", "Microservices", "Fan-Out", "Service Discovery"], "a": 0, "e": "\"A service the cloud provider fully operates (e.g., a managed database), removing the customer's operational burden.\" describes Cloud-Provided Managed Service. Reduces administrative overhead at the cost of some control and customization."}, {"obj": "4.1", "q": "Which term is most closely associated with this real-world importance: \"Ensures the scan actually covers all in-scope assets rather than leaving blind spots.\"?", "c": ["Remediation", "CVE", "Vulnerability Identification", "Scanning Scope"], "a": 3, "e": "Ensures the scan actually covers all in-scope assets rather than leaving blind spots. This describes Scanning Scope (\"Defining which systems, networks, or applications a vulnerability scan will cover.\")."}, {"obj": "5.1", "q": "A team wants to be able to see exactly what changed between two versions of their codebase and roll back to an earlier version if needed. What capability provides this?", "c": ["Code review alone", "Version management (tracking history via version control)", "A single pull request with no history", "Branch deletion"], "a": 1, "e": "Version management tracks and organizes different versions of code over time, providing the history needed to compare changes and roll back if necessary."}, {"obj": "3.4", "q": "Which concept is described by the phrase: \"Temporary data that does not need to persist beyond a session or process.\"?", "c": ["Minor Update", "Ephemeral Data", "Decommissioning — End of Life", "Major Update"], "a": 1, "e": "\"Temporary data that does not need to persist beyond a session or process.\" describes Ephemeral Data. Doesn't require the same backup/retention rigor as persistent data."}, {"obj": "5.2", "q": "A pipeline produces a versioned .rpm package as its build output for deployment to Red Hat-based Linux servers. What type of artifact is this?", "c": ["A Debian package", "An RPM package", "A container image artifact", "A VM image artifact"], "a": 1, "e": "An RPM package is the standard format used for installing software on RPM-based Linux distributions like Red Hat or CentOS."}, {"obj": "1.7", "q": "Which statement accurately describes \"Stand-Alone Virtualization\"?", "c": ["The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network.", "Network Attached Storage — shared file-level storage accessible by multiple hosts.", "A rule keeping specific VMs running on the same (or different) physical host.", "A single hypervisor host running VMs with no clustering."], "a": 3, "e": "A single hypervisor host running VMs with no clustering. Simple but offers no failover if the host fails."}, {"obj": "1.4", "q": "An administrator explains the importance of a concept: \"Appropriate for active production data that needs to be retrieved quickly and often.\" What concept is this?", "c": ["Block Storage", "Archive Storage Tier", "Cold Storage Tier", "Hot Storage Tier"], "a": 3, "e": "Appropriate for active production data that needs to be retrieved quickly and often. This describes Hot Storage Tier (\"A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost.\")."}, {"obj": "1.3", "q": "Given the description \"A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features.\", which term is being defined?", "c": ["Transit Gateway", "Application Gateway", "Subnet", "Firewall"], "a": 1, "e": "\"A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features.\" describes Application Gateway. Provides a single ingress point for web applications with built-in security and traffic-shaping features."}, {"obj": "1.2", "q": "A company chooses a warm DR site instead of a hot site for a moderately critical application. What trade-off are they accepting?", "c": ["Zero recovery time in exchange for higher cost", "A somewhat longer recovery time in exchange for lower ongoing cost than a hot site", "No possibility of data loss under any circumstances", "Guaranteed compliance with all regulations"], "a": 1, "e": "A warm site balances cost and readiness, accepting a longer RTO than a hot site in exchange for significantly lower ongoing operating costs."}, {"obj": "6.3", "q": "A developer installs an unapproved browser extension on a company-managed cloud console workstation, which turns out to exfiltrate session cookies. What category of issue caused this exposure?", "c": ["Cipher suite deprecation", "Unauthorized software", "Regional service availability", "IP scope exhaustion"], "a": 1, "e": "An unapproved, unvetted browser extension is unauthorized software, which introduced the vulnerability that led to session cookie exfiltration."}, {"obj": "1.6", "q": "Which term is most closely associated with this real-world importance: \"Allows external traffic to reach a service running inside an otherwise isolated container.\"?", "c": ["Port Mapping", "Ephemeral Storage", "Stand-Alone Container", "Persistent Volume"], "a": 0, "e": "Allows external traffic to reach a service running inside an otherwise isolated container. This describes Port Mapping (\"Binding a container's internal port to a port on the host or load balancer.\")."}, {"obj": "1.1", "q": "An enterprise IT team provisions virtual machines, configures the guest OS, and installs their own middleware and application stack on top of a provider's virtualized hardware. Which model are they using?", "c": ["SaaS", "PaaS", "IaaS", "FaaS"], "a": 2, "e": "IaaS provides only the virtualized infrastructure; the customer is responsible for the OS, middleware, and application layers."}, {"obj": "4.3", "q": "Which of the following is the correct expansion of \"SSO\"?", "c": ["Common Weakness Scoring System", "Single Sign-On", "Cloud Security Alliance", "Data Loss Prevention"], "a": 1, "e": "SSO stands for Single Sign-On. Authenticate once to gain access to multiple connected systems."}, {"obj": "3.3", "q": "Which term best matches this description: \"Restoring a large set of data all at once.\"?", "c": ["Backup Recoverability Testing", "Bulk Recovery", "Incremental Backup", "In-Place Recovery"], "a": 1, "e": "\"Restoring a large set of data all at once.\" describes Bulk Recovery. Appropriate when an entire system or dataset needs to be recovered together."}, {"obj": "4.4", "q": "A company configures its containers to run with the minimum necessary permissions, isolated from the host's sensitive resources, as a default security practice. What type of container is this?", "c": ["A privileged container", "An unprivileged container", "A public container with no restrictions", "A container with root access to the host"], "a": 1, "e": "Unprivileged containers run with restricted access, isolated from sensitive host resources, which is the safer default limiting the impact of a container-level compromise."}, {"obj": "4.3", "q": "How would you most accurately define \"SAML\"?", "c": ["Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.", "Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources.", "An identity layer built on top of OAuth 2.0 used for authentication (proving who you are).", "Software Development Kit — a set of libraries/tools that let developers programmatically interact with a cloud platform."], "a": 0, "e": "Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties. Commonly used to implement federated single sign-on into cloud platforms."}, {"obj": "1.10", "q": "In Cloud+ terminology, \"vCPU\" is an abbreviation for which of the following?", "c": ["Input/Output Operations Per Second", "Virtual CPU", "Center for Internet Security", "Artificial Intelligence"], "a": 1, "e": "vCPU stands for Virtual CPU. A virtualized representation of a physical CPU core allocated to a VM."}, {"obj": "6.1", "q": "In cloud computing terminology, \"Regional Service Availability\" refers to which of the following?", "c": ["The fact that not all cloud services are available in every region.", "A complete loss of service availability.", "A previously available feature or API being retired by the provider.", "Allocating more virtual resources than the underlying physical capacity can truly support."], "a": 0, "e": "The fact that not all cloud services are available in every region. A deployment can fail simply because a required service isn't offered in the chosen region."}, {"obj": "5.1", "q": "Which concept is described by the phrase: \"Having other team members examine proposed code changes before they are merged.\"?", "c": ["Version Management", "Pull Request", "Code Review", "Branch Management"], "a": 2, "e": "\"Having other team members examine proposed code changes before they are merged.\" describes Code Review. Catches bugs, security issues, and design problems before they reach production."}, {"obj": "4.6", "q": "How would you most accurately define \"Vulnerability Exploitation — Outdated Software\"?", "c": ["Malicious software designed to damage, disrupt, or gain unauthorized access to a system.", "An attack that abuses a cloud instance's metadata service to steal credentials or configuration data.", "A departure from a system's established normal behavior pattern.", "An attack that succeeds because a system was running software with a known, unpatched vulnerability."], "a": 3, "e": "An attack that succeeds because a system was running software with a known, unpatched vulnerability. Reinforces why timely patch management is one of the most effective security controls."}, {"obj": "1.8", "q": "Which statement accurately describes \"Reserved Resources\"?", "c": ["Adjusting the size/type of provisioned resources to match actual workload demand.", "Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice.", "Attaching key-value metadata labels to cloud resources.", "Pre-purchasing capacity for a discounted rate in exchange for a committed term."], "a": 3, "e": "Pre-purchasing capacity for a discounted rate in exchange for a committed term. Reduces cost for predictable, steady-state workloads compared to pay-as-you-go pricing."}, {"obj": "1.4", "q": "Which of the following is the correct expansion of \"VM\"?", "c": ["Platform as a Service", "Common Weakness Scoring System", "Simple Object Access Protocol", "Virtual Machine"], "a": 3, "e": "VM stands for Virtual Machine. A software-based emulation of a physical computer running under a hypervisor."}, {"obj": "6.1", "q": "Which concept is described by the phrase: \"A deployment failing because the deploying identity lacks sufficient rights.\"?", "c": ["Sizing Issues", "Permission Issues (Deployment)", "Oversubscription", "Full Outage"], "a": 1, "e": "\"A deployment failing because the deploying identity lacks sufficient rights.\" describes Permission Issues (Deployment). One of the most common causes of failed automated deployments in cloud environments."}, {"obj": "1.1", "q": "Which of the following terms fits this definition: \"Software as a Service — delivers a fully managed application to end users over the internet.\"?", "c": ["PaaS", "Shared Responsibility Model", "SaaS", "IaaS"], "a": 2, "e": "\"Software as a Service — delivers a fully managed application to end users over the internet.\" describes SaaS. The provider manages everything except the user's own data and configuration within the app."}, {"obj": "1.10", "q": "A workload needs to scale instantly to handle unpredictable spikes with zero server management and pay only for actual execution time. Which compute option fits best?", "c": ["VMs", "Containers", "Serverless functions", "Dedicated hosts"], "a": 2, "e": "Serverless (FaaS) compute eliminates server management and bills only for actual execution time, ideal for unpredictable event-driven workloads."}, {"obj": "3.1", "q": "Which of the following terms fits this definition: \"The defined actions taken once an alert is triaged and confirmed to need action.\"?", "c": ["Alert Response", "Alert Triage", "Log Aggregation", "Tracing"], "a": 0, "e": "\"The defined actions taken once an alert is triaged and confirmed to need action.\" describes Alert Response. Turns detection into resolution — an alert with no response plan provides little value."}, {"obj": "1.6", "q": "Which of the following would be the most appropriate use case for ephemeral storage in a container?", "c": ["Storing a customer database that must never lose data", "Storing temporary cache files used only during the current container's runtime", "Storing container images for reuse", "Storing long-term compliance archives"], "a": 1, "e": "Ephemeral storage is appropriate for temporary, disposable data like a runtime cache, since it is lost when the container stops."}, {"obj": "6.2", "q": "\"Protocol Incompatibility\" is best defined as which of the following?", "c": ["Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500).", "Network Address Translation — translates private addresses to a public address for routing.", "A connectivity failure caused by two systems using different or mismatched protocol versions.", "Domain Name System — resolves hostnames to IP addresses."], "a": 2, "e": "A connectivity failure caused by two systems using different or mismatched protocol versions. Common after upgrading one side of a connection without updating the other."}, {"obj": "6.2", "q": "A description reads: \"A connectivity failure caused by a system relying on a protocol version the other side no longer supports.\" Which term does this describe?", "c": ["HTTP Status Codes", "Access vs. Trunk Ports", "Misconfigured Route", "Protocol Deprecation"], "a": 3, "e": "\"A connectivity failure caused by a system relying on a protocol version the other side no longer supports.\" describes Protocol Deprecation. Highlights the need to track and update deprecated protocol usage before it causes an outage."}, {"obj": "6.2", "q": "Given the description \"Incorrect VLAN tagging causing traffic to be dropped or delivered to the wrong segment.\", which term is being defined?", "c": ["VLAN Misconfigured Tags", "Network Overlap", "NTP (Troubleshooting)", "Misconfigured Route"], "a": 0, "e": "\"Incorrect VLAN tagging causing traffic to be dropped or delivered to the wrong segment.\" describes VLAN Misconfigured Tags. A classic Layer 2 troubleshooting issue, especially after switch or trunk reconfiguration."}, {"obj": "4.5", "q": "Select the most accurate description of \"WAF\":", "c": ["Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications.", "A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs.", "Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic.", "Security software (antivirus, EDR) installed directly on servers, VMs, or devices."], "a": 0, "e": "Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications. Protects against application-layer attacks like SQL injection and cross-site scripting that a normal firewall wouldn't catch."}, {"obj": "1.2", "q": "Which term is most closely associated with this real-world importance: \"A tight RPO requires frequent backups or synchronous replication; a looser RPO allows infrequent backups.\"?", "c": ["Availability Zone", "Region", "RTO", "RPO"], "a": 3, "e": "A tight RPO requires frequent backups or synchronous replication; a looser RPO allows infrequent backups. This describes RPO (\"Recovery Point Objective — the maximum acceptable amount of data loss, measured in time.\")."}, {"obj": "5.4", "q": "A long-established team wants a widely adopted, extensible open-source automation server to orchestrate their build, test, and deployment stages, with a large plugin ecosystem. Which tool fits best?", "c": ["Grafana", "Jenkins", "Git", "Docker"], "a": 1, "e": "Jenkins is one of the most established and widely used open-source automation servers for orchestrating CI/CD pipelines, known for its extensive plugin ecosystem."}, {"obj": "2.3", "q": "A company redesigns a monolithic application into cloud-native microservices to fully leverage auto-scaling and managed services, investing significant engineering effort. What migration strategy is this?", "c": ["Rehost", "Replatform", "Re-architect", "Retain"], "a": 2, "e": "Re-architecting substantially redesigns an application to be cloud-native, requiring the most effort but unlocking the greatest long-term scalability and cost benefits."}, {"obj": "2.1", "q": "A colleague says: \"Lowest upfront cost and fastest to provision, but less control than private cloud.\" Which concept are they describing?", "c": ["Public Cloud", "On Premises", "Hybrid Cloud", "Private Cloud"], "a": 0, "e": "Lowest upfront cost and fastest to provision, but less control than private cloud. This describes Public Cloud (\"Infrastructure owned by a third-party provider and shared across many customers (multi-tenant).\")."}, {"obj": "1.6", "q": "Which concept is described by the phrase: \"Binding a container's internal port to a port on the host or load balancer.\"?", "c": ["Stand-Alone Container", "Persistent Volume", "Port Mapping", "Ephemeral Storage"], "a": 2, "e": "\"Binding a container's internal port to a port on the host or load balancer.\" describes Port Mapping. Allows external traffic to reach a service running inside an otherwise isolated container."}, {"obj": "6.1", "q": "Select the most accurate description of \"Regional Service Availability\":", "c": ["A provider intentionally limiting the rate of API calls a customer can make.", "The fact that not all cloud services are available in every region.", "Allocating more virtual resources than the underlying physical capacity can truly support.", "Incorrectly assigned CPU, memory, or storage limits for a workload."], "a": 1, "e": "The fact that not all cloud services are available in every region. A deployment can fail simply because a required service isn't offered in the chosen region."}, {"obj": "4.6", "q": "Which concept is described by the phrase: \"An attack that succeeds because a system was running software with a known, unpatched vulnerability.\"?", "c": ["Vulnerability Exploitation — Outdated Software", "Malware", "Vulnerability Exploitation — Human Error", "Phishing"], "a": 0, "e": "\"An attack that succeeds because a system was running software with a known, unpatched vulnerability.\" describes Vulnerability Exploitation — Outdated Software. Reinforces why timely patch management is one of the most effective security controls."}, {"obj": "4.4", "q": "A security review discovers that an object storage bucket containing customer data was configured with public read access by mistake. What is the most direct security risk this represents?", "c": ["No risk, since object storage cannot be accessed externally", "Public exposure of potentially sensitive data to anyone on the internet", "Automatic encryption of the exposed data", "Guaranteed compliance with all data protection laws"], "a": 1, "e": "Misconfigured object storage permissions are a very common real-world cause of public data exposure, directly risking unauthorized access to sensitive data."}, {"obj": "4.4", "q": "Given the description \"Encrypting data as it moves across a network (e.g., via TLS).\", which term is being defined?", "c": ["Data in Transit Encryption", "Zero Trust", "Principle of Least Privilege", "Hardening"], "a": 0, "e": "\"Encrypting data as it moves across a network (e.g., via TLS).\" describes Data in Transit Encryption. Protects data from eavesdropping while crossing untrusted networks like the internet."}, {"obj": "4.1", "q": "Which of the following is the correct expansion of \"CWSS\"?", "c": ["Local Area Network", "Function as a Service", "Common Weakness Scoring System", "Representational State Transfer"], "a": 2, "e": "CWSS stands for Common Weakness Scoring System. A method for scoring the severity of software weaknesses."}, {"obj": "4.5", "q": "Which combination of controls would provide the most comprehensive protection for a public-facing web application against both network-layer floods and application-layer attacks?", "c": ["Only a network ACL", "DDoS protection for network-layer floods combined with a WAF for application-layer attacks", "Only IAM policies", "Only data at rest encryption"], "a": 1, "e": "DDoS protection addresses network/transport-layer flooding attacks, while a WAF addresses application-layer attacks like SQL injection — together providing layered protection."}, {"obj": "1.2", "q": "Which term best matches this description: \"Processing data physically close to where it is generated rather than in a centralized datacenter.\"?", "c": ["Edge Computing", "Hot Site", "Multicloud Tenancy", "RPO"], "a": 0, "e": "\"Processing data physically close to where it is generated rather than in a centralized datacenter.\" describes Edge Computing. Reduces latency for time-sensitive applications like IoT and content delivery."}, {"obj": "2.2", "q": "A team applies an update directly to a single production database server with no separate standby environment, accepting the risk since a full parallel environment isn't cost-justified for this workload. What strategy is this?", "c": ["Blue-green deployment", "In-place deployment", "Canary deployment", "Rolling deployment"], "a": 1, "e": "Directly updating the existing server with no separate environment is in-place deployment, simpler but riskier without a ready fallback."}, {"obj": "3.2", "q": "Which scaling approach provides both increased capacity and improved redundancy, since a failure of any single instance doesn't take down the entire service?", "c": ["Vertical scaling of a single instance", "Horizontal scaling across multiple instances", "Manual scaling with no redundancy consideration", "None of these approaches affect redundancy"], "a": 1, "e": "Horizontal scaling spreads the workload across multiple instances, so the failure of any single instance doesn't take down the entire service, unlike a single vertically scaled instance."}, {"obj": "6.2", "q": "An administrator explains the importance of a concept: \"Common after upgrading one side of a connection without updating the other.\" What concept is this?", "c": ["NAT (Troubleshooting)", "HTTP Status Codes", "DNS (Troubleshooting)", "Protocol Incompatibility"], "a": 3, "e": "Common after upgrading one side of a connection without updating the other. This describes Protocol Incompatibility (\"A connectivity failure caused by two systems using different or mismatched protocol versions.\")."}, {"obj": "2.3", "q": "Given the description \"A migration strategy that keeps a workload where it currently is, deferring migration.\", which term is being defined?", "c": ["Refactor", "Rehost", "Retain", "Re-Architect"], "a": 2, "e": "\"A migration strategy that keeps a workload where it currently is, deferring migration.\" describes Retain. Appropriate for applications not yet ready or not worth migrating due to cost or complexity."}, {"obj": "4.6", "q": "A ransomware attack encrypts a company's production data, and the attacker demands payment for a decryption key. What should this reinforce about the company's backup strategy?", "c": ["Backups are unnecessary if ransomware protection software is installed", "Immutable or offline backup copies are critical, since online/connected backups could also be encrypted by the same attack", "Only cloud-native applications are vulnerable to ransomware", "Ransomware only affects on-premises infrastructure, not the cloud"], "a": 1, "e": "Since ransomware can potentially reach and encrypt connected backup storage, immutable or offline backup copies are critical to ensure recovery remains possible."}, {"obj": "3.2", "q": "Why does this matter on the exam and in practice? \"The most common autoscaling trigger, reacting quickly to current demand.\" — which term does this explain?", "c": ["Scheduled Scaling", "Manual Scaling", "Triggered Scaling — Trending", "Triggered Scaling — Load"], "a": 3, "e": "The most common autoscaling trigger, reacting quickly to current demand. This describes Triggered Scaling — Load (\"Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%).\")."}, {"obj": "1.7", "q": "Which of the following terms fits this definition: \"A virtual network built on top of physical network infrastructure, common in virtualization and containers.\"?", "c": ["Overlay Network", "Clustering", "VM Network", "NAS (Virtualization Context)"], "a": 0, "e": "\"A virtual network built on top of physical network infrastructure, common in virtualization and containers.\" describes Overlay Network. Allows flexible virtual network topologies independent of the underlying physical network layout."}, {"obj": "1.5", "q": "In cloud computing terminology, \"Microservices\" refers to which of the following?", "c": ["An architecture where an application is broken into small, independently deployable services.", "A mechanism that lets services dynamically find the network location of other services.", "A service the cloud provider fully operates (e.g., a managed database), removing the customer's operational burden.", "A design where components interact through well-defined interfaces with minimal direct dependencies."], "a": 0, "e": "An architecture where an application is broken into small, independently deployable services. Allows teams to develop, scale, and deploy components independently rather than as one large monolith."}, {"obj": "1.7", "q": "A description reads: \"The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network.\" Which term does this describe?", "c": ["Clustering", "SAN (Virtualization Context)", "Host Affinity", "VM Network"], "a": 3, "e": "\"The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network.\" describes VM Network. Determines how a VM communicates with other VMs, the host, and external networks."}, {"obj": "4.2", "q": "Which of the following best describes \"Data Sovereignty\"?", "c": ["The principle that data is subject to the laws of the country in which it is physically located.", "An international standard specifying requirements for an information security management system.", "Requirements or preferences about the physical location where data is stored or processed.", "Defining who legally owns and controls a given set of data."], "a": 0, "e": "The principle that data is subject to the laws of the country in which it is physically located. Determines which region a workload must be deployed in to satisfy legal requirements."}, {"obj": "5.2", "q": "A description reads: \"The defined sequence of automated stages a change passes through from commit to deployment.\" Which term does this describe?", "c": ["CI/CD Testing", "Code Integration", "RPM Package", "CI/CD Workflow"], "a": 3, "e": "\"The defined sequence of automated stages a change passes through from commit to deployment.\" describes CI/CD Workflow. Documents and enforces a consistent, repeatable delivery process."}, {"obj": "3.1", "q": "Which concept is described by the phrase: \"Combining logs from many sources into a unified, searchable view.\"?", "c": ["Log Retention", "Log Aggregation", "Alert Response", "Tracing"], "a": 1, "e": "\"Combining logs from many sources into a unified, searchable view.\" describes Log Aggregation. Enables correlation across services, which is essential for diagnosing distributed system issues."}, {"obj": "4.1", "q": "After identifying a critical vulnerability in a web server, the team applies a vendor-released patch to resolve it. What step of the vulnerability management lifecycle is this?", "c": ["Vulnerability identification", "Vulnerability assessment", "Remediation", "Scanning scope definition"], "a": 2, "e": "Remediation is the step that actually applies a fix to resolve a known vulnerability, reducing real risk rather than just cataloging it."}, {"obj": "6.1", "q": "An administrator explains the importance of a concept: \"Can cause deployment or application failures if automation exceeds the allowed request rate.\" What concept is this?", "c": ["Oversubscription", "Regional Service Availability", "API Throttling", "Resource Allocation Misconfiguration"], "a": 2, "e": "Can cause deployment or application failures if automation exceeds the allowed request rate. This describes API Throttling (\"A provider intentionally limiting the rate of API calls a customer can make.\")."}, {"obj": "4.1", "q": "Why does this matter on the exam and in practice? \"Provides a common reference so vulnerabilities can be tracked and discussed consistently across tools and vendors.\" — which term does this explain?", "c": ["CVE", "Vulnerability Assessment", "Remediation", "Scanning Scope"], "a": 0, "e": "Provides a common reference so vulnerabilities can be tracked and discussed consistently across tools and vendors. This describes CVE (\"Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities.\")."}, {"obj": "4.3", "q": "An organization wants employees to log in to cloud resources using their existing corporate Active Directory credentials rather than separate cloud-only accounts. What should be implemented?", "c": ["Local user authentication", "Federation", "Discretionary access control", "Token-based authentication only"], "a": 1, "e": "Federation lets users authenticate with a trusted external identity provider, avoiding duplicate account management."}, {"obj": "3.4", "q": "A vendor releases a small update containing only minor bug fixes and small improvements, with no breaking changes expected. What type of update is this?", "c": ["A major update", "A minor update", "A patch specifically for a security vulnerability", "A full re-architecture"], "a": 1, "e": "A minor update typically includes small bug fixes and improvements, generally lower risk than a major update but still warranting testing before production rollout."}, {"obj": "3.3", "q": "A user accidentally deletes a single important spreadsheet from a large shared drive containing thousands of files. What type of recovery is most appropriate?", "c": ["Bulk recovery of the entire drive", "Granular recovery of just the deleted file", "In-place recovery of the entire system", "Parallel recovery to an alternate environment"], "a": 1, "e": "Granular recovery restores individual files or specific data items rather than an entire dataset, saving significant time for a small-scope restore like a single file."}, {"obj": "1.7", "q": "In cloud computing terminology, \"Local Storage (Virtualization)\" refers to which of the following?", "c": ["Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction.", "Creating an exact copy of an existing VM.", "Storage physically attached to a single hypervisor host.", "A rule keeping specific VMs running on the same (or different) physical host."], "a": 2, "e": "Storage physically attached to a single hypervisor host. Fast and simple but doesn't support live migration of VMs to other hosts without shared storage."}, {"obj": "1.8", "q": "A company wants to compare costs across projects but discovers many resources were never tagged, making cost allocation impossible after the fact. What should have been implemented from the start?", "c": ["A mandatory tagging policy enforced at resource creation", "Dedicated host billing for every resource", "Spot instance pricing for every resource", "Avoiding resource metering"], "a": 0, "e": "Enforcing a mandatory tagging policy at creation time ensures every resource can later be allocated to the correct project or cost center."}, {"obj": "2.1", "q": "A colleague says: \"Offers greater control and customization at higher cost than public cloud.\" Which concept are they describing?", "c": ["On Premises", "Private Cloud", "Community Cloud", "Hybrid Cloud"], "a": 1, "e": "Offers greater control and customization at higher cost than public cloud. This describes Private Cloud (\"Infrastructure dedicated to a single organization, hosted on- or off-premises.\")."}, {"obj": "4.6", "q": "A security team discovers a cloud instance that has been running for eight months with no assigned owner, no monitoring, and an outdated OS. What immediate risk does this represent?", "c": ["No risk, since the instance has been stable for eight months", "An unpatched, unmonitored zombie instance representing both wasted cost and an unmanaged attack surface", "Guaranteed compliance with security policy", "Automatic protection from all attacks due to its age"], "a": 1, "e": "An unmonitored, unowned, outdated instance (a zombie instance) represents real risk: it's likely unpatched and could be compromised without anyone noticing."}, {"obj": "1.6", "q": "A description reads: \"Temporary storage tied to a container's lifecycle that is lost when the container stops.\" Which term does this describe?", "c": ["Persistent Volume", "Ephemeral Storage", "Stand-Alone Container", "Port Mapping"], "a": 1, "e": "\"Temporary storage tied to a container's lifecycle that is lost when the container stops.\" describes Ephemeral Storage. Suitable only for temporary/scratch data since it disappears when the container is removed."}, {"obj": "6.1", "q": "A deployment pipeline consistently fails at the exact same step where it tries to attach a role to a new service, and the pipeline's own identity lacks the rights to perform that specific action. What category of issue is this?", "c": ["Sizing issues", "Permission issues", "Deprecation of functionality", "Oversubscription"], "a": 1, "e": "A failure specifically due to the deploying identity lacking sufficient rights for a particular action is a permission issue."}, {"obj": "5.2", "q": "Select the most accurate description of \"Build (CI/CD)\":", "c": ["A package format (.deb) used for installing software on Debian-based Linux distributions.", "A code or artifact repository accessible to anyone.", "Compiling/packaging source code into a deployable artifact.", "The defined sequence of automated stages a change passes through from commit to deployment."], "a": 2, "e": "Compiling/packaging source code into a deployable artifact. The step that transforms source code into something that can actually be run or deployed."}, {"obj": "1.3", "q": "Which term is most closely associated with this real-world importance: \"Forms the fundamental network boundary for cloud resources, similar to a private on-premises network.\"?", "c": ["VPC", "VPC Peering", "Network Load Balancer", "Static Route"], "a": 0, "e": "Forms the fundamental network boundary for cloud resources, similar to a private on-premises network. This describes VPC (\"Virtual Private Cloud — an isolated, logically defined network within a public cloud provider's infrastructure.\")."}, {"obj": "1.6", "q": "A company needs to automatically restart failed containers, scale services up under load, and schedule containers across a cluster of nodes. What is required?", "c": ["A stand-alone container runtime only", "Workload orchestration (e.g., Kubernetes)", "A single image registry", "Ephemeral storage only"], "a": 1, "e": "Workload orchestration platforms like Kubernetes automate deployment, scaling, and self-healing of containers across a cluster, which stand-alone containers cannot do."}, {"obj": "6.3", "q": "Which of the following scenarios best illustrates privilege escalation as distinct from simple unauthorized access?", "c": ["An attacker uses a stolen valid password to log into an account they were never authorized to use at all", "An account with limited permissions exploits a flaw to gain permissions well beyond what was originally granted to that same account", "An employee accidentally emails a file to the wrong recipient", "A server experiences a network outage"], "a": 1, "e": "Privilege escalation specifically involves an already-authenticated identity gaining permissions beyond what was originally granted to it, distinct from an outsider using stolen credentials to access an account they had no rights to at all."}, {"obj": "5.2", "q": "Which concept is described by the phrase: \"A simple, unstructured file (like a config or script) produced or consumed by a pipeline.\"?", "c": ["Public Repository", "Build (CI/CD)", "Flat File Artifact", "Container Image Artifact"], "a": 2, "e": "\"A simple, unstructured file (like a config or script) produced or consumed by a pipeline.\" describes Flat File Artifact. Sometimes all that's needed for simple deployment tasks, without a full package format."}, {"obj": "2.2", "q": "Which deployment strategy carries the highest risk of extended downtime if a critical bug is introduced, since there is no separate environment to fall back to?", "c": ["Blue-green deployment", "Canary deployment", "In-place deployment", "Rolling deployment with health checks"], "a": 2, "e": "In-place deployment updates the existing instance directly with no separate fallback environment, making recovery from a bad update slower and riskier."}, {"obj": "3.3", "q": "Which of the following best describes \"Incremental Backup\"?", "c": ["Restoring data to an alternate system running alongside the original.", "Backs up only data changed since the last backup of any type.", "Restoring a large set of data all at once.", "Copying backup data to another location (often off-site or another region)."], "a": 1, "e": "Backs up only data changed since the last backup of any type. Fastest to perform, but restoring requires the full chain of backups applied in order."}, {"obj": "6.1", "q": "Which concept is described by the phrase: \"A provider intentionally limiting the rate of API calls a customer can make.\"?", "c": ["Permission Issues (Deployment)", "Oversubscription", "API Throttling", "Resource Allocation Misconfiguration"], "a": 2, "e": "\"A provider intentionally limiting the rate of API calls a customer can make.\" describes API Throttling. Can cause deployment or application failures if automation exceeds the allowed request rate."}, {"obj": "6.1", "q": "A description reads: \"Allocating more virtual resources than the underlying physical capacity can truly support.\" Which term does this describe?", "c": ["Outdated Component Definitions", "Oversubscription", "Permission Issues (Deployment)", "Deprecation of Functionality"], "a": 1, "e": "\"Allocating more virtual resources than the underlying physical capacity can truly support.\" describes Oversubscription. Can cause performance degradation or failed provisioning if too many workloads compete for the same physical resources."}, {"obj": "6.2", "q": "A switch port configured as an access port for a single VLAN is instead expected to carry traffic for multiple VLANs simultaneously as a trunk. What is the likely misconfiguration?", "c": ["Confusing access vs. trunk port configuration", "IP scope exhaustion", "NTP misconfiguration", "DHCP failure"], "a": 0, "e": "Confusing an access port (single VLAN) with a trunk port (multiple VLANs) is a classic cause of VLAN connectivity problems after switch configuration changes."}, {"obj": "1.10", "q": "Select the most accurate description of \"Storage Throughput\":", "c": ["Using virtual machines as the compute resource type for a workload.", "Using containers as the compute resource type for a workload.", "The actual amount of data successfully transferred over a network connection in a given time.", "The rate of data transfer to/from a storage system, usually measured in MB/s or GB/s."], "a": 3, "e": "The rate of data transfer to/from a storage system, usually measured in MB/s or GB/s. Important for workloads that move large volumes of data, like backups or media processing."}, {"obj": "3.4", "q": "A temporary cache used only during a single batch processing job does not need to be backed up or retained after the job completes. What type of data is this?", "c": ["Persistent data", "Ephemeral data", "Regulatory data", "Archived compliance data"], "a": 1, "e": "Ephemeral data is temporary and does not need to persist beyond a session or process, unlike persistent data that represents lasting business value."}, {"obj": "6.1", "q": "A colleague says: \"A deployment can fail simply because a required service isn't offered in the chosen region.\" Which concept are they describing?", "c": ["Deprecation of Functionality", "Regional Service Availability", "Service Quota", "Incompatibility (Deployment)"], "a": 1, "e": "A deployment can fail simply because a required service isn't offered in the chosen region. This describes Regional Service Availability (\"The fact that not all cloud services are available in every region.\")."}, {"obj": "4.5", "q": "Given the description \"Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications.\", which term is being defined?", "c": ["IAM Policies", "Endpoint Protection", "Network ACL", "WAF"], "a": 3, "e": "\"Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications.\" describes WAF. Protects against application-layer attacks like SQL injection and cross-site scripting that a normal firewall wouldn't catch."}, {"obj": "1.3", "q": "An application needs routing decisions made based on the URL path of incoming HTTP requests. Which type of load balancer is required?", "c": ["Network load balancer", "Application load balancer", "DNS round robin", "Static route"], "a": 1, "e": "Application (Layer 7) load balancers can inspect HTTP-level data like URL paths to make routing decisions, unlike Layer 4 network load balancers."}, {"obj": "3.3", "q": "Which term is most closely associated with this real-world importance: \"Directly determines the achievable RPO for a given system.\"?", "c": ["Incremental Backup", "Backup Encryption", "Backup Schedule", "Granular Recovery"], "a": 2, "e": "Directly determines the achievable RPO for a given system. This describes Backup Schedule (\"The defined frequency and timing of backup jobs.\")."}, {"obj": "4.2", "q": "Which term best matches this description: \"Requirements or preferences about the physical location where data is stored or processed.\"?", "c": ["Data Classification", "Data Locality", "Litigation Hold", "Data Sovereignty"], "a": 1, "e": "\"Requirements or preferences about the physical location where data is stored or processed.\" describes Data Locality. Closely related to, but distinct from, data sovereignty — it may be a business rather than legal requirement."}, {"obj": "4.5", "q": "A company wants both subnet-level and instance-level network access control for defense in depth within its VPC. Which two controls should be combined?", "c": ["WAF and DLP", "Network ACLs (subnet-level) and network security groups (instance-level)", "IDS and IPS only", "CDN caching and DDoS protection"], "a": 1, "e": "Combining network ACLs at the subnet level with network security groups at the instance level provides layered, defense-in-depth network access control."}, {"obj": "2.2", "q": "\"Canary Deployment\" is best defined as which of the following?", "c": ["A strategy running two identical environments (blue and green), switching traffic to the new version once verified.", "Updating instances incrementally, a few at a time, rather than all at once.", "Gradually rolling out a change to a small subset of users or servers before a full rollout.", "Updating an existing server or instance directly rather than deploying an entirely new one."], "a": 2, "e": "Gradually rolling out a change to a small subset of users or servers before a full rollout. Limits the blast radius of a bad deployment by exposing it to only a fraction of traffic first."}, {"obj": "4.5", "q": "A company deploys a control that monitors network traffic for suspicious patterns and generates alerts for the security team to investigate, without automatically blocking anything. What control is this?", "c": ["IPS", "IDS", "A WAF blocking mode", "DDoS protection"], "a": 1, "e": "IDS monitors and alerts on suspicious activity without automatically blocking it, distinct from IPS which takes active blocking action."}, {"obj": "6.2", "q": "After a switch reconfiguration, traffic tagged for VLAN 20 is being delivered to devices expecting VLAN 10 instead. What is the likely cause?", "c": ["VLAN misconfigured tags", "IP scope exhaustion", "NTP drift", "HTTP status code mismatch"], "a": 0, "e": "Incorrect VLAN tagging causes traffic to be delivered to the wrong logical segment, a classic Layer 2 troubleshooting issue after switch reconfiguration."}, {"obj": "1.10", "q": "Why does this matter on the exam and in practice? \"Frees up staff time from routine maintenance so they can focus on higher-value work.\" — which term does this explain?", "c": ["Managed Services (Optimization)", "Compute Optimization (Serverless)", "Network Latency", "Compute Optimization (VM)"], "a": 0, "e": "Frees up staff time from routine maintenance so they can focus on higher-value work. This describes Managed Services (Optimization) (\"Using provider-operated services instead of self-managed infrastructure to reduce operational overhead.\")."}, {"obj": "3.1", "q": "Which term best matches this description: \"Gathering log data from applications, systems, and services into a central location.\"?", "c": ["Alert Response", "Tracing", "Monitoring Metrics", "Log Collection"], "a": 3, "e": "\"Gathering log data from applications, systems, and services into a central location.\" describes Log Collection. The first step in observability — without collection, logs remain scattered and hard to analyze."}, {"obj": "5.1", "q": "Why does this matter on the exam and in practice? \"The standard workflow mechanism for reviewing and discussing changes before merging.\" — which term does this explain?", "c": ["Code Merge", "Code Push", "Branch Management", "Pull Request"], "a": 3, "e": "The standard workflow mechanism for reviewing and discussing changes before merging. This describes Pull Request (\"A formal request to merge a proposed code change into a shared branch, typically triggering review.\")."}, {"obj": "3.3", "q": "An administrator explains the importance of a concept: \"Restores are simpler than incremental (just the full plus the latest differential), but each differential grows larger over time.\" What concept is this?", "c": ["Backup Schedule", "Incremental Backup", "Differential Backup", "Granular Recovery"], "a": 2, "e": "Restores are simpler than incremental (just the full plus the latest differential), but each differential grows larger over time. This describes Differential Backup (\"Backs up all data changed since the last full backup.\")."}, {"obj": "5.3", "q": "A stock trading platform needs to stream live price updates to thousands of connected clients with minimal latency and without clients needing to repeatedly poll for new data. Which technology is best suited?", "c": ["A nightly batch export", "Web sockets", "A one-time REST GET request", "SOAP with polling"], "a": 1, "e": "Web sockets provide the persistent, low-latency, push-based connection needed to stream continuously updating data like live stock prices to many clients."}, {"obj": "2.3", "q": "Which term is most closely associated with this real-world importance: \"A middle ground between a straight lift-and-shift and a full application redesign.\"?", "c": ["Replatform", "On-Premises-to-Cloud Migration", "Rehost", "Retain"], "a": 0, "e": "A middle ground between a straight lift-and-shift and a full application redesign. This describes Replatform (\"A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture.\")."}, {"obj": "6.3", "q": "Given the description \"Software installed or running without proper approval, increasing risk and potentially breaching policy.\", which term is being defined?", "c": ["Software Vulnerability Issues", "Unauthorized Access", "Unauthorized Software", "Cipher Suite Deprecation"], "a": 2, "e": "\"Software installed or running without proper approval, increasing risk and potentially breaching policy.\" describes Unauthorized Software. Can introduce vulnerabilities, malware, or licensing violations into an otherwise controlled environment."}, {"obj": "5.2", "q": "Which statement accurately describes \"Build (CI/CD)\"?", "c": ["Automatically running tests against code as part of the pipeline.", "A simple, unstructured file (like a config or script) produced or consumed by a pipeline.", "Compiling/packaging source code into a deployable artifact.", "A packaged container image produced and stored as a build output."], "a": 2, "e": "Compiling/packaging source code into a deployable artifact. The step that transforms source code into something that can actually be run or deployed."}, {"obj": "4.3", "q": "A description reads: \"A hardened server that provides a single, monitored entry point for administrative access into a private network.\" Which term does this describe?", "c": ["Bastion Host", "OpenID Connect", "Directory-Based Authentication", "MFA"], "a": 0, "e": "\"A hardened server that provides a single, monitored entry point for administrative access into a private network.\" describes Bastion Host. Reduces the attack surface by ensuring administrative access doesn't require directly exposing every resource."}, {"obj": "1.2", "q": "A company deploys redundant application servers across three separate physical datacenters within the same metro region, each with independent power and cooling. What construct are they using?", "c": ["Multiple regions", "Multiple availability zones", "A single datacenter with redundant racks", "Edge computing nodes"], "a": 1, "e": "Availability zones are isolated locations within a single region with independent power, cooling, and networking, protecting against a single datacenter failure."}, {"obj": "5.2", "q": "Which term is most closely associated with this real-world importance: \"Sometimes all that's needed for simple deployment tasks, without a full package format.\"?", "c": ["CI/CD Automation", "CI/CD Workflow", "Code Deployment", "Flat File Artifact"], "a": 3, "e": "Sometimes all that's needed for simple deployment tasks, without a full package format. This describes Flat File Artifact (\"A simple, unstructured file (like a config or script) produced or consumed by a pipeline.\")."}, {"obj": "5.2", "q": "Which of the following terms fits this definition: \"Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions.\"?", "c": ["RPM Package", "Code Integration", "Debian Package", "Public Repository"], "a": 0, "e": "\"Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions.\" describes RPM Package. One of several standard package formats a CI/CD pipeline might produce or deploy."}, {"obj": "1.10", "q": "Why does this matter on the exam and in practice? \"Ensures workloads are placed, scaled, and healed automatically according to defined policies.\" — which term does this explain?", "c": ["Compute Optimization (Serverless)", "Orchestration (Workload)", "Network Latency", "Compute Optimization (VM)"], "a": 1, "e": "Ensures workloads are placed, scaled, and healed automatically according to defined policies. This describes Orchestration (Workload) (\"Automated coordination of workload deployment, scaling, and lifecycle management.\")."}, {"obj": "5.1", "q": "Which term best matches this description: \"Organizing and maintaining separate lines of development (branches) within a repository.\"?", "c": ["Pull Request", "Branch Management", "Code Merge", "Code Commit"], "a": 1, "e": "\"Organizing and maintaining separate lines of development (branches) within a repository.\" describes Branch Management. Allows parallel work on features/fixes without disrupting the main codebase."}, {"obj": "1.3", "q": "A company's cloud network engineer manually configures a fixed path for traffic between two specific subnets that rarely changes. What did they configure?", "c": ["A dynamic BGP route", "A static route", "A CDN cache rule", "A load balancer health check"], "a": 1, "e": "A static route is a manually configured, fixed path that doesn't automatically adjust to topology changes, appropriate for simple, stable routing needs."}, {"obj": "4.1", "q": "Which of the following terms fits this definition: \"Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability.\"?", "c": ["Vulnerability Assessment", "CVE", "Scanning Scope", "Remediation"], "a": 3, "e": "\"Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability.\" describes Remediation. The step that actually reduces risk — identification without remediation provides no real protection."}, {"obj": "3.2", "q": "Given the description \"Scaling resources up or down at predefined times based on known usage patterns.\", which term is being defined?", "c": ["Horizontal Scaling", "Manual Scaling", "Triggered Scaling — Load", "Scheduled Scaling"], "a": 3, "e": "\"Scaling resources up or down at predefined times based on known usage patterns.\" describes Scheduled Scaling. Ideal for predictable daily/weekly demand cycles, like scaling up before business hours."}, {"obj": "2.3", "q": "Why does this matter on the exam and in practice? \"The fastest migration approach but does not take advantage of cloud-native features.\" — which term does this explain?", "c": ["Replatform", "Rehost", "Re-Architect", "Refactor"], "a": 1, "e": "The fastest migration approach but does not take advantage of cloud-native features. This describes Rehost (\"A migration strategy that moves an application to the cloud with minimal changes, also called lift and shift.\")."}, {"obj": "4.3", "q": "How would you most accurately define \"OAuth 2.0\"?", "c": ["A chronological record of who did what, and when, within a system.", "An authorization framework that lets an application access resources on a user's behalf without sharing their password.", "Application Programming Interface — used here for programmatic management/access to cloud resources.", "Allowing users to authenticate using credentials from a separate, trusted identity provider."], "a": 1, "e": "An authorization framework that lets an application access resources on a user's behalf without sharing their password. The standard mechanism behind \"log in with...\" and delegated API access scenarios."}, {"obj": "4.6", "q": "Which of the following scenarios best illustrates detecting an attack through deviation from an established baseline rather than a signature-based detection?", "c": ["A known malware hash is matched by antivirus software", "A system's normal login pattern is a handful of times during business hours, but monitoring flags dozens of logins at 2 AM from an unusual location", "A firewall blocks traffic on a known malicious port", "A vulnerability scanner matches a system against a published CVE"], "a": 1, "e": "Flagging behavior that deviates from an established normal pattern (like unusual login times/locations) is baseline-deviation detection, distinct from signature-based methods like hash or CVE matching."}, {"obj": "4.4", "q": "A description reads: \"Applying vendor-released updates that fix known vulnerabilities.\" Which term does this describe?", "c": ["CIS Benchmark", "Vendor-Specific Benchmark", "Data at Rest Encryption", "Patching (Security)"], "a": 3, "e": "\"Applying vendor-released updates that fix known vulnerabilities.\" describes Patching (Security). Closes known security gaps that attackers commonly target since patches for them already exist."}, {"obj": "1.1", "q": "A media company needs to run a short image-processing task every time a user uploads a photo, without maintaining any server capacity between uploads. Which service model minimizes idle cost for this workload?", "c": ["IaaS with reserved instances", "PaaS with an always-on app server", "FaaS (serverless functions)", "On-premises dedicated hardware"], "a": 2, "e": "FaaS bills only for actual execution time triggered by events like uploads, avoiding the cost of maintaining idle capacity between invocations."}, {"obj": "5.1", "q": "A colleague says: \"Allows parallel work on features/fixes without disrupting the main codebase.\" Which concept are they describing?", "c": ["Branch Management", "Code Commit", "Version Management", "Pull Request"], "a": 0, "e": "Allows parallel work on features/fixes without disrupting the main codebase. This describes Branch Management (\"Organizing and maintaining separate lines of development (branches) within a repository.\")."}, {"obj": "1.8", "q": "Given the description \"Adjusting the size/type of provisioned resources to match actual workload demand.\", which term is being defined?", "c": ["Resource Metering", "Rightsizing", "Tagging", "Reserved Resources"], "a": 1, "e": "\"Adjusting the size/type of provisioned resources to match actual workload demand.\" describes Rightsizing. Prevents overspending on oversized resources while avoiding performance issues from undersized ones."}, {"obj": "1.10", "q": "Given the description \"Using containers as the compute resource type for a workload.\", which term is being defined?", "c": ["Network Throughput", "Network Latency", "Compute Optimization (VM)", "Compute Optimization (Container)"], "a": 3, "e": "\"Using containers as the compute resource type for a workload.\" describes Compute Optimization (Container). More lightweight and portable than VMs, ideal for microservices and rapid scaling."}, {"obj": "4.5", "q": "An administrator explains the importance of a concept: \"Detects and blocks malicious activity at the individual system level.\" What concept is this?", "c": ["DDoS Protection", "DLP", "IPS/IDS", "Endpoint Protection"], "a": 3, "e": "Detects and blocks malicious activity at the individual system level. This describes Endpoint Protection (\"Security software (antivirus, EDR) installed directly on servers, VMs, or devices.\")."}, {"obj": "6.1", "q": "Given the description \"A deployment failure or performance problem caused by choosing an inappropriately sized resource.\", which term is being defined?", "c": ["Partial Outage", "Outdated Component Definitions", "Sizing Issues", "Permission Issues (Deployment)"], "a": 2, "e": "\"A deployment failure or performance problem caused by choosing an inappropriately sized resource.\" describes Sizing Issues. Both undersizing (poor performance) and oversizing (wasted cost) are common sizing mistakes."}, {"obj": "1.2", "q": "Which statement accurately describes \"RPO\"?", "c": ["Temporarily extending an on-premises workload into the public cloud to handle demand spikes.", "Recovery Point Objective — the maximum acceptable amount of data loss, measured in time.", "Processing data physically close to where it is generated rather than in a centralized datacenter.", "Using services from more than one public cloud provider simultaneously."], "a": 1, "e": "Recovery Point Objective — the maximum acceptable amount of data loss, measured in time. A tight RPO requires frequent backups or synchronous replication; a looser RPO allows infrequent backups."}, {"obj": "1.10", "q": "Which of the following terms fits this definition: \"Automated coordination of workload deployment, scaling, and lifecycle management.\"?", "c": ["Orchestration (Workload)", "Compute Optimization (Container)", "Network Latency", "Network Throughput"], "a": 0, "e": "\"Automated coordination of workload deployment, scaling, and lifecycle management.\" describes Orchestration (Workload). Ensures workloads are placed, scaled, and healed automatically according to defined policies."}, {"obj": "4.6", "q": "Why does this matter on the exam and in practice? \"Provides the raw visibility needed to detect an attack in progress.\" — which term does this explain?", "c": ["Ransomware", "Event Monitoring (Security)", "Cryptojacking", "DDoS"], "a": 1, "e": "Provides the raw visibility needed to detect an attack in progress. This describes Event Monitoring (Security) (\"Continuously observing system and security events for signs of malicious activity.\")."}, {"obj": "4.2", "q": "In cloud computing terminology, \"SOC2\" refers to which of the following?", "c": ["Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted).", "Systems and Organization Controls 2 — an audit framework evaluating a service provider's controls around security, availability, and confidentiality.", "A legal requirement to preserve specific data because it may be relevant to pending litigation.", "The principle that data is subject to the laws of the country in which it is physically located."], "a": 1, "e": "Systems and Organization Controls 2 — an audit framework evaluating a service provider's controls around security, availability, and confidentiality. A common compliance report requested by customers evaluating a cloud vendor's security posture."}, {"obj": "1.11", "q": "Given the description \"AI technology that extracts text from images or scanned documents (OCR).\", which term is being defined?", "c": ["IoT Gateway", "Generative AI", "Text Recognition", "IoT Communication"], "a": 2, "e": "\"AI technology that extracts text from images or scanned documents (OCR).\" describes Text Recognition. Used to digitize and search paper documents or extract data from images automatically."}, {"obj": "1.4", "q": "A performance-sensitive application requires fast random I/O for many small transactions. Which storage media is most appropriate?", "c": ["HDD", "SSD", "Magnetic tape", "Archive tier object storage"], "a": 1, "e": "SSDs have no moving parts and provide much faster random I/O than HDDs, suiting transaction-heavy, performance-sensitive workloads."}, {"obj": "1.4", "q": "A company mistakenly stores frequently accessed production data in the archive tier to save costs. What is the most likely operational consequence?", "c": ["No consequence; archive tier performs identically to hot tier", "Significantly degraded performance and higher retrieval latency/cost for frequent access", "Data will be automatically deleted", "The data becomes permanently inaccessible"], "a": 1, "e": "Archive tier storage is optimized for rare access with slow retrieval times; using it for frequently accessed data causes significant performance and cost problems."}, {"obj": "2.2", "q": "Which deployment strategy would be most appropriate for a large fleet of stateless web servers where gradual, incremental updates with continuous availability are prioritized over the fastest possible rollback?", "c": ["In-place deployment on all servers at once", "Rolling deployment", "A canary deployment targeting only internal test users forever", "No deployment strategy is needed"], "a": 1, "e": "Rolling deployment fits large stateless fleets well, incrementally updating instances while keeping the service available throughout, though full rollout takes longer than blue-green."}, {"obj": "2.3", "q": "Which concept is described by the phrase: \"Moving workloads from local infrastructure into a cloud environment.\"?", "c": ["Cloud-to-On-Premises Migration", "Retire", "On-Premises-to-Cloud Migration", "Rehost"], "a": 2, "e": "\"Moving workloads from local infrastructure into a cloud environment.\" describes On-Premises-to-Cloud Migration. The most common migration type when organizations first adopt cloud computing."}, {"obj": "4.4", "q": "Given the description \"Encrypting stored data so it remains unreadable without the correct key.\", which term is being defined?", "c": ["Data at Rest Encryption", "Zero Trust", "API Security", "File Storage Security"], "a": 0, "e": "\"Encrypting stored data so it remains unreadable without the correct key.\" describes Data at Rest Encryption. Protects data even if the underlying storage media is stolen or improperly accessed."}, {"obj": "6.2", "q": "In cloud computing terminology, \"Network Overlap\" refers to which of the following?", "c": ["Dynamic Host Configuration Protocol — automatically assigns IP addressing information to hosts.", "Two networks using conflicting/duplicate IP address ranges.", "Running out of available addresses within a defined IP range or subnet.", "Network Address Translation — translates private addresses to a public address for routing."], "a": 1, "e": "Two networks using conflicting/duplicate IP address ranges. Commonly causes routing failures when connecting previously separate networks (e.g., via VPN or peering)."}, {"obj": "1.7", "q": "Which term is most closely associated with this real-world importance: \"Fast and simple but doesn't support live migration of VMs to other hosts without shared storage.\"?", "c": ["Local Storage (Virtualization)", "Stand-Alone Virtualization", "Overlay Network", "VM Network"], "a": 0, "e": "Fast and simple but doesn't support live migration of VMs to other hosts without shared storage. This describes Local Storage (Virtualization) (\"Storage physically attached to a single hypervisor host.\")."}, {"obj": "5.3", "q": "A retailer's inventory service publishes a single event whenever stock changes, and any interested downstream service can subscribe independently, without the inventory service needing to know who's listening. What pattern does this best illustrate?", "c": ["Tight, synchronous coupling", "Event-driven fan-out", "A rigid SOAP contract", "A direct RPC call chain"], "a": 1, "e": "Publishing an event without needing to know the specific subscribers is a hallmark of event-driven, loosely coupled fan-out integration."}, {"obj": "5.2", "q": "Which of the following would be considered part of 'CI/CD security' rather than a general pipeline stage?", "c": ["Compiling source code into an artifact", "Running an automated dependency vulnerability scan before allowing deployment", "Merging a pull request", "Tagging a release version"], "a": 1, "e": "Running an automated vulnerability scan specifically incorporates security checks into the pipeline, which is the definition of CI/CD security as distinct from general build/merge/tag operations."}, {"obj": "5.4", "q": "Which of the following best describes why a team might choose Terraform over manually clicking through a cloud console to provision resources?", "c": ["Terraform requires more manual steps than a console", "Terraform provides declarative, version-controlled, repeatable infrastructure provisioning across environments and providers", "Terraform can only be used for a single cloud provider", "Terraform eliminates the need for any testing"], "a": 1, "e": "Terraform's declarative, version-controlled approach makes infrastructure provisioning repeatable and consistent, unlike ad hoc manual console clicks."}, {"obj": "3.2", "q": "An administrator explains the importance of a concept: \"Simpler than horizontal scaling but has an upper limit and usually requires downtime or a reboot.\" What concept is this?", "c": ["Vertical Scaling", "Triggered Scaling — Event", "Triggered Scaling — Trending", "Scheduled Scaling"], "a": 0, "e": "Simpler than horizontal scaling but has an upper limit and usually requires downtime or a reboot. This describes Vertical Scaling (\"Increasing the resources (CPU/RAM) of an existing instance (scale up).\")."}, {"obj": "4.2", "q": "A company's contract with a major customer requires that support ticket data be retained for 5 years, even though the company's internal policy would normally delete it after 2 years. What type of retention requirement is this?", "c": ["Regulatory retention", "Contractual retention", "Litigation hold", "Data sovereignty"], "a": 1, "e": "Contractual retention is a data retention requirement specified in a contract with a customer or partner, which may extend beyond internal default policies."}, {"obj": "6.2", "q": "A description reads: \"Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500).\" Which term does this describe?", "c": ["Access vs. Trunk Ports", "HTTP Status Codes", "Misconfigured Route", "DHCP (Troubleshooting)"], "a": 1, "e": "\"Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500).\" describes HTTP Status Codes. Provide the first clue about whether a problem is client-side, server-side, or related to routing/access."}, {"obj": "5.1", "q": "In cloud computing terminology, \"Pull Request\" refers to which of the following?", "c": ["A formal request to merge a proposed code change into a shared branch, typically triggering review.", "Tracking and organizing different versions of code or configuration over time.", "Combining changes from different branches into one.", "Saving a snapshot of changes to the local version control history."], "a": 0, "e": "A formal request to merge a proposed code change into a shared branch, typically triggering review. The standard workflow mechanism for reviewing and discussing changes before merging."}, {"obj": "2.4", "q": "A team's IaC pipeline automatically runs a linter and a security scanner against every proposed infrastructure change before it can be merged. What is this process an example of?", "c": ["Drift detection", "IaC testing", "Configuration as Code without any validation", "Manual provisioning"], "a": 1, "e": "Running automated linting and security scans against proposed IaC changes before merge is a form of IaC testing, catching issues before deployment."}, {"obj": "6.2", "q": "Authentication between a client and a Kerberos-based service intermittently fails, and investigation reveals the two systems' clocks differ by several minutes. What service should be checked?", "c": ["NTP", "DNS", "NAT", "DHCP"], "a": 0, "e": "Kerberos authentication is highly sensitive to time differences between systems; correcting NTP synchronization typically resolves this class of failure."}, {"obj": "1.10", "q": "Which term best matches this description: \"Automated coordination of workload deployment, scaling, and lifecycle management.\"?", "c": ["Orchestration (Workload)", "Storage Throughput", "Compute Optimization (Container)", "IOPS (Optimization)"], "a": 0, "e": "\"Automated coordination of workload deployment, scaling, and lifecycle management.\" describes Orchestration (Workload). Ensures workloads are placed, scaled, and healed automatically according to defined policies."}, {"obj": "5.3", "q": "An administrator explains the importance of a concept: \"Enables loose coupling and scalability, common in cloud-native and microservices designs.\" What concept is this?", "c": ["Event-Driven Architecture", "REST", "SOAP", "GraphQL"], "a": 0, "e": "Enables loose coupling and scalability, common in cloud-native and microservices designs. This describes Event-Driven Architecture (\"A design where components communicate by producing and reacting to events rather than direct calls.\")."}, {"obj": "3.3", "q": "Which of the following best describes \"Parallel Recovery\"?", "c": ["Encrypting backup data so it remains protected even if the storage media or files are exposed.", "How long backup copies are kept before being deleted or overwritten.", "Restoring data to an alternate system running alongside the original.", "Restoring data directly onto the original system/location."], "a": 2, "e": "Restoring data to an alternate system running alongside the original. Useful for testing a restore or recovering without disrupting the still-running original system."}, {"obj": "1.10", "q": "Which of the following best describes \"Orchestration (Workload)\"?", "c": ["Automated coordination of workload deployment, scaling, and lifecycle management.", "Using virtual machines as the compute resource type for a workload.", "A defined sequence of automated steps/tasks that process data or coordinate resources.", "Using Function as a Service as the compute resource type for a workload."], "a": 0, "e": "Automated coordination of workload deployment, scaling, and lifecycle management. Ensures workloads are placed, scaled, and healed automatically according to defined policies."}, {"obj": "1.2", "q": "How would you most accurately define \"Multicloud Tenancy\"?", "c": ["Using services from more than one public cloud provider simultaneously.", "Processing data physically close to where it is generated rather than in a centralized datacenter.", "Continuously checking that a resource or service is up and responding as expected.", "A partially equipped DR site that needs recent data restored before it can take over."], "a": 0, "e": "Using services from more than one public cloud provider simultaneously. Reduces vendor lock-in and can improve resilience, but increases operational and integration complexity."}, {"obj": "1.3", "q": "How would you most accurately define \"VPC Peering\"?", "c": ["A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers).", "A logical subdivision of a network's IP address range.", "A direct network connection between two VPCs that allows them to communicate as if on the same network.", "A device or service that filters network traffic based on defined rules."], "a": 2, "e": "A direct network connection between two VPCs that allows them to communicate as if on the same network. Enables private communication between separate VPCs without routing traffic over the public internet."}, {"obj": "2.5", "q": "A workload processes highly sensitive healthcare data and must remain within a specific country's borders. What requirement is driving the resource provisioning decision?", "c": ["Performance requirements", "Compliance requirements", "Cost requirements", "Availability requirements"], "a": 1, "e": "Compliance requirements can dictate region/provider choice due to legal or regulatory obligations governing data location."}, {"obj": "2.4", "q": "Why does this matter on the exam and in practice? \"Catches errors before they cause an outage or misconfiguration in production.\" — which term does this explain?", "c": ["YAML", "Drift Detection", "JSON", "IaC Testing"], "a": 3, "e": "Catches errors before they cause an outage or misconfiguration in production. This describes IaC Testing (\"Validating infrastructure code for syntax, security, and logic before it is applied to real environments.\")."}, {"obj": "4.6", "q": "How would you most accurately define \"Malware\"?", "c": ["Unauthorized use of a system's computing resources to mine cryptocurrency.", "A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email.", "Malicious software designed to damage, disrupt, or gain unauthorized access to a system.", "A departure from a system's established normal behavior pattern."], "a": 2, "e": "Malicious software designed to damage, disrupt, or gain unauthorized access to a system. A broad category of threats requiring layered defenses like endpoint protection and patching."}, {"obj": "1.7", "q": "Select the most accurate description of \"NAS (Virtualization Context)\":", "c": ["A virtual network built on top of physical network infrastructure, common in virtualization and containers.", "A rule keeping specific VMs running on the same (or different) physical host.", "Network Attached Storage — shared file-level storage accessible by multiple hosts.", "Storage physically attached to a single hypervisor host."], "a": 2, "e": "Network Attached Storage — shared file-level storage accessible by multiple hosts. Commonly used for storing VM templates, ISOs, and shared datastores."}, {"obj": "4.3", "q": "Which statement accurately describes \"RDP\"?", "c": ["Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.", "A hardened server that provides a single, monitored entry point for administrative access into a private network.", "A chronological record of who did what, and when, within a system.", "Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties."], "a": 0, "e": "Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system. The standard way to remotely access Windows-based cloud instances."}, {"obj": "1.10", "q": "A team wants to reduce operational overhead for a workload currently running on self-managed VMs performing routine, well-understood tasks like caching. What optimization approach should they consider?", "c": ["Switching to a fully self-managed on-premises deployment", "Migrating to a provider-managed service to reduce operational burden", "Increasing the VM count without reviewing utilization", "Disabling all monitoring to reduce noise"], "a": 1, "e": "Migrating well-understood, standard functionality like caching to a managed service reduces the operational burden of self-managing routine infrastructure."}, {"obj": "5.2", "q": "A colleague says: \"The standard choice for proprietary source code and internal build artifacts.\" Which concept are they describing?", "c": ["CI/CD Automation", "Build (CI/CD)", "CI/CD Security", "Private Repository"], "a": 3, "e": "The standard choice for proprietary source code and internal build artifacts. This describes Private Repository (\"A code or artifact repository restricted to authorized users/systems.\")."}, {"obj": "2.4", "q": "Which term best matches this description: \"Validating infrastructure code for syntax, security, and logic before it is applied to real environments.\"?", "c": ["Drift Detection", "Infrastructure as Code", "Configuration as Code", "IaC Testing"], "a": 3, "e": "\"Validating infrastructure code for syntax, security, and logic before it is applied to real environments.\" describes IaC Testing. Catches errors before they cause an outage or misconfiguration in production."}, {"obj": "3.2", "q": "Which scaling approach typically requires a brief service interruption or reboot to apply, unlike adding new parallel instances?", "c": ["Horizontal scaling", "Vertical scaling", "Event-triggered scaling", "Scheduled scaling"], "a": 1, "e": "Vertical scaling usually requires resizing (and often restarting) an existing instance, unlike horizontal scaling which can add new instances without disrupting existing ones."}, {"obj": "3.1", "q": "An operations team receives 200 alerts overnight and must quickly determine which represent a genuine emergency requiring immediate action versus which can wait until morning. What process are they performing?", "c": ["Log aggregation", "Alert triage", "Distributed tracing", "Log retention"], "a": 1, "e": "Alert triage reviews and prioritizes incoming alerts by urgency, which is essential for preventing alert fatigue and focusing on true emergencies first."}, {"obj": "1.7", "q": "Which of the following terms fits this definition: \"Storage physically attached to a single hypervisor host.\"?", "c": ["Local Storage (Virtualization)", "Overlay Network", "Clustering", "VM Network"], "a": 0, "e": "\"Storage physically attached to a single hypervisor host.\" describes Local Storage (Virtualization). Fast and simple but doesn't support live migration of VMs to other hosts without shared storage."}, {"obj": "5.4", "q": "Given the description \"A widely used open-source automation server for building CI/CD pipelines.\", which term is being defined?", "c": ["Jenkins", "Git", "Terraform", "ELK Stack"], "a": 0, "e": "\"A widely used open-source automation server for building CI/CD pipelines.\" describes Jenkins. One of the most established tools for orchestrating build, test, and deployment automation."}, {"obj": "4.4", "q": "Which term best matches this description: \"Access controls and encryption applied to shared file storage systems.\"?", "c": ["Container File Access Permissions", "Zero Trust", "File Storage Security", "API Security"], "a": 2, "e": "\"Access controls and encryption applied to shared file storage systems.\" describes File Storage Security. Ensures only authorized users/systems can read or modify shared file data."}, {"obj": "1.9", "q": "A colleague says: \"Reduces administrative burden significantly, letting teams focus on the data and application instead of the database engine.\" Which concept are they describing?", "c": ["Non-Relational Database", "Provider-Managed Database", "Relational Database", "Self-Managed Database"], "a": 1, "e": "Reduces administrative burden significantly, letting teams focus on the data and application instead of the database engine. This describes Provider-Managed Database (\"A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS).\")."}, {"obj": "6.2", "q": "Select the most accurate description of \"Protocol Deprecation\":", "c": ["The distinction between a switch port carrying a single VLAN (access) versus multiple VLANs (trunk).", "A connectivity failure caused by a system relying on a protocol version the other side no longer supports.", "Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500).", "Dynamic Host Configuration Protocol — automatically assigns IP addressing information to hosts."], "a": 1, "e": "A connectivity failure caused by a system relying on a protocol version the other side no longer supports. Highlights the need to track and update deprecated protocol usage before it causes an outage."}, {"obj": "5.2", "q": "Which statement accurately describes \"Debian Package\"?", "c": ["The defined sequence of automated stages a change passes through from commit to deployment.", "A package format (.deb) used for installing software on Debian-based Linux distributions.", "A simple, unstructured file (like a config or script) produced or consumed by a pipeline.", "A packaged virtual machine image produced and stored as a build output."], "a": 1, "e": "A package format (.deb) used for installing software on Debian-based Linux distributions. The counterpart to RPM packages on Debian/Ubuntu-based systems."}, {"obj": "3.3", "q": "Select the most accurate description of \"Backup Recoverability Testing\":", "c": ["Restoring individual files or specific data items rather than an entire dataset.", "How long backup copies are kept before being deleted or overwritten.", "Backs up only data changed since the last backup of any type.", "Actually restoring backup data to confirm it can be used successfully."], "a": 3, "e": "Actually restoring backup data to confirm it can be used successfully. A backup reporting \"success\" does not guarantee the data is truly restorable — testing closes that gap."}, {"obj": "1.4", "q": "Select the most accurate description of \"Object Storage\":", "c": ["Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB).", "Storage that manages data as discrete objects with metadata, accessed via an API (e.g., S3).", "Hard Disk Drive — traditional magnetic spinning-platter storage.", "The lowest-cost storage tier, designed for rarely accessed data with the slowest retrieval times (sometimes hours)."], "a": 1, "e": "Storage that manages data as discrete objects with metadata, accessed via an API (e.g., S3). Highly scalable and durable, ideal for unstructured data like backups, media, and static web content."}, {"obj": "5.2", "q": "A colleague says: \"Shifts security left, catching vulnerabilities earlier and cheaper than after deployment.\" Which concept are they describing?", "c": ["Flat File Artifact", "CI/CD Security", "RPM Package", "CI/CD Automation"], "a": 1, "e": "Shifts security left, catching vulnerabilities earlier and cheaper than after deployment. This describes CI/CD Security (\"Incorporating security scanning and checks into the automated pipeline.\")."}, {"obj": "4.1", "q": "Which concept is described by the phrase: \"Evaluating identified vulnerabilities for severity, exploitability, and business impact.\"?", "c": ["CVE", "Remediation", "Scanning Scope", "Vulnerability Assessment"], "a": 3, "e": "\"Evaluating identified vulnerabilities for severity, exploitability, and business impact.\" describes Vulnerability Assessment. Helps prioritize which vulnerabilities to remediate first based on actual risk."}, {"obj": "1.7", "q": "Which statement accurately describes \"Host Affinity\"?", "c": ["A single hypervisor host running VMs with no clustering.", "A virtual network built on top of physical network infrastructure, common in virtualization and containers.", "Storage physically attached to a single hypervisor host.", "A rule keeping specific VMs running on the same (or different) physical host."], "a": 3, "e": "A rule keeping specific VMs running on the same (or different) physical host. Used to keep related VMs together for performance, or apart for redundancy (anti-affinity)."}, {"obj": "6.1", "q": "A team's deployment pipeline fails with an error indicating the account has reached its maximum allowed number of load balancers. What should the team do?", "c": ["Ignore the error since it will resolve itself", "Request a quota increase from the provider or reduce the number of load balancers needed", "Switch to a completely different cloud provider immediately", "Disable all monitoring to hide the error"], "a": 1, "e": "Reaching a service quota limit typically requires requesting an increase from the provider or reducing the resource footprint to fit within the existing quota."}, {"obj": "1.11", "q": "How would you most accurately define \"Voice-to-Text\"?", "c": ["A device that aggregates and relays data from multiple IoT sensors to the cloud.", "AI technology that identifies objects, scenes, or features within images or video.", "AI models that create new content (text, images, code) based on learned patterns.", "AI technology that converts spoken audio into written text (speech recognition)."], "a": 3, "e": "AI technology that converts spoken audio into written text (speech recognition). Powers transcription services, voice assistants, and accessibility features."}, {"obj": "4.2", "q": "How would you most accurately define \"ISO 27001\"?", "c": ["Requirements or preferences about the physical location where data is stored or processed.", "A legal requirement to preserve specific data because it may be relevant to pending litigation.", "Defining who legally owns and controls a given set of data.", "An international standard specifying requirements for an information security management system."], "a": 3, "e": "An international standard specifying requirements for an information security management system. A widely recognized certification demonstrating a structured approach to information security."}, {"obj": "1.10", "q": "How would you most accurately define \"Managed Services (Optimization)\"?", "c": ["The actual amount of data successfully transferred over a network connection in a given time.", "Automated coordination of workload deployment, scaling, and lifecycle management.", "Using provider-operated services instead of self-managed infrastructure to reduce operational overhead.", "Using Function as a Service as the compute resource type for a workload."], "a": 2, "e": "Using provider-operated services instead of self-managed infrastructure to reduce operational overhead. Frees up staff time from routine maintenance so they can focus on higher-value work."}, {"obj": "6.2", "q": "An administrator explains the importance of a concept: \"Commonly causes routing failures when connecting previously separate networks (e.g., via VPN or peering).\" What concept is this?", "c": ["NTP (Troubleshooting)", "Network Overlap", "Missing Route", "Misconfigured Route"], "a": 1, "e": "Commonly causes routing failures when connecting previously separate networks (e.g., via VPN or peering). This describes Network Overlap (\"Two networks using conflicting/duplicate IP address ranges.\")."}, {"obj": "2.1", "q": "Select the most accurate description of \"Public Cloud\":", "c": ["Infrastructure physically located and managed within the organization's own facilities.", "Infrastructure owned by a third-party provider and shared across many customers (multi-tenant).", "Infrastructure dedicated to a single organization, hosted on- or off-premises.", "A deployment model combining private/on-premises infrastructure with public cloud resources."], "a": 1, "e": "Infrastructure owned by a third-party provider and shared across many customers (multi-tenant). Lowest upfront cost and fastest to provision, but less control than private cloud."}, {"obj": "6.1", "q": "An administrator explains the importance of a concept: \"One of the most common causes of failed automated deployments in cloud environments.\" What concept is this?", "c": ["Full Outage", "Permission Issues (Deployment)", "Regional Service Availability", "API Throttling"], "a": 1, "e": "One of the most common causes of failed automated deployments in cloud environments. This describes Permission Issues (Deployment) (\"A deployment failing because the deploying identity lacks sufficient rights.\")."}, {"obj": "6.3", "q": "A description reads: \"Access to a system or data by someone without proper permission.\" Which term does this describe?", "c": ["Leaked Credentials", "Cipher Suite Deprecation", "Unauthorized Access", "Privilege Escalation (Troubleshooting)"], "a": 2, "e": "\"Access to a system or data by someone without proper permission.\" describes Unauthorized Access. The core security incident type that access controls, logging, and monitoring are designed to catch."}, {"obj": "1.4", "q": "Select the most accurate description of \"Hot Storage Tier\":", "c": ["Storage that manages data as discrete objects with metadata, accessed via an API (e.g., S3).", "Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk.", "A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost.", "Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB)."], "a": 2, "e": "A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost. Appropriate for active production data that needs to be retrieved quickly and often."}, {"obj": "3.4", "q": "A description reads: \"A smaller update, typically with bug fixes and small improvements.\" Which term does this describe?", "c": ["Decommissioning — End of Support", "Patch", "Minor Update", "Decommissioning — End of Life"], "a": 2, "e": "\"A smaller update, typically with bug fixes and small improvements.\" describes Minor Update. Generally lower risk than major updates but should still be tested before production rollout."}, {"obj": "1.2", "q": "Which of the following best describes \"Cold Site\"?", "c": ["Recovery Point Objective — the maximum acceptable amount of data loss, measured in time.", "A distinct geographic location where a cloud provider operates one or more datacenters.", "A basic facility with power and space but no pre-installed equipment.", "A partially equipped DR site that needs recent data restored before it can take over."], "a": 2, "e": "A basic facility with power and space but no pre-installed equipment. Cheapest DR option, but has by far the longest time to bring online."}, {"obj": "6.3", "q": "A company's TLS handshake failures increase sharply right after they disable support for an older cipher suite fleet-wide as part of a security hardening initiative. What should the team do?", "c": ["Re-enable the insecure cipher suite indefinitely to stop the failures", "Identify and upgrade the specific legacy clients causing the failures, since they need to support current ciphers", "Disable TLS entirely across the fleet", "Ignore the failures since they are unrelated to the change"], "a": 1, "e": "Rather than reverting to an insecure cipher suite, the correct response is to identify and upgrade the legacy clients that can't yet support the current, more secure ciphers."}, {"obj": "5.1", "q": "Which statement accurately describes \"Code Review\"?", "c": ["Having other team members examine proposed code changes before they are merged.", "Tracking and organizing different versions of code or configuration over time.", "Uploading local code changes to a remote/shared repository.", "A formal request to merge a proposed code change into a shared branch, typically triggering review."], "a": 0, "e": "Having other team members examine proposed code changes before they are merged. Catches bugs, security issues, and design problems before they reach production."}, {"obj": "4.5", "q": "Which of the following terms fits this definition: \"Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data.\"?", "c": ["IAM Policies", "Network ACL", "DLP", "IPS/IDS"], "a": 2, "e": "\"Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data.\" describes DLP. Commonly blocks sensitive data like credit card numbers from leaving the network through channels like email."}, {"obj": "1.8", "q": "Which statement accurately describes \"Spot Instance\"?", "c": ["A billing model charging only for actual resource consumption, with no upfront commitment.", "Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice.", "A billing model where a customer pays for an entire physical host, regardless of utilization.", "Pre-purchasing capacity for a discounted rate in exchange for a committed term."], "a": 1, "e": "Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice. Ideal for fault-tolerant, interruptible workloads like batch processing, but not suitable for critical always-on services."}, {"obj": "6.2", "q": "Which of the following best describes \"HTTP Status Codes\"?", "c": ["A required network path that has not been defined in a route table.", "Domain Name System — resolves hostnames to IP addresses.", "Running out of available addresses within a defined IP range or subnet.", "Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500)."], "a": 3, "e": "Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500). Provide the first clue about whether a problem is client-side, server-side, or related to routing/access."}, {"obj": "3.4", "q": "Which of the following best distinguishes ephemeral data from persistent data in terms of backup strategy?", "c": ["Ephemeral data requires the same rigorous backup and retention as persistent data", "Ephemeral data generally does not require the same backup/retention rigor since it doesn't need to survive beyond its immediate use", "Persistent data never needs to be backed up", "There is no meaningful difference between the two for backup purposes"], "a": 1, "e": "Since ephemeral data is temporary by design, it typically doesn't warrant the same backup and retention investment as persistent data representing lasting business value."}, {"obj": "2.2", "q": "Which of the following terms fits this definition: \"Updating instances incrementally, a few at a time, rather than all at once.\"?", "c": ["Blue-Green Deployment", "Canary Deployment", "In-Place Deployment", "Rolling Deployment"], "a": 3, "e": "\"Updating instances incrementally, a few at a time, rather than all at once.\" describes Rolling Deployment. Keeps the application available throughout the deployment, at the cost of a longer overall rollout window."}, {"obj": "3.4", "q": "\"Ephemeral Data\" is best defined as which of the following?", "c": ["Retiring a resource because it has reached the end of its useful life or support.", "Data that must be retained beyond the life of the process or instance that created it.", "Temporary data that does not need to persist beyond a session or process.", "A software update addressing a specific bug or vulnerability."], "a": 2, "e": "Temporary data that does not need to persist beyond a session or process. Doesn't require the same backup/retention rigor as persistent data."}, {"obj": "1.11", "q": "How would you most accurately define \"IoT Transmission Protocol\"?", "c": ["Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case.", "AI technology that extracts text from images or scanned documents (OCR).", "Lightweight protocols (like MQTT or CoAP) designed for constrained IoT devices and networks.", "AI technology that converts written text into spoken audio (speech synthesis)."], "a": 2, "e": "Lightweight protocols (like MQTT or CoAP) designed for constrained IoT devices and networks. Optimized for low bandwidth and power use, unlike heavier traditional web protocols."}, {"obj": "5.1", "q": "Which concept is described by the phrase: \"Combining changes from different branches into one.\"?", "c": ["Code Commit", "Code Push", "Code Merge", "Version Management"], "a": 2, "e": "\"Combining changes from different branches into one.\" describes Code Merge. Integrates parallel work from multiple developers or feature branches."}, {"obj": "4.2", "q": "A colleague says: \"A widely recognized certification demonstrating a structured approach to information security.\" Which concept are they describing?", "c": ["ISO 27001", "SOC2", "Cloud Security Alliance", "Contractual Retention"], "a": 0, "e": "A widely recognized certification demonstrating a structured approach to information security. This describes ISO 27001 (\"An international standard specifying requirements for an information security management system.\")."}, {"obj": "5.1", "q": "Which of the following best describes \"Code Review\"?", "c": ["A formal request to merge a proposed code change into a shared branch, typically triggering review.", "Combining changes from different branches into one.", "Having other team members examine proposed code changes before they are merged.", "Saving a snapshot of changes to the local version control history."], "a": 2, "e": "Having other team members examine proposed code changes before they are merged. Catches bugs, security issues, and design problems before they reach production."}, {"obj": "4.6", "q": "Which statement accurately describes \"Malware\"?", "c": ["An attack that succeeds because a system was running software with a known, unpatched vulnerability.", "Malware that encrypts a victim's data and demands payment for the decryption key.", "Continuously observing system and security events for signs of malicious activity.", "Malicious software designed to damage, disrupt, or gain unauthorized access to a system."], "a": 3, "e": "Malicious software designed to damage, disrupt, or gain unauthorized access to a system. A broad category of threats requiring layered defenses like endpoint protection and patching."}, {"obj": "2.1", "q": "Which concept is described by the phrase: \"Infrastructure owned by a third-party provider and shared across many customers (multi-tenant).\"?", "c": ["Community Cloud", "On Premises", "Hybrid Cloud", "Public Cloud"], "a": 3, "e": "\"Infrastructure owned by a third-party provider and shared across many customers (multi-tenant).\" describes Public Cloud. Lowest upfront cost and fastest to provision, but less control than private cloud."}, {"obj": "4.6", "q": "A description reads: \"Unauthorized use of a system's computing resources to mine cryptocurrency.\" Which term does this describe?", "c": ["Deviation from Baseline", "Cryptojacking", "Vulnerability Exploitation — Outdated Software", "Event Monitoring (Security)"], "a": 1, "e": "\"Unauthorized use of a system's computing resources to mine cryptocurrency.\" describes Cryptojacking. Often detected through unexplained high CPU usage and increased cloud compute costs."}, {"obj": "4.2", "q": "Which concept is described by the phrase: \"A legal requirement to preserve specific data because it may be relevant to pending litigation.\"?", "c": ["PCI DSS", "Litigation Hold", "Cloud Security Alliance", "Contractual Retention"], "a": 1, "e": "\"A legal requirement to preserve specific data because it may be relevant to pending litigation.\" describes Litigation Hold. Overrides normal retention/deletion schedules until the hold is lifted."}, {"obj": "1.11", "q": "A company deploys an AI writing assistant that drafts entire email replies based on a brief description of what the user wants to say. What category of AI service is this?", "c": ["Text recognition", "Generative AI", "IoT transmission protocol", "Visual recognition"], "a": 1, "e": "An AI service that generates new content like full email drafts from short prompts is an example of generative AI."}, {"obj": "1.3", "q": "Which concept is described by the phrase: \"A manually configured network route that does not change dynamically.\"?", "c": ["CDN", "Subnet", "Static Route", "Application Gateway"], "a": 2, "e": "\"A manually configured network route that does not change dynamically.\" describes Static Route. Simple and predictable, but requires manual updates if the network topology changes."}, {"obj": "5.4", "q": "A team needs to build, package, and run applications in lightweight, portable containers on their local machines and in production. Which tool is the standard choice?", "c": ["Ansible", "Docker", "Grafana", "Jenkins"], "a": 1, "e": "Docker is the most widely used platform for building, running, and managing containers, providing the container runtime and image format."}, {"obj": "5.4", "q": "Which term is most closely associated with this real-world importance: \"Commonly paired with time-series databases to build real-time operational dashboards.\"?", "c": ["Terraform", "GitHub Actions", "Ansible", "Grafana"], "a": 3, "e": "Commonly paired with time-series databases to build real-time operational dashboards. This describes Grafana (\"An open-source tool for visualizing metrics and creating monitoring dashboards.\")."}, {"obj": "1.3", "q": "Which statement accurately describes \"VPC Peering\"?", "c": ["A direct network connection between two VPCs that allows them to communicate as if on the same network.", "A device or service that filters network traffic based on defined rules.", "Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.", "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port."], "a": 0, "e": "A direct network connection between two VPCs that allows them to communicate as if on the same network. Enables private communication between separate VPCs without routing traffic over the public internet."}, {"obj": "1.3", "q": "An architect needs a Layer 7 solution that combines load balancing, SSL termination, and basic web application filtering into a single ingress point for a web app. What should be deployed?", "c": ["A network load balancer", "An application gateway", "A static route table", "A VPC peering connection"], "a": 1, "e": "An application gateway typically combines Layer 7 load balancing, SSL termination, and WAF-style features into a unified ingress point."}, {"obj": "3.1", "q": "Which of the following best describes \"Log Retention\"?", "c": ["The defined actions taken once an alert is triaged and confirmed to need action.", "Numeric measurements of system behavior (CPU, memory, request rate) collected over time.", "Combining logs from many sources into a unified, searchable view.", "Defining how long log data is kept before being archived or deleted."], "a": 3, "e": "Defining how long log data is kept before being archived or deleted. Balances storage cost against the need to investigate older incidents or meet compliance requirements."}, {"obj": "3.3", "q": "A team wants to test whether a backup can actually be restored without disrupting the still-running original production system. What recovery approach allows this?", "c": ["In-place recovery directly onto production", "Parallel recovery to an alternate system running alongside production", "Bulk recovery only", "Granular recovery of unrelated files"], "a": 1, "e": "Parallel recovery restores data to an alternate system running alongside the original, allowing validation of a restore without disrupting the still-running production system."}, {"obj": "1.11", "q": "Which term best matches this description: \"AI technology that converts spoken audio into written text (speech recognition).\"?", "c": ["Voice-to-Text", "Machine Learning", "Text Recognition", "Generative AI"], "a": 0, "e": "\"AI technology that converts spoken audio into written text (speech recognition).\" describes Voice-to-Text. Powers transcription services, voice assistants, and accessibility features."}, {"obj": "4.5", "q": "An organization wants to block emails containing what appear to be customer credit card numbers from leaving the company network. What control should be deployed?", "c": ["DLP", "WAF", "IDS", "Network security group"], "a": 0, "e": "DLP detects and blocks unauthorized transmission of sensitive data such as credit card numbers leaving via email."}, {"obj": "4.1", "q": "Select the most accurate description of \"Vulnerability Assessment\":", "c": ["Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities.", "Evaluating identified vulnerabilities for severity, exploitability, and business impact.", "The step of detecting known weaknesses in systems, typically via automated scanning.", "Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability."], "a": 1, "e": "Evaluating identified vulnerabilities for severity, exploitability, and business impact. Helps prioritize which vulnerabilities to remediate first based on actual risk."}, {"obj": "4.3", "q": "Which concept is described by the phrase: \"Granting permissions to a group, which members inherit by being added to that group.\"?", "c": ["Group-Based Access Control", "SDK", "Token-Based Authentication", "CLI"], "a": 0, "e": "\"Granting permissions to a group, which members inherit by being added to that group.\" describes Group-Based Access Control. Similar to RBAC but organized around groups rather than formally defined roles."}, {"obj": "1.9", "q": "An application stores highly structured order data with strict relationships between customers, orders, and line items, requiring complex joins. Which database type fits best?", "c": ["Non-relational database", "Relational database", "Object storage", "File storage"], "a": 1, "e": "Relational databases are designed for structured data with defined relationships and support complex SQL queries and joins."}, {"obj": "4.5", "q": "An administrator explains the importance of a concept: \"Essential for internet-facing cloud services that could otherwise be overwhelmed by attack traffic.\" What concept is this?", "c": ["IAM Policies", "Endpoint Protection", "DDoS Protection", "Network ACL"], "a": 2, "e": "Essential for internet-facing cloud services that could otherwise be overwhelmed by attack traffic. This describes DDoS Protection (\"Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic.\")."}, {"obj": "3.1", "q": "In cloud computing terminology, \"Log Collection\" refers to which of the following?", "c": ["The defined actions taken once an alert is triaged and confirmed to need action.", "The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.", "Combining logs from many sources into a unified, searchable view.", "Gathering log data from applications, systems, and services into a central location."], "a": 3, "e": "Gathering log data from applications, systems, and services into a central location. The first step in observability — without collection, logs remain scattered and hard to analyze."}, {"obj": "1.4", "q": "An application requires the lowest possible storage cost per gigabyte for a large, less performance-sensitive archive dataset. Which drive type is typically most cost-effective?", "c": ["SSD", "HDD", "NVMe SSD", "In-memory cache"], "a": 1, "e": "HDDs offer a lower cost per gigabyte than SSDs, making them more economical for large, less performance-sensitive datasets."}, {"obj": "1.3", "q": "A company has 15 VPCs and 3 on-premises sites that all need to interconnect, and manually configuring peering between every pair has become unmanageable. What should be implemented?", "c": ["Additional VPC peering connections for every new pair", "A transit gateway acting as a central hub", "A single static route shared by all VPCs", "A CDN in front of every VPC"], "a": 1, "e": "A transit gateway centralizes connectivity for many VPCs and on-premises networks through one hub, avoiding an unmanageable full-mesh of peering connections."}, {"obj": "6.2", "q": "What does the abbreviation \"DNS\" stand for?", "c": ["Security, Trust, Assurance, Risk", "Domain Name System", "Random Access Memory", "Logical Unit Number"], "a": 1, "e": "DNS stands for Domain Name System. Resolves human-readable hostnames to IP addresses."}, {"obj": "2.1", "q": "Several regional hospitals want to share cloud infrastructure that meets a common set of healthcare compliance requirements, without opening it to the general public. Which deployment model fits?", "c": ["Public cloud", "Private cloud", "Community cloud", "Hybrid cloud"], "a": 2, "e": "A community cloud is shared among organizations with common concerns, such as shared healthcare compliance requirements in this case."}, {"obj": "2.2", "q": "A colleague says: \"Simpler but riskier than blue-green since there is no separate environment to instantly roll back to.\" Which concept are they describing?", "c": ["Canary Deployment", "Rolling Deployment", "In-Place Deployment", "Blue-Green Deployment"], "a": 2, "e": "Simpler but riskier than blue-green since there is no separate environment to instantly roll back to. This describes In-Place Deployment (\"Updating an existing server or instance directly rather than deploying an entirely new one.\")."}, {"obj": "5.2", "q": "Why does this matter on the exam and in practice? \"Documents and enforces a consistent, repeatable delivery process.\" — which term does this explain?", "c": ["Private Repository", "CI/CD Workflow", "Flat File Artifact", "RPM Package"], "a": 1, "e": "Documents and enforces a consistent, repeatable delivery process. This describes CI/CD Workflow (\"The defined sequence of automated stages a change passes through from commit to deployment.\")."}, {"obj": "4.1", "q": "A security team reviews a list of newly identified vulnerabilities and ranks them by exploitability and potential business impact before deciding what to fix first. What step is this?", "c": ["Vulnerability identification", "Vulnerability assessment", "Remediation", "Scanning scope definition"], "a": 1, "e": "Assessment evaluates identified vulnerabilities for severity and impact, which drives prioritization before remediation begins."}, {"obj": "6.2", "q": "\"Missing Route\" is best defined as which of the following?", "c": ["Running out of available addresses within a defined IP range or subnet.", "Network Time Protocol — synchronizes system clocks across a network.", "Incorrect VLAN tagging causing traffic to be dropped or delivered to the wrong segment.", "A required network path that has not been defined in a route table."], "a": 3, "e": "A required network path that has not been defined in a route table. Traffic destined for that path is silently dropped, a common and often overlooked cloud networking issue."}, {"obj": "1.4", "q": "Which storage characteristic makes SSDs generally more reliable than HDDs in environments with vibration or physical movement?", "c": ["SSDs have larger storage capacities", "SSDs have no moving mechanical parts", "SSDs are always cheaper", "SSDs require less electrical power in all cases"], "a": 1, "e": "The absence of moving mechanical parts (like spinning platters) makes SSDs more resistant to vibration-related failures than HDDs."}, {"obj": "4.4", "q": "A help desk technician is granted only the specific permissions needed to reset passwords, rather than full administrative rights across the environment. What principle does this reflect?", "c": ["Zero Trust", "Principle of least privilege", "API security", "Secrets management"], "a": 1, "e": "Least privilege grants only the minimum access rights needed to perform a function, limiting potential damage if that account is compromised or misused."}, {"obj": "6.1", "q": "Select the most accurate description of \"Deprecation of Functionality\":", "c": ["Incorrectly assigned CPU, memory, or storage limits for a workload.", "A previously available feature or API being retired by the provider.", "Allocating more virtual resources than the underlying physical capacity can truly support.", "A deployment failure or performance problem caused by choosing an inappropriately sized resource."], "a": 1, "e": "A previously available feature or API being retired by the provider. Deployments relying on deprecated functionality will eventually fail and must be updated proactively."}, {"obj": "1.10", "q": "Which of the following best describes \"Network Throughput\"?", "c": ["The actual amount of data successfully transferred over a network connection in a given time.", "The time delay for data to travel between two points on a network.", "Using Function as a Service as the compute resource type for a workload.", "A defined sequence of automated steps/tasks that process data or coordinate resources."], "a": 0, "e": "The actual amount of data successfully transferred over a network connection in a given time. Determines whether a network link can support a workload's data transfer needs."}, {"obj": "1.9", "q": "A company needs to store highly structured customer order data with strict relationships between customers, orders, and products, requiring complex multi-table joins. Which database type fits best?", "c": ["A non-relational key-value store", "A relational database", "Object storage", "A document store with no schema"], "a": 1, "e": "Relational databases are designed for structured data with defined relationships and support complex SQL joins across tables."}, {"obj": "1.2", "q": "In cloud computing terminology, \"RTO\" refers to which of the following?", "c": ["Continuously checking that a resource or service is up and responding as expected.", "An isolated location within a region with independent power, cooling, and networking.", "A distinct geographic location where a cloud provider operates one or more datacenters.", "Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption."], "a": 3, "e": "Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption. Drives the choice of DR site type and how much automation/investment is needed to meet the target."}, {"obj": "1.3", "q": "An administrator explains the importance of a concept: \"Used for advanced routing scenarios like connecting on-premises networks to the cloud via dedicated connections.\" What concept is this?", "c": ["CDN", "Firewall", "BGP", "VLAN"], "a": 2, "e": "Used for advanced routing scenarios like connecting on-premises networks to the cloud via dedicated connections. This describes BGP (\"Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.\")."}, {"obj": "4.2", "q": "Which of the following terms fits this definition: \"Payment Card Industry Data Security Standard — security requirements for handling payment card data.\"?", "c": ["Contractual Retention", "PCI DSS", "Data Sovereignty", "Data Locality"], "a": 1, "e": "\"Payment Card Industry Data Security Standard — security requirements for handling payment card data.\" describes PCI DSS. Any cloud workload that stores, processes, or transmits card data must meet these requirements."}, {"obj": "3.4", "q": "Given the description \"A significant version update that may include new features and breaking changes.\", which term is being defined?", "c": ["Patch", "Ephemeral Data", "Decommissioning — End of Life", "Major Update"], "a": 3, "e": "\"A significant version update that may include new features and breaking changes.\" describes Major Update. Requires more careful testing than minor updates due to a higher risk of compatibility issues."}, {"obj": "1.9", "q": "In cloud computing terminology, \"Provider-Managed Database\" refers to which of the following?", "c": ["A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs.", "A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS).", "A database that organizes data into structured tables with defined relationships (SQL).", "A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure."], "a": 1, "e": "A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS). Reduces administrative burden significantly, letting teams focus on the data and application instead of the database engine."}, {"obj": "5.2", "q": "Given the description \"Compiling/packaging source code into a deployable artifact.\", which term is being defined?", "c": ["VM Image Artifact", "Container Image Artifact", "RPM Package", "Build (CI/CD)"], "a": 3, "e": "\"Compiling/packaging source code into a deployable artifact.\" describes Build (CI/CD). The step that transforms source code into something that can actually be run or deployed."}, {"obj": "4.2", "q": "An administrator explains the importance of a concept: \"A common compliance report requested by customers evaluating a cloud vendor's security posture.\" What concept is this?", "c": ["Data Classification", "ISO 27001", "Data Ownership", "SOC2"], "a": 3, "e": "A common compliance report requested by customers evaluating a cloud vendor's security posture. This describes SOC2 (\"Systems and Organization Controls 2 — an audit framework evaluating a service provider's controls around security, availability, and confidentiality.\")."}, {"obj": "3.3", "q": "How would you most accurately define \"Backup Integrity Testing\"?", "c": ["How long backup copies are kept before being deleted or overwritten.", "Verifying that backed-up data has not been corrupted.", "Restoring individual files or specific data items rather than an entire dataset.", "Restoring a large set of data all at once."], "a": 1, "e": "Verifying that backed-up data has not been corrupted. Ensures the backup itself is trustworthy before it's ever relied upon during an actual incident."}, {"obj": "2.5", "q": "An architect calculates the expected CPU and RAM needs of a new application before selecting an instance size. What category of requirement are they addressing?", "c": ["Compliance requirements", "Compute requirements", "Availability requirements", "Network requirements"], "a": 1, "e": "Compute requirements define the processing power (CPU, RAM) needed to run a workload effectively, directly informing instance size selection."}, {"obj": "1.3", "q": "Why does this matter on the exam and in practice? \"Underpins most cloud networking, allowing networks to be defined and changed through code/APIs rather than physical rewiring.\" — which term does this explain?", "c": ["VPN", "Firewall", "SDN", "VLAN"], "a": 2, "e": "Underpins most cloud networking, allowing networks to be defined and changed through code/APIs rather than physical rewiring. This describes SDN (\"Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management.\")."}, {"obj": "1.3", "q": "A colleague says: \"Provides a single ingress point for web applications with built-in security and traffic-shaping features.\" Which concept are they describing?", "c": ["Transit Gateway", "VPN", "Application Gateway", "SDN"], "a": 2, "e": "Provides a single ingress point for web applications with built-in security and traffic-shaping features. This describes Application Gateway (\"A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features.\")."}, {"obj": "4.3", "q": "An administrator explains the importance of a concept: \"Similar to RBAC but organized around groups rather than formally defined roles.\" What concept is this?", "c": ["Group-Based Access Control", "Audit Trail", "Token-Based Authentication", "RDP"], "a": 0, "e": "Similar to RBAC but organized around groups rather than formally defined roles. This describes Group-Based Access Control (\"Granting permissions to a group, which members inherit by being added to that group.\")."}, {"obj": "1.11", "q": "Which of the following best describes \"Visual Recognition\"?", "c": ["Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case.", "A device that collects data from the physical environment (temperature, motion, etc.).", "AI technology that identifies objects, scenes, or features within images or video.", "A device that aggregates and relays data from multiple IoT sensors to the cloud."], "a": 2, "e": "AI technology that identifies objects, scenes, or features within images or video. Powers use cases like content moderation, quality inspection, and security monitoring."}, {"obj": "4.1", "q": "Which of the following best describes \"Vulnerability Assessment\"?", "c": ["Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability.", "The step of detecting known weaknesses in systems, typically via automated scanning.", "Evaluating identified vulnerabilities for severity, exploitability, and business impact.", "Defining which systems, networks, or applications a vulnerability scan will cover."], "a": 2, "e": "Evaluating identified vulnerabilities for severity, exploitability, and business impact. Helps prioritize which vulnerabilities to remediate first based on actual risk."}, {"obj": "5.1", "q": "After committing changes locally, a developer uploads those commits to the shared team repository so others can see and build on them. What action is this?", "c": ["A code commit", "A code push", "A code review", "A branch deletion"], "a": 1, "e": "A code push uploads local committed changes to a remote/shared repository, sharing them with the rest of the team."}, {"obj": "6.1", "q": "A deployment consistently fails with a resource allocation error stating that the requested memory configuration is invalid for the selected instance family. What is the most likely cause?", "c": ["A resource allocation misconfiguration mismatching memory settings with the chosen instance type", "API throttling", "Regional service availability", "A full outage"], "a": 0, "e": "An invalid combination of requested resources (like memory) for a specific instance family points to a resource allocation misconfiguration in the deployment request."}, {"obj": "4.2", "q": "Which concept is described by the phrase: \"Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted).\"?", "c": ["Data Classification", "SOC2", "ISO 27001", "Litigation Hold"], "a": 0, "e": "\"Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted).\" describes Data Classification. Drives how strictly a given piece of data must be protected and handled."}, {"obj": "6.2", "q": "Given the description \"Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500).\", which term is being defined?", "c": ["HTTP Status Codes", "IP Scope Exhaustion", "DNS (Troubleshooting)", "NAT (Troubleshooting)"], "a": 0, "e": "\"Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500).\" describes HTTP Status Codes. Provide the first clue about whether a problem is client-side, server-side, or related to routing/access."}, {"obj": "1.2", "q": "A description reads: \"Processing data physically close to where it is generated rather than in a centralized datacenter.\" Which term does this describe?", "c": ["Availability Zone", "Hot Site", "Edge Computing", "Availability Monitoring"], "a": 2, "e": "\"Processing data physically close to where it is generated rather than in a centralized datacenter.\" describes Edge Computing. Reduces latency for time-sensitive applications like IoT and content delivery."}, {"obj": "2.3", "q": "How would you most accurately define \"Retire\"?", "c": ["A migration strategy that decommissions an application no longer needed.", "A migration strategy that rewrites portions of an application to better fit cloud-native patterns.", "Moving workloads out of the cloud back to local infrastructure.", "A migration strategy that keeps a workload where it currently is, deferring migration."], "a": 0, "e": "A migration strategy that decommissions an application no longer needed. Reduces the overall migration scope and ongoing costs by eliminating unnecessary systems."}, {"obj": "5.4", "q": "Which term best matches this description: \"A CI/CD automation feature built into GitHub for running workflows in response to repository events.\"?", "c": ["Git", "GitHub Actions", "Docker", "Terraform"], "a": 1, "e": "\"A CI/CD automation feature built into GitHub for running workflows in response to repository events.\" describes GitHub Actions. Lets teams define build/test/deploy pipelines directly alongside their code in GitHub."}, {"obj": "4.6", "q": "An administrator explains the importance of a concept: \"Provides the raw visibility needed to detect an attack in progress.\" What concept is this?", "c": ["Zombie Instance", "Event Monitoring (Security)", "DDoS", "Ransomware"], "a": 1, "e": "Provides the raw visibility needed to detect an attack in progress. This describes Event Monitoring (Security) (\"Continuously observing system and security events for signs of malicious activity.\")."}, {"obj": "2.2", "q": "Which of the following best describes the primary risk-mitigation benefit of canary deployments?", "c": ["They guarantee zero downtime under all circumstances", "They limit the impact of a bad release to a small subset of users/traffic before a full rollout", "They eliminate the need for monitoring entirely", "They always cost less than any other deployment strategy"], "a": 1, "e": "Canary deployments limit exposure to a bad release by testing it on a small fraction of traffic first, reducing the overall impact if problems are found."}, {"obj": "2.3", "q": "After a period in the cloud, a company decides that a specific latency-sensitive workload performs and costs better running locally, and moves it back to their own datacenter. What type of migration is this?", "c": ["On-premises-to-cloud migration", "Cloud-to-on-premises migration", "Cloud-to-cloud migration", "Retire"], "a": 1, "e": "Cloud-to-on-premises migration moves workloads out of the cloud back to local infrastructure, sometimes chosen for performance or cost reasons."}, {"obj": "4.3", "q": "Given the description \"Multifactor Authentication — requiring two or more independent verification factors to log in.\", which term is being defined?", "c": ["Group-Based Access Control", "MFA", "OpenID Connect", "Web Portal"], "a": 1, "e": "\"Multifactor Authentication — requiring two or more independent verification factors to log in.\" describes MFA. Makes stolen credentials alone insufficient for an attacker to gain access."}, {"obj": "4.2", "q": "A colleague says: \"Determines which region a workload must be deployed in to satisfy legal requirements.\" Which concept are they describing?", "c": ["ISO 27001", "Contractual Retention", "SOC2", "Data Sovereignty"], "a": 3, "e": "Determines which region a workload must be deployed in to satisfy legal requirements. This describes Data Sovereignty (\"The principle that data is subject to the laws of the country in which it is physically located.\")."}, {"obj": "1.10", "q": "Which term best matches this description: \"The rate of data transfer to/from a storage system, usually measured in MB/s or GB/s.\"?", "c": ["Orchestration (Workload)", "IOPS (Optimization)", "Workflow (Optimization)", "Storage Throughput"], "a": 3, "e": "\"The rate of data transfer to/from a storage system, usually measured in MB/s or GB/s.\" describes Storage Throughput. Important for workloads that move large volumes of data, like backups or media processing."}, {"obj": "3.2", "q": "How would you most accurately define \"Triggered Scaling — Load\"?", "c": ["Scaling in response to a specific event (like a message queue depth increasing).", "Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU).", "Increasing the resources (CPU/RAM) of an existing instance (scale up).", "Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%)."], "a": 3, "e": "Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%). The most common autoscaling trigger, reacting quickly to current demand."}, {"obj": "1.3", "q": "Which of the following is the correct expansion of \"SSL\"?", "c": ["Real-time Messaging Protocol", "Data Loss Prevention", "Secure Sockets Layer", "Software as a Service"], "a": 2, "e": "SSL stands for Secure Sockets Layer. The predecessor to TLS for encrypting network communications, now largely deprecated."}, {"obj": "2.4", "q": "An administrator explains the importance of a concept: \"The preferred format for tools like Kubernetes manifests and many CI/CD pipeline definitions.\" What concept is this?", "c": ["Infrastructure as Code", "Configuration as Code", "Drift Detection", "YAML"], "a": 3, "e": "The preferred format for tools like Kubernetes manifests and many CI/CD pipeline definitions. This describes YAML (\"Yet Another Markup Language — a human-readable data format widely used for IaC and configuration files.\")."}, {"obj": "3.3", "q": "An administrator explains the importance of a concept: \"Protects against a disaster affecting the primary backup location.\" What concept is this?", "c": ["Parallel Recovery", "Differential Backup", "Backup Replication", "Full Backup"], "a": 2, "e": "Protects against a disaster affecting the primary backup location. This describes Backup Replication (\"Copying backup data to another location (often off-site or another region).\")."}, {"obj": "6.1", "q": "Which of the following terms fits this definition: \"A deployment failing because the deploying identity lacks sufficient rights.\"?", "c": ["Service Quota", "Resource Allocation Misconfiguration", "Permission Issues (Deployment)", "Deprecation of Functionality"], "a": 2, "e": "\"A deployment failing because the deploying identity lacks sufficient rights.\" describes Permission Issues (Deployment). One of the most common causes of failed automated deployments in cloud environments."}, {"obj": "1.3", "q": "Which term is most closely associated with this real-world importance: \"Provides extremely high throughput and low latency for use cases where Layer 7 inspection isn't needed.\"?", "c": ["Subnet", "VPN", "Static Route", "Network Load Balancer"], "a": 3, "e": "Provides extremely high throughput and low latency for use cases where Layer 7 inspection isn't needed. This describes Network Load Balancer (\"A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port.\")."}, {"obj": "4.4", "q": "Which of the following is the correct expansion of \"AES\"?", "c": ["Information Technology Infrastructure Library", "Platform as a Service", "Advanced Encryption Standard", "Single Sign-On"], "a": 2, "e": "AES stands for Advanced Encryption Standard. The current industry-standard symmetric block cipher used to encrypt data at rest and in transit."}, {"obj": "6.2", "q": "An organization's addressing scheme has run out of available IPs to assign new instances within a subnet. What is this called?", "c": ["IP scope exhaustion", "Network overlap", "Protocol incompatibility", "Missing route"], "a": 0, "e": "IP scope exhaustion means the available address range has been fully consumed, blocking new provisioning until it's expanded."}, {"obj": "4.4", "q": "A description reads: \"Access controls and encryption applied to shared file storage systems.\" Which term does this describe?", "c": ["Object Storage Security", "Container File Access Permissions", "API Security", "File Storage Security"], "a": 3, "e": "\"Access controls and encryption applied to shared file storage systems.\" describes File Storage Security. Ensures only authorized users/systems can read or modify shared file data."}, {"obj": "2.2", "q": "Given the description \"A strategy running two identical environments (blue and green), switching traffic to the new version once verified.\", which term is being defined?", "c": ["Canary Deployment", "Rolling Deployment", "In-Place Deployment", "Blue-Green Deployment"], "a": 3, "e": "\"A strategy running two identical environments (blue and green), switching traffic to the new version once verified.\" describes Blue-Green Deployment. Allows near-instant rollback by simply switching traffic back to the previous environment."}, {"obj": "5.1", "q": "A team keeps a long-lived 'main' branch always in a deployable state, while all new work happens in short-lived feature branches merged in via pull request. What practice does this reflect?", "c": ["Ignoring branch management entirely", "A disciplined branch management strategy supporting stable releases", "Skipping code review to move faster", "Avoiding version control altogether"], "a": 1, "e": "Maintaining a stable main branch while isolating new work in feature branches is a disciplined branch management strategy that supports reliable, deployable releases."}, {"obj": "2.4", "q": "Which of the following best describes \"JSON\"?", "c": ["Managing system or application configuration through code rather than manual configuration.", "Identifying when a deployed resource's actual state no longer matches its defined IaC configuration.", "JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates.", "Yet Another Markup Language — a human-readable data format widely used for IaC and configuration files."], "a": 2, "e": "JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates. One of the two dominant data formats used to define cloud resources declaratively."}, {"obj": "2.3", "q": "Which statement accurately describes \"Retain\"?", "c": ["A migration strategy that rewrites portions of an application to better fit cloud-native patterns.", "A migration strategy that keeps a workload where it currently is, deferring migration.", "Moving workloads from local infrastructure into a cloud environment.", "A migration strategy that substantially redesigns an application to be cloud-native."], "a": 1, "e": "A migration strategy that keeps a workload where it currently is, deferring migration. Appropriate for applications not yet ready or not worth migrating due to cost or complexity."}, {"obj": "4.5", "q": "In Cloud+ terminology, \"IDS\" is an abbreviation for which of the following?", "c": ["Application Programming Interface", "General Data Protection Regulation", "Intrusion Detection System", "Common Weakness Scoring System"], "a": 2, "e": "IDS stands for Intrusion Detection System. Monitors network or host activity for signs of an attack without blocking it."}, {"obj": "3.3", "q": "\"Backup Retention (Ops)\" is best defined as which of the following?", "c": ["Restoring data directly onto the original system/location.", "Restoring data to an alternate system running alongside the original.", "Restoring individual files or specific data items rather than an entire dataset.", "How long backup copies are kept before being deleted or overwritten."], "a": 3, "e": "How long backup copies are kept before being deleted or overwritten. Balances storage cost against the need to recover from an issue discovered after some delay."}, {"obj": "5.2", "q": "Which concept is described by the phrase: \"Releasing built and tested code to a target environment (e.g., production).\"?", "c": ["CI/CD Workflow", "CI/CD Testing", "Code Deployment", "Build (CI/CD)"], "a": 2, "e": "\"Releasing built and tested code to a target environment (e.g., production).\" describes Code Deployment. The \"CD\" in CI/CD — automating this step reduces the risk and effort of releasing changes."}, {"obj": "4.2", "q": "Which concept is described by the phrase: \"An organization that publishes best practices and frameworks specifically for cloud security.\"?", "c": ["Cloud Security Alliance", "SOC2", "ISO 27001", "Contractual Retention"], "a": 0, "e": "\"An organization that publishes best practices and frameworks specifically for cloud security.\" describes Cloud Security Alliance. Provides cloud-specific guidance (like the CCM) that general security standards may not fully address."}, {"obj": "5.4", "q": "How would you most accurately define \"GitHub Actions\"?", "c": ["An open-source tool for visualizing metrics and creating monitoring dashboards.", "An open-source, agentless automation tool used for configuration management and orchestration.", "An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively.", "A CI/CD automation feature built into GitHub for running workflows in response to repository events."], "a": 3, "e": "A CI/CD automation feature built into GitHub for running workflows in response to repository events. Lets teams define build/test/deploy pipelines directly alongside their code in GitHub."}, {"obj": "3.4", "q": "An administrator explains the importance of a concept: \"Reduces the risk that a routine update introduces a new production issue.\" What concept is this?", "c": ["Decommissioning — End of Support", "Major Update", "Minor Update", "Lifecycle Testing"], "a": 3, "e": "Reduces the risk that a routine update introduces a new production issue. This describes Lifecycle Testing (\"Validating changes (patches, updates, configuration) before applying them broadly.\")."}, {"obj": "1.9", "q": "In cloud computing terminology, \"Self-Managed Database\" refers to which of the following?", "c": ["A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS).", "A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs.", "A database that organizes data into structured tables with defined relationships (SQL).", "A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure."], "a": 3, "e": "A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure. Offers maximum control but requires the customer to handle all operational overhead."}, {"obj": "5.1", "q": "A developer accidentally commits a hardcoded API key to their feature branch. What source control practice would most likely catch this before it reaches the main branch?", "c": ["Branch management alone", "Code review as part of the pull request process", "Deleting all commit history", "Disabling version control"], "a": 1, "e": "Code review during the pull request process is well positioned to catch issues like hardcoded secrets before the change is merged into the shared codebase."}, {"obj": "6.1", "q": "Which statement accurately describes \"Incompatibility (Deployment)\"?", "c": ["The fact that not all cloud services are available in every region.", "IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated.", "A provider intentionally limiting the rate of API calls a customer can make.", "A failure caused by mismatched software, hardware, or configuration versions."], "a": 3, "e": "A failure caused by mismatched software, hardware, or configuration versions. A very common root cause of failed deployments, especially after an update to one dependency."}, {"obj": "4.4", "q": "A company applies access controls and encryption specifically to its shared file storage system used by multiple application servers. What practice is this an example of?", "c": ["Object storage security", "File storage security", "API security", "Zero Trust for containers"], "a": 1, "e": "Applying access controls and encryption to shared file storage systems is specifically file storage security, ensuring only authorized users/systems can read or modify shared data."}, {"obj": "1.11", "q": "A colleague says: \"Underpins many modern cloud AI services such as recommendation engines and fraud detection.\" Which concept are they describing?", "c": ["Visual Recognition", "Machine Learning", "IoT Communication", "Voice-to-Text"], "a": 1, "e": "Underpins many modern cloud AI services such as recommendation engines and fraud detection. This describes Machine Learning (\"Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case.\")."}, {"obj": "2.3", "q": "A company moves an application to the cloud with no code changes, simply relocating the VMs as-is. What migration strategy is this?", "c": ["Re-architect", "Rehost", "Refactor", "Retire"], "a": 1, "e": "Rehost (\"lift and shift\") moves an application with minimal changes, the fastest but least cloud-optimized migration strategy."}, {"obj": "1.2", "q": "Why does this matter on the exam and in practice? \"Lets an organization keep steady-state workloads on cheaper private infrastructure while still handling peak load.\" — which term does this explain?", "c": ["Cold Site", "Availability Monitoring", "Cloud Bursting", "Availability Zone"], "a": 2, "e": "Lets an organization keep steady-state workloads on cheaper private infrastructure while still handling peak load. This describes Cloud Bursting (\"Temporarily extending an on-premises workload into the public cloud to handle demand spikes.\")."}, {"obj": "4.4", "q": "A company applies a vendor-neutral, consensus-based hardening checklist to all of its cloud VM images before deployment. What resource are they most likely using?", "c": ["A CVE database", "A CIS Benchmark", "A litigation hold notice", "An OAuth 2.0 specification"], "a": 1, "e": "CIS Benchmarks provide vendor-neutral, consensus-based configuration hardening guidelines widely adopted for exactly this kind of baseline hardening."}, {"obj": "6.3", "q": "IT discovers an employee installed an unapproved remote-access tool on their workstation, bypassing normal corporate security policy. What is this called?", "c": ["Cipher suite deprecation", "Unauthorized software", "Leaked credentials", "IP scope exhaustion"], "a": 1, "e": "Unauthorized software is software installed or running without proper approval, increasing risk and potentially violating policy, exactly matching this scenario."}, {"obj": "6.2", "q": "A colleague says: \"A failed DHCP service can leave hosts without any usable network configuration.\" Which concept are they describing?", "c": ["DHCP (Troubleshooting)", "DNS (Troubleshooting)", "Misconfigured Route", "Protocol Incompatibility"], "a": 0, "e": "A failed DHCP service can leave hosts without any usable network configuration. This describes DHCP (Troubleshooting) (\"Dynamic Host Configuration Protocol — automatically assigns IP addressing information to hosts.\")."}, {"obj": "3.4", "q": "A cloud resource has reached the point where the organization no longer has a business need for it, and the team plans its retirement, including data migration or retention as needed. What lifecycle stage is this?", "c": ["End of support", "End of life", "A minor update", "Lifecycle testing"], "a": 1, "e": "End of life describes retiring a resource because it has reached the end of its useful life or is no longer needed, requiring planning for data handling before removal."}, {"obj": "5.4", "q": "In cloud computing terminology, \"ELK Stack\" refers to which of the following?", "c": ["An open-source, agentless automation tool used for configuration management and orchestration.", "A CI/CD automation feature built into GitHub for running workflows in response to repository events.", "An open-source tool for visualizing metrics and creating monitoring dashboards.", "Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization."], "a": 3, "e": "Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization. A widely used open-source stack for centralized logging and observability."}, {"obj": "6.1", "q": "An administrator explains the importance of a concept: \"Still requires prompt attention but may allow more measured troubleshooting than a full outage.\" What concept is this?", "c": ["Incompatibility (Deployment)", "API Throttling", "Permission Issues (Deployment)", "Partial Outage"], "a": 3, "e": "Still requires prompt attention but may allow more measured troubleshooting than a full outage. This describes Partial Outage (\"A degradation where some, but not all, functionality or users are affected.\")."}, {"obj": "1.3", "q": "Which of the following is the correct expansion of \"SDN\"?", "c": ["Software-defined Network", "Internet Service Provider", "Advanced Encryption Standard", "OpenID Connect Protocol"], "a": 0, "e": "SDN stands for Software-defined Network. Decouples the network control plane from the physical data plane for programmatic management."}, {"obj": "1.4", "q": "A description reads: \"A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost.\" Which term does this describe?", "c": ["Hot Storage Tier", "Object Storage", "SSD", "File Storage"], "a": 0, "e": "\"A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost.\" describes Hot Storage Tier. Appropriate for active production data that needs to be retrieved quickly and often."}, {"obj": "4.3", "q": "An administrator explains the importance of a concept: \"Simplifies calling cloud provider APIs from within application code.\" What concept is this?", "c": ["Directory-Based Authentication", "SDK", "Audit Trail", "API (IAM Context)"], "a": 1, "e": "Simplifies calling cloud provider APIs from within application code. This describes SDK (\"Software Development Kit — a set of libraries/tools that let developers programmatically interact with a cloud platform.\")."}, {"obj": "3.2", "q": "A company's database cannot be horizontally scaled easily due to its architecture, so during peak load the team temporarily increases its instance size. What scaling approach are they using, and what is its main limitation?", "c": ["Horizontal scaling; unlimited scalability", "Vertical scaling; limited by the maximum available instance size", "Scheduled scaling; requires no monitoring", "Event-triggered scaling; requires a message queue"], "a": 1, "e": "Vertical scaling increases resources of the existing instance but is capped by the largest instance size the provider offers, unlike horizontal scaling's more open-ended growth."}, {"obj": "4.3", "q": "Given the description \"Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.\", which term is being defined?", "c": ["RDP", "API (IAM Context)", "Role-Based Access Control", "SDK"], "a": 0, "e": "\"Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.\" describes RDP. The standard way to remotely access Windows-based cloud instances."}, {"obj": "3.4", "q": "Which statement accurately describes \"Persistent Data\"?", "c": ["A smaller update, typically with bug fixes and small improvements.", "Data that must be retained beyond the life of the process or instance that created it.", "Validating changes (patches, updates, configuration) before applying them broadly.", "A software update addressing a specific bug or vulnerability."], "a": 1, "e": "Data that must be retained beyond the life of the process or instance that created it. Requires durable storage and appropriate backup strategy since it represents lasting business value."}, {"obj": "1.2", "q": "A description reads: \"A partially equipped DR site that needs recent data restored before it can take over.\" Which term does this describe?", "c": ["RTO", "Edge Computing", "Cloud Bursting", "Warm Site"], "a": 3, "e": "\"A partially equipped DR site that needs recent data restored before it can take over.\" describes Warm Site. A middle-ground between cost and recovery speed compared to hot and cold sites."}, {"obj": "4.5", "q": "How would you most accurately define \"Network ACL\"?", "c": ["Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications.", "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data.", "Access Control List — a set of rules controlling traffic in and out of a subnet at the network level.", "Rules that define what actions a given identity is allowed or denied to perform on cloud resources."], "a": 2, "e": "Access Control List — a set of rules controlling traffic in and out of a subnet at the network level. Operates at the subnet/network level, distinct from security group/instance-level rules."}, {"obj": "4.2", "q": "In Cloud+ terminology, \"GDPR\" is an abbreviation for which of the following?", "c": ["Multifactor Authentication", "General Data Protection Regulation", "Intrusion Detection System", "Network Time Protocol"], "a": 1, "e": "GDPR stands for General Data Protection Regulation. EU regulation governing the protection of personal data and privacy."}, {"obj": "1.9", "q": "Why does this matter on the exam and in practice? \"Offers maximum control but requires the customer to handle all operational overhead.\" — which term does this explain?", "c": ["Relational Database", "Provider-Managed Database", "Self-Managed Database", "Non-Relational Database"], "a": 2, "e": "Offers maximum control but requires the customer to handle all operational overhead. This describes Self-Managed Database (\"A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure.\")."}, {"obj": "4.1", "q": "Select the most accurate description of \"Vulnerability Identification\":", "c": ["Defining which systems, networks, or applications a vulnerability scan will cover.", "Evaluating identified vulnerabilities for severity, exploitability, and business impact.", "The step of detecting known weaknesses in systems, typically via automated scanning.", "Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities."], "a": 2, "e": "The step of detecting known weaknesses in systems, typically via automated scanning. The first concrete step in the vulnerability management lifecycle, feeding into assessment and remediation."}, {"obj": "3.2", "q": "A database server is running low on capacity, so an administrator increases its CPU and RAM allocation rather than adding another database instance. What scaling approach is this?", "c": ["Horizontal scaling", "Vertical scaling", "Scheduled scaling", "Event-triggered scaling"], "a": 1, "e": "Vertical scaling increases the resources of an existing instance (scale up), as opposed to horizontal scaling which adds more instances."}, {"obj": "1.2", "q": "Which of the following terms fits this definition: \"A distinct geographic location where a cloud provider operates one or more datacenters.\"?", "c": ["Cloud Bursting", "Hot Site", "Region", "RPO"], "a": 2, "e": "\"A distinct geographic location where a cloud provider operates one or more datacenters.\" describes Region. Choosing the right region affects latency, data sovereignty, and compliance."}, {"obj": "2.3", "q": "A company migrates a database from its self-managed VM to a cloud provider's managed database service, while keeping the application's core logic largely unchanged. What migration strategy is this?", "c": ["Rehost", "Replatform", "Retire", "Retain"], "a": 1, "e": "Replatforming makes some optimizations (like adopting a managed database) to leverage cloud capabilities without fully redesigning the core application architecture."}, {"obj": "1.2", "q": "An administrator explains the importance of a concept: \"Cheapest DR option, but has by far the longest time to bring online.\" What concept is this?", "c": ["Hot Site", "RPO", "Availability Monitoring", "Cold Site"], "a": 3, "e": "Cheapest DR option, but has by far the longest time to bring online. This describes Cold Site (\"A basic facility with power and space but no pre-installed equipment.\")."}, {"obj": "6.1", "q": "\"Deprecation of Functionality\" is best defined as which of the following?", "c": ["A previously available feature or API being retired by the provider.", "A complete loss of service availability.", "IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated.", "A provider-imposed limit on how many of a given resource type can be provisioned."], "a": 0, "e": "A previously available feature or API being retired by the provider. Deployments relying on deprecated functionality will eventually fail and must be updated proactively."}, {"obj": "4.3", "q": "\"Bastion Host\" is best defined as which of the following?", "c": ["Granting permissions based on a user's assigned role rather than to each individual directly.", "A hardened server that provides a single, monitored entry point for administrative access into a private network.", "Application Programming Interface — used here for programmatic management/access to cloud resources.", "Multifactor Authentication — requiring two or more independent verification factors to log in."], "a": 1, "e": "A hardened server that provides a single, monitored entry point for administrative access into a private network. Reduces the attack surface by ensuring administrative access doesn't require directly exposing every resource."}, {"obj": "4.3", "q": "Which term is most closely associated with this real-world importance: \"Simplifies administration and enforces consistent access across users with the same job function.\"?", "c": ["Role-Based Access Control", "SAML", "Local User Authentication", "Group-Based Access Control"], "a": 0, "e": "Simplifies administration and enforces consistent access across users with the same job function. This describes Role-Based Access Control (\"Granting permissions based on a user's assigned role rather than to each individual directly.\")."}, {"obj": "3.4", "q": "How would you most accurately define \"Ephemeral Data\"?", "c": ["Data that must be retained beyond the life of the process or instance that created it.", "Retiring or upgrading a resource because the vendor no longer provides support/patches for it.", "A significant version update that may include new features and breaking changes.", "Temporary data that does not need to persist beyond a session or process."], "a": 3, "e": "Temporary data that does not need to persist beyond a session or process. Doesn't require the same backup/retention rigor as persistent data."}, {"obj": "1.2", "q": "Which term is most closely associated with this real-world importance: \"Spreading resources across AZs protects against a single datacenter failure without the latency of a different region.\"?", "c": ["Availability Monitoring", "Availability Zone", "Cold Site", "Multicloud Tenancy"], "a": 1, "e": "Spreading resources across AZs protects against a single datacenter failure without the latency of a different region. This describes Availability Zone (\"An isolated location within a region with independent power, cooling, and networking.\")."}, {"obj": "3.1", "q": "Which statement accurately describes \"Monitoring Metrics\"?", "c": ["Gathering log data from applications, systems, and services into a central location.", "Numeric measurements of system behavior (CPU, memory, request rate) collected over time.", "Following a single request as it moves through multiple services in a distributed system.", "Defining how long log data is kept before being archived or deleted."], "a": 1, "e": "Numeric measurements of system behavior (CPU, memory, request rate) collected over time. The foundation of dashboards and alerting used to understand system health."}, {"obj": "4.4", "q": "An administrator explains the importance of a concept: \"Misconfigured object storage permissions are a very common real-world cause of public data exposure.\" What concept is this?", "c": ["Object Storage Security", "Zero Trust", "Data at Rest Encryption", "Patching (Security)"], "a": 0, "e": "Misconfigured object storage permissions are a very common real-world cause of public data exposure. This describes Object Storage Security (\"Access controls and encryption settings applied to object storage buckets/containers.\")."}, {"obj": "1.8", "q": "Which concept is described by the phrase: \"Tracking actual consumption of cloud resources for billing and capacity planning purposes.\"?", "c": ["Reserved Resources", "Resource Metering", "Pay-As-You-Go", "Dedicated Host Billing"], "a": 1, "e": "\"Tracking actual consumption of cloud resources for billing and capacity planning purposes.\" describes Resource Metering. Provides the raw usage data that billing and rightsizing decisions are based on."}, {"obj": "1.2", "q": "In Cloud+ terminology, \"AZ\" is an abbreviation for which of the following?", "c": ["Central Processing Unit", "Open Authorization", "Artificial Intelligence", "Availability Zone"], "a": 3, "e": "AZ stands for Availability Zone. An isolated location within a cloud region with independent power, cooling, and networking."}, {"obj": "2.4", "q": "Which concept is described by the phrase: \"Validating infrastructure code for syntax, security, and logic before it is applied to real environments.\"?", "c": ["YAML", "IaC Testing", "IaC Versioning", "Configuration as Code"], "a": 1, "e": "\"Validating infrastructure code for syntax, security, and logic before it is applied to real environments.\" describes IaC Testing. Catches errors before they cause an outage or misconfiguration in production."}, {"obj": "4.2", "q": "Which statement accurately describes \"Cloud Security Alliance\"?", "c": ["A data retention requirement specified in a contract with a customer or partner.", "A legal requirement to preserve specific data because it may be relevant to pending litigation.", "An organization that publishes best practices and frameworks specifically for cloud security.", "Payment Card Industry Data Security Standard — security requirements for handling payment card data."], "a": 2, "e": "An organization that publishes best practices and frameworks specifically for cloud security. Provides cloud-specific guidance (like the CCM) that general security standards may not fully address."}, {"obj": "1.7", "q": "An administrator explains the importance of a concept: \"Simple but offers no failover if the host fails.\" What concept is this?", "c": ["Hardware Pass-Through", "NAS (Virtualization Context)", "Host Affinity", "Stand-Alone Virtualization"], "a": 3, "e": "Simple but offers no failover if the host fails. This describes Stand-Alone Virtualization (\"A single hypervisor host running VMs with no clustering.\")."}, {"obj": "1.2", "q": "A company's board requires that a critical payroll system never be down for more than 30 minutes after any disruption. Which metric does this directly describe?", "c": ["RPO", "RTO", "MTBF", "ALE"], "a": 1, "e": "RTO defines the maximum acceptable downtime after a disruption, exactly matching this 30-minute requirement."}, {"obj": "4.2", "q": "A description reads: \"An international standard specifying requirements for an information security management system.\" Which term does this describe?", "c": ["Data Classification", "ISO 27001", "SOC2", "PCI DSS"], "a": 1, "e": "\"An international standard specifying requirements for an information security management system.\" describes ISO 27001. A widely recognized certification demonstrating a structured approach to information security."}, {"obj": "2.5", "q": "Why does this matter on the exam and in practice? \"Must be assessed before provisioning to choose the right storage type and tier.\" — which term does this explain?", "c": ["Storage Requirements", "Compute Requirements", "Network Requirements", "Availability Requirements"], "a": 0, "e": "Must be assessed before provisioning to choose the right storage type and tier. This describes Storage Requirements (\"The capacity, performance, and durability needs a workload has for its data.\")."}, {"obj": "3.2", "q": "An e-commerce site knows from historical data that Black Friday will bring 10x normal traffic on a specific date. What scaling approach should they configure in advance for that specific day?", "c": ["Scheduled scaling for the known date", "Reactive load-triggered scaling only, with no advance planning", "Vertical scaling only", "No scaling changes are needed"], "a": 0, "e": "Scheduled scaling for a known, specific high-traffic date ensures capacity is ready in advance, rather than relying solely on reactive triggers that might lag behind a sudden surge."}, {"obj": "4.5", "q": "Which of the following terms fits this definition: \"Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity.\"?", "c": ["IPS/IDS", "DDoS Protection", "Endpoint Protection", "Network Security Group"], "a": 0, "e": "\"Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity.\" describes IPS/IDS. IDS alerts on suspicious activity; IPS goes further by actively blocking it in real time."}, {"obj": "1.10", "q": "Which term best matches this description: \"Using Function as a Service as the compute resource type for a workload.\"?", "c": ["Compute Optimization (Serverless)", "Compute Optimization (Container)", "IOPS (Optimization)", "Network Throughput"], "a": 0, "e": "\"Using Function as a Service as the compute resource type for a workload.\" describes Compute Optimization (Serverless). Eliminates server management entirely, billing only for actual execution time."}, {"obj": "6.3", "q": "Which of the following is the most appropriate first step after discovering that a set of cloud API keys were accidentally published in a public GitHub repository?", "c": ["Wait to see if anyone notices before taking action", "Immediately revoke/rotate the exposed keys and audit for any unauthorized usage since exposure", "Delete the GitHub repository only, leaving the keys active", "Ignore it since API keys cannot be misused"], "a": 1, "e": "The immediate priority is to revoke or rotate the exposed keys to cut off potential unauthorized access, followed by auditing for any misuse that already occurred."}, {"obj": "3.2", "q": "An administrator explains the importance of a concept: \"Reacts to gradual changes in demand rather than short spikes.\" What concept is this?", "c": ["Horizontal Scaling", "Triggered Scaling — Trending", "Scheduled Scaling", "Triggered Scaling — Load"], "a": 1, "e": "Reacts to gradual changes in demand rather than short spikes. This describes Triggered Scaling — Trending (\"Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU).\")."}, {"obj": "1.8", "q": "Which of the following best describes \"Rightsizing\"?", "c": ["A billing model where a customer pays for an entire physical host, regardless of utilization.", "Adjusting the size/type of provisioned resources to match actual workload demand.", "Attaching key-value metadata labels to cloud resources.", "A billing model charging only for actual resource consumption, with no upfront commitment."], "a": 1, "e": "Adjusting the size/type of provisioned resources to match actual workload demand. Prevents overspending on oversized resources while avoiding performance issues from undersized ones."}, {"obj": "5.2", "q": "A pipeline includes an automated static analysis security scan that must pass before code can proceed to the deployment stage. What CI/CD principle does this reflect?", "c": ["CI/CD workflow only, with no security consideration", "CI/CD security, shifting security checks earlier in the pipeline", "Artifact publishing", "Code review by a human only"], "a": 1, "e": "Incorporating automated security scanning into the pipeline is CI/CD security, catching vulnerabilities earlier and more cheaply than after deployment."}, {"obj": "2.3", "q": "Which of the following best describes \"Re-Architect\"?", "c": ["A migration strategy that rewrites portions of an application to better fit cloud-native patterns.", "Moving workloads from local infrastructure into a cloud environment.", "Moving workloads out of the cloud back to local infrastructure.", "A migration strategy that substantially redesigns an application to be cloud-native."], "a": 3, "e": "A migration strategy that substantially redesigns an application to be cloud-native. Takes the most effort but unlocks the greatest long-term benefits like scalability and cost efficiency."}, {"obj": "1.10", "q": "A colleague says: \"Determines whether a network link can support a workload's data transfer needs.\" Which concept are they describing?", "c": ["Network Throughput", "Workflow (Optimization)", "Compute Optimization (VM)", "Network Latency"], "a": 0, "e": "Determines whether a network link can support a workload's data transfer needs. This describes Network Throughput (\"The actual amount of data successfully transferred over a network connection in a given time.\")."}, {"obj": "4.3", "q": "A third-party application requests permission to access a user's cloud storage on their behalf, without the user ever sharing their password with the third party. What framework enables this?", "c": ["SAML", "OAuth 2.0", "RDP", "Directory-based authentication"], "a": 1, "e": "OAuth 2.0 is an authorization framework specifically designed to let an application access resources on a user's behalf without exposing their password."}, {"obj": "4.4", "q": "Which of the following terms fits this definition: \"Access controls and encryption settings applied to object storage buckets/containers.\"?", "c": ["File Storage Security", "Secrets Management", "Object Storage Security", "Data in Transit Encryption"], "a": 2, "e": "\"Access controls and encryption settings applied to object storage buckets/containers.\" describes Object Storage Security. Misconfigured object storage permissions are a very common real-world cause of public data exposure."}, {"obj": "1.4", "q": "A company must retain seven years of compliance records that are almost never accessed but must remain retrievable. Which storage tier minimizes cost?", "c": ["Hot", "Warm", "Archive", "Local block storage"], "a": 2, "e": "Archive tier storage offers the lowest cost for rarely accessed data, accepting slower retrieval times in exchange."}, {"obj": "1.3", "q": "In Cloud+ terminology, \"ISP\" is an abbreviation for which of the following?", "c": ["General Data Protection Regulation", "Internet Service Provider", "Web Application Firewall", "Network Interface Card"], "a": 1, "e": "ISP stands for Internet Service Provider. A company providing internet access and connectivity."}, {"obj": "4.2", "q": "Which concept is described by the phrase: \"Requirements or preferences about the physical location where data is stored or processed.\"?", "c": ["PCI DSS", "ISO 27001", "Data Locality", "Regulatory Retention"], "a": 2, "e": "\"Requirements or preferences about the physical location where data is stored or processed.\" describes Data Locality. Closely related to, but distinct from, data sovereignty — it may be a business rather than legal requirement."}, {"obj": "1.7", "q": "Why does this matter on the exam and in practice? \"Fast and simple but doesn't support live migration of VMs to other hosts without shared storage.\" — which term does this explain?", "c": ["Local Storage (Virtualization)", "Overlay Network", "Host Affinity", "NAS (Virtualization Context)"], "a": 0, "e": "Fast and simple but doesn't support live migration of VMs to other hosts without shared storage. This describes Local Storage (Virtualization) (\"Storage physically attached to a single hypervisor host.\")."}, {"obj": "5.4", "q": "An administrator explains the importance of a concept: \"One of the most widely used multi-cloud IaC tools, using its own HCL configuration language.\" What concept is this?", "c": ["Docker", "Kubernetes", "Git", "Terraform"], "a": 3, "e": "One of the most widely used multi-cloud IaC tools, using its own HCL configuration language. This describes Terraform (\"An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively.\")."}, {"obj": "4.4", "q": "Which concept is described by the phrase: \"A security model that assumes no user or device should be trusted by default, even inside the network perimeter.\"?", "c": ["Secrets Management", "Zero Trust", "Hardening", "Principle of Least Privilege"], "a": 1, "e": "\"A security model that assumes no user or device should be trusted by default, even inside the network perimeter.\" describes Zero Trust. Requires continuous verification of identity and context for every access request, not just at the network edge."}, {"obj": "1.3", "q": "Which of the following is the correct expansion of \"NIC\"?", "c": ["Network Interface Card", "Information Technology Infrastructure Library", "Machine Learning", "Real-time Messaging Protocol"], "a": 0, "e": "NIC stands for Network Interface Card. Hardware that connects a compute instance to a network."}, {"obj": "1.7", "q": "\"SAN (Virtualization Context)\" is best defined as which of the following?", "c": ["Network Attached Storage — shared file-level storage accessible by multiple hosts.", "Storage physically attached to a single hypervisor host.", "Storage Area Network — shared block storage accessible by multiple hypervisor hosts.", "The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network."], "a": 2, "e": "Storage Area Network — shared block storage accessible by multiple hypervisor hosts. Enables features like live migration and clustering since any host in the cluster can access the same storage."}, {"obj": "5.4", "q": "A team containerizes their application with Docker and then needs a way to automatically restart failed containers and scale replicas up and down based on load in production. What additional tool should they add?", "c": ["Grafana alone", "Kubernetes", "Git alone", "GitHub Actions alone"], "a": 1, "e": "While Docker provides the container runtime, Kubernetes adds the orchestration layer needed for automated restarts, scaling, and scheduling across a cluster."}, {"obj": "3.4", "q": "In cloud computing terminology, \"Lifecycle Testing\" refers to which of the following?", "c": ["A software update addressing a specific bug or vulnerability.", "Retiring a resource because it has reached the end of its useful life or support.", "Validating changes (patches, updates, configuration) before applying them broadly.", "A smaller update, typically with bug fixes and small improvements."], "a": 2, "e": "Validating changes (patches, updates, configuration) before applying them broadly. Reduces the risk that a routine update introduces a new production issue."}, {"obj": "6.3", "q": "An investigation finds that API keys were accidentally committed to a public code repository, leading to unauthorized cloud resource usage. What is the root cause?", "c": ["Privilege escalation", "Leaked credentials", "Cipher suite deprecation", "Software vulnerability issues"], "a": 1, "e": "Leaked credentials exposed in places like public repositories are a very common real-world cause of cloud account compromise."}, {"obj": "6.1", "q": "Which concept is described by the phrase: \"A degradation where some, but not all, functionality or users are affected.\"?", "c": ["Outdated Component Definitions", "Resource Allocation Misconfiguration", "Service Quota", "Partial Outage"], "a": 3, "e": "\"A degradation where some, but not all, functionality or users are affected.\" describes Partial Outage. Still requires prompt attention but may allow more measured troubleshooting than a full outage."}, {"obj": "3.3", "q": "In cloud computing terminology, \"Backup Encryption\" refers to which of the following?", "c": ["How long backup copies are kept before being deleted or overwritten.", "Encrypting backup data so it remains protected even if the storage media or files are exposed.", "Restoring data directly onto the original system/location.", "A complete copy of all selected data."], "a": 1, "e": "Encrypting backup data so it remains protected even if the storage media or files are exposed. Especially important since backups often contain complete copies of sensitive production data."}, {"obj": "4.4", "q": "Which term is most closely associated with this real-world importance: \"Complements general benchmarks with platform-specific configuration recommendations.\"?", "c": ["Zero Trust", "Unprivileged Container", "Vendor-Specific Benchmark", "Secrets Management"], "a": 2, "e": "Complements general benchmarks with platform-specific configuration recommendations. This describes Vendor-Specific Benchmark (\"Hardening guidance published by a specific cloud provider or software vendor for their own product.\")."}, {"obj": "1.4", "q": "A company has a database that requires the fastest possible read/write access for active transactions. Which storage tier should this data reside on?", "c": ["Archive tier", "Cold tier", "Warm tier", "Hot tier"], "a": 3, "e": "The hot tier is optimized for frequently accessed, performance-sensitive data like active transactional databases."}, {"obj": "2.4", "q": "Which practice would most directly help a team understand exactly what changed in their infrastructure configuration between two dates, and who made the change?", "c": ["IaC versioning with commit history", "Disabling all logging", "Avoiding code review", "Removing all comments from IaC templates"], "a": 0, "e": "IaC versioning (via a version control system) provides a commit history showing exactly what changed, when, and by whom."}, {"obj": "4.2", "q": "Given the description \"Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted).\", which term is being defined?", "c": ["Data Ownership", "Contractual Retention", "Regulatory Retention", "Data Classification"], "a": 3, "e": "\"Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted).\" describes Data Classification. Drives how strictly a given piece of data must be protected and handled."}, {"obj": "1.2", "q": "Which of the following best explains why a company might choose to deploy across multiple availability zones within one region rather than across multiple distant regions?", "c": ["To reduce latency between components while still protecting against a single datacenter failure", "To meet requirements for data to leave the country", "To reduce cost to zero", "To eliminate the need for any monitoring"], "a": 0, "e": "Multiple AZs within a single region are geographically close enough to keep latency low between components while still providing protection against a single facility's failure."}, {"obj": "3.1", "q": "Which of the following best illustrates log aggregation providing value during an incident affecting multiple services?", "c": ["Viewing each service's logs separately on different servers with no correlation", "Searching a single centralized system to correlate related log entries across all affected services simultaneously", "Manually copying log files between servers", "Deleting logs immediately after each service restarts"], "a": 1, "e": "Log aggregation's value is precisely in letting engineers search and correlate related events across many services from one centralized system during an incident."}, {"obj": "1.3", "q": "A company wants low-latency Layer 4 load balancing for a high-throughput TCP-based application where content inspection is not needed. Which load balancer type is most appropriate?", "c": ["An application (Layer 7) load balancer", "A network (Layer 4) load balancer", "A CDN edge cache", "A DNS round-robin resolver only"], "a": 1, "e": "A network load balancer operates at Layer 4, providing very high throughput and low latency for raw TCP/UDP traffic without the overhead of Layer 7 inspection."}, {"obj": "1.2", "q": "A financial firm determines it can tolerate losing at most 5 minutes of transaction data in a worst-case disaster. Which metric does this define, and what design implication follows?", "c": ["RTO; requires a faster network connection", "RPO; requires very frequent backups or near-real-time replication", "MTBF; requires more reliable hardware", "ALE; requires cyber insurance"], "a": 1, "e": "RPO defines maximum acceptable data loss; a 5-minute RPO requires frequent backups or continuous/synchronous replication rather than daily backups."}, {"obj": "4.4", "q": "Which combination of practices would best reduce the risk of a compromised container affecting the underlying host system?", "c": ["Running all containers as privileged with root access", "Running containers as unprivileged with least-privilege file access permissions", "Disabling all container security features for performance", "Allowing containers unrestricted network access to the host"], "a": 1, "e": "Running containers unprivileged with tightly scoped file access permissions directly limits the potential impact of a container-level compromise on the host."}, {"obj": "2.5", "q": "A healthcare company provisioning new infrastructure must ensure patient data is encrypted and only processed within approved facilities per regulatory mandates. Which requirement category governs this constraint?", "c": ["Compute requirements", "Compliance requirements", "Network requirements only", "Availability requirements only"], "a": 1, "e": "Regulatory mandates governing how and where sensitive data can be processed and protected fall under compliance requirements."}, {"obj": "1.11", "q": "A company builds a customer service chatbot feature that lets users speak their questions instead of typing them, converting speech into text for the backend to process. Which AI capability enables this?", "c": ["Text-to-voice", "Voice-to-text", "Visual recognition", "Text translation"], "a": 1, "e": "Voice-to-text (speech recognition) converts spoken audio into written text, which is what the chatbot needs to process spoken user questions."}, {"obj": "2.5", "q": "Which of the following best describes \"Availability Requirements\"?", "c": ["The uptime and resiliency expectations for a workload.", "The capacity, performance, and durability needs a workload has for its data.", "Legal or regulatory obligations a workload's data and processing must meet.", "The bandwidth, latency, and connectivity needs of a workload."], "a": 0, "e": "The uptime and resiliency expectations for a workload. Drives decisions like multi-AZ deployment, clustering, and failover design."}, {"obj": "1.5", "q": "In a dynamic cloud-native environment where service instances scale up and down constantly, how do services find the current network location of other services they depend on?", "c": ["Hardcoded IP addresses configured once at deployment", "Service discovery", "Manual DNS updates by an administrator for every scaling event", "Static routing tables updated by hand"], "a": 1, "e": "Service discovery dynamically tracks and provides the current location of service instances, essential in environments where instances and IPs change constantly."}, {"obj": "4.3", "q": "A security audit reviews a chronological record showing which user accessed a specific cloud storage bucket and when, following a suspected data exposure incident. What is this record called?", "c": ["A discretionary access control list", "An audit trail", "A federation configuration", "An OAuth token"], "a": 1, "e": "An audit trail is a chronological record of who did what and when, essential for investigating incidents like this suspected data exposure."}, {"obj": "2.5", "q": "A company's legal team mandates that certain customer data must remain within a specific country's borders when provisioning new cloud resources. What requirement category is this?", "c": ["Compute requirements", "Compliance requirements", "Network requirements", "Storage requirements only"], "a": 1, "e": "Compliance requirements are legal/regulatory obligations that can restrict which regions or configurations are acceptable, such as data residency mandates."}, {"obj": "6.2", "q": "A colleague says: \"DNS failures cause connectivity issues that look like the destination is down, even when it's reachable by IP.\" Which concept are they describing?", "c": ["Access vs. Trunk Ports", "DHCP (Troubleshooting)", "NTP (Troubleshooting)", "DNS (Troubleshooting)"], "a": 3, "e": "DNS failures cause connectivity issues that look like the destination is down, even when it's reachable by IP. This describes DNS (Troubleshooting) (\"Domain Name System — resolves hostnames to IP addresses.\")."}, {"obj": "1.11", "q": "A description reads: \"AI technology that automatically converts text from one language to another.\" Which term does this describe?", "c": ["Text Translation", "IoT Transmission Protocol", "Generative AI", "IoT Sensor"], "a": 0, "e": "\"AI technology that automatically converts text from one language to another.\" describes Text Translation. Enables applications to serve global users without manual translation."}, {"obj": "5.1", "q": "A developer opens a formal request to merge their feature branch into the main branch, which automatically notifies teammates to review the change before it's accepted. What is this called?", "c": ["A code commit", "A pull request", "A code push", "Branch management"], "a": 1, "e": "A pull request is the formal mechanism for requesting a merge, typically triggering mandatory review before code is integrated into the shared branch."}, {"obj": "6.1", "q": "Which term best matches this description: \"Allocating more virtual resources than the underlying physical capacity can truly support.\"?", "c": ["Incompatibility (Deployment)", "Regional Service Availability", "Oversubscription", "Partial Outage"], "a": 2, "e": "\"Allocating more virtual resources than the underlying physical capacity can truly support.\" describes Oversubscription. Can cause performance degradation or failed provisioning if too many workloads compete for the same physical resources."}, {"obj": "2.4", "q": "Select the most accurate description of \"Configuration as Code\":", "c": ["Managing and provisioning infrastructure through machine-readable definition files rather than manual processes.", "Identifying when a deployed resource's actual state no longer matches its defined IaC configuration.", "JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates.", "Managing system or application configuration through code rather than manual configuration."], "a": 3, "e": "Managing system or application configuration through code rather than manual configuration. Ensures configuration consistency across environments and enables automated drift correction."}, {"obj": "1.3", "q": "Which of the following terms fits this definition: \"Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network.\"?", "c": ["VPN", "Dedicated Connection", "Transit Gateway", "BGP"], "a": 0, "e": "\"Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network.\" describes VPN. A common way to connect on-premises networks or remote users securely to cloud resources."}, {"obj": "3.3", "q": "An administrator explains the importance of a concept: \"The simplest recovery approach when the original infrastructure is still available and intact.\" What concept is this?", "c": ["In-Place Recovery", "Backup Schedule", "Full Backup", "Backup Replication"], "a": 0, "e": "The simplest recovery approach when the original infrastructure is still available and intact. This describes In-Place Recovery (\"Restoring data directly onto the original system/location.\")."}, {"obj": "2.3", "q": "A company decides to move its entire cloud workload from one provider to another to take advantage of better pricing and additional managed services. What type of migration is this?", "c": ["On-premises-to-cloud migration", "Cloud-to-on-premises migration", "Cloud-to-cloud migration", "Retain migration"], "a": 2, "e": "Cloud-to-cloud migration moves workloads between different cloud providers or regions, often driven by cost, features, or avoiding vendor lock-in."}, {"obj": "3.3", "q": "Which of the following terms fits this definition: \"How long backup copies are kept before being deleted or overwritten.\"?", "c": ["Backup Schedule", "Backup Retention (Ops)", "Parallel Recovery", "Granular Recovery"], "a": 1, "e": "\"How long backup copies are kept before being deleted or overwritten.\" describes Backup Retention (Ops). Balances storage cost against the need to recover from an issue discovered after some delay."}, {"obj": "1.3", "q": "Which of the following best describes \"CDN\"?", "c": ["A direct network connection between two VPCs that allows them to communicate as if on the same network.", "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port.", "Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network.", "Content Delivery Network — a geographically distributed set of servers that cache content closer to end users."], "a": 3, "e": "Content Delivery Network — a geographically distributed set of servers that cache content closer to end users. Reduces latency and origin server load by serving cached static (and sometimes dynamic) content from edge locations."}, {"obj": "5.3", "q": "What does the abbreviation \"REST\" stand for?", "c": ["Storage Area Network", "Operating System", "Structured Query Language", "Representational State Transfer"], "a": 3, "e": "REST stands for Representational State Transfer. An architectural style for web services using standard HTTP methods."}, {"obj": "1.5", "q": "Which term is most closely associated with this real-world importance: \"Common in event-driven microservices to notify several services of the same event simultaneously.\"?", "c": ["Service Discovery", "Cloud-Provided Managed Service", "Microservices", "Fan-Out"], "a": 3, "e": "Common in event-driven microservices to notify several services of the same event simultaneously. This describes Fan-Out (\"A messaging pattern where one event is distributed to multiple downstream consumers/services.\")."}, {"obj": "6.2", "q": "Which term is most closely associated with this real-world importance: \"Highlights the need to track and update deprecated protocol usage before it causes an outage.\"?", "c": ["HTTP Status Codes", "IP Scope Exhaustion", "Protocol Deprecation", "Access vs. Trunk Ports"], "a": 2, "e": "Highlights the need to track and update deprecated protocol usage before it causes an outage. This describes Protocol Deprecation (\"A connectivity failure caused by a system relying on a protocol version the other side no longer supports.\")."}, {"obj": "1.11", "q": "A company wants to automatically flag negative customer reviews for follow-up. Which AI capability should be used?", "c": ["Visual recognition", "Sentiment analysis", "Text-to-voice", "IoT gateway"], "a": 1, "e": "Sentiment analysis determines the emotional tone of text, making it well suited to automatically flagging negative reviews."}, {"obj": "6.2", "q": "Users report that a web application is reachable by IP address but not by hostname. What should be checked first?", "c": ["NTP configuration", "DNS resolution", "NAT configuration", "HTTP status codes"], "a": 1, "e": "Reachability by IP but not hostname is a classic sign of a DNS resolution failure."}, {"obj": "3.2", "q": "A web tier adds more identical server instances behind a load balancer to handle growing traffic rather than upgrading the size of existing servers. What scaling approach is this?", "c": ["Vertical scaling", "Horizontal scaling", "Manual scaling only, with no automation", "Scheduled scaling only"], "a": 1, "e": "Horizontal scaling (scale out) adds more instances of a resource, which is the standard cloud-native approach to improving both capacity and redundancy."}, {"obj": "1.1", "q": "Which term best matches this description: \"Infrastructure as a Service — provides virtualized compute, storage, and networking, leaving the OS and above to the customer.\"?", "c": ["PaaS", "Shared Responsibility Model", "FaaS", "IaaS"], "a": 3, "e": "\"Infrastructure as a Service — provides virtualized compute, storage, and networking, leaving the OS and above to the customer.\" describes IaaS. The customer patches and secures the OS/apps; the provider is responsible only for the underlying physical infrastructure."}, {"obj": "1.4", "q": "How would you most accurately define \"Archive Storage Tier\"?", "c": ["A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost.", "The lowest-cost storage tier, designed for rarely accessed data with the slowest retrieval times (sometimes hours).", "Hard Disk Drive — traditional magnetic spinning-platter storage.", "Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O."], "a": 1, "e": "The lowest-cost storage tier, designed for rarely accessed data with the slowest retrieval times (sometimes hours). Ideal for long-term retention data that must be kept for compliance but is almost never read."}, {"obj": "5.4", "q": "Why does this matter on the exam and in practice? \"The de facto standard version control system underlying most modern DevOps workflows.\" — which term does this explain?", "c": ["Git", "Ansible", "ELK Stack", "Jenkins"], "a": 0, "e": "The de facto standard version control system underlying most modern DevOps workflows. This describes Git (\"A distributed version control system used to track changes in source code.\")."}, {"obj": "1.3", "q": "Given the description \"A manually configured network route that does not change dynamically.\", which term is being defined?", "c": ["SDN", "Transit Gateway", "Static Route", "BGP"], "a": 2, "e": "\"A manually configured network route that does not change dynamically.\" describes Static Route. Simple and predictable, but requires manual updates if the network topology changes."}, {"obj": "6.1", "q": "An automation script begins issuing API calls faster than the provider allows and starts receiving rejected requests mid-deployment. What is happening?", "c": ["API throttling", "A full outage", "A sizing issue", "Regional service availability"], "a": 0, "e": "API throttling is the provider intentionally limiting request rates; exceeding the allowed rate causes calls to be rejected until the rate decreases."}, {"obj": "3.2", "q": "In cloud computing terminology, \"Scheduled Scaling\" refers to which of the following?", "c": ["Increasing the resources (CPU/RAM) of an existing instance (scale up).", "Adding more instances of a resource to handle increased load (scale out).", "Scaling resources up or down at predefined times based on known usage patterns.", "Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%)."], "a": 2, "e": "Scaling resources up or down at predefined times based on known usage patterns. Ideal for predictable daily/weekly demand cycles, like scaling up before business hours."}, {"obj": "2.4", "q": "A DevOps engineer is writing a Kubernetes manifest and an Ansible playbook. Which data format are both most likely written in?", "c": ["JSON", "YAML", "CSV", "Binary"], "a": 1, "e": "YAML is the preferred human-readable format for Kubernetes manifests and many configuration/IaC tools."}, {"obj": "1.10", "q": "A colleague says: \"Eliminates server management entirely, billing only for actual execution time.\" Which concept are they describing?", "c": ["Orchestration (Workload)", "Compute Optimization (Serverless)", "Compute Optimization (VM)", "Network Latency"], "a": 1, "e": "Eliminates server management entirely, billing only for actual execution time. This describes Compute Optimization (Serverless) (\"Using Function as a Service as the compute resource type for a workload.\")."}, {"obj": "3.4", "q": "Which statement accurately describes \"Ephemeral Data\"?", "c": ["Retiring or upgrading a resource because the vendor no longer provides support/patches for it.", "Retiring a resource because it has reached the end of its useful life or support.", "A smaller update, typically with bug fixes and small improvements.", "Temporary data that does not need to persist beyond a session or process."], "a": 3, "e": "Temporary data that does not need to persist beyond a session or process. Doesn't require the same backup/retention rigor as persistent data."}, {"obj": "4.4", "q": "Given the description \"Applying vendor-released updates that fix known vulnerabilities.\", which term is being defined?", "c": ["Patching (Security)", "Principle of Least Privilege", "Object Storage Security", "API Security"], "a": 0, "e": "\"Applying vendor-released updates that fix known vulnerabilities.\" describes Patching (Security). Closes known security gaps that attackers commonly target since patches for them already exist."}, {"obj": "4.3", "q": "In Cloud+ terminology, \"RDP\" is an abbreviation for which of the following?", "c": ["Local Area Network", "Structured Query Language", "Remote Desktop Protocol", "Create, Read, Update, Delete"], "a": 2, "e": "RDP stands for Remote Desktop Protocol. Microsoft's protocol for remote graphical access to a system."}, {"obj": "1.3", "q": "In cloud computing terminology, \"Application Load Balancer\" refers to which of the following?", "c": ["A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers).", "A set of rules that determines where network traffic is directed.", "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port.", "A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features."], "a": 0, "e": "A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers). Enables advanced routing such as sending /api traffic to one backend and /images to another."}, {"obj": "1.5", "q": "Which statement accurately describes \"Microservices\"?", "c": ["A mechanism that lets services dynamically find the network location of other services.", "A design where components interact through well-defined interfaces with minimal direct dependencies.", "An architecture where an application is broken into small, independently deployable services.", "A messaging pattern where one event is distributed to multiple downstream consumers/services."], "a": 2, "e": "An architecture where an application is broken into small, independently deployable services. Allows teams to develop, scale, and deploy components independently rather than as one large monolith."}, {"obj": "5.3", "q": "In Cloud+ terminology, \"SOAP\" is an abbreviation for which of the following?", "c": ["Red Hat Package Manager", "Simple Object Access Protocol", "Cloud Service Provider", "Non-Volatile Memory Express"], "a": 1, "e": "SOAP stands for Simple Object Access Protocol. An XML-based messaging protocol for web services."}, {"obj": "2.1", "q": "An administrator explains the importance of a concept: \"Balances shared cost benefits with more tailored governance than a general public cloud.\" What concept is this?", "c": ["On Premises", "Hybrid Cloud", "Community Cloud", "Private Cloud"], "a": 2, "e": "Balances shared cost benefits with more tailored governance than a general public cloud. This describes Community Cloud (\"Infrastructure shared by several organizations with common concerns such as compliance or security requirements.\")."}, {"obj": "3.3", "q": "Which statement accurately describes \"Parallel Recovery\"?", "c": ["Restoring data to an alternate system running alongside the original.", "How long backup copies are kept before being deleted or overwritten.", "Restoring a large set of data all at once.", "Verifying that backed-up data has not been corrupted."], "a": 0, "e": "Restoring data to an alternate system running alongside the original. Useful for testing a restore or recovering without disrupting the still-running original system."}, {"obj": "3.1", "q": "A description reads: \"Following a single request as it moves through multiple services in a distributed system.\" Which term does this describe?", "c": ["Log Collection", "Tracing", "Monitoring Metrics", "Log Retention"], "a": 1, "e": "\"Following a single request as it moves through multiple services in a distributed system.\" describes Tracing. Critical for pinpointing where latency or errors occur across microservices."}, {"obj": "4.5", "q": "How would you most accurately define \"Endpoint Protection\"?", "c": ["Security software (antivirus, EDR) installed directly on servers, VMs, or devices.", "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data.", "Rules that define what actions a given identity is allowed or denied to perform on cloud resources.", "Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic."], "a": 0, "e": "Security software (antivirus, EDR) installed directly on servers, VMs, or devices. Detects and blocks malicious activity at the individual system level."}, {"obj": "1.2", "q": "An on-premises data warehouse normally runs at 40% capacity but needs to temporarily use public cloud compute during a quarterly reporting crunch. What is this practice called?", "c": ["Cloud bursting", "Edge computing", "Multicloud tenancy", "A community cloud deployment"], "a": 0, "e": "Cloud bursting extends an on-premises workload into the public cloud temporarily to handle demand spikes, avoiding the cost of permanently overprovisioning on-premises capacity."}, {"obj": "1.2", "q": "Select the most accurate description of \"RPO\":", "c": ["Recovery Point Objective — the maximum acceptable amount of data loss, measured in time.", "An isolated location within a region with independent power, cooling, and networking.", "Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption.", "Continuously checking that a resource or service is up and responding as expected."], "a": 0, "e": "Recovery Point Objective — the maximum acceptable amount of data loss, measured in time. A tight RPO requires frequent backups or synchronous replication; a looser RPO allows infrequent backups."}, {"obj": "4.6", "q": "Which concept is described by the phrase: \"A departure from a system's established normal behavior pattern.\"?", "c": ["Ransomware", "Vulnerability Exploitation — Human Error", "Deviation from Baseline", "Phishing"], "a": 2, "e": "\"A departure from a system's established normal behavior pattern.\" describes Deviation from Baseline. A key signal used to detect anomalies that might indicate compromise or misuse."}, {"obj": "4.3", "q": "Which of the following best describes \"MFA\"?", "c": ["Multifactor Authentication — requiring two or more independent verification factors to log in.", "An identity layer built on top of OAuth 2.0 used for authentication (proving who you are).", "Accessing cloud resources via code rather than a human using a GUI (API/SDK).", "A hardened server that provides a single, monitored entry point for administrative access into a private network."], "a": 0, "e": "Multifactor Authentication — requiring two or more independent verification factors to log in. Makes stolen credentials alone insufficient for an attacker to gain access."}, {"obj": "5.2", "q": "A pipeline produces a versioned .deb package as its build output for deployment to Debian-based Linux servers. What type of artifact is this?", "c": ["A container image artifact", "A Debian package", "An RPM package", "A flat file artifact"], "a": 1, "e": "A .deb file is a Debian package, one of the standard package formats used for installing software on Debian-based Linux distributions."}, {"obj": "1.10", "q": "Given the description \"A defined sequence of automated steps/tasks that process data or coordinate resources.\", which term is being defined?", "c": ["Managed Services (Optimization)", "Workflow (Optimization)", "Compute Optimization (VM)", "IOPS (Optimization)"], "a": 1, "e": "\"A defined sequence of automated steps/tasks that process data or coordinate resources.\" describes Workflow (Optimization). Helps chain together cloud services and automate multi-step business processes."}, {"obj": "1.6", "q": "A developer needs to expose a container's internal port 3000 so that a load balancer positioned in front of it can send traffic to the container. What must be configured on the container?", "c": ["An image registry connection", "Port mapping from an external port to the container's internal port 3000", "A persistent volume", "A stand-alone runtime configuration"], "a": 1, "e": "Port mapping is what allows external traffic (from the load balancer) to be directed into the container's internal listening port."}, {"obj": "3.4", "q": "A description reads: \"Retiring a resource because it has reached the end of its useful life or support.\" Which term does this describe?", "c": ["Minor Update", "Major Update", "Decommissioning — End of Life", "Persistent Data"], "a": 2, "e": "\"Retiring a resource because it has reached the end of its useful life or support.\" describes Decommissioning — End of Life. Requires planning for data migration/retention before the resource is removed."}, {"obj": "6.2", "q": "A client cannot ping a server using ICMP, but the web application on that server works fine over HTTPS from the same client. What is the most likely explanation?", "c": ["DNS is completely broken", "A firewall rule specifically blocks ICMP while still allowing HTTPS traffic", "The server is completely offline", "NAT is misconfigured for all traffic"], "a": 1, "e": "A firewall commonly blocks ICMP (ping) specifically while still allowing legitimate application traffic like HTTPS, which is a normal and intentional configuration in many environments."}, {"obj": "4.6", "q": "A distributed set of compromised systems floods a company's public-facing application with traffic, aiming to make it unavailable to legitimate users. What attack is this?", "c": ["Cryptojacking", "DDoS", "Phishing", "A metadata attack"], "a": 1, "e": "A Distributed Denial of Service (DDoS) attack overwhelms a target with traffic from many distributed sources, aiming to exhaust resources and deny legitimate access."}, {"obj": "4.3", "q": "A CI/CD pipeline needs to authenticate to cloud APIs to provision resources automatically, without any human typing a password. What type of access is this?", "c": ["Web portal access", "Programmatic access using API keys or tokens", "RDP access", "A physical smart card login"], "a": 1, "e": "Programmatic access uses API/SDK credentials (keys or tokens) for automated systems like CI/CD pipelines, distinct from interactive human logins."}, {"obj": "5.1", "q": "Which of the following terms fits this definition: \"Organizing and maintaining separate lines of development (branches) within a repository.\"?", "c": ["Code Push", "Pull Request", "Branch Management", "Code Review"], "a": 2, "e": "\"Organizing and maintaining separate lines of development (branches) within a repository.\" describes Branch Management. Allows parallel work on features/fixes without disrupting the main codebase."}, {"obj": "6.3", "q": "In cloud computing terminology, \"Cipher Suite Deprecation\" refers to which of the following?", "c": ["Access to a system or data by someone without proper permission.", "An identity gaining higher access than originally granted, often through a flaw or misconfiguration.", "Software installed or running without proper approval, increasing risk and potentially breaching policy.", "A connectivity/security failure caused by relying on an outdated, no-longer-supported encryption cipher suite."], "a": 3, "e": "A connectivity/security failure caused by relying on an outdated, no-longer-supported encryption cipher suite. Common after a platform disables old, insecure ciphers for security reasons, breaking legacy clients."}, {"obj": "4.2", "q": "A German company must ensure that customer data physically stored on servers in Germany remains subject to German and EU law, even if the cloud provider is US-based. What concept governs this requirement?", "c": ["Data ownership", "Data sovereignty", "Data classification", "Litigation hold"], "a": 1, "e": "Data sovereignty means data is subject to the laws of the country in which it is physically located, regardless of the provider's home country."}, {"obj": "4.3", "q": "Given the description \"An identity layer built on top of OAuth 2.0 used for authentication (proving who you are).\", which term is being defined?", "c": ["Discretionary Access Control", "Directory-Based Authentication", "Web Portal", "OpenID Connect"], "a": 3, "e": "\"An identity layer built on top of OAuth 2.0 used for authentication (proving who you are).\" describes OpenID Connect. Widely used for consumer and enterprise single sign-on into cloud applications."}, {"obj": "3.4", "q": "Select the most accurate description of \"Patch\":", "c": ["A smaller update, typically with bug fixes and small improvements.", "Temporary data that does not need to persist beyond a session or process.", "A significant version update that may include new features and breaking changes.", "A software update addressing a specific bug or vulnerability."], "a": 3, "e": "A software update addressing a specific bug or vulnerability. Applying patches promptly closes known security gaps before they can be exploited."}, {"obj": "4.4", "q": "A description reads: \"A container granted elevated access to the host system's resources.\" Which term does this describe?", "c": ["Privileged Container", "Object Storage Security", "CIS Benchmark", "Data at Rest Encryption"], "a": 0, "e": "\"A container granted elevated access to the host system's resources.\" describes Privileged Container. Significantly increases risk since a compromised privileged container can affect the underlying host."}, {"obj": "4.5", "q": "How would you most accurately define \"Network Security Group\"?", "c": ["A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs.", "Security software (antivirus, EDR) installed directly on servers, VMs, or devices.", "Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity.", "Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic."], "a": 0, "e": "A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs. The primary mechanism for instance-level network access control in most cloud platforms."}, {"obj": "4.2", "q": "A company prefers, for business reasons rather than legal requirements, to keep its analytics data within North America even though no law mandates this. What concept describes this preference?", "c": ["Data sovereignty (a legal requirement)", "Data locality (a business preference about physical location)", "Litigation hold", "Contractual retention"], "a": 1, "e": "Data locality refers to preferences or requirements about physical data location that may be business-driven rather than strictly legal, distinguishing it from data sovereignty."}, {"obj": "6.2", "q": "Two systems attempting to communicate use incompatible versions of the same protocol, one much newer than the other supports. What category of issue is this?", "c": ["Protocol incompatibility", "IP scope exhaustion", "A missing route", "NAT misconfiguration"], "a": 0, "e": "Protocol incompatibility describes a connectivity failure caused by mismatched protocol versions between two systems, common after upgrading one side without the other."}, {"obj": "5.2", "q": "A pipeline automatically compiles source code into a deployable artifact every time a change is merged into the main branch. What CI/CD stage is this?", "c": ["Code integration", "Build", "Testing", "Deployment"], "a": 1, "e": "The build stage compiles/packages source code into a deployable artifact, transforming source code into something that can actually be run or deployed."}, {"obj": "6.1", "q": "Which statement accurately describes \"Resource Allocation Misconfiguration\"?", "c": ["A previously available feature or API being retired by the provider.", "A provider intentionally limiting the rate of API calls a customer can make.", "Incorrectly assigned CPU, memory, or storage limits for a workload.", "IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated."], "a": 2, "e": "Incorrectly assigned CPU, memory, or storage limits for a workload. Can cause performance problems or outright deployment failure if requested resources aren't actually available."}, {"obj": "4.6", "q": "How would you most accurately define \"Metadata Attack\"?", "c": ["A departure from a system's established normal behavior pattern.", "Malware that encrypts a victim's data and demands payment for the decryption key.", "An attack that abuses a cloud instance's metadata service to steal credentials or configuration data.", "Network ports left open on a system that are not required for its function."], "a": 2, "e": "An attack that abuses a cloud instance's metadata service to steal credentials or configuration data. A cloud-specific attack vector, since metadata services often provide temporary credentials to the instance."}, {"obj": "1.11", "q": "A company wants to automatically flag negative product reviews for a support team to follow up on. Which AI capability should be used?", "c": ["Visual recognition", "Sentiment analysis", "Text-to-voice", "IoT communication"], "a": 1, "e": "Sentiment analysis determines the emotional tone of text, making it well suited to automatically flagging negative reviews."}, {"obj": "2.2", "q": "Which term best matches this description: \"Updating an existing server or instance directly rather than deploying an entirely new one.\"?", "c": ["Rolling Deployment", "In-Place Deployment", "Blue-Green Deployment", "Canary Deployment"], "a": 1, "e": "\"Updating an existing server or instance directly rather than deploying an entirely new one.\" describes In-Place Deployment. Simpler but riskier than blue-green since there is no separate environment to instantly roll back to."}, {"obj": "1.3", "q": "A description reads: \"Virtual Private Cloud — an isolated, logically defined network within a public cloud provider's infrastructure.\" Which term does this describe?", "c": ["VLAN", "VPC", "Network Load Balancer", "Subnet"], "a": 1, "e": "\"Virtual Private Cloud — an isolated, logically defined network within a public cloud provider's infrastructure.\" describes VPC. Forms the fundamental network boundary for cloud resources, similar to a private on-premises network."}, {"obj": "1.7", "q": "Given the description \"Storage Area Network — shared block storage accessible by multiple hypervisor hosts.\", which term is being defined?", "c": ["SAN (Virtualization Context)", "Cloning", "Clustering", "Host Affinity"], "a": 0, "e": "\"Storage Area Network — shared block storage accessible by multiple hypervisor hosts.\" describes SAN (Virtualization Context). Enables features like live migration and clustering since any host in the cluster can access the same storage."}, {"obj": "1.3", "q": "\"Application Load Balancer\" is best defined as which of the following?", "c": ["Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains.", "A manually configured network route that does not change dynamically.", "Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management.", "A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers)."], "a": 3, "e": "A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers). Enables advanced routing such as sending /api traffic to one backend and /images to another."}, {"obj": "4.3", "q": "Why does this matter on the exam and in practice? \"Reduces the attack surface by ensuring administrative access doesn't require directly exposing every resource.\" — which term does this explain?", "c": ["RDP", "MFA", "OAuth 2.0", "Bastion Host"], "a": 3, "e": "Reduces the attack surface by ensuring administrative access doesn't require directly exposing every resource. This describes Bastion Host (\"A hardened server that provides a single, monitored entry point for administrative access into a private network.\")."}, {"obj": "5.2", "q": "Select the most accurate description of \"CI/CD Security\":", "c": ["Incorporating security scanning and checks into the automated pipeline.", "A code or artifact repository accessible to anyone.", "Compiling/packaging source code into a deployable artifact.", "Automatically building, testing, and deploying code changes with minimal manual intervention."], "a": 0, "e": "Incorporating security scanning and checks into the automated pipeline. Shifts security left, catching vulnerabilities earlier and cheaper than after deployment."}, {"obj": "5.2", "q": "A CI/CD pipeline includes an automated static analysis scan for vulnerabilities before code can proceed to deployment. What CI/CD principle does this reflect?", "c": ["CI/CD workflow only", "CI/CD security", "Code integration", "Artifact versioning"], "a": 1, "e": "Incorporating security scanning into the pipeline (CI/CD security) shifts security checks earlier and cheaper than after deployment."}, {"obj": "1.11", "q": "Which concept is described by the phrase: \"AI technology that extracts text from images or scanned documents (OCR).\"?", "c": ["Machine Learning", "IoT Communication", "Text Recognition", "Text-to-Voice"], "a": 2, "e": "\"AI technology that extracts text from images or scanned documents (OCR).\" describes Text Recognition. Used to digitize and search paper documents or extract data from images automatically."}, {"obj": "4.3", "q": "In cloud computing terminology, \"Directory-Based Authentication\" refers to which of the following?", "c": ["A graphical, browser-based interface for managing cloud resources.", "A chronological record of who did what, and when, within a system.", "An access model where the resource owner decides who else can access it.", "Authenticating against a centralized directory service (like LDAP or Active Directory)."], "a": 3, "e": "Authenticating against a centralized directory service (like LDAP or Active Directory). Centralizes identity management across many systems rather than maintaining separate local accounts."}, {"obj": "4.2", "q": "How would you most accurately define \"Cloud Security Alliance\"?", "c": ["Requirements or preferences about the physical location where data is stored or processed.", "A data retention requirement mandated by law or industry regulation.", "An organization that publishes best practices and frameworks specifically for cloud security.", "Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted)."], "a": 2, "e": "An organization that publishes best practices and frameworks specifically for cloud security. Provides cloud-specific guidance (like the CCM) that general security standards may not fully address."}, {"obj": "4.2", "q": "A description reads: \"A legal requirement to preserve specific data because it may be relevant to pending litigation.\" Which term does this describe?", "c": ["Regulatory Retention", "PCI DSS", "Litigation Hold", "Data Ownership"], "a": 2, "e": "\"A legal requirement to preserve specific data because it may be relevant to pending litigation.\" describes Litigation Hold. Overrides normal retention/deletion schedules until the hold is lifted."}, {"obj": "6.2", "q": "Which term best matches this description: \"An incorrect entry in a route table sending traffic to the wrong destination.\"?", "c": ["NAT (Troubleshooting)", "VLAN Misconfigured Tags", "Misconfigured Route", "Protocol Incompatibility"], "a": 2, "e": "\"An incorrect entry in a route table sending traffic to the wrong destination.\" describes Misconfigured Route. Can cause traffic to be dropped, looped, or sent somewhere unintended."}, {"obj": "1.8", "q": "An administrator explains the importance of a concept: \"Reduces cost for predictable, steady-state workloads compared to pay-as-you-go pricing.\" What concept is this?", "c": ["Spot Instance", "Resource Metering", "Reserved Resources", "Tagging"], "a": 2, "e": "Reduces cost for predictable, steady-state workloads compared to pay-as-you-go pricing. This describes Reserved Resources (\"Pre-purchasing capacity for a discounted rate in exchange for a committed term.\")."}, {"obj": "1.3", "q": "The acronym \"VPN\" stands for:", "c": ["Common Weakness Enumeration", "Application Programming Interface", "Virtual Private Network", "Software Development Kit"], "a": 2, "e": "VPN stands for Virtual Private Network. An encrypted tunnel providing secure remote connectivity over a public network."}, {"obj": "5.2", "q": "A colleague says: \"Reduces human error and speeds up the delivery of software changes.\" Which concept are they describing?", "c": ["CI/CD Automation", "VM Image Artifact", "CI/CD Testing", "CI/CD Security"], "a": 0, "e": "Reduces human error and speeds up the delivery of software changes. This describes CI/CD Automation (\"Automatically building, testing, and deploying code changes with minimal manual intervention.\")."}, {"obj": "2.4", "q": "How would you most accurately define \"YAML\"?", "c": ["Managing and provisioning infrastructure through machine-readable definition files rather than manual processes.", "Yet Another Markup Language — a human-readable data format widely used for IaC and configuration files.", "Tracking changes to infrastructure code over time using version control.", "JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates."], "a": 1, "e": "Yet Another Markup Language — a human-readable data format widely used for IaC and configuration files. The preferred format for tools like Kubernetes manifests and many CI/CD pipeline definitions."}, {"obj": "6.2", "q": "After merging two previously separate networks via a site-to-site VPN, hosts on both sides begin experiencing intermittent routing failures. What is the likely cause?", "c": ["A missing route only", "Network overlap from duplicate/conflicting IP address ranges", "Protocol deprecation", "VLAN misconfigured tags"], "a": 1, "e": "Connecting networks that use overlapping or duplicate IP address ranges causes routing conflicts and intermittent failures once merged."}, {"obj": "1.11", "q": "Why does this matter on the exam and in practice? \"Reduces the number of direct cloud connections needed and can perform local pre-processing.\" — which term does this explain?", "c": ["IoT Gateway", "Voice-to-Text", "Text Recognition", "Sentiment Analysis"], "a": 0, "e": "Reduces the number of direct cloud connections needed and can perform local pre-processing. This describes IoT Gateway (\"A device that aggregates and relays data from multiple IoT sensors to the cloud.\")."}, {"obj": "4.3", "q": "Which statement accurately describes \"Group-Based Access Control\"?", "c": ["Allowing users to authenticate using credentials from a separate, trusted identity provider.", "Authenticating with credentials stored directly on the system rather than a central directory.", "Secure Shell — an encrypted protocol for remote command-line access to cloud resources.", "Granting permissions to a group, which members inherit by being added to that group."], "a": 3, "e": "Granting permissions to a group, which members inherit by being added to that group. Similar to RBAC but organized around groups rather than formally defined roles."}, {"obj": "5.4", "q": "Which of the following best describes \"Grafana\"?", "c": ["An open-source tool for visualizing metrics and creating monitoring dashboards.", "An open-source, agentless automation tool used for configuration management and orchestration.", "An open-source platform for automating deployment, scaling, and management of containerized applications.", "A platform for building, running, and managing containers."], "a": 0, "e": "An open-source tool for visualizing metrics and creating monitoring dashboards. Commonly paired with time-series databases to build real-time operational dashboards."}, {"obj": "2.5", "q": "An architect provisions a new application server with substantially more CPU and RAM than the application will realistically ever use. What has likely been misjudged?", "c": ["Availability requirements", "Compute requirements (oversized relative to actual need)", "Compliance requirements", "Network requirements"], "a": 1, "e": "Oversizing compute resources relative to actual application needs reflects a compute requirements assessment that didn't match real workload demand, wasting cost."}, {"obj": "3.3", "q": "A description reads: \"A complete copy of all selected data.\" Which term does this describe?", "c": ["Backup Retention (Ops)", "Granular Recovery", "Full Backup", "Bulk Recovery"], "a": 2, "e": "\"A complete copy of all selected data.\" describes Full Backup. Forms the baseline that incremental and differential backups build on."}, {"obj": "1.5", "q": "Which of the following terms fits this definition: \"A messaging pattern where one event is distributed to multiple downstream consumers/services.\"?", "c": ["Cloud-Provided Managed Service", "Microservices", "Loosely Coupled Architecture", "Fan-Out"], "a": 3, "e": "\"A messaging pattern where one event is distributed to multiple downstream consumers/services.\" describes Fan-Out. Common in event-driven microservices to notify several services of the same event simultaneously."}, {"obj": "4.2", "q": "Which of the following terms fits this definition: \"A legal requirement to preserve specific data because it may be relevant to pending litigation.\"?", "c": ["Regulatory Retention", "Litigation Hold", "SOC2", "Data Locality"], "a": 1, "e": "\"A legal requirement to preserve specific data because it may be relevant to pending litigation.\" describes Litigation Hold. Overrides normal retention/deletion schedules until the hold is lifted."}, {"obj": "6.3", "q": "\"Software Vulnerability Issues\" is best defined as which of the following?", "c": ["Problems arising from unpatched or improperly configured software containing known weaknesses.", "A connectivity/security failure caused by relying on an outdated, no-longer-supported encryption cipher suite.", "Access to a system or data by someone without proper permission.", "An identity gaining higher access than originally granted, often through a flaw or misconfiguration."], "a": 0, "e": "Problems arising from unpatched or improperly configured software containing known weaknesses. Reinforces the ongoing need for vulnerability management and timely patching."}, {"obj": "4.3", "q": "A description reads: \"Secure Shell — an encrypted protocol for remote command-line access to cloud resources.\" Which term does this describe?", "c": ["OpenID Connect", "SSH", "SDK", "Discretionary Access Control"], "a": 1, "e": "\"Secure Shell — an encrypted protocol for remote command-line access to cloud resources.\" describes SSH. The standard way to securely administer Linux-based cloud instances remotely."}, {"obj": "4.6", "q": "Which statement accurately describes \"Cryptojacking\"?", "c": ["Unauthorized use of a system's computing resources to mine cryptocurrency.", "A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email.", "An attack that abuses a cloud instance's metadata service to steal credentials or configuration data.", "An attack that succeeds due to a mistake made by an authorized user (misconfiguration, mishandling credentials, etc.)."], "a": 0, "e": "Unauthorized use of a system's computing resources to mine cryptocurrency. Often detected through unexplained high CPU usage and increased cloud compute costs."}, {"obj": "4.1", "q": "A company using a third-party vulnerability scanning tool receives a report listing each finding by its CVE ID along with a calculated risk score. Which two elements of the vulnerability management lifecycle does this report primarily support?", "c": ["Scanning scope definition and remediation only", "Vulnerability identification (via CVE-tagged findings) and assessment (via the risk score)", "Only remediation, with no other lifecycle stage involved", "End of life planning"], "a": 1, "e": "CVE-tagged findings represent identification, while the calculated risk score supports the assessment stage that informs prioritization."}, {"obj": "1.11", "q": "How would you most accurately define \"Sentiment Analysis\"?", "c": ["AI technology that extracts text from images or scanned documents (OCR).", "AI technology that converts written text into spoken audio (speech synthesis).", "AI technology that automatically converts text from one language to another.", "AI technology that determines the emotional tone (positive/negative/neutral) of text."], "a": 3, "e": "AI technology that determines the emotional tone (positive/negative/neutral) of text. Used to analyze customer feedback, reviews, and social media at scale."}, {"obj": "4.2", "q": "A company labels certain files as 'confidential' and applies stricter access controls and encryption to them compared to files labeled 'public'. What practice is this?", "c": ["Data sovereignty", "Data classification", "Litigation hold", "SOC 2 auditing"], "a": 1, "e": "Data classification categorizes data by sensitivity, directly driving how strictly each category must be protected and handled."}, {"obj": "1.2", "q": "Which concept is described by the phrase: \"A fully equipped, continuously running DR site that can take over almost immediately.\"?", "c": ["Hot Site", "Availability Zone", "RPO", "Warm Site"], "a": 0, "e": "\"A fully equipped, continuously running DR site that can take over almost immediately.\" describes Hot Site. Offers the shortest RTO but is the most expensive DR option to maintain."}, {"obj": "4.3", "q": "A company centralizes all user accounts in an LDAP-based directory so that access across many systems can be managed from one place rather than per-system local accounts. What authentication approach is this?", "c": ["Directory-based authentication", "Local user authentication", "Programmatic access only", "Discretionary access control"], "a": 0, "e": "Directory-based authentication centralizes identity management in a directory service (like LDAP or Active Directory), rather than maintaining separate local accounts on every system."}, {"obj": "4.4", "q": "A description reads: \"Hardening guidance published by a specific cloud provider or software vendor for their own product.\" Which term does this describe?", "c": ["Unprivileged Container", "Secrets Management", "Vendor-Specific Benchmark", "File Storage Security"], "a": 2, "e": "\"Hardening guidance published by a specific cloud provider or software vendor for their own product.\" describes Vendor-Specific Benchmark. Complements general benchmarks with platform-specific configuration recommendations."}, {"obj": "3.3", "q": "Why does this matter on the exam and in practice? \"Fastest to perform, but restoring requires the full chain of backups applied in order.\" — which term does this explain?", "c": ["Parallel Recovery", "Backup Replication", "Incremental Backup", "In-Place Recovery"], "a": 2, "e": "Fastest to perform, but restoring requires the full chain of backups applied in order. This describes Incremental Backup (\"Backs up only data changed since the last backup of any type.\")."}, {"obj": "3.4", "q": "The acronym \"ITIL\" stands for:", "c": ["Random Access Memory", "Information Technology Infrastructure Library", "Internet Protocol", "Common Vulnerabilities and Exposures"], "a": 1, "e": "ITIL stands for Information Technology Infrastructure Library. A framework of best practices for IT service management."}, {"obj": "2.5", "q": "Which statement accurately describes \"Availability Requirements\"?", "c": ["The processing power (CPU, RAM) needed to run a workload effectively.", "Legal or regulatory obligations a workload's data and processing must meet.", "The capacity, performance, and durability needs a workload has for its data.", "The uptime and resiliency expectations for a workload."], "a": 3, "e": "The uptime and resiliency expectations for a workload. Drives decisions like multi-AZ deployment, clustering, and failover design."}, {"obj": "1.2", "q": "A company runs identical workloads across AWS and Google Cloud simultaneously to avoid depending entirely on one vendor's pricing and roadmap. What is this strategy called?", "c": ["Cloud bursting", "Multicloud tenancy", "Edge computing", "A single-region deployment"], "a": 1, "e": "Multicloud tenancy uses multiple cloud providers simultaneously, reducing vendor lock-in risk at the cost of added operational complexity."}, {"obj": "1.1", "q": "A description reads: \"Function as a Service — lets code run in response to events without provisioning or managing any server (serverless).\" Which term does this describe?", "c": ["FaaS", "Shared Responsibility Model", "SaaS", "IaaS"], "a": 0, "e": "\"Function as a Service — lets code run in response to events without provisioning or managing any server (serverless).\" describes FaaS. Billing is based on execution time/invocations rather than reserved capacity, ideal for event-driven workloads."}, {"obj": "1.4", "q": "An application needs a shared file system that multiple VMs can mount and read/write simultaneously. Which storage type fits?", "c": ["Block storage", "Object storage", "File storage", "Local ephemeral disk"], "a": 2, "e": "File storage provides a shared, hierarchical file system accessible by multiple clients simultaneously, unlike block storage which is typically attached to one VM."}, {"obj": "1.3", "q": "Which term is most closely associated with this real-world importance: \"Offers more consistent bandwidth/latency and often lower cost at scale than routing through the public internet.\"?", "c": ["CDN", "VPC", "Route Table", "Dedicated Connection"], "a": 3, "e": "Offers more consistent bandwidth/latency and often lower cost at scale than routing through the public internet. This describes Dedicated Connection (\"A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute).\")."}, {"obj": "1.3", "q": "Which statement accurately describes \"Firewall\"?", "c": ["A device or service that filters network traffic based on defined rules.", "Content Delivery Network — a geographically distributed set of servers that cache content closer to end users.", "A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers).", "A hub service that connects many VPCs and on-premises networks through a single point."], "a": 0, "e": "A device or service that filters network traffic based on defined rules. The primary control for restricting which traffic is allowed in/out of a cloud network segment."}, {"obj": "2.3", "q": "Which term best matches this description: \"Moving workloads from one cloud provider or region to another.\"?", "c": ["Refactor", "Cloud-to-On-Premises Migration", "Replatform", "Cloud-to-Cloud Migration"], "a": 3, "e": "\"Moving workloads from one cloud provider or region to another.\" describes Cloud-to-Cloud Migration. Often driven by cost optimization, feature needs, or avoiding vendor lock-in."}, {"obj": "3.2", "q": "Which term best matches this description: \"An administrator explicitly changing resource capacity rather than relying on automation.\"?", "c": ["Triggered Scaling — Trending", "Triggered Scaling — Load", "Triggered Scaling — Event", "Manual Scaling"], "a": 3, "e": "\"An administrator explicitly changing resource capacity rather than relying on automation.\" describes Manual Scaling. Useful for planned events or when automated triggers aren't yet configured."}, {"obj": "1.5", "q": "Which of the following terms fits this definition: \"A service the cloud provider fully operates (e.g., a managed database), removing the customer's operational burden.\"?", "c": ["Service Discovery", "Cloud-Provided Managed Service", "Fan-Out", "Microservices"], "a": 1, "e": "\"A service the cloud provider fully operates (e.g., a managed database), removing the customer's operational burden.\" describes Cloud-Provided Managed Service. Reduces administrative overhead at the cost of some control and customization."}, {"obj": "1.7", "q": "Which term is most closely associated with this real-world importance: \"Enables high availability and load balancing of VMs across multiple physical hosts.\"?", "c": ["Host Affinity", "Hardware Pass-Through", "Clustering", "Stand-Alone Virtualization"], "a": 2, "e": "Enables high availability and load balancing of VMs across multiple physical hosts. This describes Clustering (\"Grouping multiple hypervisor hosts together to share resources and enable failover/migration.\")."}, {"obj": "4.2", "q": "In cloud computing terminology, \"Data Classification\" refers to which of the following?", "c": ["Systems and Organization Controls 2 — an audit framework evaluating a service provider's controls around security, availability, and confidentiality.", "Defining who legally owns and controls a given set of data.", "An organization that publishes best practices and frameworks specifically for cloud security.", "Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted)."], "a": 3, "e": "Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted). Drives how strictly a given piece of data must be protected and handled."}, {"obj": "4.4", "q": "Select the most accurate description of \"Unprivileged Container\":", "c": ["Encrypting stored data so it remains unreadable without the correct key.", "Access controls and encryption settings applied to object storage buckets/containers.", "A container running with restricted access, isolated from the host's sensitive resources.", "Securely storing and controlling access to credentials, API keys, and other sensitive configuration values."], "a": 2, "e": "A container running with restricted access, isolated from the host's sensitive resources. The safer default for container security, limiting the impact of a container-level compromise."}, {"obj": "1.3", "q": "Which term best matches this description: \"A device or service that filters network traffic based on defined rules.\"?", "c": ["VPN", "Firewall", "Application Load Balancer", "Network Load Balancer"], "a": 1, "e": "\"A device or service that filters network traffic based on defined rules.\" describes Firewall. The primary control for restricting which traffic is allowed in/out of a cloud network segment."}, {"obj": "1.9", "q": "A retailer needs a database to enforce strict referential integrity between its customers, orders, and inventory tables. Which database type enforces this kind of integrity natively?", "c": ["A relational database with foreign key constraints", "A pure object storage bucket", "An unstructured document store with no schema", "Local ephemeral storage"], "a": 0, "e": "Relational databases natively enforce referential integrity through foreign key constraints between related tables."}, {"obj": "5.3", "q": "A company wants to decouple its order-processing pipeline so that inventory, billing, and shipping services can each independently react to new orders without the order service directly calling each one. What architecture best supports this?", "c": ["A tightly coupled RPC chain calling each service in sequence", "Event-driven architecture with a published 'new order' event", "A rigid SOAP contract requiring synchronous responses from all three services", "A single monolithic function handling all three tasks"], "a": 1, "e": "Event-driven architecture lets each downstream service react independently to a published event, decoupling the order service from directly managing each downstream call."}, {"obj": "6.2", "q": "Select the most accurate description of \"Protocol Incompatibility\":", "c": ["Network Time Protocol — synchronizes system clocks across a network.", "An incorrect entry in a route table sending traffic to the wrong destination.", "A connectivity failure caused by two systems using different or mismatched protocol versions.", "A required network path that has not been defined in a route table."], "a": 2, "e": "A connectivity failure caused by two systems using different or mismatched protocol versions. Common after upgrading one side of a connection without updating the other."}, {"obj": "2.5", "q": "How would you most accurately define \"Network Requirements\"?", "c": ["The uptime and resiliency expectations for a workload.", "The capacity, performance, and durability needs a workload has for its data.", "The bandwidth, latency, and connectivity needs of a workload.", "The processing power (CPU, RAM) needed to run a workload effectively."], "a": 2, "e": "The bandwidth, latency, and connectivity needs of a workload. Shapes decisions about region placement, dedicated connections, and load balancer configuration."}, {"obj": "1.10", "q": "A storage volume backing a high-transaction database is consistently maxing out its available operations per second. What metric is the bottleneck?", "c": ["Network latency", "IOPS", "Storage capacity (GB)", "CPU count"], "a": 1, "e": "IOPS measures how many read/write operations a storage system can handle per second; exhausting it creates a performance bottleneck regardless of free capacity."}, {"obj": "4.4", "q": "Which of the following best describes \"Zero Trust\"?", "c": ["A security model that assumes no user or device should be trusted by default, even inside the network perimeter.", "Encrypting stored data so it remains unreadable without the correct key.", "Controls governing which files and directories a container process can read or write.", "Granting only the minimum access rights needed to perform a function."], "a": 0, "e": "A security model that assumes no user or device should be trusted by default, even inside the network perimeter. Requires continuous verification of identity and context for every access request, not just at the network edge."}, {"obj": "1.1", "q": "A development team pushes application code to a managed platform that automatically handles the runtime, scaling, and load balancing, but the team never configures an OS. Which model is this?", "c": ["IaaS", "PaaS", "SaaS", "On-premises"], "a": 1, "e": "PaaS provides a managed application platform and runtime, abstracting away OS-level management while still requiring the customer to manage their own code and data."}, {"obj": "4.4", "q": "Why does this matter on the exam and in practice? \"Protects data from eavesdropping while crossing untrusted networks like the internet.\" — which term does this explain?", "c": ["Data in Transit Encryption", "File Storage Security", "API Security", "Vendor-Specific Benchmark"], "a": 0, "e": "Protects data from eavesdropping while crossing untrusted networks like the internet. This describes Data in Transit Encryption (\"Encrypting data as it moves across a network (e.g., via TLS).\")."}, {"obj": "5.4", "q": "In cloud computing terminology, \"Kubernetes\" refers to which of the following?", "c": ["A distributed version control system used to track changes in source code.", "An open-source platform for automating deployment, scaling, and management of containerized applications.", "A platform for building, running, and managing containers.", "An open-source tool for visualizing metrics and creating monitoring dashboards."], "a": 1, "e": "An open-source platform for automating deployment, scaling, and management of containerized applications. The de facto standard for container orchestration in modern cloud-native environments."}, {"obj": "1.2", "q": "Which statement accurately describes \"Region\"?", "c": ["A fully equipped, continuously running DR site that can take over almost immediately.", "Using services from more than one public cloud provider simultaneously.", "A basic facility with power and space but no pre-installed equipment.", "A distinct geographic location where a cloud provider operates one or more datacenters."], "a": 3, "e": "A distinct geographic location where a cloud provider operates one or more datacenters. Choosing the right region affects latency, data sovereignty, and compliance."}, {"obj": "4.2", "q": "A company processing customer credit card payments in the cloud must comply with which specific industry standard?", "c": ["ISO 27001 only", "PCI DSS", "GDPR exclusively", "SOC 2 only"], "a": 1, "e": "PCI DSS specifically governs the security requirements for organizations that store, process, or transmit payment card data."}, {"obj": "1.4", "q": "Which term is most closely associated with this real-world importance: \"Suitable for older backups or compliance data that is rarely, but occasionally, needed.\"?", "c": ["File Storage", "Object Storage", "Cold Storage Tier", "Archive Storage Tier"], "a": 2, "e": "Suitable for older backups or compliance data that is rarely, but occasionally, needed. This describes Cold Storage Tier (\"A storage tier for infrequently accessed data, offering lower cost with slower retrieval.\")."}, {"obj": "1.3", "q": "Which term best matches this description: \"Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management.\"?", "c": ["VPC", "Application Load Balancer", "SDN", "Firewall"], "a": 2, "e": "\"Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management.\" describes SDN. Underpins most cloud networking, allowing networks to be defined and changed through code/APIs rather than physical rewiring."}, {"obj": "1.11", "q": "\"Text Translation\" is best defined as which of the following?", "c": ["A device that aggregates and relays data from multiple IoT sensors to the cloud.", "AI technology that converts spoken audio into written text (speech recognition).", "AI technology that automatically converts text from one language to another.", "AI technology that determines the emotional tone (positive/negative/neutral) of text."], "a": 2, "e": "AI technology that automatically converts text from one language to another. Enables applications to serve global users without manual translation."}, {"obj": "4.1", "q": "A security team defines exactly which systems, subnets, and applications will be included in an upcoming vulnerability scan before running it. What step is this?", "c": ["Vulnerability assessment", "Remediation", "Scanning scope definition", "CVE tracking"], "a": 2, "e": "Defining scanning scope ensures the scan actually covers all intended in-scope assets, preventing blind spots from systems accidentally left out."}, {"obj": "1.8", "q": "How would you most accurately define \"Rightsizing\"?", "c": ["A billing model where a customer pays for an entire physical host, regardless of utilization.", "Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice.", "Adjusting the size/type of provisioned resources to match actual workload demand.", "Tracking actual consumption of cloud resources for billing and capacity planning purposes."], "a": 2, "e": "Adjusting the size/type of provisioned resources to match actual workload demand. Prevents overspending on oversized resources while avoiding performance issues from undersized ones."}, {"obj": "4.2", "q": "What does the abbreviation \"STAR\" stand for?", "c": ["Random Access Memory", "Continuous Integration/Continuous Deployment", "Security, Trust, Assurance, Risk", "Network Address Translation"], "a": 2, "e": "STAR stands for Security, Trust, Assurance, Risk. A Cloud Security Alliance program for assessing cloud provider security."}, {"obj": "1.2", "q": "What does the abbreviation \"RPO\" stand for?", "c": ["Recovery Point Objective", "Random Access Memory", "General Data Protection Regulation", "Secure Shell"], "a": 0, "e": "RPO stands for Recovery Point Objective. The maximum acceptable amount of data loss, measured in time."}, {"obj": "1.1", "q": "Which statement accurately describes \"Shared Responsibility Model\"?", "c": ["Infrastructure as a Service — provides virtualized compute, storage, and networking, leaving the OS and above to the customer.", "Function as a Service — lets code run in response to events without provisioning or managing any server (serverless).", "A framework defining which security and operational tasks belong to the cloud provider versus the customer.", "Software as a Service — delivers a fully managed application to end users over the internet."], "a": 2, "e": "A framework defining which security and operational tasks belong to the cloud provider versus the customer. Responsibility shifts up the stack as you move from IaaS to PaaS to SaaS — misunderstanding this is a common real-world security gap."}, {"obj": "6.1", "q": "Which statement accurately describes \"Full Outage\"?", "c": ["Incorrectly assigned CPU, memory, or storage limits for a workload.", "A complete loss of service availability.", "The fact that not all cloud services are available in every region.", "A provider intentionally limiting the rate of API calls a customer can make."], "a": 1, "e": "A complete loss of service availability. Represents the most severe availability impact, prioritized above partial outages."}, {"obj": "5.2", "q": "Which of the following best describes \"VM Image Artifact\"?", "c": ["A simple, unstructured file (like a config or script) produced or consumed by a pipeline.", "A packaged virtual machine image produced and stored as a build output.", "Incorporating security scanning and checks into the automated pipeline.", "Automatically running tests against code as part of the pipeline."], "a": 1, "e": "A packaged virtual machine image produced and stored as a build output. Provides a versioned, reusable deployment unit for VM-based workloads."}, {"obj": "3.2", "q": "A description reads: \"An administrator explicitly changing resource capacity rather than relying on automation.\" Which term does this describe?", "c": ["Triggered Scaling — Event", "Manual Scaling", "Horizontal Scaling", "Triggered Scaling — Load"], "a": 1, "e": "\"An administrator explicitly changing resource capacity rather than relying on automation.\" describes Manual Scaling. Useful for planned events or when automated triggers aren't yet configured."}, {"obj": "6.3", "q": "Which of the following terms fits this definition: \"Access to a system or data by someone without proper permission.\"?", "c": ["Unauthorized Software", "Leaked Credentials", "Cipher Suite Deprecation", "Unauthorized Access"], "a": 3, "e": "\"Access to a system or data by someone without proper permission.\" describes Unauthorized Access. The core security incident type that access controls, logging, and monitoring are designed to catch."}, {"obj": "1.9", "q": "A company using a provider-managed database service is notified that a routine patch will be applied automatically during a scheduled maintenance window. What responsibility has effectively been transferred to the provider?", "c": ["Application-level business logic", "Database engine patching and maintenance", "Data modeling and schema design", "Choosing which reports to generate"], "a": 1, "e": "With a provider-managed database, database engine patching and maintenance become the provider's responsibility, unlike with a self-managed database."}, {"obj": "2.1", "q": "Which deployment model gives an organization the most control over physical hardware and data location, at the cost of full operational responsibility?", "c": ["Public cloud", "On premises", "Community cloud", "Hybrid cloud with a majority public footprint"], "a": 1, "e": "On-premises infrastructure gives maximum control since the organization owns and manages everything physically, but they bear full operational responsibility."}, {"obj": "1.7", "q": "An administrator explains the importance of a concept: \"Commonly used for storing VM templates, ISOs, and shared datastores.\" What concept is this?", "c": ["Cloning", "NAS (Virtualization Context)", "Clustering", "Local Storage (Virtualization)"], "a": 1, "e": "Commonly used for storing VM templates, ISOs, and shared datastores. This describes NAS (Virtualization Context) (\"Network Attached Storage — shared file-level storage accessible by multiple hosts.\")."}, {"obj": "3.4", "q": "A colleague says: \"Requires planning for data migration/retention before the resource is removed.\" Which concept are they describing?", "c": ["Decommissioning — End of Life", "Patch", "Persistent Data", "Major Update"], "a": 0, "e": "Requires planning for data migration/retention before the resource is removed. This describes Decommissioning — End of Life (\"Retiring a resource because it has reached the end of its useful life or support.\")."}, {"obj": "5.4", "q": "Select the most accurate description of \"Jenkins\":", "c": ["A widely used open-source automation server for building CI/CD pipelines.", "An open-source, agentless automation tool used for configuration management and orchestration.", "Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization.", "An open-source tool for visualizing metrics and creating monitoring dashboards."], "a": 0, "e": "A widely used open-source automation server for building CI/CD pipelines. One of the most established tools for orchestrating build, test, and deployment automation."}, {"obj": "6.3", "q": "A company's clients begin failing to connect securely to a cloud API after the provider deprecated TLS 1.0 and 1.1 in favor of requiring TLS 1.2 or higher. What should the affected clients do?", "c": ["Continue using the deprecated protocol indefinitely", "Upgrade their client software/configuration to support the required newer TLS version", "Disable encryption entirely to restore connectivity", "Ignore the issue since it will resolve itself"], "a": 1, "e": "Since the provider has deprecated older TLS versions for security reasons, affected clients need to be upgraded to support the currently required, more secure version."}, {"obj": "3.3", "q": "Which statement accurately describes \"Backup Integrity Testing\"?", "c": ["A complete copy of all selected data.", "Verifying that backed-up data has not been corrupted.", "Actually restoring backup data to confirm it can be used successfully.", "Copying backup data to another location (often off-site or another region)."], "a": 1, "e": "Verifying that backed-up data has not been corrupted. Ensures the backup itself is trustworthy before it's ever relied upon during an actual incident."}, {"obj": "6.1", "q": "Which of the following best describes \"Service Quota\"?", "c": ["Allocating more virtual resources than the underlying physical capacity can truly support.", "A deployment failure or performance problem caused by choosing an inappropriately sized resource.", "The fact that not all cloud services are available in every region.", "A provider-imposed limit on how many of a given resource type can be provisioned."], "a": 3, "e": "A provider-imposed limit on how many of a given resource type can be provisioned. Deployments can fail silently if a quota is reached without prior awareness."}, {"obj": "6.2", "q": "A colleague says: \"Misconfigured NAT/port forwarding is a common cause of unreachable services behind a private network.\" Which concept are they describing?", "c": ["VLAN Misconfigured Tags", "Misconfigured Route", "NAT (Troubleshooting)", "IP Scope Exhaustion"], "a": 2, "e": "Misconfigured NAT/port forwarding is a common cause of unreachable services behind a private network. This describes NAT (Troubleshooting) (\"Network Address Translation — translates private addresses to a public address for routing.\")."}, {"obj": "1.3", "q": "Which concept is described by the phrase: \"Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network.\"?", "c": ["Dedicated Connection", "VPN", "CDN", "BGP"], "a": 1, "e": "\"Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network.\" describes VPN. A common way to connect on-premises networks or remote users securely to cloud resources."}, {"obj": "6.3", "q": "A company's incident response team finds that an attacker escalated privileges by exploiting an overly permissive role assignment that granted far more access than the role's job function required. What security best practice, if followed, would have reduced this risk?", "c": ["Zero Trust for network perimeter only", "The principle of least privilege applied to role assignments", "Cipher suite hardening only", "Data at rest encryption only"], "a": 1, "e": "Applying least privilege to role assignments — granting only the minimum access needed — would have reduced the impact of the overly permissive role being exploited for privilege escalation."}, {"obj": "1.4", "q": "A database administrator needs a virtual disk with low-latency, structured block-level access dedicated to a single VM running a relational database. What storage type is appropriate?", "c": ["Object storage", "File storage", "Block storage", "Archive storage"], "a": 2, "e": "Block storage presents raw addressable blocks attached to a single VM, ideal for database workloads needing low-latency structured access."}, {"obj": "1.8", "q": "A company wants to right-size a fleet of VMs but is unsure which are over- or under-provisioned. What data should they examine first?", "c": ["The color of each VM's icon in the console", "Historical resource metering and utilization data for CPU, memory, and storage", "The initial purchase price only", "The VM's creation date only"], "a": 1, "e": "Historical utilization metrics (CPU, memory, storage) are the direct evidence needed to determine whether a resource is over- or under-provisioned."}, {"obj": "1.2", "q": "Which of the following terms fits this definition: \"An isolated location within a region with independent power, cooling, and networking.\"?", "c": ["Region", "Warm Site", "Availability Zone", "Cold Site"], "a": 2, "e": "\"An isolated location within a region with independent power, cooling, and networking.\" describes Availability Zone. Spreading resources across AZs protects against a single datacenter failure without the latency of a different region."}, {"obj": "3.3", "q": "Which of the following best describes \"Backup Schedule\"?", "c": ["Backs up only data changed since the last backup of any type.", "Restoring data to an alternate system running alongside the original.", "Encrypting backup data so it remains protected even if the storage media or files are exposed.", "The defined frequency and timing of backup jobs."], "a": 3, "e": "The defined frequency and timing of backup jobs. Directly determines the achievable RPO for a given system."}, {"obj": "1.9", "q": "A company adopts a cloud provider's fully managed database offering where the provider automatically handles patching, backups, and failover. What type of database deployment is this?", "c": ["A self-managed database", "A provider-managed database (DBaaS)", "A stand-alone container database", "Local block storage"], "a": 1, "e": "A provider-managed database service (DBaaS) has the provider handling routine operations like patching and backups, reducing the customer's administrative burden."}, {"obj": "2.4", "q": "Which concept is described by the phrase: \"Managing and provisioning infrastructure through machine-readable definition files rather than manual processes.\"?", "c": ["Configuration as Code", "Infrastructure as Code", "JSON", "Drift Detection"], "a": 1, "e": "\"Managing and provisioning infrastructure through machine-readable definition files rather than manual processes.\" describes Infrastructure as Code. Makes infrastructure changes repeatable, version-controlled, and auditable."}, {"obj": "5.2", "q": "Which of the following best describes \"Code Integration\"?", "c": ["Releasing built and tested code to a target environment (e.g., production).", "Incorporating security scanning and checks into the automated pipeline.", "Merging code changes from multiple contributors into a shared, continuously tested codebase.", "Compiling/packaging source code into a deployable artifact."], "a": 2, "e": "Merging code changes from multiple contributors into a shared, continuously tested codebase. The \"CI\" in CI/CD — frequent integration catches conflicts and bugs early."}, {"obj": "1.8", "q": "Which billing model would be least appropriate for a mission-critical, always-on service that cannot tolerate sudden interruption?", "c": ["Reserved resources", "Pay-as-you-go", "Spot instances", "Dedicated host billing"], "a": 2, "e": "Spot instances can be reclaimed with little notice, making them unsuitable for mission-critical, always-on services that cannot tolerate interruption."}, {"obj": "4.4", "q": "A help desk technician is granted only the specific permissions needed to reset passwords, rather than full administrative rights. What principle does this reflect?", "c": ["Zero Trust", "Principle of least privilege", "Federation", "Secrets management"], "a": 1, "e": "Least privilege grants only the minimum access rights needed to perform a function, limiting potential damage from misuse or compromise."}, {"obj": "1.6", "q": "Which concept is described by the phrase: \"Temporary storage tied to a container's lifecycle that is lost when the container stops.\"?", "c": ["Ephemeral Storage", "Persistent Volume", "Image Registry", "Stand-Alone Container"], "a": 0, "e": "\"Temporary storage tied to a container's lifecycle that is lost when the container stops.\" describes Ephemeral Storage. Suitable only for temporary/scratch data since it disappears when the container is removed."}, {"obj": "4.5", "q": "A security team wants to detect malicious network activity and automatically block it in real time, rather than just alerting on it. What control provides this active blocking capability?", "c": ["IDS (detection only)", "IPS (detection and active blocking)", "A network ACL with only allow rules", "DLP for data classification only"], "a": 1, "e": "IPS goes beyond IDS by not just detecting but actively blocking malicious activity in real time."}, {"obj": "2.2", "q": "A team releases a change to 5% of servers, monitors error rates for an hour, then gradually increases to 25%, 50%, and 100% if no issues are found. What deployment strategy is this?", "c": ["In-place deployment", "Canary deployment", "Blue-green deployment (single switch)", "A synchronous deployment"], "a": 1, "e": "Gradually increasing the rollout percentage while monitoring for issues at each stage is the hallmark of a canary deployment."}, {"obj": "5.3", "q": "Which of the following best distinguishes REST from RPC in terms of typical usage pattern?", "c": ["REST is typically resource-oriented using standard HTTP verbs; RPC is typically action/procedure-oriented, calling a specific remote function", "They are functionally identical in every respect", "RPC always uses XML; REST always uses plain text", "REST cannot be used for microservices"], "a": 0, "e": "REST is generally resource-oriented (using HTTP verbs against resources), while RPC is procedure-oriented, invoking a specific remote function or procedure directly."}, {"obj": "2.3", "q": "Why does this matter on the exam and in practice? \"Sometimes chosen for cost, compliance, or performance reasons after initial cloud adoption.\" — which term does this explain?", "c": ["Refactor", "Cloud-to-On-Premises Migration", "Replatform", "Retain"], "a": 1, "e": "Sometimes chosen for cost, compliance, or performance reasons after initial cloud adoption. This describes Cloud-to-On-Premises Migration (\"Moving workloads out of the cloud back to local infrastructure.\")."}, {"obj": "5.1", "q": "Which of the following best describes \"Pull Request\"?", "c": ["Tracking and organizing different versions of code or configuration over time.", "Having other team members examine proposed code changes before they are merged.", "Organizing and maintaining separate lines of development (branches) within a repository.", "A formal request to merge a proposed code change into a shared branch, typically triggering review."], "a": 3, "e": "A formal request to merge a proposed code change into a shared branch, typically triggering review. The standard workflow mechanism for reviewing and discussing changes before merging."}, {"obj": "1.7", "q": "An administrator wants a VM's virtual network adapter to connect to the hypervisor's virtual switch, which in turn connects to the physical network. What component is being configured on the VM?", "c": ["A vNIC", "A persistent volume", "An image registry", "Host affinity"], "a": 0, "e": "A vNIC is the VM's virtual network adapter, connecting through the hypervisor's virtual switch to reach the physical network."}, {"obj": "5.4", "q": "Which of the following best describes \"Ansible\"?", "c": ["An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively.", "A widely used open-source automation server for building CI/CD pipelines.", "An open-source, agentless automation tool used for configuration management and orchestration.", "A CI/CD automation feature built into GitHub for running workflows in response to repository events."], "a": 2, "e": "An open-source, agentless automation tool used for configuration management and orchestration. Uses simple YAML playbooks to automate repetitive configuration tasks across many systems."}, {"obj": "1.10", "q": "Which term best matches this description: \"Input/Output Operations Per Second — a measure of storage performance.\"?", "c": ["Network Throughput", "Orchestration (Workload)", "Compute Optimization (Container)", "IOPS (Optimization)"], "a": 3, "e": "\"Input/Output Operations Per Second — a measure of storage performance.\" describes IOPS (Optimization). A key metric for sizing storage for database or transaction-heavy workloads."}, {"obj": "6.3", "q": "Which of the following best describes \"Cipher Suite Deprecation\"?", "c": ["Access to a system or data by someone without proper permission.", "A connectivity/security failure caused by relying on an outdated, no-longer-supported encryption cipher suite.", "Problems arising from unpatched or improperly configured software containing known weaknesses.", "Authentication credentials that have been exposed, such as in code repositories or logs."], "a": 1, "e": "A connectivity/security failure caused by relying on an outdated, no-longer-supported encryption cipher suite. Common after a platform disables old, insecure ciphers for security reasons, breaking legacy clients."}, {"obj": "5.1", "q": "Which of the following terms fits this definition: \"Tracking and organizing different versions of code or configuration over time.\"?", "c": ["Code Commit", "Code Merge", "Branch Management", "Version Management"], "a": 3, "e": "\"Tracking and organizing different versions of code or configuration over time.\" describes Version Management. Provides the history needed to understand what changed and to roll back if necessary."}, {"obj": "6.1", "q": "Why does this matter on the exam and in practice? \"Leads to deployment failures when the referenced component is no longer valid on the platform.\" — which term does this explain?", "c": ["Oversubscription", "Permission Issues (Deployment)", "Sizing Issues", "Outdated Component Definitions"], "a": 3, "e": "Leads to deployment failures when the referenced component is no longer valid on the platform. This describes Outdated Component Definitions (\"IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated.\")."}, {"obj": "4.3", "q": "In cloud computing terminology, \"Federation\" refers to which of the following?", "c": ["Accessing cloud resources via code rather than a human using a GUI (API/SDK).", "Allowing users to authenticate using credentials from a separate, trusted identity provider.", "A hardened server that provides a single, monitored entry point for administrative access into a private network.", "Authentication using a temporary token issued after initial login, rather than resending credentials each time."], "a": 1, "e": "Allowing users to authenticate using credentials from a separate, trusted identity provider. Lets organizations use existing corporate identities to access cloud resources without duplicate accounts."}, {"obj": "2.4", "q": "Which of the following is the correct expansion of \"CaC\"?", "c": ["Solid-state Drive", "Machine Learning", "Configuration as Code", "General Data Protection Regulation"], "a": 2, "e": "CaC stands for Configuration as Code. Managing system/application configuration through code rather than manual configuration."}, {"obj": "2.2", "q": "Which deployment strategy inherently provides the clearest, most gradual signal about whether a new release is safe before it reaches all users?", "c": ["In-place deployment", "Blue-green deployment (single switch)", "Canary deployment with staged traffic percentages", "None of these strategies provide this signal"], "a": 2, "e": "Canary deployment's staged, incremental traffic exposure provides continuous, gradual feedback on release safety before a full rollout, unlike an all-at-once switch or in-place update."}, {"obj": "3.1", "q": "Which of the following terms fits this definition: \"Defining how long log data is kept before being archived or deleted.\"?", "c": ["Log Retention", "Tracing", "Alert Response", "Log Collection"], "a": 0, "e": "\"Defining how long log data is kept before being archived or deleted.\" describes Log Retention. Balances storage cost against the need to investigate older incidents or meet compliance requirements."}, {"obj": "3.1", "q": "\"Monitoring Metrics\" is best defined as which of the following?", "c": ["Following a single request as it moves through multiple services in a distributed system.", "Combining logs from many sources into a unified, searchable view.", "Numeric measurements of system behavior (CPU, memory, request rate) collected over time.", "Defining how long log data is kept before being archived or deleted."], "a": 2, "e": "Numeric measurements of system behavior (CPU, memory, request rate) collected over time. The foundation of dashboards and alerting used to understand system health."}, {"obj": "4.3", "q": "Given the description \"Authenticating against a centralized directory service (like LDAP or Active Directory).\", which term is being defined?", "c": ["Bastion Host", "SAML", "Directory-Based Authentication", "Federation"], "a": 2, "e": "\"Authenticating against a centralized directory service (like LDAP or Active Directory).\" describes Directory-Based Authentication. Centralizes identity management across many systems rather than maintaining separate local accounts."}, {"obj": "4.4", "q": "A colleague says: \"One of the most fundamental and heavily tested security practices across all IT domains.\" Which concept are they describing?", "c": ["Vendor-Specific Benchmark", "Hardening", "Patching (Security)", "Container File Access Permissions"], "a": 1, "e": "One of the most fundamental and heavily tested security practices across all IT domains. This describes Hardening (\"Reducing a system's attack surface by disabling unnecessary services, closing unused ports, and applying secure configurations.\")."}, {"obj": "3.4", "q": "Which of the following would be classified as persistent data requiring durable storage and backup?", "c": ["A temporary in-memory session token that expires in 30 minutes", "A customer's completed order history", "A scratch file used only during a single batch job", "A cache entry that can be regenerated at any time"], "a": 1, "e": "Completed order history represents lasting business value that must be retained beyond any single process, making it persistent data requiring durable storage and backup."}, {"obj": "1.2", "q": "Which of the following best describes \"Hot Site\"?", "c": ["A partially equipped DR site that needs recent data restored before it can take over.", "A distinct geographic location where a cloud provider operates one or more datacenters.", "A fully equipped, continuously running DR site that can take over almost immediately.", "A basic facility with power and space but no pre-installed equipment."], "a": 2, "e": "A fully equipped, continuously running DR site that can take over almost immediately. Offers the shortest RTO but is the most expensive DR option to maintain."}, {"obj": "4.3", "q": "Which term best matches this description: \"Application Programming Interface — used here for programmatic management/access to cloud resources.\"?", "c": ["OAuth 2.0", "API (IAM Context)", "Programmatic Access", "SDK"], "a": 1, "e": "\"Application Programming Interface — used here for programmatic management/access to cloud resources.\" describes API (IAM Context). API access typically requires its own credentials (keys/tokens) separate from human user logins."}, {"obj": "1.7", "q": "A company wants to quickly stand up ten new VMs with identical OS and application configuration for a temporary project. What is the fastest supported method?", "c": ["Manually installing the OS and applications on each VM", "Cloning from a pre-configured VM", "Using hardware pass-through for each VM", "Building each VM from a bare-metal installation"], "a": 1, "e": "Cloning an existing pre-configured VM is far faster than manually building each VM individually from scratch."}, {"obj": "1.2", "q": "A colleague says: \"Drives the choice of DR site type and how much automation/investment is needed to meet the target.\" Which concept are they describing?", "c": ["Hot Site", "Warm Site", "RPO", "RTO"], "a": 3, "e": "Drives the choice of DR site type and how much automation/investment is needed to meet the target. This describes RTO (\"Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption.\")."}, {"obj": "2.2", "q": "A team wants to validate a new feature with real production traffic but only exposes it to a small, controlled percentage of users rather than switching everyone over at once. What deployment approach are they using?", "c": ["Blue-green deployment", "Canary deployment", "In-place deployment", "A full outage rollout"], "a": 1, "e": "Testing a change with a small percentage of real production traffic before wider rollout is the defining characteristic of a canary deployment."}, {"obj": "3.3", "q": "A company needs to recover just the last three days of transactions for a specific customer table without restoring an entire multi-terabyte database. What recovery approach best fits this need?", "c": ["Bulk recovery of the entire database", "Granular recovery targeting the specific table and time range", "In-place recovery of the whole server", "Parallel recovery of an unrelated system"], "a": 1, "e": "Granular recovery allows restoring a specific, narrow subset of data (like one table's recent transactions) without the time and resource cost of a full bulk restore."}, {"obj": "3.3", "q": "A backup administrator actually restores a sample file from last night's backup to confirm it can genuinely be used, rather than trusting a 'success' status report alone. What practice is this?", "c": ["Backup integrity testing only", "Backup recoverability testing", "Backup replication", "Granular recovery only, unrelated to testing"], "a": 1, "e": "Backup recoverability testing involves actually restoring data to confirm it is truly usable, since a reported success doesn't guarantee the data is actually restorable."}, {"obj": "4.3", "q": "Select the most accurate description of \"OpenID Connect\":", "c": ["Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.", "An identity layer built on top of OAuth 2.0 used for authentication (proving who you are).", "Granting permissions based on a user's assigned role rather than to each individual directly.", "A graphical, browser-based interface for managing cloud resources."], "a": 1, "e": "An identity layer built on top of OAuth 2.0 used for authentication (proving who you are). Widely used for consumer and enterprise single sign-on into cloud applications."}, {"obj": "4.4", "q": "Which of the following best describes \"Unprivileged Container\"?", "c": ["Controls governing which files and directories a container process can read or write.", "A container running with restricted access, isolated from the host's sensitive resources.", "A set of vendor-neutral, consensus-based configuration hardening guidelines.", "Access controls and encryption settings applied to object storage buckets/containers."], "a": 1, "e": "A container running with restricted access, isolated from the host's sensitive resources. The safer default for container security, limiting the impact of a container-level compromise."}, {"obj": "1.6", "q": "Given the description \"Temporary storage tied to a container's lifecycle that is lost when the container stops.\", which term is being defined?", "c": ["Ephemeral Storage", "Image Registry", "Persistent Volume", "Stand-Alone Container"], "a": 0, "e": "\"Temporary storage tied to a container's lifecycle that is lost when the container stops.\" describes Ephemeral Storage. Suitable only for temporary/scratch data since it disappears when the container is removed."}, {"obj": "6.2", "q": "Select the most accurate description of \"IP Scope Exhaustion\":", "c": ["Incorrect VLAN tagging causing traffic to be dropped or delivered to the wrong segment.", "Running out of available addresses within a defined IP range or subnet.", "A required network path that has not been defined in a route table.", "Domain Name System — resolves hostnames to IP addresses."], "a": 1, "e": "Running out of available addresses within a defined IP range or subnet. Prevents new resources from being provisioned with an address until the range is expanded or reclaimed."}, {"obj": "1.5", "q": "Which term best matches this description: \"A service the cloud provider fully operates (e.g., a managed database), removing the customer's operational burden.\"?", "c": ["Fan-Out", "Loosely Coupled Architecture", "Cloud-Provided Managed Service", "Microservices"], "a": 2, "e": "\"A service the cloud provider fully operates (e.g., a managed database), removing the customer's operational burden.\" describes Cloud-Provided Managed Service. Reduces administrative overhead at the cost of some control and customization."}, {"obj": "2.3", "q": "Which statement accurately describes \"Rehost\"?", "c": ["Moving workloads from one cloud provider or region to another.", "A migration strategy that moves an application to the cloud with minimal changes, also called lift and shift.", "A migration strategy that keeps a workload where it currently is, deferring migration.", "A migration strategy that decommissions an application no longer needed."], "a": 1, "e": "A migration strategy that moves an application to the cloud with minimal changes, also called lift and shift. The fastest migration approach but does not take advantage of cloud-native features."}, {"obj": "2.5", "q": "A company provisions redundant instances across two regions and configures automated failover to meet a strict uptime commitment to its customers. Which requirement category is primarily being addressed?", "c": ["Compute requirements", "Availability requirements", "Storage requirements", "Compliance requirements"], "a": 1, "e": "Deploying redundant instances with automated failover directly addresses availability requirements — the uptime and resiliency expectations for the workload."}, {"obj": "3.4", "q": "Given the description \"A software update addressing a specific bug or vulnerability.\", which term is being defined?", "c": ["Decommissioning — End of Support", "Major Update", "Ephemeral Data", "Patch"], "a": 3, "e": "\"A software update addressing a specific bug or vulnerability.\" describes Patch. Applying patches promptly closes known security gaps before they can be exploited."}, {"obj": "5.2", "q": "Which of the following terms fits this definition: \"Automatically running tests against code as part of the pipeline.\"?", "c": ["VM Image Artifact", "Code Deployment", "CI/CD Testing", "CI/CD Security"], "a": 2, "e": "\"Automatically running tests against code as part of the pipeline.\" describes CI/CD Testing. Catches regressions before code reaches production, a core benefit of CI/CD."}, {"obj": "4.3", "q": "In Cloud+ terminology, \"SAML\" is an abbreviation for which of the following?", "c": ["Secure Shell", "Security Assertion Markup Language", "Application Programming Interface", "Network Time Protocol"], "a": 1, "e": "SAML stands for Security Assertion Markup Language. An XML-based standard for exchanging authentication and authorization data."}, {"obj": "1.3", "q": "\"Network Load Balancer\" is best defined as which of the following?", "c": ["A device or service that filters network traffic based on defined rules.", "Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management.", "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port.", "A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers)."], "a": 2, "e": "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port. Provides extremely high throughput and low latency for use cases where Layer 7 inspection isn't needed."}, {"obj": "5.3", "q": "Why does this matter on the exam and in practice? \"The most common style for modern web APIs due to its simplicity and statelessness.\" — which term does this explain?", "c": ["Web Sockets", "GraphQL", "REST", "RPC"], "a": 2, "e": "The most common style for modern web APIs due to its simplicity and statelessness. This describes REST (\"Representational State Transfer — an architectural style for web services using standard HTTP methods.\")."}, {"obj": "1.7", "q": "Given the description \"A rule keeping specific VMs running on the same (or different) physical host.\", which term is being defined?", "c": ["Hardware Pass-Through", "Clustering", "Overlay Network", "Host Affinity"], "a": 3, "e": "\"A rule keeping specific VMs running on the same (or different) physical host.\" describes Host Affinity. Used to keep related VMs together for performance, or apart for redundancy (anti-affinity)."}, {"obj": "6.3", "q": "Which term is most closely associated with this real-world importance: \"A very common real-world cause of cloud breaches, often via credentials accidentally committed to source control.\"?", "c": ["Cipher Suite Deprecation", "Leaked Credentials", "Software Vulnerability Issues", "Unauthorized Access"], "a": 1, "e": "A very common real-world cause of cloud breaches, often via credentials accidentally committed to source control. This describes Leaked Credentials (\"Authentication credentials that have been exposed, such as in code repositories or logs.\")."}, {"obj": "5.1", "q": "Which of the following actions directly makes a developer's local changes visible to the rest of the team for the first time?", "c": ["A local commit only", "A push to the shared remote repository", "Opening a code editor", "Writing a comment in the code"], "a": 1, "e": "A push uploads local commits to the shared remote repository, which is the point at which the changes become visible to the rest of the team."}, {"obj": "4.2", "q": "A colleague says: \"A common compliance report requested by customers evaluating a cloud vendor's security posture.\" Which concept are they describing?", "c": ["Data Ownership", "Contractual Retention", "ISO 27001", "SOC2"], "a": 3, "e": "A common compliance report requested by customers evaluating a cloud vendor's security posture. This describes SOC2 (\"Systems and Organization Controls 2 — an audit framework evaluating a service provider's controls around security, availability, and confidentiality.\")."}, {"obj": "1.7", "q": "Which of the following terms fits this definition: \"The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network.\"?", "c": ["Hardware Pass-Through", "VM Network", "SAN (Virtualization Context)", "Cloning"], "a": 1, "e": "\"The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network.\" describes VM Network. Determines how a VM communicates with other VMs, the host, and external networks."}, {"obj": "1.10", "q": "How would you most accurately define \"Storage Throughput\"?", "c": ["The actual amount of data successfully transferred over a network connection in a given time.", "The rate of data transfer to/from a storage system, usually measured in MB/s or GB/s.", "Using virtual machines as the compute resource type for a workload.", "Using provider-operated services instead of self-managed infrastructure to reduce operational overhead."], "a": 1, "e": "The rate of data transfer to/from a storage system, usually measured in MB/s or GB/s. Important for workloads that move large volumes of data, like backups or media processing."}, {"obj": "3.4", "q": "An administrator explains the importance of a concept: \"Running unsupported resources leaves known vulnerabilities permanently unpatched.\" What concept is this?", "c": ["Patch", "Lifecycle Testing", "Decommissioning — End of Support", "Major Update"], "a": 2, "e": "Running unsupported resources leaves known vulnerabilities permanently unpatched. This describes Decommissioning — End of Support (\"Retiring or upgrading a resource because the vendor no longer provides support/patches for it.\")."}, {"obj": "1.3", "q": "Which term is most closely associated with this real-world importance: \"Provides a single ingress point for web applications with built-in security and traffic-shaping features.\"?", "c": ["SDN", "CDN", "Transit Gateway", "Application Gateway"], "a": 3, "e": "Provides a single ingress point for web applications with built-in security and traffic-shaping features. This describes Application Gateway (\"A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features.\")."}, {"obj": "4.3", "q": "\"Local User Authentication\" is best defined as which of the following?", "c": ["Authenticating with credentials stored directly on the system rather than a central directory.", "Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.", "Multifactor Authentication — requiring two or more independent verification factors to log in.", "Authentication using a temporary token issued after initial login, rather than resending credentials each time."], "a": 0, "e": "Authenticating with credentials stored directly on the system rather than a central directory. Simple but doesn't scale well and complicates centralized policy enforcement across many systems."}, {"obj": "4.6", "q": "A description reads: \"A departure from a system's established normal behavior pattern.\" Which term does this describe?", "c": ["Event Monitoring (Security)", "Metadata Attack", "Deviation from Baseline", "DDoS"], "a": 2, "e": "\"A departure from a system's established normal behavior pattern.\" describes Deviation from Baseline. A key signal used to detect anomalies that might indicate compromise or misuse."}, {"obj": "5.2", "q": "A team wants their build artifacts to be simple, unstructured files like a configuration script, without needing a full package manager format. What type of artifact fits this need?", "c": ["A container image artifact", "A flat file artifact", "A VM image artifact", "An RPM package"], "a": 1, "e": "A flat file artifact is a simple, unstructured file (like a script or config), sometimes all that's needed without a full package format."}, {"obj": "4.1", "q": "Which of the following terms fits this definition: \"Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities.\"?", "c": ["CVE", "Vulnerability Assessment", "Remediation", "Vulnerability Identification"], "a": 0, "e": "\"Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities.\" describes CVE. Provides a common reference so vulnerabilities can be tracked and discussed consistently across tools and vendors."}, {"obj": "1.6", "q": "A company scales a containerized web service from 3 to 15 instances during a traffic spike, then back down afterward, entirely automatically. What is enabling this behavior?", "c": ["Port mapping alone", "Workload orchestration with autoscaling policies", "An image registry", "Ephemeral storage configuration"], "a": 1, "e": "Workload orchestration platforms provide the automated scaling policies needed to add and remove container instances in response to demand."}, {"obj": "4.4", "q": "\"Secrets Management\" is best defined as which of the following?", "c": ["Securely storing and controlling access to credentials, API keys, and other sensitive configuration values.", "Practices and controls that protect APIs from abuse, unauthorized access, and attack.", "A container running with restricted access, isolated from the host's sensitive resources.", "Granting only the minimum access rights needed to perform a function."], "a": 0, "e": "Securely storing and controlling access to credentials, API keys, and other sensitive configuration values. Prevents secrets from being hardcoded in source code or exposed in plaintext configuration files."}, {"obj": "6.3", "q": "Which of the following best describes \"Privilege Escalation (Troubleshooting)\"?", "c": ["Authentication credentials that have been exposed, such as in code repositories or logs.", "An identity gaining higher access than originally granted, often through a flaw or misconfiguration.", "Problems arising from unpatched or improperly configured software containing known weaknesses.", "Access to a system or data by someone without proper permission."], "a": 1, "e": "An identity gaining higher access than originally granted, often through a flaw or misconfiguration. A critical security troubleshooting concern after any suspected compromise of a low-privilege account."}, {"obj": "5.2", "q": "In Cloud+ terminology, \"RPM\" is an abbreviation for which of the following?", "c": ["Internet Service Provider", "Red Hat Package Manager", "Software Development Kit", "Network Attached Storage"], "a": 1, "e": "RPM stands for Red Hat Package Manager. A package format used for installing software on RPM-based Linux distributions."}, {"obj": "4.2", "q": "A colleague says: \"May require data to be kept longer (or shorter) than the organization's default policy.\" Which concept are they describing?", "c": ["PCI DSS", "Litigation Hold", "Contractual Retention", "Data Locality"], "a": 2, "e": "May require data to be kept longer (or shorter) than the organization's default policy. This describes Contractual Retention (\"A data retention requirement specified in a contract with a customer or partner.\")."}, {"obj": "3.3", "q": "Why does this matter on the exam and in practice? \"Saves time when only a small subset of data (like one accidentally deleted file) needs to be restored.\" — which term does this explain?", "c": ["Backup Schedule", "Granular Recovery", "Differential Backup", "Full Backup"], "a": 1, "e": "Saves time when only a small subset of data (like one accidentally deleted file) needs to be restored. This describes Granular Recovery (\"Restoring individual files or specific data items rather than an entire dataset.\")."}, {"obj": "4.5", "q": "A company defines rules specifying exactly which actions a given cloud identity is allowed or denied to perform on specific resources. What are these rules called?", "c": ["Network ACLs", "IAM policies", "WAF rules", "DDoS protection rules"], "a": 1, "e": "IAM policies define what actions a given identity is allowed or denied to perform on cloud resources, the core mechanism for enforcing least privilege."}, {"obj": "6.2", "q": "How would you most accurately define \"NAT (Troubleshooting)\"?", "c": ["A required network path that has not been defined in a route table.", "Network Time Protocol — synchronizes system clocks across a network.", "Network Address Translation — translates private addresses to a public address for routing.", "Running out of available addresses within a defined IP range or subnet."], "a": 2, "e": "Network Address Translation — translates private addresses to a public address for routing. Misconfigured NAT/port forwarding is a common cause of unreachable services behind a private network."}, {"obj": "2.3", "q": "A company heavily relies on a specific cloud provider's proprietary managed services and finds it prohibitively expensive and complex to move to another provider. What risk does this illustrate?", "c": ["Cloud bursting", "Vendor lock-in", "Cloud-native design", "Rightsizing"], "a": 1, "e": "Vendor lock-in describes the difficulty of moving away from a provider due to reliance on their proprietary services, a key risk consideration in migration planning."}, {"obj": "1.11", "q": "An administrator explains the importance of a concept: \"Powers use cases like content moderation, quality inspection, and security monitoring.\" What concept is this?", "c": ["IoT Gateway", "Machine Learning", "IoT Communication", "Visual Recognition"], "a": 3, "e": "Powers use cases like content moderation, quality inspection, and security monitoring. This describes Visual Recognition (\"AI technology that identifies objects, scenes, or features within images or video.\")."}, {"obj": "5.1", "q": "Which of the following terms fits this definition: \"Having other team members examine proposed code changes before they are merged.\"?", "c": ["Code Review", "Code Push", "Code Merge", "Branch Management"], "a": 0, "e": "\"Having other team members examine proposed code changes before they are merged.\" describes Code Review. Catches bugs, security issues, and design problems before they reach production."}, {"obj": "1.10", "q": "Why does this matter on the exam and in practice? \"A critical factor when placing workloads and choosing regions/AZs for latency-sensitive applications.\" — which term does this explain?", "c": ["Network Latency", "Compute Optimization (VM)", "Managed Services (Optimization)", "Network Throughput"], "a": 0, "e": "A critical factor when placing workloads and choosing regions/AZs for latency-sensitive applications. This describes Network Latency (\"The time delay for data to travel between two points on a network.\")."}, {"obj": "4.2", "q": "Which term is most closely associated with this real-world importance: \"Any cloud workload that stores, processes, or transmits card data must meet these requirements.\"?", "c": ["Data Ownership", "Data Sovereignty", "PCI DSS", "Data Locality"], "a": 2, "e": "Any cloud workload that stores, processes, or transmits card data must meet these requirements. This describes PCI DSS (\"Payment Card Industry Data Security Standard — security requirements for handling payment card data.\")."}, {"obj": "1.11", "q": "Select the most accurate description of \"Voice-to-Text\":", "c": ["Lightweight protocols (like MQTT or CoAP) designed for constrained IoT devices and networks.", "AI models that create new content (text, images, code) based on learned patterns.", "AI technology that converts written text into spoken audio (speech synthesis).", "AI technology that converts spoken audio into written text (speech recognition)."], "a": 3, "e": "AI technology that converts spoken audio into written text (speech recognition). Powers transcription services, voice assistants, and accessibility features."}, {"obj": "3.1", "q": "Given the description \"The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.\", which term is being defined?", "c": ["Alert Triage", "Log Aggregation", "Monitoring Metrics", "Alert Response"], "a": 0, "e": "\"The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.\" describes Alert Triage. Prevents alert fatigue and ensures the most critical issues are addressed first."}, {"obj": "4.4", "q": "A team disables unused network services, closes unnecessary ports, and removes default accounts on every new VM image before it's used in production. What practice is this?", "c": ["Secrets management", "Hardening", "API security", "Least privilege enforcement only"], "a": 1, "e": "Hardening reduces a system's attack surface by disabling unnecessary services, closing unused ports, and removing default accounts, exactly as described."}, {"obj": "2.1", "q": "A retailer wants to keep sensitive payment processing on dedicated private infrastructure while running its public-facing marketing website on cheaper, publicly shared cloud resources. What deployment approach does this represent?", "c": ["Pure private cloud", "Hybrid cloud, using private infrastructure for sensitive workloads and public cloud for the rest", "Pure public cloud", "Pure community cloud"], "a": 1, "e": "Splitting workloads between dedicated private infrastructure for sensitive processing and public cloud for less sensitive functions is a hybrid cloud approach."}, {"obj": "4.2", "q": "Given the description \"A data retention requirement mandated by law or industry regulation.\", which term is being defined?", "c": ["ISO 27001", "Data Sovereignty", "Cloud Security Alliance", "Regulatory Retention"], "a": 3, "e": "\"A data retention requirement mandated by law or industry regulation.\" describes Regulatory Retention. Non-compliance can result in legal penalties, distinct from purely internal retention preferences."}, {"obj": "3.4", "q": "Which of the following terms fits this definition: \"Temporary data that does not need to persist beyond a session or process.\"?", "c": ["Ephemeral Data", "Persistent Data", "Decommissioning — End of Support", "Decommissioning — End of Life"], "a": 0, "e": "\"Temporary data that does not need to persist beyond a session or process.\" describes Ephemeral Data. Doesn't require the same backup/retention rigor as persistent data."}, {"obj": "4.3", "q": "A company implements single sign-on into a SaaS application using an XML-based standard for exchanging authentication assertions between their identity provider and the application. Which technology is this?", "c": ["OAuth 2.0", "SAML", "RDP", "CLI-based authentication"], "a": 1, "e": "SAML is an XML-based standard commonly used to implement federated single sign-on between an identity provider and a service."}, {"obj": "2.1", "q": "A description reads: \"Infrastructure shared by several organizations with common concerns such as compliance or security requirements.\" Which term does this describe?", "c": ["Hybrid Cloud", "Community Cloud", "Private Cloud", "On Premises"], "a": 1, "e": "\"Infrastructure shared by several organizations with common concerns such as compliance or security requirements.\" describes Community Cloud. Balances shared cost benefits with more tailored governance than a general public cloud."}, {"obj": "6.3", "q": "An investigation finds that a developer accidentally committed API keys to a public code repository, leading to unauthorized cloud resource usage days later. What is the root cause?", "c": ["Privilege escalation", "Leaked credentials", "Cipher suite deprecation", "Software vulnerability issues"], "a": 1, "e": "Leaked credentials exposed in places like public repositories are a very common real-world cause of cloud account compromise and unauthorized usage."}, {"obj": "6.1", "q": "A newly provisioned instance runs a memory-intensive application extremely slowly because the chosen instance type has far less RAM than the workload actually requires. What is the underlying cause?", "c": ["A sizing issue (undersized instance type)", "API throttling", "Regional service availability", "Outdated component definitions"], "a": 0, "e": "Choosing an instance type that is too small for the workload's actual requirements is a sizing issue, directly causing poor performance."}, {"obj": "4.2", "q": "What does the abbreviation \"PCI\" stand for?", "c": ["Access Control List", "Internet Service Provider", "Payment Card Industry", "Information Technology Infrastructure Library"], "a": 2, "e": "PCI stands for Payment Card Industry. The industry group whose standards govern the security of payment card data."}, {"obj": "4.5", "q": "Given the description \"A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs.\", which term is being defined?", "c": ["IAM Policies", "Endpoint Protection", "DDoS Protection", "Network Security Group"], "a": 3, "e": "\"A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs.\" describes Network Security Group. The primary mechanism for instance-level network access control in most cloud platforms."}, {"obj": "1.11", "q": "Given the description \"A device that aggregates and relays data from multiple IoT sensors to the cloud.\", which term is being defined?", "c": ["IoT Gateway", "Voice-to-Text", "Generative AI", "Visual Recognition"], "a": 0, "e": "\"A device that aggregates and relays data from multiple IoT sensors to the cloud.\" describes IoT Gateway. Reduces the number of direct cloud connections needed and can perform local pre-processing."}, {"obj": "4.2", "q": "A prospective enterprise customer asks a SaaS vendor for independent third-party assurance regarding the vendor's security, availability, and confidentiality controls before signing a contract. What should the vendor provide?", "c": ["A CVE report", "A SOC 2 report", "A litigation hold notice", "A data classification policy document only"], "a": 1, "e": "A SOC 2 report is an independent audit specifically evaluating a service provider's controls around security, availability, and confidentiality, commonly requested by prospective customers."}, {"obj": "1.3", "q": "What does the abbreviation \"TCP\" stand for?", "c": ["Domain Name System", "Transmission Control Protocol", "Continuous Integration/Continuous Deployment", "Common Vulnerabilities and Exposures"], "a": 1, "e": "TCP stands for Transmission Control Protocol. A connection-oriented transport protocol that guarantees reliable, ordered delivery."}, {"obj": "6.2", "q": "Which term best matches this description: \"Dynamic Host Configuration Protocol — automatically assigns IP addressing information to hosts.\"?", "c": ["Misconfigured Route", "Network Overlap", "DHCP (Troubleshooting)", "Missing Route"], "a": 2, "e": "\"Dynamic Host Configuration Protocol — automatically assigns IP addressing information to hosts.\" describes DHCP (Troubleshooting). A failed DHCP service can leave hosts without any usable network configuration."}, {"obj": "2.4", "q": "Which of the following terms fits this definition: \"Managing system or application configuration through code rather than manual configuration.\"?", "c": ["Configuration as Code", "Infrastructure as Code", "IaC Versioning", "YAML"], "a": 0, "e": "\"Managing system or application configuration through code rather than manual configuration.\" describes Configuration as Code. Ensures configuration consistency across environments and enables automated drift correction."}, {"obj": "1.9", "q": "Which term is most closely associated with this real-world importance: \"Better suited for unstructured/semi-structured data and workloads needing horizontal scalability.\"?", "c": ["Relational Database", "Self-Managed Database", "Provider-Managed Database", "Non-Relational Database"], "a": 3, "e": "Better suited for unstructured/semi-structured data and workloads needing horizontal scalability. This describes Non-Relational Database (\"A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs.\")."}, {"obj": "2.4", "q": "Which of the following is the correct expansion of \"JSON\"?", "c": ["Internet Small Computer System Interface", "Create, Read, Update, Delete", "Logical Unit Number", "JavaScript Object Notation"], "a": 3, "e": "JSON stands for JavaScript Object Notation. A lightweight, structured data format commonly used for APIs and IaC templates."}, {"obj": "6.3", "q": "How would you most accurately define \"Unauthorized Software\"?", "c": ["Access to a system or data by someone without proper permission.", "Software installed or running without proper approval, increasing risk and potentially breaching policy.", "A connectivity/security failure caused by relying on an outdated, no-longer-supported encryption cipher suite.", "An identity gaining higher access than originally granted, often through a flaw or misconfiguration."], "a": 1, "e": "Software installed or running without proper approval, increasing risk and potentially breaching policy. Can introduce vulnerabilities, malware, or licensing violations into an otherwise controlled environment."}, {"obj": "5.4", "q": "Which term best matches this description: \"A platform for building, running, and managing containers.\"?", "c": ["Kubernetes", "Ansible", "Docker", "ELK Stack"], "a": 2, "e": "\"A platform for building, running, and managing containers.\" describes Docker. The most widely used container runtime and image format in modern DevOps workflows."}, {"obj": "2.4", "q": "Which of the following best describes \"IaC Versioning\"?", "c": ["Tracking changes to infrastructure code over time using version control.", "JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates.", "Validating infrastructure code for syntax, security, and logic before it is applied to real environments.", "Identifying when a deployed resource's actual state no longer matches its defined IaC configuration."], "a": 0, "e": "Tracking changes to infrastructure code over time using version control. Enables rollback to a known-good configuration and provides an audit trail of infrastructure changes."}, {"obj": "3.3", "q": "Which term best matches this description: \"Actually restoring backup data to confirm it can be used successfully.\"?", "c": ["Granular Recovery", "Full Backup", "Backup Retention (Ops)", "Backup Recoverability Testing"], "a": 3, "e": "\"Actually restoring backup data to confirm it can be used successfully.\" describes Backup Recoverability Testing. A backup reporting \"success\" does not guarantee the data is truly restorable — testing closes that gap."}, {"obj": "4.4", "q": "How would you most accurately define \"CIS Benchmark\"?", "c": ["Securely storing and controlling access to credentials, API keys, and other sensitive configuration values.", "A security model that assumes no user or device should be trusted by default, even inside the network perimeter.", "Practices and controls that protect APIs from abuse, unauthorized access, and attack.", "A set of vendor-neutral, consensus-based configuration hardening guidelines."], "a": 3, "e": "A set of vendor-neutral, consensus-based configuration hardening guidelines. Provides a well-known, widely adopted baseline for hardening systems and cloud services."}, {"obj": "1.11", "q": "A description reads: \"AI models that create new content (text, images, code) based on learned patterns.\" Which term does this describe?", "c": ["IoT Communication", "Voice-to-Text", "Generative AI", "IoT Transmission Protocol"], "a": 2, "e": "\"AI models that create new content (text, images, code) based on learned patterns.\" describes Generative AI. A rapidly growing category of cloud AI services used for content creation and code assistance."}, {"obj": "1.9", "q": "A description reads: \"A database that organizes data into structured tables with defined relationships (SQL).\" Which term does this describe?", "c": ["Relational Database", "Self-Managed Database", "Non-Relational Database", "Provider-Managed Database"], "a": 0, "e": "\"A database that organizes data into structured tables with defined relationships (SQL).\" describes Relational Database. Best suited for structured data requiring strong consistency and complex queries/joins."}, {"obj": "1.8", "q": "A company runs a steady-state database workload 24/7 for the foreseeable future and wants to minimize cost through a committed-term discount. What pricing model fits best?", "c": ["Spot instances", "Reserved resources", "Pay-as-you-go", "Dedicated host billing"], "a": 1, "e": "Reserved resources offer a discount in exchange for a committed term, ideal for predictable, always-on workloads like a steady-state database."}, {"obj": "3.1", "q": "A company needs its incident response team to have documented steps that specify exactly what to do when a specific alert fires, including who to notify and what commands to run. What should be created?", "c": ["A monitoring dashboard only", "An alert response runbook/procedure", "A log retention policy only", "A tracing configuration only"], "a": 1, "e": "A documented alert response procedure (runbook) turns detection into a clear, repeatable resolution process rather than leaving responders to improvise."}, {"obj": "1.11", "q": "Which concept is described by the phrase: \"Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case.\"?", "c": ["Machine Learning", "Generative AI", "IoT Sensor", "Text Translation"], "a": 0, "e": "\"Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case.\" describes Machine Learning. Underpins many modern cloud AI services such as recommendation engines and fraud detection."}, {"obj": "2.1", "q": "A hospital must keep patient data on infrastructure it fully owns and controls due to regulatory concerns, but wants to burst analytics workloads to a public provider occasionally. Which model fits?", "c": ["Public cloud only", "Private cloud only", "Hybrid cloud", "Community cloud"], "a": 2, "e": "Hybrid cloud combines dedicated private/on-premises infrastructure with public cloud resources for occasional burst workloads."}, {"obj": "2.3", "q": "Select the most accurate description of \"On-Premises-to-Cloud Migration\":", "c": ["Moving workloads out of the cloud back to local infrastructure.", "A migration strategy that keeps a workload where it currently is, deferring migration.", "A migration strategy that substantially redesigns an application to be cloud-native.", "Moving workloads from local infrastructure into a cloud environment."], "a": 3, "e": "Moving workloads from local infrastructure into a cloud environment. The most common migration type when organizations first adopt cloud computing."}, {"obj": "6.1", "q": "Which of the following terms fits this definition: \"Incorrectly assigned CPU, memory, or storage limits for a workload.\"?", "c": ["Resource Allocation Misconfiguration", "Sizing Issues", "Incompatibility (Deployment)", "Service Quota"], "a": 0, "e": "\"Incorrectly assigned CPU, memory, or storage limits for a workload.\" describes Resource Allocation Misconfiguration. Can cause performance problems or outright deployment failure if requested resources aren't actually available."}, {"obj": "2.3", "q": "A description reads: \"Moving workloads from one cloud provider or region to another.\" Which term does this describe?", "c": ["Vendor Lock-In", "Refactor", "Replatform", "Cloud-to-Cloud Migration"], "a": 3, "e": "\"Moving workloads from one cloud provider or region to another.\" describes Cloud-to-Cloud Migration. Often driven by cost optimization, feature needs, or avoiding vendor lock-in."}, {"obj": "1.6", "q": "A stateful containerized application loses all its data every time the container restarts, even though the team expected data to persist. What is the most likely misconfiguration?", "c": ["The image registry was set to private", "No persistent volume was attached; the container relied on its own ephemeral filesystem", "Port mapping was left enabled", "Workload orchestration was not disabled"], "a": 1, "e": "Without a properly attached persistent volume, container data resides only in the ephemeral container filesystem, which is lost on restart."}, {"obj": "4.2", "q": "A description reads: \"Defining who legally owns and controls a given set of data.\" Which term does this describe?", "c": ["Data Ownership", "SOC2", "Regulatory Retention", "PCI DSS"], "a": 0, "e": "\"Defining who legally owns and controls a given set of data.\" describes Data Ownership. Clarifies responsibility and rights when data is stored or processed by a third-party cloud provider."}, {"obj": "4.2", "q": "An administrator explains the importance of a concept: \"May require data to be kept longer (or shorter) than the organization's default policy.\" What concept is this?", "c": ["Data Sovereignty", "Contractual Retention", "SOC2", "Data Ownership"], "a": 1, "e": "May require data to be kept longer (or shorter) than the organization's default policy. This describes Contractual Retention (\"A data retention requirement specified in a contract with a customer or partner.\")."}, {"obj": "3.3", "q": "Why does this matter on the exam and in practice? \"Ensures the backup itself is trustworthy before it's ever relied upon during an actual incident.\" — which term does this explain?", "c": ["Backup Replication", "Backup Integrity Testing", "Bulk Recovery", "Backup Recoverability Testing"], "a": 1, "e": "Ensures the backup itself is trustworthy before it's ever relied upon during an actual incident. This describes Backup Integrity Testing (\"Verifying that backed-up data has not been corrupted.\")."}, {"obj": "6.1", "q": "Which statement accurately describes \"Outdated Component Definitions\"?", "c": ["A previously available feature or API being retired by the provider.", "IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated.", "A failure caused by mismatched software, hardware, or configuration versions.", "A provider intentionally limiting the rate of API calls a customer can make."], "a": 1, "e": "IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated. Leads to deployment failures when the referenced component is no longer valid on the platform."}, {"obj": "5.2", "q": "Which statement accurately describes \"Private Repository\"?", "c": ["Automatically running tests against code as part of the pipeline.", "A code or artifact repository restricted to authorized users/systems.", "A packaged virtual machine image produced and stored as a build output.", "Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions."], "a": 1, "e": "A code or artifact repository restricted to authorized users/systems. The standard choice for proprietary source code and internal build artifacts."}, {"obj": "1.1", "q": "A company is deciding between IaaS and SaaS for a new HR system. Which factor would most strongly favor choosing SaaS?", "c": ["The need for full control over the operating system", "A desire for the fastest time-to-value with minimal internal IT management", "A requirement to install custom kernel modules", "A need to manage physical hardware directly"], "a": 1, "e": "SaaS is fully managed by the vendor, offering the fastest time-to-value when the organization does not need deep customization or infrastructure control."}, {"obj": "4.3", "q": "Which of the following terms fits this definition: \"Accessing cloud resources via code rather than a human using a GUI (API/SDK).\"?", "c": ["Directory-Based Authentication", "Group-Based Access Control", "OpenID Connect", "Programmatic Access"], "a": 3, "e": "\"Accessing cloud resources via code rather than a human using a GUI (API/SDK).\" describes Programmatic Access. Enables automation but requires careful credential management since keys can be leaked or misused."}, {"obj": "3.2", "q": "Which statement accurately describes \"Vertical Scaling\"?", "c": ["Increasing the resources (CPU/RAM) of an existing instance (scale up).", "Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU).", "Scaling resources up or down at predefined times based on known usage patterns.", "Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%)."], "a": 0, "e": "Increasing the resources (CPU/RAM) of an existing instance (scale up). Simpler than horizontal scaling but has an upper limit and usually requires downtime or a reboot."}, {"obj": "2.5", "q": "\"Storage Requirements\" is best defined as which of the following?", "c": ["The capacity, performance, and durability needs a workload has for its data.", "The bandwidth, latency, and connectivity needs of a workload.", "The uptime and resiliency expectations for a workload.", "Legal or regulatory obligations a workload's data and processing must meet."], "a": 0, "e": "The capacity, performance, and durability needs a workload has for its data. Must be assessed before provisioning to choose the right storage type and tier."}, {"obj": "3.4", "q": "Which term best matches this description: \"A software update addressing a specific bug or vulnerability.\"?", "c": ["Minor Update", "Patch", "Decommissioning — End of Support", "Ephemeral Data"], "a": 1, "e": "\"A software update addressing a specific bug or vulnerability.\" describes Patch. Applying patches promptly closes known security gaps before they can be exploited."}, {"obj": "5.4", "q": "A description reads: \"A widely used open-source automation server for building CI/CD pipelines.\" Which term does this describe?", "c": ["ELK Stack", "Kubernetes", "Jenkins", "Terraform"], "a": 2, "e": "\"A widely used open-source automation server for building CI/CD pipelines.\" describes Jenkins. One of the most established tools for orchestrating build, test, and deployment automation."}, {"obj": "4.6", "q": "Select the most accurate description of \"Phishing\":", "c": ["An attack that succeeds because a system was running software with a known, unpatched vulnerability.", "A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email.", "A departure from a system's established normal behavior pattern.", "An attack that succeeds due to a mistake made by an authorized user (misconfiguration, mishandling credentials, etc.)."], "a": 1, "e": "A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email. One of the most common initial access vectors used in real-world breaches."}, {"obj": "4.4", "q": "A colleague says: \"Misconfigured permissions inside a container can let an attacker access or modify data they shouldn't.\" Which concept are they describing?", "c": ["API Security", "Container File Access Permissions", "Data at Rest Encryption", "Object Storage Security"], "a": 1, "e": "Misconfigured permissions inside a container can let an attacker access or modify data they shouldn't. This describes Container File Access Permissions (\"Controls governing which files and directories a container process can read or write.\")."}, {"obj": "5.3", "q": "A description reads: \"A protocol providing full-duplex, persistent communication channels over a single TCP connection.\" Which term does this describe?", "c": ["Web Sockets", "GraphQL", "Event-Driven Architecture", "SOAP"], "a": 0, "e": "\"A protocol providing full-duplex, persistent communication channels over a single TCP connection.\" describes Web Sockets. Enables real-time, bidirectional communication like chat apps or live dashboards, unlike typical request/response HTTP."}, {"obj": "5.3", "q": "\"GraphQL\" is best defined as which of the following?", "c": ["Simple Object Access Protocol — an XML-based messaging protocol for web services.", "A query language for APIs that lets clients request exactly the data they need.", "Representational State Transfer — an architectural style for web services using standard HTTP methods.", "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local."], "a": 1, "e": "A query language for APIs that lets clients request exactly the data they need. Reduces over-fetching/under-fetching of data compared to traditional REST endpoints."}, {"obj": "6.2", "q": "Which concept is described by the phrase: \"Domain Name System — resolves hostnames to IP addresses.\"?", "c": ["DHCP (Troubleshooting)", "Protocol Deprecation", "Protocol Incompatibility", "DNS (Troubleshooting)"], "a": 3, "e": "\"Domain Name System — resolves hostnames to IP addresses.\" describes DNS (Troubleshooting). DNS failures cause connectivity issues that look like the destination is down, even when it's reachable by IP."}, {"obj": "5.4", "q": "Why does this matter on the exam and in practice? \"Lets teams define build/test/deploy pipelines directly alongside their code in GitHub.\" — which term does this explain?", "c": ["Terraform", "Kubernetes", "GitHub Actions", "Docker"], "a": 2, "e": "Lets teams define build/test/deploy pipelines directly alongside their code in GitHub. This describes GitHub Actions (\"A CI/CD automation feature built into GitHub for running workflows in response to repository events.\")."}, {"obj": "1.4", "q": "Which of the following terms fits this definition: \"A storage tier for infrequently accessed data, offering lower cost with slower retrieval.\"?", "c": ["File Storage", "SSD", "Cold Storage Tier", "HDD"], "a": 2, "e": "\"A storage tier for infrequently accessed data, offering lower cost with slower retrieval.\" describes Cold Storage Tier. Suitable for older backups or compliance data that is rarely, but occasionally, needed."}, {"obj": "4.2", "q": "A company operating in multiple countries must determine which country's data protection laws apply to a given customer's data based on where it is physically stored. What concept is most directly relevant?", "c": ["Data ownership", "Data sovereignty", "SOC 2 auditing", "Contractual retention"], "a": 1, "e": "Data sovereignty determines which country's laws apply based on the physical location of the data, which is exactly the determination this multinational company must make."}, {"obj": "3.1", "q": "Select the most accurate description of \"Log Aggregation\":", "c": ["Gathering log data from applications, systems, and services into a central location.", "Defining how long log data is kept before being archived or deleted.", "Combining logs from many sources into a unified, searchable view.", "Following a single request as it moves through multiple services in a distributed system."], "a": 2, "e": "Combining logs from many sources into a unified, searchable view. Enables correlation across services, which is essential for diagnosing distributed system issues."}, {"obj": "1.3", "q": "Two VPCs owned by the same company need to communicate privately without traversing the public internet. What should be configured?", "c": ["A public IP on each VPC", "VPC peering", "A CDN in front of both VPCs", "BGP with the ISP"], "a": 1, "e": "VPC peering creates a direct private connection between two VPCs, letting them communicate as if on the same network."}, {"obj": "1.10", "q": "A colleague says: \"Ensures workloads are placed, scaled, and healed automatically according to defined policies.\" Which concept are they describing?", "c": ["Compute Optimization (Container)", "Compute Optimization (VM)", "Orchestration (Workload)", "Storage Throughput"], "a": 2, "e": "Ensures workloads are placed, scaled, and healed automatically according to defined policies. This describes Orchestration (Workload) (\"Automated coordination of workload deployment, scaling, and lifecycle management.\")."}, {"obj": "2.4", "q": "In cloud computing terminology, \"YAML\" refers to which of the following?", "c": ["Validating infrastructure code for syntax, security, and logic before it is applied to real environments.", "JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates.", "Tracking changes to infrastructure code over time using version control.", "Yet Another Markup Language — a human-readable data format widely used for IaC and configuration files."], "a": 3, "e": "Yet Another Markup Language — a human-readable data format widely used for IaC and configuration files. The preferred format for tools like Kubernetes manifests and many CI/CD pipeline definitions."}, {"obj": "1.3", "q": "Two departments each have their own VPC and need to communicate privately without exposing traffic to the public internet, with no plan to add more VPCs in the future. What is the simplest solution?", "c": ["VPC peering", "A transit gateway", "A public load balancer", "A dedicated connection"], "a": 0, "e": "For a simple, direct connection between exactly two VPCs, peering is simpler than deploying a transit gateway, which is better suited for many-to-many connections."}, {"obj": "1.2", "q": "In cloud computing terminology, \"Multicloud Tenancy\" refers to which of the following?", "c": ["Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption.", "A partially equipped DR site that needs recent data restored before it can take over.", "Continuously checking that a resource or service is up and responding as expected.", "Using services from more than one public cloud provider simultaneously."], "a": 3, "e": "Using services from more than one public cloud provider simultaneously. Reduces vendor lock-in and can improve resilience, but increases operational and integration complexity."}, {"obj": "3.3", "q": "Which of the following terms fits this definition: \"Restoring data directly onto the original system/location.\"?", "c": ["Full Backup", "Parallel Recovery", "In-Place Recovery", "Backup Retention (Ops)"], "a": 2, "e": "\"Restoring data directly onto the original system/location.\" describes In-Place Recovery. The simplest recovery approach when the original infrastructure is still available and intact."}, {"obj": "3.1", "q": "Which term is most closely associated with this real-world importance: \"Critical for pinpointing where latency or errors occur across microservices.\"?", "c": ["Monitoring Metrics", "Tracing", "Log Retention", "Log Aggregation"], "a": 1, "e": "Critical for pinpointing where latency or errors occur across microservices. This describes Tracing (\"Following a single request as it moves through multiple services in a distributed system.\")."}, {"obj": "1.9", "q": "Which of the following best describes \"Relational Database\"?", "c": ["A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs.", "A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure.", "A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS).", "A database that organizes data into structured tables with defined relationships (SQL)."], "a": 3, "e": "A database that organizes data into structured tables with defined relationships (SQL). Best suited for structured data requiring strong consistency and complex queries/joins."}, {"obj": "1.2", "q": "Given the description \"A basic facility with power and space but no pre-installed equipment.\", which term is being defined?", "c": ["Cold Site", "RPO", "Cloud Bursting", "Availability Monitoring"], "a": 0, "e": "\"A basic facility with power and space but no pre-installed equipment.\" describes Cold Site. Cheapest DR option, but has by far the longest time to bring online."}, {"obj": "1.3", "q": "Why does this matter on the exam and in practice? \"A common way to connect on-premises networks or remote users securely to cloud resources.\" — which term does this explain?", "c": ["Network Load Balancer", "Application Load Balancer", "VPN", "Route Table"], "a": 2, "e": "A common way to connect on-premises networks or remote users securely to cloud resources. This describes VPN (\"Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network.\")."}, {"obj": "1.1", "q": "Which term best matches this description: \"A framework defining which security and operational tasks belong to the cloud provider versus the customer.\"?", "c": ["Shared Responsibility Model", "PaaS", "IaaS", "FaaS"], "a": 0, "e": "\"A framework defining which security and operational tasks belong to the cloud provider versus the customer.\" describes Shared Responsibility Model. Responsibility shifts up the stack as you move from IaaS to PaaS to SaaS — misunderstanding this is a common real-world security gap."}, {"obj": "4.6", "q": "\"Deviation from Baseline\" is best defined as which of the following?", "c": ["Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources.", "An attack that succeeds due to a mistake made by an authorized user (misconfiguration, mishandling credentials, etc.).", "A departure from a system's established normal behavior pattern.", "A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email."], "a": 2, "e": "A departure from a system's established normal behavior pattern. A key signal used to detect anomalies that might indicate compromise or misuse."}, {"obj": "4.5", "q": "A large volume of malicious traffic attempts to overwhelm a public-facing cloud application's bandwidth and availability. What control specifically mitigates this?", "c": ["DLP", "DDoS protection", "IAM policies", "A network ACL alone"], "a": 1, "e": "DDoS protection services specifically absorb or filter malicious traffic volumes designed to overwhelm a target, unlike controls focused on data leakage or access management."}, {"obj": "4.4", "q": "\"Principle of Least Privilege\" is best defined as which of the following?", "c": ["Granting only the minimum access rights needed to perform a function.", "Securely storing and controlling access to credentials, API keys, and other sensitive configuration values.", "A set of vendor-neutral, consensus-based configuration hardening guidelines.", "A security model that assumes no user or device should be trusted by default, even inside the network perimeter."], "a": 0, "e": "Granting only the minimum access rights needed to perform a function. Limits the potential damage if an account or service is compromised."}, {"obj": "1.2", "q": "A retailer wants to serve video content with minimal buffering to users across the country without deploying full application stacks in every region. What approach addresses this specific need?", "c": ["Deploying a full copy of the application in every region", "Using edge caching/edge computing for content delivery specifically, while keeping the core application centralized", "Using only a single availability zone", "Avoiding all forms of distributed infrastructure"], "a": 1, "e": "Edge computing/caching can address latency for specific content delivery needs without requiring a full application deployment in every region."}, {"obj": "6.1", "q": "In cloud computing terminology, \"Resource Allocation Misconfiguration\" refers to which of the following?", "c": ["A previously available feature or API being retired by the provider.", "IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated.", "Allocating more virtual resources than the underlying physical capacity can truly support.", "Incorrectly assigned CPU, memory, or storage limits for a workload."], "a": 3, "e": "Incorrectly assigned CPU, memory, or storage limits for a workload. Can cause performance problems or outright deployment failure if requested resources aren't actually available."}, {"obj": "1.11", "q": "Which statement accurately describes \"Sentiment Analysis\"?", "c": ["AI technology that identifies objects, scenes, or features within images or video.", "AI technology that determines the emotional tone (positive/negative/neutral) of text.", "Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case.", "A device that collects data from the physical environment (temperature, motion, etc.)."], "a": 1, "e": "AI technology that determines the emotional tone (positive/negative/neutral) of text. Used to analyze customer feedback, reviews, and social media at scale."}, {"obj": "1.5", "q": "Which benefit is most directly associated with breaking an application into microservices rather than keeping it as a single monolith?", "c": ["Guaranteed lower total infrastructure cost in every case", "Independent development, deployment, and scaling of individual components", "Elimination of the need for any networking between components", "Automatic conversion of all code to serverless functions"], "a": 1, "e": "Microservices allow each component to be developed, deployed, and scaled independently, which is their primary architectural benefit over a monolith."}, {"obj": "3.3", "q": "Which concept is described by the phrase: \"Restoring data directly onto the original system/location.\"?", "c": ["Backup Recoverability Testing", "In-Place Recovery", "Backup Retention (Ops)", "Incremental Backup"], "a": 1, "e": "\"Restoring data directly onto the original system/location.\" describes In-Place Recovery. The simplest recovery approach when the original infrastructure is still available and intact."}, {"obj": "4.5", "q": "Why does this matter on the exam and in practice? \"IDS alerts on suspicious activity; IPS goes further by actively blocking it in real time.\" — which term does this explain?", "c": ["Network Security Group", "DDoS Protection", "IPS/IDS", "DLP"], "a": 2, "e": "IDS alerts on suspicious activity; IPS goes further by actively blocking it in real time. This describes IPS/IDS (\"Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity.\")."}, {"obj": "4.3", "q": "\"CLI\" is best defined as which of the following?", "c": ["Secure Shell — an encrypted protocol for remote command-line access to cloud resources.", "An authorization framework that lets an application access resources on a user's behalf without sharing their password.", "Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources.", "Multifactor Authentication — requiring two or more independent verification factors to log in."], "a": 2, "e": "Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources. Popular for scripting and automation tasks that would be tedious through a web portal."}, {"obj": "6.1", "q": "Which concept is described by the phrase: \"A complete loss of service availability.\"?", "c": ["Regional Service Availability", "Outdated Component Definitions", "Full Outage", "Permission Issues (Deployment)"], "a": 2, "e": "\"A complete loss of service availability.\" describes Full Outage. Represents the most severe availability impact, prioritized above partial outages."}, {"obj": "1.3", "q": "Which concept is described by the phrase: \"A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers).\"?", "c": ["Network Load Balancer", "Application Load Balancer", "VPN", "CDN"], "a": 1, "e": "\"A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers).\" describes Application Load Balancer. Enables advanced routing such as sending /api traffic to one backend and /images to another."}, {"obj": "3.3", "q": "Select the most accurate description of \"Granular Recovery\":", "c": ["Restoring individual files or specific data items rather than an entire dataset.", "Restoring data to an alternate system running alongside the original.", "Verifying that backed-up data has not been corrupted.", "A complete copy of all selected data."], "a": 0, "e": "Restoring individual files or specific data items rather than an entire dataset. Saves time when only a small subset of data (like one accidentally deleted file) needs to be restored."}, {"obj": "1.7", "q": "Which of the following terms fits this definition: \"Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction.\"?", "c": ["Clustering", "Stand-Alone Virtualization", "Hardware Pass-Through", "Local Storage (Virtualization)"], "a": 2, "e": "\"Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction.\" describes Hardware Pass-Through. Used when a workload needs near-native performance from a specific device, like a GPU."}, {"obj": "4.5", "q": "Which of the following best describes \"DLP\"?", "c": ["Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic.", "Security software (antivirus, EDR) installed directly on servers, VMs, or devices.", "Access Control List — a set of rules controlling traffic in and out of a subnet at the network level.", "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data."], "a": 3, "e": "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data. Commonly blocks sensitive data like credit card numbers from leaving the network through channels like email."}, {"obj": "4.3", "q": "A company implements RBAC by assigning permissions to a 'Database Administrators' role rather than to each individual DBA directly. What benefit does this provide?", "c": ["It eliminates the need for any authentication", "It simplifies administration and enforces consistent access for everyone in the same job function", "It requires more manual configuration per user than assigning permissions individually", "It removes the need for auditing"], "a": 1, "e": "Role-based access control simplifies administration and ensures consistent access across all users sharing the same job function, rather than configuring permissions per individual."}, {"obj": "1.2", "q": "Which concept is described by the phrase: \"A partially equipped DR site that needs recent data restored before it can take over.\"?", "c": ["Warm Site", "Availability Zone", "Cloud Bursting", "Region"], "a": 0, "e": "\"A partially equipped DR site that needs recent data restored before it can take over.\" describes Warm Site. A middle-ground between cost and recovery speed compared to hot and cold sites."}, {"obj": "5.4", "q": "Which of the following terms fits this definition: \"A widely used open-source automation server for building CI/CD pipelines.\"?", "c": ["Grafana", "Git", "Terraform", "Jenkins"], "a": 3, "e": "\"A widely used open-source automation server for building CI/CD pipelines.\" describes Jenkins. One of the most established tools for orchestrating build, test, and deployment automation."}, {"obj": "1.5", "q": "A payment service publishes a single 'payment completed' event that is simultaneously consumed by inventory, shipping, and notification services. What pattern is this?", "c": ["Point-to-point synchronous calls", "Fan-out", "Tight coupling", "A monolithic call stack"], "a": 1, "e": "Fan-out distributes a single event to multiple downstream consumers simultaneously, a common event-driven microservices pattern."}, {"obj": "3.3", "q": "Which term best matches this description: \"Backs up all data changed since the last full backup.\"?", "c": ["Differential Backup", "Backup Recoverability Testing", "Backup Integrity Testing", "Backup Retention (Ops)"], "a": 0, "e": "\"Backs up all data changed since the last full backup.\" describes Differential Backup. Restores are simpler than incremental (just the full plus the latest differential), but each differential grows larger over time."}, {"obj": "1.9", "q": "Which of the following is a key operational benefit of using a provider-managed database over a self-managed one?", "c": ["Complete control over the underlying OS kernel", "Automatic patching, backups, and often built-in high availability managed by the provider", "Lower cost in every possible scenario", "No need for any data modeling"], "a": 1, "e": "Provider-managed databases typically include automated patching, backups, and high-availability features managed by the provider, reducing the customer's operational load."}, {"obj": "2.3", "q": "Which concept is described by the phrase: \"Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.\"?", "c": ["Replatform", "On-Premises-to-Cloud Migration", "Retire", "Vendor Lock-In"], "a": 3, "e": "\"Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.\" describes Vendor Lock-In. A key risk consideration when architecting for portability across multiple providers."}, {"obj": "2.1", "q": "Which of the following scenarios best justifies choosing a private cloud over a public cloud?", "c": ["The organization has no specific compliance or customization requirements", "The organization requires dedicated, highly customizable infrastructure and stricter control over its environment than shared multi-tenancy allows", "The organization wants the lowest possible cost with no dedicated resources", "The organization has no existing IT staff at all"], "a": 1, "e": "Private cloud is justified when an organization needs dedicated infrastructure and more control/customization than a shared, multi-tenant public cloud environment provides."}, {"obj": "1.1", "q": "A company wants to deploy a custom application but does not want to manage the underlying OS or runtime, only the application code. Which service model fits best?", "c": ["IaaS", "PaaS", "SaaS", "On-premises"], "a": 1, "e": "PaaS lets developers deploy code onto a managed runtime/platform, leaving OS and infrastructure management to the provider."}, {"obj": "6.2", "q": "In cloud computing terminology, \"Access vs. Trunk Ports\" refers to which of the following?", "c": ["Network Time Protocol — synchronizes system clocks across a network.", "Network Address Translation — translates private addresses to a public address for routing.", "A connectivity failure caused by a system relying on a protocol version the other side no longer supports.", "The distinction between a switch port carrying a single VLAN (access) versus multiple VLANs (trunk)."], "a": 3, "e": "The distinction between a switch port carrying a single VLAN (access) versus multiple VLANs (trunk). Misconfiguring one as the other is a common cause of VLAN connectivity problems."}, {"obj": "5.3", "q": "Given the description \"Representational State Transfer — an architectural style for web services using standard HTTP methods.\", which term is being defined?", "c": ["REST", "SOAP", "Event-Driven Architecture", "GraphQL"], "a": 0, "e": "\"Representational State Transfer — an architectural style for web services using standard HTTP methods.\" describes REST. The most common style for modern web APIs due to its simplicity and statelessness."}, {"obj": "1.10", "q": "Which statement accurately describes \"Managed Services (Optimization)\"?", "c": ["Using virtual machines as the compute resource type for a workload.", "The actual amount of data successfully transferred over a network connection in a given time.", "Using provider-operated services instead of self-managed infrastructure to reduce operational overhead.", "Using containers as the compute resource type for a workload."], "a": 2, "e": "Using provider-operated services instead of self-managed infrastructure to reduce operational overhead. Frees up staff time from routine maintenance so they can focus on higher-value work."}, {"obj": "5.3", "q": "A legacy enterprise system integration still relies on a rigid, XML-based contract between two systems that has not been modernized. What protocol is most likely in use?", "c": ["GraphQL", "SOAP", "Web sockets", "REST"], "a": 1, "e": "SOAP's rigid, XML-based formal contract is characteristic of older enterprise integrations that haven't been modernized to more flexible REST or GraphQL approaches."}, {"obj": "1.8", "q": "Which term is most closely associated with this real-world importance: \"Provides the raw usage data that billing and rightsizing decisions are based on.\"?", "c": ["Pay-As-You-Go", "Reserved Resources", "Resource Metering", "Spot Instance"], "a": 2, "e": "Provides the raw usage data that billing and rightsizing decisions are based on. This describes Resource Metering (\"Tracking actual consumption of cloud resources for billing and capacity planning purposes.\")."}, {"obj": "1.7", "q": "\"Local Storage (Virtualization)\" is best defined as which of the following?", "c": ["Storage physically attached to a single hypervisor host.", "Creating an exact copy of an existing VM.", "A rule keeping specific VMs running on the same (or different) physical host.", "Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction."], "a": 0, "e": "Storage physically attached to a single hypervisor host. Fast and simple but doesn't support live migration of VMs to other hosts without shared storage."}, {"obj": "1.1", "q": "\"FaaS\" is best defined as which of the following?", "c": ["Platform as a Service — provides a managed runtime/platform for developing and deploying applications without managing the underlying OS.", "Software as a Service — delivers a fully managed application to end users over the internet.", "Function as a Service — lets code run in response to events without provisioning or managing any server (serverless).", "A framework defining which security and operational tasks belong to the cloud provider versus the customer."], "a": 2, "e": "Function as a Service — lets code run in response to events without provisioning or managing any server (serverless). Billing is based on execution time/invocations rather than reserved capacity, ideal for event-driven workloads."}, {"obj": "5.2", "q": "Given the description \"Merging code changes from multiple contributors into a shared, continuously tested codebase.\", which term is being defined?", "c": ["Container Image Artifact", "Private Repository", "Code Integration", "CI/CD Workflow"], "a": 2, "e": "\"Merging code changes from multiple contributors into a shared, continuously tested codebase.\" describes Code Integration. The \"CI\" in CI/CD — frequent integration catches conflicts and bugs early."}, {"obj": "6.2", "q": "Given the description \"An incorrect entry in a route table sending traffic to the wrong destination.\", which term is being defined?", "c": ["NAT (Troubleshooting)", "DNS (Troubleshooting)", "DHCP (Troubleshooting)", "Misconfigured Route"], "a": 3, "e": "\"An incorrect entry in a route table sending traffic to the wrong destination.\" describes Misconfigured Route. Can cause traffic to be dropped, looped, or sent somewhere unintended."}, {"obj": "1.2", "q": "An administrator explains the importance of a concept: \"Reduces latency for time-sensitive applications like IoT and content delivery.\" What concept is this?", "c": ["Region", "Edge Computing", "Hot Site", "Availability Zone"], "a": 1, "e": "Reduces latency for time-sensitive applications like IoT and content delivery. This describes Edge Computing (\"Processing data physically close to where it is generated rather than in a centralized datacenter.\")."}, {"obj": "5.2", "q": "After a build passes all tests, the pipeline automatically releases it to the production environment with no manual steps required. What CI/CD stage is this?", "c": ["Code integration", "Build", "Code deployment", "Code review"], "a": 2, "e": "Code deployment releases built and tested code to a target environment, and automating this step reduces the risk and effort of releasing changes."}, {"obj": "4.3", "q": "In cloud computing terminology, \"Token-Based Authentication\" refers to which of the following?", "c": ["Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.", "An authorization framework that lets an application access resources on a user's behalf without sharing their password.", "A graphical, browser-based interface for managing cloud resources.", "Authentication using a temporary token issued after initial login, rather than resending credentials each time."], "a": 3, "e": "Authentication using a temporary token issued after initial login, rather than resending credentials each time. Reduces the exposure of long-term credentials and supports short-lived, revocable sessions."}, {"obj": "4.3", "q": "In Cloud+ terminology, \"VDI\" is an abbreviation for which of the following?", "c": ["Virtual Desktop Infrastructure", "Network Attached Storage", "Artificial Intelligence", "Security, Trust, Assurance, Risk"], "a": 0, "e": "VDI stands for Virtual Desktop Infrastructure. Hosting desktop operating systems on centralized servers, accessed remotely by users."}, {"obj": "1.8", "q": "A finance team wants to see cloud spend broken out by project and department. What should be applied to every resource first?", "c": ["Rightsizing", "Tagging", "Resource metering", "Reserved billing"], "a": 1, "e": "Tagging resources with key-value metadata (like project or department) enables accurate cost allocation and reporting."}, {"obj": "3.3", "q": "Which of the following terms fits this definition: \"Encrypting backup data so it remains protected even if the storage media or files are exposed.\"?", "c": ["Backup Recoverability Testing", "Backup Encryption", "Granular Recovery", "Backup Replication"], "a": 1, "e": "\"Encrypting backup data so it remains protected even if the storage media or files are exposed.\" describes Backup Encryption. Especially important since backups often contain complete copies of sensitive production data."}, {"obj": "4.5", "q": "Which term best matches this description: \"Rules that define what actions a given identity is allowed or denied to perform on cloud resources.\"?", "c": ["Network ACL", "IPS/IDS", "IAM Policies", "Network Security Group"], "a": 2, "e": "\"Rules that define what actions a given identity is allowed or denied to perform on cloud resources.\" describes IAM Policies. The core mechanism for enforcing least privilege and access control in cloud environments."}, {"obj": "5.1", "q": "Which term best matches this description: \"Having other team members examine proposed code changes before they are merged.\"?", "c": ["Code Review", "Branch Management", "Code Commit", "Pull Request"], "a": 0, "e": "\"Having other team members examine proposed code changes before they are merged.\" describes Code Review. Catches bugs, security issues, and design problems before they reach production."}, {"obj": "5.3", "q": "Why does this matter on the exam and in practice? \"Older and more rigid than REST, but still used in some enterprise and legacy integrations.\" — which term does this explain?", "c": ["REST", "RPC", "SOAP", "Web Sockets"], "a": 2, "e": "Older and more rigid than REST, but still used in some enterprise and legacy integrations. This describes SOAP (\"Simple Object Access Protocol — an XML-based messaging protocol for web services.\")."}, {"obj": "6.2", "q": "An application team reports the API is returning HTTP 403 responses for a specific client, while other clients succeed with 200 responses to the same endpoint. What should be investigated first?", "c": ["DHCP configuration on the server", "Authorization/permissions for that specific client, since 403 indicates a permissions-related denial rather than a connectivity problem", "NTP synchronization", "IP scope exhaustion"], "a": 1, "e": "An HTTP 403 status specifically indicates the request was understood but denied due to authorization, pointing directly to a permissions issue for that client rather than basic connectivity or infrastructure problems."}, {"obj": "3.4", "q": "A vendor releases an update that fixes a specific security vulnerability in a widely used library, with no new features. What type of update is this?", "c": ["A major update", "A patch", "A minor update with new features", "A complete re-architecture"], "a": 1, "e": "A patch addresses a specific bug or vulnerability, distinct from a major or minor update that may include broader feature changes."}, {"obj": "3.2", "q": "An application automatically adds new instances whenever average CPU utilization crosses 75% for five minutes. What scaling approach is this?", "c": ["Scheduled scaling", "Triggered scaling — load", "Vertical scaling", "Manual scaling"], "a": 1, "e": "Load-triggered scaling reacts to a real-time threshold being crossed, the most common autoscaling mechanism."}, {"obj": "1.10", "q": "Which term best matches this description: \"The actual amount of data successfully transferred over a network connection in a given time.\"?", "c": ["Orchestration (Workload)", "Network Throughput", "Compute Optimization (Container)", "Workflow (Optimization)"], "a": 1, "e": "\"The actual amount of data successfully transferred over a network connection in a given time.\" describes Network Throughput. Determines whether a network link can support a workload's data transfer needs."}, {"obj": "4.1", "q": "A colleague says: \"The step that actually reduces risk — identification without remediation provides no real protection.\" Which concept are they describing?", "c": ["Scanning Scope", "Vulnerability Assessment", "Remediation", "Vulnerability Identification"], "a": 2, "e": "The step that actually reduces risk — identification without remediation provides no real protection. This describes Remediation (\"Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability.\")."}, {"obj": "5.1", "q": "Given the description \"Uploading local code changes to a remote/shared repository.\", which term is being defined?", "c": ["Code Merge", "Version Management", "Code Push", "Branch Management"], "a": 2, "e": "\"Uploading local code changes to a remote/shared repository.\" describes Code Push. The action that shares a developer's committed changes with the rest of the team."}, {"obj": "1.1", "q": "Select the most accurate description of \"SaaS\":", "c": ["A framework defining which security and operational tasks belong to the cloud provider versus the customer.", "Platform as a Service — provides a managed runtime/platform for developing and deploying applications without managing the underlying OS.", "Infrastructure as a Service — provides virtualized compute, storage, and networking, leaving the OS and above to the customer.", "Software as a Service — delivers a fully managed application to end users over the internet."], "a": 3, "e": "Software as a Service — delivers a fully managed application to end users over the internet. The provider manages everything except the user's own data and configuration within the app."}, {"obj": "1.10", "q": "Which term best matches this description: \"The time delay for data to travel between two points on a network.\"?", "c": ["Storage Throughput", "Compute Optimization (Serverless)", "Network Latency", "Compute Optimization (VM)"], "a": 2, "e": "\"The time delay for data to travel between two points on a network.\" describes Network Latency. A critical factor when placing workloads and choosing regions/AZs for latency-sensitive applications."}, {"obj": "3.3", "q": "A company verifies that its backup files have not been corrupted by comparing checksums against expected values, without actually performing a full restore. What practice is this?", "c": ["Backup recoverability testing", "Backup integrity testing", "Backup replication", "Bulk recovery"], "a": 1, "e": "Backup integrity testing verifies that backed-up data has not been corrupted (e.g., via checksums), which is distinct from actually restoring the data to confirm recoverability."}, {"obj": "6.1", "q": "Why does this matter on the exam and in practice? \"Can cause deployment or application failures if automation exceeds the allowed request rate.\" — which term does this explain?", "c": ["Resource Allocation Misconfiguration", "Partial Outage", "Sizing Issues", "API Throttling"], "a": 3, "e": "Can cause deployment or application failures if automation exceeds the allowed request rate. This describes API Throttling (\"A provider intentionally limiting the rate of API calls a customer can make.\")."}, {"obj": "2.3", "q": "Which concept is described by the phrase: \"A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture.\"?", "c": ["Rehost", "Re-Architect", "Refactor", "Replatform"], "a": 3, "e": "\"A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture.\" describes Replatform. A middle ground between a straight lift-and-shift and a full application redesign."}, {"obj": "3.2", "q": "\"Triggered Scaling — Event\" is best defined as which of the following?", "c": ["Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU).", "Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%).", "Increasing the resources (CPU/RAM) of an existing instance (scale up).", "Scaling in response to a specific event (like a message queue depth increasing)."], "a": 3, "e": "Scaling in response to a specific event (like a message queue depth increasing). Useful for event-driven architectures where load isn't purely CPU/memory based."}, {"obj": "5.2", "q": "Which term best matches this description: \"A packaged container image produced and stored as a build output.\"?", "c": ["CI/CD Workflow", "Container Image Artifact", "Debian Package", "VM Image Artifact"], "a": 1, "e": "\"A packaged container image produced and stored as a build output.\" describes Container Image Artifact. Provides a versioned, portable, reusable deployment unit for containerized workloads."}, {"obj": "1.10", "q": "Why does this matter on the exam and in practice? \"Helps chain together cloud services and automate multi-step business processes.\" — which term does this explain?", "c": ["Compute Optimization (Container)", "Network Throughput", "Workflow (Optimization)", "Compute Optimization (Serverless)"], "a": 2, "e": "Helps chain together cloud services and automate multi-step business processes. This describes Workflow (Optimization) (\"A defined sequence of automated steps/tasks that process data or coordinate resources.\")."}, {"obj": "5.1", "q": "Which concept is described by the phrase: \"Tracking and organizing different versions of code or configuration over time.\"?", "c": ["Code Merge", "Code Commit", "Version Management", "Code Push"], "a": 2, "e": "\"Tracking and organizing different versions of code or configuration over time.\" describes Version Management. Provides the history needed to understand what changed and to roll back if necessary."}, {"obj": "6.2", "q": "An administrator explains the importance of a concept: \"DNS failures cause connectivity issues that look like the destination is down, even when it's reachable by IP.\" What concept is this?", "c": ["Misconfigured Route", "Access vs. Trunk Ports", "DNS (Troubleshooting)", "IP Scope Exhaustion"], "a": 2, "e": "DNS failures cause connectivity issues that look like the destination is down, even when it's reachable by IP. This describes DNS (Troubleshooting) (\"Domain Name System — resolves hostnames to IP addresses.\")."}, {"obj": "1.8", "q": "Which of the following best describes \"Spot Instance\"?", "c": ["Tracking actual consumption of cloud resources for billing and capacity planning purposes.", "A billing model charging only for actual resource consumption, with no upfront commitment.", "Pre-purchasing capacity for a discounted rate in exchange for a committed term.", "Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice."], "a": 3, "e": "Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice. Ideal for fault-tolerant, interruptible workloads like batch processing, but not suitable for critical always-on services."}, {"obj": "1.7", "q": "Which of the following best describes \"Overlay Network\"?", "c": ["Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction.", "A single hypervisor host running VMs with no clustering.", "A virtual network built on top of physical network infrastructure, common in virtualization and containers.", "Storage Area Network — shared block storage accessible by multiple hypervisor hosts."], "a": 2, "e": "A virtual network built on top of physical network infrastructure, common in virtualization and containers. Allows flexible virtual network topologies independent of the underlying physical network layout."}, {"obj": "1.7", "q": "An administrator wants two related VMs to always run on the same physical host for performance reasons. What should be configured?", "c": ["Anti-affinity", "Host affinity", "Clustering", "Hardware pass-through"], "a": 1, "e": "Host affinity rules keep specified VMs running together on the same physical host."}, {"obj": "4.3", "q": "A colleague says: \"Widely used for consumer and enterprise single sign-on into cloud applications.\" Which concept are they describing?", "c": ["MFA", "Discretionary Access Control", "OAuth 2.0", "OpenID Connect"], "a": 3, "e": "Widely used for consumer and enterprise single sign-on into cloud applications. This describes OpenID Connect (\"An identity layer built on top of OAuth 2.0 used for authentication (proving who you are).\")."}, {"obj": "5.3", "q": "Why does this matter on the exam and in practice? \"Underpins many internal microservice-to-microservice communication patterns (e.g., gRPC).\" — which term does this explain?", "c": ["RPC", "Event-Driven Architecture", "GraphQL", "SOAP"], "a": 0, "e": "Underpins many internal microservice-to-microservice communication patterns (e.g., gRPC). This describes RPC (\"Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local.\")."}, {"obj": "1.4", "q": "\"Cold Storage Tier\" is best defined as which of the following?", "c": ["A storage tier for infrequently accessed data, offering lower cost with slower retrieval.", "Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB).", "Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.", "Hard Disk Drive — traditional magnetic spinning-platter storage."], "a": 0, "e": "A storage tier for infrequently accessed data, offering lower cost with slower retrieval. Suitable for older backups or compliance data that is rarely, but occasionally, needed."}, {"obj": "1.7", "q": "Given the description \"Grouping multiple hypervisor hosts together to share resources and enable failover/migration.\", which term is being defined?", "c": ["Clustering", "SAN (Virtualization Context)", "VM Network", "Hardware Pass-Through"], "a": 0, "e": "\"Grouping multiple hypervisor hosts together to share resources and enable failover/migration.\" describes Clustering. Enables high availability and load balancing of VMs across multiple physical hosts."}, {"obj": "1.5", "q": "An e-commerce platform is broken into independently deployable services for catalog, checkout, and shipping. What design pattern is this?", "c": ["Monolithic architecture", "Microservices", "Fan-out", "Service discovery"], "a": 1, "e": "Microservices architecture breaks an application into small, independently deployable services rather than one large monolith."}, {"obj": "1.4", "q": "A media company stores millions of video files that are accessed unpredictably via a web application through HTTP APIs. Which storage type is best suited?", "c": ["Block storage", "Object storage", "A single shared block volume", "Ephemeral instance storage"], "a": 1, "e": "Object storage is designed for massive-scale, unstructured data accessed via API, ideal for large libraries of media files."}, {"obj": "2.3", "q": "A company evaluating migration options decides that a specific internal tool has had zero active users for a year and simply removes it from the migration scope entirely. Which strategy does this represent?", "c": ["Retain", "Retire", "Rehost", "Replatform"], "a": 1, "e": "Retiring an unused application removes it from migration scope entirely, reducing both migration effort and ongoing costs."}, {"obj": "6.1", "q": "\"Partial Outage\" is best defined as which of the following?", "c": ["A deployment failure or performance problem caused by choosing an inappropriately sized resource.", "A degradation where some, but not all, functionality or users are affected.", "Allocating more virtual resources than the underlying physical capacity can truly support.", "The fact that not all cloud services are available in every region."], "a": 1, "e": "A degradation where some, but not all, functionality or users are affected. Still requires prompt attention but may allow more measured troubleshooting than a full outage."}, {"obj": "1.11", "q": "Which term is most closely associated with this real-world importance: \"Optimized for low bandwidth and power use, unlike heavier traditional web protocols.\"?", "c": ["Voice-to-Text", "IoT Transmission Protocol", "Visual Recognition", "IoT Sensor"], "a": 1, "e": "Optimized for low bandwidth and power use, unlike heavier traditional web protocols. This describes IoT Transmission Protocol (\"Lightweight protocols (like MQTT or CoAP) designed for constrained IoT devices and networks.\")."}, {"obj": "4.1", "q": "Which term best matches this description: \"The step of detecting known weaknesses in systems, typically via automated scanning.\"?", "c": ["Scanning Scope", "Vulnerability Assessment", "Vulnerability Identification", "CVE"], "a": 2, "e": "\"The step of detecting known weaknesses in systems, typically via automated scanning.\" describes Vulnerability Identification. The first concrete step in the vulnerability management lifecycle, feeding into assessment and remediation."}, {"obj": "2.5", "q": "Before provisioning a new database instance, an architect determines the expected read/write load and required uptime. Which two requirement categories are they addressing?", "c": ["Compute and compliance", "Performance and availability", "Network and cost", "Storage and compliance"], "a": 1, "e": "Expected load relates to performance requirements, while required uptime relates to availability requirements, both key inputs to provisioning decisions."}, {"obj": "4.1", "q": "A description reads: \"The step of detecting known weaknesses in systems, typically via automated scanning.\" Which term does this describe?", "c": ["CVE", "Remediation", "Scanning Scope", "Vulnerability Identification"], "a": 3, "e": "\"The step of detecting known weaknesses in systems, typically via automated scanning.\" describes Vulnerability Identification. The first concrete step in the vulnerability management lifecycle, feeding into assessment and remediation."}, {"obj": "1.8", "q": "Which of the following best describes \"Dedicated Host Billing\"?", "c": ["A billing model where a customer pays for an entire physical host, regardless of utilization.", "Tracking actual consumption of cloud resources for billing and capacity planning purposes.", "Pre-purchasing capacity for a discounted rate in exchange for a committed term.", "Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice."], "a": 0, "e": "A billing model where a customer pays for an entire physical host, regardless of utilization. Useful for licensing or compliance requirements that need physical isolation from other tenants."}, {"obj": "1.7", "q": "Which term best matches this description: \"Creating an exact copy of an existing VM.\"?", "c": ["Host Affinity", "Stand-Alone Virtualization", "Cloning", "Local Storage (Virtualization)"], "a": 2, "e": "\"Creating an exact copy of an existing VM.\" describes Cloning. Speeds up deployment of identical VMs without building each one from scratch."}, {"obj": "5.1", "q": "A description reads: \"Uploading local code changes to a remote/shared repository.\" Which term does this describe?", "c": ["Code Push", "Code Commit", "Code Review", "Code Merge"], "a": 0, "e": "\"Uploading local code changes to a remote/shared repository.\" describes Code Push. The action that shares a developer's committed changes with the rest of the team."}, {"obj": "4.4", "q": "Which term best matches this description: \"Encrypting stored data so it remains unreadable without the correct key.\"?", "c": ["API Security", "Data at Rest Encryption", "CIS Benchmark", "Privileged Container"], "a": 1, "e": "\"Encrypting stored data so it remains unreadable without the correct key.\" describes Data at Rest Encryption. Protects data even if the underlying storage media is stolen or improperly accessed."}, {"obj": "4.2", "q": "Select the most accurate description of \"Regulatory Retention\":", "c": ["A data retention requirement specified in a contract with a customer or partner.", "An international standard specifying requirements for an information security management system.", "The principle that data is subject to the laws of the country in which it is physically located.", "A data retention requirement mandated by law or industry regulation."], "a": 3, "e": "A data retention requirement mandated by law or industry regulation. Non-compliance can result in legal penalties, distinct from purely internal retention preferences."}, {"obj": "4.2", "q": "A company's contract with a cloud provider explicitly states that the customer retains legal ownership and control of all data stored in the provider's environment. What concept does this address?", "c": ["Data locality", "Data ownership", "Regulatory retention", "SOC 2 certification"], "a": 1, "e": "Data ownership defines who legally owns and controls a given set of data, clarifying rights when a third-party provider stores or processes it."}, {"obj": "4.3", "q": "In cloud computing terminology, \"Audit Trail\" refers to which of the following?", "c": ["Secure Shell — an encrypted protocol for remote command-line access to cloud resources.", "A chronological record of who did what, and when, within a system.", "Accessing cloud resources via code rather than a human using a GUI (API/SDK).", "Allowing users to authenticate using credentials from a separate, trusted identity provider."], "a": 1, "e": "A chronological record of who did what, and when, within a system. Essential for investigating incidents and demonstrating compliance with access policies."}, {"obj": "1.1", "q": "An organization evaluates a project management tool that requires no installation, is updated automatically by the vendor, and is accessed entirely via a web browser. Which service model is this?", "c": ["IaaS", "PaaS", "SaaS", "FaaS"], "a": 2, "e": "A fully managed, browser-accessed application updated by the vendor is the defining characteristic of SaaS."}, {"obj": "1.1", "q": "A development team wants to run short bursts of code triggered by file uploads, without provisioning or managing any servers. Which model fits?", "c": ["IaaS", "PaaS", "FaaS", "SaaS"], "a": 2, "e": "FaaS (serverless) runs code in response to events, with billing based on execution rather than reserved server capacity."}, {"obj": "5.4", "q": "A team needs to declaratively provision cloud infrastructure across multiple providers using a single configuration language. Which tool fits best?", "c": ["Kubernetes", "Terraform", "Docker", "Git"], "a": 1, "e": "Terraform is a widely used multi-cloud IaC tool that provisions infrastructure declaratively using its own configuration language."}, {"obj": "2.5", "q": "Which of the following is the correct expansion of \"CPU\"?", "c": ["Storage Area Network", "Simple Object Access Protocol", "Common Weakness Scoring System", "Central Processing Unit"], "a": 3, "e": "CPU stands for Central Processing Unit. The primary processor executing instructions in a compute instance."}, {"obj": "4.3", "q": "Which of the following terms fits this definition: \"A hardened server that provides a single, monitored entry point for administrative access into a private network.\"?", "c": ["SDK", "Local User Authentication", "Bastion Host", "Audit Trail"], "a": 2, "e": "\"A hardened server that provides a single, monitored entry point for administrative access into a private network.\" describes Bastion Host. Reduces the attack surface by ensuring administrative access doesn't require directly exposing every resource."}, {"obj": "1.2", "q": "A description reads: \"A fully equipped, continuously running DR site that can take over almost immediately.\" Which term does this describe?", "c": ["Hot Site", "Warm Site", "RTO", "Cold Site"], "a": 0, "e": "\"A fully equipped, continuously running DR site that can take over almost immediately.\" describes Hot Site. Offers the shortest RTO but is the most expensive DR option to maintain."}, {"obj": "5.1", "q": "In cloud computing terminology, \"Version Management\" refers to which of the following?", "c": ["Organizing and maintaining separate lines of development (branches) within a repository.", "Tracking and organizing different versions of code or configuration over time.", "Having other team members examine proposed code changes before they are merged.", "A formal request to merge a proposed code change into a shared branch, typically triggering review."], "a": 1, "e": "Tracking and organizing different versions of code or configuration over time. Provides the history needed to understand what changed and to roll back if necessary."}, {"obj": "6.2", "q": "Select the most accurate description of \"Access vs. Trunk Ports\":", "c": ["Domain Name System — resolves hostnames to IP addresses.", "Network Address Translation — translates private addresses to a public address for routing.", "Incorrect VLAN tagging causing traffic to be dropped or delivered to the wrong segment.", "The distinction between a switch port carrying a single VLAN (access) versus multiple VLANs (trunk)."], "a": 3, "e": "The distinction between a switch port carrying a single VLAN (access) versus multiple VLANs (trunk). Misconfiguring one as the other is a common cause of VLAN connectivity problems."}, {"obj": "4.1", "q": "In cloud computing terminology, \"Scanning Scope\" refers to which of the following?", "c": ["Evaluating identified vulnerabilities for severity, exploitability, and business impact.", "Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities.", "Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability.", "Defining which systems, networks, or applications a vulnerability scan will cover."], "a": 3, "e": "Defining which systems, networks, or applications a vulnerability scan will cover. Ensures the scan actually covers all in-scope assets rather than leaving blind spots."}, {"obj": "5.3", "q": "A company integrating with a modern web API that follows stateless request/response semantics using standard HTTP verbs is most likely working with which style?", "c": ["SOAP", "REST", "Web sockets exclusively", "RPC exclusively"], "a": 1, "e": "REST's defining characteristics are statelessness and standard HTTP verb usage, matching this description of a modern web API."}, {"obj": "5.2", "q": "Select the most accurate description of \"VM Image Artifact\":", "c": ["Automatically running tests against code as part of the pipeline.", "Compiling/packaging source code into a deployable artifact.", "A simple, unstructured file (like a config or script) produced or consumed by a pipeline.", "A packaged virtual machine image produced and stored as a build output."], "a": 3, "e": "A packaged virtual machine image produced and stored as a build output. Provides a versioned, reusable deployment unit for VM-based workloads."}, {"obj": "1.11", "q": "Which term is most closely associated with this real-world importance: \"Enables applications to serve global users without manual translation.\"?", "c": ["Text Recognition", "Generative AI", "Text Translation", "IoT Communication"], "a": 2, "e": "Enables applications to serve global users without manual translation. This describes Text Translation (\"AI technology that automatically converts text from one language to another.\")."}, {"obj": "4.2", "q": "Which of the following best describes \"SOC2\"?", "c": ["An organization that publishes best practices and frameworks specifically for cloud security.", "Requirements or preferences about the physical location where data is stored or processed.", "Systems and Organization Controls 2 — an audit framework evaluating a service provider's controls around security, availability, and confidentiality.", "A legal requirement to preserve specific data because it may be relevant to pending litigation."], "a": 2, "e": "Systems and Organization Controls 2 — an audit framework evaluating a service provider's controls around security, availability, and confidentiality. A common compliance report requested by customers evaluating a cloud vendor's security posture."}, {"obj": "2.4", "q": "A team wants to ensure a proposed IaC change won't introduce a security misconfiguration, such as an overly permissive storage bucket policy, before it reaches production. What should be part of their pipeline?", "c": ["Automated IaC security testing/scanning as part of the CI pipeline", "Skipping all testing to move faster", "Manual production changes with no code review", "Removing IaC entirely in favor of manual configuration"], "a": 0, "e": "Automated security scanning of IaC templates as part of the CI pipeline catches misconfigurations like overly permissive policies before they reach production."}, {"obj": "2.5", "q": "An architect determines the expected bandwidth and acceptable latency for a new application before deciding whether a dedicated connection is needed. What requirement category is this?", "c": ["Compute requirements", "Network requirements", "Storage requirements", "Compliance requirements"], "a": 1, "e": "Network requirements cover bandwidth, latency, and connectivity needs, shaping decisions like whether a dedicated connection or specific region placement is needed."}, {"obj": "6.2", "q": "In cloud computing terminology, \"IP Scope Exhaustion\" refers to which of the following?", "c": ["A required network path that has not been defined in a route table.", "Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500).", "The distinction between a switch port carrying a single VLAN (access) versus multiple VLANs (trunk).", "Running out of available addresses within a defined IP range or subnet."], "a": 3, "e": "Running out of available addresses within a defined IP range or subnet. Prevents new resources from being provisioned with an address until the range is expanded or reclaimed."}, {"obj": "1.10", "q": "\"Compute Optimization (VM)\" is best defined as which of the following?", "c": ["Using provider-operated services instead of self-managed infrastructure to reduce operational overhead.", "A defined sequence of automated steps/tasks that process data or coordinate resources.", "Using virtual machines as the compute resource type for a workload.", "Automated coordination of workload deployment, scaling, and lifecycle management."], "a": 2, "e": "Using virtual machines as the compute resource type for a workload. Appropriate for workloads needing full OS control and long-running processes."}, {"obj": "5.4", "q": "Select the most accurate description of \"GitHub Actions\":", "c": ["A widely used open-source automation server for building CI/CD pipelines.", "A CI/CD automation feature built into GitHub for running workflows in response to repository events.", "A platform for building, running, and managing containers.", "A distributed version control system used to track changes in source code."], "a": 1, "e": "A CI/CD automation feature built into GitHub for running workflows in response to repository events. Lets teams define build/test/deploy pipelines directly alongside their code in GitHub."}, {"obj": "4.3", "q": "The acronym \"BYOD\" stands for:", "c": ["Common Language Infrastructure", "JavaScript Object Notation", "Bring Your Own Device", "Common Vulnerability Scoring System"], "a": 2, "e": "BYOD stands for Bring Your Own Device. A policy allowing employees to use personal devices to access corporate/cloud resources."}, {"obj": "1.3", "q": "Select the most accurate description of \"Route Table\":", "c": ["A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers).", "A set of rules that determines where network traffic is directed.", "A device or service that filters network traffic based on defined rules.", "Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains."], "a": 1, "e": "A set of rules that determines where network traffic is directed. Every subnet in a VPC is associated with a route table controlling how its traffic flows."}, {"obj": "1.5", "q": "An administrator explains the importance of a concept: \"Improves resilience and flexibility since one component's changes or failures don't directly break others.\" What concept is this?", "c": ["Service Discovery", "Loosely Coupled Architecture", "Microservices", "Fan-Out"], "a": 1, "e": "Improves resilience and flexibility since one component's changes or failures don't directly break others. This describes Loosely Coupled Architecture (\"A design where components interact through well-defined interfaces with minimal direct dependencies.\")."}, {"obj": "4.5", "q": "How would you most accurately define \"WAF\"?", "c": ["Rules that define what actions a given identity is allowed or denied to perform on cloud resources.", "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data.", "Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications.", "Security software (antivirus, EDR) installed directly on servers, VMs, or devices."], "a": 2, "e": "Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications. Protects against application-layer attacks like SQL injection and cross-site scripting that a normal firewall wouldn't catch."}, {"obj": "1.11", "q": "A company wants to automatically classify whether uploaded product images meet quality standards without human review. Which AI capability is most relevant?", "c": ["Visual recognition", "Text translation", "Voice-to-text", "Sentiment analysis"], "a": 0, "e": "Visual recognition can automatically identify features or defects within images, supporting automated quality classification."}, {"obj": "4.3", "q": "Which of the following is the correct expansion of \"LDAP\"?", "c": ["Hard Disk Drive", "Real-time Messaging Protocol", "Lightweight Directory Access Protocol", "Common Vulnerability Scoring System"], "a": 2, "e": "LDAP stands for Lightweight Directory Access Protocol. A protocol for querying and modifying directory services."}, {"obj": "4.4", "q": "Which of the following best describes \"CIS Benchmark\"?", "c": ["Encrypting data as it moves across a network (e.g., via TLS).", "Controls governing which files and directories a container process can read or write.", "Securely storing and controlling access to credentials, API keys, and other sensitive configuration values.", "A set of vendor-neutral, consensus-based configuration hardening guidelines."], "a": 3, "e": "A set of vendor-neutral, consensus-based configuration hardening guidelines. Provides a well-known, widely adopted baseline for hardening systems and cloud services."}, {"obj": "1.11", "q": "A battery-powered IoT device needs to transmit small telemetry messages using minimal power and bandwidth. Which type of protocol is designed for this purpose?", "c": ["A heavyweight traditional web protocol like standard HTTP with large headers", "A lightweight IoT transmission protocol like MQTT or CoAP", "A protocol requiring constant persistent large file transfers", "Standard SMTP email protocol"], "a": 1, "e": "Lightweight protocols like MQTT or CoAP are specifically designed for constrained IoT devices with limited power and bandwidth, unlike heavier traditional protocols."}, {"obj": "2.3", "q": "In cloud computing terminology, \"Replatform\" refers to which of the following?", "c": ["A migration strategy that substantially redesigns an application to be cloud-native.", "Moving workloads out of the cloud back to local infrastructure.", "A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture.", "A migration strategy that moves an application to the cloud with minimal changes, also called lift and shift."], "a": 2, "e": "A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture. A middle ground between a straight lift-and-shift and a full application redesign."}, {"obj": "2.3", "q": "A description reads: \"A migration strategy that substantially redesigns an application to be cloud-native.\" Which term does this describe?", "c": ["Refactor", "On-Premises-to-Cloud Migration", "Re-Architect", "Retire"], "a": 2, "e": "\"A migration strategy that substantially redesigns an application to be cloud-native.\" describes Re-Architect. Takes the most effort but unlocks the greatest long-term benefits like scalability and cost efficiency."}, {"obj": "3.2", "q": "An administrator explains the importance of a concept: \"Improves both capacity and redundancy, and is the standard scaling approach in cloud-native design.\" What concept is this?", "c": ["Triggered Scaling — Event", "Vertical Scaling", "Horizontal Scaling", "Manual Scaling"], "a": 2, "e": "Improves both capacity and redundancy, and is the standard scaling approach in cloud-native design. This describes Horizontal Scaling (\"Adding more instances of a resource to handle increased load (scale out).\")."}, {"obj": "6.2", "q": "After upgrading a client application, it can no longer establish a TLS connection to a service because the client only supports an older TLS version the service no longer accepts. What is this an example of?", "c": ["Protocol deprecation causing incompatibility", "IP scope exhaustion", "A missing route", "DHCP failure"], "a": 0, "e": "This describes protocol deprecation: the service has dropped support for an older protocol version that the client still relies on, causing connection failures."}, {"obj": "6.1", "q": "Why does this matter on the exam and in practice? \"Represents the most severe availability impact, prioritized above partial outages.\" — which term does this explain?", "c": ["Incompatibility (Deployment)", "Full Outage", "Sizing Issues", "Oversubscription"], "a": 1, "e": "Represents the most severe availability impact, prioritized above partial outages. This describes Full Outage (\"A complete loss of service availability.\")."}, {"obj": "4.3", "q": "\"Web Portal\" is best defined as which of the following?", "c": ["Accessing cloud resources via code rather than a human using a GUI (API/SDK).", "An authorization framework that lets an application access resources on a user's behalf without sharing their password.", "Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources.", "A graphical, browser-based interface for managing cloud resources."], "a": 3, "e": "A graphical, browser-based interface for managing cloud resources. The most accessible management interface for humans, though less suited to automation."}, {"obj": "1.11", "q": "Select the most accurate description of \"Text-to-Voice\":", "c": ["AI models that create new content (text, images, code) based on learned patterns.", "The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data.", "AI technology that determines the emotional tone (positive/negative/neutral) of text.", "AI technology that converts written text into spoken audio (speech synthesis)."], "a": 3, "e": "AI technology that converts written text into spoken audio (speech synthesis). Used for voice assistants, accessibility tools, and automated phone systems."}, {"obj": "3.1", "q": "Select the most accurate description of \"Alert Triage\":", "c": ["Gathering log data from applications, systems, and services into a central location.", "Combining logs from many sources into a unified, searchable view.", "The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.", "Defining how long log data is kept before being archived or deleted."], "a": 2, "e": "The process of reviewing and prioritizing incoming alerts to determine urgency and next steps. Prevents alert fatigue and ensures the most critical issues are addressed first."}, {"obj": "5.1", "q": "Which of the following terms fits this definition: \"Saving a snapshot of changes to the local version control history.\"?", "c": ["Code Merge", "Code Push", "Code Commit", "Version Management"], "a": 2, "e": "\"Saving a snapshot of changes to the local version control history.\" describes Code Commit. The basic unit of change tracking in most version control systems."}, {"obj": "1.2", "q": "An e-commerce company wants continuous monitoring of its checkout service so that any downtime is detected within seconds rather than waiting for customer complaints. What should be implemented?", "c": ["A quarterly manual review", "Availability monitoring with automated health checks", "A single annual penetration test", "A one-time architecture review"], "a": 1, "e": "Continuous availability monitoring with automated health checks provides real-time visibility into outages, rather than relying on infrequent manual reviews."}, {"obj": "5.3", "q": "Which term best matches this description: \"Simple Object Access Protocol — an XML-based messaging protocol for web services.\"?", "c": ["RPC", "REST", "SOAP", "GraphQL"], "a": 2, "e": "\"Simple Object Access Protocol — an XML-based messaging protocol for web services.\" describes SOAP. Older and more rigid than REST, but still used in some enterprise and legacy integrations."}, {"obj": "4.2", "q": "Which concept is described by the phrase: \"A data retention requirement specified in a contract with a customer or partner.\"?", "c": ["Contractual Retention", "ISO 27001", "Litigation Hold", "Data Ownership"], "a": 0, "e": "\"A data retention requirement specified in a contract with a customer or partner.\" describes Contractual Retention. May require data to be kept longer (or shorter) than the organization's default policy."}, {"obj": "1.11", "q": "An accessibility feature reads website content aloud to visually impaired users. Which AI capability powers this?", "c": ["Voice-to-text", "Text-to-voice (speech synthesis)", "Text recognition", "Visual recognition"], "a": 1, "e": "Text-to-voice (speech synthesis) converts written text into spoken audio, powering accessibility features like screen readers."}, {"obj": "1.4", "q": "The acronym \"iSCSI\" stands for:", "c": ["Transport Layer Security", "Internet Small Computer System Interface", "Information Technology Infrastructure Library", "Bring Your Own Device"], "a": 1, "e": "iSCSI stands for Internet Small Computer System Interface. Carries SCSI storage commands over IP networks for block-level SAN access."}, {"obj": "4.4", "q": "Given the description \"A set of vendor-neutral, consensus-based configuration hardening guidelines.\", which term is being defined?", "c": ["CIS Benchmark", "Principle of Least Privilege", "API Security", "Zero Trust"], "a": 0, "e": "\"A set of vendor-neutral, consensus-based configuration hardening guidelines.\" describes CIS Benchmark. Provides a well-known, widely adopted baseline for hardening systems and cloud services."}, {"obj": "6.2", "q": "A server can reach some external websites but not others, all tested by IP address to bypass DNS. What category of issue does this suggest?", "c": ["A pure DNS resolution issue", "A routing, firewall, or upstream network issue affecting specific destination networks", "A DHCP failure", "An NTP misconfiguration"], "a": 1, "e": "Since DNS is bypassed by testing with raw IP addresses, inconsistent reachability points to routing, firewall, or upstream network issues rather than DNS."}, {"obj": "1.7", "q": "A hypervisor host uses storage physically attached only to that host, meaning VMs cannot be live-migrated to other hosts without extra steps. What storage type is this?", "c": ["SAN", "NAS", "Local storage", "An overlay network"], "a": 2, "e": "Local storage is physically attached to a single host, which is fast and simple but does not support live migration without shared storage."}, {"obj": "2.4", "q": "An API request body used to provision a cloud resource through a REST API is most likely structured in which format?", "c": ["YAML exclusively", "JSON", "A proprietary spreadsheet format", "Plain unstructured text"], "a": 1, "e": "JSON is the lightweight, structured data format most commonly used for API request/response bodies, including many cloud provisioning APIs."}, {"obj": "4.4", "q": "What does the abbreviation \"TLS\" stand for?", "c": ["Simple Object Access Protocol", "Common Vulnerability Scoring System", "Border Gateway Protocol", "Transport Layer Security"], "a": 3, "e": "TLS stands for Transport Layer Security. The modern standard protocol for encrypting network communications."}, {"obj": "4.3", "q": "Which of the following best describes \"RDP\"?", "c": ["An authorization framework that lets an application access resources on a user's behalf without sharing their password.", "Granting permissions to a group, which members inherit by being added to that group.", "Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.", "A hardened server that provides a single, monitored entry point for administrative access into a private network."], "a": 2, "e": "Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system. The standard way to remotely access Windows-based cloud instances."}, {"obj": "6.1", "q": "Select the most accurate description of \"Incompatibility (Deployment)\":", "c": ["The fact that not all cloud services are available in every region.", "A failure caused by mismatched software, hardware, or configuration versions.", "IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated.", "A provider-imposed limit on how many of a given resource type can be provisioned."], "a": 1, "e": "A failure caused by mismatched software, hardware, or configuration versions. A very common root cause of failed deployments, especially after an update to one dependency."}, {"obj": "1.7", "q": "A company needs to enable live migration of VMs between hosts in a cluster, requiring all hosts to access the same storage. What storage type should be used?", "c": ["Local storage attached to a single host", "A SAN or NAS accessible to all hosts in the cluster", "Ephemeral container storage", "Hardware pass-through storage"], "a": 1, "e": "Shared storage like a SAN or NAS accessible to every host in the cluster is required for features like live migration, since any host may need to run the VM."}, {"obj": "1.7", "q": "A specialized workload requires direct access to a physical network card's advanced hardware features that the hypervisor's virtual NIC abstraction does not expose. What should be configured?", "c": ["A vNIC only", "Hardware pass-through for the physical NIC", "An overlay network", "Host affinity"], "a": 1, "e": "Hardware pass-through gives the VM direct access to the physical device's full feature set, bypassing the more limited virtual NIC abstraction."}, {"obj": "3.2", "q": "An online retailer's traffic predictably spikes every day at 9 AM when the site opens for business. What scaling approach best matches this recurring pattern?", "c": ["Manual scaling performed by an engineer each morning", "Scheduled scaling configured to add capacity ahead of the known daily spike", "Triggered scaling based on CPU load only", "Vertical scaling of a single instance"], "a": 1, "e": "Scheduled scaling adjusts capacity at predefined times based on known, recurring usage patterns, ideal for predictable daily spikes."}, {"obj": "2.4", "q": "A company discovers that its production environment no longer matches what is defined in its IaC templates because of several undocumented manual changes over time. What practice should they implement going forward to catch this earlier?", "c": ["Regular drift detection scans comparing actual state to IaC definitions", "Disabling all monitoring", "Removing version control from IaC files", "Avoiding IaC entirely in favor of manual changes"], "a": 0, "e": "Regular drift detection scans would have caught the growing divergence between actual infrastructure state and the IaC-defined configuration much earlier."}, {"obj": "4.6", "q": "A colleague says: \"Represents both wasted cost and an unpatched, unmonitored attack surface.\" Which concept are they describing?", "c": ["Zombie Instance", "Unnecessary Open Ports", "Phishing", "Metadata Attack"], "a": 0, "e": "Represents both wasted cost and an unpatched, unmonitored attack surface. This describes Zombie Instance (\"A cloud instance that is running but forgotten, unmonitored, or unmanaged.\")."}, {"obj": "3.2", "q": "Select the most accurate description of \"Vertical Scaling\":", "c": ["Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%).", "Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU).", "Increasing the resources (CPU/RAM) of an existing instance (scale up).", "Scaling resources up or down at predefined times based on known usage patterns."], "a": 2, "e": "Increasing the resources (CPU/RAM) of an existing instance (scale up). Simpler than horizontal scaling but has an upper limit and usually requires downtime or a reboot."}, {"obj": "1.11", "q": "Why does this matter on the exam and in practice? \"Enables applications to serve global users without manual translation.\" — which term does this explain?", "c": ["Text Translation", "Machine Learning", "Sentiment Analysis", "IoT Communication"], "a": 0, "e": "Enables applications to serve global users without manual translation. This describes Text Translation (\"AI technology that automatically converts text from one language to another.\")."}, {"obj": "2.5", "q": "Which statement accurately describes \"Compliance Requirements\"?", "c": ["Legal or regulatory obligations a workload's data and processing must meet.", "The capacity, performance, and durability needs a workload has for its data.", "The uptime and resiliency expectations for a workload.", "The processing power (CPU, RAM) needed to run a workload effectively."], "a": 0, "e": "Legal or regulatory obligations a workload's data and processing must meet. Can restrict which regions, providers, or configurations are acceptable for a given workload."}, {"obj": "4.5", "q": "Which of the following best describes \"Endpoint Protection\"?", "c": ["Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data.", "Access Control List — a set of rules controlling traffic in and out of a subnet at the network level.", "Security software (antivirus, EDR) installed directly on servers, VMs, or devices.", "Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity."], "a": 2, "e": "Security software (antivirus, EDR) installed directly on servers, VMs, or devices. Detects and blocks malicious activity at the individual system level."}, {"obj": "3.4", "q": "In cloud computing terminology, \"Minor Update\" refers to which of the following?", "c": ["A smaller update, typically with bug fixes and small improvements.", "Retiring or upgrading a resource because the vendor no longer provides support/patches for it.", "A significant version update that may include new features and breaking changes.", "Temporary data that does not need to persist beyond a session or process."], "a": 0, "e": "A smaller update, typically with bug fixes and small improvements. Generally lower risk than major updates but should still be tested before production rollout."}, {"obj": "4.3", "q": "Select the most accurate description of \"Role-Based Access Control\":", "c": ["Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources.", "Authenticating with credentials stored directly on the system rather than a central directory.", "Granting permissions based on a user's assigned role rather than to each individual directly.", "Multifactor Authentication — requiring two or more independent verification factors to log in."], "a": 2, "e": "Granting permissions based on a user's assigned role rather than to each individual directly. Simplifies administration and enforces consistent access across users with the same job function."}, {"obj": "1.2", "q": "Given the description \"A partially equipped DR site that needs recent data restored before it can take over.\", which term is being defined?", "c": ["Cloud Bursting", "Hot Site", "Warm Site", "RPO"], "a": 2, "e": "\"A partially equipped DR site that needs recent data restored before it can take over.\" describes Warm Site. A middle-ground between cost and recovery speed compared to hot and cold sites."}, {"obj": "3.4", "q": "A vendor announces that a specific database version will no longer receive security patches after a certain date, even though it still functions. What lifecycle stage does this trigger?", "c": ["End of life planning by the business only", "End of support, requiring an upgrade or migration before patches stop", "A routine minor update with no urgency", "Lifecycle testing with no further action needed"], "a": 1, "e": "End of support means the vendor will no longer provide patches, which should trigger a planned upgrade or migration before the resource becomes permanently vulnerable."}, {"obj": "1.2", "q": "Given the description \"Recovery Point Objective — the maximum acceptable amount of data loss, measured in time.\", which term is being defined?", "c": ["RPO", "Availability Zone", "Availability Monitoring", "Edge Computing"], "a": 0, "e": "\"Recovery Point Objective — the maximum acceptable amount of data loss, measured in time.\" describes RPO. A tight RPO requires frequent backups or synchronous replication; a looser RPO allows infrequent backups."}, {"obj": "1.1", "q": "A colleague says: \"Developers push code and the provider handles the OS, runtime, and scaling, speeding up application delivery.\" Which concept are they describing?", "c": ["FaaS", "SaaS", "PaaS", "IaaS"], "a": 2, "e": "Developers push code and the provider handles the OS, runtime, and scaling, speeding up application delivery. This describes PaaS (\"Platform as a Service — provides a managed runtime/platform for developing and deploying applications without managing the underlying OS.\")."}, {"obj": "1.11", "q": "A description reads: \"AI technology that converts written text into spoken audio (speech synthesis).\" Which term does this describe?", "c": ["Text-to-Voice", "IoT Communication", "IoT Sensor", "Generative AI"], "a": 0, "e": "\"AI technology that converts written text into spoken audio (speech synthesis).\" describes Text-to-Voice. Used for voice assistants, accessibility tools, and automated phone systems."}, {"obj": "2.5", "q": "Which concept is described by the phrase: \"The capacity, performance, and durability needs a workload has for its data.\"?", "c": ["Network Requirements", "Availability Requirements", "Storage Requirements", "Compute Requirements"], "a": 2, "e": "\"The capacity, performance, and durability needs a workload has for its data.\" describes Storage Requirements. Must be assessed before provisioning to choose the right storage type and tier."}, {"obj": "5.3", "q": "A payment service publishes an \"order placed\" event, and multiple independent downstream services react to it without direct calls between them. What architecture is this?", "c": ["RPC-based architecture", "Event-driven architecture", "SOAP-based architecture", "REST-only architecture"], "a": 1, "e": "Event-driven architecture lets components communicate through events rather than direct calls, enabling loose coupling."}, {"obj": "1.7", "q": "Which concept is described by the phrase: \"A virtual network built on top of physical network infrastructure, common in virtualization and containers.\"?", "c": ["Clustering", "Overlay Network", "Hardware Pass-Through", "NAS (Virtualization Context)"], "a": 1, "e": "\"A virtual network built on top of physical network infrastructure, common in virtualization and containers.\" describes Overlay Network. Allows flexible virtual network topologies independent of the underlying physical network layout."}, {"obj": "1.2", "q": "A business determines it can tolerate at most 2 hours of downtime and 15 minutes of data loss for a critical system. Which two metrics have they defined?", "c": ["MTBF and MTTR", "RTO and RPO", "SLA and BIA", "ARO and ALE"], "a": 1, "e": "RTO defines maximum acceptable downtime; RPO defines maximum acceptable data loss, both central to DR planning."}, {"obj": "4.2", "q": "Which of the following terms fits this definition: \"Defining who legally owns and controls a given set of data.\"?", "c": ["PCI DSS", "Regulatory Retention", "Contractual Retention", "Data Ownership"], "a": 3, "e": "\"Defining who legally owns and controls a given set of data.\" describes Data Ownership. Clarifies responsibility and rights when data is stored or processed by a third-party cloud provider."}, {"obj": "3.1", "q": "Which term is most closely associated with this real-world importance: \"Balances storage cost against the need to investigate older incidents or meet compliance requirements.\"?", "c": ["Log Retention", "Log Collection", "Monitoring Metrics", "Alert Triage"], "a": 0, "e": "Balances storage cost against the need to investigate older incidents or meet compliance requirements. This describes Log Retention (\"Defining how long log data is kept before being archived or deleted.\")."}, {"obj": "1.1", "q": "Which of the following best describes \"SaaS\"?", "c": ["Infrastructure as a Service — provides virtualized compute, storage, and networking, leaving the OS and above to the customer.", "Function as a Service — lets code run in response to events without provisioning or managing any server (serverless).", "Software as a Service — delivers a fully managed application to end users over the internet.", "Platform as a Service — provides a managed runtime/platform for developing and deploying applications without managing the underlying OS."], "a": 2, "e": "Software as a Service — delivers a fully managed application to end users over the internet. The provider manages everything except the user's own data and configuration within the app."}, {"obj": "2.3", "q": "Given the description \"Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.\", which term is being defined?", "c": ["Retire", "Vendor Lock-In", "Refactor", "Retain"], "a": 1, "e": "\"Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.\" describes Vendor Lock-In. A key risk consideration when architecting for portability across multiple providers."}, {"obj": "3.1", "q": "Which of the following best describes \"Tracing\"?", "c": ["The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.", "Combining logs from many sources into a unified, searchable view.", "Defining how long log data is kept before being archived or deleted.", "Following a single request as it moves through multiple services in a distributed system."], "a": 3, "e": "Following a single request as it moves through multiple services in a distributed system. Critical for pinpointing where latency or errors occur across microservices."}, {"obj": "5.3", "q": "A payment service publishes an 'order placed' event, and multiple independent downstream services react to it without any direct calls between them. What architecture pattern is this?", "c": ["RPC-based synchronous architecture", "Event-driven architecture", "SOAP-based architecture", "A monolithic call stack"], "a": 1, "e": "Event-driven architecture lets components communicate through events rather than direct calls, enabling loose coupling between publishers and subscribers."}, {"obj": "1.4", "q": "Which term best matches this description: \"Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.\"?", "c": ["Object Storage", "SSD", "Block Storage", "Archive Storage Tier"], "a": 1, "e": "\"Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.\" describes SSD. The default choice for performance-sensitive workloads like databases."}, {"obj": "2.5", "q": "Which of the following best illustrates assessing network requirements during provisioning?", "c": ["Determining the expected request latency tolerance and bandwidth needs before choosing a region and connectivity option", "Determining how long data must be retained for legal reasons", "Determining the required uptime percentage for an SLA", "Determining the CPU core count needed for a workload"], "a": 0, "e": "Assessing expected latency tolerance and bandwidth needs, which then inform region and connectivity choices, is a direct example of evaluating network requirements."}, {"obj": "1.3", "q": "How would you most accurately define \"Dedicated Connection\"?", "c": ["A hub service that connects many VPCs and on-premises networks through a single point.", "A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute).", "A logical subdivision of a network's IP address range.", "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port."], "a": 1, "e": "A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute). Offers more consistent bandwidth/latency and often lower cost at scale than routing through the public internet."}, {"obj": "1.11", "q": "A colleague says: \"Used to digitize and search paper documents or extract data from images automatically.\" Which concept are they describing?", "c": ["IoT Sensor", "Text Recognition", "Generative AI", "IoT Transmission Protocol"], "a": 1, "e": "Used to digitize and search paper documents or extract data from images automatically. This describes Text Recognition (\"AI technology that extracts text from images or scanned documents (OCR).\")."}, {"obj": "3.4", "q": "Before rolling out a minor patch across their entire production fleet, a team applies it to a small subset of servers first and monitors for issues. What practice is this an example of?", "c": ["Skipping lifecycle testing entirely", "Lifecycle testing via a staged/canary rollout of the patch", "Ignoring the patch's risk profile", "End of life planning"], "a": 1, "e": "Applying an update to a small subset first and monitoring results is a staged form of lifecycle testing, reducing risk before a full rollout."}, {"obj": "1.4", "q": "\"Warm Storage Tier\" is best defined as which of the following?", "c": ["A storage tier for data accessed less frequently than hot data, balancing cost and access speed.", "Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.", "A storage tier for infrequently accessed data, offering lower cost with slower retrieval.", "Hard Disk Drive — traditional magnetic spinning-platter storage."], "a": 0, "e": "A storage tier for data accessed less frequently than hot data, balancing cost and access speed. A middle ground for data that's not actively hot but still needed with reasonable speed."}, {"obj": "1.11", "q": "A software company integrates a cloud AI service that can generate draft marketing copy and sample code based on short prompts. What category of AI service is this?", "c": ["Sentiment analysis", "Generative AI", "Text recognition", "IoT gateway processing"], "a": 1, "e": "Generative AI models create new content (text, images, code) based on learned patterns, matching this description of generating draft copy and code."}, {"obj": "4.5", "q": "Why does this matter on the exam and in practice? \"The core mechanism for enforcing least privilege and access control in cloud environments.\" — which term does this explain?", "c": ["IAM Policies", "Network ACL", "Endpoint Protection", "DDoS Protection"], "a": 0, "e": "The core mechanism for enforcing least privilege and access control in cloud environments. This describes IAM Policies (\"Rules that define what actions a given identity is allowed or denied to perform on cloud resources.\")."}, {"obj": "1.10", "q": "What does the abbreviation \"GPU\" stand for?", "c": ["Hard Disk Drive", "Graphics Processing Unit", "Function as a Service", "Common Weakness Scoring System"], "a": 1, "e": "GPU stands for Graphics Processing Unit. A specialized processor for graphics and parallel compute workloads."}, {"obj": "1.11", "q": "Which of the following best describes \"IoT Sensor\"?", "c": ["A device that collects data from the physical environment (temperature, motion, etc.).", "AI technology that extracts text from images or scanned documents (OCR).", "A device that aggregates and relays data from multiple IoT sensors to the cloud.", "Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case."], "a": 0, "e": "A device that collects data from the physical environment (temperature, motion, etc.). The data-collection endpoint in most IoT architectures, feeding data upstream for processing."}, {"obj": "6.2", "q": "Select the most accurate description of \"Misconfigured Route\":", "c": ["A required network path that has not been defined in a route table.", "Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500).", "Network Address Translation — translates private addresses to a public address for routing.", "An incorrect entry in a route table sending traffic to the wrong destination."], "a": 3, "e": "An incorrect entry in a route table sending traffic to the wrong destination. Can cause traffic to be dropped, looped, or sent somewhere unintended."}, {"obj": "6.1", "q": "A deployment fails because it requests more virtual CPUs than the account's regional quota allows. What is the underlying cause?", "c": ["A service quota limit", "A regional service availability issue", "API throttling", "A deprecated component"], "a": 0, "e": "Service quotas cap how many of a given resource type can be provisioned; exceeding one causes a deployment failure."}, {"obj": "4.3", "q": "Why does this matter on the exam and in practice? \"The most accessible management interface for humans, though less suited to automation.\" — which term does this explain?", "c": ["RDP", "SSH", "Web Portal", "Directory-Based Authentication"], "a": 2, "e": "The most accessible management interface for humans, though less suited to automation. This describes Web Portal (\"A graphical, browser-based interface for managing cloud resources.\")."}, {"obj": "4.5", "q": "In cloud computing terminology, \"DLP\" refers to which of the following?", "c": ["Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic.", "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data.", "A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs.", "Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity."], "a": 1, "e": "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data. Commonly blocks sensitive data like credit card numbers from leaving the network through channels like email."}, {"obj": "6.3", "q": "A vulnerability scan identifies a critical, actively-exploited flaw in a widely used library still running on several internet-facing servers, with a patch available for months. What category does this fall under?", "c": ["Leaked credentials", "Software vulnerability issues (unpatched known vulnerability)", "Cipher suite deprecation", "Privilege escalation"], "a": 1, "e": "Running unpatched software with a known, actively exploited vulnerability represents a software vulnerability issue, reinforcing the need for timely patching."}, {"obj": "2.4", "q": "Why does this matter on the exam and in practice? \"Ensures configuration consistency across environments and enables automated drift correction.\" — which term does this explain?", "c": ["IaC Testing", "IaC Versioning", "Configuration as Code", "YAML"], "a": 2, "e": "Ensures configuration consistency across environments and enables automated drift correction. This describes Configuration as Code (\"Managing system or application configuration through code rather than manual configuration.\")."}, {"obj": "1.2", "q": "What does the abbreviation \"IP\" stand for?", "c": ["Internet Control Message Protocol", "Infrastructure as a Service", "Internet Protocol", "Internet Small Computer System Interface"], "a": 2, "e": "IP stands for Internet Protocol. The protocol responsible for addressing and routing packets across networks."}, {"obj": "1.3", "q": "Select the most accurate description of \"Network Load Balancer\":", "c": ["A manually configured network route that does not change dynamically.", "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port.", "A set of rules that determines where network traffic is directed.", "Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management."], "a": 1, "e": "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port. Provides extremely high throughput and low latency for use cases where Layer 7 inspection isn't needed."}, {"obj": "1.5", "q": "Which concept is described by the phrase: \"A design where components interact through well-defined interfaces with minimal direct dependencies.\"?", "c": ["Microservices", "Cloud-Provided Managed Service", "Service Discovery", "Loosely Coupled Architecture"], "a": 3, "e": "\"A design where components interact through well-defined interfaces with minimal direct dependencies.\" describes Loosely Coupled Architecture. Improves resilience and flexibility since one component's changes or failures don't directly break others."}, {"obj": "1.4", "q": "Which of the following best describes \"File Storage\"?", "c": ["A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost.", "The lowest-cost storage tier, designed for rarely accessed data with the slowest retrieval times (sometimes hours).", "Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.", "Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB)."], "a": 3, "e": "Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB). Ideal for shared application data and home directories accessed by multiple servers simultaneously."}, {"obj": "4.1", "q": "\"Remediation\" is best defined as which of the following?", "c": ["Evaluating identified vulnerabilities for severity, exploitability, and business impact.", "Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities.", "Defining which systems, networks, or applications a vulnerability scan will cover.", "Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability."], "a": 3, "e": "Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability. The step that actually reduces risk — identification without remediation provides no real protection."}, {"obj": "6.3", "q": "A description reads: \"A connectivity/security failure caused by relying on an outdated, no-longer-supported encryption cipher suite.\" Which term does this describe?", "c": ["Cipher Suite Deprecation", "Privilege Escalation (Troubleshooting)", "Unauthorized Access", "Unauthorized Software"], "a": 0, "e": "\"A connectivity/security failure caused by relying on an outdated, no-longer-supported encryption cipher suite.\" describes Cipher Suite Deprecation. Common after a platform disables old, insecure ciphers for security reasons, breaking legacy clients."}, {"obj": "5.2", "q": "In cloud computing terminology, \"Public Repository\" refers to which of the following?", "c": ["Compiling/packaging source code into a deployable artifact.", "A packaged container image produced and stored as a build output.", "A packaged virtual machine image produced and stored as a build output.", "A code or artifact repository accessible to anyone."], "a": 3, "e": "A code or artifact repository accessible to anyone. Convenient for open-source projects but not suitable for proprietary or sensitive code."}, {"obj": "1.7", "q": "A company groups multiple hypervisor hosts together so that VMs can automatically migrate to a healthy host if one host fails. What is this called?", "c": ["Stand-alone virtualization", "Clustering", "Hardware pass-through", "Local storage"], "a": 1, "e": "Clustering groups multiple hosts to share resources and enable VM failover/migration, providing high availability that a single stand-alone host cannot."}, {"obj": "4.5", "q": "Select the most accurate description of \"IPS/IDS\":", "c": ["Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity.", "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data.", "Rules that define what actions a given identity is allowed or denied to perform on cloud resources.", "Access Control List — a set of rules controlling traffic in and out of a subnet at the network level."], "a": 0, "e": "Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity. IDS alerts on suspicious activity; IPS goes further by actively blocking it in real time."}, {"obj": "3.3", "q": "Select the most accurate description of \"Parallel Recovery\":", "c": ["Restoring data to an alternate system running alongside the original.", "How long backup copies are kept before being deleted or overwritten.", "The defined frequency and timing of backup jobs.", "Encrypting backup data so it remains protected even if the storage media or files are exposed."], "a": 0, "e": "Restoring data to an alternate system running alongside the original. Useful for testing a restore or recovering without disrupting the still-running original system."}, {"obj": "6.3", "q": "Which statement accurately describes \"Privilege Escalation (Troubleshooting)\"?", "c": ["An identity gaining higher access than originally granted, often through a flaw or misconfiguration.", "Problems arising from unpatched or improperly configured software containing known weaknesses.", "A connectivity/security failure caused by relying on an outdated, no-longer-supported encryption cipher suite.", "Software installed or running without proper approval, increasing risk and potentially breaching policy."], "a": 0, "e": "An identity gaining higher access than originally granted, often through a flaw or misconfiguration. A critical security troubleshooting concern after any suspected compromise of a low-privilege account."}, {"obj": "1.2", "q": "An application must remain available even if an entire datacenter within a region fails. What should the architecture use?", "c": ["A single availability zone", "Multiple availability zones within the region", "A single on-premises server", "One spot instance"], "a": 1, "e": "Spreading resources across multiple availability zones protects against the failure of any single datacenter within a region."}, {"obj": "1.11", "q": "A colleague says: \"Used to analyze customer feedback, reviews, and social media at scale.\" Which concept are they describing?", "c": ["Generative AI", "IoT Gateway", "Voice-to-Text", "Sentiment Analysis"], "a": 3, "e": "Used to analyze customer feedback, reviews, and social media at scale. This describes Sentiment Analysis (\"AI technology that determines the emotional tone (positive/negative/neutral) of text.\")."}, {"obj": "5.4", "q": "Select the most accurate description of \"Grafana\":", "c": ["A distributed version control system used to track changes in source code.", "An open-source, agentless automation tool used for configuration management and orchestration.", "A CI/CD automation feature built into GitHub for running workflows in response to repository events.", "An open-source tool for visualizing metrics and creating monitoring dashboards."], "a": 3, "e": "An open-source tool for visualizing metrics and creating monitoring dashboards. Commonly paired with time-series databases to build real-time operational dashboards."}, {"obj": "4.2", "q": "Which term best matches this description: \"Defining who legally owns and controls a given set of data.\"?", "c": ["Data Ownership", "Data Locality", "Cloud Security Alliance", "PCI DSS"], "a": 0, "e": "\"Defining who legally owns and controls a given set of data.\" describes Data Ownership. Clarifies responsibility and rights when data is stored or processed by a third-party cloud provider."}, {"obj": "1.7", "q": "Which storage configuration would prevent a VM from being live-migrated to another host in the same cluster?", "c": ["Shared SAN storage accessible to all cluster hosts", "Local storage attached only to the VM's current host", "NAS storage shared across the cluster", "Any storage type supports live migration equally"], "a": 1, "e": "Local storage tied to a single host prevents live migration unless the VM's disk is first moved to shared storage accessible by the destination host."}, {"obj": "3.3", "q": "Select the most accurate description of \"Bulk Recovery\":", "c": ["Backs up only data changed since the last backup of any type.", "Restoring a large set of data all at once.", "Restoring data to an alternate system running alongside the original.", "A complete copy of all selected data."], "a": 1, "e": "Restoring a large set of data all at once. Appropriate when an entire system or dataset needs to be recovered together."}, {"obj": "5.4", "q": "Which of the following best describes \"Docker\"?", "c": ["A platform for building, running, and managing containers.", "Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization.", "An open-source tool for visualizing metrics and creating monitoring dashboards.", "A distributed version control system used to track changes in source code."], "a": 0, "e": "A platform for building, running, and managing containers. The most widely used container runtime and image format in modern DevOps workflows."}, {"obj": "1.11", "q": "Which term is most closely associated with this real-world importance: \"A rapidly growing category of cloud AI services used for content creation and code assistance.\"?", "c": ["Generative AI", "IoT Transmission Protocol", "Text Translation", "IoT Sensor"], "a": 0, "e": "A rapidly growing category of cloud AI services used for content creation and code assistance. This describes Generative AI (\"AI models that create new content (text, images, code) based on learned patterns.\")."}, {"obj": "2.2", "q": "Why does this matter on the exam and in practice? \"Allows near-instant rollback by simply switching traffic back to the previous environment.\" — which term does this explain?", "c": ["Canary Deployment", "Rolling Deployment", "In-Place Deployment", "Blue-Green Deployment"], "a": 3, "e": "Allows near-instant rollback by simply switching traffic back to the previous environment. This describes Blue-Green Deployment (\"A strategy running two identical environments (blue and green), switching traffic to the new version once verified.\")."}, {"obj": "5.2", "q": "In cloud computing terminology, \"Code Deployment\" refers to which of the following?", "c": ["Releasing built and tested code to a target environment (e.g., production).", "A package format (.deb) used for installing software on Debian-based Linux distributions.", "A code or artifact repository accessible to anyone.", "A code or artifact repository restricted to authorized users/systems."], "a": 0, "e": "Releasing built and tested code to a target environment (e.g., production). The \"CD\" in CI/CD — automating this step reduces the risk and effort of releasing changes."}, {"obj": "4.3", "q": "Which of the following is the correct expansion of \"SDK\"?", "c": ["Network Time Protocol", "Software Development Kit", "Availability Zone", "Transport Layer Security"], "a": 1, "e": "SDK stands for Software Development Kit. Libraries and tools letting developers programmatically interact with a cloud platform."}, {"obj": "1.11", "q": "Which term best matches this description: \"AI technology that converts written text into spoken audio (speech synthesis).\"?", "c": ["Generative AI", "Sentiment Analysis", "Text-to-Voice", "Text Translation"], "a": 2, "e": "\"AI technology that converts written text into spoken audio (speech synthesis).\" describes Text-to-Voice. Used for voice assistants, accessibility tools, and automated phone systems."}, {"obj": "5.4", "q": "A team wants to automate the configuration of network settings, installed packages, and user accounts across a fleet of existing servers without installing any agent software on them. Which tool fits best?", "c": ["Kubernetes", "Ansible", "Docker", "GitHub Actions"], "a": 1, "e": "Ansible's agentless design (using SSH) makes it well suited for configuring existing servers without requiring any additional agent software to be installed."}, {"obj": "5.2", "q": "Which of the following best describes \"Container Image Artifact\"?", "c": ["A packaged container image produced and stored as a build output.", "The defined sequence of automated stages a change passes through from commit to deployment.", "A code or artifact repository restricted to authorized users/systems.", "Compiling/packaging source code into a deployable artifact."], "a": 0, "e": "A packaged container image produced and stored as a build output. Provides a versioned, portable, reusable deployment unit for containerized workloads."}, {"obj": "3.3", "q": "A company performs a full backup every Sunday and incremental backups every other day. If a restore is needed on Thursday, which backups must be applied, and in what order?", "c": ["Only Thursday's incremental backup", "Sunday's full backup only", "Sunday's full backup, then Monday, Tuesday, and Wednesday's incrementals in order", "Only the most recent incremental, regardless of earlier ones"], "a": 2, "e": "Restoring from an incremental chain requires the last full backup plus every incremental backup taken since, applied in order."}, {"obj": "2.2", "q": "A description reads: \"Gradually rolling out a change to a small subset of users or servers before a full rollout.\" Which term does this describe?", "c": ["Blue-Green Deployment", "In-Place Deployment", "Canary Deployment", "Rolling Deployment"], "a": 2, "e": "\"Gradually rolling out a change to a small subset of users or servers before a full rollout.\" describes Canary Deployment. Limits the blast radius of a bad deployment by exposing it to only a fraction of traffic first."}, {"obj": "2.2", "q": "A team wants to release a new application version by provisioning an entirely separate, fully tested environment and then instantly switching all traffic to it, with instant rollback available by switching back. Which strategy is this?", "c": ["Rolling deployment", "Canary deployment", "Blue-green deployment", "In-place deployment"], "a": 2, "e": "Blue-green deployment maintains two parallel environments and switches traffic between them, enabling near-instant rollback by reverting the switch."}, {"obj": "1.1", "q": "A retailer wants to quickly test a new checkout feature using a managed database and application runtime, without provisioning any servers themselves. Which model reduces their operational burden the most while still allowing custom application code?", "c": ["IaaS", "PaaS", "On-premises", "Dedicated hosting"], "a": 1, "e": "PaaS lets the team focus on custom application code while the provider manages the runtime, database service, and scaling infrastructure."}, {"obj": "1.1", "q": "The acronym \"PaaS\" stands for:", "c": ["Multifactor Authentication", "Platform as a Service", "System and Organization Controls 2", "Machine Learning"], "a": 1, "e": "PaaS stands for Platform as a Service. A cloud model providing a managed platform for developing and running applications."}, {"obj": "5.2", "q": "The acronym \"CI/CD\" stands for:", "c": ["Data Loss Prevention", "Disaster Recovery", "Graphics Processing Unit", "Continuous Integration/Continuous Deployment"], "a": 3, "e": "CI/CD stands for Continuous Integration/Continuous Deployment. Automated pipelines that build, test, and deploy code changes with minimal manual effort."}, {"obj": "1.6", "q": "In cloud computing terminology, \"Port Mapping\" refers to which of the following?", "c": ["Storage that survives beyond the lifecycle of an individual container.", "Binding a container's internal port to a port on the host or load balancer.", "Automated management of container deployment, scaling, and healing (e.g., Kubernetes).", "Temporary storage tied to a container's lifecycle that is lost when the container stops."], "a": 1, "e": "Binding a container's internal port to a port on the host or load balancer. Allows external traffic to reach a service running inside an otherwise isolated container."}, {"obj": "4.4", "q": "Which of the following best describes \"Container File Access Permissions\"?", "c": ["Encrypting data as it moves across a network (e.g., via TLS).", "Access controls and encryption applied to shared file storage systems.", "Reducing a system's attack surface by disabling unnecessary services, closing unused ports, and applying secure configurations.", "Controls governing which files and directories a container process can read or write."], "a": 3, "e": "Controls governing which files and directories a container process can read or write. Misconfigured permissions inside a container can let an attacker access or modify data they shouldn't."}, {"obj": "2.3", "q": "Which statement accurately describes \"Re-Architect\"?", "c": ["A migration strategy that decommissions an application no longer needed.", "Moving workloads from one cloud provider or region to another.", "A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture.", "A migration strategy that substantially redesigns an application to be cloud-native."], "a": 3, "e": "A migration strategy that substantially redesigns an application to be cloud-native. Takes the most effort but unlocks the greatest long-term benefits like scalability and cost efficiency."}, {"obj": "2.2", "q": "Which of the following terms fits this definition: \"A strategy running two identical environments (blue and green), switching traffic to the new version once verified.\"?", "c": ["Canary Deployment", "Rolling Deployment", "Blue-Green Deployment", "In-Place Deployment"], "a": 2, "e": "\"A strategy running two identical environments (blue and green), switching traffic to the new version once verified.\" describes Blue-Green Deployment. Allows near-instant rollback by simply switching traffic back to the previous environment."}, {"obj": "1.6", "q": "A colleague says: \"Essential for running containerized applications reliably at scale in production.\" Which concept are they describing?", "c": ["Ephemeral Storage", "Persistent Volume", "Workload Orchestration", "Image Registry"], "a": 2, "e": "Essential for running containerized applications reliably at scale in production. This describes Workload Orchestration (\"Automated management of container deployment, scaling, and healing (e.g., Kubernetes).\")."}, {"obj": "4.4", "q": "A colleague says: \"Protects data from eavesdropping while crossing untrusted networks like the internet.\" Which concept are they describing?", "c": ["Data at Rest Encryption", "Data in Transit Encryption", "Zero Trust", "File Storage Security"], "a": 1, "e": "Protects data from eavesdropping while crossing untrusted networks like the internet. This describes Data in Transit Encryption (\"Encrypting data as it moves across a network (e.g., via TLS).\")."}, {"obj": "1.2", "q": "Which term is most closely associated with this real-world importance: \"Provides the data needed to detect outages and calculate real-world uptime against SLA targets.\"?", "c": ["RTO", "Availability Monitoring", "RPO", "Region"], "a": 1, "e": "Provides the data needed to detect outages and calculate real-world uptime against SLA targets. This describes Availability Monitoring (\"Continuously checking that a resource or service is up and responding as expected.\")."}, {"obj": "1.1", "q": "An administrator explains the importance of a concept: \"The provider manages everything except the user's own data and configuration within the app.\" What concept is this?", "c": ["SaaS", "IaaS", "PaaS", "FaaS"], "a": 0, "e": "The provider manages everything except the user's own data and configuration within the app. This describes SaaS (\"Software as a Service — delivers a fully managed application to end users over the internet.\")."}, {"obj": "4.3", "q": "Which term is most closely associated with this real-world importance: \"The standard mechanism behind \"log in with...\" and delegated API access scenarios.\"?", "c": ["OAuth 2.0", "OpenID Connect", "Directory-Based Authentication", "Discretionary Access Control"], "a": 0, "e": "The standard mechanism behind \"log in with...\" and delegated API access scenarios. This describes OAuth 2.0 (\"An authorization framework that lets an application access resources on a user's behalf without sharing their password.\")."}, {"obj": "3.2", "q": "A company vertically scales a single database instance repeatedly until it hits the maximum instance size the provider offers, and performance still isn't sufficient. What is the most likely next step?", "c": ["Continue attempting to vertically scale beyond the maximum size", "Consider horizontal scaling strategies (e.g., read replicas, sharding) since vertical scaling has a hard limit", "Switch to manual scaling only", "Disable monitoring to hide the performance issue"], "a": 1, "e": "Vertical scaling has an upper limit determined by the largest available instance size; once reached, horizontal scaling strategies become necessary to scale further."}, {"obj": "1.4", "q": "An administrator explains the importance of a concept: \"Ideal for long-term retention data that must be kept for compliance but is almost never read.\" What concept is this?", "c": ["Hot Storage Tier", "Archive Storage Tier", "Object Storage", "HDD"], "a": 1, "e": "Ideal for long-term retention data that must be kept for compliance but is almost never read. This describes Archive Storage Tier (\"The lowest-cost storage tier, designed for rarely accessed data with the slowest retrieval times (sometimes hours).\")."}, {"obj": "1.7", "q": "A company wants two specific VMs to always run on different physical hosts so that a single host failure cannot take down both simultaneously. What should be configured?", "c": ["Host affinity (same-host rule)", "Anti-affinity (different-host rule)", "Hardware pass-through", "Local storage only"], "a": 1, "e": "Anti-affinity rules keep specified VMs apart on different hosts, ensuring a single host failure doesn't affect both, unlike affinity which keeps them together."}, {"obj": "6.1", "q": "In cloud computing terminology, \"Service Quota\" refers to which of the following?", "c": ["A complete loss of service availability.", "A previously available feature or API being retired by the provider.", "A provider-imposed limit on how many of a given resource type can be provisioned.", "A deployment failure or performance problem caused by choosing an inappropriately sized resource."], "a": 2, "e": "A provider-imposed limit on how many of a given resource type can be provisioned. Deployments can fail silently if a quota is reached without prior awareness."}, {"obj": "4.4", "q": "An administrator explains the importance of a concept: \"Closes known security gaps that attackers commonly target since patches for them already exist.\" What concept is this?", "c": ["Hardening", "Principle of Least Privilege", "Data in Transit Encryption", "Patching (Security)"], "a": 3, "e": "Closes known security gaps that attackers commonly target since patches for them already exist. This describes Patching (Security) (\"Applying vendor-released updates that fix known vulnerabilities.\")."}, {"obj": "1.6", "q": "Which of the following is the most accurate description of workload orchestration in a containerized environment?", "c": ["Manually restarting failed containers by hand each time", "Automated management of container deployment, scaling, and healing across a cluster", "A method for storing container images only", "A way to expose container ports without any automation"], "a": 1, "e": "Workload orchestration automates deployment, scaling, and self-healing of containers, removing the need for manual intervention on failures."}, {"obj": "2.4", "q": "Before applying a new Terraform configuration to production, a team runs automated checks for syntax errors and known security misconfigurations. What practice is this?", "c": ["IaC testing", "Drift detection", "Manual production deployment", "Configuration as Code without validation"], "a": 0, "e": "IaC testing validates infrastructure code before it's applied to real environments, catching errors and misconfigurations before they cause problems."}, {"obj": "4.6", "q": "Which statement accurately describes \"Unnecessary Open Ports\"?", "c": ["Continuously observing system and security events for signs of malicious activity.", "Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources.", "Unauthorized use of a system's computing resources to mine cryptocurrency.", "Network ports left open on a system that are not required for its function."], "a": 3, "e": "Network ports left open on a system that are not required for its function. A common finding during security assessments and an easy target for attackers to exploit."}, {"obj": "4.3", "q": "Which of the following is the correct expansion of \"MFA\"?", "c": ["Not Only Structured Query Language", "Common Vulnerability Scoring System", "Multifactor Authentication", "Recovery Time Objective"], "a": 2, "e": "MFA stands for Multifactor Authentication. Requiring two or more independent verification factors to authenticate."}, {"obj": "2.4", "q": "Which of the following best describes \"IaC Testing\"?", "c": ["Managing system or application configuration through code rather than manual configuration.", "Managing and provisioning infrastructure through machine-readable definition files rather than manual processes.", "Tracking changes to infrastructure code over time using version control.", "Validating infrastructure code for syntax, security, and logic before it is applied to real environments."], "a": 3, "e": "Validating infrastructure code for syntax, security, and logic before it is applied to real environments. Catches errors before they cause an outage or misconfiguration in production."}, {"obj": "1.9", "q": "In Cloud+ terminology, \"DBaaS\" is an abbreviation for which of the following?", "c": ["Redundant Array of Independent Disks", "Web Application Firewall", "Database as a Service", "Input/Output Operations Per Second"], "a": 2, "e": "DBaaS stands for Database as a Service. A managed cloud database offering where the provider handles the underlying operations."}, {"obj": "3.1", "q": "\"Log Aggregation\" is best defined as which of the following?", "c": ["The defined actions taken once an alert is triaged and confirmed to need action.", "The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.", "Combining logs from many sources into a unified, searchable view.", "Defining how long log data is kept before being archived or deleted."], "a": 2, "e": "Combining logs from many sources into a unified, searchable view. Enables correlation across services, which is essential for diagnosing distributed system issues."}, {"obj": "4.2", "q": "The acronym \"DSS\" stands for:", "c": ["Availability Zone", "Database as a Service", "Cloud Service Provider", "Data Security Standard"], "a": 3, "e": "DSS stands for Data Security Standard. Security requirements for protecting sensitive data, as in PCI DSS."}, {"obj": "2.5", "q": "A team decides a new application must survive the loss of any single availability zone with minimal disruption. What requirement category is driving this design decision?", "c": ["Compliance requirements", "Availability requirements", "Compute requirements", "Storage requirements"], "a": 1, "e": "Availability requirements define uptime and resiliency expectations, driving design decisions like multi-AZ deployment."}, {"obj": "1.4", "q": "Which term is most closely associated with this real-world importance: \"A middle ground for data that's not actively hot but still needed with reasonable speed.\"?", "c": ["Object Storage", "Warm Storage Tier", "File Storage", "SSD"], "a": 1, "e": "A middle ground for data that's not actively hot but still needed with reasonable speed. This describes Warm Storage Tier (\"A storage tier for data accessed less frequently than hot data, balancing cost and access speed.\")."}, {"obj": "4.1", "q": "Which of the following best describes \"CVE\"?", "c": ["Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities.", "Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability.", "The step of detecting known weaknesses in systems, typically via automated scanning.", "Defining which systems, networks, or applications a vulnerability scan will cover."], "a": 0, "e": "Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities. Provides a common reference so vulnerabilities can be tracked and discussed consistently across tools and vendors."}, {"obj": "3.2", "q": "How would you most accurately define \"Horizontal Scaling\"?", "c": ["Scaling in response to a specific event (like a message queue depth increasing).", "Adding more instances of a resource to handle increased load (scale out).", "Scaling resources up or down at predefined times based on known usage patterns.", "Increasing the resources (CPU/RAM) of an existing instance (scale up)."], "a": 1, "e": "Adding more instances of a resource to handle increased load (scale out). Improves both capacity and redundancy, and is the standard scaling approach in cloud-native design."}, {"obj": "3.1", "q": "A monitoring team receives hundreds of alerts overnight and needs to determine which ones require immediate action. What process are they performing?", "c": ["Log aggregation", "Alert triage", "Tracing", "Log retention"], "a": 1, "e": "Alert triage reviews and prioritizes incoming alerts to determine urgency, preventing alert fatigue."}, {"obj": "3.2", "q": "An administrator explains the importance of a concept: \"The most common autoscaling trigger, reacting quickly to current demand.\" What concept is this?", "c": ["Vertical Scaling", "Horizontal Scaling", "Triggered Scaling — Load", "Scheduled Scaling"], "a": 2, "e": "The most common autoscaling trigger, reacting quickly to current demand. This describes Triggered Scaling — Load (\"Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%).\")."}, {"obj": "2.4", "q": "A colleague says: \"The preferred format for tools like Kubernetes manifests and many CI/CD pipeline definitions.\" Which concept are they describing?", "c": ["Infrastructure as Code", "Configuration as Code", "YAML", "Drift Detection"], "a": 2, "e": "The preferred format for tools like Kubernetes manifests and many CI/CD pipeline definitions. This describes YAML (\"Yet Another Markup Language — a human-readable data format widely used for IaC and configuration files.\")."}, {"obj": "1.4", "q": "Which term is most closely associated with this real-world importance: \"The default choice for performance-sensitive workloads like databases.\"?", "c": ["File Storage", "SSD", "Hot Storage Tier", "HDD"], "a": 1, "e": "The default choice for performance-sensitive workloads like databases. This describes SSD (\"Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.\")."}, {"obj": "3.4", "q": "Why does this matter on the exam and in practice? \"Applying patches promptly closes known security gaps before they can be exploited.\" — which term does this explain?", "c": ["Ephemeral Data", "Patch", "Decommissioning — End of Life", "Lifecycle Testing"], "a": 1, "e": "Applying patches promptly closes known security gaps before they can be exploited. This describes Patch (\"A software update addressing a specific bug or vulnerability.\")."}, {"obj": "4.3", "q": "A company wants a single, hardened, monitored entry point for administrators to reach private cloud instances via SSH, rather than exposing every instance's SSH port directly to the internet. What should be deployed?", "c": ["A web portal", "A bastion host", "An SDK", "OAuth 2.0 delegation"], "a": 1, "e": "A bastion host provides a single hardened, monitored entry point for administrative access, significantly reducing the exposed attack surface compared to direct SSH exposure."}, {"obj": "4.1", "q": "In cloud computing terminology, \"CVE\" refers to which of the following?", "c": ["The step of detecting known weaknesses in systems, typically via automated scanning.", "Defining which systems, networks, or applications a vulnerability scan will cover.", "Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability.", "Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities."], "a": 3, "e": "Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities. Provides a common reference so vulnerabilities can be tracked and discussed consistently across tools and vendors."}, {"obj": "4.3", "q": "A colleague says: \"Popular for scripting and automation tasks that would be tedious through a web portal.\" Which concept are they describing?", "c": ["CLI", "SDK", "Audit Trail", "OpenID Connect"], "a": 0, "e": "Popular for scripting and automation tasks that would be tedious through a web portal. This describes CLI (\"Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources.\")."}, {"obj": "6.1", "q": "How would you most accurately define \"Permission Issues (Deployment)\"?", "c": ["A degradation where some, but not all, functionality or users are affected.", "A deployment failing because the deploying identity lacks sufficient rights.", "A failure caused by mismatched software, hardware, or configuration versions.", "Incorrectly assigned CPU, memory, or storage limits for a workload."], "a": 1, "e": "A deployment failing because the deploying identity lacks sufficient rights. One of the most common causes of failed automated deployments in cloud environments."}, {"obj": "5.4", "q": "A team wants to aggregate, process, and visualize log data from many distributed services in one centralized open-source stack. Which combination of tools is commonly used for this?", "c": ["Terraform, Ansible, and Docker", "The ELK Stack (Elasticsearch, Logstash, Kibana)", "Kubernetes alone", "Git and GitHub Actions alone"], "a": 1, "e": "The ELK Stack is a widely used open-source combination specifically designed for centralized log aggregation, processing, and visualization."}, {"obj": "4.5", "q": "Given the description \"Security software (antivirus, EDR) installed directly on servers, VMs, or devices.\", which term is being defined?", "c": ["DLP", "Network ACL", "Endpoint Protection", "IAM Policies"], "a": 2, "e": "\"Security software (antivirus, EDR) installed directly on servers, VMs, or devices.\" describes Endpoint Protection. Detects and blocks malicious activity at the individual system level."}, {"obj": "5.2", "q": "A description reads: \"A code or artifact repository accessible to anyone.\" Which term does this describe?", "c": ["Public Repository", "VM Image Artifact", "CI/CD Workflow", "CI/CD Testing"], "a": 0, "e": "\"A code or artifact repository accessible to anyone.\" describes Public Repository. Convenient for open-source projects but not suitable for proprietary or sensitive code."}, {"obj": "1.11", "q": "How would you most accurately define \"Visual Recognition\"?", "c": ["A device that collects data from the physical environment (temperature, motion, etc.).", "AI technology that identifies objects, scenes, or features within images or video.", "Lightweight protocols (like MQTT or CoAP) designed for constrained IoT devices and networks.", "AI technology that automatically converts text from one language to another."], "a": 1, "e": "AI technology that identifies objects, scenes, or features within images or video. Powers use cases like content moderation, quality inspection, and security monitoring."}, {"obj": "1.11", "q": "A smart agriculture company deploys battery-powered soil moisture sensors across a large farm that transmit small amounts of data periodically. Which component collects this raw environmental data?", "c": ["An IoT sensor", "An IoT gateway", "A CDN edge node", "A load balancer"], "a": 0, "e": "IoT sensors are the devices that collect data from the physical environment, such as soil moisture readings in this scenario."}, {"obj": "6.1", "q": "An administrator explains the importance of a concept: \"Can cause performance problems or outright deployment failure if requested resources aren't actually available.\" What concept is this?", "c": ["Partial Outage", "Resource Allocation Misconfiguration", "Outdated Component Definitions", "Full Outage"], "a": 1, "e": "Can cause performance problems or outright deployment failure if requested resources aren't actually available. This describes Resource Allocation Misconfiguration (\"Incorrectly assigned CPU, memory, or storage limits for a workload.\")."}, {"obj": "4.4", "q": "Which of the following terms fits this definition: \"Access controls and encryption applied to shared file storage systems.\"?", "c": ["File Storage Security", "Unprivileged Container", "Object Storage Security", "Principle of Least Privilege"], "a": 0, "e": "\"Access controls and encryption applied to shared file storage systems.\" describes File Storage Security. Ensures only authorized users/systems can read or modify shared file data."}, {"obj": "4.6", "q": "A server's outbound traffic suddenly spikes to an unfamiliar external IP at 3 AM with no scheduled process running. What should be suspected?", "c": ["A scheduled backup", "Potential malware or compromised account communicating externally", "A routine health check", "Normal DNS caching"], "a": 1, "e": "Unexplained outbound traffic to an unfamiliar destination during off-hours is a classic indicator of malware or compromise."}, {"obj": "4.4", "q": "Which statement accurately describes \"Hardening\"?", "c": ["Access controls and encryption settings applied to object storage buckets/containers.", "A set of vendor-neutral, consensus-based configuration hardening guidelines.", "Controls governing which files and directories a container process can read or write.", "Reducing a system's attack surface by disabling unnecessary services, closing unused ports, and applying secure configurations."], "a": 3, "e": "Reducing a system's attack surface by disabling unnecessary services, closing unused ports, and applying secure configurations. One of the most fundamental and heavily tested security practices across all IT domains."}, {"obj": "1.3", "q": "An administrator explains the importance of a concept: \"Reduces latency and origin server load by serving cached static (and sometimes dynamic) content from edge locations.\" What concept is this?", "c": ["Route Table", "CDN", "Network Load Balancer", "Application Gateway"], "a": 1, "e": "Reduces latency and origin server load by serving cached static (and sometimes dynamic) content from edge locations. This describes CDN (\"Content Delivery Network — a geographically distributed set of servers that cache content closer to end users.\")."}, {"obj": "1.9", "q": "Which statement accurately describes \"Relational Database\"?", "c": ["A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs.", "A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure.", "A database that organizes data into structured tables with defined relationships (SQL).", "A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS)."], "a": 2, "e": "A database that organizes data into structured tables with defined relationships (SQL). Best suited for structured data requiring strong consistency and complex queries/joins."}, {"obj": "4.3", "q": "An enterprise implements SSO using an XML-based standard to exchange authentication assertions between its identity provider and a SaaS application. Which technology is this?", "c": ["OAuth 2.0", "SAML", "OpenID Connect", "RBAC"], "a": 1, "e": "SAML is an XML-based standard commonly used to implement federated single sign-on between an identity provider and a service."}, {"obj": "2.5", "q": "A team calculates how much data their application needs to store, how fast it needs to be retrieved, and how durable it must be before choosing a storage type and tier. What requirement category is this?", "c": ["Storage requirements", "Network requirements", "Availability requirements", "Compliance requirements"], "a": 0, "e": "Storage requirements cover capacity, performance, and durability needs, which must be assessed before choosing the right storage type and tier."}, {"obj": "4.6", "q": "Given the description \"An attack that succeeds because a system was running software with a known, unpatched vulnerability.\", which term is being defined?", "c": ["Zombie Instance", "Event Monitoring (Security)", "Vulnerability Exploitation — Outdated Software", "Vulnerability Exploitation — Human Error"], "a": 2, "e": "\"An attack that succeeds because a system was running software with a known, unpatched vulnerability.\" describes Vulnerability Exploitation — Outdated Software. Reinforces why timely patch management is one of the most effective security controls."}, {"obj": "1.3", "q": "Which of the following terms fits this definition: \"Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management.\"?", "c": ["Dedicated Connection", "Static Route", "Route Table", "SDN"], "a": 3, "e": "\"Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management.\" describes SDN. Underpins most cloud networking, allowing networks to be defined and changed through code/APIs rather than physical rewiring."}, {"obj": "1.11", "q": "Which of the following is the correct expansion of \"ML\"?", "c": ["Distributed Denial of Service", "Configuration as Code", "Machine Learning", "Local Area Network"], "a": 2, "e": "ML stands for Machine Learning. Algorithms that learn patterns from data to make predictions without explicit programming."}, {"obj": "3.1", "q": "Which statement accurately describes \"Log Aggregation\"?", "c": ["Defining how long log data is kept before being archived or deleted.", "Combining logs from many sources into a unified, searchable view.", "The defined actions taken once an alert is triaged and confirmed to need action.", "Numeric measurements of system behavior (CPU, memory, request rate) collected over time."], "a": 1, "e": "Combining logs from many sources into a unified, searchable view. Enables correlation across services, which is essential for diagnosing distributed system issues."}, {"obj": "4.1", "q": "Select the most accurate description of \"CVE\":", "c": ["Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities.", "The step of detecting known weaknesses in systems, typically via automated scanning.", "Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability.", "Defining which systems, networks, or applications a vulnerability scan will cover."], "a": 0, "e": "Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities. Provides a common reference so vulnerabilities can be tracked and discussed consistently across tools and vendors."}, {"obj": "4.5", "q": "A company configures a virtual firewall attached directly to a specific cloud VM instance to control its inbound and outbound traffic. What is this called?", "c": ["A network ACL", "A network security group", "A CDN rule", "A DLP policy"], "a": 1, "e": "A network security group is the primary mechanism for instance-level network access control, distinct from subnet-level network ACLs."}, {"obj": "1.3", "q": "\"CDN\" is best defined as which of the following?", "c": ["Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.", "Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management.", "A hub service that connects many VPCs and on-premises networks through a single point.", "Content Delivery Network — a geographically distributed set of servers that cache content closer to end users."], "a": 3, "e": "Content Delivery Network — a geographically distributed set of servers that cache content closer to end users. Reduces latency and origin server load by serving cached static (and sometimes dynamic) content from edge locations."}, {"obj": "4.6", "q": "Which term best matches this description: \"Network ports left open on a system that are not required for its function.\"?", "c": ["Event Monitoring (Security)", "Unnecessary Open Ports", "DDoS", "Deviation from Baseline"], "a": 1, "e": "\"Network ports left open on a system that are not required for its function.\" describes Unnecessary Open Ports. A common finding during security assessments and an easy target for attackers to exploit."}, {"obj": "1.9", "q": "Select the most accurate description of \"Self-Managed Database\":", "c": ["A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS).", "A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure.", "A database that organizes data into structured tables with defined relationships (SQL).", "A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs."], "a": 1, "e": "A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure. Offers maximum control but requires the customer to handle all operational overhead."}, {"obj": "4.2", "q": "Which statement accurately describes \"Regulatory Retention\"?", "c": ["A data retention requirement mandated by law or industry regulation.", "Defining who legally owns and controls a given set of data.", "A data retention requirement specified in a contract with a customer or partner.", "Requirements or preferences about the physical location where data is stored or processed."], "a": 0, "e": "A data retention requirement mandated by law or industry regulation. Non-compliance can result in legal penalties, distinct from purely internal retention preferences."}, {"obj": "6.2", "q": "Which term is most closely associated with this real-world importance: \"Clock drift can break authentication (like Kerberos) and certificate validation in subtle, confusing ways.\"?", "c": ["VLAN Misconfigured Tags", "Access vs. Trunk Ports", "Misconfigured Route", "NTP (Troubleshooting)"], "a": 3, "e": "Clock drift can break authentication (like Kerberos) and certificate validation in subtle, confusing ways. This describes NTP (Troubleshooting) (\"Network Time Protocol — synchronizes system clocks across a network.\")."}, {"obj": "4.1", "q": "An administrator explains the importance of a concept: \"Helps prioritize which vulnerabilities to remediate first based on actual risk.\" What concept is this?", "c": ["CVE", "Remediation", "Vulnerability Assessment", "Vulnerability Identification"], "a": 2, "e": "Helps prioritize which vulnerabilities to remediate first based on actual risk. This describes Vulnerability Assessment (\"Evaluating identified vulnerabilities for severity, exploitability, and business impact.\")."}, {"obj": "1.9", "q": "A development team wants to reduce operational overhead and let the cloud provider handle database patching and failover, freeing them to focus on the application. What should they choose?", "c": ["A self-managed database on a VM they administer", "A provider-managed database service", "A local file-based database with no backups", "An unmanaged open-source database with manual scaling"], "a": 1, "e": "A provider-managed database service shifts operational responsibilities like patching and failover to the provider, reducing the team's administrative burden."}, {"obj": "3.2", "q": "A retailer's traffic predictably spikes every day at 9 AM when the store opens online. What scaling approach best matches this pattern?", "c": ["Manual scaling", "Scheduled scaling", "Triggered scaling based on load", "Vertical scaling"], "a": 1, "e": "Scheduled scaling adjusts capacity at predefined times, ideal for predictable, recurring demand patterns."}, {"obj": "5.4", "q": "Which of the following terms fits this definition: \"An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively.\"?", "c": ["Jenkins", "Git", "Terraform", "ELK Stack"], "a": 2, "e": "\"An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively.\" describes Terraform. One of the most widely used multi-cloud IaC tools, using its own HCL configuration language."}, {"obj": "6.2", "q": "After merging two previously separate networks via a VPN, hosts on both sides experience routing failures. What is the likely cause?", "c": ["A missing route", "Network overlap (duplicate IP ranges)", "Protocol deprecation", "VLAN misconfigured tags"], "a": 1, "e": "Connecting networks that use overlapping/duplicate IP ranges causes routing conflicts and failures."}, {"obj": "4.4", "q": "In cloud computing terminology, \"Data at Rest Encryption\" refers to which of the following?", "c": ["Reducing a system's attack surface by disabling unnecessary services, closing unused ports, and applying secure configurations.", "A container running with restricted access, isolated from the host's sensitive resources.", "A container granted elevated access to the host system's resources.", "Encrypting stored data so it remains unreadable without the correct key."], "a": 3, "e": "Encrypting stored data so it remains unreadable without the correct key. Protects data even if the underlying storage media is stolen or improperly accessed."}, {"obj": "4.3", "q": "How would you most accurately define \"Role-Based Access Control\"?", "c": ["Granting permissions based on a user's assigned role rather than to each individual directly.", "Authenticating with credentials stored directly on the system rather than a central directory.", "Secure Shell — an encrypted protocol for remote command-line access to cloud resources.", "A hardened server that provides a single, monitored entry point for administrative access into a private network."], "a": 0, "e": "Granting permissions based on a user's assigned role rather than to each individual directly. Simplifies administration and enforces consistent access across users with the same job function."}, {"obj": "5.2", "q": "Select the most accurate description of \"Private Repository\":", "c": ["A simple, unstructured file (like a config or script) produced or consumed by a pipeline.", "Automatically running tests against code as part of the pipeline.", "A code or artifact repository restricted to authorized users/systems.", "The defined sequence of automated stages a change passes through from commit to deployment."], "a": 2, "e": "A code or artifact repository restricted to authorized users/systems. The standard choice for proprietary source code and internal build artifacts."}, {"obj": "2.1", "q": "A large enterprise wants dedicated infrastructure for a single organization's exclusive use, but is willing to have it hosted and managed off-site by a third party. Which deployment model fits?", "c": ["Public cloud", "Private cloud (hosted off-premises)", "Community cloud", "On premises"], "a": 1, "e": "A private cloud can be hosted on- or off-premises; its defining trait is that it is dedicated to a single organization, unlike public or community models."}, {"obj": "4.6", "q": "Which of the following best describes \"Phishing\"?", "c": ["An attack that succeeds because a system was running software with a known, unpatched vulnerability.", "Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources.", "Network ports left open on a system that are not required for its function.", "A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email."], "a": 3, "e": "A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email. One of the most common initial access vectors used in real-world breaches."}, {"obj": "5.1", "q": "In cloud computing terminology, \"Code Commit\" refers to which of the following?", "c": ["Saving a snapshot of changes to the local version control history.", "Tracking and organizing different versions of code or configuration over time.", "Combining changes from different branches into one.", "Having other team members examine proposed code changes before they are merged."], "a": 0, "e": "Saving a snapshot of changes to the local version control history. The basic unit of change tracking in most version control systems."}, {"obj": "1.1", "q": "Which statement correctly distinguishes IaaS from PaaS?", "c": ["IaaS provides virtualized infrastructure only; PaaS additionally provides a managed application runtime/platform", "IaaS and PaaS are identical, differing only in price", "PaaS requires customers to manage the hypervisor; IaaS does not", "IaaS is always cheaper than PaaS regardless of workload"], "a": 0, "e": "IaaS stops at virtualized infrastructure (compute/storage/network), while PaaS adds a managed platform/runtime layer on top."}, {"obj": "1.3", "q": "Which term is most closely associated with this real-world importance: \"Used within a VPC to separate resources (e.g., public-facing vs. private-only) for security and routing control.\"?", "c": ["VPC", "VPN", "Dedicated Connection", "Subnet"], "a": 3, "e": "Used within a VPC to separate resources (e.g., public-facing vs. private-only) for security and routing control. This describes Subnet (\"A logical subdivision of a network's IP address range.\")."}, {"obj": "2.3", "q": "How would you most accurately define \"Cloud-to-Cloud Migration\"?", "c": ["Moving workloads from one cloud provider or region to another.", "A migration strategy that decommissions an application no longer needed.", "Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.", "Moving workloads out of the cloud back to local infrastructure."], "a": 0, "e": "Moving workloads from one cloud provider or region to another. Often driven by cost optimization, feature needs, or avoiding vendor lock-in."}, {"obj": "4.3", "q": "Which concept is described by the phrase: \"Secure Shell — an encrypted protocol for remote command-line access to cloud resources.\"?", "c": ["Bastion Host", "Discretionary Access Control", "Directory-Based Authentication", "SSH"], "a": 3, "e": "\"Secure Shell — an encrypted protocol for remote command-line access to cloud resources.\" describes SSH. The standard way to securely administer Linux-based cloud instances remotely."}, {"obj": "1.11", "q": "In cloud computing terminology, \"Voice-to-Text\" refers to which of the following?", "c": ["AI technology that converts spoken audio into written text (speech recognition).", "AI technology that converts written text into spoken audio (speech synthesis).", "A device that aggregates and relays data from multiple IoT sensors to the cloud.", "AI technology that determines the emotional tone (positive/negative/neutral) of text."], "a": 0, "e": "AI technology that converts spoken audio into written text (speech recognition). Powers transcription services, voice assistants, and accessibility features."}, {"obj": "1.9", "q": "Which of the following best describes \"Provider-Managed Database\"?", "c": ["A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs.", "A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure.", "A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS).", "A database that organizes data into structured tables with defined relationships (SQL)."], "a": 2, "e": "A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS). Reduces administrative burden significantly, letting teams focus on the data and application instead of the database engine."}, {"obj": "2.1", "q": "A startup wants the lowest upfront cost and fastest time to market, accepting shared multi-tenant infrastructure managed by a third party. Which deployment model fits best?", "c": ["On premises", "Private cloud", "Public cloud", "Community cloud"], "a": 2, "e": "Public cloud infrastructure is owned by a third-party provider and shared across many customers, offering the lowest upfront cost and fastest provisioning."}, {"obj": "4.6", "q": "Which term best matches this description: \"An attack that succeeds because a system was running software with a known, unpatched vulnerability.\"?", "c": ["Ransomware", "Event Monitoring (Security)", "Unnecessary Open Ports", "Vulnerability Exploitation — Outdated Software"], "a": 3, "e": "\"An attack that succeeds because a system was running software with a known, unpatched vulnerability.\" describes Vulnerability Exploitation — Outdated Software. Reinforces why timely patch management is one of the most effective security controls."}, {"obj": "1.7", "q": "An administrator explains the importance of a concept: \"Enables features like live migration and clustering since any host in the cluster can access the same storage.\" What concept is this?", "c": ["Hardware Pass-Through", "SAN (Virtualization Context)", "Cloning", "Stand-Alone Virtualization"], "a": 1, "e": "Enables features like live migration and clustering since any host in the cluster can access the same storage. This describes SAN (Virtualization Context) (\"Storage Area Network — shared block storage accessible by multiple hypervisor hosts.\")."}, {"obj": "1.2", "q": "A company's BIA determines that a critical order-processing system's RTO is 1 hour and RPO is 5 minutes. Which DR site type is most likely to meet both targets?", "c": ["Cold site", "Warm site with near-real-time replication, or a hot site", "A site with only weekly backups", "No DR site is needed"], "a": 1, "e": "A 1-hour RTO and 5-minute RPO require very fast recovery and minimal data loss, typically achievable only with a warm site using frequent replication or a hot site."}, {"obj": "1.10", "q": "Which of the following terms fits this definition: \"Using Function as a Service as the compute resource type for a workload.\"?", "c": ["Network Throughput", "Storage Throughput", "Compute Optimization (Serverless)", "Compute Optimization (Container)"], "a": 2, "e": "\"Using Function as a Service as the compute resource type for a workload.\" describes Compute Optimization (Serverless). Eliminates server management entirely, billing only for actual execution time."}, {"obj": "1.10", "q": "Which combination of compute types would be most appropriate for a workload with a mix of long-running stateful components and short, event-triggered tasks?", "c": ["VMs for the long-running stateful components and serverless functions for the short event-triggered tasks", "Only serverless functions for everything", "Only VMs for everything, including the event-triggered tasks", "Only containers with no VMs or serverless functions"], "a": 0, "e": "Matching each part of the workload to the most appropriate compute type — VMs for persistent stateful needs, serverless for short event-driven tasks — is a core workload optimization principle."}, {"obj": "1.2", "q": "Which term best matches this description: \"Using services from more than one public cloud provider simultaneously.\"?", "c": ["Warm Site", "Cloud Bursting", "Availability Monitoring", "Multicloud Tenancy"], "a": 3, "e": "\"Using services from more than one public cloud provider simultaneously.\" describes Multicloud Tenancy. Reduces vendor lock-in and can improve resilience, but increases operational and integration complexity."}, {"obj": "6.3", "q": "In cloud computing terminology, \"Unauthorized Software\" refers to which of the following?", "c": ["Authentication credentials that have been exposed, such as in code repositories or logs.", "Software installed or running without proper approval, increasing risk and potentially breaching policy.", "An identity gaining higher access than originally granted, often through a flaw or misconfiguration.", "Access to a system or data by someone without proper permission."], "a": 1, "e": "Software installed or running without proper approval, increasing risk and potentially breaching policy. Can introduce vulnerabilities, malware, or licensing violations into an otherwise controlled environment."}, {"obj": "4.6", "q": "Which of the following terms fits this definition: \"A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email.\"?", "c": ["Metadata Attack", "Event Monitoring (Security)", "Phishing", "Malware"], "a": 2, "e": "\"A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email.\" describes Phishing. One of the most common initial access vectors used in real-world breaches."}, {"obj": "4.3", "q": "Which statement accurately describes \"Token-Based Authentication\"?", "c": ["Application Programming Interface — used here for programmatic management/access to cloud resources.", "Authenticating with credentials stored directly on the system rather than a central directory.", "Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.", "Authentication using a temporary token issued after initial login, rather than resending credentials each time."], "a": 3, "e": "Authentication using a temporary token issued after initial login, rather than resending credentials each time. Reduces the exposure of long-term credentials and supports short-lived, revocable sessions."}, {"obj": "2.3", "q": "Which term best matches this description: \"Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.\"?", "c": ["Vendor Lock-In", "Re-Architect", "Retain", "Replatform"], "a": 0, "e": "\"Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.\" describes Vendor Lock-In. A key risk consideration when architecting for portability across multiple providers."}, {"obj": "1.3", "q": "\"VPC Peering\" is best defined as which of the following?", "c": ["Virtual Private Cloud — an isolated, logically defined network within a public cloud provider's infrastructure.", "Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network.", "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port.", "A direct network connection between two VPCs that allows them to communicate as if on the same network."], "a": 3, "e": "A direct network connection between two VPCs that allows them to communicate as if on the same network. Enables private communication between separate VPCs without routing traffic over the public internet."}, {"obj": "3.2", "q": "Which of the following is a key limitation of relying solely on manual scaling for a production workload with unpredictable demand?", "c": ["It responds instantly to sudden demand spikes", "It depends on a human noticing and reacting, which can be too slow for sudden, unpredictable spikes", "It is always cheaper than automated scaling", "It eliminates the need for monitoring"], "a": 1, "e": "Manual scaling depends on a person noticing demand changes and reacting, which is often too slow to handle sudden, unpredictable spikes compared to automated triggers."}, {"obj": "4.2", "q": "A company seeks international certification demonstrating a structured, comprehensive approach to information security management across its organization. Which standard are they most likely pursuing?", "c": ["PCI DSS", "ISO 27001", "SOC 2 exclusively", "A litigation hold policy"], "a": 1, "e": "ISO 27001 is a widely recognized international standard specifying requirements for an information security management system, demonstrating a structured security approach."}, {"obj": "1.6", "q": "Which concept is described by the phrase: \"A single container running in isolation without orchestration.\"?", "c": ["Stand-Alone Container", "Persistent Volume", "Ephemeral Storage", "Image Registry"], "a": 0, "e": "\"A single container running in isolation without orchestration.\" describes Stand-Alone Container. Simple to run for development/testing but lacks automated scaling, healing, or scheduling."}, {"obj": "1.4", "q": "In Cloud+ terminology, \"HDD\" is an abbreviation for which of the following?", "c": ["Hard Disk Drive", "Non-Volatile Memory Express", "Local Area Network", "Internet Service Provider"], "a": 0, "e": "HDD stands for Hard Disk Drive. A traditional magnetic spinning-platter storage device."}, {"obj": "6.3", "q": "A post-incident investigation reveals an attacker used a compromised low-privilege account, then exploited a misconfigured IAM policy to gain administrative access. What best describes the second step of this attack?", "c": ["Cipher suite deprecation", "Privilege escalation via a misconfigured IAM policy", "Unauthorized software installation", "Regional service availability failure"], "a": 1, "e": "Using a misconfigured policy to gain access beyond the originally granted low-privilege level is privilege escalation, a critical concern after any suspected compromise."}, {"obj": "5.2", "q": "A colleague says: \"Provides a versioned, reusable deployment unit for VM-based workloads.\" Which concept are they describing?", "c": ["VM Image Artifact", "Flat File Artifact", "Private Repository", "CI/CD Security"], "a": 0, "e": "Provides a versioned, reusable deployment unit for VM-based workloads. This describes VM Image Artifact (\"A packaged virtual machine image produced and stored as a build output.\")."}, {"obj": "1.7", "q": "A colleague says: \"Speeds up deployment of identical VMs without building each one from scratch.\" Which concept are they describing?", "c": ["Stand-Alone Virtualization", "Host Affinity", "Cloning", "Overlay Network"], "a": 2, "e": "Speeds up deployment of identical VMs without building each one from scratch. This describes Cloning (\"Creating an exact copy of an existing VM.\")."}, {"obj": "2.4", "q": "Why might a team choose YAML over JSON for a configuration file intended to be edited by hand frequently?", "c": ["YAML is always faster to parse programmatically", "YAML is generally considered more human-readable for manually authored configuration files", "JSON cannot represent nested data structures", "YAML is not supported by any tooling"], "a": 1, "e": "YAML is often preferred for hand-edited configuration files due to its more human-readable syntax, even though JSON is equally capable of representing structured data."}, {"obj": "1.3", "q": "A company has dozens of VPCs and on-premises sites that all need to interconnect. Managing individual peering connections has become unmanageable. What should be implemented?", "c": ["A transit gateway", "A single static route", "An access control vestibule", "A community cloud"], "a": 0, "e": "A transit gateway acts as a hub connecting many VPCs and on-premises networks through one central point, avoiding a full peering mesh."}, {"obj": "4.2", "q": "Select the most accurate description of \"Contractual Retention\":", "c": ["Systems and Organization Controls 2 — an audit framework evaluating a service provider's controls around security, availability, and confidentiality.", "Defining who legally owns and controls a given set of data.", "A data retention requirement specified in a contract with a customer or partner.", "A legal requirement to preserve specific data because it may be relevant to pending litigation."], "a": 2, "e": "A data retention requirement specified in a contract with a customer or partner. May require data to be kept longer (or shorter) than the organization's default policy."}, {"obj": "3.4", "q": "Given the description \"Retiring a resource because it has reached the end of its useful life or support.\", which term is being defined?", "c": ["Patch", "Persistent Data", "Decommissioning — End of Life", "Ephemeral Data"], "a": 2, "e": "\"Retiring a resource because it has reached the end of its useful life or support.\" describes Decommissioning — End of Life. Requires planning for data migration/retention before the resource is removed."}, {"obj": "6.2", "q": "A description reads: \"Two networks using conflicting/duplicate IP address ranges.\" Which term does this describe?", "c": ["NTP (Troubleshooting)", "DNS (Troubleshooting)", "Misconfigured Route", "Network Overlap"], "a": 3, "e": "\"Two networks using conflicting/duplicate IP address ranges.\" describes Network Overlap. Commonly causes routing failures when connecting previously separate networks (e.g., via VPN or peering)."}, {"obj": "2.3", "q": "Why does this matter on the exam and in practice? \"Often driven by cost optimization, feature needs, or avoiding vendor lock-in.\" — which term does this explain?", "c": ["Cloud-to-On-Premises Migration", "Cloud-to-Cloud Migration", "On-Premises-to-Cloud Migration", "Replatform"], "a": 1, "e": "Often driven by cost optimization, feature needs, or avoiding vendor lock-in. This describes Cloud-to-Cloud Migration (\"Moving workloads from one cloud provider or region to another.\")."}, {"obj": "1.3", "q": "Which of the following is the correct expansion of \"VLAN\"?", "c": ["Secure Shell", "Virtual LAN", "Real-time Messaging Protocol", "Function as a Service"], "a": 1, "e": "VLAN stands for Virtual LAN. Logically segments a physical switch into multiple isolated broadcast domains."}, {"obj": "2.2", "q": "A team wants to release a new version by routing all traffic to an entirely new, pre-tested environment and instantly rolling back by switching traffic back if something goes wrong. Which strategy is this?", "c": ["Rolling deployment", "Canary deployment", "Blue-green deployment", "In-place deployment"], "a": 2, "e": "Blue-green deployment maintains two parallel environments and switches traffic between them, enabling near-instant rollback."}, {"obj": "6.1", "q": "In cloud computing terminology, \"Deprecation of Functionality\" refers to which of the following?", "c": ["A complete loss of service availability.", "A deployment failing because the deploying identity lacks sufficient rights.", "A deployment failure or performance problem caused by choosing an inappropriately sized resource.", "A previously available feature or API being retired by the provider."], "a": 3, "e": "A previously available feature or API being retired by the provider. Deployments relying on deprecated functionality will eventually fail and must be updated proactively."}, {"obj": "6.2", "q": "A description reads: \"An incorrect entry in a route table sending traffic to the wrong destination.\" Which term does this describe?", "c": ["Protocol Incompatibility", "HTTP Status Codes", "IP Scope Exhaustion", "Misconfigured Route"], "a": 3, "e": "\"An incorrect entry in a route table sending traffic to the wrong destination.\" describes Misconfigured Route. Can cause traffic to be dropped, looped, or sent somewhere unintended."}, {"obj": "1.2", "q": "A colleague says: \"Provides the data needed to detect outages and calculate real-world uptime against SLA targets.\" Which concept are they describing?", "c": ["RPO", "Availability Monitoring", "Cold Site", "Availability Zone"], "a": 1, "e": "Provides the data needed to detect outages and calculate real-world uptime against SLA targets. This describes Availability Monitoring (\"Continuously checking that a resource or service is up and responding as expected.\")."}, {"obj": "3.2", "q": "Why does this matter on the exam and in practice? \"Reacts to gradual changes in demand rather than short spikes.\" — which term does this explain?", "c": ["Scheduled Scaling", "Triggered Scaling — Trending", "Manual Scaling", "Triggered Scaling — Event"], "a": 1, "e": "Reacts to gradual changes in demand rather than short spikes. This describes Triggered Scaling — Trending (\"Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU).\")."}, {"obj": "1.5", "q": "Which of the following best describes \"Loosely Coupled Architecture\"?", "c": ["A design where components interact through well-defined interfaces with minimal direct dependencies.", "A messaging pattern where one event is distributed to multiple downstream consumers/services.", "A mechanism that lets services dynamically find the network location of other services.", "An architecture where an application is broken into small, independently deployable services."], "a": 0, "e": "A design where components interact through well-defined interfaces with minimal direct dependencies. Improves resilience and flexibility since one component's changes or failures don't directly break others."}, {"obj": "6.3", "q": "A company's security team finds that an internal tool was compiled using a cryptographic library with a known, unpatched vulnerability. What category of issue does this represent?", "c": ["Unauthorized access", "Software vulnerability issues", "Cipher suite deprecation only", "Leaked credentials"], "a": 1, "e": "Using a library with a known, unpatched vulnerability is a software vulnerability issue, requiring an update to resolve."}, {"obj": "4.6", "q": "A monitoring system flags that a specific cloud instance's behavior has significantly deviated from its established normal baseline, such as unusual process activity. What is this an example of?", "c": ["A deviation from baseline, a key signal for detecting anomalies", "A routine scheduled maintenance event", "A billing anomaly only", "A DNS resolution failure"], "a": 0, "e": "A deviation from an established baseline is a core observability/security signal used to detect potentially malicious or anomalous activity."}, {"obj": "4.6", "q": "Select the most accurate description of \"Deviation from Baseline\":", "c": ["Network ports left open on a system that are not required for its function.", "A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email.", "A departure from a system's established normal behavior pattern.", "An attack that abuses a cloud instance's metadata service to steal credentials or configuration data."], "a": 2, "e": "A departure from a system's established normal behavior pattern. A key signal used to detect anomalies that might indicate compromise or misuse."}, {"obj": "1.3", "q": "A colleague says: \"Forms the fundamental network boundary for cloud resources, similar to a private on-premises network.\" Which concept are they describing?", "c": ["VPC", "Transit Gateway", "Static Route", "Network Load Balancer"], "a": 0, "e": "Forms the fundamental network boundary for cloud resources, similar to a private on-premises network. This describes VPC (\"Virtual Private Cloud — an isolated, logically defined network within a public cloud provider's infrastructure.\")."}, {"obj": "4.3", "q": "Which of the following terms fits this definition: \"An identity layer built on top of OAuth 2.0 used for authentication (proving who you are).\"?", "c": ["OpenID Connect", "Programmatic Access", "Group-Based Access Control", "Token-Based Authentication"], "a": 0, "e": "\"An identity layer built on top of OAuth 2.0 used for authentication (proving who you are).\" describes OpenID Connect. Widely used for consumer and enterprise single sign-on into cloud applications."}, {"obj": "4.6", "q": "Which term best matches this description: \"Unauthorized use of a system's computing resources to mine cryptocurrency.\"?", "c": ["Unnecessary Open Ports", "Cryptojacking", "Ransomware", "Deviation from Baseline"], "a": 1, "e": "\"Unauthorized use of a system's computing resources to mine cryptocurrency.\" describes Cryptojacking. Often detected through unexplained high CPU usage and increased cloud compute costs."}, {"obj": "5.1", "q": "Which of the following best describes the relationship between a commit and a push in version control?", "c": ["A commit uploads to the remote repository; a push saves locally", "A commit saves a local snapshot of changes; a push uploads those committed changes to a remote/shared repository", "They are the same action performed twice", "A push must always happen before a commit"], "a": 1, "e": "A commit saves changes locally first; a push then uploads those already-committed changes to the shared remote repository, in that order."}, {"obj": "2.3", "q": "Why does this matter on the exam and in practice? \"Similar to re-architecting but often more incremental, improving specific components over time.\" — which term does this explain?", "c": ["Refactor", "Cloud-to-On-Premises Migration", "Retire", "Cloud-to-Cloud Migration"], "a": 0, "e": "Similar to re-architecting but often more incremental, improving specific components over time. This describes Refactor (\"A migration strategy that rewrites portions of an application to better fit cloud-native patterns.\")."}, {"obj": "1.3", "q": "Which statement accurately describes \"VLAN\"?", "c": ["A device or service that filters network traffic based on defined rules.", "Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains.", "A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute).", "A hub service that connects many VPCs and on-premises networks through a single point."], "a": 1, "e": "Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains. Separates traffic types on shared physical/virtual network infrastructure."}, {"obj": "4.2", "q": "Which statement accurately describes \"ISO 27001\"?", "c": ["An organization that publishes best practices and frameworks specifically for cloud security.", "An international standard specifying requirements for an information security management system.", "A data retention requirement mandated by law or industry regulation.", "Payment Card Industry Data Security Standard — security requirements for handling payment card data."], "a": 1, "e": "An international standard specifying requirements for an information security management system. A widely recognized certification demonstrating a structured approach to information security."}, {"obj": "3.3", "q": "Which of the following terms fits this definition: \"Restoring individual files or specific data items rather than an entire dataset.\"?", "c": ["Parallel Recovery", "Backup Encryption", "In-Place Recovery", "Granular Recovery"], "a": 3, "e": "\"Restoring individual files or specific data items rather than an entire dataset.\" describes Granular Recovery. Saves time when only a small subset of data (like one accidentally deleted file) needs to be restored."}, {"obj": "2.3", "q": "Which term is most closely associated with this real-world importance: \"Appropriate for applications not yet ready or not worth migrating due to cost or complexity.\"?", "c": ["Retire", "Refactor", "Retain", "On-Premises-to-Cloud Migration"], "a": 2, "e": "Appropriate for applications not yet ready or not worth migrating due to cost or complexity. This describes Retain (\"A migration strategy that keeps a workload where it currently is, deferring migration.\")."}, {"obj": "6.1", "q": "A team migrates their IaC templates to reference a newer API version after the cloud provider announced the old version would be deprecated in 90 days. What deployment issue were they proactively avoiding?", "c": ["Oversubscription", "Deprecation of functionality causing future deployment failures", "A sizing issue", "A permission issue"], "a": 1, "e": "Proactively updating to the new API version before the deprecation deadline avoids the deployment failures that would occur once the old version stops functioning."}, {"obj": "1.4", "q": "A company wants to reduce storage costs for log files that are actively written for 7 days, then rarely accessed but must be kept for a year. What is the most cost-effective approach?", "c": ["Keep all logs in the hot tier for the entire year", "Automatically transition logs from hot to cooler tiers as they age", "Delete logs after 7 days regardless of retention requirements", "Store all logs exclusively in archive tier from day one"], "a": 1, "e": "Automated tiering that moves aging data from hot to progressively cooler, cheaper tiers balances cost against the retention requirement, since the data is rarely accessed after the initial period but must be retained."}, {"obj": "6.1", "q": "An administrator explains the importance of a concept: \"Deployments relying on deprecated functionality will eventually fail and must be updated proactively.\" What concept is this?", "c": ["Incompatibility (Deployment)", "Deprecation of Functionality", "Partial Outage", "Full Outage"], "a": 1, "e": "Deployments relying on deprecated functionality will eventually fail and must be updated proactively. This describes Deprecation of Functionality (\"A previously available feature or API being retired by the provider.\")."}, {"obj": "4.5", "q": "Which control would be most appropriate for enforcing that a specific service account can only read from one storage bucket and cannot write to or delete any resources?", "c": ["A WAF rule", "An IAM policy scoped to read-only access on that specific bucket", "A network ACL", "DDoS protection"], "a": 1, "e": "IAM policies are the mechanism for defining precise, scoped permissions like read-only access to a single resource, directly enforcing least privilege."}, {"obj": "5.2", "q": "How would you most accurately define \"Public Repository\"?", "c": ["Automatically building, testing, and deploying code changes with minimal manual intervention.", "Compiling/packaging source code into a deployable artifact.", "A code or artifact repository accessible to anyone.", "Incorporating security scanning and checks into the automated pipeline."], "a": 2, "e": "A code or artifact repository accessible to anyone. Convenient for open-source projects but not suitable for proprietary or sensitive code."}, {"obj": "2.1", "q": "Which of the following terms fits this definition: \"Infrastructure physically located and managed within the organization's own facilities.\"?", "c": ["Private Cloud", "On Premises", "Hybrid Cloud", "Public Cloud"], "a": 1, "e": "\"Infrastructure physically located and managed within the organization's own facilities.\" describes On Premises. Gives maximum control over hardware and data location, at the cost of full operational responsibility."}, {"obj": "3.4", "q": "Before applying a major version update to a production database engine, a team first applies it to a staging environment and runs their full test suite. What practice is this?", "c": ["Skipping validation entirely", "Lifecycle testing", "Ignoring compatibility concerns", "Immediate production rollout with no validation"], "a": 1, "e": "Lifecycle testing validates changes like patches and updates before applying them broadly, reducing the risk that an update introduces a new production issue."}, {"obj": "6.1", "q": "An automation script begins making calls faster than the API allows and starts receiving rejected requests. What is happening?", "c": ["API throttling", "A full outage", "A sizing issue", "Regional service availability"], "a": 0, "e": "API throttling is the provider intentionally limiting request rates; exceeding it causes calls to be rejected."}, {"obj": "5.4", "q": "A team wants to build real-time dashboards visualizing metrics collected from their cloud infrastructure and applications. Which tool is commonly used for this visualization?", "c": ["Terraform", "Grafana", "Ansible", "Docker"], "a": 1, "e": "Grafana is widely used to visualize metrics and build monitoring dashboards, often paired with a time-series database as the data source."}, {"obj": "6.2", "q": "Which term best matches this description: \"Incorrect VLAN tagging causing traffic to be dropped or delivered to the wrong segment.\"?", "c": ["Protocol Deprecation", "HTTP Status Codes", "Access vs. Trunk Ports", "VLAN Misconfigured Tags"], "a": 3, "e": "\"Incorrect VLAN tagging causing traffic to be dropped or delivered to the wrong segment.\" describes VLAN Misconfigured Tags. A classic Layer 2 troubleshooting issue, especially after switch or trunk reconfiguration."}, {"obj": "5.3", "q": "In cloud computing terminology, \"REST\" refers to which of the following?", "c": ["Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local.", "Representational State Transfer — an architectural style for web services using standard HTTP methods.", "A query language for APIs that lets clients request exactly the data they need.", "Simple Object Access Protocol — an XML-based messaging protocol for web services."], "a": 1, "e": "Representational State Transfer — an architectural style for web services using standard HTTP methods. The most common style for modern web APIs due to its simplicity and statelessness."}, {"obj": "4.1", "q": "After a scan identifies dozens of vulnerabilities, the security team ranks them by exploitability and business impact before deciding what to fix first. What step is this?", "c": ["Scanning scope definition", "Vulnerability assessment", "Remediation", "Identification"], "a": 1, "e": "Assessment evaluates identified vulnerabilities for severity and impact, driving prioritization before remediation begins."}, {"obj": "1.2", "q": "Why does this matter on the exam and in practice? \"Spreading resources across AZs protects against a single datacenter failure without the latency of a different region.\" — which term does this explain?", "c": ["Hot Site", "Cloud Bursting", "Availability Monitoring", "Availability Zone"], "a": 3, "e": "Spreading resources across AZs protects against a single datacenter failure without the latency of a different region. This describes Availability Zone (\"An isolated location within a region with independent power, cooling, and networking.\")."}, {"obj": "3.4", "q": "An administrator explains the importance of a concept: \"Requires durable storage and appropriate backup strategy since it represents lasting business value.\" What concept is this?", "c": ["Decommissioning — End of Life", "Patch", "Persistent Data", "Major Update"], "a": 2, "e": "Requires durable storage and appropriate backup strategy since it represents lasting business value. This describes Persistent Data (\"Data that must be retained beyond the life of the process or instance that created it.\")."}, {"obj": "5.2", "q": "A company stores proprietary compiled binaries in a registry accessible only to authorized internal systems and employees. What type of repository is this?", "c": ["A public repository", "A private repository", "An open registry with no restrictions", "A community repository"], "a": 1, "e": "A private repository restricts access to authorized users/systems, appropriate for proprietary compiled binaries that shouldn't be publicly accessible."}, {"obj": "1.8", "q": "Which concept is described by the phrase: \"A billing model where a customer pays for an entire physical host, regardless of utilization.\"?", "c": ["Reserved Resources", "Dedicated Host Billing", "Resource Metering", "Tagging"], "a": 1, "e": "\"A billing model where a customer pays for an entire physical host, regardless of utilization.\" describes Dedicated Host Billing. Useful for licensing or compliance requirements that need physical isolation from other tenants."}, {"obj": "1.7", "q": "Which concept is described by the phrase: \"Storage Area Network — shared block storage accessible by multiple hypervisor hosts.\"?", "c": ["NAS (Virtualization Context)", "Hardware Pass-Through", "Stand-Alone Virtualization", "SAN (Virtualization Context)"], "a": 3, "e": "\"Storage Area Network — shared block storage accessible by multiple hypervisor hosts.\" describes SAN (Virtualization Context). Enables features like live migration and clustering since any host in the cluster can access the same storage."}, {"obj": "1.11", "q": "Which of the following best explains why IoT devices commonly use lightweight transmission protocols instead of traditional web protocols?", "c": ["Lightweight protocols are always faster over high-bandwidth connections", "IoT devices often have constrained power, bandwidth, and processing resources that traditional protocols weren't designed for", "Traditional protocols are illegal for IoT use", "Lightweight protocols require more processing power than standard protocols"], "a": 1, "e": "IoT devices are often resource-constrained (power, bandwidth, processing), and lightweight protocols like MQTT/CoAP are specifically designed to operate efficiently under those constraints."}, {"obj": "2.1", "q": "Which statement accurately describes \"Hybrid Cloud\"?", "c": ["Infrastructure shared by several organizations with common concerns such as compliance or security requirements.", "Infrastructure physically located and managed within the organization's own facilities.", "A deployment model combining private/on-premises infrastructure with public cloud resources.", "Infrastructure owned by a third-party provider and shared across many customers (multi-tenant)."], "a": 2, "e": "A deployment model combining private/on-premises infrastructure with public cloud resources. Common for gradual migration, burst capacity, or workloads with data residency constraints."}, {"obj": "5.4", "q": "In cloud computing terminology, \"Terraform\" refers to which of the following?", "c": ["An open-source platform for automating deployment, scaling, and management of containerized applications.", "An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively.", "An open-source, agentless automation tool used for configuration management and orchestration.", "Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization."], "a": 1, "e": "An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively. One of the most widely used multi-cloud IaC tools, using its own HCL configuration language."}, {"obj": "2.4", "q": "Which term best matches this description: \"JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates.\"?", "c": ["JSON", "Drift Detection", "YAML", "IaC Versioning"], "a": 0, "e": "\"JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates.\" describes JSON. One of the two dominant data formats used to define cloud resources declaratively."}, {"obj": "1.3", "q": "An administrator creates a new VPC and needs to logically separate public-facing web servers from private-only database servers within it. What should be configured?", "c": ["Separate VLANs only", "Separate subnets with different route tables and access rules", "A single flat subnet for all resources", "A dedicated connection for each server"], "a": 1, "e": "Subnets within a VPC allow logical separation of resources (like public web tier vs. private database tier) with different routing and access rules."}, {"obj": "5.2", "q": "A description reads: \"Releasing built and tested code to a target environment (e.g., production).\" Which term does this describe?", "c": ["Private Repository", "Build (CI/CD)", "CI/CD Security", "Code Deployment"], "a": 3, "e": "\"Releasing built and tested code to a target environment (e.g., production).\" describes Code Deployment. The \"CD\" in CI/CD — automating this step reduces the risk and effort of releasing changes."}, {"obj": "1.11", "q": "A description reads: \"AI technology that converts spoken audio into written text (speech recognition).\" Which term does this describe?", "c": ["Text-to-Voice", "Text Recognition", "Voice-to-Text", "Text Translation"], "a": 2, "e": "\"AI technology that converts spoken audio into written text (speech recognition).\" describes Voice-to-Text. Powers transcription services, voice assistants, and accessibility features."}, {"obj": "1.5", "q": "Which of the following is an example of using a cloud-provided managed service rather than a self-managed component?", "c": ["Installing and patching a database engine on a self-managed VM", "Using the cloud provider's fully managed message queue service", "Manually configuring load balancing software on a VM", "Writing custom code to replicate a database manually"], "a": 1, "e": "Using the provider's fully managed message queue service offloads operational responsibility to the provider, the definition of a managed service."}, {"obj": "1.7", "q": "Select the most accurate description of \"Stand-Alone Virtualization\":", "c": ["Grouping multiple hypervisor hosts together to share resources and enable failover/migration.", "A virtual network built on top of physical network infrastructure, common in virtualization and containers.", "A single hypervisor host running VMs with no clustering.", "Storage Area Network — shared block storage accessible by multiple hypervisor hosts."], "a": 2, "e": "A single hypervisor host running VMs with no clustering. Simple but offers no failover if the host fails."}, {"obj": "5.2", "q": "Which statement accurately describes \"CI/CD Testing\"?", "c": ["A package format (.deb) used for installing software on Debian-based Linux distributions.", "A code or artifact repository accessible to anyone.", "Automatically running tests against code as part of the pipeline.", "A code or artifact repository restricted to authorized users/systems."], "a": 2, "e": "Automatically running tests against code as part of the pipeline. Catches regressions before code reaches production, a core benefit of CI/CD."}, {"obj": "4.1", "q": "A company decides to scan only its production environment for vulnerabilities, explicitly excluding its staging and development environments from scope. What risk does this decision carry?", "c": ["No risk, since staging and development never contain sensitive data or credentials", "Vulnerabilities in staging/development (which sometimes contain copies of production data or credentials) could go undetected", "This decision has no effect on the vulnerability management program", "Scanning scope has no bearing on actual security risk"], "a": 1, "e": "Excluding staging/development from scope risks missing vulnerabilities in environments that often contain sensitive data, test credentials, or configurations mirroring production."}, {"obj": "1.2", "q": "An administrator explains the importance of a concept: \"Choosing the right region affects latency, data sovereignty, and compliance.\" What concept is this?", "c": ["Availability Monitoring", "Availability Zone", "Region", "Multicloud Tenancy"], "a": 2, "e": "Choosing the right region affects latency, data sovereignty, and compliance. This describes Region (\"A distinct geographic location where a cloud provider operates one or more datacenters.\")."}, {"obj": "5.3", "q": "A mobile app needs a live, continuously updated chat feed without repeatedly polling the server. Which technology is best suited?", "c": ["REST", "SOAP", "Web sockets", "RPC"], "a": 2, "e": "Web sockets provide a persistent, full-duplex connection ideal for real-time, bidirectional communication like live chat."}, {"obj": "2.1", "q": "A university research consortium builds a shared HPC (high-performance computing) cloud platform accessible only to member universities conducting similar research. What deployment model is this?", "c": ["Public cloud", "Community cloud", "On premises", "A single institution's private cloud"], "a": 1, "e": "A community cloud is shared among organizations with common needs (research computing, in this case), restricted to consortium members rather than the general public."}, {"obj": "5.2", "q": "Which of the following terms fits this definition: \"Releasing built and tested code to a target environment (e.g., production).\"?", "c": ["Code Deployment", "Build (CI/CD)", "Private Repository", "CI/CD Security"], "a": 0, "e": "\"Releasing built and tested code to a target environment (e.g., production).\" describes Code Deployment. The \"CD\" in CI/CD — automating this step reduces the risk and effort of releasing changes."}, {"obj": "1.1", "q": "Which statement accurately describes \"PaaS\"?", "c": ["Platform as a Service — provides a managed runtime/platform for developing and deploying applications without managing the underlying OS.", "Infrastructure as a Service — provides virtualized compute, storage, and networking, leaving the OS and above to the customer.", "Function as a Service — lets code run in response to events without provisioning or managing any server (serverless).", "A framework defining which security and operational tasks belong to the cloud provider versus the customer."], "a": 0, "e": "Platform as a Service — provides a managed runtime/platform for developing and deploying applications without managing the underlying OS. Developers push code and the provider handles the OS, runtime, and scaling, speeding up application delivery."}, {"obj": "1.1", "q": "Why does this matter on the exam and in practice? \"Responsibility shifts up the stack as you move from IaaS to PaaS to SaaS — misunderstanding this is a common real-world security gap.\" — which term does this explain?", "c": ["IaaS", "PaaS", "SaaS", "Shared Responsibility Model"], "a": 3, "e": "Responsibility shifts up the stack as you move from IaaS to PaaS to SaaS — misunderstanding this is a common real-world security gap. This describes Shared Responsibility Model (\"A framework defining which security and operational tasks belong to the cloud provider versus the customer.\")."}, {"obj": "6.2", "q": "Users report that a web application is reachable by IP address but not by hostname. What should be checked first?", "c": ["NTP configuration", "DNS resolution", "NAT configuration", "HTTP status codes"], "a": 1, "e": "Reachability by IP but not hostname is a classic sign of a DNS resolution failure or misconfiguration."}, {"obj": "3.1", "q": "\"Alert Response\" is best defined as which of the following?", "c": ["Gathering log data from applications, systems, and services into a central location.", "Combining logs from many sources into a unified, searchable view.", "The defined actions taken once an alert is triaged and confirmed to need action.", "Following a single request as it moves through multiple services in a distributed system."], "a": 2, "e": "The defined actions taken once an alert is triaged and confirmed to need action. Turns detection into resolution — an alert with no response plan provides little value."}, {"obj": "3.1", "q": "Which combination of observability components would best help a team both detect that error rates spiked and understand precisely which service in a request chain caused it?", "c": ["Monitoring metrics to detect the spike, and distributed tracing to pinpoint the responsible service", "Log retention alone", "Alert triage without any metrics or tracing", "A single dashboard showing only CPU usage"], "a": 0, "e": "Metrics detect that something changed (an error rate spike), while tracing pinpoints exactly which service in a multi-hop request chain is responsible, complementing each other."}, {"obj": "3.1", "q": "A company builds an alert rule that pages the on-call engineer only when error rate exceeds 5% for more than 3 consecutive minutes, rather than for every single error. What is this an example of?", "c": ["Poor alert design with no value", "Effective alert triage/tuning to reduce noise while catching real problems", "Log aggregation", "Distributed tracing"], "a": 1, "e": "Setting a meaningful threshold and duration before alerting reduces noise from transient blips while still catching genuinely sustained problems, an example of good alert tuning."}, {"obj": "4.6", "q": "A security review discovers several cloud instances that are running, incurring cost, but are unmonitored and not tied to any active project. What are these called?", "c": ["Bastion hosts", "Zombie instances", "Reserved instances", "Spot instances"], "a": 1, "e": "Zombie instances are forgotten, unmonitored resources that represent both wasted cost and an unmanaged attack surface."}, {"obj": "1.2", "q": "Which of the following terms fits this definition: \"A basic facility with power and space but no pre-installed equipment.\"?", "c": ["Cold Site", "Edge Computing", "Multicloud Tenancy", "Region"], "a": 0, "e": "\"A basic facility with power and space but no pre-installed equipment.\" describes Cold Site. Cheapest DR option, but has by far the longest time to bring online."}, {"obj": "1.6", "q": "Why does this matter on the exam and in practice? \"Provides a central, versioned source for pulling container images during deployment.\" — which term does this explain?", "c": ["Stand-Alone Container", "Ephemeral Storage", "Image Registry", "Port Mapping"], "a": 2, "e": "Provides a central, versioned source for pulling container images during deployment. This describes Image Registry (\"A repository for storing and distributing container images (e.g., Docker Hub, a private registry).\")."}, {"obj": "5.1", "q": "A team wants to work on three different features simultaneously without one feature's incomplete code blocking the others. What source control practice enables this?", "c": ["Working directly on a single shared branch with no isolation", "Branch management, using separate branches for each feature", "Disabling commits entirely", "Avoiding pull requests"], "a": 1, "e": "Branch management allows parallel, isolated development on multiple features simultaneously without one incomplete feature blocking the others."}, {"obj": "4.3", "q": "Which term is most closely associated with this real-world importance: \"Lets organizations use existing corporate identities to access cloud resources without duplicate accounts.\"?", "c": ["Discretionary Access Control", "CLI", "Federation", "SSH"], "a": 2, "e": "Lets organizations use existing corporate identities to access cloud resources without duplicate accounts. This describes Federation (\"Allowing users to authenticate using credentials from a separate, trusted identity provider.\")."}, {"obj": "1.1", "q": "A company subscribes to a cloud-hosted CRM tool that they access entirely through a browser and configure only with their own business data. Which model is this?", "c": ["IaaS", "PaaS", "SaaS", "FaaS"], "a": 2, "e": "SaaS delivers a fully managed application; the customer only configures their own data and settings within it."}, {"obj": "1.11", "q": "\"IoT Communication\" is best defined as which of the following?", "c": ["The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data.", "A device that aggregates and relays data from multiple IoT sensors to the cloud.", "A device that collects data from the physical environment (temperature, motion, etc.).", "Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case."], "a": 0, "e": "The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data. Choice of communication method affects range, power consumption, and bandwidth available to the device."}, {"obj": "4.6", "q": "Which concept is described by the phrase: \"Malicious software designed to damage, disrupt, or gain unauthorized access to a system.\"?", "c": ["Unnecessary Open Ports", "Metadata Attack", "Malware", "Vulnerability Exploitation — Human Error"], "a": 2, "e": "\"Malicious software designed to damage, disrupt, or gain unauthorized access to a system.\" describes Malware. A broad category of threats requiring layered defenses like endpoint protection and patching."}, {"obj": "4.3", "q": "Which term best matches this description: \"Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.\"?", "c": ["SDK", "Web Portal", "SSH", "RDP"], "a": 3, "e": "\"Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.\" describes RDP. The standard way to remotely access Windows-based cloud instances."}, {"obj": "1.8", "q": "In cloud computing terminology, \"Spot Instance\" refers to which of the following?", "c": ["Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice.", "Adjusting the size/type of provisioned resources to match actual workload demand.", "Pre-purchasing capacity for a discounted rate in exchange for a committed term.", "Tracking actual consumption of cloud resources for billing and capacity planning purposes."], "a": 0, "e": "Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice. Ideal for fault-tolerant, interruptible workloads like batch processing, but not suitable for critical always-on services."}, {"obj": "1.3", "q": "Why does this matter on the exam and in practice? \"Every subnet in a VPC is associated with a route table controlling how its traffic flows.\" — which term does this explain?", "c": ["Firewall", "Route Table", "Network Load Balancer", "VPN"], "a": 1, "e": "Every subnet in a VPC is associated with a route table controlling how its traffic flows. This describes Route Table (\"A set of rules that determines where network traffic is directed.\")."}, {"obj": "5.1", "q": "Which concept is described by the phrase: \"Saving a snapshot of changes to the local version control history.\"?", "c": ["Code Commit", "Pull Request", "Code Merge", "Code Review"], "a": 0, "e": "\"Saving a snapshot of changes to the local version control history.\" describes Code Commit. The basic unit of change tracking in most version control systems."}, {"obj": "4.3", "q": "A company wants to grant permissions based on job function (e.g., \"Database Admins\") rather than to each individual employee. What access model is this?", "c": ["Discretionary access control", "Role-based access control", "OAuth 2.0", "Federation"], "a": 1, "e": "RBAC assigns permissions based on a defined role that users are placed into, simplifying administration."}, {"obj": "1.1", "q": "Given the description \"Platform as a Service — provides a managed runtime/platform for developing and deploying applications without managing the underlying OS.\", which term is being defined?", "c": ["PaaS", "Shared Responsibility Model", "FaaS", "IaaS"], "a": 0, "e": "\"Platform as a Service — provides a managed runtime/platform for developing and deploying applications without managing the underlying OS.\" describes PaaS. Developers push code and the provider handles the OS, runtime, and scaling, speeding up application delivery."}, {"obj": "1.10", "q": "Which term best matches this description: \"Using containers as the compute resource type for a workload.\"?", "c": ["Compute Optimization (Container)", "Managed Services (Optimization)", "Compute Optimization (Serverless)", "Network Throughput"], "a": 0, "e": "\"Using containers as the compute resource type for a workload.\" describes Compute Optimization (Container). More lightweight and portable than VMs, ideal for microservices and rapid scaling."}, {"obj": "5.4", "q": "How would you most accurately define \"Ansible\"?", "c": ["A widely used open-source automation server for building CI/CD pipelines.", "An open-source, agentless automation tool used for configuration management and orchestration.", "Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization.", "An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively."], "a": 1, "e": "An open-source, agentless automation tool used for configuration management and orchestration. Uses simple YAML playbooks to automate repetitive configuration tasks across many systems."}, {"obj": "1.7", "q": "In cloud computing terminology, \"Hardware Pass-Through\" refers to which of the following?", "c": ["A single hypervisor host running VMs with no clustering.", "Creating an exact copy of an existing VM.", "Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction.", "A virtual network built on top of physical network infrastructure, common in virtualization and containers."], "a": 2, "e": "Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction. Used when a workload needs near-native performance from a specific device, like a GPU."}, {"obj": "2.2", "q": "How would you most accurately define \"Blue-Green Deployment\"?", "c": ["Updating an existing server or instance directly rather than deploying an entirely new one.", "Updating instances incrementally, a few at a time, rather than all at once.", "Gradually rolling out a change to a small subset of users or servers before a full rollout.", "A strategy running two identical environments (blue and green), switching traffic to the new version once verified."], "a": 3, "e": "A strategy running two identical environments (blue and green), switching traffic to the new version once verified. Allows near-instant rollback by simply switching traffic back to the previous environment."}, {"obj": "5.4", "q": "A team needs to declaratively define and provision cloud infrastructure across multiple providers using a single configuration language and maintain state of what's been deployed. Which tool is purpose-built for this?", "c": ["Docker", "Terraform", "Grafana", "Git"], "a": 1, "e": "Terraform is a widely used multi-cloud Infrastructure as Code tool that declaratively provisions and tracks the state of cloud resources using its own configuration language."}, {"obj": "6.1", "q": "A deployment fails because it requests more vCPUs than the account's regional quota allows, even though billing is not an issue. What is the root cause?", "c": ["API throttling", "A service quota limit being exceeded", "Regional service availability", "Oversubscription of physical hardware"], "a": 1, "e": "Service quotas cap how many of a given resource type can be provisioned in an account/region; exceeding one causes a deployment failure regardless of billing status."}, {"obj": "6.2", "q": "A company merges its cloud VPC with an acquired company's on-premises network via VPN, and both networks turn out to use the identical 10.0.0.0/16 address range. What problem will this cause?", "c": ["No problem; identical ranges are automatically resolved", "Network overlap, causing routing conflicts since both networks claim the same address space", "Improved performance due to matching subnets", "Automatic NAT translation with no further action needed"], "a": 1, "e": "Identical, overlapping IP address ranges between two networks being connected causes routing conflicts, since routers cannot distinguish which network owns that address space."}, {"obj": "1.4", "q": "An administrator explains the importance of a concept: \"Ideal for shared application data and home directories accessed by multiple servers simultaneously.\" What concept is this?", "c": ["HDD", "Cold Storage Tier", "File Storage", "SSD"], "a": 2, "e": "Ideal for shared application data and home directories accessed by multiple servers simultaneously. This describes File Storage (\"Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB).\")."}, {"obj": "2.2", "q": "An administrator updates each of ten web servers one at a time, keeping the application available throughout the entire process. What strategy is this?", "c": ["Blue-green deployment", "Rolling deployment", "In-place deployment", "Canary deployment"], "a": 1, "e": "Rolling deployment updates instances incrementally, keeping the application available during the whole rollout."}, {"obj": "5.4", "q": "Which statement accurately describes \"Ansible\"?", "c": ["An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively.", "An open-source, agentless automation tool used for configuration management and orchestration.", "Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization.", "A distributed version control system used to track changes in source code."], "a": 1, "e": "An open-source, agentless automation tool used for configuration management and orchestration. Uses simple YAML playbooks to automate repetitive configuration tasks across many systems."}, {"obj": "2.4", "q": "In cloud computing terminology, \"Drift Detection\" refers to which of the following?", "c": ["Managing system or application configuration through code rather than manual configuration.", "Identifying when a deployed resource's actual state no longer matches its defined IaC configuration.", "Yet Another Markup Language — a human-readable data format widely used for IaC and configuration files.", "JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates."], "a": 1, "e": "Identifying when a deployed resource's actual state no longer matches its defined IaC configuration. Helps catch unauthorized or manual changes that could cause inconsistency or security gaps."}, {"obj": "4.2", "q": "Which term is most closely associated with this real-world importance: \"May require data to be kept longer (or shorter) than the organization's default policy.\"?", "c": ["Contractual Retention", "PCI DSS", "Data Ownership", "Data Sovereignty"], "a": 0, "e": "May require data to be kept longer (or shorter) than the organization's default policy. This describes Contractual Retention (\"A data retention requirement specified in a contract with a customer or partner.\")."}, {"obj": "1.8", "q": "A colleague says: \"Prevents overspending on oversized resources while avoiding performance issues from undersized ones.\" Which concept are they describing?", "c": ["Spot Instance", "Rightsizing", "Resource Metering", "Reserved Resources"], "a": 1, "e": "Prevents overspending on oversized resources while avoiding performance issues from undersized ones. This describes Rightsizing (\"Adjusting the size/type of provisioned resources to match actual workload demand.\")."}, {"obj": "3.2", "q": "An administrator explicitly increases the number of running instances ahead of a planned marketing campaign, rather than relying on any automated trigger. What scaling approach is this?", "c": ["Manual scaling", "Triggered scaling — load-based", "Event-triggered scaling", "Vertical scaling"], "a": 0, "e": "Manual scaling involves an administrator explicitly changing capacity rather than relying on automated triggers, useful for planned events with predictable but non-recurring timing."}, {"obj": "1.7", "q": "The acronym \"NAS\" stands for:", "c": ["Network Attached Storage", "Remote Desktop Protocol", "Input/Output Operations Per Second", "Platform as a Service"], "a": 0, "e": "NAS stands for Network Attached Storage. File-level storage accessed over a network, typically via NFS or SMB/CIFS."}, {"obj": "1.9", "q": "The acronym \"SQL\" stands for:", "c": ["Data Loss Prevention", "Software-defined Network", "Structured Query Language", "Central Processing Unit"], "a": 2, "e": "SQL stands for Structured Query Language. The standard language used to query and manage data in relational databases."}, {"obj": "5.4", "q": "A description reads: \"A platform for building, running, and managing containers.\" Which term does this describe?", "c": ["Ansible", "Docker", "Git", "Jenkins"], "a": 1, "e": "\"A platform for building, running, and managing containers.\" describes Docker. The most widely used container runtime and image format in modern DevOps workflows."}, {"obj": "6.1", "q": "Why does this matter on the exam and in practice? \"A very common root cause of failed deployments, especially after an update to one dependency.\" — which term does this explain?", "c": ["Full Outage", "Outdated Component Definitions", "API Throttling", "Incompatibility (Deployment)"], "a": 3, "e": "A very common root cause of failed deployments, especially after an update to one dependency. This describes Incompatibility (Deployment) (\"A failure caused by mismatched software, hardware, or configuration versions.\")."}, {"obj": "4.2", "q": "\"Data Sovereignty\" is best defined as which of the following?", "c": ["A data retention requirement mandated by law or industry regulation.", "Defining who legally owns and controls a given set of data.", "An organization that publishes best practices and frameworks specifically for cloud security.", "The principle that data is subject to the laws of the country in which it is physically located."], "a": 3, "e": "The principle that data is subject to the laws of the country in which it is physically located. Determines which region a workload must be deployed in to satisfy legal requirements."}, {"obj": "3.2", "q": "How would you most accurately define \"Triggered Scaling — Trending\"?", "c": ["Adding more instances of a resource to handle increased load (scale out).", "Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU).", "An administrator explicitly changing resource capacity rather than relying on automation.", "Scaling resources up or down at predefined times based on known usage patterns."], "a": 1, "e": "Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU). Reacts to gradual changes in demand rather than short spikes."}, {"obj": "1.7", "q": "A machine learning workload running in a VM needs near-native performance from a physical GPU, bypassing the hypervisor's usual abstraction layer. What should be configured?", "c": ["An overlay network", "Hardware pass-through", "Host affinity", "Local storage"], "a": 1, "e": "Hardware pass-through gives a VM direct access to a physical device like a GPU, avoiding hypervisor overhead for near-native performance."}, {"obj": "5.1", "q": "Which term is most closely associated with this real-world importance: \"The standard workflow mechanism for reviewing and discussing changes before merging.\"?", "c": ["Code Review", "Branch Management", "Code Merge", "Pull Request"], "a": 3, "e": "The standard workflow mechanism for reviewing and discussing changes before merging. This describes Pull Request (\"A formal request to merge a proposed code change into a shared branch, typically triggering review.\")."}, {"obj": "2.3", "q": "An administrator explains the importance of a concept: \"Reduces the overall migration scope and ongoing costs by eliminating unnecessary systems.\" What concept is this?", "c": ["Retire", "Rehost", "Refactor", "Vendor Lock-In"], "a": 0, "e": "Reduces the overall migration scope and ongoing costs by eliminating unnecessary systems. This describes Retire (\"A migration strategy that decommissions an application no longer needed.\")."}, {"obj": "4.3", "q": "An administrator explains the importance of a concept: \"Enables automation but requires careful credential management since keys can be leaked or misused.\" What concept is this?", "c": ["Programmatic Access", "RDP", "SSH", "Federation"], "a": 0, "e": "Enables automation but requires careful credential management since keys can be leaked or misused. This describes Programmatic Access (\"Accessing cloud resources via code rather than a human using a GUI (API/SDK).\")."}, {"obj": "5.4", "q": "Which concept is described by the phrase: \"An open-source platform for automating deployment, scaling, and management of containerized applications.\"?", "c": ["ELK Stack", "Grafana", "Jenkins", "Kubernetes"], "a": 3, "e": "\"An open-source platform for automating deployment, scaling, and management of containerized applications.\" describes Kubernetes. The de facto standard for container orchestration in modern cloud-native environments."}, {"obj": "4.2", "q": "Which of the following terms fits this definition: \"Requirements or preferences about the physical location where data is stored or processed.\"?", "c": ["SOC2", "Cloud Security Alliance", "Regulatory Retention", "Data Locality"], "a": 3, "e": "\"Requirements or preferences about the physical location where data is stored or processed.\" describes Data Locality. Closely related to, but distinct from, data sovereignty — it may be a business rather than legal requirement."}, {"obj": "4.6", "q": "Which of the following would most strongly suggest a metadata-service-based attack rather than a network-based attack?", "c": ["A flood of traffic overwhelming network bandwidth", "An attacker retrieving temporary cloud credentials from an instance's metadata endpoint and using them elsewhere", "An employee clicking a phishing link", "A DNS resolution failure"], "a": 1, "e": "Retrieving and misusing temporary credentials from an instance's metadata service is specifically characteristic of a metadata attack, a cloud-specific attack pattern."}, {"obj": "3.1", "q": "An administrator explains the importance of a concept: \"Prevents alert fatigue and ensures the most critical issues are addressed first.\" What concept is this?", "c": ["Log Aggregation", "Alert Triage", "Alert Response", "Log Retention"], "a": 1, "e": "Prevents alert fatigue and ensures the most critical issues are addressed first. This describes Alert Triage (\"The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.\")."}, {"obj": "4.3", "q": "A description reads: \"Allowing users to authenticate using credentials from a separate, trusted identity provider.\" Which term does this describe?", "c": ["Federation", "SSH", "API (IAM Context)", "OAuth 2.0"], "a": 0, "e": "\"Allowing users to authenticate using credentials from a separate, trusted identity provider.\" describes Federation. Lets organizations use existing corporate identities to access cloud resources without duplicate accounts."}, {"obj": "4.5", "q": "In cloud computing terminology, \"IPS/IDS\" refers to which of the following?", "c": ["Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity.", "Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications.", "A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs.", "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data."], "a": 0, "e": "Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity. IDS alerts on suspicious activity; IPS goes further by actively blocking it in real time."}, {"obj": "4.4", "q": "How would you most accurately define \"Data at Rest Encryption\"?", "c": ["A security model that assumes no user or device should be trusted by default, even inside the network perimeter.", "Encrypting stored data so it remains unreadable without the correct key.", "Securely storing and controlling access to credentials, API keys, and other sensitive configuration values.", "Controls governing which files and directories a container process can read or write."], "a": 1, "e": "Encrypting stored data so it remains unreadable without the correct key. Protects data even if the underlying storage media is stolen or improperly accessed."}, {"obj": "6.2", "q": "Why does this matter on the exam and in practice? \"Can cause traffic to be dropped, looped, or sent somewhere unintended.\" — which term does this explain?", "c": ["Protocol Deprecation", "Misconfigured Route", "IP Scope Exhaustion", "DHCP (Troubleshooting)"], "a": 1, "e": "Can cause traffic to be dropped, looped, or sent somewhere unintended. This describes Misconfigured Route (\"An incorrect entry in a route table sending traffic to the wrong destination.\")."}, {"obj": "3.2", "q": "Which concept is described by the phrase: \"Adding more instances of a resource to handle increased load (scale out).\"?", "c": ["Triggered Scaling — Event", "Scheduled Scaling", "Vertical Scaling", "Horizontal Scaling"], "a": 3, "e": "\"Adding more instances of a resource to handle increased load (scale out).\" describes Horizontal Scaling. Improves both capacity and redundancy, and is the standard scaling approach in cloud-native design."}, {"obj": "1.8", "q": "A startup with unpredictable, rapidly changing workloads wants maximum flexibility with no upfront commitment, accepting a higher per-unit cost in exchange. What billing model fits?", "c": ["Reserved resources", "Pay-as-you-go", "Dedicated host billing", "Spot instances only"], "a": 1, "e": "Pay-as-you-go charges only for actual consumption with no commitment, maximizing flexibility for unpredictable workloads at a higher per-unit price than reserved options."}, {"obj": "1.3", "q": "What does the abbreviation \"BGP\" stand for?", "c": ["Random Access Memory", "Hypertext Transfer Protocol", "Border Gateway Protocol", "Information Technology Infrastructure Library"], "a": 2, "e": "BGP stands for Border Gateway Protocol. The routing protocol used to exchange routing information between large networks."}, {"obj": "2.5", "q": "A description reads: \"The capacity, performance, and durability needs a workload has for its data.\" Which term does this describe?", "c": ["Compute Requirements", "Network Requirements", "Availability Requirements", "Storage Requirements"], "a": 3, "e": "\"The capacity, performance, and durability needs a workload has for its data.\" describes Storage Requirements. Must be assessed before provisioning to choose the right storage type and tier."}, {"obj": "1.1", "q": "Given the description \"A framework defining which security and operational tasks belong to the cloud provider versus the customer.\", which term is being defined?", "c": ["FaaS", "SaaS", "Shared Responsibility Model", "PaaS"], "a": 2, "e": "\"A framework defining which security and operational tasks belong to the cloud provider versus the customer.\" describes Shared Responsibility Model. Responsibility shifts up the stack as you move from IaaS to PaaS to SaaS — misunderstanding this is a common real-world security gap."}, {"obj": "4.6", "q": "Which of the following best describes \"Vulnerability Exploitation — Human Error\"?", "c": ["A cloud instance that is running but forgotten, unmonitored, or unmanaged.", "Network ports left open on a system that are not required for its function.", "An attack that abuses a cloud instance's metadata service to steal credentials or configuration data.", "An attack that succeeds due to a mistake made by an authorized user (misconfiguration, mishandling credentials, etc.)."], "a": 3, "e": "An attack that succeeds due to a mistake made by an authorized user (misconfiguration, mishandling credentials, etc.). Highlights that technical controls alone can't fully prevent security incidents caused by human mistakes."}, {"obj": "5.2", "q": "A colleague says: \"The \"CI\" in CI/CD — frequent integration catches conflicts and bugs early.\" Which concept are they describing?", "c": ["CI/CD Workflow", "Debian Package", "Code Integration", "CI/CD Testing"], "a": 2, "e": "The \"CI\" in CI/CD — frequent integration catches conflicts and bugs early. This describes Code Integration (\"Merging code changes from multiple contributors into a shared, continuously tested codebase.\")."}, {"obj": "3.3", "q": "After a ransomware attack encrypts an entire production file server, the team needs to recover all data at once from the last known-good backup. What type of recovery is this?", "c": ["Granular recovery", "Bulk recovery", "Parallel recovery only", "Backup replication"], "a": 1, "e": "Bulk recovery restores a large set of data all at once, appropriate when an entire system or dataset needs to be recovered together, as in this ransomware scenario."}, {"obj": "1.7", "q": "Which statement accurately describes \"SAN (Virtualization Context)\"?", "c": ["A virtual network built on top of physical network infrastructure, common in virtualization and containers.", "Storage physically attached to a single hypervisor host.", "Creating an exact copy of an existing VM.", "Storage Area Network — shared block storage accessible by multiple hypervisor hosts."], "a": 3, "e": "Storage Area Network — shared block storage accessible by multiple hypervisor hosts. Enables features like live migration and clustering since any host in the cluster can access the same storage."}, {"obj": "3.3", "q": "Given the description \"Copying backup data to another location (often off-site or another region).\", which term is being defined?", "c": ["In-Place Recovery", "Backup Integrity Testing", "Differential Backup", "Backup Replication"], "a": 3, "e": "\"Copying backup data to another location (often off-site or another region).\" describes Backup Replication. Protects against a disaster affecting the primary backup location."}, {"obj": "1.6", "q": "A team needs to automatically deploy, scale, and self-heal hundreds of containers across a cluster of servers. What is required?", "c": ["A stand-alone container runtime", "Workload orchestration", "An image registry only", "Port mapping only"], "a": 1, "e": "Workload orchestration (e.g., Kubernetes) automates deployment, scaling, and healing of containers at scale."}, {"obj": "1.4", "q": "A company has data that must be retrievable within milliseconds because it's part of an active production database. Which storage tier is appropriate?", "c": ["Archive", "Cold", "Warm", "Hot"], "a": 3, "e": "Hot storage is optimized for frequently accessed data needing the fastest retrieval, appropriate for active production workloads."}, {"obj": "2.5", "q": "Select the most accurate description of \"Compute Requirements\":", "c": ["The bandwidth, latency, and connectivity needs of a workload.", "Legal or regulatory obligations a workload's data and processing must meet.", "The capacity, performance, and durability needs a workload has for its data.", "The processing power (CPU, RAM) needed to run a workload effectively."], "a": 3, "e": "The processing power (CPU, RAM) needed to run a workload effectively. Determines the instance size and type selected during provisioning."}, {"obj": "2.1", "q": "A company decides that its existing on-premises ERP system will remain in place indefinitely with no cloud migration planned, while new applications will be built in the public cloud. What best describes their overall deployment approach?", "c": ["Pure public cloud", "A hybrid arrangement combining on-premises and public cloud resources", "Pure community cloud", "Pure private cloud"], "a": 1, "e": "Running some systems on-premises while building new applications in the public cloud is a hybrid cloud arrangement, even without one workload spanning both environments."}, {"obj": "4.2", "q": "A description reads: \"A data retention requirement mandated by law or industry regulation.\" Which term does this describe?", "c": ["Regulatory Retention", "Cloud Security Alliance", "Data Locality", "Litigation Hold"], "a": 0, "e": "\"A data retention requirement mandated by law or industry regulation.\" describes Regulatory Retention. Non-compliance can result in legal penalties, distinct from purely internal retention preferences."}, {"obj": "1.3", "q": "A colleague says: \"Used within a VPC to separate resources (e.g., public-facing vs. private-only) for security and routing control.\" Which concept are they describing?", "c": ["Static Route", "Dedicated Connection", "Firewall", "Subnet"], "a": 3, "e": "Used within a VPC to separate resources (e.g., public-facing vs. private-only) for security and routing control. This describes Subnet (\"A logical subdivision of a network's IP address range.\")."}, {"obj": "1.3", "q": "In cloud computing terminology, \"CDN\" refers to which of the following?", "c": ["A direct network connection between two VPCs that allows them to communicate as if on the same network.", "Content Delivery Network — a geographically distributed set of servers that cache content closer to end users.", "A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute).", "Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks."], "a": 1, "e": "Content Delivery Network — a geographically distributed set of servers that cache content closer to end users. Reduces latency and origin server load by serving cached static (and sometimes dynamic) content from edge locations."}, {"obj": "1.3", "q": "Which term is most closely associated with this real-world importance: \"Every subnet in a VPC is associated with a route table controlling how its traffic flows.\"?", "c": ["Route Table", "Transit Gateway", "Application Load Balancer", "VLAN"], "a": 0, "e": "Every subnet in a VPC is associated with a route table controlling how its traffic flows. This describes Route Table (\"A set of rules that determines where network traffic is directed.\")."}, {"obj": "6.2", "q": "A newly provisioned server fails to receive an IP address automatically and instead shows a self-assigned address. What service should be checked first?", "c": ["DHCP", "DNS", "NAT", "HTTP status codes"], "a": 0, "e": "A failure to receive an automatic IP address points directly to a DHCP service issue, since DHCP is responsible for automatically assigning IP addressing information."}, {"obj": "4.6", "q": "Given the description \"An attack that abuses a cloud instance's metadata service to steal credentials or configuration data.\", which term is being defined?", "c": ["Cryptojacking", "Metadata Attack", "DDoS", "Unnecessary Open Ports"], "a": 1, "e": "\"An attack that abuses a cloud instance's metadata service to steal credentials or configuration data.\" describes Metadata Attack. A cloud-specific attack vector, since metadata services often provide temporary credentials to the instance."}, {"obj": "1.3", "q": "In cloud computing terminology, \"Firewall\" refers to which of the following?", "c": ["Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.", "A device or service that filters network traffic based on defined rules.", "Content Delivery Network — a geographically distributed set of servers that cache content closer to end users.", "Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network."], "a": 1, "e": "A device or service that filters network traffic based on defined rules. The primary control for restricting which traffic is allowed in/out of a cloud network segment."}, {"obj": "3.4", "q": "Which term best matches this description: \"A smaller update, typically with bug fixes and small improvements.\"?", "c": ["Minor Update", "Ephemeral Data", "Decommissioning — End of Support", "Patch"], "a": 0, "e": "\"A smaller update, typically with bug fixes and small improvements.\" describes Minor Update. Generally lower risk than major updates but should still be tested before production rollout."}, {"obj": "1.3", "q": "Select the most accurate description of \"Static Route\":", "c": ["A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute).", "Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.", "A manually configured network route that does not change dynamically.", "A hub service that connects many VPCs and on-premises networks through a single point."], "a": 2, "e": "A manually configured network route that does not change dynamically. Simple and predictable, but requires manual updates if the network topology changes."}, {"obj": "4.2", "q": "A colleague says: \"Drives how strictly a given piece of data must be protected and handled.\" Which concept are they describing?", "c": ["Data Sovereignty", "Data Classification", "Data Locality", "ISO 27001"], "a": 1, "e": "Drives how strictly a given piece of data must be protected and handled. This describes Data Classification (\"Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted).\")."}, {"obj": "3.4", "q": "A company's customer order records must be retained and remain durable well beyond the life of any single application instance or process. What type of data is this?", "c": ["Ephemeral data", "Persistent data", "Temporary session data", "Cache-only data"], "a": 1, "e": "Persistent data must be retained beyond the life of the process that created it, requiring durable storage and an appropriate backup strategy."}, {"obj": "5.4", "q": "A description reads: \"An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively.\" Which term does this describe?", "c": ["Terraform", "Git", "Ansible", "ELK Stack"], "a": 0, "e": "\"An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively.\" describes Terraform. One of the most widely used multi-cloud IaC tools, using its own HCL configuration language."}, {"obj": "3.1", "q": "Select the most accurate description of \"Log Collection\":", "c": ["Gathering log data from applications, systems, and services into a central location.", "Defining how long log data is kept before being archived or deleted.", "The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.", "Combining logs from many sources into a unified, searchable view."], "a": 0, "e": "Gathering log data from applications, systems, and services into a central location. The first step in observability — without collection, logs remain scattered and hard to analyze."}, {"obj": "1.5", "q": "In cloud computing terminology, \"Service Discovery\" refers to which of the following?", "c": ["A design where components interact through well-defined interfaces with minimal direct dependencies.", "A mechanism that lets services dynamically find the network location of other services.", "An architecture where an application is broken into small, independently deployable services.", "A messaging pattern where one event is distributed to multiple downstream consumers/services."], "a": 1, "e": "A mechanism that lets services dynamically find the network location of other services. Essential in dynamic cloud-native environments where service instances and IP addresses change constantly."}, {"obj": "5.4", "q": "In cloud computing terminology, \"Git\" refers to which of the following?", "c": ["An open-source platform for automating deployment, scaling, and management of containerized applications.", "A widely used open-source automation server for building CI/CD pipelines.", "Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization.", "A distributed version control system used to track changes in source code."], "a": 3, "e": "A distributed version control system used to track changes in source code. The de facto standard version control system underlying most modern DevOps workflows."}, {"obj": "1.11", "q": "A description reads: \"AI technology that determines the emotional tone (positive/negative/neutral) of text.\" Which term does this describe?", "c": ["Text Translation", "Machine Learning", "Visual Recognition", "Sentiment Analysis"], "a": 3, "e": "\"AI technology that determines the emotional tone (positive/negative/neutral) of text.\" describes Sentiment Analysis. Used to analyze customer feedback, reviews, and social media at scale."}, {"obj": "1.10", "q": "A description reads: \"Using provider-operated services instead of self-managed infrastructure to reduce operational overhead.\" Which term does this describe?", "c": ["Compute Optimization (VM)", "Managed Services (Optimization)", "Network Throughput", "Compute Optimization (Container)"], "a": 1, "e": "\"Using provider-operated services instead of self-managed infrastructure to reduce operational overhead.\" describes Managed Services (Optimization). Frees up staff time from routine maintenance so they can focus on higher-value work."}, {"obj": "6.1", "q": "A colleague says: \"Can cause performance problems or outright deployment failure if requested resources aren't actually available.\" Which concept are they describing?", "c": ["Oversubscription", "Deprecation of Functionality", "Resource Allocation Misconfiguration", "Partial Outage"], "a": 2, "e": "Can cause performance problems or outright deployment failure if requested resources aren't actually available. This describes Resource Allocation Misconfiguration (\"Incorrectly assigned CPU, memory, or storage limits for a workload.\")."}, {"obj": "4.4", "q": "An administrator explains the importance of a concept: \"Provides a well-known, widely adopted baseline for hardening systems and cloud services.\" What concept is this?", "c": ["Object Storage Security", "CIS Benchmark", "Hardening", "Vendor-Specific Benchmark"], "a": 1, "e": "Provides a well-known, widely adopted baseline for hardening systems and cloud services. This describes CIS Benchmark (\"A set of vendor-neutral, consensus-based configuration hardening guidelines.\")."}, {"obj": "4.2", "q": "Why does this matter on the exam and in practice? \"Closely related to, but distinct from, data sovereignty — it may be a business rather than legal requirement.\" — which term does this explain?", "c": ["Data Classification", "Cloud Security Alliance", "Data Locality", "ISO 27001"], "a": 2, "e": "Closely related to, but distinct from, data sovereignty — it may be a business rather than legal requirement. This describes Data Locality (\"Requirements or preferences about the physical location where data is stored or processed.\")."}, {"obj": "1.3", "q": "Which concept is described by the phrase: \"Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains.\"?", "c": ["Route Table", "VLAN", "VPN", "Firewall"], "a": 1, "e": "\"Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains.\" describes VLAN. Separates traffic types on shared physical/virtual network infrastructure."}, {"obj": "1.1", "q": "A company using a SaaS email platform experiences a data breach because an employee reused a weak, previously compromised password with no MFA enabled. Under the shared responsibility model, who bears primary responsibility for this specific failure?", "c": ["The SaaS provider, since they own the application", "The customer, since identity and access management for their own users is a customer responsibility even in SaaS", "Neither, since SaaS providers are fully responsible for all security", "The customer's ISP"], "a": 1, "e": "Even in SaaS, the customer typically retains responsibility for managing their own user accounts, authentication practices, and access policies."}, {"obj": "6.2", "q": "Which term is most closely associated with this real-world importance: \"Common after upgrading one side of a connection without updating the other.\"?", "c": ["Access vs. Trunk Ports", "HTTP Status Codes", "Protocol Deprecation", "Protocol Incompatibility"], "a": 3, "e": "Common after upgrading one side of a connection without updating the other. This describes Protocol Incompatibility (\"A connectivity failure caused by two systems using different or mismatched protocol versions.\")."}, {"obj": "1.5", "q": "A company wants a new order-processing service to automatically register itself and be discoverable by other services as soon as it starts, without manual configuration. What capability is required?", "c": ["Fan-out messaging only", "Service discovery", "A monolithic deployment", "Static IP assignment maintained manually"], "a": 1, "e": "Automatic registration and discoverability of new service instances is the core function of service discovery."}, {"obj": "1.3", "q": "A colleague says: \"Simplifies large-scale network architectures compared to a full mesh of individual peering connections.\" Which concept are they describing?", "c": ["Dedicated Connection", "VPC", "Transit Gateway", "Firewall"], "a": 2, "e": "Simplifies large-scale network architectures compared to a full mesh of individual peering connections. This describes Transit Gateway (\"A hub service that connects many VPCs and on-premises networks through a single point.\")."}, {"obj": "5.2", "q": "Which term best matches this description: \"Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions.\"?", "c": ["Code Deployment", "RPM Package", "CI/CD Security", "Build (CI/CD)"], "a": 1, "e": "\"Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions.\" describes RPM Package. One of several standard package formats a CI/CD pipeline might produce or deploy."}, {"obj": "2.4", "q": "Which of the following best describes \"Drift Detection\"?", "c": ["Validating infrastructure code for syntax, security, and logic before it is applied to real environments.", "Yet Another Markup Language — a human-readable data format widely used for IaC and configuration files.", "Identifying when a deployed resource's actual state no longer matches its defined IaC configuration.", "Tracking changes to infrastructure code over time using version control."], "a": 2, "e": "Identifying when a deployed resource's actual state no longer matches its defined IaC configuration. Helps catch unauthorized or manual changes that could cause inconsistency or security gaps."}, {"obj": "1.10", "q": "A team automates the coordination of multiple cloud services into a single business process, such as processing an order across inventory, payment, and shipping systems. What is this called?", "c": ["A workflow", "A compute optimization type", "IOPS tuning", "Network throughput analysis"], "a": 0, "e": "A workflow defines a sequence of automated steps/tasks that coordinate multiple services to accomplish a business process."}, {"obj": "1.3", "q": "\"Application Gateway\" is best defined as which of the following?", "c": ["A set of rules that determines where network traffic is directed.", "Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.", "Virtual Private Cloud — an isolated, logically defined network within a public cloud provider's infrastructure.", "A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features."], "a": 3, "e": "A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features. Provides a single ingress point for web applications with built-in security and traffic-shaping features."}, {"obj": "2.4", "q": "A description reads: \"Managing and provisioning infrastructure through machine-readable definition files rather than manual processes.\" Which term does this describe?", "c": ["IaC Versioning", "Infrastructure as Code", "Configuration as Code", "Drift Detection"], "a": 1, "e": "\"Managing and provisioning infrastructure through machine-readable definition files rather than manual processes.\" describes Infrastructure as Code. Makes infrastructure changes repeatable, version-controlled, and auditable."}, {"obj": "6.1", "q": "After a deployment, some users can access the application normally while others experience errors, but the service is not completely down. What severity level does this represent?", "c": ["A full outage", "A partial outage", "Regional service availability failure", "A service quota limit"], "a": 1, "e": "A partial outage describes degradation where some, but not all, functionality or users are affected, distinct from a complete full outage."}, {"obj": "1.1", "q": "What does the abbreviation \"SaaS\" stand for?", "c": ["Software as a Service", "Transmission Control Protocol", "Open Authorization", "Intrusion Prevention System"], "a": 0, "e": "SaaS stands for Software as a Service. A cloud model delivering fully managed application software over the internet."}, {"obj": "2.1", "q": "In cloud computing terminology, \"Hybrid Cloud\" refers to which of the following?", "c": ["Infrastructure owned by a third-party provider and shared across many customers (multi-tenant).", "A deployment model combining private/on-premises infrastructure with public cloud resources.", "Infrastructure physically located and managed within the organization's own facilities.", "Infrastructure dedicated to a single organization, hosted on- or off-premises."], "a": 1, "e": "A deployment model combining private/on-premises infrastructure with public cloud resources. Common for gradual migration, burst capacity, or workloads with data residency constraints."}, {"obj": "1.7", "q": "Select the most accurate description of \"Overlay Network\":", "c": ["Grouping multiple hypervisor hosts together to share resources and enable failover/migration.", "Storage Area Network — shared block storage accessible by multiple hypervisor hosts.", "Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction.", "A virtual network built on top of physical network infrastructure, common in virtualization and containers."], "a": 3, "e": "A virtual network built on top of physical network infrastructure, common in virtualization and containers. Allows flexible virtual network topologies independent of the underlying physical network layout."}, {"obj": "2.4", "q": "Which term is most closely associated with this real-world importance: \"Helps catch unauthorized or manual changes that could cause inconsistency or security gaps.\"?", "c": ["Infrastructure as Code", "Drift Detection", "JSON", "YAML"], "a": 1, "e": "Helps catch unauthorized or manual changes that could cause inconsistency or security gaps. This describes Drift Detection (\"Identifying when a deployed resource's actual state no longer matches its defined IaC configuration.\")."}, {"obj": "4.6", "q": "Given the description \"Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources.\", which term is being defined?", "c": ["DDoS", "Phishing", "Deviation from Baseline", "Vulnerability Exploitation — Outdated Software"], "a": 0, "e": "\"Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources.\" describes DDoS. Aims to exhaust resources or bandwidth so legitimate users cannot access the service."}, {"obj": "3.4", "q": "Which concept is described by the phrase: \"A smaller update, typically with bug fixes and small improvements.\"?", "c": ["Minor Update", "Persistent Data", "Patch", "Lifecycle Testing"], "a": 0, "e": "\"A smaller update, typically with bug fixes and small improvements.\" describes Minor Update. Generally lower risk than major updates but should still be tested before production rollout."}, {"obj": "3.4", "q": "Which of the following terms fits this definition: \"A significant version update that may include new features and breaking changes.\"?", "c": ["Decommissioning — End of Support", "Persistent Data", "Major Update", "Lifecycle Testing"], "a": 2, "e": "\"A significant version update that may include new features and breaking changes.\" describes Major Update. Requires more careful testing than minor updates due to a higher risk of compatibility issues."}, {"obj": "4.2", "q": "A company classifies a dataset as 'restricted' due to containing highly sensitive personal information, applying the strictest access controls in their policy. What compliance concept does this classification most directly support?", "c": ["Litigation hold procedures", "Data classification driving appropriately strict handling requirements", "Data sovereignty for a specific country", "SOC 2 certification renewal"], "a": 1, "e": "Data classification determines the appropriate handling and protection level for data based on its sensitivity, exactly as illustrated by the 'restricted' label here."}, {"obj": "6.3", "q": "In cloud computing terminology, \"Software Vulnerability Issues\" refers to which of the following?", "c": ["Software installed or running without proper approval, increasing risk and potentially breaching policy.", "Problems arising from unpatched or improperly configured software containing known weaknesses.", "An identity gaining higher access than originally granted, often through a flaw or misconfiguration.", "Access to a system or data by someone without proper permission."], "a": 1, "e": "Problems arising from unpatched or improperly configured software containing known weaknesses. Reinforces the ongoing need for vulnerability management and timely patching."}, {"obj": "1.8", "q": "Which of the following terms fits this definition: \"A billing model where a customer pays for an entire physical host, regardless of utilization.\"?", "c": ["Spot Instance", "Dedicated Host Billing", "Rightsizing", "Tagging"], "a": 1, "e": "\"A billing model where a customer pays for an entire physical host, regardless of utilization.\" describes Dedicated Host Billing. Useful for licensing or compliance requirements that need physical isolation from other tenants."}, {"obj": "2.4", "q": "Select the most accurate description of \"IaC Versioning\":", "c": ["Tracking changes to infrastructure code over time using version control.", "Yet Another Markup Language — a human-readable data format widely used for IaC and configuration files.", "Managing and provisioning infrastructure through machine-readable definition files rather than manual processes.", "Managing system or application configuration through code rather than manual configuration."], "a": 0, "e": "Tracking changes to infrastructure code over time using version control. Enables rollback to a known-good configuration and provides an audit trail of infrastructure changes."}, {"obj": "2.3", "q": "A company moves its legacy application to the cloud with minimal code changes, simply relocating the VMs as-is to meet a tight deadline. What migration strategy is this?", "c": ["Re-architect", "Rehost", "Refactor", "Retire"], "a": 1, "e": "Rehost ('lift and shift') moves an application with minimal changes, the fastest strategy but one that doesn't take advantage of cloud-native features."}, {"obj": "1.2", "q": "Select the most accurate description of \"Warm Site\":", "c": ["A partially equipped DR site that needs recent data restored before it can take over.", "A distinct geographic location where a cloud provider operates one or more datacenters.", "Temporarily extending an on-premises workload into the public cloud to handle demand spikes.", "Recovery Point Objective — the maximum acceptable amount of data loss, measured in time."], "a": 0, "e": "A partially equipped DR site that needs recent data restored before it can take over. A middle-ground between cost and recovery speed compared to hot and cold sites."}, {"obj": "4.4", "q": "Why does this matter on the exam and in practice? \"Prevents secrets from being hardcoded in source code or exposed in plaintext configuration files.\" — which term does this explain?", "c": ["Container File Access Permissions", "Zero Trust", "Vendor-Specific Benchmark", "Secrets Management"], "a": 3, "e": "Prevents secrets from being hardcoded in source code or exposed in plaintext configuration files. This describes Secrets Management (\"Securely storing and controlling access to credentials, API keys, and other sensitive configuration values.\")."}, {"obj": "6.3", "q": "Why does this matter on the exam and in practice? \"Reinforces the ongoing need for vulnerability management and timely patching.\" — which term does this explain?", "c": ["Unauthorized Software", "Cipher Suite Deprecation", "Software Vulnerability Issues", "Unauthorized Access"], "a": 2, "e": "Reinforces the ongoing need for vulnerability management and timely patching. This describes Software Vulnerability Issues (\"Problems arising from unpatched or improperly configured software containing known weaknesses.\")."}, {"obj": "5.4", "q": "In cloud computing terminology, \"Ansible\" refers to which of the following?", "c": ["An open-source tool for visualizing metrics and creating monitoring dashboards.", "An open-source platform for automating deployment, scaling, and management of containerized applications.", "An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively.", "An open-source, agentless automation tool used for configuration management and orchestration."], "a": 3, "e": "An open-source, agentless automation tool used for configuration management and orchestration. Uses simple YAML playbooks to automate repetitive configuration tasks across many systems."}, {"obj": "1.9", "q": "A company's application requires horizontal scalability across many commodity nodes to handle massive write volume from IoT devices, with eventual consistency being acceptable. Which type of database is most suitable?", "c": ["A traditional single-node relational database", "A distributed non-relational database", "A single flat file", "Local block storage only"], "a": 1, "e": "Distributed non-relational databases are designed to scale horizontally across many nodes, well suited to high-volume writes where eventual consistency is acceptable."}, {"obj": "1.4", "q": "How would you most accurately define \"File Storage\"?", "c": ["Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk.", "Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB).", "Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.", "A storage tier for infrequently accessed data, offering lower cost with slower retrieval."], "a": 1, "e": "Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB). Ideal for shared application data and home directories accessed by multiple servers simultaneously."}, {"obj": "1.4", "q": "Which of the following terms fits this definition: \"Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.\"?", "c": ["HDD", "Hot Storage Tier", "Warm Storage Tier", "SSD"], "a": 3, "e": "\"Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.\" describes SSD. The default choice for performance-sensitive workloads like databases."}, {"obj": "6.1", "q": "A description reads: \"A complete loss of service availability.\" Which term does this describe?", "c": ["Resource Allocation Misconfiguration", "Outdated Component Definitions", "Full Outage", "Partial Outage"], "a": 2, "e": "\"A complete loss of service availability.\" describes Full Outage. Represents the most severe availability impact, prioritized above partial outages."}, {"obj": "3.1", "q": "A team collects CPU, memory, and request-rate data points over time to build dashboards showing system health trends. What observability component is this?", "c": ["Distributed tracing", "Monitoring metrics", "Log retention policy", "Alert response documentation"], "a": 1, "e": "Monitoring metrics are numeric measurements of system behavior collected over time, forming the foundation of dashboards used to understand system health."}, {"obj": "1.3", "q": "Which statement accurately describes \"CDN\"?", "c": ["Content Delivery Network — a geographically distributed set of servers that cache content closer to end users.", "A direct network connection between two VPCs that allows them to communicate as if on the same network.", "Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management.", "Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network."], "a": 0, "e": "Content Delivery Network — a geographically distributed set of servers that cache content closer to end users. Reduces latency and origin server load by serving cached static (and sometimes dynamic) content from edge locations."}, {"obj": "1.6", "q": "An administrator explains the importance of a concept: \"Simple to run for development/testing but lacks automated scaling, healing, or scheduling.\" What concept is this?", "c": ["Stand-Alone Container", "Workload Orchestration", "Persistent Volume", "Image Registry"], "a": 0, "e": "Simple to run for development/testing but lacks automated scaling, healing, or scheduling. This describes Stand-Alone Container (\"A single container running in isolation without orchestration.\")."}, {"obj": "4.4", "q": "Given the description \"A container granted elevated access to the host system's resources.\", which term is being defined?", "c": ["Object Storage Security", "CIS Benchmark", "Unprivileged Container", "Privileged Container"], "a": 3, "e": "\"A container granted elevated access to the host system's resources.\" describes Privileged Container. Significantly increases risk since a compromised privileged container can affect the underlying host."}, {"obj": "2.1", "q": "A financial services consortium builds a shared cloud platform specifically for member banks needing to meet the same regulatory audit standards, and access is restricted only to consortium members. What model is this?", "c": ["Public cloud", "Community cloud", "Private cloud for a single bank", "On premises"], "a": 1, "e": "A community cloud is shared among a defined group of organizations (the consortium members) with common regulatory concerns, distinct from a fully public offering."}, {"obj": "4.3", "q": "An enterprise wants employees to log into cloud resources using their existing corporate identity provider credentials, without creating separate cloud-only accounts. What should be implemented?", "c": ["Local user authentication on every instance", "Federation with the corporate identity provider", "A bastion host only", "Programmatic API keys for every user"], "a": 1, "e": "Federation lets users authenticate with a trusted external identity provider (like their corporate directory), avoiding duplicate account management in the cloud."}, {"obj": "3.4", "q": "A colleague says: \"Requires more careful testing than minor updates due to a higher risk of compatibility issues.\" Which concept are they describing?", "c": ["Patch", "Persistent Data", "Major Update", "Ephemeral Data"], "a": 2, "e": "Requires more careful testing than minor updates due to a higher risk of compatibility issues. This describes Major Update (\"A significant version update that may include new features and breaking changes.\")."}, {"obj": "3.1", "q": "Which of the following terms fits this definition: \"Combining logs from many sources into a unified, searchable view.\"?", "c": ["Alert Response", "Log Collection", "Log Aggregation", "Tracing"], "a": 2, "e": "\"Combining logs from many sources into a unified, searchable view.\" describes Log Aggregation. Enables correlation across services, which is essential for diagnosing distributed system issues."}, {"obj": "3.3", "q": "Which concept is described by the phrase: \"Copying backup data to another location (often off-site or another region).\"?", "c": ["Parallel Recovery", "Differential Backup", "Backup Replication", "Backup Retention (Ops)"], "a": 2, "e": "\"Copying backup data to another location (often off-site or another region).\" describes Backup Replication. Protects against a disaster affecting the primary backup location."}, {"obj": "5.4", "q": "Which term is most closely associated with this real-world importance: \"Lets teams define build/test/deploy pipelines directly alongside their code in GitHub.\"?", "c": ["Git", "GitHub Actions", "ELK Stack", "Jenkins"], "a": 1, "e": "Lets teams define build/test/deploy pipelines directly alongside their code in GitHub. This describes GitHub Actions (\"A CI/CD automation feature built into GitHub for running workflows in response to repository events.\")."}, {"obj": "5.3", "q": "\"RPC\" is best defined as which of the following?", "c": ["Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local.", "A protocol providing full-duplex, persistent communication channels over a single TCP connection.", "A query language for APIs that lets clients request exactly the data they need.", "Representational State Transfer — an architectural style for web services using standard HTTP methods."], "a": 0, "e": "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local. Underpins many internal microservice-to-microservice communication patterns (e.g., gRPC)."}, {"obj": "1.3", "q": "An application needs to route traffic based on the HTTP request's URL path, sending /images to one backend pool and /api to another. Which load balancer type is required?", "c": ["A Layer 4 network load balancer", "A Layer 7 application load balancer", "A DNS-only load balancer", "A static route table"], "a": 1, "e": "Only a Layer 7 (application) load balancer can inspect HTTP-level data like the URL path to make routing decisions."}, {"obj": "4.1", "q": "A security team discovers 50 vulnerabilities during a scan but only has resources to fix 10 this month. What should guide their prioritization?", "c": ["Fixing vulnerabilities in alphabetical order by system name", "An assessment of each vulnerability's severity, exploitability, and business impact", "Ignoring all of them until next year", "Fixing only vulnerabilities discovered most recently, regardless of severity"], "a": 1, "e": "Vulnerability assessment evaluates severity, exploitability, and impact, providing a rational basis for prioritizing limited remediation resources."}, {"obj": "5.2", "q": "Which of the following best describes \"Private Repository\"?", "c": ["Releasing built and tested code to a target environment (e.g., production).", "A packaged container image produced and stored as a build output.", "The defined sequence of automated stages a change passes through from commit to deployment.", "A code or artifact repository restricted to authorized users/systems."], "a": 3, "e": "A code or artifact repository restricted to authorized users/systems. The standard choice for proprietary source code and internal build artifacts."}, {"obj": "4.3", "q": "A description reads: \"A chronological record of who did what, and when, within a system.\" Which term does this describe?", "c": ["Federation", "API (IAM Context)", "Audit Trail", "SSH"], "a": 2, "e": "\"A chronological record of who did what, and when, within a system.\" describes Audit Trail. Essential for investigating incidents and demonstrating compliance with access policies."}, {"obj": "3.4", "q": "Why does this matter on the exam and in practice? \"Requires planning for data migration/retention before the resource is removed.\" — which term does this explain?", "c": ["Persistent Data", "Decommissioning — End of Life", "Lifecycle Testing", "Ephemeral Data"], "a": 1, "e": "Requires planning for data migration/retention before the resource is removed. This describes Decommissioning — End of Life (\"Retiring a resource because it has reached the end of its useful life or support.\")."}, {"obj": "6.3", "q": "A low-privilege service account is found to have performed administrative actions it should never have been authorized to perform. What does this indicate?", "c": ["Proper least-privilege enforcement working as intended", "Privilege escalation", "Federation functioning correctly", "Zero Trust enforcement succeeding"], "a": 1, "e": "This is a textbook example of privilege escalation, where an entity gains access beyond what it was originally granted, often through a flaw or misconfiguration."}, {"obj": "5.1", "q": "A team requires at least one approving code review before any pull request can be merged into the main branch. What risk does this policy primarily reduce?", "c": ["The risk of losing version history", "The risk of unreviewed bugs or security issues reaching the shared codebase", "The risk of using too many branches", "The risk of committing too frequently"], "a": 1, "e": "Requiring review before merge reduces the risk that unreviewed bugs, security issues, or design problems make it into the shared codebase."}, {"obj": "1.3", "q": "An administrator explains the importance of a concept: \"Forms the fundamental network boundary for cloud resources, similar to a private on-premises network.\" What concept is this?", "c": ["Subnet", "Application Gateway", "Dedicated Connection", "VPC"], "a": 3, "e": "Forms the fundamental network boundary for cloud resources, similar to a private on-premises network. This describes VPC (\"Virtual Private Cloud — an isolated, logically defined network within a public cloud provider's infrastructure.\")."}, {"obj": "1.7", "q": "A colleague says: \"Determines how a VM communicates with other VMs, the host, and external networks.\" Which concept are they describing?", "c": ["NAS (Virtualization Context)", "VM Network", "Cloning", "Overlay Network"], "a": 1, "e": "Determines how a VM communicates with other VMs, the host, and external networks. This describes VM Network (\"The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network.\")."}, {"obj": "5.4", "q": "Which statement accurately describes \"ELK Stack\"?", "c": ["An open-source, agentless automation tool used for configuration management and orchestration.", "A platform for building, running, and managing containers.", "An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively.", "Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization."], "a": 3, "e": "Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization. A widely used open-source stack for centralized logging and observability."}, {"obj": "1.10", "q": "A network connection intended to transfer large nightly backup files completes far slower than the link's theoretical maximum bandwidth would suggest. What metric describes the actual observed data movement rate?", "c": ["Network throughput", "IOPS", "Storage capacity", "Compute type"], "a": 0, "e": "Network throughput measures the actual amount of data successfully transferred over a given time, which may be lower than theoretical bandwidth due to overhead or congestion."}, {"obj": "6.3", "q": "Which concept is described by the phrase: \"An identity gaining higher access than originally granted, often through a flaw or misconfiguration.\"?", "c": ["Privilege Escalation (Troubleshooting)", "Unauthorized Access", "Cipher Suite Deprecation", "Software Vulnerability Issues"], "a": 0, "e": "\"An identity gaining higher access than originally granted, often through a flaw or misconfiguration.\" describes Privilege Escalation (Troubleshooting). A critical security troubleshooting concern after any suspected compromise of a low-privilege account."}, {"obj": "4.3", "q": "A developer uses a cloud provider's Python library to create and configure resources directly from their application code. What are they using?", "c": ["A web portal", "An SDK", "RDP", "A bastion host"], "a": 1, "e": "An SDK (Software Development Kit) provides libraries that let developers programmatically interact with a cloud platform directly from code."}, {"obj": "1.4", "q": "In cloud computing terminology, \"Object Storage\" refers to which of the following?", "c": ["A storage tier for infrequently accessed data, offering lower cost with slower retrieval.", "A storage tier for data accessed less frequently than hot data, balancing cost and access speed.", "A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost.", "Storage that manages data as discrete objects with metadata, accessed via an API (e.g., S3)."], "a": 3, "e": "Storage that manages data as discrete objects with metadata, accessed via an API (e.g., S3). Highly scalable and durable, ideal for unstructured data like backups, media, and static web content."}, {"obj": "4.3", "q": "\"Directory-Based Authentication\" is best defined as which of the following?", "c": ["Authenticating against a centralized directory service (like LDAP or Active Directory).", "A graphical, browser-based interface for managing cloud resources.", "Secure Shell — an encrypted protocol for remote command-line access to cloud resources.", "An authorization framework that lets an application access resources on a user's behalf without sharing their password."], "a": 0, "e": "Authenticating against a centralized directory service (like LDAP or Active Directory). Centralizes identity management across many systems rather than maintaining separate local accounts."}, {"obj": "2.1", "q": "An administrator explains the importance of a concept: \"Gives maximum control over hardware and data location, at the cost of full operational responsibility.\" What concept is this?", "c": ["On Premises", "Community Cloud", "Public Cloud", "Hybrid Cloud"], "a": 0, "e": "Gives maximum control over hardware and data location, at the cost of full operational responsibility. This describes On Premises (\"Infrastructure physically located and managed within the organization's own facilities.\")."}, {"obj": "1.2", "q": "A colleague says: \"Cheapest DR option, but has by far the longest time to bring online.\" Which concept are they describing?", "c": ["Hot Site", "Availability Zone", "Cold Site", "Cloud Bursting"], "a": 2, "e": "Cheapest DR option, but has by far the longest time to bring online. This describes Cold Site (\"A basic facility with power and space but no pre-installed equipment.\")."}, {"obj": "4.4", "q": "Which term best matches this description: \"Hardening guidance published by a specific cloud provider or software vendor for their own product.\"?", "c": ["CIS Benchmark", "Vendor-Specific Benchmark", "Data at Rest Encryption", "Unprivileged Container"], "a": 1, "e": "\"Hardening guidance published by a specific cloud provider or software vendor for their own product.\" describes Vendor-Specific Benchmark. Complements general benchmarks with platform-specific configuration recommendations."}, {"obj": "6.2", "q": "An administrator explains the importance of a concept: \"Traffic destined for that path is silently dropped, a common and often overlooked cloud networking issue.\" What concept is this?", "c": ["IP Scope Exhaustion", "Protocol Incompatibility", "Missing Route", "VLAN Misconfigured Tags"], "a": 2, "e": "Traffic destined for that path is silently dropped, a common and often overlooked cloud networking issue. This describes Missing Route (\"A required network path that has not been defined in a route table.\")."}, {"obj": "6.2", "q": "Which term is most closely associated with this real-world importance: \"A classic Layer 2 troubleshooting issue, especially after switch or trunk reconfiguration.\"?", "c": ["IP Scope Exhaustion", "VLAN Misconfigured Tags", "HTTP Status Codes", "NTP (Troubleshooting)"], "a": 1, "e": "A classic Layer 2 troubleshooting issue, especially after switch or trunk reconfiguration. This describes VLAN Misconfigured Tags (\"Incorrect VLAN tagging causing traffic to be dropped or delivered to the wrong segment.\")."}, {"obj": "1.11", "q": "A retailer wants to analyze thousands of customer support chat transcripts to understand overall customer satisfaction trends without reading each one manually. Which AI capability directly supports this at scale?", "c": ["Sentiment analysis", "Visual recognition", "IoT gateway aggregation", "Hardware pass-through"], "a": 0, "e": "Sentiment analysis can automatically assess the emotional tone of large volumes of text, providing satisfaction trend insights without manual review of every transcript."}, {"obj": "2.4", "q": "After deploying infrastructure via IaC, an engineer manually changes a security group rule directly in the cloud console during an emergency. What process would later catch this discrepancy from the IaC definition?", "c": ["Drift detection", "Code review", "Service discovery", "Backup validation"], "a": 0, "e": "Drift detection identifies when a resource's actual state no longer matches its defined IaC configuration, catching manual out-of-band changes like this emergency fix."}, {"obj": "3.2", "q": "\"Scheduled Scaling\" is best defined as which of the following?", "c": ["Adding more instances of a resource to handle increased load (scale out).", "An administrator explicitly changing resource capacity rather than relying on automation.", "Scaling resources up or down at predefined times based on known usage patterns.", "Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%)."], "a": 2, "e": "Scaling resources up or down at predefined times based on known usage patterns. Ideal for predictable daily/weekly demand cycles, like scaling up before business hours."}, {"obj": "1.4", "q": "Which of the following best distinguishes object storage from block storage in terms of access method?", "c": ["Object storage is accessed via an API using object keys/metadata; block storage is accessed as raw addressable blocks typically by one VM", "Object storage requires a dedicated physical server; block storage does not", "Block storage is only used for backups; object storage is only used for databases", "There is no meaningful difference between the two"], "a": 0, "e": "Object storage manages data as discrete objects with metadata accessed via an API, while block storage presents raw blocks typically attached to a single VM as a virtual disk."}, {"obj": "4.3", "q": "A small company maintains separate login credentials directly on each individual cloud instance rather than using a centralized identity system. What authentication approach is this, and what is its main drawback?", "c": ["Federation; it scales poorly and complicates centralized policy", "Local user authentication; it doesn't scale well and complicates centralized policy enforcement across many systems", "Token-based authentication; it requires no maintenance", "SAML; it eliminates the need for passwords"], "a": 1, "e": "Local user authentication stores credentials directly on each system, which becomes difficult to manage and enforce consistent policy on as the number of systems grows."}, {"obj": "5.4", "q": "Which of the following best describes \"ELK Stack\"?", "c": ["An open-source tool for visualizing metrics and creating monitoring dashboards.", "Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization.", "A CI/CD automation feature built into GitHub for running workflows in response to repository events.", "An open-source, agentless automation tool used for configuration management and orchestration."], "a": 1, "e": "Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization. A widely used open-source stack for centralized logging and observability."}, {"obj": "5.3", "q": "Select the most accurate description of \"RPC\":", "c": ["Representational State Transfer — an architectural style for web services using standard HTTP methods.", "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local.", "A design where components communicate by producing and reacting to events rather than direct calls.", "Simple Object Access Protocol — an XML-based messaging protocol for web services."], "a": 1, "e": "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local. Underpins many internal microservice-to-microservice communication patterns (e.g., gRPC)."}, {"obj": "4.5", "q": "A description reads: \"Access Control List — a set of rules controlling traffic in and out of a subnet at the network level.\" Which term does this describe?", "c": ["DDoS Protection", "IAM Policies", "DLP", "Network ACL"], "a": 3, "e": "\"Access Control List — a set of rules controlling traffic in and out of a subnet at the network level.\" describes Network ACL. Operates at the subnet/network level, distinct from security group/instance-level rules."}, {"obj": "1.4", "q": "Why does this matter on the exam and in practice? \"A middle ground for data that's not actively hot but still needed with reasonable speed.\" — which term does this explain?", "c": ["Block Storage", "File Storage", "SSD", "Warm Storage Tier"], "a": 3, "e": "A middle ground for data that's not actively hot but still needed with reasonable speed. This describes Warm Storage Tier (\"A storage tier for data accessed less frequently than hot data, balancing cost and access speed.\")."}, {"obj": "3.1", "q": "Which statement accurately describes \"Log Retention\"?", "c": ["The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.", "Following a single request as it moves through multiple services in a distributed system.", "Defining how long log data is kept before being archived or deleted.", "Numeric measurements of system behavior (CPU, memory, request rate) collected over time."], "a": 2, "e": "Defining how long log data is kept before being archived or deleted. Balances storage cost against the need to investigate older incidents or meet compliance requirements."}, {"obj": "1.4", "q": "A colleague says: \"Offers lower cost per GB than SSD, suited to large, less performance-sensitive datasets.\" Which concept are they describing?", "c": ["Hot Storage Tier", "Archive Storage Tier", "HDD", "Object Storage"], "a": 2, "e": "Offers lower cost per GB than SSD, suited to large, less performance-sensitive datasets. This describes HDD (\"Hard Disk Drive — traditional magnetic spinning-platter storage.\")."}, {"obj": "1.9", "q": "Why does this matter on the exam and in practice? \"Reduces administrative burden significantly, letting teams focus on the data and application instead of the database engine.\" — which term does this explain?", "c": ["Provider-Managed Database", "Relational Database", "Self-Managed Database", "Non-Relational Database"], "a": 0, "e": "Reduces administrative burden significantly, letting teams focus on the data and application instead of the database engine. This describes Provider-Managed Database (\"A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS).\")."}, {"obj": "1.11", "q": "Which of the following terms fits this definition: \"The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data.\"?", "c": ["IoT Transmission Protocol", "Visual Recognition", "Machine Learning", "IoT Communication"], "a": 3, "e": "\"The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data.\" describes IoT Communication. Choice of communication method affects range, power consumption, and bandwidth available to the device."}, {"obj": "6.3", "q": "\"Leaked Credentials\" is best defined as which of the following?", "c": ["Access to a system or data by someone without proper permission.", "Authentication credentials that have been exposed, such as in code repositories or logs.", "Problems arising from unpatched or improperly configured software containing known weaknesses.", "An identity gaining higher access than originally granted, often through a flaw or misconfiguration."], "a": 1, "e": "Authentication credentials that have been exposed, such as in code repositories or logs. A very common real-world cause of cloud breaches, often via credentials accidentally committed to source control."}, {"obj": "6.1", "q": "Given the description \"Allocating more virtual resources than the underlying physical capacity can truly support.\", which term is being defined?", "c": ["Sizing Issues", "Resource Allocation Misconfiguration", "Oversubscription", "Service Quota"], "a": 2, "e": "\"Allocating more virtual resources than the underlying physical capacity can truly support.\" describes Oversubscription. Can cause performance degradation or failed provisioning if too many workloads compete for the same physical resources."}, {"obj": "1.5", "q": "A description reads: \"A design where components interact through well-defined interfaces with minimal direct dependencies.\" Which term does this describe?", "c": ["Fan-Out", "Loosely Coupled Architecture", "Service Discovery", "Cloud-Provided Managed Service"], "a": 1, "e": "\"A design where components interact through well-defined interfaces with minimal direct dependencies.\" describes Loosely Coupled Architecture. Improves resilience and flexibility since one component's changes or failures don't directly break others."}, {"obj": "1.2", "q": "A company wants a DR environment that is fully staffed, continuously synchronized, and ready to take over within seconds of a primary outage, and is willing to pay a premium for this. Which DR site type fits?", "c": ["Cold site", "Warm site", "Hot site", "Community site"], "a": 2, "e": "A hot site is kept fully live and synchronized for near-instant failover, at the highest ongoing cost of the three site types."}, {"obj": "4.3", "q": "How would you most accurately define \"Federation\"?", "c": ["Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.", "Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.", "Multifactor Authentication — requiring two or more independent verification factors to log in.", "Allowing users to authenticate using credentials from a separate, trusted identity provider."], "a": 3, "e": "Allowing users to authenticate using credentials from a separate, trusted identity provider. Lets organizations use existing corporate identities to access cloud resources without duplicate accounts."}, {"obj": "1.10", "q": "Which statement accurately describes \"Network Latency\"?", "c": ["A defined sequence of automated steps/tasks that process data or coordinate resources.", "Using containers as the compute resource type for a workload.", "The actual amount of data successfully transferred over a network connection in a given time.", "The time delay for data to travel between two points on a network."], "a": 3, "e": "The time delay for data to travel between two points on a network. A critical factor when placing workloads and choosing regions/AZs for latency-sensitive applications."}, {"obj": "5.1", "q": "Which term is most closely associated with this real-world importance: \"Integrates parallel work from multiple developers or feature branches.\"?", "c": ["Code Review", "Branch Management", "Pull Request", "Code Merge"], "a": 3, "e": "Integrates parallel work from multiple developers or feature branches. This describes Code Merge (\"Combining changes from different branches into one.\")."}, {"obj": "1.8", "q": "Which of the following best describes \"Tagging\"?", "c": ["Tracking actual consumption of cloud resources for billing and capacity planning purposes.", "A billing model where a customer pays for an entire physical host, regardless of utilization.", "Attaching key-value metadata labels to cloud resources.", "Adjusting the size/type of provisioned resources to match actual workload demand."], "a": 2, "e": "Attaching key-value metadata labels to cloud resources. Enables cost allocation, automation, and organization of resources by project, owner, or environment."}, {"obj": "3.3", "q": "In cloud computing terminology, \"Backup Recoverability Testing\" refers to which of the following?", "c": ["Actually restoring backup data to confirm it can be used successfully.", "Restoring a large set of data all at once.", "Backs up only data changed since the last backup of any type.", "The defined frequency and timing of backup jobs."], "a": 0, "e": "Actually restoring backup data to confirm it can be used successfully. A backup reporting \"success\" does not guarantee the data is truly restorable — testing closes that gap."}, {"obj": "4.6", "q": "An administrator explains the importance of a concept: \"Aims to exhaust resources or bandwidth so legitimate users cannot access the service.\" What concept is this?", "c": ["DDoS", "Cryptojacking", "Deviation from Baseline", "Vulnerability Exploitation — Outdated Software"], "a": 0, "e": "Aims to exhaust resources or bandwidth so legitimate users cannot access the service. This describes DDoS (\"Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources.\")."}, {"obj": "1.10", "q": "An administrator explains the importance of a concept: \"Helps chain together cloud services and automate multi-step business processes.\" What concept is this?", "c": ["Compute Optimization (Container)", "Compute Optimization (VM)", "Workflow (Optimization)", "Managed Services (Optimization)"], "a": 2, "e": "Helps chain together cloud services and automate multi-step business processes. This describes Workflow (Optimization) (\"A defined sequence of automated steps/tasks that process data or coordinate resources.\")."}, {"obj": "4.3", "q": "A third-party application needs to access a user's cloud storage files on their behalf without ever seeing their password. What framework enables this?", "c": ["SAML", "OAuth 2.0", "RDP", "Bastion host"], "a": 1, "e": "OAuth 2.0 is an authorization framework letting an application access resources on a user's behalf without sharing credentials."}, {"obj": "4.1", "q": "Which statement accurately describes \"Scanning Scope\"?", "c": ["Defining which systems, networks, or applications a vulnerability scan will cover.", "Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities.", "Evaluating identified vulnerabilities for severity, exploitability, and business impact.", "The step of detecting known weaknesses in systems, typically via automated scanning."], "a": 0, "e": "Defining which systems, networks, or applications a vulnerability scan will cover. Ensures the scan actually covers all in-scope assets rather than leaving blind spots."}, {"obj": "4.3", "q": "How would you most accurately define \"Programmatic Access\"?", "c": ["Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.", "Software Development Kit — a set of libraries/tools that let developers programmatically interact with a cloud platform.", "Accessing cloud resources via code rather than a human using a GUI (API/SDK).", "An access model where the resource owner decides who else can access it."], "a": 2, "e": "Accessing cloud resources via code rather than a human using a GUI (API/SDK). Enables automation but requires careful credential management since keys can be leaked or misused."}, {"obj": "1.3", "q": "A cloud network engineer configures each cloud resource's networking through code and APIs rather than manually rewiring physical switches. What underlying capability enables this?", "c": ["SDN (Software-Defined Networking)", "BGP", "A CDN", "VLAN tagging alone"], "a": 0, "e": "SDN decouples the network control plane from physical hardware, enabling network configuration through code and APIs rather than manual physical changes."}, {"obj": "6.1", "q": "Which of the following best describes \"Incompatibility (Deployment)\"?", "c": ["A failure caused by mismatched software, hardware, or configuration versions.", "Allocating more virtual resources than the underlying physical capacity can truly support.", "A deployment failing because the deploying identity lacks sufficient rights.", "Incorrectly assigned CPU, memory, or storage limits for a workload."], "a": 0, "e": "A failure caused by mismatched software, hardware, or configuration versions. A very common root cause of failed deployments, especially after an update to one dependency."}, {"obj": "5.4", "q": "Which statement accurately describes \"Kubernetes\"?", "c": ["A platform for building, running, and managing containers.", "An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively.", "An open-source platform for automating deployment, scaling, and management of containerized applications.", "A CI/CD automation feature built into GitHub for running workflows in response to repository events."], "a": 2, "e": "An open-source platform for automating deployment, scaling, and management of containerized applications. The de facto standard for container orchestration in modern cloud-native environments."}, {"obj": "6.2", "q": "What does the abbreviation \"MTU\" stand for?", "c": ["Secure Shell", "Common Weakness Scoring System", "Elasticsearch, Logstash, and Kibana", "Maximum Transmission Unit"], "a": 3, "e": "MTU stands for Maximum Transmission Unit. The largest packet size that can be transmitted over a network link."}, {"obj": "1.2", "q": "A global company wants to reduce latency for users in Europe and Asia by deploying application instances physically closer to each user base. What should they use?", "c": ["A single availability zone", "Multiple regions", "Cloud bursting", "A single hot site"], "a": 1, "e": "Deploying across multiple geographic regions places resources closer to distant user populations, reducing latency compared to a single region."}, {"obj": "1.6", "q": "A DevOps team needs a central place to store, version, and distribute container images for their CI/CD pipeline to pull from during deployments. What should they use?", "c": ["A persistent volume", "An image registry", "Ephemeral storage", "A stand-alone container"], "a": 1, "e": "An image registry provides a versioned, central repository for storing and distributing container images used during deployment."}, {"obj": "3.3", "q": "A colleague says: \"Ensures the backup itself is trustworthy before it's ever relied upon during an actual incident.\" Which concept are they describing?", "c": ["Backup Integrity Testing", "Backup Recoverability Testing", "Full Backup", "Backup Replication"], "a": 0, "e": "Ensures the backup itself is trustworthy before it's ever relied upon during an actual incident. This describes Backup Integrity Testing (\"Verifying that backed-up data has not been corrupted.\")."}, {"obj": "5.2", "q": "Select the most accurate description of \"Public Repository\":", "c": ["A code or artifact repository accessible to anyone.", "A packaged container image produced and stored as a build output.", "A packaged virtual machine image produced and stored as a build output.", "Automatically building, testing, and deploying code changes with minimal manual intervention."], "a": 0, "e": "A code or artifact repository accessible to anyone. Convenient for open-source projects but not suitable for proprietary or sensitive code."}, {"obj": "1.2", "q": "Select the most accurate description of \"Availability Monitoring\":", "c": ["An isolated location within a region with independent power, cooling, and networking.", "A basic facility with power and space but no pre-installed equipment.", "Continuously checking that a resource or service is up and responding as expected.", "Using services from more than one public cloud provider simultaneously."], "a": 2, "e": "Continuously checking that a resource or service is up and responding as expected. Provides the data needed to detect outages and calculate real-world uptime against SLA targets."}, {"obj": "4.6", "q": "An attacker gains initial access to a system by exploiting a known vulnerability in an unpatched application that had a fix available for months. What category of cause does this represent?", "c": ["Human error", "Vulnerability exploitation via outdated software", "A DDoS attack", "A metadata attack"], "a": 1, "e": "This scenario describes exploitation of a known vulnerability that remained unpatched, categorizing it as vulnerability exploitation via outdated software."}, {"obj": "5.2", "q": "Which of the following terms fits this definition: \"The defined sequence of automated stages a change passes through from commit to deployment.\"?", "c": ["RPM Package", "CI/CD Workflow", "Code Integration", "CI/CD Automation"], "a": 1, "e": "\"The defined sequence of automated stages a change passes through from commit to deployment.\" describes CI/CD Workflow. Documents and enforces a consistent, repeatable delivery process."}, {"obj": "1.1", "q": "Which of the following terms fits this definition: \"Infrastructure as a Service — provides virtualized compute, storage, and networking, leaving the OS and above to the customer.\"?", "c": ["Shared Responsibility Model", "FaaS", "IaaS", "SaaS"], "a": 2, "e": "\"Infrastructure as a Service — provides virtualized compute, storage, and networking, leaving the OS and above to the customer.\" describes IaaS. The customer patches and secures the OS/apps; the provider is responsible only for the underlying physical infrastructure."}, {"obj": "4.2", "q": "Which of the following terms fits this definition: \"A data retention requirement mandated by law or industry regulation.\"?", "c": ["Data Locality", "Cloud Security Alliance", "Contractual Retention", "Regulatory Retention"], "a": 3, "e": "\"A data retention requirement mandated by law or industry regulation.\" describes Regulatory Retention. Non-compliance can result in legal penalties, distinct from purely internal retention preferences."}, {"obj": "4.6", "q": "A colleague says: \"A cloud-specific attack vector, since metadata services often provide temporary credentials to the instance.\" Which concept are they describing?", "c": ["Cryptojacking", "Event Monitoring (Security)", "Metadata Attack", "Ransomware"], "a": 2, "e": "A cloud-specific attack vector, since metadata services often provide temporary credentials to the instance. This describes Metadata Attack (\"An attack that abuses a cloud instance's metadata service to steal credentials or configuration data.\")."}, {"obj": "4.2", "q": "Which of the following is the correct expansion of \"CSA\"?", "c": ["Cloud Security Alliance", "Secure Sockets Layer", "Software Development Kit", "Simple Object Access Protocol"], "a": 0, "e": "CSA stands for Cloud Security Alliance. An organization publishing best practices and frameworks for cloud security."}, {"obj": "4.3", "q": "Which statement accurately describes \"Audit Trail\"?", "c": ["Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.", "A chronological record of who did what, and when, within a system.", "Application Programming Interface — used here for programmatic management/access to cloud resources.", "An authorization framework that lets an application access resources on a user's behalf without sharing their password."], "a": 1, "e": "A chronological record of who did what, and when, within a system. Essential for investigating incidents and demonstrating compliance with access policies."}, {"obj": "4.3", "q": "In cloud computing terminology, \"Local User Authentication\" refers to which of the following?", "c": ["Authenticating with credentials stored directly on the system rather than a central directory.", "A chronological record of who did what, and when, within a system.", "Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.", "Allowing users to authenticate using credentials from a separate, trusted identity provider."], "a": 0, "e": "Authenticating with credentials stored directly on the system rather than a central directory. Simple but doesn't scale well and complicates centralized policy enforcement across many systems."}, {"obj": "6.3", "q": "Select the most accurate description of \"Software Vulnerability Issues\":", "c": ["Authentication credentials that have been exposed, such as in code repositories or logs.", "Problems arising from unpatched or improperly configured software containing known weaknesses.", "Access to a system or data by someone without proper permission.", "Software installed or running without proper approval, increasing risk and potentially breaching policy."], "a": 1, "e": "Problems arising from unpatched or improperly configured software containing known weaknesses. Reinforces the ongoing need for vulnerability management and timely patching."}];
QBANK.forEach((q,i)=>{ q.id = i; });

/* ============ FLASHCARDS (every named concept and acronym in the CV0-004 objectives) ============ */
const FLASHCARDS = [{"t": "IaaS", "obj": "1.1", "d": "Infrastructure as a Service — provides virtualized compute, storage, and networking, leaving the OS and above to the customer.", "m": "The customer patches and secures the OS/apps; the provider is responsible only for the underlying physical infrastructure."}, {"t": "PaaS", "obj": "1.1", "d": "Platform as a Service — provides a managed runtime/platform for developing and deploying applications without managing the underlying OS.", "m": "Developers push code and the provider handles the OS, runtime, and scaling, speeding up application delivery."}, {"t": "SaaS", "obj": "1.1", "d": "Software as a Service — delivers a fully managed application to end users over the internet.", "m": "The provider manages everything except the user's own data and configuration within the app."}, {"t": "FaaS", "obj": "1.1", "d": "Function as a Service — lets code run in response to events without provisioning or managing any server (serverless).", "m": "Billing is based on execution time/invocations rather than reserved capacity, ideal for event-driven workloads."}, {"t": "Shared Responsibility Model", "obj": "1.1", "d": "A framework defining which security and operational tasks belong to the cloud provider versus the customer.", "m": "Responsibility shifts up the stack as you move from IaaS to PaaS to SaaS — misunderstanding this is a common real-world security gap."}, {"t": "Region", "obj": "1.2", "d": "A distinct geographic location where a cloud provider operates one or more datacenters.", "m": "Choosing the right region affects latency, data sovereignty, and compliance."}, {"t": "Availability Zone", "obj": "1.2", "d": "An isolated location within a region with independent power, cooling, and networking.", "m": "Spreading resources across AZs protects against a single datacenter failure without the latency of a different region."}, {"t": "Cloud Bursting", "obj": "1.2", "d": "Temporarily extending an on-premises workload into the public cloud to handle demand spikes.", "m": "Lets an organization keep steady-state workloads on cheaper private infrastructure while still handling peak load."}, {"t": "Edge Computing", "obj": "1.2", "d": "Processing data physically close to where it is generated rather than in a centralized datacenter.", "m": "Reduces latency for time-sensitive applications like IoT and content delivery."}, {"t": "Availability Monitoring", "obj": "1.2", "d": "Continuously checking that a resource or service is up and responding as expected.", "m": "Provides the data needed to detect outages and calculate real-world uptime against SLA targets."}, {"t": "RTO", "obj": "1.2", "d": "Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption.", "m": "Drives the choice of DR site type and how much automation/investment is needed to meet the target."}, {"t": "RPO", "obj": "1.2", "d": "Recovery Point Objective — the maximum acceptable amount of data loss, measured in time.", "m": "A tight RPO requires frequent backups or synchronous replication; a looser RPO allows infrequent backups."}, {"t": "Hot Site", "obj": "1.2", "d": "A fully equipped, continuously running DR site that can take over almost immediately.", "m": "Offers the shortest RTO but is the most expensive DR option to maintain."}, {"t": "Warm Site", "obj": "1.2", "d": "A partially equipped DR site that needs recent data restored before it can take over.", "m": "A middle-ground between cost and recovery speed compared to hot and cold sites."}, {"t": "Cold Site", "obj": "1.2", "d": "A basic facility with power and space but no pre-installed equipment.", "m": "Cheapest DR option, but has by far the longest time to bring online."}, {"t": "Multicloud Tenancy", "obj": "1.2", "d": "Using services from more than one public cloud provider simultaneously.", "m": "Reduces vendor lock-in and can improve resilience, but increases operational and integration complexity."}, {"t": "VPN", "obj": "1.3", "d": "Virtual Private Network — an encrypted tunnel providing secure connectivity over a public network.", "m": "A common way to connect on-premises networks or remote users securely to cloud resources."}, {"t": "Dedicated Connection", "obj": "1.3", "d": "A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute).", "m": "Offers more consistent bandwidth/latency and often lower cost at scale than routing through the public internet."}, {"t": "Application Load Balancer", "obj": "1.3", "d": "A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers).", "m": "Enables advanced routing such as sending /api traffic to one backend and /images to another."}, {"t": "Network Load Balancer", "obj": "1.3", "d": "A load balancer that operates at Layer 4, distributing raw TCP/UDP traffic based on IP and port.", "m": "Provides extremely high throughput and low latency for use cases where Layer 7 inspection isn't needed."}, {"t": "Application Gateway", "obj": "1.3", "d": "A Layer 7 traffic management service, often combining load balancing with routing, SSL termination, and WAF features.", "m": "Provides a single ingress point for web applications with built-in security and traffic-shaping features."}, {"t": "CDN", "obj": "1.3", "d": "Content Delivery Network — a geographically distributed set of servers that cache content closer to end users.", "m": "Reduces latency and origin server load by serving cached static (and sometimes dynamic) content from edge locations."}, {"t": "Firewall", "obj": "1.3", "d": "A device or service that filters network traffic based on defined rules.", "m": "The primary control for restricting which traffic is allowed in/out of a cloud network segment."}, {"t": "VPC", "obj": "1.3", "d": "Virtual Private Cloud — an isolated, logically defined network within a public cloud provider's infrastructure.", "m": "Forms the fundamental network boundary for cloud resources, similar to a private on-premises network."}, {"t": "VPC Peering", "obj": "1.3", "d": "A direct network connection between two VPCs that allows them to communicate as if on the same network.", "m": "Enables private communication between separate VPCs without routing traffic over the public internet."}, {"t": "Transit Gateway", "obj": "1.3", "d": "A hub service that connects many VPCs and on-premises networks through a single point.", "m": "Simplifies large-scale network architectures compared to a full mesh of individual peering connections."}, {"t": "Subnet", "obj": "1.3", "d": "A logical subdivision of a network's IP address range.", "m": "Used within a VPC to separate resources (e.g., public-facing vs. private-only) for security and routing control."}, {"t": "VLAN", "obj": "1.3", "d": "Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains.", "m": "Separates traffic types on shared physical/virtual network infrastructure."}, {"t": "SDN", "obj": "1.3", "d": "Software-Defined Network — decouples the network control plane from the physical data plane, enabling programmatic network management.", "m": "Underpins most cloud networking, allowing networks to be defined and changed through code/APIs rather than physical rewiring."}, {"t": "BGP", "obj": "1.3", "d": "Border Gateway Protocol — the routing protocol used to exchange routing information between large networks, including cloud and ISP networks.", "m": "Used for advanced routing scenarios like connecting on-premises networks to the cloud via dedicated connections."}, {"t": "Static Route", "obj": "1.3", "d": "A manually configured network route that does not change dynamically.", "m": "Simple and predictable, but requires manual updates if the network topology changes."}, {"t": "Route Table", "obj": "1.3", "d": "A set of rules that determines where network traffic is directed.", "m": "Every subnet in a VPC is associated with a route table controlling how its traffic flows."}, {"t": "Hot Storage Tier", "obj": "1.4", "d": "A storage tier optimized for frequently accessed data, offering the fastest access at the highest cost.", "m": "Appropriate for active production data that needs to be retrieved quickly and often."}, {"t": "Warm Storage Tier", "obj": "1.4", "d": "A storage tier for data accessed less frequently than hot data, balancing cost and access speed.", "m": "A middle ground for data that's not actively hot but still needed with reasonable speed."}, {"t": "Cold Storage Tier", "obj": "1.4", "d": "A storage tier for infrequently accessed data, offering lower cost with slower retrieval.", "m": "Suitable for older backups or compliance data that is rarely, but occasionally, needed."}, {"t": "Archive Storage Tier", "obj": "1.4", "d": "The lowest-cost storage tier, designed for rarely accessed data with the slowest retrieval times (sometimes hours).", "m": "Ideal for long-term retention data that must be kept for compliance but is almost never read."}, {"t": "SSD", "obj": "1.4", "d": "Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O.", "m": "The default choice for performance-sensitive workloads like databases."}, {"t": "HDD", "obj": "1.4", "d": "Hard Disk Drive — traditional magnetic spinning-platter storage.", "m": "Offers lower cost per GB than SSD, suited to large, less performance-sensitive datasets."}, {"t": "Object Storage", "obj": "1.4", "d": "Storage that manages data as discrete objects with metadata, accessed via an API (e.g., S3).", "m": "Highly scalable and durable, ideal for unstructured data like backups, media, and static web content."}, {"t": "Block Storage", "obj": "1.4", "d": "Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk.", "m": "Used for OS disks and databases that need low-latency, structured access to storage."}, {"t": "File Storage", "obj": "1.4", "d": "Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB).", "m": "Ideal for shared application data and home directories accessed by multiple servers simultaneously."}, {"t": "Cloud-Provided Managed Service", "obj": "1.5", "d": "A service the cloud provider fully operates (e.g., a managed database), removing the customer's operational burden.", "m": "Reduces administrative overhead at the cost of some control and customization."}, {"t": "Microservices", "obj": "1.5", "d": "An architecture where an application is broken into small, independently deployable services.", "m": "Allows teams to develop, scale, and deploy components independently rather than as one large monolith."}, {"t": "Loosely Coupled Architecture", "obj": "1.5", "d": "A design where components interact through well-defined interfaces with minimal direct dependencies.", "m": "Improves resilience and flexibility since one component's changes or failures don't directly break others."}, {"t": "Fan-Out", "obj": "1.5", "d": "A messaging pattern where one event is distributed to multiple downstream consumers/services.", "m": "Common in event-driven microservices to notify several services of the same event simultaneously."}, {"t": "Service Discovery", "obj": "1.5", "d": "A mechanism that lets services dynamically find the network location of other services.", "m": "Essential in dynamic cloud-native environments where service instances and IP addresses change constantly."}, {"t": "Stand-Alone Container", "obj": "1.6", "d": "A single container running in isolation without orchestration.", "m": "Simple to run for development/testing but lacks automated scaling, healing, or scheduling."}, {"t": "Workload Orchestration", "obj": "1.6", "d": "Automated management of container deployment, scaling, and healing (e.g., Kubernetes).", "m": "Essential for running containerized applications reliably at scale in production."}, {"t": "Port Mapping", "obj": "1.6", "d": "Binding a container's internal port to a port on the host or load balancer.", "m": "Allows external traffic to reach a service running inside an otherwise isolated container."}, {"t": "Persistent Volume", "obj": "1.6", "d": "Storage that survives beyond the lifecycle of an individual container.", "m": "Needed for stateful container workloads like databases, since container filesystems are normally ephemeral."}, {"t": "Ephemeral Storage", "obj": "1.6", "d": "Temporary storage tied to a container's lifecycle that is lost when the container stops.", "m": "Suitable only for temporary/scratch data since it disappears when the container is removed."}, {"t": "Image Registry", "obj": "1.6", "d": "A repository for storing and distributing container images (e.g., Docker Hub, a private registry).", "m": "Provides a central, versioned source for pulling container images during deployment."}, {"t": "Stand-Alone Virtualization", "obj": "1.7", "d": "A single hypervisor host running VMs with no clustering.", "m": "Simple but offers no failover if the host fails."}, {"t": "Clustering", "obj": "1.7", "d": "Grouping multiple hypervisor hosts together to share resources and enable failover/migration.", "m": "Enables high availability and load balancing of VMs across multiple physical hosts."}, {"t": "Cloning", "obj": "1.7", "d": "Creating an exact copy of an existing VM.", "m": "Speeds up deployment of identical VMs without building each one from scratch."}, {"t": "Host Affinity", "obj": "1.7", "d": "A rule keeping specific VMs running on the same (or different) physical host.", "m": "Used to keep related VMs together for performance, or apart for redundancy (anti-affinity)."}, {"t": "Hardware Pass-Through", "obj": "1.7", "d": "Giving a VM direct access to a physical hardware device, bypassing the hypervisor's abstraction.", "m": "Used when a workload needs near-native performance from a specific device, like a GPU."}, {"t": "Overlay Network", "obj": "1.7", "d": "A virtual network built on top of physical network infrastructure, common in virtualization and containers.", "m": "Allows flexible virtual network topologies independent of the underlying physical network layout."}, {"t": "VM Network", "obj": "1.7", "d": "The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network.", "m": "Determines how a VM communicates with other VMs, the host, and external networks."}, {"t": "Local Storage (Virtualization)", "obj": "1.7", "d": "Storage physically attached to a single hypervisor host.", "m": "Fast and simple but doesn't support live migration of VMs to other hosts without shared storage."}, {"t": "SAN (Virtualization Context)", "obj": "1.7", "d": "Storage Area Network — shared block storage accessible by multiple hypervisor hosts.", "m": "Enables features like live migration and clustering since any host in the cluster can access the same storage."}, {"t": "NAS (Virtualization Context)", "obj": "1.7", "d": "Network Attached Storage — shared file-level storage accessible by multiple hosts.", "m": "Commonly used for storing VM templates, ISOs, and shared datastores."}, {"t": "Dedicated Host Billing", "obj": "1.8", "d": "A billing model where a customer pays for an entire physical host, regardless of utilization.", "m": "Useful for licensing or compliance requirements that need physical isolation from other tenants."}, {"t": "Reserved Resources", "obj": "1.8", "d": "Pre-purchasing capacity for a discounted rate in exchange for a committed term.", "m": "Reduces cost for predictable, steady-state workloads compared to pay-as-you-go pricing."}, {"t": "Pay-As-You-Go", "obj": "1.8", "d": "A billing model charging only for actual resource consumption, with no upfront commitment.", "m": "Maximizes flexibility for unpredictable or short-term workloads, at a higher per-unit cost than reserved pricing."}, {"t": "Spot Instance", "obj": "1.8", "d": "Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice.", "m": "Ideal for fault-tolerant, interruptible workloads like batch processing, but not suitable for critical always-on services."}, {"t": "Resource Metering", "obj": "1.8", "d": "Tracking actual consumption of cloud resources for billing and capacity planning purposes.", "m": "Provides the raw usage data that billing and rightsizing decisions are based on."}, {"t": "Tagging", "obj": "1.8", "d": "Attaching key-value metadata labels to cloud resources.", "m": "Enables cost allocation, automation, and organization of resources by project, owner, or environment."}, {"t": "Rightsizing", "obj": "1.8", "d": "Adjusting the size/type of provisioned resources to match actual workload demand.", "m": "Prevents overspending on oversized resources while avoiding performance issues from undersized ones."}, {"t": "Relational Database", "obj": "1.9", "d": "A database that organizes data into structured tables with defined relationships (SQL).", "m": "Best suited for structured data requiring strong consistency and complex queries/joins."}, {"t": "Non-Relational Database", "obj": "1.9", "d": "A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs.", "m": "Better suited for unstructured/semi-structured data and workloads needing horizontal scalability."}, {"t": "Self-Managed Database", "obj": "1.9", "d": "A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure.", "m": "Offers maximum control but requires the customer to handle all operational overhead."}, {"t": "Provider-Managed Database", "obj": "1.9", "d": "A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS).", "m": "Reduces administrative burden significantly, letting teams focus on the data and application instead of the database engine."}, {"t": "Compute Optimization (VM)", "obj": "1.10", "d": "Using virtual machines as the compute resource type for a workload.", "m": "Appropriate for workloads needing full OS control and long-running processes."}, {"t": "Compute Optimization (Container)", "obj": "1.10", "d": "Using containers as the compute resource type for a workload.", "m": "More lightweight and portable than VMs, ideal for microservices and rapid scaling."}, {"t": "Compute Optimization (Serverless)", "obj": "1.10", "d": "Using Function as a Service as the compute resource type for a workload.", "m": "Eliminates server management entirely, billing only for actual execution time."}, {"t": "Orchestration (Workload)", "obj": "1.10", "d": "Automated coordination of workload deployment, scaling, and lifecycle management.", "m": "Ensures workloads are placed, scaled, and healed automatically according to defined policies."}, {"t": "Workflow (Optimization)", "obj": "1.10", "d": "A defined sequence of automated steps/tasks that process data or coordinate resources.", "m": "Helps chain together cloud services and automate multi-step business processes."}, {"t": "Network Latency", "obj": "1.10", "d": "The time delay for data to travel between two points on a network.", "m": "A critical factor when placing workloads and choosing regions/AZs for latency-sensitive applications."}, {"t": "Network Throughput", "obj": "1.10", "d": "The actual amount of data successfully transferred over a network connection in a given time.", "m": "Determines whether a network link can support a workload's data transfer needs."}, {"t": "IOPS (Optimization)", "obj": "1.10", "d": "Input/Output Operations Per Second — a measure of storage performance.", "m": "A key metric for sizing storage for database or transaction-heavy workloads."}, {"t": "Storage Throughput", "obj": "1.10", "d": "The rate of data transfer to/from a storage system, usually measured in MB/s or GB/s.", "m": "Important for workloads that move large volumes of data, like backups or media processing."}, {"t": "Managed Services (Optimization)", "obj": "1.10", "d": "Using provider-operated services instead of self-managed infrastructure to reduce operational overhead.", "m": "Frees up staff time from routine maintenance so they can focus on higher-value work."}, {"t": "Machine Learning", "obj": "1.11", "d": "Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case.", "m": "Underpins many modern cloud AI services such as recommendation engines and fraud detection."}, {"t": "Text Recognition", "obj": "1.11", "d": "AI technology that extracts text from images or scanned documents (OCR).", "m": "Used to digitize and search paper documents or extract data from images automatically."}, {"t": "Text Translation", "obj": "1.11", "d": "AI technology that automatically converts text from one language to another.", "m": "Enables applications to serve global users without manual translation."}, {"t": "Visual Recognition", "obj": "1.11", "d": "AI technology that identifies objects, scenes, or features within images or video.", "m": "Powers use cases like content moderation, quality inspection, and security monitoring."}, {"t": "Sentiment Analysis", "obj": "1.11", "d": "AI technology that determines the emotional tone (positive/negative/neutral) of text.", "m": "Used to analyze customer feedback, reviews, and social media at scale."}, {"t": "Voice-to-Text", "obj": "1.11", "d": "AI technology that converts spoken audio into written text (speech recognition).", "m": "Powers transcription services, voice assistants, and accessibility features."}, {"t": "Text-to-Voice", "obj": "1.11", "d": "AI technology that converts written text into spoken audio (speech synthesis).", "m": "Used for voice assistants, accessibility tools, and automated phone systems."}, {"t": "Generative AI", "obj": "1.11", "d": "AI models that create new content (text, images, code) based on learned patterns.", "m": "A rapidly growing category of cloud AI services used for content creation and code assistance."}, {"t": "IoT Sensor", "obj": "1.11", "d": "A device that collects data from the physical environment (temperature, motion, etc.).", "m": "The data-collection endpoint in most IoT architectures, feeding data upstream for processing."}, {"t": "IoT Gateway", "obj": "1.11", "d": "A device that aggregates and relays data from multiple IoT sensors to the cloud.", "m": "Reduces the number of direct cloud connections needed and can perform local pre-processing."}, {"t": "IoT Communication", "obj": "1.11", "d": "The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data.", "m": "Choice of communication method affects range, power consumption, and bandwidth available to the device."}, {"t": "IoT Transmission Protocol", "obj": "1.11", "d": "Lightweight protocols (like MQTT or CoAP) designed for constrained IoT devices and networks.", "m": "Optimized for low bandwidth and power use, unlike heavier traditional web protocols."}, {"t": "Public Cloud", "obj": "2.1", "d": "Infrastructure owned by a third-party provider and shared across many customers (multi-tenant).", "m": "Lowest upfront cost and fastest to provision, but less control than private cloud."}, {"t": "Private Cloud", "obj": "2.1", "d": "Infrastructure dedicated to a single organization, hosted on- or off-premises.", "m": "Offers greater control and customization at higher cost than public cloud."}, {"t": "On Premises", "obj": "2.1", "d": "Infrastructure physically located and managed within the organization's own facilities.", "m": "Gives maximum control over hardware and data location, at the cost of full operational responsibility."}, {"t": "Hybrid Cloud", "obj": "2.1", "d": "A deployment model combining private/on-premises infrastructure with public cloud resources.", "m": "Common for gradual migration, burst capacity, or workloads with data residency constraints."}, {"t": "Community Cloud", "obj": "2.1", "d": "Infrastructure shared by several organizations with common concerns such as compliance or security requirements.", "m": "Balances shared cost benefits with more tailored governance than a general public cloud."}, {"t": "Blue-Green Deployment", "obj": "2.2", "d": "A strategy running two identical environments (blue and green), switching traffic to the new version once verified.", "m": "Allows near-instant rollback by simply switching traffic back to the previous environment."}, {"t": "Canary Deployment", "obj": "2.2", "d": "Gradually rolling out a change to a small subset of users or servers before a full rollout.", "m": "Limits the blast radius of a bad deployment by exposing it to only a fraction of traffic first."}, {"t": "Rolling Deployment", "obj": "2.2", "d": "Updating instances incrementally, a few at a time, rather than all at once.", "m": "Keeps the application available throughout the deployment, at the cost of a longer overall rollout window."}, {"t": "In-Place Deployment", "obj": "2.2", "d": "Updating an existing server or instance directly rather than deploying an entirely new one.", "m": "Simpler but riskier than blue-green since there is no separate environment to instantly roll back to."}, {"t": "On-Premises-to-Cloud Migration", "obj": "2.3", "d": "Moving workloads from local infrastructure into a cloud environment.", "m": "The most common migration type when organizations first adopt cloud computing."}, {"t": "Cloud-to-On-Premises Migration", "obj": "2.3", "d": "Moving workloads out of the cloud back to local infrastructure.", "m": "Sometimes chosen for cost, compliance, or performance reasons after initial cloud adoption."}, {"t": "Cloud-to-Cloud Migration", "obj": "2.3", "d": "Moving workloads from one cloud provider or region to another.", "m": "Often driven by cost optimization, feature needs, or avoiding vendor lock-in."}, {"t": "Vendor Lock-In", "obj": "2.3", "d": "Difficulty moving away from a cloud provider due to reliance on proprietary services or formats.", "m": "A key risk consideration when architecting for portability across multiple providers."}, {"t": "Rehost", "obj": "2.3", "d": "A migration strategy that moves an application to the cloud with minimal changes, also called lift and shift.", "m": "The fastest migration approach but does not take advantage of cloud-native features."}, {"t": "Replatform", "obj": "2.3", "d": "A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture.", "m": "A middle ground between a straight lift-and-shift and a full application redesign."}, {"t": "Re-Architect", "obj": "2.3", "d": "A migration strategy that substantially redesigns an application to be cloud-native.", "m": "Takes the most effort but unlocks the greatest long-term benefits like scalability and cost efficiency."}, {"t": "Retain", "obj": "2.3", "d": "A migration strategy that keeps a workload where it currently is, deferring migration.", "m": "Appropriate for applications not yet ready or not worth migrating due to cost or complexity."}, {"t": "Retire", "obj": "2.3", "d": "A migration strategy that decommissions an application no longer needed.", "m": "Reduces the overall migration scope and ongoing costs by eliminating unnecessary systems."}, {"t": "Refactor", "obj": "2.3", "d": "A migration strategy that rewrites portions of an application to better fit cloud-native patterns.", "m": "Similar to re-architecting but often more incremental, improving specific components over time."}, {"t": "Infrastructure as Code", "obj": "2.4", "d": "Managing and provisioning infrastructure through machine-readable definition files rather than manual processes.", "m": "Makes infrastructure changes repeatable, version-controlled, and auditable."}, {"t": "Configuration as Code", "obj": "2.4", "d": "Managing system or application configuration through code rather than manual configuration.", "m": "Ensures configuration consistency across environments and enables automated drift correction."}, {"t": "Drift Detection", "obj": "2.4", "d": "Identifying when a deployed resource's actual state no longer matches its defined IaC configuration.", "m": "Helps catch unauthorized or manual changes that could cause inconsistency or security gaps."}, {"t": "IaC Versioning", "obj": "2.4", "d": "Tracking changes to infrastructure code over time using version control.", "m": "Enables rollback to a known-good configuration and provides an audit trail of infrastructure changes."}, {"t": "IaC Testing", "obj": "2.4", "d": "Validating infrastructure code for syntax, security, and logic before it is applied to real environments.", "m": "Catches errors before they cause an outage or misconfiguration in production."}, {"t": "JSON", "obj": "2.4", "d": "JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates.", "m": "One of the two dominant data formats used to define cloud resources declaratively."}, {"t": "YAML", "obj": "2.4", "d": "Yet Another Markup Language — a human-readable data format widely used for IaC and configuration files.", "m": "The preferred format for tools like Kubernetes manifests and many CI/CD pipeline definitions."}, {"t": "Storage Requirements", "obj": "2.5", "d": "The capacity, performance, and durability needs a workload has for its data.", "m": "Must be assessed before provisioning to choose the right storage type and tier."}, {"t": "Compute Requirements", "obj": "2.5", "d": "The processing power (CPU, RAM) needed to run a workload effectively.", "m": "Determines the instance size and type selected during provisioning."}, {"t": "Network Requirements", "obj": "2.5", "d": "The bandwidth, latency, and connectivity needs of a workload.", "m": "Shapes decisions about region placement, dedicated connections, and load balancer configuration."}, {"t": "Availability Requirements", "obj": "2.5", "d": "The uptime and resiliency expectations for a workload.", "m": "Drives decisions like multi-AZ deployment, clustering, and failover design."}, {"t": "Compliance Requirements", "obj": "2.5", "d": "Legal or regulatory obligations a workload's data and processing must meet.", "m": "Can restrict which regions, providers, or configurations are acceptable for a given workload."}, {"t": "Log Collection", "obj": "3.1", "d": "Gathering log data from applications, systems, and services into a central location.", "m": "The first step in observability — without collection, logs remain scattered and hard to analyze."}, {"t": "Log Aggregation", "obj": "3.1", "d": "Combining logs from many sources into a unified, searchable view.", "m": "Enables correlation across services, which is essential for diagnosing distributed system issues."}, {"t": "Log Retention", "obj": "3.1", "d": "Defining how long log data is kept before being archived or deleted.", "m": "Balances storage cost against the need to investigate older incidents or meet compliance requirements."}, {"t": "Tracing", "obj": "3.1", "d": "Following a single request as it moves through multiple services in a distributed system.", "m": "Critical for pinpointing where latency or errors occur across microservices."}, {"t": "Monitoring Metrics", "obj": "3.1", "d": "Numeric measurements of system behavior (CPU, memory, request rate) collected over time.", "m": "The foundation of dashboards and alerting used to understand system health."}, {"t": "Alert Triage", "obj": "3.1", "d": "The process of reviewing and prioritizing incoming alerts to determine urgency and next steps.", "m": "Prevents alert fatigue and ensures the most critical issues are addressed first."}, {"t": "Alert Response", "obj": "3.1", "d": "The defined actions taken once an alert is triaged and confirmed to need action.", "m": "Turns detection into resolution — an alert with no response plan provides little value."}, {"t": "Triggered Scaling — Trending", "obj": "3.2", "d": "Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU).", "m": "Reacts to gradual changes in demand rather than short spikes."}, {"t": "Triggered Scaling — Load", "obj": "3.2", "d": "Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%).", "m": "The most common autoscaling trigger, reacting quickly to current demand."}, {"t": "Triggered Scaling — Event", "obj": "3.2", "d": "Scaling in response to a specific event (like a message queue depth increasing).", "m": "Useful for event-driven architectures where load isn't purely CPU/memory based."}, {"t": "Scheduled Scaling", "obj": "3.2", "d": "Scaling resources up or down at predefined times based on known usage patterns.", "m": "Ideal for predictable daily/weekly demand cycles, like scaling up before business hours."}, {"t": "Manual Scaling", "obj": "3.2", "d": "An administrator explicitly changing resource capacity rather than relying on automation.", "m": "Useful for planned events or when automated triggers aren't yet configured."}, {"t": "Horizontal Scaling", "obj": "3.2", "d": "Adding more instances of a resource to handle increased load (scale out).", "m": "Improves both capacity and redundancy, and is the standard scaling approach in cloud-native design."}, {"t": "Vertical Scaling", "obj": "3.2", "d": "Increasing the resources (CPU/RAM) of an existing instance (scale up).", "m": "Simpler than horizontal scaling but has an upper limit and usually requires downtime or a reboot."}, {"t": "Incremental Backup", "obj": "3.3", "d": "Backs up only data changed since the last backup of any type.", "m": "Fastest to perform, but restoring requires the full chain of backups applied in order."}, {"t": "Full Backup", "obj": "3.3", "d": "A complete copy of all selected data.", "m": "Forms the baseline that incremental and differential backups build on."}, {"t": "Differential Backup", "obj": "3.3", "d": "Backs up all data changed since the last full backup.", "m": "Restores are simpler than incremental (just the full plus the latest differential), but each differential grows larger over time."}, {"t": "Backup Schedule", "obj": "3.3", "d": "The defined frequency and timing of backup jobs.", "m": "Directly determines the achievable RPO for a given system."}, {"t": "Backup Retention (Ops)", "obj": "3.3", "d": "How long backup copies are kept before being deleted or overwritten.", "m": "Balances storage cost against the need to recover from an issue discovered after some delay."}, {"t": "Backup Replication", "obj": "3.3", "d": "Copying backup data to another location (often off-site or another region).", "m": "Protects against a disaster affecting the primary backup location."}, {"t": "Backup Encryption", "obj": "3.3", "d": "Encrypting backup data so it remains protected even if the storage media or files are exposed.", "m": "Especially important since backups often contain complete copies of sensitive production data."}, {"t": "Backup Recoverability Testing", "obj": "3.3", "d": "Actually restoring backup data to confirm it can be used successfully.", "m": "A backup reporting \"success\" does not guarantee the data is truly restorable — testing closes that gap."}, {"t": "Backup Integrity Testing", "obj": "3.3", "d": "Verifying that backed-up data has not been corrupted.", "m": "Ensures the backup itself is trustworthy before it's ever relied upon during an actual incident."}, {"t": "In-Place Recovery", "obj": "3.3", "d": "Restoring data directly onto the original system/location.", "m": "The simplest recovery approach when the original infrastructure is still available and intact."}, {"t": "Parallel Recovery", "obj": "3.3", "d": "Restoring data to an alternate system running alongside the original.", "m": "Useful for testing a restore or recovering without disrupting the still-running original system."}, {"t": "Bulk Recovery", "obj": "3.3", "d": "Restoring a large set of data all at once.", "m": "Appropriate when an entire system or dataset needs to be recovered together."}, {"t": "Granular Recovery", "obj": "3.3", "d": "Restoring individual files or specific data items rather than an entire dataset.", "m": "Saves time when only a small subset of data (like one accidentally deleted file) needs to be restored."}, {"t": "Patch", "obj": "3.4", "d": "A software update addressing a specific bug or vulnerability.", "m": "Applying patches promptly closes known security gaps before they can be exploited."}, {"t": "Major Update", "obj": "3.4", "d": "A significant version update that may include new features and breaking changes.", "m": "Requires more careful testing than minor updates due to a higher risk of compatibility issues."}, {"t": "Minor Update", "obj": "3.4", "d": "A smaller update, typically with bug fixes and small improvements.", "m": "Generally lower risk than major updates but should still be tested before production rollout."}, {"t": "Lifecycle Testing", "obj": "3.4", "d": "Validating changes (patches, updates, configuration) before applying them broadly.", "m": "Reduces the risk that a routine update introduces a new production issue."}, {"t": "Ephemeral Data", "obj": "3.4", "d": "Temporary data that does not need to persist beyond a session or process.", "m": "Doesn't require the same backup/retention rigor as persistent data."}, {"t": "Persistent Data", "obj": "3.4", "d": "Data that must be retained beyond the life of the process or instance that created it.", "m": "Requires durable storage and appropriate backup strategy since it represents lasting business value."}, {"t": "Decommissioning — End of Life", "obj": "3.4", "d": "Retiring a resource because it has reached the end of its useful life or support.", "m": "Requires planning for data migration/retention before the resource is removed."}, {"t": "Decommissioning — End of Support", "obj": "3.4", "d": "Retiring or upgrading a resource because the vendor no longer provides support/patches for it.", "m": "Running unsupported resources leaves known vulnerabilities permanently unpatched."}, {"t": "Scanning Scope", "obj": "4.1", "d": "Defining which systems, networks, or applications a vulnerability scan will cover.", "m": "Ensures the scan actually covers all in-scope assets rather than leaving blind spots."}, {"t": "Vulnerability Identification", "obj": "4.1", "d": "The step of detecting known weaknesses in systems, typically via automated scanning.", "m": "The first concrete step in the vulnerability management lifecycle, feeding into assessment and remediation."}, {"t": "Vulnerability Assessment", "obj": "4.1", "d": "Evaluating identified vulnerabilities for severity, exploitability, and business impact.", "m": "Helps prioritize which vulnerabilities to remediate first based on actual risk."}, {"t": "Remediation", "obj": "4.1", "d": "Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability.", "m": "The step that actually reduces risk — identification without remediation provides no real protection."}, {"t": "CVE", "obj": "4.1", "d": "Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities.", "m": "Provides a common reference so vulnerabilities can be tracked and discussed consistently across tools and vendors."}, {"t": "Data Sovereignty", "obj": "4.2", "d": "The principle that data is subject to the laws of the country in which it is physically located.", "m": "Determines which region a workload must be deployed in to satisfy legal requirements."}, {"t": "Data Ownership", "obj": "4.2", "d": "Defining who legally owns and controls a given set of data.", "m": "Clarifies responsibility and rights when data is stored or processed by a third-party cloud provider."}, {"t": "Data Locality", "obj": "4.2", "d": "Requirements or preferences about the physical location where data is stored or processed.", "m": "Closely related to, but distinct from, data sovereignty — it may be a business rather than legal requirement."}, {"t": "Data Classification", "obj": "4.2", "d": "Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted).", "m": "Drives how strictly a given piece of data must be protected and handled."}, {"t": "Litigation Hold", "obj": "4.2", "d": "A legal requirement to preserve specific data because it may be relevant to pending litigation.", "m": "Overrides normal retention/deletion schedules until the hold is lifted."}, {"t": "Contractual Retention", "obj": "4.2", "d": "A data retention requirement specified in a contract with a customer or partner.", "m": "May require data to be kept longer (or shorter) than the organization's default policy."}, {"t": "Regulatory Retention", "obj": "4.2", "d": "A data retention requirement mandated by law or industry regulation.", "m": "Non-compliance can result in legal penalties, distinct from purely internal retention preferences."}, {"t": "SOC2", "obj": "4.2", "d": "Systems and Organization Controls 2 — an audit framework evaluating a service provider's controls around security, availability, and confidentiality.", "m": "A common compliance report requested by customers evaluating a cloud vendor's security posture."}, {"t": "PCI DSS", "obj": "4.2", "d": "Payment Card Industry Data Security Standard — security requirements for handling payment card data.", "m": "Any cloud workload that stores, processes, or transmits card data must meet these requirements."}, {"t": "ISO 27001", "obj": "4.2", "d": "An international standard specifying requirements for an information security management system.", "m": "A widely recognized certification demonstrating a structured approach to information security."}, {"t": "Cloud Security Alliance", "obj": "4.2", "d": "An organization that publishes best practices and frameworks specifically for cloud security.", "m": "Provides cloud-specific guidance (like the CCM) that general security standards may not fully address."}, {"t": "Programmatic Access", "obj": "4.3", "d": "Accessing cloud resources via code rather than a human using a GUI (API/SDK).", "m": "Enables automation but requires careful credential management since keys can be leaked or misused."}, {"t": "API (IAM Context)", "obj": "4.3", "d": "Application Programming Interface — used here for programmatic management/access to cloud resources.", "m": "API access typically requires its own credentials (keys/tokens) separate from human user logins."}, {"t": "SDK", "obj": "4.3", "d": "Software Development Kit — a set of libraries/tools that let developers programmatically interact with a cloud platform.", "m": "Simplifies calling cloud provider APIs from within application code."}, {"t": "CLI", "obj": "4.3", "d": "Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources.", "m": "Popular for scripting and automation tasks that would be tedious through a web portal."}, {"t": "Web Portal", "obj": "4.3", "d": "A graphical, browser-based interface for managing cloud resources.", "m": "The most accessible management interface for humans, though less suited to automation."}, {"t": "SSH", "obj": "4.3", "d": "Secure Shell — an encrypted protocol for remote command-line access to cloud resources.", "m": "The standard way to securely administer Linux-based cloud instances remotely."}, {"t": "RDP", "obj": "4.3", "d": "Remote Desktop Protocol — Microsoft's protocol for remote graphical access to a system.", "m": "The standard way to remotely access Windows-based cloud instances."}, {"t": "Bastion Host", "obj": "4.3", "d": "A hardened server that provides a single, monitored entry point for administrative access into a private network.", "m": "Reduces the attack surface by ensuring administrative access doesn't require directly exposing every resource."}, {"t": "Local User Authentication", "obj": "4.3", "d": "Authenticating with credentials stored directly on the system rather than a central directory.", "m": "Simple but doesn't scale well and complicates centralized policy enforcement across many systems."}, {"t": "Federation", "obj": "4.3", "d": "Allowing users to authenticate using credentials from a separate, trusted identity provider.", "m": "Lets organizations use existing corporate identities to access cloud resources without duplicate accounts."}, {"t": "SAML", "obj": "4.3", "d": "Security Assertion Markup Language — an XML-based standard for exchanging authentication and authorization data between parties.", "m": "Commonly used to implement federated single sign-on into cloud platforms."}, {"t": "Token-Based Authentication", "obj": "4.3", "d": "Authentication using a temporary token issued after initial login, rather than resending credentials each time.", "m": "Reduces the exposure of long-term credentials and supports short-lived, revocable sessions."}, {"t": "Directory-Based Authentication", "obj": "4.3", "d": "Authenticating against a centralized directory service (like LDAP or Active Directory).", "m": "Centralizes identity management across many systems rather than maintaining separate local accounts."}, {"t": "MFA", "obj": "4.3", "d": "Multifactor Authentication — requiring two or more independent verification factors to log in.", "m": "Makes stolen credentials alone insufficient for an attacker to gain access."}, {"t": "OpenID Connect", "obj": "4.3", "d": "An identity layer built on top of OAuth 2.0 used for authentication (proving who you are).", "m": "Widely used for consumer and enterprise single sign-on into cloud applications."}, {"t": "Role-Based Access Control", "obj": "4.3", "d": "Granting permissions based on a user's assigned role rather than to each individual directly.", "m": "Simplifies administration and enforces consistent access across users with the same job function."}, {"t": "Group-Based Access Control", "obj": "4.3", "d": "Granting permissions to a group, which members inherit by being added to that group.", "m": "Similar to RBAC but organized around groups rather than formally defined roles."}, {"t": "OAuth 2.0", "obj": "4.3", "d": "An authorization framework that lets an application access resources on a user's behalf without sharing their password.", "m": "The standard mechanism behind \"log in with...\" and delegated API access scenarios."}, {"t": "Discretionary Access Control", "obj": "4.3", "d": "An access model where the resource owner decides who else can access it.", "m": "Flexible, but relies on individual owners consistently applying good judgment about access grants."}, {"t": "Audit Trail", "obj": "4.3", "d": "A chronological record of who did what, and when, within a system.", "m": "Essential for investigating incidents and demonstrating compliance with access policies."}, {"t": "Zero Trust", "obj": "4.4", "d": "A security model that assumes no user or device should be trusted by default, even inside the network perimeter.", "m": "Requires continuous verification of identity and context for every access request, not just at the network edge."}, {"t": "CIS Benchmark", "obj": "4.4", "d": "A set of vendor-neutral, consensus-based configuration hardening guidelines.", "m": "Provides a well-known, widely adopted baseline for hardening systems and cloud services."}, {"t": "Vendor-Specific Benchmark", "obj": "4.4", "d": "Hardening guidance published by a specific cloud provider or software vendor for their own product.", "m": "Complements general benchmarks with platform-specific configuration recommendations."}, {"t": "Hardening", "obj": "4.4", "d": "Reducing a system's attack surface by disabling unnecessary services, closing unused ports, and applying secure configurations.", "m": "One of the most fundamental and heavily tested security practices across all IT domains."}, {"t": "Patching (Security)", "obj": "4.4", "d": "Applying vendor-released updates that fix known vulnerabilities.", "m": "Closes known security gaps that attackers commonly target since patches for them already exist."}, {"t": "Data in Transit Encryption", "obj": "4.4", "d": "Encrypting data as it moves across a network (e.g., via TLS).", "m": "Protects data from eavesdropping while crossing untrusted networks like the internet."}, {"t": "Data at Rest Encryption", "obj": "4.4", "d": "Encrypting stored data so it remains unreadable without the correct key.", "m": "Protects data even if the underlying storage media is stolen or improperly accessed."}, {"t": "Secrets Management", "obj": "4.4", "d": "Securely storing and controlling access to credentials, API keys, and other sensitive configuration values.", "m": "Prevents secrets from being hardcoded in source code or exposed in plaintext configuration files."}, {"t": "API Security", "obj": "4.4", "d": "Practices and controls that protect APIs from abuse, unauthorized access, and attack.", "m": "APIs are a primary attack surface in cloud-native applications and require dedicated protective controls."}, {"t": "Principle of Least Privilege", "obj": "4.4", "d": "Granting only the minimum access rights needed to perform a function.", "m": "Limits the potential damage if an account or service is compromised."}, {"t": "Privileged Container", "obj": "4.4", "d": "A container granted elevated access to the host system's resources.", "m": "Significantly increases risk since a compromised privileged container can affect the underlying host."}, {"t": "Unprivileged Container", "obj": "4.4", "d": "A container running with restricted access, isolated from the host's sensitive resources.", "m": "The safer default for container security, limiting the impact of a container-level compromise."}, {"t": "Container File Access Permissions", "obj": "4.4", "d": "Controls governing which files and directories a container process can read or write.", "m": "Misconfigured permissions inside a container can let an attacker access or modify data they shouldn't."}, {"t": "Object Storage Security", "obj": "4.4", "d": "Access controls and encryption settings applied to object storage buckets/containers.", "m": "Misconfigured object storage permissions are a very common real-world cause of public data exposure."}, {"t": "File Storage Security", "obj": "4.4", "d": "Access controls and encryption applied to shared file storage systems.", "m": "Ensures only authorized users/systems can read or modify shared file data."}, {"t": "Endpoint Protection", "obj": "4.5", "d": "Security software (antivirus, EDR) installed directly on servers, VMs, or devices.", "m": "Detects and blocks malicious activity at the individual system level."}, {"t": "DLP", "obj": "4.5", "d": "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data.", "m": "Commonly blocks sensitive data like credit card numbers from leaving the network through channels like email."}, {"t": "IPS/IDS", "obj": "4.5", "d": "Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity.", "m": "IDS alerts on suspicious activity; IPS goes further by actively blocking it in real time."}, {"t": "DDoS Protection", "obj": "4.5", "d": "Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic.", "m": "Essential for internet-facing cloud services that could otherwise be overwhelmed by attack traffic."}, {"t": "IAM Policies", "obj": "4.5", "d": "Rules that define what actions a given identity is allowed or denied to perform on cloud resources.", "m": "The core mechanism for enforcing least privilege and access control in cloud environments."}, {"t": "Network ACL", "obj": "4.5", "d": "Access Control List — a set of rules controlling traffic in and out of a subnet at the network level.", "m": "Operates at the subnet/network level, distinct from security group/instance-level rules."}, {"t": "WAF", "obj": "4.5", "d": "Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications.", "m": "Protects against application-layer attacks like SQL injection and cross-site scripting that a normal firewall wouldn't catch."}, {"t": "Network Security Group", "obj": "4.5", "d": "A virtual firewall that controls inbound/outbound traffic for cloud resources like VMs.", "m": "The primary mechanism for instance-level network access control in most cloud platforms."}, {"t": "Event Monitoring (Security)", "obj": "4.6", "d": "Continuously observing system and security events for signs of malicious activity.", "m": "Provides the raw visibility needed to detect an attack in progress."}, {"t": "Deviation from Baseline", "obj": "4.6", "d": "A departure from a system's established normal behavior pattern.", "m": "A key signal used to detect anomalies that might indicate compromise or misuse."}, {"t": "Unnecessary Open Ports", "obj": "4.6", "d": "Network ports left open on a system that are not required for its function.", "m": "A common finding during security assessments and an easy target for attackers to exploit."}, {"t": "Vulnerability Exploitation — Human Error", "obj": "4.6", "d": "An attack that succeeds due to a mistake made by an authorized user (misconfiguration, mishandling credentials, etc.).", "m": "Highlights that technical controls alone can't fully prevent security incidents caused by human mistakes."}, {"t": "Vulnerability Exploitation — Outdated Software", "obj": "4.6", "d": "An attack that succeeds because a system was running software with a known, unpatched vulnerability.", "m": "Reinforces why timely patch management is one of the most effective security controls."}, {"t": "Phishing", "obj": "4.6", "d": "A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email.", "m": "One of the most common initial access vectors used in real-world breaches."}, {"t": "Malware", "obj": "4.6", "d": "Malicious software designed to damage, disrupt, or gain unauthorized access to a system.", "m": "A broad category of threats requiring layered defenses like endpoint protection and patching."}, {"t": "Ransomware", "obj": "4.6", "d": "Malware that encrypts a victim's data and demands payment for the decryption key.", "m": "Makes immutable, offline backups especially critical, since online backups can also be encrypted."}, {"t": "DDoS", "obj": "4.6", "d": "Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources.", "m": "Aims to exhaust resources or bandwidth so legitimate users cannot access the service."}, {"t": "Cryptojacking", "obj": "4.6", "d": "Unauthorized use of a system's computing resources to mine cryptocurrency.", "m": "Often detected through unexplained high CPU usage and increased cloud compute costs."}, {"t": "Zombie Instance", "obj": "4.6", "d": "A cloud instance that is running but forgotten, unmonitored, or unmanaged.", "m": "Represents both wasted cost and an unpatched, unmonitored attack surface."}, {"t": "Metadata Attack", "obj": "4.6", "d": "An attack that abuses a cloud instance's metadata service to steal credentials or configuration data.", "m": "A cloud-specific attack vector, since metadata services often provide temporary credentials to the instance."}, {"t": "Version Management", "obj": "5.1", "d": "Tracking and organizing different versions of code or configuration over time.", "m": "Provides the history needed to understand what changed and to roll back if necessary."}, {"t": "Code Review", "obj": "5.1", "d": "Having other team members examine proposed code changes before they are merged.", "m": "Catches bugs, security issues, and design problems before they reach production."}, {"t": "Pull Request", "obj": "5.1", "d": "A formal request to merge a proposed code change into a shared branch, typically triggering review.", "m": "The standard workflow mechanism for reviewing and discussing changes before merging."}, {"t": "Code Push", "obj": "5.1", "d": "Uploading local code changes to a remote/shared repository.", "m": "The action that shares a developer's committed changes with the rest of the team."}, {"t": "Code Commit", "obj": "5.1", "d": "Saving a snapshot of changes to the local version control history.", "m": "The basic unit of change tracking in most version control systems."}, {"t": "Code Merge", "obj": "5.1", "d": "Combining changes from different branches into one.", "m": "Integrates parallel work from multiple developers or feature branches."}, {"t": "Branch Management", "obj": "5.1", "d": "Organizing and maintaining separate lines of development (branches) within a repository.", "m": "Allows parallel work on features/fixes without disrupting the main codebase."}, {"t": "CI/CD Automation", "obj": "5.2", "d": "Automatically building, testing, and deploying code changes with minimal manual intervention.", "m": "Reduces human error and speeds up the delivery of software changes."}, {"t": "Code Integration", "obj": "5.2", "d": "Merging code changes from multiple contributors into a shared, continuously tested codebase.", "m": "The \"CI\" in CI/CD — frequent integration catches conflicts and bugs early."}, {"t": "Code Deployment", "obj": "5.2", "d": "Releasing built and tested code to a target environment (e.g., production).", "m": "The \"CD\" in CI/CD — automating this step reduces the risk and effort of releasing changes."}, {"t": "Build (CI/CD)", "obj": "5.2", "d": "Compiling/packaging source code into a deployable artifact.", "m": "The step that transforms source code into something that can actually be run or deployed."}, {"t": "CI/CD Testing", "obj": "5.2", "d": "Automatically running tests against code as part of the pipeline.", "m": "Catches regressions before code reaches production, a core benefit of CI/CD."}, {"t": "CI/CD Security", "obj": "5.2", "d": "Incorporating security scanning and checks into the automated pipeline.", "m": "Shifts security left, catching vulnerabilities earlier and cheaper than after deployment."}, {"t": "CI/CD Workflow", "obj": "5.2", "d": "The defined sequence of automated stages a change passes through from commit to deployment.", "m": "Documents and enforces a consistent, repeatable delivery process."}, {"t": "VM Image Artifact", "obj": "5.2", "d": "A packaged virtual machine image produced and stored as a build output.", "m": "Provides a versioned, reusable deployment unit for VM-based workloads."}, {"t": "Container Image Artifact", "obj": "5.2", "d": "A packaged container image produced and stored as a build output.", "m": "Provides a versioned, portable, reusable deployment unit for containerized workloads."}, {"t": "RPM Package", "obj": "5.2", "d": "Red Hat Package Manager — a package format used for installing software on RPM-based Linux distributions.", "m": "One of several standard package formats a CI/CD pipeline might produce or deploy."}, {"t": "Debian Package", "obj": "5.2", "d": "A package format (.deb) used for installing software on Debian-based Linux distributions.", "m": "The counterpart to RPM packages on Debian/Ubuntu-based systems."}, {"t": "Flat File Artifact", "obj": "5.2", "d": "A simple, unstructured file (like a config or script) produced or consumed by a pipeline.", "m": "Sometimes all that's needed for simple deployment tasks, without a full package format."}, {"t": "Public Repository", "obj": "5.2", "d": "A code or artifact repository accessible to anyone.", "m": "Convenient for open-source projects but not suitable for proprietary or sensitive code."}, {"t": "Private Repository", "obj": "5.2", "d": "A code or artifact repository restricted to authorized users/systems.", "m": "The standard choice for proprietary source code and internal build artifacts."}, {"t": "Event-Driven Architecture", "obj": "5.3", "d": "A design where components communicate by producing and reacting to events rather than direct calls.", "m": "Enables loose coupling and scalability, common in cloud-native and microservices designs."}, {"t": "REST", "obj": "5.3", "d": "Representational State Transfer — an architectural style for web services using standard HTTP methods.", "m": "The most common style for modern web APIs due to its simplicity and statelessness."}, {"t": "SOAP", "obj": "5.3", "d": "Simple Object Access Protocol — an XML-based messaging protocol for web services.", "m": "Older and more rigid than REST, but still used in some enterprise and legacy integrations."}, {"t": "RPC", "obj": "5.3", "d": "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local.", "m": "Underpins many internal microservice-to-microservice communication patterns (e.g., gRPC)."}, {"t": "Web Sockets", "obj": "5.3", "d": "A protocol providing full-duplex, persistent communication channels over a single TCP connection.", "m": "Enables real-time, bidirectional communication like chat apps or live dashboards, unlike typical request/response HTTP."}, {"t": "GraphQL", "obj": "5.3", "d": "A query language for APIs that lets clients request exactly the data they need.", "m": "Reduces over-fetching/under-fetching of data compared to traditional REST endpoints."}, {"t": "Ansible", "obj": "5.4", "d": "An open-source, agentless automation tool used for configuration management and orchestration.", "m": "Uses simple YAML playbooks to automate repetitive configuration tasks across many systems."}, {"t": "Docker", "obj": "5.4", "d": "A platform for building, running, and managing containers.", "m": "The most widely used container runtime and image format in modern DevOps workflows."}, {"t": "ELK Stack", "obj": "5.4", "d": "Elasticsearch, Logstash, and Kibana — a common combination of tools for log aggregation, processing, and visualization.", "m": "A widely used open-source stack for centralized logging and observability."}, {"t": "Git", "obj": "5.4", "d": "A distributed version control system used to track changes in source code.", "m": "The de facto standard version control system underlying most modern DevOps workflows."}, {"t": "GitHub Actions", "obj": "5.4", "d": "A CI/CD automation feature built into GitHub for running workflows in response to repository events.", "m": "Lets teams define build/test/deploy pipelines directly alongside their code in GitHub."}, {"t": "Grafana", "obj": "5.4", "d": "An open-source tool for visualizing metrics and creating monitoring dashboards.", "m": "Commonly paired with time-series databases to build real-time operational dashboards."}, {"t": "Jenkins", "obj": "5.4", "d": "A widely used open-source automation server for building CI/CD pipelines.", "m": "One of the most established tools for orchestrating build, test, and deployment automation."}, {"t": "Kubernetes", "obj": "5.4", "d": "An open-source platform for automating deployment, scaling, and management of containerized applications.", "m": "The de facto standard for container orchestration in modern cloud-native environments."}, {"t": "Terraform", "obj": "5.4", "d": "An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively.", "m": "One of the most widely used multi-cloud IaC tools, using its own HCL configuration language."}, {"t": "Incompatibility (Deployment)", "obj": "6.1", "d": "A failure caused by mismatched software, hardware, or configuration versions.", "m": "A very common root cause of failed deployments, especially after an update to one dependency."}, {"t": "Resource Allocation Misconfiguration", "obj": "6.1", "d": "Incorrectly assigned CPU, memory, or storage limits for a workload.", "m": "Can cause performance problems or outright deployment failure if requested resources aren't actually available."}, {"t": "Permission Issues (Deployment)", "obj": "6.1", "d": "A deployment failing because the deploying identity lacks sufficient rights.", "m": "One of the most common causes of failed automated deployments in cloud environments."}, {"t": "Oversubscription", "obj": "6.1", "d": "Allocating more virtual resources than the underlying physical capacity can truly support.", "m": "Can cause performance degradation or failed provisioning if too many workloads compete for the same physical resources."}, {"t": "Sizing Issues", "obj": "6.1", "d": "A deployment failure or performance problem caused by choosing an inappropriately sized resource.", "m": "Both undersizing (poor performance) and oversizing (wasted cost) are common sizing mistakes."}, {"t": "Outdated Component Definitions", "obj": "6.1", "d": "IaC or configuration templates referencing resource types/versions that no longer exist or are deprecated.", "m": "Leads to deployment failures when the referenced component is no longer valid on the platform."}, {"t": "Deprecation of Functionality", "obj": "6.1", "d": "A previously available feature or API being retired by the provider.", "m": "Deployments relying on deprecated functionality will eventually fail and must be updated proactively."}, {"t": "Full Outage", "obj": "6.1", "d": "A complete loss of service availability.", "m": "Represents the most severe availability impact, prioritized above partial outages."}, {"t": "Partial Outage", "obj": "6.1", "d": "A degradation where some, but not all, functionality or users are affected.", "m": "Still requires prompt attention but may allow more measured troubleshooting than a full outage."}, {"t": "API Throttling", "obj": "6.1", "d": "A provider intentionally limiting the rate of API calls a customer can make.", "m": "Can cause deployment or application failures if automation exceeds the allowed request rate."}, {"t": "Service Quota", "obj": "6.1", "d": "A provider-imposed limit on how many of a given resource type can be provisioned.", "m": "Deployments can fail silently if a quota is reached without prior awareness."}, {"t": "Regional Service Availability", "obj": "6.1", "d": "The fact that not all cloud services are available in every region.", "m": "A deployment can fail simply because a required service isn't offered in the chosen region."}, {"t": "DHCP (Troubleshooting)", "obj": "6.2", "d": "Dynamic Host Configuration Protocol — automatically assigns IP addressing information to hosts.", "m": "A failed DHCP service can leave hosts without any usable network configuration."}, {"t": "DNS (Troubleshooting)", "obj": "6.2", "d": "Domain Name System — resolves hostnames to IP addresses.", "m": "DNS failures cause connectivity issues that look like the destination is down, even when it's reachable by IP."}, {"t": "NTP (Troubleshooting)", "obj": "6.2", "d": "Network Time Protocol — synchronizes system clocks across a network.", "m": "Clock drift can break authentication (like Kerberos) and certificate validation in subtle, confusing ways."}, {"t": "NAT (Troubleshooting)", "obj": "6.2", "d": "Network Address Translation — translates private addresses to a public address for routing.", "m": "Misconfigured NAT/port forwarding is a common cause of unreachable services behind a private network."}, {"t": "HTTP Status Codes", "obj": "6.2", "d": "Standardized codes returned by web servers indicating the result of a request (e.g., 404, 500).", "m": "Provide the first clue about whether a problem is client-side, server-side, or related to routing/access."}, {"t": "Protocol Incompatibility", "obj": "6.2", "d": "A connectivity failure caused by two systems using different or mismatched protocol versions.", "m": "Common after upgrading one side of a connection without updating the other."}, {"t": "Protocol Deprecation", "obj": "6.2", "d": "A connectivity failure caused by a system relying on a protocol version the other side no longer supports.", "m": "Highlights the need to track and update deprecated protocol usage before it causes an outage."}, {"t": "IP Scope Exhaustion", "obj": "6.2", "d": "Running out of available addresses within a defined IP range or subnet.", "m": "Prevents new resources from being provisioned with an address until the range is expanded or reclaimed."}, {"t": "Network Overlap", "obj": "6.2", "d": "Two networks using conflicting/duplicate IP address ranges.", "m": "Commonly causes routing failures when connecting previously separate networks (e.g., via VPN or peering)."}, {"t": "Missing Route", "obj": "6.2", "d": "A required network path that has not been defined in a route table.", "m": "Traffic destined for that path is silently dropped, a common and often overlooked cloud networking issue."}, {"t": "Misconfigured Route", "obj": "6.2", "d": "An incorrect entry in a route table sending traffic to the wrong destination.", "m": "Can cause traffic to be dropped, looped, or sent somewhere unintended."}, {"t": "VLAN Misconfigured Tags", "obj": "6.2", "d": "Incorrect VLAN tagging causing traffic to be dropped or delivered to the wrong segment.", "m": "A classic Layer 2 troubleshooting issue, especially after switch or trunk reconfiguration."}, {"t": "Access vs. Trunk Ports", "obj": "6.2", "d": "The distinction between a switch port carrying a single VLAN (access) versus multiple VLANs (trunk).", "m": "Misconfiguring one as the other is a common cause of VLAN connectivity problems."}, {"t": "Cipher Suite Deprecation", "obj": "6.3", "d": "A connectivity/security failure caused by relying on an outdated, no-longer-supported encryption cipher suite.", "m": "Common after a platform disables old, insecure ciphers for security reasons, breaking legacy clients."}, {"t": "Privilege Escalation (Troubleshooting)", "obj": "6.3", "d": "An identity gaining higher access than originally granted, often through a flaw or misconfiguration.", "m": "A critical security troubleshooting concern after any suspected compromise of a low-privilege account."}, {"t": "Unauthorized Access", "obj": "6.3", "d": "Access to a system or data by someone without proper permission.", "m": "The core security incident type that access controls, logging, and monitoring are designed to catch."}, {"t": "Leaked Credentials", "obj": "6.3", "d": "Authentication credentials that have been exposed, such as in code repositories or logs.", "m": "A very common real-world cause of cloud breaches, often via credentials accidentally committed to source control."}, {"t": "Software Vulnerability Issues", "obj": "6.3", "d": "Problems arising from unpatched or improperly configured software containing known weaknesses.", "m": "Reinforces the ongoing need for vulnerability management and timely patching."}, {"t": "Unauthorized Software", "obj": "6.3", "d": "Software installed or running without proper approval, increasing risk and potentially breaching policy.", "m": "Can introduce vulnerabilities, malware, or licensing violations into an otherwise controlled environment."}, {"t": "ACL", "obj": "4.5", "d": "Access Control List — A list of rules attached to a resource that allows or denies specific traffic or users.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "AES", "obj": "4.4", "d": "Advanced Encryption Standard — The current industry-standard symmetric block cipher used to encrypt data at rest and in transit.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "AI", "obj": "1.2", "d": "Artificial Intelligence — Computer systems performing tasks that typically require human intelligence.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "API", "obj": "1.4", "d": "Application Programming Interface — A defined interface letting software components communicate, often used for cloud automation.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "BYOD", "obj": "4.3", "d": "Bring Your Own Device — A policy allowing employees to use personal devices to access corporate/cloud resources.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "CI/CD", "obj": "5.2", "d": "Continuous Integration/Continuous Deployment — Automated pipelines that build, test, and deploy code changes with minimal manual effort.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "CIS", "obj": "1.3", "d": "Center for Internet Security — Publishes consensus-based configuration hardening benchmarks.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "CPU", "obj": "2.5", "d": "Central Processing Unit — The primary processor executing instructions in a compute instance.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "CRM", "obj": "1.9", "d": "Customer Relationship Management — Software used to manage a company's interactions with customers, often delivered as SaaS.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "CRUD", "obj": "1.9", "d": "Create, Read, Update, Delete — The four basic operations performed on stored data.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "CSP", "obj": "1.1", "d": "Cloud Service Provider — A company offering cloud computing services (IaaS, PaaS, SaaS).", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "CVSS", "obj": "4.1", "d": "Common Vulnerability Scoring System — A framework for rating the severity of security vulnerabilities.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "CWE", "obj": "4.1", "d": "Common Weakness Enumeration — A community list of common software and hardware weakness types.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "CWSS", "obj": "4.1", "d": "Common Weakness Scoring System — A method for scoring the severity of software weaknesses.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "DBaaS", "obj": "1.9", "d": "Database as a Service — A managed cloud database offering where the provider handles the underlying operations.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "DHCP", "obj": "6.2", "d": "Dynamic Host Configuration Protocol — Automatically assigns IP addressing information to hosts on a network.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "DNS", "obj": "6.2", "d": "Domain Name System — Resolves human-readable hostnames to IP addresses.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "DR", "obj": "1.2", "d": "Disaster Recovery — The process and plans for restoring IT operations after a disruptive event.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "DSS", "obj": "4.2", "d": "Data Security Standard — Security requirements for protecting sensitive data, as in PCI DSS.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "ELK", "obj": "5.4", "d": "Elasticsearch, Logstash, and Kibana — A common open-source stack for log aggregation, processing, and visualization.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "GDPR", "obj": "4.2", "d": "General Data Protection Regulation — EU regulation governing the protection of personal data and privacy.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "GPU", "obj": "1.10", "d": "Graphics Processing Unit — A specialized processor for graphics and parallel compute workloads.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "HTTP", "obj": "4.5", "d": "Hypertext Transfer Protocol — The unencrypted protocol used to transfer web content.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "IAM", "obj": "4.3", "d": "Identity and Access Management — The framework of policies and tools controlling who can access which cloud resources.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "ICMP", "obj": "6.2", "d": "Internet Control Message Protocol — A protocol used for network diagnostics such as ping and error reporting.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "IDS", "obj": "4.5", "d": "Intrusion Detection System — Monitors network or host activity for signs of an attack without blocking it.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "IOPS", "obj": "1.10", "d": "Input/Output Operations Per Second — A measure of storage system performance.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "IP", "obj": "1.2", "d": "Internet Protocol — The protocol responsible for addressing and routing packets across networks.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "IPS", "obj": "1.9", "d": "Intrusion Prevention System — Detects and actively blocks malicious network activity.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "iSCSI", "obj": "1.4", "d": "Internet Small Computer System Interface — Carries SCSI storage commands over IP networks for block-level SAN access.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "ISO", "obj": "1.2", "d": "International Organization for Standardization — Publishes international standards; also refers to a disk image (.iso) file format.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "ISP", "obj": "1.3", "d": "Internet Service Provider — A company providing internet access and connectivity.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "ITIL", "obj": "3.4", "d": "Information Technology Infrastructure Library — A framework of best practices for IT service management.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "LAN", "obj": "1.3", "d": "Local Area Network — A network confined to a relatively small physical area.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "LDAP", "obj": "4.3", "d": "Lightweight Directory Access Protocol — A protocol for querying and modifying directory services.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "LUN", "obj": "1.4", "d": "Logical Unit Number — An identifier for a logically addressable storage volume presented from a SAN.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "MTU", "obj": "6.2", "d": "Maximum Transmission Unit — The largest packet size that can be transmitted over a network link.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "NAS", "obj": "1.7", "d": "Network Attached Storage — File-level storage accessed over a network, typically via NFS or SMB/CIFS.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "NAT", "obj": "1.3", "d": "Network Address Translation — Translates private IP addresses to a public address (or vice versa) for routing.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "NIC", "obj": "1.3", "d": "Network Interface Card — Hardware that connects a compute instance to a network.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "NoSQL", "obj": "1.9", "d": "Not Only Structured Query Language — A category of non-relational databases using flexible data models.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "NTP", "obj": "6.2", "d": "Network Time Protocol — Synchronizes system clocks across a network, critical for authentication and logging.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "NVME", "obj": "1.4", "d": "Non-Volatile Memory Express — A high-speed protocol for SSDs connected via the PCIe bus.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "OAuth", "obj": "4.3", "d": "Open Authorization — An authorization framework letting an application access resources on a user's behalf.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "OIDC", "obj": "4.3", "d": "OpenID Connect Protocol — An identity layer built on OAuth 2.0 used for authentication.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "OS", "obj": "1.1", "d": "Operating System — The base software managing hardware resources and running applications.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "PCI", "obj": "4.2", "d": "Payment Card Industry — The industry group whose standards govern the security of payment card data.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "RACI", "obj": "3.1", "d": "Responsible, Accountable, Consulted, Informed — A framework for defining roles and responsibilities in a process.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "RAID", "obj": "1.4", "d": "Redundant Array of Independent Disks — A technology combining multiple physical disks for redundancy, performance, or both.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "RAM", "obj": "1.1", "d": "Random Access Memory — Volatile memory used to store data actively in use by running processes.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "RPM", "obj": "5.2", "d": "Red Hat Package Manager — A package format used for installing software on RPM-based Linux distributions.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "RTMP", "obj": "5.3", "d": "Real-time Messaging Protocol — A protocol historically used for streaming audio, video, and data over the internet.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "SAN", "obj": "1.7", "d": "Storage Area Network — A dedicated network providing block-level storage access to servers.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "SQL", "obj": "1.9", "d": "Structured Query Language — The standard language used to query and manage data in relational databases.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "SSL", "obj": "1.3", "d": "Secure Sockets Layer — The predecessor to TLS for encrypting network communications, now largely deprecated.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "SSO", "obj": "4.3", "d": "Single Sign-On — Authenticate once to gain access to multiple connected systems.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "STAR", "obj": "4.2", "d": "Security, Trust, Assurance, Risk — A Cloud Security Alliance program for assessing cloud provider security.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "TCP", "obj": "1.3", "d": "Transmission Control Protocol — A connection-oriented transport protocol that guarantees reliable, ordered delivery.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "TLS", "obj": "4.4", "d": "Transport Layer Security — The modern standard protocol for encrypting network communications.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "USB", "obj": "1.7", "d": "Universal Serial Bus — A common interface standard for connecting peripherals and storage.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "vCPU", "obj": "1.10", "d": "Virtual CPU — A virtualized representation of a physical CPU core allocated to a VM.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "VDI", "obj": "4.3", "d": "Virtual Desktop Infrastructure — Hosting desktop operating systems on centralized servers, accessed remotely by users.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "VM", "obj": "1.4", "d": "Virtual Machine — A software-based emulation of a physical computer running under a hypervisor.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}, {"t": "vNIC", "obj": "1.7", "d": "Virtual NIC — A virtual network adapter presented to a guest VM by the hypervisor.", "m": "Appears in the CV0-004 acronym list; know both the expansion and the concept it refers to."}];

