const ACRONYMS = [["CPU", "Central Processing Unit", "The primary processor executing instructions in a compute instance."], ["CRM", "Customer Relationship Management", "Software used to manage a company's interactions with customers, often delivered as SaaS."], ["NoSQL", "Not Only Structured Query Language", "A category of non-relational databases using flexible data models."], ["TCP", "Transmission Control Protocol", "A connection-oriented transport protocol that guarantees reliable, ordered delivery."], ["SSL", "Secure Sockets Layer", "The predecessor to TLS for encrypting network communications, now largely deprecated."], ["CSP", "Cloud Service Provider", "A company offering cloud computing services (IaaS, PaaS, SaaS)."], ["SOAP", "Simple Object Access Protocol", "An XML-based messaging protocol for web services."], ["LUN", "Logical Unit Number", "An identifier for a logically addressable storage volume presented from a SAN."], ["CSA", "Cloud Security Alliance", "An organization publishing best practices and frameworks for cloud security."], ["BGP", "Border Gateway Protocol", "The routing protocol used to exchange routing information between large networks."], ["DR", "Disaster Recovery", "The process and plans for restoring IT operations after a disruptive event."], ["CWSS", "Common Weakness Scoring System", "A method for scoring the severity of software weaknesses."], ["SQL", "Structured Query Language", "The standard language used to query and manage data in relational databases."], ["CIS", "Center for Internet Security", "Publishes consensus-based configuration hardening benchmarks."], ["CI/CD", "Continuous Integration/Continuous Deployment", "Automated pipelines that build, test, and deploy code changes with minimal manual effort."], ["NAS", "Network Attached Storage", "File-level storage accessed over a network, typically via NFS or SMB/CIFS."], ["RAID", "Redundant Array of Independent Disks", "A technology combining multiple physical disks for redundancy, performance, or both."], ["CRUD", "Create, Read, Update, Delete", "The four basic operations performed on stored data."], ["SDK", "Software Development Kit", "Libraries and tools letting developers programmatically interact with a cloud platform."], ["NIC", "Network Interface Card", "Hardware that connects a compute instance to a network."], ["RPM", "Red Hat Package Manager", "A package format used for installing software on RPM-based Linux distributions."], ["vCPU", "Virtual CPU", "A virtualized representation of a physical CPU core allocated to a VM."], ["LDAP", "Lightweight Directory Access Protocol", "A protocol for querying and modifying directory services."], ["RTMP", "Real-time Messaging Protocol", "A protocol historically used for streaming audio, video, and data over the internet."], ["USB", "Universal Serial Bus", "A common interface standard for connecting peripherals and storage."], ["MTU", "Maximum Transmission Unit", "The largest packet size that can be transmitted over a network link."], ["ELK", "Elasticsearch, Logstash, and Kibana", "A common open-source stack for log aggregation, processing, and visualization."], ["RDP", "Remote Desktop Protocol", "Microsoft's protocol for remote graphical access to a system."], ["NVME", "Non-Volatile Memory Express", "A high-speed protocol for SSDs connected via the PCIe bus."], ["IPS", "Intrusion Prevention System", "Detects and actively blocks malicious network activity."], ["API", "Application Programming Interface", "A defined interface letting software components communicate, often used for cloud automation."], ["ISP", "Internet Service Provider", "A company providing internet access and connectivity."], ["VPN", "Virtual Private Network", "An encrypted tunnel providing secure remote connectivity over a public network."], ["OAuth", "Open Authorization", "An authorization framework letting an application access resources on a user's behalf."], ["DDoS", "Distributed Denial of Service", "An attack overwhelming a target with traffic from many distributed sources."], ["STAR", "Security, Trust, Assurance, Risk", "A Cloud Security Alliance program for assessing cloud provider security."], ["SAML", "Security Assertion Markup Language", "An XML-based standard for exchanging authentication and authorization data."], ["PaaS", "Platform as a Service", "A cloud model providing a managed platform for developing and running applications."], ["SAN", "Storage Area Network", "A dedicated network providing block-level storage access to servers."], ["IDS", "Intrusion Detection System", "Monitors network or host activity for signs of an attack without blocking it."], ["OIDC", "OpenID Connect Protocol", "An identity layer built on OAuth 2.0 used for authentication."], ["SaaS", "Software as a Service", "A cloud model delivering fully managed application software over the internet."], ["IAM", "Identity and Access Management", "The framework of policies and tools controlling who can access which cloud resources."], ["JSON", "JavaScript Object Notation", "A lightweight, structured data format commonly used for APIs and IaC templates."], ["AI", "Artificial Intelligence", "Computer systems performing tasks that typically require human intelligence."], ["DHCP", "Dynamic Host Configuration Protocol", "Automatically assigns IP addressing information to hosts on a network."], ["ML", "Machine Learning", "Algorithms that learn patterns from data to make predictions without explicit programming."], ["ACL", "Access Control List", "A list of rules attached to a resource that allows or denies specific traffic or users."], ["SDN", "Software-defined Network", "Decouples the network control plane from the physical data plane for programmatic management."], ["IP", "Internet Protocol", "The protocol responsible for addressing and routing packets across networks."], ["IOPS", "Input/Output Operations Per Second", "A measure of storage system performance."], ["SSO", "Single Sign-On", "Authenticate once to gain access to multiple connected systems."], ["ITIL", "Information Technology Infrastructure Library", "A framework of best practices for IT service management."], ["WAF", "Web Application Firewall", "A firewall designed to filter and monitor HTTP traffic to web applications."], ["VPC", "Virtual Private Cloud", "An isolated, logically defined network within a public cloud provider's infrastructure."], ["IaaS", "Infrastructure as a Service", "A cloud model providing virtualized compute, storage, and networking resources."], ["RAM", "Random Access Memory", "Volatile memory used to store data actively in use by running processes."], ["SOC2", "System and Organization Controls 2", "An audit framework evaluating a service provider's security and availability controls."], ["CVE", "Common Vulnerabilities and Exposures", "A standardized identifier for publicly known security vulnerabilities."], ["AZ", "Availability Zone", "An isolated location within a cloud region with independent power, cooling, and networking."], ["GPU", "Graphics Processing Unit", "A specialized processor for graphics and parallel compute workloads."], ["SSH", "Secure Shell", "An encrypted protocol for secure remote command-line access and file transfer."], ["CDN", "Content Delivery Network", "A geographically distributed set of servers that cache content closer to end users."], ["VM", "Virtual Machine", "A software-based emulation of a physical computer running under a hypervisor."], ["CWE", "Common Weakness Enumeration", "A community list of common software and hardware weakness types."], ["NTP", "Network Time Protocol", "Synchronizes system clocks across a network, critical for authentication and logging."], ["iSCSI", "Internet Small Computer System Interface", "Carries SCSI storage commands over IP networks for block-level SAN access."], ["HTTP", "Hypertext Transfer Protocol", "The unencrypted protocol used to transfer web content."], ["CLI", "Common Language Infrastructure", "A text-based command line tool for managing cloud resources."], ["vNIC", "Virtual NIC", "A virtual network adapter presented to a guest VM by the hypervisor."], ["NAT", "Network Address Translation", "Translates private IP addresses to a public address (or vice versa) for routing."], ["SSD", "Solid-state Drive", "Flash-based storage offering faster performance and no moving parts compared to HDDs."], ["TLS", "Transport Layer Security", "The modern standard protocol for encrypting network communications."], ["VDI", "Virtual Desktop Infrastructure", "Hosting desktop operating systems on centralized servers, accessed remotely by users."], ["DSS", "Data Security Standard", "Security requirements for protecting sensitive data, as in PCI DSS."], ["RPO", "Recovery Point Objective", "The maximum acceptable amount of data loss, measured in time."], ["GDPR", "General Data Protection Regulation", "EU regulation governing the protection of personal data and privacy."], ["CVSS", "Common Vulnerability Scoring System", "A framework for rating the severity of security vulnerabilities."], ["PCI", "Payment Card Industry", "The industry group whose standards govern the security of payment card data."], ["RACI", "Responsible, Accountable, Consulted, Informed", "A framework for defining roles and responsibilities in a process."], ["LAN", "Local Area Network", "A network confined to a relatively small physical area."], ["RTO", "Recovery Time Objective", "The maximum acceptable downtime for a system after a disruption."], ["AES", "Advanced Encryption Standard", "The current industry-standard symmetric block cipher used to encrypt data at rest and in transit."], ["DNS", "Domain Name System", "Resolves human-readable hostnames to IP addresses."], ["DLP", "Data Loss Prevention", "Controls that detect and prevent unauthorized transmission of sensitive data."], ["RPC", "Remote Procedure Call", "Lets a program execute a procedure on a remote system as if it were local."], ["ICMP", "Internet Control Message Protocol", "A protocol used for network diagnostics such as ping and error reporting."], ["ISO", "International Organization for Standardization", "Publishes international standards; also refers to a disk image (.iso) file format."], ["REST", "Representational State Transfer", "An architectural style for web services using standard HTTP methods."], ["OS", "Operating System", "The base software managing hardware resources and running applications."], ["CaC", "Configuration as Code", "Managing system/application configuration through code rather than manual configuration."], ["MFA", "Multifactor Authentication", "Requiring two or more independent verification factors to authenticate."], ["VLAN", "Virtual LAN", "Logically segments a physical switch into multiple isolated broadcast domains."], ["FaaS", "Function as a Service", "A serverless model where code runs in response to events without managing servers."], ["BYOD", "Bring Your Own Device", "A policy allowing employees to use personal devices to access corporate/cloud resources."], ["DBaaS", "Database as a Service", "A managed cloud database offering where the provider handles the underlying operations."], ["IaC", "Infrastructure as Code", "Managing and provisioning infrastructure through machine-readable definition files."], ["HDD", "Hard Disk Drive", "A traditional magnetic spinning-platter storage device."]];

/* ============ PERFORMANCE-BASED QUESTIONS (PBQ) ============ */
const PBQ = [{"obj": "1.1", "type": "match", "title": "Match each term to its correct definition (1.1)", "pairs": [["Shared Responsibility Model", "A framework defining which security and operational tasks belong to the cloud provider versus the customer."], ["IaaS", "Infrastructure as a Service — provides virtualized compute, storage, and networking, leaving the OS and above to the customer."], ["PaaS", "Platform as a Service — provides a managed runtime/platform for developing and deploying applications without managing the underlying OS."], ["SaaS", "Software as a Service — delivers a fully managed application to end users over the internet."], ["FaaS", "Function as a Service — lets code run in response to events without provisioning or managing any server (serverless)."]], "id": 0}, {"obj": "1.3", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["NAT", "Network Address Translation"], ["SSD", "Solid-state Drive"], ["TLS", "Transport Layer Security"], ["VDI", "Virtual Desktop Infrastructure"], ["DSS", "Data Security Standard"]], "id": 1}, {"obj": "6.3", "type": "match", "title": "Match each term to its correct definition (6.3)", "pairs": [["Unauthorized Software", "Software installed or running without proper approval, increasing risk and potentially breaching policy."], ["Software Vulnerability Issues", "Problems arising from unpatched or improperly configured software containing known weaknesses."], ["Leaked Credentials", "Authentication credentials that have been exposed, such as in code repositories or logs."], ["Privilege Escalation (Troubleshooting)", "An identity gaining higher access than originally granted, often through a flaw or misconfiguration."], ["Unauthorized Access", "Access to a system or data by someone without proper permission."], ["Cipher Suite Deprecation", "A connectivity/security failure caused by relying on an outdated, no-longer-supported encryption cipher suite."]], "id": 2}, {"obj": "6.1", "type": "match", "title": "Match each term to its correct definition (6.1)", "pairs": [["Full Outage", "A complete loss of service availability."], ["Incompatibility (Deployment)", "A failure caused by mismatched software, hardware, or configuration versions."], ["API Throttling", "A provider intentionally limiting the rate of API calls a customer can make."], ["Deprecation of Functionality", "A previously available feature or API being retired by the provider."], ["Partial Outage", "A degradation where some, but not all, functionality or users are affected."], ["Permission Issues (Deployment)", "A deployment failing because the deploying identity lacks sufficient rights."]], "id": 3}, {"obj": "1.7", "type": "match", "title": "Match each term to its correct definition (1.7)", "pairs": [["Clustering", "Grouping multiple hypervisor hosts together to share resources and enable failover/migration."], ["VM Network", "The virtual networking configuration connecting a VM to virtual switches and, ultimately, the physical network."], ["Overlay Network", "A virtual network built on top of physical network infrastructure, common in virtualization and containers."], ["Stand-Alone Virtualization", "A single hypervisor host running VMs with no clustering."], ["Host Affinity", "A rule keeping specific VMs running on the same (or different) physical host."], ["Cloning", "Creating an exact copy of an existing VM."]], "id": 4}, {"obj": "6.1", "type": "order", "title": "General cloud troubleshooting methodology", "steps": ["Identify the problem: gather information, question users, and replicate if possible", "Establish a theory of probable cause", "Test the theory to determine the actual cause", "Establish a plan of action to resolve the problem", "Implement the solution or escalate", "Verify full system functionality", "Document findings, actions taken, and outcomes"], "id": 5}, {"obj": "4.4", "type": "match", "title": "Match each term to its correct definition (4.4)", "pairs": [["Data at Rest Encryption", "Encrypting stored data so it remains unreadable without the correct key."], ["Principle of Least Privilege", "Granting only the minimum access rights needed to perform a function."], ["File Storage Security", "Access controls and encryption applied to shared file storage systems."], ["API Security", "Practices and controls that protect APIs from abuse, unauthorized access, and attack."], ["Privileged Container", "A container granted elevated access to the host system's resources."], ["Container File Access Permissions", "Controls governing which files and directories a container process can read or write."]], "id": 6}, {"obj": "4.6", "type": "match", "title": "Match each term to its correct definition (4.6)", "pairs": [["Malware", "Malicious software designed to damage, disrupt, or gain unauthorized access to a system."], ["Event Monitoring (Security)", "Continuously observing system and security events for signs of malicious activity."], ["Phishing", "A social engineering attack that tricks a user into revealing credentials or taking a harmful action, typically via email."], ["Zombie Instance", "A cloud instance that is running but forgotten, unmonitored, or unmanaged."], ["Metadata Attack", "An attack that abuses a cloud instance's metadata service to steal credentials or configuration data."], ["DDoS", "Distributed Denial of Service — an attack that overwhelms a target with traffic from many distributed sources."]], "id": 7}, {"obj": "1.1", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["CSP", "Cloud Service Provider"], ["SOAP", "Simple Object Access Protocol"], ["LUN", "Logical Unit Number"], ["CSA", "Cloud Security Alliance"], ["BGP", "Border Gateway Protocol"]], "id": 8}, {"obj": "1.4", "type": "match", "title": "Match each term to its correct definition (1.4)", "pairs": [["File Storage", "Storage that presents a shared, hierarchical file system accessible by multiple clients (e.g., NFS/SMB)."], ["Block Storage", "Storage that presents raw, addressable blocks of data, typically attached to a single VM like a virtual disk."], ["Cold Storage Tier", "A storage tier for infrequently accessed data, offering lower cost with slower retrieval."], ["Warm Storage Tier", "A storage tier for data accessed less frequently than hot data, balancing cost and access speed."], ["SSD", "Solid-State Drive — flash-based storage with no moving parts, offering fast random I/O."], ["HDD", "Hard Disk Drive — traditional magnetic spinning-platter storage."]], "id": 9}, {"obj": "4.2", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["STAR", "Security, Trust, Assurance, Risk"], ["SAML", "Security Assertion Markup Language"], ["PaaS", "Platform as a Service"], ["SAN", "Storage Area Network"], ["IDS", "Intrusion Detection System"]], "id": 10}, {"obj": "5.2", "type": "order", "title": "A typical CI/CD pipeline flow", "steps": ["Developer commits and pushes code to the shared repository", "Pipeline automatically triggers a build", "Automated tests run against the build", "Security/quality scans are performed", "Artifact is published to a repository", "Artifact is deployed to the target environment"], "id": 11}, {"obj": "2.2", "type": "match", "title": "Match each term to its correct definition (2.2)", "pairs": [["Canary Deployment", "Gradually rolling out a change to a small subset of users or servers before a full rollout."], ["Rolling Deployment", "Updating instances incrementally, a few at a time, rather than all at once."], ["In-Place Deployment", "Updating an existing server or instance directly rather than deploying an entirely new one."], ["Blue-Green Deployment", "A strategy running two identical environments (blue and green), switching traffic to the new version once verified."]], "id": 12}, {"obj": "2.5", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["CPU", "Central Processing Unit"], ["CRM", "Customer Relationship Management"], ["NoSQL", "Not Only Structured Query Language"], ["TCP", "Transmission Control Protocol"], ["SSL", "Secure Sockets Layer"]], "id": 13}, {"obj": "1.7", "type": "order", "title": "Migrating a running VM between hosts (live migration)", "steps": ["Confirm both source and destination hosts are part of the same cluster with shared storage", "Verify the destination host has sufficient available resources", "Initiate the live migration", "Memory state is copied to the destination while the VM keeps running on the source", "A brief final cutover switches execution to the destination host", "Confirm the VM is running normally on the new host"], "id": 14}, {"obj": "1.10", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["GPU", "Graphics Processing Unit"], ["SSH", "Secure Shell"], ["CDN", "Content Delivery Network"], ["VM", "Virtual Machine"], ["CWE", "Common Weakness Enumeration"]], "id": 15}, {"obj": "4.1", "type": "order", "title": "The vulnerability management lifecycle", "steps": ["Define the scanning scope for systems to be assessed", "Scan and identify vulnerabilities across in-scope assets", "Assess each vulnerability's severity and business impact", "Prioritize vulnerabilities based on risk", "Remediate through patching or compensating controls", "Re-scan to confirm remediation was successful"], "id": 16}, {"obj": "1.3", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["LAN", "Local Area Network"], ["RTO", "Recovery Time Objective"], ["AES", "Advanced Encryption Standard"], ["DNS", "Domain Name System"], ["DLP", "Data Loss Prevention"]], "id": 17}, {"obj": "2.4", "type": "match", "title": "Match each term to its correct definition (2.4)", "pairs": [["Configuration as Code", "Managing system or application configuration through code rather than manual configuration."], ["Infrastructure as Code", "Managing and provisioning infrastructure through machine-readable definition files rather than manual processes."], ["JSON", "JavaScript Object Notation — a lightweight, structured data format commonly used for APIs and some IaC templates."], ["Drift Detection", "Identifying when a deployed resource's actual state no longer matches its defined IaC configuration."], ["IaC Testing", "Validating infrastructure code for syntax, security, and logic before it is applied to real environments."], ["IaC Versioning", "Tracking changes to infrastructure code over time using version control."]], "id": 18}, {"obj": "1.7", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["NAS", "Network Attached Storage"], ["RAID", "Redundant Array of Independent Disks"], ["CRUD", "Create, Read, Update, Delete"], ["SDK", "Software Development Kit"], ["NIC", "Network Interface Card"]], "id": 19}, {"obj": "5.3", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["RPC", "Remote Procedure Call"], ["ICMP", "Internet Control Message Protocol"], ["ISO", "International Organization for Standardization"], ["REST", "Representational State Transfer"], ["OS", "Operating System"]], "id": 20}, {"obj": "4.1", "type": "match", "title": "Match each term to its correct definition (4.1)", "pairs": [["Vulnerability Assessment", "Evaluating identified vulnerabilities for severity, exploitability, and business impact."], ["Remediation", "Applying a fix (patch, configuration change, or compensating control) to resolve a vulnerability."], ["Vulnerability Identification", "The step of detecting known weaknesses in systems, typically via automated scanning."], ["Scanning Scope", "Defining which systems, networks, or applications a vulnerability scan will cover."], ["CVE", "Common Vulnerabilities and Exposures — a standardized identifier for publicly known security vulnerabilities."]], "id": 21}, {"obj": "1.10", "type": "match", "title": "Match each term to its correct definition (1.10)", "pairs": [["Workflow (Optimization)", "A defined sequence of automated steps/tasks that process data or coordinate resources."], ["Network Latency", "The time delay for data to travel between two points on a network."], ["Network Throughput", "The actual amount of data successfully transferred over a network connection in a given time."], ["Compute Optimization (Serverless)", "Using Function as a Service as the compute resource type for a workload."], ["Managed Services (Optimization)", "Using provider-operated services instead of self-managed infrastructure to reduce operational overhead."], ["Orchestration (Workload)", "Automated coordination of workload deployment, scaling, and lifecycle management."]], "id": 22}, {"obj": "2.2", "type": "order", "title": "Performing a blue-green deployment", "steps": ["Provision the new (green) environment identical to production (blue)", "Deploy and test the new version fully in the green environment", "Gradually or fully switch traffic from blue to green", "Monitor the green environment closely for issues", "Keep blue on standby for rollback if problems occur", "Decommission the blue environment once green is confirmed stable"], "id": 23}, {"obj": "5.2", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["RPM", "Red Hat Package Manager"], ["vCPU", "Virtual CPU"], ["LDAP", "Lightweight Directory Access Protocol"], ["RTMP", "Real-time Messaging Protocol"], ["USB", "Universal Serial Bus"]], "id": 24}, {"obj": "6.2", "type": "match", "title": "Match each term to its correct definition (6.2)", "pairs": [["Protocol Incompatibility", "A connectivity failure caused by two systems using different or mismatched protocol versions."], ["Missing Route", "A required network path that has not been defined in a route table."], ["Network Overlap", "Two networks using conflicting/duplicate IP address ranges."], ["NTP (Troubleshooting)", "Network Time Protocol — synchronizes system clocks across a network."], ["IP Scope Exhaustion", "Running out of available addresses within a defined IP range or subnet."], ["Access vs. Trunk Ports", "The distinction between a switch port carrying a single VLAN (access) versus multiple VLANs (trunk)."]], "id": 25}, {"obj": "6.2", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["DHCP", "Dynamic Host Configuration Protocol"], ["ML", "Machine Learning"], ["ACL", "Access Control List"], ["SDN", "Software-defined Network"], ["IP", "Internet Protocol"]], "id": 26}, {"obj": "3.2", "type": "match", "title": "Match each term to its correct definition (3.2)", "pairs": [["Horizontal Scaling", "Adding more instances of a resource to handle increased load (scale out)."], ["Scheduled Scaling", "Scaling resources up or down at predefined times based on known usage patterns."], ["Triggered Scaling — Trending", "Scaling based on a sustained trend in a metric over time (e.g., steadily rising CPU)."], ["Vertical Scaling", "Increasing the resources (CPU/RAM) of an existing instance (scale up)."], ["Manual Scaling", "An administrator explicitly changing resource capacity rather than relying on automation."], ["Triggered Scaling — Load", "Scaling based on a real-time load threshold being crossed (e.g., CPU > 80%)."]], "id": 27}, {"obj": "3.1", "type": "match", "title": "Match each term to its correct definition (3.1)", "pairs": [["Log Collection", "Gathering log data from applications, systems, and services into a central location."], ["Tracing", "Following a single request as it moves through multiple services in a distributed system."], ["Monitoring Metrics", "Numeric measurements of system behavior (CPU, memory, request rate) collected over time."], ["Log Retention", "Defining how long log data is kept before being archived or deleted."], ["Alert Response", "The defined actions taken once an alert is triaged and confirmed to need action."], ["Log Aggregation", "Combining logs from many sources into a unified, searchable view."]], "id": 28}, {"obj": "1.3", "type": "match", "title": "Match each term to its correct definition (1.3)", "pairs": [["Static Route", "A manually configured network route that does not change dynamically."], ["Dedicated Connection", "A private, direct physical link between an organization and the cloud provider (e.g., AWS Direct Connect, Azure ExpressRoute)."], ["Firewall", "A device or service that filters network traffic based on defined rules."], ["Application Load Balancer", "A load balancer that operates at Layer 7, making routing decisions based on application data (like URL path or headers)."], ["VPC", "Virtual Private Cloud — an isolated, logically defined network within a public cloud provider's infrastructure."], ["VLAN", "Virtual Local Area Network — logically segments a switch into multiple isolated broadcast domains."]], "id": 29}, {"obj": "1.4", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["API", "Application Programming Interface"], ["ISP", "Internet Service Provider"], ["VPN", "Virtual Private Network"], ["OAuth", "Open Authorization"], ["DDoS", "Distributed Denial of Service"]], "id": 30}, {"obj": "4.3", "type": "match", "title": "Match each term to its correct definition (4.3)", "pairs": [["Discretionary Access Control", "An access model where the resource owner decides who else can access it."], ["SDK", "Software Development Kit — a set of libraries/tools that let developers programmatically interact with a cloud platform."], ["CLI", "Common Language Infrastructure / Command Line Interface — a text-based tool for managing cloud resources."], ["Audit Trail", "A chronological record of who did what, and when, within a system."], ["API (IAM Context)", "Application Programming Interface — used here for programmatic management/access to cloud resources."], ["SSH", "Secure Shell — an encrypted protocol for remote command-line access to cloud resources."]], "id": 31}, {"obj": "1.9", "type": "match", "title": "Match each term to its correct definition (1.9)", "pairs": [["Self-Managed Database", "A database the customer installs, configures, patches, and maintains themselves on cloud infrastructure."], ["Relational Database", "A database that organizes data into structured tables with defined relationships (SQL)."], ["Non-Relational Database", "A database (NoSQL) that stores data in flexible formats like documents, key-value pairs, or graphs."], ["Provider-Managed Database", "A database service where the cloud provider handles patching, backups, and maintenance (e.g., DBaaS)."]], "id": 32}, {"obj": "4.5", "type": "match", "title": "Match each term to its correct definition (4.5)", "pairs": [["Endpoint Protection", "Security software (antivirus, EDR) installed directly on servers, VMs, or devices."], ["Network ACL", "Access Control List — a set of rules controlling traffic in and out of a subnet at the network level."], ["IPS/IDS", "Intrusion Prevention/Detection System — monitors (and optionally blocks) malicious network or host activity."], ["DLP", "Data Loss Prevention — controls that detect and block unauthorized transmission of sensitive data."], ["DDoS Protection", "Services or controls that mitigate distributed denial-of-service attacks by absorbing or filtering malicious traffic."], ["WAF", "Web Application Firewall — a firewall specifically designed to filter and monitor HTTP traffic to web applications."]], "id": 33}, {"obj": "1.2", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["RPO", "Recovery Point Objective"], ["GDPR", "General Data Protection Regulation"], ["CVSS", "Common Vulnerability Scoring System"], ["PCI", "Payment Card Industry"], ["RACI", "Responsible, Accountable, Consulted, Informed"]], "id": 34}, {"obj": "5.1", "type": "match", "title": "Match each term to its correct definition (5.1)", "pairs": [["Version Management", "Tracking and organizing different versions of code or configuration over time."], ["Pull Request", "A formal request to merge a proposed code change into a shared branch, typically triggering review."], ["Code Review", "Having other team members examine proposed code changes before they are merged."], ["Branch Management", "Organizing and maintaining separate lines of development (branches) within a repository."], ["Code Commit", "Saving a snapshot of changes to the local version control history."], ["Code Merge", "Combining changes from different branches into one."]], "id": 35}, {"obj": "2.5", "type": "match", "title": "Match each term to its correct definition (2.5)", "pairs": [["Compliance Requirements", "Legal or regulatory obligations a workload's data and processing must meet."], ["Compute Requirements", "The processing power (CPU, RAM) needed to run a workload effectively."], ["Network Requirements", "The bandwidth, latency, and connectivity needs of a workload."], ["Availability Requirements", "The uptime and resiliency expectations for a workload."], ["Storage Requirements", "The capacity, performance, and durability needs a workload has for its data."]], "id": 36}, {"obj": "1.1", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["IaaS", "Infrastructure as a Service"], ["RAM", "Random Access Memory"], ["SOC2", "System and Organization Controls 2"], ["CVE", "Common Vulnerabilities and Exposures"], ["AZ", "Availability Zone"]], "id": 37}, {"obj": "1.2", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["DR", "Disaster Recovery"], ["CWSS", "Common Weakness Scoring System"], ["SQL", "Structured Query Language"], ["CIS", "Center for Internet Security"], ["CI/CD", "Continuous Integration/Continuous Deployment"]], "id": 38}, {"obj": "3.2", "type": "order", "title": "Responding to a load-triggered autoscaling event", "steps": ["Monitoring detects a metric (like CPU) crossing the defined threshold", "The autoscaling policy is triggered", "New instances are automatically provisioned from a template/image", "New instances register with the load balancer", "Load balancer begins distributing traffic to the new instances", "Instances are automatically removed once demand subsides"], "id": 39}, {"obj": "2.1", "type": "match", "title": "Match each term to its correct definition (2.1)", "pairs": [["Hybrid Cloud", "A deployment model combining private/on-premises infrastructure with public cloud resources."], ["On Premises", "Infrastructure physically located and managed within the organization's own facilities."], ["Public Cloud", "Infrastructure owned by a third-party provider and shared across many customers (multi-tenant)."], ["Community Cloud", "Infrastructure shared by several organizations with common concerns such as compliance or security requirements."], ["Private Cloud", "Infrastructure dedicated to a single organization, hosted on- or off-premises."]], "id": 40}, {"obj": "1.10", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["IOPS", "Input/Output Operations Per Second"], ["SSO", "Single Sign-On"], ["ITIL", "Information Technology Infrastructure Library"], ["WAF", "Web Application Firewall"], ["VPC", "Virtual Private Cloud"]], "id": 41}, {"obj": "1.8", "type": "match", "title": "Match each term to its correct definition (1.8)", "pairs": [["Pay-As-You-Go", "A billing model charging only for actual resource consumption, with no upfront commitment."], ["Dedicated Host Billing", "A billing model where a customer pays for an entire physical host, regardless of utilization."], ["Tagging", "Attaching key-value metadata labels to cloud resources."], ["Reserved Resources", "Pre-purchasing capacity for a discounted rate in exchange for a committed term."], ["Spot Instance", "Spare cloud compute capacity offered at a steep discount, which can be reclaimed by the provider with little notice."], ["Rightsizing", "Adjusting the size/type of provisioned resources to match actual workload demand."]], "id": 42}, {"obj": "3.4", "type": "match", "title": "Match each term to its correct definition (3.4)", "pairs": [["Persistent Data", "Data that must be retained beyond the life of the process or instance that created it."], ["Decommissioning — End of Life", "Retiring a resource because it has reached the end of its useful life or support."], ["Patch", "A software update addressing a specific bug or vulnerability."], ["Major Update", "A significant version update that may include new features and breaking changes."], ["Minor Update", "A smaller update, typically with bug fixes and small improvements."], ["Lifecycle Testing", "Validating changes (patches, updates, configuration) before applying them broadly."]], "id": 43}, {"obj": "6.2", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["NTP", "Network Time Protocol"], ["iSCSI", "Internet Small Computer System Interface"], ["HTTP", "Hypertext Transfer Protocol"], ["CLI", "Common Language Infrastructure"], ["vNIC", "Virtual NIC"]], "id": 44}, {"obj": "4.2", "type": "match", "title": "Match each term to its correct definition (4.2)", "pairs": [["ISO 27001", "An international standard specifying requirements for an information security management system."], ["Regulatory Retention", "A data retention requirement mandated by law or industry regulation."], ["Data Classification", "Categorizing data based on sensitivity (e.g., public, internal, confidential, restricted)."], ["Data Ownership", "Defining who legally owns and controls a given set of data."], ["SOC2", "Systems and Organization Controls 2 — an audit framework evaluating a service provider's controls around security, availability, and confidentiality."], ["Data Sovereignty", "The principle that data is subject to the laws of the country in which it is physically located."]], "id": 45}, {"obj": "5.4", "type": "match", "title": "Match each term to its correct definition (5.4)", "pairs": [["Kubernetes", "An open-source platform for automating deployment, scaling, and management of containerized applications."], ["GitHub Actions", "A CI/CD automation feature built into GitHub for running workflows in response to repository events."], ["Git", "A distributed version control system used to track changes in source code."], ["Jenkins", "A widely used open-source automation server for building CI/CD pipelines."], ["Grafana", "An open-source tool for visualizing metrics and creating monitoring dashboards."], ["Terraform", "An open-source Infrastructure as Code tool for provisioning and managing cloud resources declaratively."]], "id": 46}, {"obj": "1.2", "type": "match", "title": "Match each term to its correct definition (1.2)", "pairs": [["Region", "A distinct geographic location where a cloud provider operates one or more datacenters."], ["Multicloud Tenancy", "Using services from more than one public cloud provider simultaneously."], ["RTO", "Recovery Time Objective — the maximum acceptable length of time a system can be down after a disruption."], ["RPO", "Recovery Point Objective — the maximum acceptable amount of data loss, measured in time."], ["Availability Monitoring", "Continuously checking that a resource or service is up and responding as expected."], ["Edge Computing", "Processing data physically close to where it is generated rather than in a centralized datacenter."]], "id": 47}, {"obj": "1.11", "type": "match", "title": "Match each term to its correct definition (1.11)", "pairs": [["Generative AI", "AI models that create new content (text, images, code) based on learned patterns."], ["IoT Communication", "The networking methods (Wi-Fi, cellular, Bluetooth, etc.) IoT devices use to transmit data."], ["Sentiment Analysis", "AI technology that determines the emotional tone (positive/negative/neutral) of text."], ["Text Recognition", "AI technology that extracts text from images or scanned documents (OCR)."], ["Visual Recognition", "AI technology that identifies objects, scenes, or features within images or video."], ["Machine Learning", "Algorithms that learn patterns from data to make predictions or decisions without being explicitly programmed for every case."]], "id": 48}, {"obj": "3.3", "type": "order", "title": "Restoring data after a loss event", "steps": ["Identify the most recent valid backup set containing the needed data", "Notify stakeholders of the planned restore and any downtime", "Restore the last full backup", "Apply the most recent differential or the incremental chain in order", "Validate the restored data for completeness and integrity", "Document the incident and the restore outcome"], "id": 49}, {"obj": "3.3", "type": "match", "title": "Match each term to its correct definition (3.3)", "pairs": [["In-Place Recovery", "Restoring data directly onto the original system/location."], ["Full Backup", "A complete copy of all selected data."], ["Bulk Recovery", "Restoring a large set of data all at once."], ["Backup Retention (Ops)", "How long backup copies are kept before being deleted or overwritten."], ["Differential Backup", "Backs up all data changed since the last full backup."], ["Parallel Recovery", "Restoring data to an alternate system running alongside the original."]], "id": 50}, {"obj": "1.6", "type": "match", "title": "Match each term to its correct definition (1.6)", "pairs": [["Port Mapping", "Binding a container's internal port to a port on the host or load balancer."], ["Workload Orchestration", "Automated management of container deployment, scaling, and healing (e.g., Kubernetes)."], ["Stand-Alone Container", "A single container running in isolation without orchestration."], ["Image Registry", "A repository for storing and distributing container images (e.g., Docker Hub, a private registry)."], ["Ephemeral Storage", "Temporary storage tied to a container's lifecycle that is lost when the container stops."], ["Persistent Volume", "Storage that survives beyond the lifecycle of an individual container."]], "id": 51}, {"obj": "5.3", "type": "match", "title": "Match each term to its correct definition (5.3)", "pairs": [["Event-Driven Architecture", "A design where components communicate by producing and reacting to events rather than direct calls."], ["SOAP", "Simple Object Access Protocol — an XML-based messaging protocol for web services."], ["GraphQL", "A query language for APIs that lets clients request exactly the data they need."], ["RPC", "Remote Procedure Call — lets a program execute a procedure on a remote system as if it were local."], ["Web Sockets", "A protocol providing full-duplex, persistent communication channels over a single TCP connection."], ["REST", "Representational State Transfer — an architectural style for web services using standard HTTP methods."]], "id": 52}, {"obj": "4.3", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["OIDC", "OpenID Connect Protocol"], ["SaaS", "Software as a Service"], ["IAM", "Identity and Access Management"], ["JSON", "JavaScript Object Notation"], ["AI", "Artificial Intelligence"]], "id": 53}, {"obj": "6.2", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["MTU", "Maximum Transmission Unit"], ["ELK", "Elasticsearch, Logstash, and Kibana"], ["RDP", "Remote Desktop Protocol"], ["NVME", "Non-Volatile Memory Express"], ["IPS", "Intrusion Prevention System"]], "id": 54}, {"obj": "2.4", "type": "match", "title": "Match each acronym to its correct expansion", "pairs": [["CaC", "Configuration as Code"], ["MFA", "Multifactor Authentication"], ["VLAN", "Virtual LAN"], ["FaaS", "Function as a Service"], ["BYOD", "Bring Your Own Device"]], "id": 55}, {"obj": "2.3", "type": "match", "title": "Match each term to its correct definition (2.3)", "pairs": [["Cloud-to-On-Premises Migration", "Moving workloads out of the cloud back to local infrastructure."], ["Retain", "A migration strategy that keeps a workload where it currently is, deferring migration."], ["Re-Architect", "A migration strategy that substantially redesigns an application to be cloud-native."], ["Replatform", "A migration strategy making some optimizations to leverage cloud capabilities without changing the core architecture."], ["On-Premises-to-Cloud Migration", "Moving workloads from local infrastructure into a cloud environment."], ["Retire", "A migration strategy that decommissions an application no longer needed."]], "id": 56}, {"obj": "2.3", "type": "order", "title": "Planning and executing a cloud migration", "steps": ["Assess current workloads and choose a migration strategy (rehost, replatform, re-architect, etc.)", "Provision target cloud resources and networking", "Migrate data and validate integrity", "Migrate the application/workload and test functionality", "Cut over production traffic to the new environment", "Decommission the old environment once stable"], "id": 57}, {"obj": "5.2", "type": "match", "title": "Match each term to its correct definition (5.2)", "pairs": [["Private Repository", "A code or artifact repository restricted to authorized users/systems."], ["Public Repository", "A code or artifact repository accessible to anyone."], ["CI/CD Testing", "Automatically running tests against code as part of the pipeline."], ["Container Image Artifact", "A packaged container image produced and stored as a build output."], ["CI/CD Security", "Incorporating security scanning and checks into the automated pipeline."], ["VM Image Artifact", "A packaged virtual machine image produced and stored as a build output."]], "id": 58}, {"obj": "1.5", "type": "match", "title": "Match each term to its correct definition (1.5)", "pairs": [["Fan-Out", "A messaging pattern where one event is distributed to multiple downstream consumers/services."], ["Service Discovery", "A mechanism that lets services dynamically find the network location of other services."], ["Loosely Coupled Architecture", "A design where components interact through well-defined interfaces with minimal direct dependencies."], ["Microservices", "An architecture where an application is broken into small, independently deployable services."], ["Cloud-Provided Managed Service", "A service the cloud provider fully operates (e.g., a managed database), removing the customer's operational burden."]], "id": 59}];
PBQ.forEach((p,i)=>{ p.id = i; });

/* ============ TROUBLESHOOTING METHODOLOGY (ordered reference + practice) ============ */
const TS_STEPS = [{"t": "Identify the problem", "d": "Gather details from users/monitoring, identify recent changes, review logs and documentation, and replicate the problem if possible. Back up data before making changes, and escalate if necessary."}, {"t": "Establish a theory of probable cause", "d": "Question the obvious first, and determine whether a common element or symptom links multiple problems together."}, {"t": "Test the theory to determine the cause", "d": "If confirmed, determine the next steps to resolve the problem. If not confirmed, establish a new theory or escalate."}, {"t": "Establish a plan of action", "d": "Plan the resolution steps, prepare a backout plan, and notify impacted users before making changes."}, {"t": "Implement the solution or escalate", "d": "Make one change at a time, testing and confirming after each. If unresolved, reverse the change if appropriate and try a new one."}, {"t": "Verify full system functionality", "d": "Confirm the system works end-to-end and implement preventive measures to stop recurrence."}, {"t": "Document findings, actions, and outcomes", "d": "Record what was found, what was done, and the result — and perform a root cause analysis throughout the process."}];

/* ============ STATE: progress & settings (localStorage) ============ */
const STORE_KEY = 'cloudplus_progress_v1';
const SETTINGS_KEY = 'cloudplus_settings_v1';
function loadProgress(){
  try{ const raw = localStorage.getItem(STORE_KEY); if(raw) return JSON.parse(raw); }catch(e){}
  return {seen:{}, correct:{}, flashSeen:{}, dailyLog:{}, tsPassed:0};
}
function saveProgress(p){ try{ localStorage.setItem(STORE_KEY, JSON.stringify(p)); }catch(e){} }
let progress = loadProgress();

