const THEME_GROUPS = {'Steel (default)': ['steel-light','steel-dark']};
THEME_DATA.forEach(t=>{
  if(!THEME_GROUPS[t.family]) THEME_GROUPS[t.family] = [];
  THEME_GROUPS[t.family].push(t.id);
});
const THEME_COLOR_MAP = {'steel-light':{bg:'#eef1f4',bgElev:'#ffffff',accent:'#215f8c'}, 'steel-dark':{bg:'#101418',bgElev:'#171d23',accent:'#5fa8dd'}};
THEME_DATA.forEach(t=>{ THEME_COLOR_MAP[t.id] = {bg:t.c.bg, bgElev:t.c.bgElev, accent:t.c.accent}; });
const THEME_LABELS = {'steel-light':'Steel Light','steel-dark':'Steel Dark'};
THEME_DATA.forEach(t=>{ THEME_LABELS[t.id] = t.label; });

const CUSTOM_COLOR_KEYS = [
 ['bg','Background','--bg'], ['bgElev','Surface / Card','--bg-elev'], ['bgSunken','Sunken Panel','--bg-sunken'],
 ['text','Text','--text'], ['textDim','Muted Text','--text-dim'], ['accent','Accent','--accent'],
 ['accentText','Accent Text','--accent-text'], ['border','Border','--border'],
 ['success','Success','--success'], ['danger','Danger','--danger'], ['warn','Warning','--warn'],
];

function loadSettings(){
  try{ const raw = localStorage.getItem(SETTINGS_KEY); if(raw) return JSON.parse(raw); }catch(e){}
  return {theme:'steel-light', layout:'default', density:'comfortable', radius:'theme', motion:'normal', quizDefaultSize:10, dailyGoal:20, fontSize:15, customColors:{}};
}
function saveSettings(s){ try{ localStorage.setItem(SETTINGS_KEY, JSON.stringify(s)); }catch(e){} }
let settings = loadSettings();
function applySettings(){
  document.documentElement.setAttribute('data-theme', settings.theme || 'steel-light');
  document.documentElement.setAttribute('data-layout', settings.layout || 'default');
  document.documentElement.setAttribute('data-density', settings.density || 'comfortable');
  document.documentElement.setAttribute('data-radius', settings.radius || 'theme');
  document.documentElement.setAttribute('data-motion', settings.motion || 'normal');
  document.documentElement.style.fontSize = (settings.fontSize || 15) + 'px';
  // Clear any previously-applied custom color overrides, then reapply current ones
  CUSTOM_COLOR_KEYS.forEach(([key,label,cssVar])=>{ document.documentElement.style.removeProperty(cssVar); });
  const cc = settings.customColors || {};
  CUSTOM_COLOR_KEYS.forEach(([key,label,cssVar])=>{
    if(cc[key]) document.documentElement.style.setProperty(cssVar, cc[key]);
  });
}
applySettings();

function todayKey(){ const d=new Date(); return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate(); }
function logAnswer(qid, isCorrect){
  progress.seen[qid] = true;
  if(isCorrect) progress.correct[qid] = true; else delete progress.correct[qid];
  const k = todayKey();
  progress.dailyLog[k] = (progress.dailyLog[k]||0) + 1;
  saveProgress(progress);
}
function overallStats(){
  const seenIds = Object.keys(progress.seen).filter(k=>progress.seen[k]);
  const correctIds = Object.keys(progress.correct).filter(k=>progress.correct[k]);
  return {total: QBANK.length, seen: seenIds.length, correct: correctIds.length};
}
function objStats(objId){
  const qs = QBANK.filter(q=>q.obj===objId);
  let seen=0, correct=0;
  qs.forEach(q=>{ if(progress.seen[q.id]) seen++; if(progress.correct[q.id]) correct++; });
  return {total: qs.length, seen, correct};
}
function domainStats(domId){
  const dom = DOMAINS.find(d=>d.id===domId);
  let total=0, seen=0, correct=0;
  dom.objectives.forEach(o=>{ const s=objStats(o.id); total+=s.total; seen+=s.seen; correct+=s.correct; });
  return {total, seen, correct};
}

/* ============ SIDEBAR: domain/objective tree ============ */
let openDomains = {'1.0':true};
function renderNavDomains(){
  const el = document.getElementById('navDomains');
  el.innerHTML = DOMAINS.map(d=>{
    const isOpen = !!openDomains[d.id];
    return '<div class="domain-block">'+
      '<div class="domain-header" data-domtoggle="'+d.id+'">'+
        '<span class="domain-header-label">'+icon(d.icon)+'<span>'+d.id+' '+d.title+'</span></span>'+
        '<span style="display:flex; align-items:center; gap:6px;"><span class="domain-weight">'+d.weight+'%</span>'+
        '<span class="domain-chevron'+(isOpen?' open':'')+'">▸</span></span>'+
      '</div>'+
      '<ul class="obj-list'+(isOpen?'':' collapsed')+'">'+
        d.objectives.map(o=>{
          const s = objStats(o.id);
          return '<li class="obj-item"><a href="#/objective/'+o.id+'" class="obj-link" data-objid="'+o.id+'">'+
            '<span>'+o.id+' '+o.title+'</span>'+
            '<span class="obj-badge">'+s.correct+'/'+s.total+'</span></a></li>';
        }).join('')+
      '</ul>'+
    '</div>';
  }).join('');
  el.querySelectorAll('[data-domtoggle]').forEach(h=>h.addEventListener('click', ()=>{
    const id = h.getAttribute('data-domtoggle');
    openDomains[id] = !openDomains[id];
    renderNavDomains();
    document.querySelectorAll('.obj-link').forEach(a=>{
      const parts = location.hash.replace('#/','').split('/');
      if(parts[0]==='objective' && a.getAttribute('data-objid')===parts[1]) a.classList.add('active');
    });
  }));
}

/* ============ DASHBOARD ============ */
function conicDonut(segments){
  // segments: [{pct, color}] summing to <=100
  let acc = 0;
  const stops = [];
  segments.forEach(s=>{
    const start = acc;
    const end = acc + s.pct;
    stops.push(s.color+' '+start+'% '+end+'%');
    acc = end;
  });
  if(acc < 100) stops.push('var(--bg-sunken) '+acc+'% 100%');
  return 'conic-gradient(' + stops.join(', ') + ')';
}
function last7DayKeys(){
  const out = [];
  for(let i=6;i>=0;i--){
    const d = new Date(); d.setDate(d.getDate()-i);
    out.push({key: d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate(), label: d.toLocaleDateString(undefined,{weekday:'short'})});
  }
  return out;
}
function computeStreak(){
  let streak = 0;
  for(let i=0;i<365;i++){
    const d = new Date(); d.setDate(d.getDate()-i);
    const key = d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate();
    if(progress.dailyLog[key] && progress.dailyLog[key]>0){ streak++; } else if(i===0){ continue; } else { break; }
  }
  return streak;
}

function renderDashboard(main){
  const st = overallStats();
  const acc = st.seen ? Math.round((st.correct/st.seen)*100) : 0;
  const todayCount = progress.dailyLog[todayKey()] || 0;
  const goal = settings.dailyGoal || 20;
  const goalPct = Math.min(100, Math.round((todayCount/goal)*100));
  const streak = computeStreak();
  const incorrectCount = st.seen - st.correct;
  const unseenCount = st.total - st.seen;
  const pctCorrect = st.total ? Math.round((st.correct/st.total)*100) : 0;
  const pctIncorrect = st.total ? Math.round((incorrectCount/st.total)*100) : 0;
  const pbqDone = progress.pbqPassed ? Object.keys(progress.pbqPassed).length : 0;
  const week = last7DayKeys();
  const weekMax = Math.max(1, ...week.map(w=>progress.dailyLog[w.key]||0));

  main.innerHTML =
    '<div class="eyebrow">Cloud+ CV0-004</div>'+
    '<h1>Welcome back</h1>'+
    '<p class="muted">Track your progress across all four exam domains, then jump into a quiz, flashcards, or the troubleshooting methodology drill.</p>'+

    '<div class="grid grid-4">'+
      '<div class="card"><div class="stat-icon">'+icon('quiz')+'</div><div class="stat-num">'+st.seen+'/'+st.total+'</div><div class="stat-label">Questions attempted</div></div>'+
      '<div class="card"><div class="stat-icon">'+icon('check')+'</div><div class="stat-num">'+acc+'%</div><div class="stat-label">Overall accuracy</div></div>'+
      '<div class="card"><div class="stat-icon">'+icon('pbq')+'</div><div class="stat-num">'+pbqDone+'/'+PBQ.length+'</div><div class="stat-label">PBQs mastered</div></div>'+
      '<div class="card"><div class="stat-icon">'+icon('tips')+'</div><div class="stat-num">'+streak+'</div><div class="stat-label">Day streak</div></div>'+
    '</div>'+

    '<h2>Question performance</h2>'+
    '<div class="card">'+
      '<div class="donut-wrap">'+
        '<div class="donut" style="background:'+conicDonut([{pct:pctCorrect, color:'var(--success)'},{pct:pctIncorrect, color:'var(--danger)'}])+';">'+
          '<div class="donut-center"><div class="dc-num">'+acc+'%</div><div class="dc-label">Accuracy</div></div>'+
        '</div>'+
        '<div class="legend-list">'+
          '<div class="legend-row"><span><span class="legend-dot" style="background:var(--success);"></span>Correct</span><strong>'+st.correct+'</strong></div>'+
          '<div class="legend-row"><span><span class="legend-dot" style="background:var(--danger);"></span>Incorrect</span><strong>'+incorrectCount+'</strong></div>'+
          '<div class="legend-row"><span><span class="legend-dot" style="background:var(--bg-sunken); border:1px solid var(--border);"></span>Not attempted</span><strong>'+unseenCount+'</strong></div>'+
          '<div class="legend-row" style="margin-top:6px; padding-top:6px; border-top:1px solid var(--border);"><span>Total question bank</span><strong>'+st.total+'</strong></div>'+
        '</div>'+
      '</div>'+
    '</div>'+

    '<h2>Accuracy by domain (vs. exam weight)</h2>'+
    '<div class="card">'+
      DOMAINS.map(d=>{
        const s = domainStats(d.id);
        const domAcc = s.seen ? Math.round((s.correct/s.seen)*100) : 0;
        return '<div class="bar-row"><span>'+d.id+' '+d.title+'</span>'+
          '<div class="bar-track"><div class="bar-fill weight" style="width:'+d.weight+'%;"></div><div class="bar-fill acc" style="width:'+domAcc+'%;"></div></div>'+
          '<span class="muted">'+domAcc+'%</span></div>';
      }).join('')+
      '<p class="muted" style="margin-top:8px; font-size:0.8rem;">Faint bar = that domain\'s share of the real exam (%). Solid bar = your accuracy so far.</p>'+
    '</div>'+

    '<h2>Progress by objective</h2>'+
    '<div class="card">'+
      DOMAINS.map(d=>{
        return '<div style="margin-bottom:14px;"><div class="card-icon-row">'+icon(d.icon)+'<strong>'+d.id+' '+d.title+'</strong></div>'+
          d.objectives.map(o=>{
            const s = objStats(o.id);
            const pct = s.total ? Math.round((s.correct/s.total)*100) : 0;
            return '<div class="obj-progress-row">'+
              '<a href="#/objective/'+o.id+'">'+o.id+' '+o.title+'</a>'+
              '<div class="hbar-track"><div class="hbar-fill" style="width:'+pct+'%;"></div></div>'+
              '<span class="muted" style="text-align:right;">'+s.correct+'/'+s.total+'</span>'+
            '</div>';
          }).join('')+
        '</div>';
      }).join('')+
    '</div>'+

    '<div class="grid grid-2">'+
      '<div class="card">'+
        '<h3 style="margin-top:0;">Last 7 days</h3>'+
        '<div class="weekbar-wrap">'+
          week.map(w=>{
            const c = progress.dailyLog[w.key]||0;
            const h = Math.round((c/weekMax)*100);
            return '<div class="weekbar-col"><div class="muted" style="font-size:0.68rem;">'+c+'</div><div class="weekbar-fill" style="height:'+h+'%;"></div><div class="weekbar-label">'+w.label+'</div></div>';
          }).join('')+
        '</div>'+
      '</div>'+
      '<div class="card">'+
        '<h3 style="margin-top:0;">Today\'s goal</h3>'+
        '<p class="muted" style="margin-bottom:10px;">'+todayCount+' of '+goal+' questions answered today</p>'+
        '<div class="progress-track"><div class="progress-fill" style="width:'+goalPct+'%;"></div></div>'+
      '</div>'+
    '</div>'+

    '<h2>Study material overview</h2>'+
    '<div class="card">'+
      '<div class="mini-stat-grid">'+
        '<div class="mini-stat"><div class="ms-num">'+QBANK.length+'</div><div class="ms-label">Total quiz questions</div></div>'+
        '<div class="mini-stat"><div class="ms-num">'+PBQ.length+'</div><div class="ms-label">Performance-based Qs</div></div>'+
        '<div class="mini-stat"><div class="ms-num">'+FLASHCARDS.length+'</div><div class="ms-label">Concept flashcards</div></div>'+
        '<div class="mini-stat"><div class="ms-num">'+ACRONYMS.length+'</div><div class="ms-label">Acronyms</div></div>'+
      '</div>'+
      '<h3>Questions per domain</h3>'+
      DOMAINS.map(d=>{
        const count = QBANK.filter(q=>OBJ_INDEX[q.obj] && OBJ_INDEX[q.obj].domain===d.id).length;
        const pct = Math.round((count/QBANK.length)*100);
        return '<div class="hbar-row"><span>'+d.id+' '+d.title+'</span><div class="hbar-track"><div class="hbar-fill" style="width:'+pct+'%;"></div></div><span class="muted">'+count+'</span></div>';
      }).join('')+
    '</div>'+

    '<div class="card">'+
      '<h3 style="margin-top:0;">Jump back in</h3>'+
      '<div class="btn-row">'+
        '<a class="btn" href="#/quiz">Start a quiz</a>'+
        '<a class="btn secondary" href="#/flashcards">Flashcards</a>'+
        '<a class="btn secondary" href="#/pbq">Performance-Based Qs</a>'+
        '<a class="btn secondary" href="#/troubleshooting">Methodology drill</a>'+
        '<a class="btn secondary" href="#/settings">Customize UI</a>'+
      '</div>'+
    '</div>';
}

/* ============ QUIZ ENGINE ============ */
function shuffle(arr){ const a=arr.slice(); for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; } return a; }

let quiz = null; // {queue, index, score, answered, selected, objFilter}

function renderQuizStart(main, objId){
  const obj = objId ? OBJ_INDEX[objId] : null;
  const pool = objId ? QBANK.filter(q=>q.obj===objId) : QBANK;
  const sizes = [5,10,25,50,100].filter(n=>n<=pool.length || n===5);
  main.innerHTML =
    '<div class="eyebrow">'+(obj?('Objective '+obj.id):'Practice Quiz')+'</div>'+
    '<h1>'+(obj? obj.title : 'Practice Quiz')+'</h1>'+
    '<p class="muted">'+(obj? 'Focused practice on this objective only ('+pool.length+' questions available).' : 'Multiple-choice practice pulled from the full '+QBANK.length+'-question bank. Pick a batch size and go.')+'</p>'+
    '<div class="card">'+
      '<h3 style="margin-top:0;">Batch size</h3>'+
      '<div class="btn-row" id="quizSizeRow">'+
        [5,10,25,50,100,200].filter(n=>n<=pool.length).map(n=>'<button class="btn secondary" data-size="'+n+'">'+n+' questions</button>').join('')+
        '<button class="btn secondary" data-size="all">All ('+pool.length+')</button>'+
      '</div>'+
    '</div>'+
    (obj ? '<a class="btn secondary" href="#/quiz">← Back to full question bank</a>' : '');
  main.querySelectorAll('[data-size]').forEach(b=>b.addEventListener('click', ()=>{
    const sizeAttr = b.getAttribute('data-size');
    const n = sizeAttr==='all' ? pool.length : parseInt(sizeAttr,10);
    startQuiz(pool, n);
  }));
}

function startQuiz(pool, n){
  const picked = shuffle(pool).slice(0, n);
  quiz = {queue: picked, index:0, score:0, answered:new Array(picked.length).fill(false), selected:new Array(picked.length).fill(null)};
  renderQuizQuestion();
}

function renderQuizQuestion(){
  const main = document.getElementById('main');
  if(!quiz || quiz.index >= quiz.queue.length){ renderQuizResults(main); return; }
  const q = quiz.queue[quiz.index];
  const answered = quiz.answered[quiz.index];
  const sel = quiz.selected[quiz.index];
  const letters = ['A','B','C','D','E','F'];
  main.innerHTML =
    '<div class="q-meta">Question '+(quiz.index+1)+' of '+quiz.queue.length+' · Objective '+q.obj+' — '+(OBJ_INDEX[q.obj]?OBJ_INDEX[q.obj].title:'')+'</div>'+
    '<div class="progress-track" style="margin-bottom:16px;"><div class="progress-fill" style="width:'+Math.round((quiz.index/quiz.queue.length)*100)+'%;"></div></div>'+
    '<div class="card">'+
      '<div class="q-text">'+q.q+'</div>'+
      '<div id="choicesWrap">'+
        q.c.map((choice,i)=>{
          let cls='choice';
          if(answered){
            if(i===q.a) cls+=' correct';
            else if(i===sel) cls+=' incorrect';
          } else if(i===sel) cls+=' selected';
          return '<div class="'+cls+'" data-idx="'+i+'"><span class="choice-letter">'+letters[i]+'</span><span>'+choice+'</span></div>';
        }).join('')+
      '</div>'+
      (answered ? '<div class="explain"><strong>'+(sel===q.a?'Correct. ':'Incorrect. ')+'</strong>'+q.e+'</div>' : '')+
    '</div>'+
    '<div class="quiz-nav">'+
      '<a class="btn secondary" href="#/quiz">Exit quiz</a>'+
      '<span>'+(answered ? '<button class="btn" id="nextBtn">'+(quiz.index+1<quiz.queue.length?'Next question':'See results')+'</button>' : '<span class="muted">Select an answer to continue</span>')+'</span>'+
    '</div>';

  if(!answered){
    main.querySelectorAll('#choicesWrap .choice').forEach(c=>c.addEventListener('click', ()=>{
      const idx = parseInt(c.getAttribute('data-idx'),10);
      quiz.selected[quiz.index] = idx;
      quiz.answered[quiz.index] = true;
      const isCorrect = idx===q.a;
      if(isCorrect) quiz.score++;
      logAnswer(q.id, isCorrect);
      renderQuizQuestion();
      renderNavDomains();
    }));
  } else {
    const nb = document.getElementById('nextBtn');
    if(nb) nb.addEventListener('click', ()=>{ quiz.index++; renderQuizQuestion(); });
  }
}

function renderQuizResults(main){
  const total = quiz.queue.length;
  const pct = total ? Math.round((quiz.score/total)*100) : 0;
  main.innerHTML =
    '<div class="eyebrow">Quiz complete</div>'+
    '<h1>You scored '+quiz.score+' / '+total+'</h1>'+
    '<div class="card">'+
      '<div class="stat-num">'+pct+'%</div><div class="stat-label muted">This batch — passing on the real exam requires roughly 83% (750/900 scaled).</div>'+
      '<div class="progress-track" style="margin:14px 0;"><div class="progress-fill" style="width:'+pct+'%;"></div></div>'+
      '<div class="btn-row">'+
        '<a class="btn" href="#/quiz">New quiz</a>'+
        '<a class="btn secondary" href="#/dashboard">Back to dashboard</a>'+
      '</div>'+
    '</div>'+
    '<h2>Review</h2>'+
    quiz.queue.map((q,i)=>{
      const sel = quiz.selected[i];
      const ok = sel===q.a;
      return '<div class="card">'+
        '<div class="q-meta">Objective '+q.obj+' <span class="pill '+(ok?'correct':'wrong')+'">'+(ok?'Correct':'Incorrect')+'</span></div>'+
        '<div style="font-weight:600; margin-bottom:6px;">'+q.q+'</div>'+
        '<div class="muted" style="font-size:0.86rem;">Your answer: '+q.c[sel]+(ok?'':' · Correct answer: '+q.c[q.a])+'</div>'+
        '<div class="explain" style="margin-top:8px;">'+q.e+'</div>'+
      '</div>';
    }).join('');
}

/* ============ FLASHCARDS ============ */
let fcDeck = 'concepts', fcOrder = [], fcIndex = 0, fcFlipped = false;
function fcBuildOrder(){
  const src = fcDeck==='acronyms' ? ACRONYMS.map((a,i)=>({t:a[0], sub:a[1], d:a[2], m:'', id:'a'+i})) :
              fcDeck==='all' ? FLASHCARDS.map((f,i)=>({t:f.t, sub:'Objective '+f.obj, d:f.d, m:f.m, id:'c'+i})).concat(ACRONYMS.map((a,i)=>({t:a[0], sub:a[1], d:a[2], m:'', id:'a'+i}))) :
              FLASHCARDS.map((f,i)=>({t:f.t, sub:'Objective '+f.obj, d:f.d, m:f.m, id:'c'+i}));
  fcOrder = shuffle(src);
  fcIndex = 0; fcFlipped = false;
}
function renderFlashcards(main){
  if(fcOrder.length===0) fcBuildOrder();
  const card = fcOrder[fcIndex];
  main.innerHTML =
    '<div class="eyebrow">Study Tools</div>'+
    '<h1>Flashcards</h1>'+
    '<div class="tab-row">'+
      ['concepts','acronyms','all'].map(k=>'<button class="tab-btn'+(fcDeck===k?' active':'')+'" data-deck="'+k+'">'+(k==='concepts'?'Concepts':k==='acronyms'?'Acronyms':'All')+'</button>').join('')+
    '</div>'+
    '<div class="q-meta">Card '+(fcIndex+1)+' of '+fcOrder.length+'</div>'+
    '<div class="card flashcard" id="fcCard">'+
      (fcFlipped ?
        ('<div><div>'+card.d+'</div>'+(card.m?'<span class="fc-explain">'+card.m+'</span>':'')+'<span class="fc-sub">'+card.t+'</span></div>') :
        ('<div><div>'+card.t+'</div>'+(card.sub?'<span class="fc-sub">'+card.sub+'</span>':'')+'<span class="fc-explain">Click to reveal definition &amp; why it matters</span></div>')
      )+
    '</div>'+
    '<div class="fc-controls">'+
      '<button class="btn secondary" id="fcPrev">◂ Prev</button>'+
      '<button class="btn secondary" id="fcShuffle">'+icon('refresh')+' Shuffle</button>'+
      '<button class="btn" id="fcNext">Next ▸</button>'+
    '</div>';
  document.getElementById('fcCard').addEventListener('click', ()=>{ fcFlipped=!fcFlipped; renderFlashcards(main); });
  document.getElementById('fcPrev').addEventListener('click', (e)=>{ e.stopPropagation(); fcIndex=(fcIndex-1+fcOrder.length)%fcOrder.length; fcFlipped=false; renderFlashcards(main); });
  document.getElementById('fcNext').addEventListener('click', (e)=>{ e.stopPropagation(); fcIndex=(fcIndex+1)%fcOrder.length; fcFlipped=false; renderFlashcards(main); });
  document.getElementById('fcShuffle').addEventListener('click', (e)=>{ e.stopPropagation(); fcBuildOrder(); renderFlashcards(main); });
  main.querySelectorAll('[data-deck]').forEach(b=>b.addEventListener('click', ()=>{ fcDeck=b.getAttribute('data-deck'); fcBuildOrder(); renderFlashcards(main); }));
}

/* ============ ACRONYMS ============ */
function renderAcronyms(main){
  main.innerHTML =
    '<div class="eyebrow">Reference</div>'+
    '<h1>Acronym Glossary</h1>'+
    '<p class="muted">'+ACRONYMS.length+' acronyms from the CompTIA Cloud+ (CV0-004) acronym list, each with a plain-language explanation.</p>'+
    '<div class="acr-toolbar"><input class="acr-search" id="acrSearch" placeholder="Search acronyms or terms…"></div>'+
    '<div class="card"><table class="acr-table" id="acrTable"><thead><tr><th>Acronym</th><th>Stands for</th><th>Explanation</th></tr></thead><tbody></tbody></table></div>';
  const tbody = main.querySelector('#acrTable tbody');
  function paint(filter){
    const f = (filter||'').toLowerCase();
    const rows = ACRONYMS.filter(a=> !f || a[0].toLowerCase().includes(f) || a[1].toLowerCase().includes(f) || a[2].toLowerCase().includes(f));
    tbody.innerHTML = rows.map(a=>'<tr><td>'+a[0]+'</td><td>'+a[1]+'</td><td>'+a[2]+'</td></tr>').join('') || '<tr><td colspan="3" class="muted">No matches.</td></tr>';
  }
  paint('');
  document.getElementById('acrSearch').addEventListener('input', e=>paint(e.target.value));
}

/* ============ PERFORMANCE-BASED QUESTIONS (PBQ) ============ */
function renderPBQList(main){
  main.innerHTML =
    '<div class="eyebrow">Practice</div>'+
    '<h1>Performance-Based Questions</h1>'+
    '<p class="muted">'+PBQ.length+' hands-on exercises: match terms/acronyms to their definitions, or put multi-step server procedures in the correct order — the same interaction styles used on the real exam\'s PBQs.</p>'+
    DOMAINS.map(d=>{
      const items = PBQ.filter(p=>OBJ_INDEX[p.obj] && OBJ_INDEX[p.obj].domain===d.id);
      if(items.length===0) return '';
      return '<h2>'+d.id+' '+d.title+'</h2>'+
        '<div class="card">'+
          items.map(p=>'<a class="pbq-card" href="#/pbqitem/'+p.id+'"><span>'+(icon(p.type==='order'?'wrench':'pbq'))+' <strong style="margin-left:8px;">'+p.title+'</strong> <span class="muted" style="font-size:0.8rem;">— Objective '+p.obj+'</span></span><span class="pbq-type-badge">'+(p.type==='order'?'Sequence':'Match')+'</span></a>').join('')+
        '</div>';
    }).join('');
}

let pbqRuntimeOrder = {}; // per-pbq shuffled order cache: id -> array of indices
let pbqRuntimeMatch = {}; // per-pbq shuffled right-column options: id -> array

function renderPBQItem(main, id){
  const p = PBQ[id];
  if(!p){ renderPBQList(main); return; }
  main.innerHTML =
    '<div class="eyebrow">Objective '+p.obj+' · '+(p.type==='order'?'Sequence exercise':'Matching exercise')+'</div>'+
    '<h1>'+p.title+'</h1>'+
    (p.type==='order' ?
      '<p class="muted">Use the dropdowns to place these steps in the correct order, then check your work.</p>'
      : '<p class="muted">Use the dropdowns to match each item on the left to its correct answer on the right, then check your work.</p>'
    )+
    '<div class="card"><div id="pbqBody"></div>'+
      '<div class="btn-row" style="margin-top:12px;">'+
        '<button class="btn" id="pbqCheck">Check answers</button>'+
        '<button class="btn secondary" id="pbqShuffle">Shuffle again</button>'+
        '<a class="btn secondary" href="#/pbq">Back to list</a>'+
      '</div>'+
      '<div id="pbqResult" style="margin-top:12px;"></div>'+
    '</div>';

  function paintOrder(){
    if(!pbqRuntimeOrder[id]) pbqRuntimeOrder[id] = shuffle(p.steps.map((s,i)=>i));
    const ord = pbqRuntimeOrder[id];
    document.getElementById('pbqBody').innerHTML = ord.map((stepIdx,pos)=>
      '<div class="order-row" data-pos="'+pos+'"><div class="order-num">'+(pos+1)+'</div>'+
      '<select class="order-select" data-pos="'+pos+'">'+
        p.steps.map((s,i)=>'<option value="'+i+'" '+(i===stepIdx?'selected':'')+'>'+s+'</option>').join('')+
      '</select></div>'
    ).join('');
  }
  function paintMatch(){
    if(!pbqRuntimeMatch[id]) pbqRuntimeMatch[id] = shuffle(p.pairs.map((pr,i)=>i));
    const rightOrder = pbqRuntimeMatch[id];
    document.getElementById('pbqBody').innerHTML = p.pairs.map((pr,leftIdx)=>
      '<div class="match-row" data-left="'+leftIdx+'"><div><strong>'+pr[0]+'</strong></div>'+
      '<select class="match-select" data-left="'+leftIdx+'">'+
        '<option value="">— select a match —</option>'+
        rightOrder.map(ri=>'<option value="'+ri+'">'+p.pairs[ri][1]+'</option>').join('')+
      '</select></div>'
    ).join('');
  }
  function paint(){ p.type==='order' ? paintOrder() : paintMatch(); document.getElementById('pbqResult').innerHTML=''; }
  paint();

  document.getElementById('pbqShuffle').addEventListener('click', ()=>{ delete pbqRuntimeOrder[id]; delete pbqRuntimeMatch[id]; paint(); });
  document.getElementById('pbqCheck').addEventListener('click', ()=>{
    let correctCount = 0, totalCount = 0;
    if(p.type==='order'){
      const selects = Array.from(main.querySelectorAll('.order-select'));
      totalCount = selects.length;
      selects.forEach((sel,pos)=>{
        const val = parseInt(sel.value,10);
        const row = sel.closest('.order-row');
        row.classList.remove('ok','bad');
        if(val===pos){ row.classList.add('ok'); correctCount++; } else { row.classList.add('bad'); }
      });
    } else {
      const selects = Array.from(main.querySelectorAll('.match-select'));
      totalCount = selects.length;
      selects.forEach(sel=>{
        const leftIdx = parseInt(sel.getAttribute('data-left'),10);
        const val = sel.value;
        const row = sel.closest('.match-row');
        row.classList.remove('ok','bad');
        if(val !== '' && parseInt(val,10)===leftIdx){ row.classList.add('ok'); correctCount++; } else { row.classList.add('bad'); }
      });
    }
    const resultEl = document.getElementById('pbqResult');
    resultEl.innerHTML = '<div class="explain">'+correctCount+' of '+totalCount+' correct. '+(correctCount===totalCount ? 'Perfect score on this PBQ.' : 'Green rows are correct — adjust the red rows and check again.')+'</div>';
    if(correctCount===totalCount){ progress.pbqPassed = progress.pbqPassed || {}; progress.pbqPassed[id]=true; saveProgress(progress); }
  });
}


let tsOrder = []; // current shuffled indices for the drill, and user-picked order
function tsResetDrill(){ tsOrder = shuffle(TS_STEPS.map((s,i)=>i)); }
function renderTroubleshooting(main){
  if(tsOrder.length===0) tsResetDrill();
  main.innerHTML =
    '<div class="eyebrow">Domain 6.0 Reference</div>'+
    '<h1>Troubleshooting Theory &amp; Methodology</h1>'+
    '<p class="muted">The general IT troubleshooting methodology that underlies deployment, network, and security troubleshooting in Domain 6.0. Learn it as a reference, then drill the order below.</p>'+
    '<div class="card">'+
      '<h3 style="margin-top:0;">Reference order</h3>'+
      TS_STEPS.map((s,i)=>'<div style="display:flex; gap:12px; margin-bottom:12px;"><div class="order-num" style="flex-shrink:0;">'+(i+1)+'</div><div><strong>'+s.t+'</strong><div class="muted" style="font-size:0.86rem;">'+s.d+'</div></div></div>').join('')+
    '</div>'+
    '<h2>Practice: put the steps in order</h2>'+
    '<div class="card">'+
      '<div id="tsRows">'+
        tsOrder.map((stepIdx,pos)=>{
          return '<div class="order-row" data-pos="'+pos+'"><div class="order-num">'+(pos+1)+'</div>'+
            '<select class="order-select" data-pos="'+pos+'">'+
              TS_STEPS.map((s,i)=>'<option value="'+i+'" '+(i===stepIdx?'selected':'')+'>'+s.t+'</option>').join('')+
            '</select></div>';
        }).join('')+
      '</div>'+
      '<div class="btn-row" style="margin-top:12px;">'+
        '<button class="btn" id="tsCheck">Check order</button>'+
        '<button class="btn secondary" id="tsShuffle">Shuffle again</button>'+
      '</div>'+
      '<div id="tsResult" style="margin-top:12px;"></div>'+
    '</div>';

  document.getElementById('tsShuffle').addEventListener('click', ()=>{ tsResetDrill(); renderTroubleshooting(main); });
  document.getElementById('tsCheck').addEventListener('click', ()=>{
    const selects = Array.from(main.querySelectorAll('.order-select'));
    let correctCount = 0;
    selects.forEach((sel,pos)=>{
      const val = parseInt(sel.value,10);
      const row = sel.closest('.order-row');
      row.classList.remove('ok','bad');
      if(val===pos){ row.classList.add('ok'); correctCount++; } else { row.classList.add('bad'); }
    });
    const resultEl = document.getElementById('tsResult');
    resultEl.innerHTML = '<div class="explain">'+correctCount+' of '+TS_STEPS.length+' steps in the correct position. '+(correctCount===TS_STEPS.length ? 'Perfect — that\'s the full methodology in order.' : 'Green rows are correctly placed; adjust the rest and check again.')+'</div>';
    if(correctCount===TS_STEPS.length){ progress.tsPassed = (progress.tsPassed||0)+1; saveProgress(progress); }
  });
}

/* ============ STUDY TIPS ============ */
const STUDY_TIPS = [
  {icon:'server', title:'Think in scenarios, not trivia', body:'Most exam objectives begin with "Given a scenario…" Practice reasoning through symptoms and causes (especially in Domains 3.0 and 6.0) rather than memorizing isolated facts.', list:['Read the full scenario before looking at answer choices','Eliminate answers that solve a different problem than the one described','Watch for the most likely cause, not just a possible one']},
  {icon:'wrench', title:'Know the general troubleshooting methodology cold', body:'Domain 6.0 (Troubleshooting) expects you to reason through problems systematically, even though it is not spelled out as its own objective the way it is on other CompTIA exams.', list:['Identify → Theorize → Test → Plan → Implement → Verify → Document','Always change one variable at a time','Documentation and root cause analysis happen throughout, not just at the end']},
  {icon:'disk', title:'Separate cloud service and deployment models clearly', body:'IaaS/PaaS/SaaS/FaaS and public/private/hybrid/community models show up constantly and are easy to mix up — anchor each one to a concrete example.', list:['IaaS = you manage OS and up; PaaS = you manage app/data only; SaaS = fully managed','Public = shared multi-tenant; Private = dedicated; Hybrid = both; Community = shared compliance needs','Shared responsibility shifts more toward the provider as you move IaaS → PaaS → SaaS']},
  {icon:'lock', title:'Separate the security domains clearly', body:'Domain 4.0 blends vulnerability management, compliance, IAM, hardening, and controls — keep each bucket distinct in your head.', list:['IAM = RBAC, MFA, SSO, federation, OAuth/SAML/OIDC','Compliance = data sovereignty/locality, retention, SOC 2, PCI DSS, ISO 27001','Hardening = least privilege, disabling unused services, patching, secrets management','Controls = WAF, IDS/IPS, DLP, network security groups, DDoS protection']},
  {icon:'admin', title:'Know your deployment and migration strategies', body:'Blue-green, canary, rolling, and in-place deployments — plus rehost, replatform, re-architect, retain, retire, and refactor migration strategies — are frequently tested by scenario.', list:['Blue-green = instant rollback via traffic switch; Canary = small subset first; Rolling = incremental','Rehost = lift-and-shift (fastest, least optimized); Re-architect = full redesign (most effort, most benefit)','Match the strategy to the scenario\'s stated risk tolerance and timeline']},
  {icon:'acronym', title:'Drill acronyms daily in short bursts', body:'The exam leans heavily on acronyms across every domain. Five minutes a day with the flashcard deck compounds fast.', list:['Focus first on networking (VPC, SDN, BGP, CDN) and security (IAM, MFA, WAF, DLP) acronyms','Say the full expansion out loud, not just recognize the letters','Retest acronyms you got wrong the same day']},
];
function renderStudyTips(main){
  main.innerHTML =
    '<div class="eyebrow">Exam Strategy</div>'+
    '<h1>Study Tips</h1>'+
    '<p class="muted">Focused strategies for the CV0-004 exam, organized around how the objectives are actually tested.</p>'+
    STUDY_TIPS.map(t=>
      '<div class="card tip-card">'+
        '<div class="tip-head"><div class="tip-icon">'+icon(t.icon)+'</div><div><h3 style="margin:0 0 4px;">'+t.title+'</h3><p class="muted" style="margin:0;">'+t.body+'</p></div></div>'+
        '<ul class="tip-list">'+t.list.map(li=>'<li>'+li+'</li>').join('')+'</ul>'+
      '</div>'
    ).join('');
}

/* ============ SETTINGS ============ */
function themeSwatchHTML(id, isActive){
  const c = THEME_COLOR_MAP[id] || {bg:'#ccc',bgElev:'#eee',accent:'#888'};
  const label = THEME_LABELS[id] || id;
  return '<button class="theme-swatch2'+(isActive?' active':'')+'" data-theme-pick="'+id+'" title="'+label+'">'+
    '<span class="swatch-preview">'+
      '<i style="background:'+c.bg+'"></i>'+
      '<i style="background:'+c.bgElev+'"></i>'+
      '<i style="background:'+c.accent+'"></i>'+
    '</span>'+
    '<span class="swatch-label-row" style="background:'+c.bgElev+'; color:'+(c.bg==='#101418'||c.bg==='#171d23'?'#eee':'#222')+';">'+
      '<span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">'+label.replace(' Light','').replace(' Dark','')+'</span>'+
      (isActive ? '<span class="swatch-check" style="background:'+c.accent+';">'+icon('check')+'</span>' : '')+
    '</span>'+
  '</button>';
}
function layoutCardHTML(l, isActive){
  return '<div class="layout-card'+(isActive?' active':'')+'" data-layout-pick="'+l.id+'">'+
    '<div class="layout-preview '+l.cls+'">'+
      '<div class="lp-side">'+(l.id==='top-tabs'?'<i></i><i></i><i></i>':'')+'</div>'+
      '<div class="lp-main"><i></i><i></i><i></i></div>'+
    '</div>'+
    '<div class="layout-card-label">'+l.label+'</div>'+
  '</div>';
}
function renderSettings(main){
  const fs = settings.fontSize || 15;
  const cc = settings.customColors || {};
  main.innerHTML =
    '<div class="eyebrow">Preferences</div>'+
    '<h1>Settings</h1>'+
    '<p class="muted">Every visual aspect of the study desk can be customized: 42 built-in themes, 10 layout models, full per-color overrides, density, corners, motion, and text size.</p>'+

    '<h2>Theme</h2>'+
    '<div class="card">'+
      Object.entries(THEME_GROUPS).map(([group,ids])=>
        '<div class="theme-group"><div class="theme-group-title">'+group+'</div><div class="theme-row">'+
          ids.map(id=>themeSwatchHTML(id, (settings.theme||'steel-light')===id)).join('')+
        '</div></div>'
      ).join('')+
    '</div>'+

    '<h2>Layout</h2>'+
    '<div class="card">'+
      '<p class="muted" style="margin-top:0; font-size:0.84rem;">Restructures the navigation and content areas. All 10 use the same features, just arranged differently.</p>'+
      '<div class="theme-row" style="grid-template-columns:repeat(auto-fill,minmax(130px,1fr));">'+
        LAYOUTS.map(l=>layoutCardHTML(l, (settings.layout||'default')===l.id)).join('')+
      '</div>'+
    '</div>'+

    '<h2>Custom Colors</h2>'+
    '<div class="card">'+
      '<p class="muted" style="margin-top:0; font-size:0.84rem;">Override any individual color used across the entire UI. Overrides apply on top of whichever theme is selected above, and persist until reset.</p>'+
      CUSTOM_COLOR_KEYS.map(([key,label,cssVar])=>{
        const current = cc[key] || getComputedStyle(document.documentElement).getPropertyValue(cssVar).trim() || '#888888';
        const hex = current.startsWith('#') ? current : '#888888';
        return '<div class="color-row">'+
          '<label>'+label+'</label>'+
          '<span class="cr-value">'+(cc[key]?hex:'theme default')+'</span>'+
          '<input type="color" data-color-key="'+key+'" data-css-var="'+cssVar+'" value="'+hex+'">'+
          (cc[key] ? '<button class="cr-reset" data-color-reset="'+key+'">Reset</button>' : '<span style="width:44px;"></span>')+
        '</div>';
      }).join('')+
      '<div class="btn-row" style="margin-top:12px;"><button class="btn secondary" id="resetAllColors">Reset all custom colors</button></div>'+
    '</div>'+

    '<h2>Layout Density &amp; Shape</h2>'+
    '<div class="grid grid-2">'+
      '<div class="card"><strong style="display:block; margin-bottom:10px;">Density</strong>'+
        '<div class="btn-row">'+
          [['comfortable','Comfortable'],['compact','Compact'],['spacious','Spacious']].map(([k,l])=>'<button class="btn '+((settings.density||'comfortable')===k?'':'secondary')+'" data-density="'+k+'">'+l+'</button>').join('')+
        '</div>'+
      '</div>'+
      '<div class="card"><strong style="display:block; margin-bottom:10px;">Corner style</strong>'+
        '<div class="btn-row">'+
          [['theme','Theme default'],['sharp','Sharp'],['soft','Soft'],['rounded','Rounded'],['pill','Extra round']].map(([k,l])=>'<button class="btn '+((settings.radius||'theme')===k?'':'secondary')+'" data-radius="'+k+'" style="border-radius:'+({sharp:'2px',soft:'6px',rounded:'16px',pill:'28px',theme:'10px'}[k])+';">'+l+'</button>').join('')+
        '</div>'+
      '</div>'+
    '</div>'+

    '<div class="card"><strong style="display:block; margin-bottom:10px;">Motion</strong>'+
      '<div class="btn-row">'+
        [['normal','Normal'],['reduced','Reduced motion']].map(([k,l])=>'<button class="btn '+((settings.motion||'normal')===k?'':'secondary')+'" data-motion="'+k+'">'+l+'</button>').join('')+
      '</div>'+
      '<p class="muted" style="margin:8px 0 0; font-size:0.8rem;">Reduced motion turns off transitions/animations across the site.</p>'+
    '</div>'+

    '<h2>Text Size</h2>'+
    '<div class="card">'+
      '<strong style="display:block; margin-bottom:10px;">Font size <span class="muted" style="font-weight:400; font-size:0.8rem;">— rescales all text on the site, 8–28px</span></strong>'+
      '<div style="display:flex; align-items:center; gap:10px;"><span class="muted">8</span><input type="range" id="fsRange" min="8" max="28" step="1" value="'+fs+'" style="flex:1;"><span class="muted">28</span><span id="fsVal" style="width:44px; text-align:right; font-weight:600;">'+fs+'px</span></div>'+
      '<div style="margin-top:14px; padding:14px; background:var(--bg-sunken); border-radius:var(--radius-sm); font-size:'+fs+'px;" id="fsPreview">The quick brown fox jumps over the lazy dog. AAA, RAID, PDU, IOPS.</div>'+
    '</div>'+

    '<h2>Study Tools</h2>'+
    '<div class="card">'+
      '<div class="setting-row"><span>Default quiz length</span>'+
        '<select id="quizDefaultSize" style="padding:7px 10px; border-radius:var(--radius-sm); border:1px solid var(--border); background:var(--bg-elev); color:var(--text);">'+
          [5,10,25,50,100].map(n=>'<option value="'+n+'" '+((settings.quizDefaultSize||10)===n?'selected':'')+'>'+n+' questions</option>').join('')+
        '</select>'+
      '</div>'+
      '<div class="setting-row" style="border-bottom:none;"><span>Daily question goal</span><input type="number" id="dailyGoalInput" min="5" max="500" step="5" value="'+(settings.dailyGoal||20)+'" style="width:90px; padding:7px 10px; border-radius:var(--radius-sm); border:1px solid var(--border); background:var(--bg-elev); color:var(--text);"></div>'+
    '</div>'+

    '<h2>Documentation</h2>'+
    '<div class="card">'+
      '<p class="muted" style="margin-top:0; font-size:0.84rem;">Download a copy of the user manual to read offline or print.</p>'+
      '<a class="download-btn" href="manual.pdf" download="Server-Plus-Study-Desk-Manual.pdf">'+
        '<span class="download-icon">'+icon('book')+'</span>'+
        '<span>'+
          '<span class="download-title">User Manual (PDF)</span>'+
          '<span class="download-sub">How to use every feature, plus FAQ</span>'+
        '</span>'+
      '</a>'+
    '</div>'+

    '<div class="card"><div class="setting-row" style="border-bottom:none;"><span>Reset all progress</span><button class="btn secondary" id="resetProgress">Reset</button></div></div>';

  main.querySelectorAll('[data-theme-pick]').forEach(b=>b.addEventListener('click', ()=>{ settings.theme=b.getAttribute('data-theme-pick'); saveSettings(settings); applySettings(); renderSettings(main); }));
  main.querySelectorAll('[data-layout-pick]').forEach(b=>b.addEventListener('click', ()=>{ settings.layout=b.getAttribute('data-layout-pick'); saveSettings(settings); applySettings(); renderNavDomains(); renderSettings(main); }));
  main.querySelectorAll('[data-density]').forEach(b=>b.addEventListener('click', ()=>{ settings.density=b.getAttribute('data-density'); saveSettings(settings); applySettings(); renderSettings(main); }));
  main.querySelectorAll('[data-radius]').forEach(b=>b.addEventListener('click', ()=>{ settings.radius=b.getAttribute('data-radius'); saveSettings(settings); applySettings(); renderSettings(main); }));
  main.querySelectorAll('[data-motion]').forEach(b=>b.addEventListener('click', ()=>{ settings.motion=b.getAttribute('data-motion'); saveSettings(settings); applySettings(); renderSettings(main); }));

  main.querySelectorAll('[data-color-key]').forEach(inp=>{
    inp.addEventListener('input', e=>{
      const key = inp.getAttribute('data-color-key');
      settings.customColors = settings.customColors || {};
      settings.customColors[key] = e.target.value;
      saveSettings(settings); applySettings();
    });
    inp.addEventListener('change', ()=>{ renderSettings(main); });
  });
  main.querySelectorAll('[data-color-reset]').forEach(b=>b.addEventListener('click', ()=>{
    const key = b.getAttribute('data-color-reset');
    if(settings.customColors) delete settings.customColors[key];
    saveSettings(settings); applySettings(); renderSettings(main);
  }));
  const resetAllBtn = document.getElementById('resetAllColors');
  if(resetAllBtn) resetAllBtn.addEventListener('click', ()=>{ settings.customColors = {}; saveSettings(settings); applySettings(); renderSettings(main); });

  document.getElementById('fsRange').addEventListener('input', e=>{
    settings.fontSize=parseInt(e.target.value,10); saveSettings(settings); applySettings();
    document.getElementById('fsVal').textContent=settings.fontSize+'px';
    const prev = document.getElementById('fsPreview'); if(prev) prev.style.fontSize = settings.fontSize+'px';
  });
  document.getElementById('quizDefaultSize').addEventListener('change', e=>{ settings.quizDefaultSize=parseInt(e.target.value,10); saveSettings(settings); });
  document.getElementById('dailyGoalInput').addEventListener('change', e=>{ settings.dailyGoal = Math.max(1, parseInt(e.target.value,10)||20); saveSettings(settings); });
  document.getElementById('resetProgress').addEventListener('click', ()=>{
    if(confirm('This will erase all quiz progress and stats on this device. Continue?')){
      progress = {seen:{}, correct:{}, flashSeen:{}, dailyLog:{}, tsPassed:0};
      saveProgress(progress);
      alert('Progress reset.');
      route();
    }
  });
}

/* ============ ROUTER ============ */
function route(){
  const hash = location.hash.replace('#/','') || 'dashboard';
  const parts = hash.split('/');
  const navActive = parts[0]==='objective' ? 'quiz' : (parts[0]==='pbqitem' ? 'pbq' : parts[0]);
  document.querySelectorAll('.nav-link[data-route]').forEach(a=>a.classList.toggle('active', a.getAttribute('data-route')===navActive));
  renderNavDomains();
  document.querySelectorAll('.obj-link').forEach(a=>{ if(parts[0]==='objective' && a.getAttribute('data-objid')===parts[1]) a.classList.add('active'); });
  const main = document.getElementById('main');
  if(parts[0]==='dashboard') renderDashboard(main);
  else if(parts[0]==='quiz') renderQuizStart(main);
  else if(parts[0]==='objective') renderQuizStart(main, parts[1]);
  else if(parts[0]==='flashcards') renderFlashcards(main);
  else if(parts[0]==='pbq') renderPBQList(main);
  else if(parts[0]==='pbqitem') renderPBQItem(main, parseInt(parts[1],10));
  else if(parts[0]==='troubleshooting') renderTroubleshooting(main);
  else if(parts[0]==='acronyms') renderAcronyms(main);
  else if(parts[0]==='studytips') renderStudyTips(main);
  else if(parts[0]==='settings') renderSettings(main);
  else renderDashboard(main);
  document.getElementById('sidebar').classList.remove('open');
  window.scrollTo(0,0);
}
window.addEventListener('hashchange', route);
document.getElementById('menuToggle').addEventListener('click', ()=>document.getElementById('sidebar').classList.toggle('open'));

/* ============ DOWNLOADABLE FILES (generated client-side, no server) ============ */
function downloadTextFile(filename, content){
  const blob = new Blob([content], {type:'text/plain;charset=utf-8'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(()=>URL.revokeObjectURL(url), 1000);
}
function buildExamObjectivesText(){
  const lines = [];
  lines.push('COMPTIA CLOUD+ (CV0-004) — EXAM OBJECTIVES');
  lines.push('Compiled reference, generated from Cloud+ Study Desk');
  lines.push('='.repeat(60));
  lines.push('');
  lines.push('Required exam: CV0-004   Max questions: 90   Length: 90 minutes');
  lines.push('Question types: Multiple-choice and performance-based   Passing score: 750');
  lines.push('');
  DOMAINS.forEach(d=>{
    lines.push('-'.repeat(60));
    lines.push(d.id+'  '+d.title.toUpperCase()+'   ('+d.weight+'% of exam)');
    lines.push('-'.repeat(60));
    d.objectives.forEach(o=>{
      lines.push('');
      lines.push('  '+o.id+'  '+o.title);
    });
    lines.push('');
  });
  lines.push('='.repeat(60));
  lines.push('Generated by Cloud+ Study Desk. For the official, authoritative');
  lines.push('exam objectives document, see comptia.org/certifications/cloud.');
  return lines.join('\n');
}
